-- Testes de segurança (RLS e funções SECURITY DEFINER) sobre o banco com todas as migrations.
-- Cada verificação lança exceção se o comportamento esperado não ocorrer.
\set ON_ERROR_STOP on
-- O sistema conta "hoje" no fuso de Brasília (America/Sao_Paulo). Sem isto, entre 21h e 24h de Brasília o CI (em UTC) já está no dia seguinte e as datas dos testes não batem.
SET timezone TO 'America/Sao_Paulo';

CREATE SCHEMA ci;
GRANT USAGE ON SCHEMA ci TO PUBLIC;

CREATE FUNCTION ci.entrar(uid uuid) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claim.sub', coalesce(uid::text, ''), false);
  EXECUTE CASE WHEN uid IS NULL THEN 'SET ROLE anon' ELSE 'SET ROLE authenticated' END;
END $$;

CREATE FUNCTION ci.sair() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claim.sub', '', false);
  EXECUTE 'RESET ROLE';
END $$;

-- executa o comando como o usuário e exige que ele FALHE
CREATE FUNCTION ci.deve_falhar(uid uuid, cmd text, descricao text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE falhou boolean := false;
BEGIN
  PERFORM ci.entrar(uid);
  BEGIN
    EXECUTE cmd;
  EXCEPTION WHEN OTHERS THEN
    falhou := true;
  END;
  PERFORM ci.sair();
  IF NOT falhou THEN RAISE EXCEPTION 'FALHA: esperava erro em "%"', descricao; END IF;
END $$;

-- executa o comando como o usuário e devolve o número inteiro retornado
-- executa o comando como o dono do banco (sem RLS) e exige que FALHE: testa chaves e restrições
CREATE FUNCTION ci.deve_falhar_dono(cmd text, descricao text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE falhou boolean := false;
BEGIN
  BEGIN
    EXECUTE cmd;
  EXCEPTION WHEN OTHERS THEN
    falhou := true;
  END;
  IF NOT falhou THEN RAISE EXCEPTION 'FALHA: esperava erro em "%"', descricao; END IF;
END $$;

CREATE FUNCTION ci.contar(uid uuid, cmd text) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE n bigint;
BEGIN
  PERFORM ci.entrar(uid);
  EXECUTE cmd INTO n;
  PERFORM ci.sair();
  RETURN n;
END $$;

CREATE FUNCTION ci.exige(condicao boolean, descricao text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF condicao IS NOT TRUE THEN RAISE EXCEPTION 'FALHA: %', descricao; END IF;
  RAISE NOTICE 'ok: %', descricao;
END $$;

DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  filial constant uuid := '33333333-3333-3333-3333-333333333333';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  moto   constant uuid := 'a0000000-0000-0000-0000-000000000003';
  novo   constant uuid := 'a0000000-0000-0000-0000-000000000004';
  gest   constant uuid := 'a0000000-0000-0000-0000-000000000005';
  tenant_b uuid;
  cli_b uuid; dep_b uuid; ped_b uuid; t uuid;
  gar constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz constant uuid := 'a0000000-0000-0000-0000-000000000007';
  cxa constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  mesa1 uuid; mesa2 uuid; cat_r uuid; it_prato uuid; it_lata uuid; gr_ponto uuid; gr_add uuid;
  o_mal uuid; o_ponto uuid; o_bacon uuid; o_ovo uuid; o_queijo uuid;
  ped_t uuid; ped_t2 uuid; aut_t uuid; est_antes numeric; est_depois numeric; tef_cfg uuid; caixa_t uuid;
  mesa3 uuid; c6 uuid; i5 uuid; i6 uuid; filial2 uuid; caixa2 uuid;
  c1 uuid; c2 uuid; c3 uuid; c4 uuid; c5 uuid; i1 uuid; i2 uuid; i3 uuid; i4 uuid; caixa_r uuid; n_r bigint;
  v_json jsonb; prod uuid; est uuid; dep_est uuid; dep_novo uuid; qtd_antes numeric; qtd_depois numeric;
BEGIN
  INSERT INTO auth.users (id, email) VALUES
    (adm, 'adm@ci'), (vend, 'vend@ci'), (moto, 'moto@ci'), (novo, 'novo@ci'), (gest, 'gest@ci');

  -- 1. cadastro público nasce sem tenant e sem papel
  PERFORM ci.exige((SELECT tenant_id IS NULL FROM profiles WHERE id = novo), 'signup nasce sem tenant');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM user_roles WHERE user_id = novo), 'signup nasce sem papel');

  -- usuários do tenant de demonstração
  UPDATE profiles SET tenant_id = demo WHERE id IN (adm, vend, moto, gest);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES
    (adm, demo, 'administrador'), (vend, demo, 'vendedor'), (moto, demo, 'motorista'), (gest, demo, 'gestor');

  -- 2. anon não executa funções SECURITY DEFINER
  PERFORM ci.deve_falhar(NULL, $c$SELECT has_role('a0000000-0000-0000-0000-000000000001','administrador')$c$, 'anon executa has_role');
  PERFORM ci.deve_falhar(NULL, $c$SELECT recalcular_pedido(gen_random_uuid())$c$, 'anon executa recalcular_pedido');

  -- 3. banco_conta_padrao não é chamável por usuários
  PERFORM ci.deve_falhar(adm, $c$SELECT banco_conta_padrao('11111111-1111-1111-1111-111111111111', NULL)$c$, 'authenticated executa banco_conta_padrao');

  -- 4. recalcular_pedido não altera pedido de outro tenant
  INSERT INTO tenants (nome) VALUES ('B') RETURNING id INTO tenant_b;
  INSERT INTO clientes (tenant_id, nome) VALUES (tenant_b, 'c') RETURNING id INTO cli_b;
  INSERT INTO depositos (tenant_id, nome) VALUES (tenant_b, 'd') RETURNING id INTO dep_b;
  INSERT INTO pedidos (tenant_id, cliente_id, deposito_id, subtotal, total)
    VALUES (tenant_b, cli_b, dep_b, 999, 999) RETURNING id INTO ped_b;
  PERFORM ci.entrar(adm);
  PERFORM recalcular_pedido(ped_b);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT total FROM pedidos WHERE id = ped_b) = 999, 'recalcular_pedido ignora outro tenant');

  -- 5. quem não tem tenant não se atribui a um; onboarding cria espaço próprio uma única vez
  PERFORM ci.deve_falhar(novo, format('UPDATE profiles SET tenant_id = %L WHERE id = auth.uid()', demo), 'auto-atribuição de tenant');
  PERFORM ci.entrar(novo);
  t := onboarding_criar_espaco('Loja CI');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tenant_id FROM profiles WHERE id = novo) = t, 'onboarding vincula o tenant novo');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM user_roles WHERE user_id = novo AND role = 'administrador' AND tenant_id = t), 'onboarding concede administrador');
  PERFORM ci.exige(ci.contar(novo, format('SELECT count(*) FROM clientes WHERE tenant_id = %L', demo)) = 0, 'conta nova não vê o tenant de demonstração');
  PERFORM ci.deve_falhar(novo, $c$SELECT onboarding_criar_espaco('Outra')$c$, 'segundo onboarding');
  PERFORM ci.deve_falhar(adm, $c$SELECT onboarding_criar_espaco('Outra')$c$, 'onboarding de conta já vinculada');
  PERFORM ci.deve_falhar(novo, format('UPDATE profiles SET tenant_id = %L WHERE id = auth.uid()', demo), 'troca de tenant após onboarding');

  -- 6. has_role considera o tenant
  PERFORM ci.exige(has_role(adm, 'administrador'), 'administrador do tenant tem o papel');
  UPDATE profiles SET tenant_id = tenant_b WHERE id = gest;
  PERFORM ci.exige(NOT has_role(gest, 'gestor'), 'papel de outro tenant não vale');
  UPDATE profiles SET tenant_id = demo WHERE id = gest;
  PERFORM ci.exige(has_role(gest, 'gestor'), 'papel volta a valer no tenant certo');

  -- 7. administrador não dá papel a usuário sem vínculo com o tenant
  INSERT INTO auth.users (id, email) VALUES ('a0000000-0000-0000-0000-000000000009', 'solto@ci');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO user_roles (user_id, tenant_id, role) VALUES ('a0000000-0000-0000-0000-000000000009', %L, 'vendedor')$c$, demo), 'papel para usuário sem tenant');

  -- 8. caixas: abre e fecha por RPC; escrita direta negada; motorista não lê
  PERFORM ci.deve_falhar(vend, format($c$SELECT abrir_caixa(%L, 100)$c$, filial), 'vendedor abre caixa');
  PERFORM ci.entrar(adm);
  t := abrir_caixa(filial, 100);
  PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM caixas') = 1, 'vendedor lê caixas do tenant');
  PERFORM ci.deve_falhar(vend, 'UPDATE caixas SET valor_abertura = 999999', 'update direto em caixas');
  PERFORM ci.deve_falhar(vend, format('INSERT INTO caixas (tenant_id, filial_id) VALUES (%L, %L)', demo, filial), 'insert direto em caixas');
  PERFORM ci.exige(ci.contar(moto, 'SELECT count(*) FROM caixas') = 0, 'motorista restrito não lê caixas');
  PERFORM ci.deve_falhar(vend, format($c$SELECT fechar_caixa(%L, 100, 'ci')$c$, t), 'vendedor fecha caixa');
  PERFORM ci.entrar(adm);
  PERFORM fechar_caixa(t, 100, 'ci');
  PERFORM ci.sair();

  -- 9. auditoria: só administrador/gestor leem; ninguém grava pelo cliente
  INSERT INTO auditoria (tenant_id, entidade, operacao) VALUES (demo, 'ci', 'x');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM auditoria') = 0, 'vendedor não lê auditoria');
  PERFORM ci.exige(ci.contar(gest, 'SELECT count(*) FROM auditoria WHERE entidade = ''ci''') = 1, 'gestor lê auditoria');
  PERFORM ci.deve_falhar(gest, format($c$INSERT INTO auditoria (tenant_id, entidade, operacao) VALUES (%L, 'x', 'y')$c$, demo), 'insert em auditoria');
  PERFORM ci.deve_falhar(gest, 'DELETE FROM auditoria', 'delete em auditoria');

  -- 10. escrita direta em movimentações de estoque negada
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO estoque_movimentacoes (tenant_id, produto_id, deposito_id, tipo, quantidade) VALUES (%L, gen_random_uuid(), gen_random_uuid(), 'entrada', 1)$c$, demo), 'insert direto em estoque_movimentacoes');

  -- 11. auditoria ligada: preço, desconto e custo registram quem alterou e o que mudou
  SELECT id INTO prod FROM produtos WHERE tenant_id = demo LIMIT 1;
  PERFORM ci.exige(prod IS NOT NULL, 'há produto de demonstração para testar');
  PERFORM ci.entrar(adm);
  UPDATE produtos SET preco_venda = coalesce(preco_venda, 0) + 1 WHERE id = prod;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM auditoria
                     WHERE entidade = 'produtos' AND entidade_id = prod AND usuario_id = adm
                       AND valor_novo ? 'preco_venda' AND valor_anterior ? 'preco_venda') = 1,
                   'alteração de preço de venda é auditada com o usuário');
  PERFORM ci.entrar(adm);
  UPDATE produtos SET descricao = descricao || ' ' WHERE id = prod;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM auditoria WHERE entidade = 'produtos' AND entidade_id = prod) = 1,
                   'campo fora da lista não gera auditoria');
  UPDATE pedidos SET desconto = 10 WHERE id = ped_b;
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'pedidos' AND entidade_id = ped_b
                            AND valor_novo ? 'desconto'), 'alteração de desconto do pedido é auditada');

  -- 12. estoque: saldo só muda pelas RPCs; custo médio e inserção com saldo são auditados
  SELECT id, deposito_id, produto_id INTO est, dep_est, prod FROM estoques WHERE tenant_id = demo LIMIT 1;
  PERFORM ci.exige(est IS NOT NULL, 'há estoque de demonstração para testar');
  PERFORM ci.deve_falhar(adm, format('UPDATE estoques SET quantidade = quantidade + 1000 WHERE id = %L', est), 'update direto de saldo em estoques');
  PERFORM ci.deve_falhar(adm, format('UPDATE estoques SET reservado = 0 WHERE id = %L', est), 'update direto de reserva em estoques');
  PERFORM ci.entrar(adm);
  UPDATE estoques SET custo_medio = coalesce(custo_medio, 0) + 1 WHERE id = est;
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'estoques' AND entidade_id = est
                            AND valor_novo ? 'custo_medio'), 'alteração de custo médio é auditada');
  SELECT quantidade INTO qtd_antes FROM estoques WHERE id = est;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep_est, 'entrada'::mov_tipo, 5, 'ci', 'ci');
  PERFORM ci.sair();
  SELECT quantidade INTO qtd_depois FROM estoques WHERE id = est;
  PERFORM ci.exige(qtd_depois = qtd_antes + 5, 'RPC de movimentação continua alterando o saldo');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'ci-estoque') RETURNING id INTO dep_novo;
  PERFORM ci.deve_falhar(adm, format('INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade) VALUES (%L, %L, %L, 7)', demo, prod, dep_novo), 'insert direto de estoque com saldo');
  PERFORM ci.deve_falhar(adm, format('INSERT INTO estoques (tenant_id, produto_id, deposito_id, reservado) VALUES (%L, %L, %L, 7)', demo, prod, dep_novo), 'insert direto de estoque com reserva');
  PERFORM ci.entrar(adm);
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, custo_medio) VALUES (demo, prod, dep_novo, 3);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 0 AND reservado = 0 FROM estoques WHERE produto_id = prod AND deposito_id = dep_novo),
                   'estoque criado pelo cliente nasce com saldo e reserva zerados');

  -- 13. webhooks: tabela e funções só para o service_role; idempotência, reprocessamento e fence
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM webhook_eventos', 'usuário lê webhook_eventos');
  PERFORM ci.deve_falhar(NULL, 'SELECT count(*) FROM webhook_eventos', 'anon lê webhook_eventos');
  PERFORM ci.deve_falhar(adm, $c$SELECT webhook_registrar('pix', 'x')$c$, 'usuário executa webhook_registrar');
  PERFORM ci.deve_falhar(NULL, $c$SELECT webhook_concluir('pix', 'x', 1, 'processado')$c$, 'anon executa webhook_concluir');

  EXECUTE 'SET ROLE service_role';
  v_json := webhook_registrar('pix', 'evt-1', NULL, '{"a":1}'::jsonb);
  PERFORM ci.exige(v_json ->> 'resultado' = 'novo' AND (v_json ->> 'tentativa')::int = 1, 'primeiro registro do evento é novo (tentativa 1)');
  v_json := webhook_registrar('pix', 'evt-1');
  PERFORM ci.exige(v_json ->> 'resultado' = 'duplicado', 'evento em processamento é duplicado');
  v_json := webhook_registrar('boleto', 'evt-1');
  PERFORM ci.exige(v_json ->> 'resultado' = 'novo', 'mesmo id em outro provedor é outro evento');
  PERFORM ci.exige(webhook_concluir('pix', 'evt-1', 1, 'erro', 'falhou'), 'conclusão com erro da tentativa vigente vale');
  v_json := webhook_registrar('pix', 'evt-1');
  PERFORM ci.exige(v_json ->> 'resultado' = 'reprocessar' AND (v_json ->> 'tentativa')::int = 2, 'evento com erro é reprocessado (tentativa 2)');
  PERFORM ci.exige(NOT webhook_concluir('pix', 'evt-1', 1, 'processado'), 'conclusão de tentativa antiga é descartada');
  PERFORM ci.exige(webhook_concluir('pix', 'evt-1', 2, 'processado'), 'conclusão da tentativa vigente vale');
  v_json := webhook_registrar('pix', 'evt-1');
  PERFORM ci.exige(v_json ->> 'resultado' = 'duplicado', 'evento processado não é reprocessado');
  EXECUTE 'RESET ROLE';
  PERFORM ci.exige((SELECT status FROM webhook_eventos WHERE provedor = 'pix' AND event_id = 'evt-1') = 'processado',
                   'tentativa antiga não sobrescreveu o resultado da nova');

  UPDATE webhook_eventos SET recebido_em = now() - interval '10 minutes'
   WHERE provedor = 'boleto' AND event_id = 'evt-1';
  EXECUTE 'SET ROLE service_role';
  v_json := webhook_registrar('boleto', 'evt-1');
  PERFORM ci.exige(v_json ->> 'resultado' = 'reprocessar', 'evento preso em recebido há mais de 5 minutos é reprocessado');
  v_json := webhook_registrar('boleto', 'evt-1');
  PERFORM ci.exige(v_json ->> 'resultado' = 'duplicado', 'a trava impede processamento em paralelo');
  PERFORM ci.exige(NOT webhook_concluir('boleto', 'evt-1', 1, 'erro', 'lento'), 'processamento antigo e lento não derruba o novo');
  EXECUTE 'RESET ROLE';
  PERFORM ci.exige((SELECT status FROM webhook_eventos WHERE provedor = 'boleto' AND event_id = 'evt-1') = 'recebido',
                   'evento da tentativa nova segue em recebido');

  -- 14. restaurante: cardápio, salão, cozinha e fechamento de conta
  INSERT INTO auth.users (id, email) VALUES (gar, 'garcom@ci'), (coz, 'cozinha@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (gar, coz);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (gar, demo, 'garcom'), (coz, demo, 'cozinha');
  INSERT INTO auth.users (id, email) VALUES (cxa, 'caixa-restaurante@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = cxa;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (cxa, demo, 'caixa');

  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (%L, 'x')$c$, demo), 'garçom cadastra cardápio');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO mesas (tenant_id, numero) VALUES (%L, '99')$c$, demo), 'garçom cadastra mesa');
  PERFORM ci.entrar(adm);
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Pratos') RETURNING id INTO cat_r;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao)
    VALUES (demo, cat_r, 'Hambúrguer', 40, 'cozinha') RETURNING id INTO it_prato;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao)
    VALUES (demo, cat_r, 'Refrigerante lata', 8, 'nenhuma') RETURNING id INTO it_lata;
  INSERT INTO cardapio_grupos (tenant_id, item_id, nome, obrigatorio, max_escolhas)
    VALUES (demo, it_prato, 'Ponto da carne', true, 1) RETURNING id INTO gr_ponto;
  INSERT INTO cardapio_grupos (tenant_id, item_id, nome, obrigatorio, max_escolhas)
    VALUES (demo, it_prato, 'Adicionais', false, 2) RETURNING id INTO gr_add;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, gr_ponto, 'Mal passado', 0) RETURNING id INTO o_mal;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, gr_ponto, 'Ao ponto', 0) RETURNING id INTO o_ponto;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, gr_add, 'Bacon', 5) RETURNING id INTO o_bacon;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, gr_add, 'Ovo', 3) RETURNING id INTO o_ovo;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, gr_add, 'Queijo extra', 4) RETURNING id INTO o_queijo;
  INSERT INTO mesas (tenant_id, numero, capacidade) VALUES (demo, '1', 4) RETURNING id INTO mesa1;
  INSERT INTO mesas (tenant_id, numero, capacidade) VALUES (demo, '2', 4) RETURNING id INTO mesa2;
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO mesas (tenant_id, numero) VALUES (%L, '1')$c$, demo), 'mesa com número repetido');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM cardapio_itens') = 2, 'garçom lê o cardápio');

  -- abrir comanda: só quem opera o salão; uma comanda aberta por mesa
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_abrir_comanda(%L, 2)$c$, mesa1), 'vendedor abre comanda');
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_abrir_comanda(%L, 2)$c$, mesa1), 'cozinha abre comanda');
  PERFORM ci.deve_falhar(NULL, $c$SELECT restaurante_abrir_comanda(NULL, 2)$c$, 'anon abre comanda');
  PERFORM ci.entrar(gar);
  c1 := restaurante_abrir_comanda(mesa1, 2, 'Cliente CI', 10, 5);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT numero FROM comandas WHERE id = c1) = 1, 'primeira comanda da empresa tem o número 1');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_abrir_comanda(%L, 2)$c$, mesa1), 'segunda comanda na mesma mesa');

  -- lançar itens: opções obrigatórias, limite de escolhas, opção alheia, quantidade
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1)$c$, c1, it_prato), 'item sem a opção obrigatória');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1, ARRAY[%L, %L, %L, %L]::uuid[])$c$, c1, it_prato, o_ponto, o_bacon, o_ovo, o_queijo), 'mais escolhas que o limite do grupo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1, ARRAY[%L, %L]::uuid[])$c$, c1, it_prato, o_mal, o_ponto), 'duas opções em grupo de escolha única');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1, ARRAY[gen_random_uuid()])$c$, c1, it_prato), 'opção que não existe');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1, ARRAY[%L, %L]::uuid[])$c$, c1, it_lata, o_ponto, o_bacon), 'opção de outro item');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 0)$c$, c1, it_lata), 'quantidade zero');
  PERFORM ci.entrar(gar);
  i1 := restaurante_lancar_item(c1, it_prato, 2, ARRAY[o_ponto, o_bacon, o_ovo]::uuid[], 'sem cebola');
  i2 := restaurante_lancar_item(c1, it_lata, 1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT preco_unitario = 48 AND total = 96 AND estacao = 'cozinha' AND situacao = 'pendente'
                      AND jsonb_array_length(opcoes) = 3 FROM comanda_itens WHERE id = i1),
                   'preço do item soma os adicionais e guarda a cópia das opções');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[]'::jsonb)$c$, c1), 'fechar com itens ainda não enviados');

  -- cozinha
  PERFORM ci.entrar(gar);
  n_r := restaurante_enviar_cozinha(c1);
  PERFORM ci.sair();
  PERFORM ci.exige(n_r = 2, 'envio à cozinha marca os dois itens');
  PERFORM ci.exige((SELECT situacao FROM comanda_itens WHERE id = i1) = 'enviado'
               AND (SELECT situacao FROM comanda_itens WHERE id = i2) = 'entregue',
                   'item sem estação (lata) já sai entregue');
  PERFORM ci.exige(ci.contar(gar, format($c$SELECT restaurante_enviar_cozinha(%L)$c$, c1)) = 0, 'reenvio não repete itens');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_atualizar_item(%L, 'preparando')$c$, i1), 'garçom marca preparo');
  PERFORM ci.entrar(coz);
  PERFORM restaurante_atualizar_item(i1, 'preparando');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_atualizar_item(%L, 'entregue')$c$, i1), 'pular etapas do preparo');
  PERFORM ci.entrar(coz);
  PERFORM restaurante_atualizar_item(i1, 'pronto');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_atualizar_item(%L, 'preparando')$c$, i1), 'voltar etapa do preparo');
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_atualizar_item(%L, 'entregue')$c$, i1), 'cozinha marca o item como entregue');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_atualizar_item(i1, 'entregue');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM comanda_itens WHERE id = i1) = 'entregue', 'garçom entrega o item pronto');

  -- cancelamento: pendente é do garçom; depois de enviado, só a gestão e com motivo
  PERFORM ci.entrar(gar);
  i3 := restaurante_lancar_item(c1, it_lata, 1);
  PERFORM restaurante_cancelar_item(i3);
  i4 := restaurante_lancar_item(c1, it_prato, 1, ARRAY[o_mal]::uuid[]);
  PERFORM restaurante_enviar_cozinha(c1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM comanda_itens WHERE id = i3) = 'cancelado', 'garçom cancela item ainda não enviado');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_cancelar_item(%L, 'cliente desistiu')$c$, i4), 'garçom cancela item já enviado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT restaurante_cancelar_item(%L)$c$, i4), 'cancelar item enviado sem motivo');
  PERFORM ci.entrar(gest);
  PERFORM restaurante_cancelar_item(i4, 'cliente desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cancelado_por = gest AND motivo_cancelamento = 'cliente desistiu' FROM comanda_itens WHERE id = i4),
                   'gestão cancela item enviado e o motivo fica registrado');

  -- fechamento: 96 + 8 = 104; couvert 2 x 5 = 10; serviço 10% = 10,40; total 124,40
  PERFORM ci.entrar(adm);
  caixa_r := abrir_caixa(filial, 0);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"pix","valor":100}]'::jsonb, %L)$c$, c1, caixa_r), 'pagamentos que não fecham a conta');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"pix","valor":124.40}]'::jsonb)$c$, c1), 'fechar sem caixa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"crediario","valor":124.40}]'::jsonb, %L)$c$, c1, caixa_r), 'crediário na comanda');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"boleto","valor":124.40}]'::jsonb, %L)$c$, c1, caixa_r), 'boleto na comanda');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"pix","valor":114.40}]'::jsonb, %L, 10)$c$, c1, caixa_r), 'desconto dado pelo caixa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"pix","valor":124.40}]'::jsonb, %L)$c$, c1, caixa_r), 'garçom recebe a conta (só gestão e caixa)');
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_fechar_comanda(%L, '[]'::jsonb)$c$, c1), 'cozinha fecha conta');
  PERFORM ci.entrar(cxa);
  v_json := restaurante_fechar_comanda(c1,
    '[{"forma":"pix","valor":70,"pagante":"Ana"},{"forma":"dinheiro","valor":54.40,"pagante":"Bia"}]'::jsonb, caixa_r);
  PERFORM ci.sair();
  PERFORM ci.exige((v_json ->> 'subtotal')::numeric = 104 AND (v_json ->> 'couvert')::numeric = 10
                   AND (v_json ->> 'taxa_servico')::numeric = 10.40 AND (v_json ->> 'total')::numeric = 124.40,
                   'fechamento calcula subtotal, couvert, serviço e total');
  PERFORM ci.exige((SELECT situacao = 'fechada' AND total = 124.40 AND caixa_id = caixa_r FROM comandas WHERE id = c1), 'comanda fica fechada');
  PERFORM ci.exige((SELECT count(*) = 2 AND sum(valor) = 124.40 FROM comanda_pagamentos WHERE comanda_id = c1), 'pagamentos divididos ficam registrados');
  PERFORM ci.exige((SELECT count(*) = 2 AND sum(valor) = 124.40 FROM caixa_movimentos WHERE caixa_id = caixa_r AND tipo = 'venda'),
                   'cada pagamento é lançado no caixa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[]'::jsonb, %L)$c$, c1, caixa_r), 'fechar comanda já fechada');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1)$c$, c1, it_lata), 'lançar item em comanda fechada');

  -- desconto pela gestão, sem couvert e sem serviço
  PERFORM ci.entrar(gar);
  c2 := restaurante_abrir_comanda(mesa2, NULL, NULL, 10, 0);
  PERFORM restaurante_lancar_item(c2, it_lata, 1);
  PERFORM restaurante_enviar_cozinha(c2);
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  v_json := restaurante_fechar_comanda(c2, '[{"forma":"dinheiro","valor":8.00}]'::jsonb, caixa_r, 0.80);
  PERFORM ci.sair();
  PERFORM ci.exige((v_json ->> 'taxa_servico')::numeric = 0.80 AND (v_json ->> 'total')::numeric = 8.00,
                   'gestão fecha com desconto');

  -- cancelar comanda e transferir de mesa
  PERFORM ci.entrar(gar);
  c3 := restaurante_abrir_comanda(mesa1, 2);
  PERFORM restaurante_lancar_item(c3, it_lata, 1);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_cancelar_comanda(%L, 'teste')$c$, c3), 'garçom cancela comanda');
  PERFORM ci.entrar(gest);
  PERFORM restaurante_cancelar_comanda(c3, 'cliente foi embora');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM comandas WHERE id = c3)
               AND NOT EXISTS (SELECT 1 FROM comanda_itens WHERE comanda_id = c3 AND situacao <> 'cancelado'),
                   'cancelar comanda cancela os itens');
  PERFORM ci.entrar(gar);
  c4 := restaurante_abrir_comanda(mesa1, 2);
  c5 := restaurante_abrir_comanda(NULL, 1, 'Balcão');
  PERFORM restaurante_transferir_mesa(c4, mesa2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT mesa_id FROM comandas WHERE id = c4) = mesa2, 'comanda muda de mesa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_transferir_mesa(%L, %L)$c$, c5, mesa2), 'transferir para mesa ocupada');

  -- isolamento e permissões de leitura
  PERFORM ci.exige(ci.contar(novo, 'SELECT count(*) FROM comandas') = 0, 'outra empresa não vê comandas');
  PERFORM ci.exige(ci.contar(novo, 'SELECT count(*) FROM cardapio_itens') = 0, 'outra empresa não vê o cardápio');
  PERFORM ci.deve_falhar(novo, format($c$SELECT restaurante_lancar_item(%L, %L, 1)$c$, c4, it_lata), 'lançar em comanda de outra empresa');
  PERFORM ci.deve_falhar(novo, format($c$SELECT restaurante_atualizar_item(%L, 'preparando')$c$, i1), 'mexer em item de outra empresa');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM comandas') = 0, 'vendedor não lê comandas');
  PERFORM ci.exige(ci.contar(moto, 'SELECT count(*) FROM comandas') = 0, 'motorista não lê comandas');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM comanda_itens') > 0, 'cozinha lê os itens');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM comanda_pagamentos') = 0, 'cozinha não lê pagamentos');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM comanda_pagamentos') = 3, 'gestão lê os pagamentos');

  -- a escrita direta nas comandas é negada
  PERFORM ci.deve_falhar(gar, format('UPDATE comandas SET total = 0 WHERE id = %L', c4), 'update direto em comandas');
  PERFORM ci.deve_falhar(adm, format('UPDATE comanda_itens SET total = 0 WHERE id = %L', i1), 'update direto em comanda_itens');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO comanda_pagamentos (tenant_id, comanda_id, forma, valor) VALUES (%L, %L, 'pix', 1)$c$, demo, c4), 'insert direto em comanda_pagamentos');
  PERFORM ci.deve_falhar(adm, format('DELETE FROM comandas WHERE id = %L', c4), 'delete direto em comandas');

  -- alteração de preço do cardápio é auditada
  PERFORM ci.entrar(gest);
  UPDATE cardapio_itens SET preco = 42 WHERE id = it_prato;
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'cardapio_itens' AND entidade_id = it_prato
                            AND usuario_id = gest AND valor_novo ? 'preco'), 'preço do cardápio é auditado');
  PERFORM ci.exige((SELECT preco_unitario FROM comanda_itens WHERE id = i1) = 48, 'mudar o preço não altera item já lançado');
  PERFORM ci.exige((SELECT count(DISTINCT numero) = count(*) AND min(numero) = 1 AND max(numero) = count(*)
                      FROM comandas WHERE tenant_id = demo), 'numeração das comandas é sequencial e sem repetição');

  -- cadastros de uma empresa não apontam para os de outra (chaves compostas com a empresa)
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_grupos (tenant_id, item_id, nome) VALUES (%L, %L, 'x')$c$, tenant_b, it_prato), 'grupo de uma empresa em item de outra');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome) VALUES (%L, %L, 'x')$c$, tenant_b, gr_ponto), 'opção de uma empresa em grupo de outra');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco) VALUES (%L, %L, 'x', 1)$c$, tenant_b, cat_r), 'item de uma empresa em categoria de outra');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO mesas (tenant_id, filial_id, numero) VALUES (%L, %L, 'x')$c$, tenant_b, filial), 'mesa de uma empresa em filial de outra');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO comanda_itens (tenant_id, comanda_id, cardapio_item_id, nome, estacao, quantidade, preco_unitario, total) VALUES (%L, %L, %L, 'x', 'cozinha', 1, 1, 1)$c$, tenant_b, c4, it_lata), 'item de comanda de uma empresa em comanda de outra');

  -- fechar a conta: nada pode ficar em preparo, e o caixa precisa ser da filial da comanda
  PERFORM ci.entrar(adm);
  INSERT INTO mesas (tenant_id, filial_id, numero, capacidade) VALUES (demo, filial, '3', 4) RETURNING id INTO mesa3;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, '22222222-2222-2222-2222-222222222222', 'Filial CI 2') RETURNING id INTO filial2;
  caixa2 := abrir_caixa(filial2, 0);
  PERFORM ci.sair();
  PERFORM ci.entrar(gar);
  c6 := restaurante_abrir_comanda(mesa3);
  i5 := restaurante_lancar_item(c6, it_prato, 1, ARRAY[o_ponto]::uuid[]);
  i6 := restaurante_lancar_item(c6, it_lata, 1);
  PERFORM restaurante_enviar_cozinha(c6);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT filial_id FROM comandas WHERE id = c6) = filial, 'comanda da mesa herda a filial da mesa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"pix","valor":55}]'::jsonb, %L)$c$, c6, caixa_r), 'fechar com item ainda na cozinha');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_atualizar_item(%L, 'entregue')$c$, i5), 'garçom entrega item que ainda não ficou pronto');
  PERFORM ci.entrar(gest);
  PERFORM restaurante_atualizar_item(i5, 'entregue');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM comanda_itens WHERE id = i5) = 'entregue', 'gestão resolve item esquecido na cozinha');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"pix","valor":55}]'::jsonb, %L)$c$, c6, caixa2), 'receber em caixa de outra filial');
  PERFORM ci.entrar(cxa);
  v_json := restaurante_fechar_comanda(c6, '[{"forma":"pix","valor":55}]'::jsonb, caixa_r);
  PERFORM ci.sair();
  PERFORM ci.exige((v_json ->> 'subtotal')::numeric = 50 AND (v_json ->> 'total')::numeric = 55,
                   'conta fecha no caixa da própria filial (50 + 10% de serviço)');

  -- 15. maquininha simulada: venda de cartão de ponta a ponta, com NSU e autorização de exemplo
  PERFORM ci.entrar(adm);
  INSERT INTO tef_config (tenant_id, filial_id, credenciadora, modo) VALUES (demo, filial, 'stone', 'simulado') RETURNING id INTO tef_cfg;
  PERFORM ci.sair();
  PERFORM ci.exige(tef_cfg IS NOT NULL, 'configuração da maquininha aceita o modo simulado');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE tef_config SET modo = 'inexistente' WHERE id = %L$c$, tef_cfg), 'modo de maquininha inválido');

  SELECT quantidade INTO est_antes FROM estoques WHERE produto_id = prod AND deposito_id = dep_est;
  PERFORM ci.entrar(adm);
  ped_t := frente_venda(dep_est, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 2, 'preco_unitario', 100)),
                        'cartao_credito', NULL, 0, 3);
  PERFORM frente_registrar_tef(ped_t, 'simulado', 'SIM-000123', 'AUT456', 'Visa');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tef_credenciadora = 'simulado' AND tef_nsu = 'SIM-000123' AND tef_autorizacao = 'AUT456'
                      AND tef_bandeira = 'Visa' AND forma_pagamento = 'cartao_credito' AND total = 200
                      FROM pedidos WHERE id = ped_t), 'venda no cartão guarda credenciadora, NSU, autorização e bandeira');
  PERFORM ci.exige((SELECT status = 'aprovada' AND valor = 200 AND nsu = 'SIM-000123' AND credenciadora = 'simulado'
                      FROM tef_transacoes WHERE pedido_id = ped_t), 'transação aprovada fica registrada com o valor da venda');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(valor) = 200 FROM caixa_movimentos
                     WHERE pedido_id = ped_t AND tipo = 'venda' AND forma_pagamento = 'cartao_credito'),
                   'venda no cartão entra no caixa');
  SELECT quantidade INTO est_depois FROM estoques WHERE produto_id = prod AND deposito_id = dep_est;
  PERFORM ci.exige(est_depois = est_antes - 2, 'venda no cartão baixa o estoque');

  -- recusa da maquininha: fica registrada sem venda
  PERFORM ci.entrar(adm);
  PERFORM tef_registrar_negada(filial, 'simulado', 'cartao_credito', 50, 1, 'Mastercard', 'Simulação: cartão recusado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 1 FROM tef_transacoes WHERE status = 'negada' AND credenciadora = 'simulado'
                      AND pedido_id IS NULL AND valor = 50 AND motivo = 'Simulação: cartão recusado'),
                   'recusa da maquininha fica registrada sem criar venda');

  -- só a empresa dona da venda registra o TEF; ninguém grava direto na tabela de transações
  PERFORM ci.deve_falhar(novo, format($c$SELECT frente_registrar_tef(%L, 'simulado', 'SIM-1', 'A', 'Visa')$c$, ped_t), 'registrar TEF em venda de outra empresa');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO tef_transacoes (tenant_id, valor, status) VALUES (%L, 1, 'aprovada')$c$, demo), 'gravar transação TEF direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE tef_transacoes SET status = 'aprovada' WHERE pedido_id = %L$c$, ped_t), 'alterar transação TEF direto');

  -- cancelamento da venda com a senha do gestor: devolve estoque, estorna o caixa e marca o TEF como cancelado
  INSERT INTO gestor_autorizacoes (tenant_id, gestor_id, operador_id, acao) VALUES (demo, gest, adm, 'cancelar_venda') RETURNING id INTO aut_t;
  PERFORM ci.entrar(adm);
  PERFORM frente_cancelar_venda(ped_t, aut_t, 'Teste da maquininha simulada');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelado' FROM pedidos WHERE id = ped_t), 'venda cancelada');
  PERFORM ci.exige((SELECT status = 'cancelada' FROM tef_transacoes WHERE pedido_id = ped_t), 'cancelar a venda marca a transação TEF como cancelada');
  SELECT quantidade INTO est_depois FROM estoques WHERE produto_id = prod AND deposito_id = dep_est;
  PERFORM ci.exige(est_depois = est_antes, 'cancelar a venda devolve o estoque');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(valor) = 200 FROM caixa_movimentos
                     WHERE pedido_id = ped_t AND tipo = 'saida' AND forma_pagamento = 'cartao_credito'),
                   'cancelar a venda estorna o caixa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT frente_cancelar_venda(%L, %L, 'de novo')$c$, ped_t, aut_t), 'cancelar de novo a mesma venda');
END $$;

-- 16. isolamento do salão (garçom e cozinha)
DO $$
DECLARE
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz    constant uuid := 'a0000000-0000-0000-0000-000000000007';
  gar_cx constant uuid := 'a0000000-0000-0000-0000-000000000008';
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  liberadas constant text[] := ARRAY['profiles', 'user_roles', 'empresas', 'filiais', 'tenants',
    'cardapio_categorias', 'cardapio_itens', 'cardapio_grupos', 'cardapio_opcoes',
    'mesas', 'comandas', 'comanda_itens', 'comanda_pagamentos', 'restaurante_zonas_entrega',
    'restaurante_pracas', 'mesa_reservas', 'restaurante_taras', 'restaurante_pedidos_externos', 'restaurante_senhas_contador', 'cardapios', 'cardapio_cardapio_itens', 'restaurante_chamados', 'restaurante_chamados_motivos',
    -- módulos liberados da empresa: o menu e as travas de cada módulo leem para qualquer perfil (só leitura da própria empresa)
    'empresa_modulos_liberados',
    -- bulário veterinário (base global do MAPA): sem empresa dona e sem nenhum grant para authenticated; só as funções bulario_* leem, e elas exigem papel e clínica liberada
    'bulario_medicamentos',
    -- backup por cliente (rotina noturna da equipe): controle interno, só o serviço lê e grava; nenhum grant para authenticated
    'backup_execucoes',
    -- backup no Google Drive por cliente: conector cifrado e execuções; só o serviço lê e grava (a política restritiva é USING (false), sem grant para authenticated)
    'backup_drive_config', 'backup_drive_execucoes'];
  sem_trava constant text[] := ARRAY['current_tenant_id', 'current_motorista_id', 'has_role', 'eh_motorista_restrito',
    'eh_saas_operador', 'eh_salao_restrito', 'onboarding_criar_espaco',
    -- contador: só respondem sobre o próprio acesso (sem dado de empresa); a trava do salão não se aplica porque o perfil do salão nunca é contador
    'eh_contador_restrito', 'contador_empresa_id', 'contador_edita_tributos', 'contador_meu_acesso',
    -- página de login da empresa: devolve só nome, cor e logo (dados públicos de marca) de uma empresa ativa com link
    'empresa_por_slug', 'filial_irrestrita', 'pode_filial', 'contato_enviar',
    -- só grava a posição do próprio motorista; quem não é motorista não tem linha para alterar
    'motorista_enviar_posicao',
    -- agenda do profissional: só quem tem o perfil profissional (e a conta ligada a um cadastro) passa
    'eh_profissional_restrito', 'pet_minha_agenda', 'pet_minha_situacao',
    -- só responde se a empresa tem a clínica liberada
    'clinica_liberada',
    -- bulário veterinário: exigem administrador, gestor ou veterinário (nunca o perfil restrito do salão) e clínica liberada; bulario_total é só da equipe EZRA
    'bulario_buscar', 'bulario_resumo', 'bulario_ficha', 'bulario_nota_salvar', 'bulario_total',
    -- menu personalizado: devolve só a disposição do menu da própria empresa (sem dado sensível), para qualquer pessoa dela; gravar e restaurar exigem administrador ou gestor
    'menu_personalizado_obter',
    -- dashboard personalizado: devolve só a disposição do dashboard da própria empresa (sem dado sensível); gravar e restaurar exigem administrador ou gestor
    'dashboard_personalizado_obter',
    -- só responde se a empresa tem o lava rápido liberado
    'lava_rapido_liberado',
    -- fotos do lava rápido: respondem só verdadeiro com perfil do pátio, módulo liberado e foto reservada ou ativa
    '_lr_foto_perfil_ok', '_lr_foto_pode_enviar', '_lr_foto_pode_ler',
    -- prontuário: cada função confere o perfil Veterinário, a clínica liberada e o cadastro com CRMV
    'clinica_pacientes', 'clinica_atendimento_abrir', 'clinica_atendimento_salvar', 'clinica_atendimento_fechar',
    'clinica_adendo_criar', 'clinica_historico', 'clinica_pet_alergias',
    -- vacinas: catálogo e cartão para a gestão, o veterinário e a recepção; aplicação só do veterinário
    'clinica_vacinas_catalogo', 'clinica_vacina_catalogo_salvar', 'clinica_lotes_vacina', 'clinica_aplicadores', 'clinica_vacina_aplicar',
    'clinica_vacina_registrar_externa', 'clinica_vacina_cancelar', 'clinica_cartao_vacinacao',
    -- modelos de exame: gestão e veterinário mantêm; cada função confere o perfil e a clínica liberada
    'clinica_exame_modelos', 'clinica_exame_modelo_salvar', 'clinica_exame_campo_salvar', 'clinica_exame_campo_mover',
    'clinica_exame_referencia_salvar', 'clinica_exame_modelos_iniciais',
    -- resultados de exame: cada função confere o perfil Veterinário, a clínica liberada e o cadastro com CRMV
    'clinica_exame_abrir', 'clinica_exame_salvar', 'clinica_exame_fechar', 'clinica_exame_cancelar', 'clinica_exame_adendo_criar',
    'clinica_exame_get', 'clinica_exames_do_pet', 'clinica_exame_evolucao', 'clinica_importar_pdf', 'clinica_pacientes_atendidos',
    -- anexos: cada função confere o perfil Veterinário e a clínica liberada; as duas de apoio só respondem verdadeiro com perfil, clínica e registro prévio
    'clinica_anexo_preparar', 'clinica_anexo_confirmar', 'clinica_anexos', 'clinica_anexo_abrir', 'clinica_anexo_cancelar',
    '_clinica_anexo_pode_enviar', '_clinica_anexo_pode_ler',
    -- cópia para o trabalho sem internet: só o veterinário
    'clinica_visita_preparar',
    -- cadastro rápido de tutor e pet pelo veterinário (também sem internet): só o veterinário
    'clinica_cadastro_rapido',
    -- atendimento sem internet: cria a visita e preenche e fecha com chave de repetição; só o veterinário
    'clinica_visita_registrar', 'clinica_atendimento_offline', 'clinica_vacina_offline', 'clinica_exame_offline', 'clinica_anexo_offline_preparar',
    -- serviços de consulta para iniciar atendimento no Prontuário: só o veterinário
    'clinica_servicos_consulta', 'clinica_meu_veterinario',
    -- link combinado no cadastro do assinante, mostrado no primeiro acesso: só o do próprio tenant
    'assinante_link_sugerido',
    -- taxa inicial por segmento: só calcula o valor; confere o operador da equipe
    'saas_taxa_inicial_cliente',
    -- manufatura: só responde se a empresa tem o módulo liberado pela equipe
    'manufatura_liberada',
    -- hotelaria: só responde se a empresa tem o módulo liberado
    'hotelaria_liberada',
    -- receituário e documentos: cada função confere o perfil Veterinário, a clínica liberada e o cadastro com CRMV
    'clinica_documento_emitir', 'clinica_documento_cancelar', 'clinica_documento_obter', 'clinica_documentos_do_pet',
    'clinica_documento_contexto', 'clinica_documento_modelo_salvar', 'clinica_documento_modelo_excluir',
    -- modelos de receita: cada função confere o perfil Veterinário, a clínica liberada e o cadastro com CRMV
    'clinica_receita_modelos', 'clinica_receita_modelo_salvar', 'clinica_receita_modelo_excluir',
    -- fila do dia: cada função confere perfil da recepção ou da gestão e a clínica liberada (veterinário é perfil restrito)
    'clinica_fila_listar', 'clinica_fila_buscar_paciente', 'clinica_fila_entrada', 'clinica_fila_gravidade', 'clinica_fila_situacao',
    -- internação: cada função confere o perfil (veterinário; auxiliar só em pesagem e ocorrência; gestão só nos boxes), a clínica liberada e o cadastro ligado à conta
    'pet_box_salvar', 'clinica_boxes', 'clinica_internacao_admitir', 'clinica_internacoes', 'clinica_internacao_obter',
    'clinica_internacao_pesagem', 'clinica_internacao_relato', 'clinica_internacao_ocorrencia', 'clinica_internacao_box_trocar',
    'clinica_internacao_encerrar',
    -- internação, fase 2: prescrição e suspensão (veterinário), execução das doses e mapa (veterinário e auxiliar), itens (auxiliar lança, veterinário cancela)
    'clinica_internacao_prescrever', 'clinica_prescricao_suspender', 'clinica_execucao_registrar', 'clinica_execucoes_mapa',
    'clinica_internacao_catalogo', 'clinica_internacao_item_lancar', 'clinica_internacao_item_cancelar',
    -- SNGPC: cada função confere o perfil (administrador, gestor ou veterinário) e a clínica liberada
    'sngpc_medicamento_salvar', 'sngpc_medicamentos', 'sngpc_registrar', 'sngpc_cancelar', 'sngpc_saldo', 'sngpc_livro',
    'sngpc_responsaveis', 'sngpc_periodo', 'sngpc_inventario', 'sngpc_envio_registrar', 'sngpc_envio_transmitir', 'sngpc_envio_cancelar',
    'sngpc_envios', 'sngpc_envio_xml',
    -- cobrança no caixa da ordem de serviço do pet e da internação: confere perfil de recepção/gestão e, na internação, a clínica liberada
    'clinica_internacoes_a_cobrar', 'clinica_internacao_cobranca', 'clinica_internacao_cobrar',
    -- sinais vitais da internação: registrar, corrigir e ler são do veterinário e do auxiliar (confere a internação aberta e o cadastro ligado à conta); o catálogo é lido por eles e mantido por gestão e veterinário; todas conferem a clínica liberada
    'clinica_sinais_parametros', 'clinica_sinais_parametro_salvar', 'clinica_sinal_registrar', 'clinica_sinal_corrigir', 'clinica_sinais_internacao',
    -- passagem de turno da internação: escrever, dar ciente, resolver pendência, ler e ver o plantão são do veterinário e do auxiliar (confere a internação aberta e o cadastro ligado à conta); todas conferem a clínica liberada
    'clinica_turno_registrar', 'clinica_turno_ciente', 'clinica_pendencia_baixar', 'clinica_turnos_internacao', 'clinica_plantao',
    -- portal do tutor, lado da clínica: convites e acessos são da recepção e da gestão (conferem o perfil e a clínica liberada); liberar, retirar e listar itens do animal são do veterinário (conferem o cadastro com CRMV)
    'clinica_portal_convite_criar', 'clinica_portal_convite_revogar', 'clinica_portal_acessos', 'clinica_portal_vinculo_revogar',
    'clinica_portal_itens_do_pet', 'clinica_portal_liberar', 'clinica_portal_retirar',
    -- portal do tutor, lado do tutor: não usa papel nem empresa; a identidade vem da sessão e só vale com vínculo ATIVO ao cadastro do animal (animal de outro tutor responde "não encontrado")
    'portal_resgatar_convite', 'portal_meus_pets', 'portal_pet_itens', 'portal_exame_obter', 'portal_receita_obter'];
  faltando text;
BEGIN
  -- estrutura: tabela ou função nova sem a proteção reprova o CI
  SELECT string_agg(c.relname, ', ') INTO faltando
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity AND NOT (c.relname = ANY (liberadas))
     AND NOT EXISTS (SELECT 1 FROM pg_policies pp WHERE pp.schemaname = 'public' AND pp.tablename = c.relname
                        AND pp.permissive = 'RESTRICTIVE' AND pp.qual LIKE '%eh_salao_restrito%');
  PERFORM ci.exige(faltando IS NULL, 'toda tabela com RLS tem política restritiva do salão (eh_salao_restrito) ou está na lista liberada' || coalesce(' (faltam: ' || faltando || ')', ''));

  SELECT string_agg(p.proname, ', ') INTO faltando
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.prosecdef AND pg_get_function_result(p.oid) <> 'trigger'
     AND has_function_privilege('authenticated', p.oid, 'execute')
     AND p.proname NOT LIKE 'restaurante\_%' AND NOT (p.proname = ANY (sem_trava))
     AND pg_get_functiondef(p.oid) NOT LIKE '%exige_nao_salao%';
  PERFORM ci.exige(faltando IS NULL, 'toda função chamável tem a trava do salão ou está na lista liberada' || coalesce(' (faltam: ' || faltando || ')', ''));

  -- contador: tabela ou função nova sem a proteção do contador reprova o CI
  SELECT string_agg(c.relname, ', ') INTO faltando
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity
     AND c.relname NOT IN ('profiles', 'user_roles', 'empresas', 'filiais', 'tenants', 'nfe', 'nfe_itens', 'tributos_aprox_ncm', 'tributos_aprox_ajuste')
     AND NOT EXISTS (SELECT 1 FROM pg_policies pp WHERE pp.schemaname = 'public' AND pp.tablename = c.relname
                        AND pp.permissive = 'RESTRICTIVE' AND pp.qual LIKE '%eh_contador_restrito%');
  PERFORM ci.exige(faltando IS NULL, 'toda tabela com RLS tem política restritiva do contador (eh_contador_restrito) ou está na lista liberada ao contador' || coalesce(' (faltam: ' || faltando || ')', ''));

  SELECT string_agg(p.proname, ', ') INTO faltando
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.prosecdef AND pg_get_function_result(p.oid) <> 'trigger'
     AND has_function_privilege('authenticated', p.oid, 'execute')
     AND p.proname NOT IN ('current_tenant_id', 'current_motorista_id', 'has_role', 'eh_motorista_restrito',
                           'eh_saas_operador', 'eh_salao_restrito', 'onboarding_criar_espaco', 'eh_contador_restrito',
                           'contador_empresa_id', 'contador_edita_tributos', 'contador_meu_acesso',
                           'filial_irrestrita', 'pode_filial', 'eh_profissional_restrito')
     AND pg_get_functiondef(p.oid) NOT LIKE '%exige_nao_contador%'
     AND pg_get_functiondef(p.oid) NOT LIKE '%exige_contador_tributos%';
  PERFORM ci.exige(faltando IS NULL, 'toda função chamável tem a trava do contador (exige_nao_contador ou exige_contador_tributos) ou está na lista liberada' || coalesce(' (faltam: ' || faltando || ')', ''));

  -- comportamento
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM produtos') > 0, 'gestão enxerga os produtos');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM produtos') = 0, 'garçom não lê produtos');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM produtos') = 0, 'cozinha não lê produtos');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM clientes') > 0, 'gestão enxerga os clientes');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM clientes') = 0, 'garçom não lê clientes');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM pedidos') = 0, 'garçom não lê pedidos');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM contas_receber') = 0, 'cozinha não lê contas a receber');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM caixa_movimentos') = 0, 'garçom não lê o caixa');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM tef_transacoes') = 0, 'garçom não lê transações de cartão');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM cardapio_itens') > 0, 'garçom segue lendo o cardápio');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM mesas') > 0, 'garçom segue lendo as mesas');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM profiles WHERE id = auth.uid()') = 1, 'garçom lê o próprio perfil');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM filiais') > 0, 'garçom lê as filiais (sessão)');

  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO produtos (tenant_id, descricao) VALUES (%L, 'x')$c$, demo), 'garçom cria produto');
  PERFORM ci.exige(ci.contar(coz, 'WITH u AS (UPDATE produtos SET preco_venda = 1 RETURNING 1) SELECT count(*) FROM u') = 0, 'cozinha não altera preço (nenhuma linha)');
  PERFORM ci.exige(ci.contar(coz, 'WITH d AS (DELETE FROM clientes RETURNING 1) SELECT count(*) FROM d') = 0, 'cozinha não apaga clientes (nenhuma linha)');

  -- funções de venda, caixa e relatórios
  PERFORM ci.deve_falhar(gar, 'SELECT frente_caixa_atual()', 'garçom usa o caixa (função SQL)');
  PERFORM ci.deve_falhar(gar, 'SELECT relatorio_fechamento_operador(current_date, current_date)', 'garçom lê relatório de caixa (função SQL)');
  PERFORM ci.deve_falhar(gar, format($c$SELECT frente_venda(%L, '[]'::jsonb, 'dinheiro')$c$, gen_random_uuid()), 'garçom vende no PDV');
  PERFORM ci.deve_falhar(coz, format($c$SELECT baixar_conta('receber', %L, 10, 'dinheiro', current_date)$c$, gen_random_uuid()), 'cozinha baixa conta');
  -- a falha precisa ser a trava, e não um erro de argumento
  BEGIN
    PERFORM ci.entrar(gar);
    PERFORM public.frente_caixa_atual();
    PERFORM ci.sair();
    RAISE EXCEPTION 'FALHA: a trava do salão não bloqueou frente_caixa_atual';
  EXCEPTION WHEN OTHERS THEN
    PERFORM ci.sair();
    PERFORM ci.exige(SQLERRM LIKE '%não tem acesso a esta operação%', 'a recusa vem da trava do salão: ' || SQLERRM);
  END;

  -- quem acumula outro papel não fica restrito
  INSERT INTO auth.users (id, email) VALUES (gar_cx, 'garcom-caixa@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = gar_cx;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (gar_cx, demo, 'garcom'), (gar_cx, demo, 'vendedor');
  PERFORM ci.exige(ci.contar(gar_cx, 'SELECT count(*) FROM produtos') > 0, 'garçom que também é vendedor segue com o acesso de vendedor');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM produtos') > 0, 'vendedor segue lendo produtos');
  PERFORM ci.exige(NOT (SELECT eh_salao_restrito()), 'eh_salao_restrito é falso para quem não tem usuário logado');

  -- item de categoria desativada não pode ser lançado
  DECLARE
    cat_off uuid; item_off uuid; mesa_off uuid; cmd_off uuid;
  BEGIN
    INSERT INTO cardapio_categorias (tenant_id, nome, ativo) VALUES (demo, 'Fora do cardápio', false) RETURNING id INTO cat_off;
    INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco) VALUES (demo, cat_off, 'Prato fantasma', 10) RETURNING id INTO item_off;
    INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'categoria-off') RETURNING id INTO mesa_off;
    PERFORM ci.entrar(gar);
    cmd_off := restaurante_abrir_comanda(mesa_off, 1);
    PERFORM ci.sair();
    PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1)$c$, cmd_off, item_off), 'lançar item de categoria desativada');
    UPDATE cardapio_categorias SET ativo = true WHERE id = cat_off;
    PERFORM ci.entrar(gar);
    PERFORM restaurante_lancar_item(cmd_off, item_off, 1);
    PERFORM ci.sair();
    PERFORM ci.exige(true, 'com a categoria reativada o item pode ser lançado');
  END;
END $$;


-- 17. baixa parcial da comanda (alguém da mesa vai embora)
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  filial constant uuid := '33333333-3333-3333-3333-333333333333';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa    constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  cat uuid; it_a uuid; it_b uuid; it_c uuid; it_d uuid; it_e uuid; mesa uuid; cmd uuid; cmd2 uuid; cmd3 uuid; cx uuid; i_a uuid; i_b uuid; i_c uuid;
  r jsonb; itens jsonb; pg_total numeric; n_cmd bigint;
BEGIN
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Parcial') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Cerveja', 20, 'nenhuma') RETURNING id INTO it_a;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Porção', 12.5, 'nenhuma') RETURNING id INTO it_b;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Prato', 30, 'cozinha') RETURNING id INTO it_c;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Suco', 10.05, 'nenhuma') RETURNING id INTO it_d;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Rodízio', 50, 'nenhuma') RETURNING id INTO it_e;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'parcial-1') RETURNING id INTO mesa;
  SELECT id INTO cx FROM caixas WHERE tenant_id = demo AND filial_id = filial AND situacao = 'aberto' LIMIT 1;

  -- 4 pessoas, serviço 10%, couvert R$ 5; 3 cervejas (60) + 2 porções (25) = 85; couvert 20; serviço 8,50; conta 113,50
  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(mesa, 4, NULL, 10, 5);
  i_a := restaurante_lancar_item(cmd, it_a, 3);
  i_b := restaurante_lancar_item(cmd, it_b, 2);
  PERFORM restaurante_enviar_cozinha(cmd);
  PERFORM ci.sair();
  itens := jsonb_build_array(jsonb_build_object('id', i_a, 'quantidade', 1), jsonb_build_object('id', i_b));

  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"pix","valor":54.50}]'::jsonb, %L, %L::jsonb, 1)$c$, cmd, cx, itens), 'garçom faz baixa parcial');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"pix","valor":50}]'::jsonb, %L, %L::jsonb, 1)$c$, cmd, cx, itens), 'baixa por itens com valor que não confere');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"boleto","valor":54.50}]'::jsonb, %L, %L::jsonb, 1)$c$, cmd, cx, itens), 'boleto na baixa parcial');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"pix","valor":54.50}]'::jsonb, %L, %L::jsonb, 5)$c$, cmd, cx, itens), 'mais pessoas do que a mesa tem');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"pix","valor":54.50}]'::jsonb, %L, %L::jsonb, 1)$c$, cmd, cx, jsonb_build_array(jsonb_build_object('id', i_a, 'quantidade', 4))), 'mais unidades do que o item tem');

  -- item que ainda não foi entregue não se paga
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, 1, NULL, 10, 0);
  i_c := restaurante_lancar_item(cmd2, it_c, 1);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"pix","valor":33}]'::jsonb, %L, %L::jsonb)$c$, cmd2, cx, jsonb_build_array(jsonb_build_object('id', i_c))), 'pagar item ainda não entregue');
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_comanda(cmd2, 'teste da baixa parcial');
  PERFORM ci.sair();

  -- baixa por itens: 1 cerveja (20) + 2 porções (25) = 45; serviço 4,50; couvert de 1 pessoa 5 → 54,50
  PERFORM ci.entrar(cxa);
  r := restaurante_receber_parcial(cmd, '[{"forma":"pix","valor":54.50,"pagante":"Ana"}]'::jsonb, cx, itens, 1);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'recebido')::numeric = 54.5 AND (r ->> 'saldo')::numeric = 59, 'baixa por itens recebe 54,50 e deixa saldo de 59');
  PERFORM ci.exige((SELECT quantidade = 2 AND total = 40 AND pago_em IS NULL FROM comanda_itens WHERE id = i_a),
                   'as 2 cervejas restantes seguem na conta');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(total) = 20 AND bool_and(pagante = 'Ana') FROM comanda_itens WHERE comanda_id = cmd AND nome = 'Cerveja' AND pago_em IS NOT NULL),
                   'a cerveja paga vira uma linha própria, com quem pagou');
  PERFORM ci.exige((SELECT pago_em IS NOT NULL FROM comanda_itens WHERE id = i_b), 'a porção inteira ficou paga');
  PERFORM ci.exige((SELECT pessoas_pagas = 1 FROM comandas WHERE id = cmd), 'couvert da pessoa que saiu registrado');
  PERFORM ci.exige((SELECT count(*) = 1 AND bool_and(parcial) FROM comanda_pagamentos WHERE comanda_id = cmd), 'pagamento gravado como parcial');
  PERFORM ci.exige((SELECT sum(valor) = 54.5 FROM caixa_movimentos WHERE caixa_id = cx AND descricao = 'Comanda ' || (SELECT numero FROM comandas WHERE id = cmd) || ' (parcial)'),
                   'a baixa parcial entra no caixa');
  PERFORM ci.exige((SELECT count(*) = 3 FROM comanda_itens WHERE comanda_id = cmd AND situacao <> 'cancelado'), 'a comanda segue aberta com os itens');

  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"pix","valor":25}]'::jsonb, %L, %L::jsonb)$c$, cmd, cx, jsonb_build_array(jsonb_build_object('id', i_b))), 'pagar de novo um item já pago');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_cancelar_item(%L, 'não pode')$c$, i_b), 'cancelar item já pago');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_cancelar_comanda(%L, 'não pode')$c$, cmd), 'cancelar comanda que já recebeu');

  -- baixa por valor livre: 30 do saldo de 59; 40 passaria do que sobra (29)
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"dinheiro","valor":60}]'::jsonb, %L)$c$, cmd, cx), 'baixa por valor acima do saldo');
  PERFORM ci.entrar(cxa);
  r := restaurante_receber_parcial(cmd, '[{"forma":"dinheiro","valor":30,"pagante":"Beto"}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'saldo')::numeric = 29, 'baixa por valor deixa saldo de 29');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"dinheiro","valor":40}]'::jsonb, %L)$c$, cmd, cx), 'segunda baixa acima do saldo');

  -- o fechamento cobra só o saldo
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_fechar_comanda(%L, '[{"forma":"pix","valor":113.50}]'::jsonb, %L)$c$, cmd, cx), 'fechar cobrando a conta inteira de novo');
  PERFORM ci.entrar(cxa);
  r := restaurante_fechar_comanda(cmd, '[{"forma":"pix","valor":29}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 113.5 AND (r ->> 'recebido_antes')::numeric = 84.5 AND (r ->> 'restante')::numeric = 29,
                   'fechamento devolve total, recebido antes e saldo');
  SELECT sum(valor) INTO pg_total FROM comanda_pagamentos WHERE comanda_id = cmd;
  PERFORM ci.exige(pg_total = 113.5, 'a soma dos pagamentos fecha o total da conta');
  SELECT numero INTO n_cmd FROM comandas WHERE id = cmd;
  PERFORM ci.exige((SELECT sum(valor) = 113.5 FROM caixa_movimentos WHERE tipo = 'venda' AND descricao LIKE 'Comanda ' || n_cmd || '%'),
                   'o caixa recebeu a conta inteira, em partes');
  PERFORM ci.exige((SELECT situacao = 'fechada' AND total = 113.5 FROM comandas WHERE id = cmd), 'comanda fechada com o total cheio');

  -- conta toda paga em baixas: fechar sem novos pagamentos
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  PERFORM restaurante_lancar_item(cmd2, it_b, 2);
  PERFORM restaurante_enviar_cozinha(cmd2);
  PERFORM ci.sair();
  PERFORM ci.entrar(cxa);
  PERFORM restaurante_receber_parcial(cmd2, '[{"forma":"pix","valor":25}]'::jsonb, cx);
  r := restaurante_fechar_comanda(cmd2, '[]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'restante')::numeric = 0 AND (SELECT situacao = 'fechada' FROM comandas WHERE id = cmd2),
                   'conta já paga em baixas fecha sem novo pagamento');

  -- serviço acumulado: dois itens de 10,05 com 10% de serviço; a conta é 22,11 e as baixas somam 11,06 + 11,05
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, NULL, NULL, 10, 0);
  i_a := restaurante_lancar_item(cmd2, it_d, 1);
  i_b := restaurante_lancar_item(cmd2, it_d, 1);
  PERFORM restaurante_enviar_cozinha(cmd2);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_receber_parcial(%L, '[{"forma":"pix","valor":11.05}]'::jsonb, %L, %L::jsonb)$c$, cmd2, cx, jsonb_build_array(jsonb_build_object('id', i_a))), 'primeira baixa com o serviço arredondado errado');
  PERFORM ci.entrar(cxa);
  PERFORM restaurante_receber_parcial(cmd2, '[{"forma":"pix","valor":11.06}]'::jsonb, cx, jsonb_build_array(jsonb_build_object('id', i_a)));
  PERFORM restaurante_receber_parcial(cmd2, '[{"forma":"pix","valor":11.05}]'::jsonb, cx, jsonb_build_array(jsonb_build_object('id', i_b)));
  r := restaurante_fechar_comanda(cmd2, '[]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 22.11 AND (r ->> 'restante')::numeric = 0, 'as baixas por itens somam exatamente o total da conta');

  -- cancelar item depois de baixa por valor não pode deixar a conta abaixo do que já foi recebido
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  i_a := restaurante_lancar_item(cmd2, it_e, 1);
  i_b := restaurante_lancar_item(cmd2, it_e, 1);
  PERFORM restaurante_enviar_cozinha(cmd2);
  cmd3 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  i_c := restaurante_lancar_item(cmd3, it_e, 1);
  PERFORM restaurante_lancar_item(cmd3, it_e, 1);
  PERFORM restaurante_enviar_cozinha(cmd3);
  PERFORM ci.sair();
  PERFORM ci.entrar(cxa);
  PERFORM restaurante_receber_parcial(cmd2, '[{"forma":"dinheiro","valor":90}]'::jsonb, cx);
  PERFORM restaurante_receber_parcial(cmd3, '[{"forma":"dinheiro","valor":40}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_cancelar_item(%L, 'cancelar depois da baixa')$c$, i_a), 'cancelar item deixando a conta abaixo do recebido');
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_item(i_c, 'cancelar com folga no recebido');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelado' FROM comanda_itens WHERE id = i_c),
                   'cancelar item continua permitido quando a conta fica acima do recebido');
END $$;

-- 17b. crédito na conta e juntar contas
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  filial constant uuid := '33333333-3333-3333-3333-333333333333';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa    constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  cat uuid; it uuid; ma uuid; mb uuid; mc uuid; md uuid; me uuid; cx uuid; cx_f uuid;
  c1 uuid; c3 uuid; c4 uuid; c5 uuid; c6 uuid; c7 uuid; c8 uuid; r jsonb; n4 integer; i1 uuid;
BEGIN
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Credito CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Rodizio CI', 50, 'nenhuma') RETURNING id INTO it;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'cr-a') RETURNING id INTO ma;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'cr-b') RETURNING id INTO mb;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'cr-c') RETURNING id INTO mc;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'cr-d') RETURNING id INTO md;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'cr-e') RETURNING id INTO me;
  SELECT id INTO cx FROM caixas WHERE tenant_id = demo AND filial_id = filial AND situacao = 'aberto' LIMIT 1;

  -- crédito: só quem recebe; forma a prazo, valor zero e valor absurdo recusados
  PERFORM ci.entrar(gar);
  c1 := restaurante_abrir_comanda(ma, 2, NULL, 10, 0);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_creditar_comanda(%L, '[{"forma":"pix","valor":100}]'::jsonb, %L)$c$, c1, cx), 'garçom recebe crédito');
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_creditar_comanda(%L, '[{"forma":"pix","valor":100}]'::jsonb, %L)$c$, c1, cx), 'vendedor recebe crédito');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_creditar_comanda(%L, '[{"forma":"boleto","valor":100}]'::jsonb, %L)$c$, c1, cx), 'boleto como crédito');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_creditar_comanda(%L, '[{"forma":"pix","valor":0}]'::jsonb, %L)$c$, c1, cx), 'crédito de valor zero');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_creditar_comanda(%L, '[{"forma":"pix","valor":100001}]'::jsonb, %L)$c$, c1, cx), 'crédito acima do limite');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_creditar_comanda(%L, '[{"forma":"pix","valor":10}]'::jsonb, NULL)$c$, c1), 'crédito sem caixa');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_creditar_comanda(%L, '[{"forma":"pix","valor":10}]'::jsonb, %L)$c$, gen_random_uuid(), cx), 'crédito em comanda que não existe');
  PERFORM ci.entrar(cxa);
  PERFORM restaurante_creditar_comanda(c1, '[{"forma":"pix","valor":100,"pagante":"Ana"}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 1 AND bool_and(credito) AND sum(valor) = 100 FROM comanda_pagamentos WHERE comanda_id = c1), 'crédito gravado na comanda');
  PERFORM ci.exige((SELECT sum(valor) = 100 FROM caixa_movimentos WHERE caixa_id = cx AND descricao = 'Comanda ' || (SELECT numero FROM comandas WHERE id = c1) || ' (crédito)'), 'o crédito entra no caixa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_cancelar_comanda(%L, 'teste')$c$, c1), 'cancelar comanda com crédito recebido');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO comanda_pagamentos (tenant_id, comanda_id, forma, valor, credito) VALUES (%L, %L, 'pix', -5, true)$c$, demo, c1), 'devolução por escrita direta');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO comanda_pagamentos (tenant_id, comanda_id, forma, valor) VALUES (%L, %L, 'pix', -5)$c$, demo, c1), 'valor negativo fora de crédito');

  -- 1 rodízio de 50 + serviço 10% = 55; crédito 100; sobra 45
  PERFORM ci.entrar(gar);
  i1 := restaurante_lancar_item(c1, it, 1);
  PERFORM restaurante_enviar_cozinha(c1);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_fechar_comanda(%L, '[]'::jsonb, %L)$c$, c1, cx), 'fechar com crédito acima da conta sem devolver a sobra');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_devolver_credito(%L, 45, %L, 'sobra')$c$, c1, cx), 'caixa devolve crédito (só a gestão)');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_devolver_credito(%L, 45.01, %L, 'sobra')$c$, c1, cx), 'devolver mais do que a sobra');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_devolver_credito(%L, 45, %L, ' ')$c$, c1, cx), 'devolver sem motivo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_devolver_credito(%L, 0, %L, 'sobra')$c$, c1, cx), 'devolver zero');
  PERFORM ci.entrar(adm);
  PERFORM restaurante_devolver_credito(c1, 45, cx, 'cliente pediu a sobra');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT sum(valor) = 55 FROM comanda_pagamentos WHERE comanda_id = c1), 'devolução reduz o que foi recebido');
  PERFORM ci.exige((SELECT sum(valor) = 45 FROM caixa_movimentos WHERE caixa_id = cx AND tipo = 'saida' AND descricao = 'Devolução de crédito - comanda ' || (SELECT numero FROM comandas WHERE id = c1)), 'a devolução sai do caixa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_devolver_credito(%L, 1, %L, 'de novo')$c$, c1, cx), 'devolver de novo sem sobra');
  PERFORM ci.entrar(cxa);
  r := restaurante_fechar_comanda(c1, '[]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 55 AND (r ->> 'restante')::numeric = 0, 'conta paga só com o crédito fecha sem novo recebimento');
  PERFORM ci.exige((SELECT situacao = 'fechada' FROM comandas WHERE id = c1), 'comanda fechada');

  -- crédito inteiro devolvido libera o cancelamento
  PERFORM ci.entrar(gar);
  c3 := restaurante_abrir_comanda(mc, 1, NULL, 10, 0);
  PERFORM ci.sair();
  PERFORM ci.entrar(cxa);
  PERFORM restaurante_creditar_comanda(c3, '[{"forma":"dinheiro","valor":30}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.entrar(adm);
  PERFORM restaurante_devolver_credito(c3, 30, cx, 'desistiu');
  PERFORM restaurante_cancelar_comanda(c3, 'cliente desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM comandas WHERE id = c3), 'comanda com crédito devolvido pode ser cancelada');

  -- juntar contas
  PERFORM ci.entrar(gar);
  c4 := restaurante_abrir_comanda(mb, 2, NULL, 10, 0);
  PERFORM restaurante_lancar_item(c4, it, 1);
  c5 := restaurante_abrir_comanda(md, 3, NULL, 10, 0);
  PERFORM restaurante_lancar_item(c5, it, 2);
  c6 := restaurante_abrir_comanda(me, 1, NULL, 15, 0);
  PERFORM restaurante_lancar_item(c6, it, 1);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[%L]::uuid[])$c$, c4, c5), 'vendedor junta contas');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[]::uuid[])$c$, c4), 'juntar sem escolher contas');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[%L]::uuid[])$c$, c4, c4), 'juntar a conta com ela mesma');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[%L]::uuid[])$c$, c4, gen_random_uuid()), 'juntar conta que não existe');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[%L]::uuid[])$c$, c4, c1), 'juntar conta já fechada');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[%L]::uuid[])$c$, c4, c6), 'juntar contas com serviço diferente sem autorização');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[%L]::uuid[], true)$c$, c4, c6), 'garçom autoriza usar o serviço da conta de destino');

  PERFORM ci.entrar(gar);
  r := restaurante_juntar_comandas(c4, ARRAY[c5]);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'unidas')::int = 1 AND (r ->> 'itens')::int = 1, 'junção devolve o resumo');
  PERFORM ci.exige((SELECT count(*) = 2 FROM comanda_itens WHERE comanda_id = c4 AND situacao <> 'cancelado'), 'itens da origem passaram para o destino');
  PERFORM ci.exige((SELECT sum(quantidade) = 3 FROM comanda_itens WHERE comanda_id = c4 AND situacao <> 'cancelado'), 'as quantidades foram preservadas');
  PERFORM ci.exige((SELECT count(*) = 0 FROM comanda_itens WHERE comanda_id = c5), 'a origem ficou sem itens');
  PERFORM ci.exige((SELECT pessoas = 5 FROM comandas WHERE id = c4), 'pessoas somadas');
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND unida_em_id = c4 FROM comandas WHERE id = c5), 'origem marcada como unida');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_abrir_comanda(md, 1, NULL, 10, 0);
  PERFORM ci.sair();
  PERFORM ci.exige(true, 'a mesa da conta unida fica livre');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_juntar_comandas(%L, ARRAY[%L]::uuid[])$c$, c4, c5), 'juntar conta já unida');

  -- a gestão autoriza o serviço do destino; o crédito da origem acompanha
  PERFORM ci.entrar(cxa);
  PERFORM restaurante_creditar_comanda(c6, '[{"forma":"pix","valor":20}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.entrar(adm);
  r := restaurante_juntar_comandas(c4, ARRAY[c6], true);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'taxas_do_destino')::boolean AND (r ->> 'pagamentos')::int = 1, 'gestão junta contas com serviço diferente');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(valor) = 20 FROM comanda_pagamentos WHERE comanda_id = c4), 'o crédito da conta de origem passou para o destino');
  PERFORM ci.exige((SELECT pessoas = 6 FROM comandas WHERE id = c4), 'pessoas somadas na segunda junção');
END $$;

-- 17c. balança: item por peso, tara e teto do buffet livre
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  filial constant uuid := '33333333-3333-3333-3333-333333333333';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz    constant uuid := 'a0000000-0000-0000-0000-000000000007';
  cxa    constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  outro_tenant uuid; cat uuid; kg uuid; un uuid; prato uuid; vasi uuid; inativa uuid; tara_alheia uuid;
  cmd uuid; cx uuid; r jsonb; it record;
BEGIN
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;
  SELECT id INTO cx FROM caixas WHERE tenant_id = demo AND filial_id = filial AND situacao = 'aberto' LIMIT 1;

  -- taras: a gestão cadastra, a operação lê
  PERFORM ci.entrar(adm);
  INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (demo, 'Prato CI', 350) RETURNING id INTO prato;
  INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (demo, 'Vasilhame CI', 120) RETURNING id INTO vasi;
  INSERT INTO restaurante_taras (tenant_id, nome, peso_g, ativo) VALUES (demo, 'Antiga CI', 200, false) RETURNING id INTO inativa;
  PERFORM ci.sair();
  INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (outro_tenant, 'Prato alheio', 300) RETURNING id INTO tara_alheia;
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM restaurante_taras') = 3, 'garçom lê só as taras da própria empresa');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM restaurante_taras') = 3, 'cozinha lê as taras');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM restaurante_taras') = 0, 'vendedor não lê as taras');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (%L, 'Outra', 100)$c$, demo), 'garçom cadastra tara');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (%L, ' prato ci ', 100)$c$, demo), 'tara repetida');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (%L, 'Zero', 0)$c$, demo), 'tara de peso zero');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (%L, 'Gigante', 5001)$c$, demo), 'tara acima de 5 kg');

  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Balanca CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao, venda_por_peso, tara_id)
    VALUES (demo, cat, 'Buffet por kg CI', 60, 'nenhuma', true, prato) RETURNING id INTO kg;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Suco CI', 8, 'nenhuma') RETURNING id INTO un;
  PERFORM ci.deve_falhar_dono(format($c$UPDATE cardapio_itens SET tara_id = %L WHERE id = %L$c$, prato, un), 'tara padrão em item que não é por peso');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE cardapio_itens SET tara_id = %L WHERE id = %L$c$, tara_alheia, kg), 'tara de outra empresa no item');

  -- cálculo
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_pesagem_calcular(%L, 850, %L)$c$, kg, prato), 'vendedor pesa');
  PERFORM ci.entrar(gar);
  r := restaurante_pesagem_calcular(kg, 850, prato);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'liquido_g')::int = 500 AND (r ->> 'valor')::numeric = 30 AND NOT (r ->> 'teto_aplicado')::boolean, 'prato de 850 g com tara de 350 g custa 500 g x R$ 60/kg');
  PERFORM ci.entrar(gar);
  r := restaurante_pesagem_calcular(kg, 850, NULL);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'tara_g')::int = 0 AND (r ->> 'valor')::numeric = 51, 'sem tara cobra o peso bruto');
  UPDATE cardapio_itens SET preco = 59.90 WHERE id = kg;
  PERFORM ci.entrar(gar);
  PERFORM ci.exige((restaurante_pesagem_calcular(kg, 683, prato) ->> 'valor')::numeric = 19.95, 'arredondamento: 333 g x 59,90 = 19,95');
  PERFORM ci.exige((restaurante_pesagem_calcular(kg, 685, prato) ->> 'valor')::numeric = 20.07, 'arredondamento: 335 g x 59,90 = 20,07');
  PERFORM ci.sair();
  UPDATE cardapio_itens SET preco = 60 WHERE id = kg;
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_pesagem_calcular(%L, 350, %L)$c$, kg, prato), 'peso igual à tara');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_pesagem_calcular(%L, 300, %L)$c$, kg, prato), 'peso menor que a tara');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_pesagem_calcular(%L, 0, NULL)$c$, kg), 'peso zero');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_pesagem_calcular(%L, 30001, NULL)$c$, kg), 'peso acima de 30 kg');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_pesagem_calcular(%L, 500, %L)$c$, kg, inativa), 'tara inativa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_pesagem_calcular(%L, 500, %L)$c$, kg, tara_alheia), 'tara de outra empresa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_pesagem_calcular(%L, 500, NULL)$c$, un), 'pesar item que não é por peso');

  -- lançar: só pela balança
  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(NULL, NULL, 'Balança CI', 0, 0);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1)$c$, cmd, kg), 'lançar item por peso pelo lançamento comum');
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_lancar_pesagem(%L, %L, 850, %L)$c$, cmd, kg, prato), 'vendedor lança pesagem');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO comanda_itens (tenant_id, comanda_id, cardapio_item_id, nome, estacao, quantidade, preco_unitario, total) VALUES (%L, %L, %L, 'x', 'nenhuma', 1, 60, 60)$c$, demo, cmd, kg), 'inserir item por peso direto no banco');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_pesagem(%L, %L, 850, %L)$c$, gen_random_uuid(), kg, prato), 'pesagem em comanda que não existe');
  PERFORM ci.entrar(gar);
  r := restaurante_lancar_pesagem(cmd, kg, 850, prato, 'sem pimenta');
  PERFORM ci.sair();
  SELECT * INTO it FROM comanda_itens WHERE id = (r ->> 'item_id')::uuid;
  PERFORM ci.exige(it.quantidade = 0.5 AND it.total = 30 AND it.preco_unitario = 60 AND it.situacao = 'entregue', 'pesagem vira item entregue com o peso líquido e o valor');
  PERFORM ci.exige(it.peso_bruto_g = 850 AND it.tara_g = 350 AND it.peso_liquido_g = 500 AND NOT it.teto_buffet, 'pesagem fica gravada no item');
  PERFORM ci.exige(it.observacao LIKE '%Prato CI%' AND it.observacao LIKE '%sem pimenta%', 'observação traz a tara e o pedido');

  -- buffet livre
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_config (tenant_id, buffet_livre_ativo) VALUES (%L, true) ON CONFLICT (tenant_id) DO UPDATE SET buffet_livre_ativo = true$c$, demo), 'buffet livre ativo sem preço');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO restaurante_config (tenant_id, buffet_livre_ativo, buffet_livre_preco) VALUES (%L, true, 40)$c$, demo), 'garçom configura o buffet livre');
  PERFORM ci.entrar(adm);
  INSERT INTO restaurante_config (tenant_id, buffet_livre_ativo, buffet_livre_preco) VALUES (demo, true, 40)
    ON CONFLICT (tenant_id) DO UPDATE SET buffet_livre_ativo = true, buffet_livre_preco = 40;
  PERFORM ci.sair();
  PERFORM ci.entrar(gar);
  r := restaurante_balanca_config();
  PERFORM ci.exige((r ->> 'buffet_livre_ativo')::boolean AND (r ->> 'buffet_livre_preco')::numeric = 40, 'operação lê o buffet livre configurado');
  r := restaurante_pesagem_calcular(kg, 1350, prato);
  PERFORM ci.exige((r ->> 'valor_sem_teto')::numeric = 60 AND (r ->> 'valor')::numeric = 40 AND (r ->> 'teto_aplicado')::boolean, 'prato acima do buffet livre cobra o buffet livre');
  r := restaurante_pesagem_calcular(kg, 850, prato);
  PERFORM ci.exige((r ->> 'valor')::numeric = 30 AND NOT (r ->> 'teto_aplicado')::boolean, 'prato abaixo do buffet livre cobra o peso');
  r := restaurante_pesagem_calcular(kg, 1017, prato);
  PERFORM ci.exige((r ->> 'valor_sem_teto')::numeric = 40.02 AND (r ->> 'valor')::numeric = 40 AND (r ->> 'teto_aplicado')::boolean, 'um centavo acima do buffet livre já aplica o teto');
  r := restaurante_lancar_pesagem(cmd, kg, 1350, prato);
  PERFORM ci.sair();
  SELECT * INTO it FROM comanda_itens WHERE id = (r ->> 'item_id')::uuid;
  PERFORM ci.exige(it.total = 40 AND it.teto_buffet AND it.quantidade = 1 AND it.observacao LIKE '%limitado ao buffet livre%', 'item com teto guarda o valor do buffet livre e a marca');
  PERFORM ci.deve_falhar(vend, 'SELECT restaurante_balanca_config()', 'vendedor lê a configuração da balança');

  -- desligado: volta ao peso
  UPDATE restaurante_config SET buffet_livre_ativo = false WHERE tenant_id = demo;
  PERFORM ci.entrar(gar);
  PERFORM ci.exige((restaurante_pesagem_calcular(kg, 1350, prato) ->> 'valor')::numeric = 60, 'buffet livre desligado não limita');
  PERFORM ci.exige((restaurante_balanca_config() ->> 'buffet_livre_preco') IS NULL, 'configuração desligada não expõe o preço');
  PERFORM ci.sair();

  -- fecha a conta com os dois pratos: 30 + 40 = 70
  PERFORM ci.entrar(cxa);
  r := restaurante_fechar_comanda(cmd, '[{"forma":"pix","valor":70}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 70, 'a conta soma o valor das pesagens (sem recalcular pelo peso)');

  -- os testes seguintes partem de uma empresa sem configuração do restaurante
  DELETE FROM restaurante_config WHERE tenant_id = demo;
END $$;

-- 17d. pedidos externos (caixa de entrada do iFood)
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  outro_tenant uuid; cat uuid; burger uuid; suco uuid; pesado uuid; alheio uuid; ext uuid; ext2 uuid; ext3 uuid; ext4 uuid; cmd uuid;
  ped jsonb; r jsonb; c record; msg text;
BEGIN
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Externo CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Burger Externo CI', 30, 'cozinha') RETURNING id INTO burger;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao, codigo_externo, preco_ifood) VALUES (demo, cat, 'Suco Externo CI', 8, 'nenhuma', 'IF-SUCO', 9.5) RETURNING id INTO suco;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao, venda_por_peso) VALUES (demo, cat, 'Kg Externo CI', 60, 'nenhuma', true) RETURNING id INTO pesado;
  INSERT INTO cardapio_itens (tenant_id, nome, preco, estacao) VALUES (outro_tenant, 'Item alheio CI', 5, 'cozinha') RETURNING id INTO alheio;
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_itens (tenant_id, nome, preco, estacao, codigo_externo) VALUES (%L, 'Duplicado', 1, 'cozinha', 'IF-SUCO')$c$, demo), 'código do canal repetido na mesma empresa');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE cardapio_itens SET preco_ifood = -1 WHERE id = %L$c$, burger), 'preço do iFood negativo');

  ped := '{"numero":"4321","tipo":"entrega","cliente":{"nome":"Marina","telefone":"11988887777"},
           "endereco":{"texto":"Rua das Flores, 100","bairro":"Centro","referencia":"portão azul"},
           "itens":[{"codigo":"IF-BURGER","nome":"X-Burger","quantidade":2,"preco":30,"observacao":"sem cebola",
                     "adicionais":[{"nome":"Bacon","preco":4},{"nome":"Queijo","preco":2.5}]},
                    {"codigo":"IF-SUCO","nome":"Suco de laranja","quantidade":1,"preco":9.5}],
           "taxa_entrega":6,"desconto":5,"total":88,"pagamento":"pago_online","observacao":"tocar a campainha"}'::jsonb;

  -- só o servidor recebe
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_receber(%L, 'ifood', 'P-1', %L::jsonb)$c$, demo, ped), 'garçom injeta pedido externo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT restaurante_externo_receber(%L, 'ifood', 'P-1', %L::jsonb)$c$, demo, ped), 'gestão injeta pedido externo');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT restaurante_externo_receber(%L, 'ifood', 'P-1', %L::jsonb)$c$, demo, ped), 'anônimo injeta pedido externo');
  PERFORM ci.deve_falhar_dono(format($c$SELECT restaurante_externo_receber(%L, 'rappi', 'P-1', %L::jsonb)$c$, demo, ped), 'canal inventado');
  PERFORM ci.deve_falhar_dono(format($c$SELECT restaurante_externo_receber(%L, 'ifood', 'P-1', '{"itens":[]}'::jsonb)$c$, demo), 'pedido sem itens');
  PERFORM ci.deve_falhar_dono(format($c$SELECT restaurante_externo_receber(%L, 'ifood', 'P-1', '{"itens":[{"codigo":"a","nome":"x","quantidade":0,"preco":1}]}'::jsonb)$c$, demo), 'item com quantidade zero');
  PERFORM ci.deve_falhar_dono(format($c$SELECT restaurante_externo_receber(%L, 'ifood', 'P-1', '{"tipo":"voando","itens":[{"codigo":"a","nome":"x","quantidade":1,"preco":1}]}'::jsonb)$c$, demo), 'tipo de pedido inventado');
  PERFORM ci.deve_falhar_dono(format($c$SELECT restaurante_externo_receber(%L, 'ifood', 'P-1', %L::jsonb)$c$, gen_random_uuid(), ped), 'pedido para empresa que não existe');

  ext := restaurante_externo_receber(demo, 'ifood', 'P-1', ped);
  PERFORM ci.exige(restaurante_externo_receber(demo, 'ifood', 'P-1', ped) = ext, 'pedido repetido do canal devolve o mesmo registro');
  PERFORM ci.exige((SELECT count(*) = 1 FROM restaurante_pedidos_externos WHERE tenant_id = demo AND codigo_externo = 'P-1'), 'pedido repetido não duplica');
  PERFORM restaurante_externo_receber(outro_tenant, 'ifood', 'P-ALHEIO', ped);
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM restaurante_pedidos_externos') = 1, 'garçom vê só os pedidos da própria empresa');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM restaurante_pedidos_externos') = 0, 'vendedor não vê pedidos externos');
  PERFORM ci.entrar(gar);
  BEGIN
    UPDATE restaurante_pedidos_externos SET situacao = 'aceito', decidido_em = now() WHERE id = ext;
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'recebido' FROM restaurante_pedidos_externos WHERE id = ext), 'decidir pedido por escrita direta não altera nada');

  -- aceitar
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_externo_aceitar(%L)$c$, ext), 'vendedor aceita pedido externo');
  PERFORM ci.entrar(gar);
  BEGIN
    PERFORM restaurante_externo_aceitar(ext);
    msg := NULL;
  EXCEPTION WHEN OTHERS THEN msg := SQLERRM;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige(msg LIKE '%X-Burger%' AND msg NOT LIKE '%Suco de laranja%', 'aceitar sem correspondência lista só o item que falta');
  PERFORM ci.exige((SELECT situacao = 'recebido' FROM restaurante_pedidos_externos WHERE id = ext), 'pedido segue na caixa de entrada após o erro');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_aceitar(%L, %L::jsonb)$c$, ext, jsonb_build_object('IF-BURGER', alheio)), 'mapear para item de outra empresa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_aceitar(%L, %L::jsonb)$c$, ext, jsonb_build_object('IF-BURGER', pesado)), 'mapear para item vendido por peso');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_aceitar(%L, '{"IF-BURGER":"nao-e-uuid"}'::jsonb)$c$, ext), 'mapeamento com id inválido');

  PERFORM ci.entrar(gar);
  cmd := restaurante_externo_aceitar(ext, jsonb_build_object('IF-BURGER', burger));
  PERFORM ci.sair();
  SELECT * INTO c FROM comandas WHERE id = cmd;
  PERFORM ci.exige(c.tipo = 'delivery' AND c.canal = 'ifood' AND c.codigo_externo = 'P-1' AND c.entrega_situacao = 'aguardando', 'aceitar abre o delivery do canal');
  PERFORM ci.exige(c.entrega_pagamento = 'pago_online' AND c.entrega_bairro = 'Centro' AND c.cliente_nome = 'Marina', 'dados da entrega e do pagamento');
  PERFORM ci.exige(c.observacao LIKE '%Pedido iFood 4321%' AND c.observacao LIKE '%Desconto%5,00%' OR c.observacao LIKE '%Desconto%5.00%', 'desconto e total do canal anotados');
  -- 2 x (30 + 4 + 2,5) = 73 ; suco 9,50 ; taxa 6 => 88,50 (o canal informou 88 com R$ 5 de desconto: a diferença fica anotada)
  PERFORM ci.exige((SELECT sum(total) = 88.5 FROM comanda_itens WHERE comanda_id = cmd AND situacao <> 'cancelado'), 'itens saem pelo preço do pedido, com adicionais e taxa');
  PERFORM ci.exige((SELECT preco_unitario = 36.5 AND quantidade = 2 AND observacao = 'sem cebola' AND jsonb_array_length(opcoes) = 2 FROM comanda_itens WHERE comanda_id = cmd AND nome = 'Burger Externo CI'), 'adicionais viram opções do item');
  PERFORM ci.exige((SELECT situacao = 'enviado' FROM comanda_itens WHERE comanda_id = cmd AND nome = 'Burger Externo CI'), 'item de cozinha vai para a fila');
  PERFORM ci.exige((SELECT situacao = 'entregue' FROM comanda_itens WHERE comanda_id = cmd AND nome = 'Suco Externo CI'), 'item pronto para servir já sai entregue');
  PERFORM ci.exige((SELECT codigo_externo = 'IF-BURGER' FROM cardapio_itens WHERE id = burger), 'o mapeamento escolhido fica guardado no item');
  PERFORM ci.exige((SELECT situacao = 'aceito' AND comanda_id = cmd FROM restaurante_pedidos_externos WHERE id = ext), 'pedido marcado como aceito e ligado à comanda');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_aceitar(%L)$c$, ext), 'aceitar o mesmo pedido de novo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_recusar(%L, 'tarde demais')$c$, ext), 'recusar pedido já aceito');

  -- retirada (sem endereço), telefone mascarado e reconhecimento pelo código guardado
  ext2 := restaurante_externo_receber(demo, 'ifood', 'P-2',
    '{"tipo":"retirada","cliente":{"nome":"","telefone":"0800"},"itens":[{"codigo":"IF-BURGER","nome":"X-Burger","quantidade":1,"preco":30}],"pagamento":"inventado"}'::jsonb);
  PERFORM ci.entrar(gar);
  cmd := restaurante_externo_aceitar(ext2);
  PERFORM ci.sair();
  SELECT * INTO c FROM comandas WHERE id = cmd;
  PERFORM ci.exige(c.entrega_endereco LIKE 'Retirada no balcão%' AND c.entrega_telefone IS NULL AND c.cliente_nome = 'Cliente iFood' AND c.entrega_pagamento IS NULL,
                   'retirada: endereço padrão, telefone mascarado ignorado, nome e pagamento padrão');
  PERFORM ci.exige((SELECT sum(total) = 30 FROM comanda_itens WHERE comanda_id = cmd), 'item reconhecido pelo código já guardado, sem taxa');

  -- entrega sem endereço é recusada pelo banco; recusa com motivo
  ext3 := restaurante_externo_receber(demo, 'ifood', 'P-3',
    '{"tipo":"entrega","cliente":{"nome":"Zé"},"itens":[{"codigo":"IF-SUCO","nome":"Suco","quantidade":1,"preco":9.5}]}'::jsonb);
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_aceitar(%L)$c$, ext3), 'aceitar entrega sem endereço');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_recusar(%L, 'x')$c$, ext3), 'recusar sem motivo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_externo_recusar(%L, 'sem estoque')$c$, ext3), 'vendedor recusa pedido');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_externo_recusar(ext3, 'sem estoque');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'recusado' AND motivo = 'sem estoque' AND decidido_em IS NOT NULL FROM restaurante_pedidos_externos WHERE id = ext3), 'pedido recusado com motivo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_externo_aceitar(%L)$c$, ext3), 'aceitar pedido recusado');

  -- o mesmo código do canal não vira duas comandas
  ext4 := restaurante_externo_receber(demo, 'ifood', 'P-1', ped);
  PERFORM ci.exige(ext4 = ext AND (SELECT count(*) = 1 FROM comandas WHERE tenant_id = demo AND canal = 'ifood' AND codigo_externo = 'P-1'), 'pedido reenviado depois de aceito não cria outra comanda');
END $$;

-- 17e. senha do pedido de balcão
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz    constant uuid := 'a0000000-0000-0000-0000-000000000007';
  cat uuid; lanche uuid; mesa uuid; c1 uuid; c2 uuid; c3 uuid; cm uuid; r jsonb; i1 uuid;
BEGIN
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Senha CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Lanche Senha CI', 20, 'cozinha') RETURNING id INTO lanche;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'senha-1') RETURNING id INTO mesa;

  PERFORM ci.entrar(gar);
  c1 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  c2 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  c3 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  cm := restaurante_abrir_comanda(mesa, 2, NULL, 10, 0);
  PERFORM ci.sair();

  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_emitir_senha(%L)$c$, c1), 'senha para comanda sem itens');
  PERFORM ci.entrar(gar);
  i1 := restaurante_lancar_item(c1, lanche, 2);
  PERFORM restaurante_lancar_item(c2, lanche, 1);
  PERFORM restaurante_lancar_item(c3, lanche, 1);
  PERFORM restaurante_lancar_item(cm, lanche, 1);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_emitir_senha(%L)$c$, c1), 'vendedor emite senha');
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_emitir_senha(%L)$c$, c1), 'cozinha emite senha');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_emitir_senha(%L)$c$, cm), 'senha para comanda de mesa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_emitir_senha(%L)$c$, gen_random_uuid()), 'senha para comanda que não existe');

  PERFORM ci.entrar(gar);
  r := restaurante_emitir_senha(c1);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'senha')::int >= 1 AND (r ->> 'enviados')::int = 1 AND (r ->> 'nova')::boolean, 'emitir a senha atribui o número e envia o pedido');
  PERFORM ci.exige((SELECT situacao = 'enviado' FROM comanda_itens WHERE id = i1), 'o item foi para a fila da produção');
  PERFORM ci.entrar(gar);
  PERFORM ci.exige((restaurante_emitir_senha(c1) ->> 'senha')::int = (r ->> 'senha')::int, 'reemitir devolve a mesma senha');
  PERFORM ci.exige(NOT (restaurante_emitir_senha(c1) ->> 'nova')::boolean, 'reemitir não é senha nova');
  r := restaurante_emitir_senha(c2);
  PERFORM ci.exige((r ->> 'senha')::int = (SELECT senha + 1 FROM comandas WHERE id = c1), 'a senha seguinte é sequencial');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT senha_data = (now() AT TIME ZONE 'America/Sao_Paulo')::date FROM comandas WHERE id = c1), 'a senha vale para o dia de hoje');

  -- o contador do dia nunca repete, mesmo após comanda cancelada
  PERFORM ci.entrar(gar);
  r := restaurante_emitir_senha(c3);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'senha')::int = (SELECT senha + 2 FROM comandas WHERE id = c1), 'terceira senha do dia');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE comandas SET senha = (SELECT senha FROM comandas WHERE id = %L), senha_data = (SELECT senha_data FROM comandas WHERE id = %L) WHERE id = %L$c$, c1, c1, c2), 'duas comandas com a mesma senha no dia');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE comandas SET senha = 7 WHERE id = %L$c$, cm), 'senha sem data');
  PERFORM ci.deve_falhar(gar, 'SELECT count(*) FROM restaurante_senhas_contador', 'o contador de senhas lido pelo cliente');
END $$;

-- 17f. vários cardápios
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  outro_tenant uuid; principal uuid; jantar uuid; inativo uuid; alheio uuid; cat uuid; it_a uuid; it_b uuid; it_c uuid; op uuid; grp uuid;
  cmd uuid; i1 uuid; i2 uuid;
BEGIN
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;

  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO cardapios (tenant_id, nome) VALUES (%L, 'Do garçom')$c$, demo), 'garçom cria cardápio');
  PERFORM ci.entrar(adm);
  INSERT INTO cardapios (tenant_id, nome, padrao, ordem) VALUES (demo, 'Principal CI', true, 0) RETURNING id INTO principal;
  INSERT INTO cardapios (tenant_id, nome, ordem, uso_ifood, hora_inicio, hora_fim) VALUES (demo, 'Jantar CI', 1, true, '18:00', '23:30') RETURNING id INTO jantar;
  INSERT INTO cardapios (tenant_id, nome, ativo) VALUES (demo, 'Parado CI', false) RETURNING id INTO inativo;
  PERFORM ci.sair();
  INSERT INTO cardapios (tenant_id, nome, padrao) VALUES (outro_tenant, 'Principal alheio', true) RETURNING id INTO alheio;
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapios (tenant_id, nome, padrao) VALUES (%L, 'Outro padrão', true)$c$, demo), 'dois cardápios padrão na mesma empresa');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapios (tenant_id, nome) VALUES (%L, ' principal ci ')$c$, demo), 'nome de cardápio repetido');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapios (tenant_id, nome, hora_inicio) VALUES (%L, 'Meio horário', '10:00')$c$, demo), 'horário com só o início');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM cardapios') = 3, 'garçom lê só os cardápios da própria empresa');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM cardapios') = 0, 'vendedor não lê cardápios');

  -- item novo entra no cardápio padrão sozinho
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Varios CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Prato A CI', 40, 'nenhuma') RETURNING id INTO it_a;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Prato B CI', 25, 'nenhuma') RETURNING id INTO it_b;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao, interno, ativo) VALUES (demo, cat, 'Interno CI', 1, 'nenhuma', true, false) RETURNING id INTO it_c;
  PERFORM ci.exige((SELECT count(*) = 2 FROM cardapio_cardapio_itens WHERE cardapio_id = principal AND item_id IN (it_a, it_b)), 'item novo entra no cardápio padrão');
  PERFORM ci.exige((SELECT count(*) = 0 FROM cardapio_cardapio_itens WHERE item_id = it_c), 'item interno não entra em cardápio');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_cardapio_itens (tenant_id, cardapio_id, item_id) VALUES (%L, %L, %L)$c$, demo, alheio, it_a), 'item ligado a cardápio de outra empresa');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_cardapio_itens (tenant_id, cardapio_id, item_id, preco) VALUES (%L, %L, %L, -1)$c$, demo, jantar, it_a), 'preço negativo no cardápio');

  -- o jantar vende só o prato A, por 50 (base 40)
  INSERT INTO cardapio_cardapio_itens (tenant_id, cardapio_id, item_id, preco, ordem) VALUES (demo, jantar, it_a, 50, 1);
  INSERT INTO cardapio_cardapio_itens (tenant_id, cardapio_id, item_id) VALUES (demo, inativo, it_b);
  INSERT INTO cardapio_grupos (tenant_id, item_id, nome) VALUES (demo, it_a, 'Molho CI') RETURNING id INTO grp;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, grp, 'Extra', 3) RETURNING id INTO op;

  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_lancar_item_no_cardapio(%L, %L, 1, %L)$c$, cmd, it_a, jantar), 'vendedor lança item por cardápio');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item_no_cardapio(%L, %L, 1, NULL)$c$, cmd, it_a), 'lançar sem escolher o cardápio');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item_no_cardapio(%L, %L, 1, %L)$c$, cmd, it_b, jantar), 'item que não está no cardápio escolhido');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item_no_cardapio(%L, %L, 1, %L)$c$, cmd, it_b, inativo), 'lançar por cardápio inativo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item_no_cardapio(%L, %L, 1, %L)$c$, cmd, it_a, alheio), 'lançar por cardápio de outra empresa');
  PERFORM ci.entrar(gar);
  i1 := restaurante_lancar_item_no_cardapio(cmd, it_a, 2, jantar, ARRAY[op], 'sem sal');
  i2 := restaurante_lancar_item_no_cardapio(cmd, it_a, 1, principal);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT preco_unitario = 53 AND total = 106 AND observacao = 'sem sal' FROM comanda_itens WHERE id = i1), 'jantar cobra o preço do cardápio mais a opção');
  PERFORM ci.exige((SELECT preco_unitario = 40 AND total = 40 FROM comanda_itens WHERE id = i2), 'cardápio sem preço próprio cobra o preço base');
  UPDATE cardapio_itens SET preco = 45 WHERE id = it_a;
  PERFORM ci.exige((SELECT preco_unitario = 53 FROM comanda_itens WHERE id = i1), 'mudar o preço depois não altera o item já lançado');

END $$;

-- 17g. chamar o garçom pelo QR da mesa
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz    constant uuid := 'a0000000-0000-0000-0000-000000000007';
  outro_tenant uuid; emp record; mesa uuid; mesa_off uuid; mesa_alheia uuid; m_conta uuid; m_agua uuid; r jsonb; r2 jsonb; ch uuid;
BEGIN
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;
  SELECT id, slug, nome_fantasia, ativo INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET slug = 'chamar-ci', ativo = true WHERE id = emp.id;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'ch-1') RETURNING id INTO mesa;
  INSERT INTO mesas (tenant_id, numero, ativa) VALUES (demo, 'ch-off', false) RETURNING id INTO mesa_off;
  INSERT INTO mesas (tenant_id, numero) VALUES (outro_tenant, 'ch-alheia') RETURNING id INTO mesa_alheia;

  -- desligado por padrão
  PERFORM ci.entrar(NULL);
  PERFORM ci.exige(restaurante_chamar_info('chamar-ci', mesa) IS NULL, 'chamar garçom desligado não mostra a página');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(NULL, format($c$SELECT restaurante_chamar_garcom('chamar-ci', %L)$c$, mesa), 'chamar com o recurso desligado');

  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO restaurante_config (tenant_id, chamar_garcom) VALUES (%L, true)$c$, demo), 'garçom liga o chamar garçom');
  PERFORM ci.entrar(adm);
  INSERT INTO restaurante_config (tenant_id, chamar_garcom) VALUES (demo, true)
    ON CONFLICT (tenant_id) DO UPDATE SET chamar_garcom = true;
  INSERT INTO restaurante_chamados_motivos (tenant_id, nome, ordem) VALUES (demo, 'Pedir a conta CI', 2) RETURNING id INTO m_conta;
  INSERT INTO restaurante_chamados_motivos (tenant_id, nome, ordem) VALUES (demo, 'Pedir água CI', 1) RETURNING id INTO m_agua;
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO restaurante_chamados_motivos (tenant_id, nome) VALUES (%L, 'Do garçom')$c$, demo), 'garçom cadastra motivo');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_chamados_motivos (tenant_id, nome) VALUES (%L, ' pedir a conta ci ')$c$, demo), 'motivo repetido');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM restaurante_chamados_motivos') = 2, 'cozinha lê os motivos');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM restaurante_chamados_motivos') = 0, 'vendedor não lê os motivos');

  -- página da mesa
  PERFORM ci.entrar(NULL);
  r := restaurante_chamar_info('CHAMAR-ci', mesa);
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'mesa' = 'ch-1' AND jsonb_array_length(r -> 'motivos') = 2 AND r -> 'motivos' -> 0 ->> 'nome' = 'Pedir água CI', 'página da mesa lista os motivos na ordem');
  PERFORM ci.entrar(NULL);
  PERFORM ci.exige(restaurante_chamar_info('chamar-ci', mesa_off) IS NULL, 'mesa desativada não mostra a página');
  PERFORM ci.exige(restaurante_chamar_info('chamar-ci', mesa_alheia) IS NULL, 'mesa de outra empresa não aparece');
  PERFORM ci.exige(restaurante_chamar_info('a b', mesa) IS NULL AND restaurante_chamar_info(NULL, mesa) IS NULL, 'link inválido');
  PERFORM ci.sair();

  -- chamar (anônimo)
  PERFORM ci.deve_falhar(NULL, format($c$SELECT restaurante_chamar_garcom('chamar-ci', %L)$c$, mesa_off), 'chamar de mesa desativada');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT restaurante_chamar_garcom('chamar-ci', %L)$c$, mesa_alheia), 'chamar de mesa de outra empresa');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT restaurante_chamar_garcom('chamar-ci', %L, %L)$c$, mesa, gen_random_uuid()), 'chamar com motivo que não existe');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT restaurante_chamar_garcom('nao-existe-ci', %L)$c$, mesa), 'chamar com link desconhecido');
  PERFORM ci.entrar(NULL);
  r := restaurante_chamar_garcom('chamar-ci', mesa, m_conta);
  r2 := restaurante_chamar_garcom('chamar-ci', mesa, m_conta);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'repetido')::boolean AND (r2 ->> 'repetido')::boolean AND r ->> 'id' = r2 ->> 'id', 'toque repetido devolve o mesmo chamado');
  PERFORM ci.entrar(NULL);
  r2 := restaurante_chamar_garcom('chamar-ci', mesa, m_agua);
  PERFORM ci.sair();
  PERFORM ci.exige((r2 ->> 'repetido')::boolean, 'outro chamado da mesma mesa em menos de 20 s é tratado como repetição');
  PERFORM ci.exige((SELECT count(*) = 1 FROM restaurante_chamados WHERE mesa_id = mesa AND situacao = 'aberto'), 'um só chamado aberto');
  ch := (r ->> 'id')::uuid;
  PERFORM ci.exige((SELECT motivo = 'Pedir a conta CI' FROM restaurante_chamados WHERE id = ch), 'o chamado guarda o motivo');

  -- quem vê e quem atende
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM restaurante_chamados') = 1, 'garçom vê os chamados da própria empresa');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM restaurante_chamados') = 0, 'vendedor não vê chamados');
  PERFORM ci.deve_falhar(NULL, 'SELECT count(*) FROM restaurante_chamados', 'anônimo lê chamados');
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_chamado_atender(%L)$c$, ch), 'vendedor atende chamado');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT restaurante_chamado_atender(%L)$c$, ch), 'anônimo atende chamado');
  PERFORM ci.entrar(gar);
  BEGIN
    UPDATE restaurante_chamados SET situacao = 'atendido', atendido_em = now() WHERE id = ch;
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'aberto' FROM restaurante_chamados WHERE id = ch), 'atender por escrita direta não altera nada');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_chamado_atender(ch);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'atendido' AND atendido_por = gar FROM restaurante_chamados WHERE id = ch), 'garçom atende o chamado');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_chamado_atender(%L)$c$, ch), 'atender de novo');

  -- depois de atendido (e passados os 20 s) a mesa pode chamar de novo
  UPDATE restaurante_chamados SET criado_em = now() - interval '1 minute' WHERE id = ch;
  PERFORM ci.entrar(NULL);
  r := restaurante_chamar_garcom('chamar-ci', mesa, m_conta);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'repetido')::boolean, 'mesa chama de novo depois do atendimento');

  UPDATE empresas SET slug = emp.slug, ativo = emp.ativo WHERE id = emp.id;
  DELETE FROM restaurante_config WHERE tenant_id = demo;
END $$;

-- 17h. a pesagem baixa o estoque pela ficha técnica
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  dep uuid; arroz uuid; kg uuid; cat uuid; prato uuid; cmd uuid; r jsonb; n bigint;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Cozinha pesagem CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'PS-ARROZ', 'Arroz pesagem CI', 'kg', 8) RETURNING id INTO arroz;
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Pesagem estoque CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao, venda_por_peso) VALUES (demo, cat, 'Buffet estoque CI', 60, 'nenhuma', true) RETURNING id INTO kg;
  -- 0,4 kg de arroz por kg vendido, com 20% de perda de preparo
  INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade, perda_percentual) VALUES (demo, kg, arroz, 0.4, 20);
  INSERT INTO restaurante_taras (tenant_id, nome, peso_g) VALUES (demo, 'Prato estoque CI', 300) RETURNING id INTO prato;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(arroz, dep, 'entrada'::mov_tipo, 2, 'ci', 'ci', NULL, 8);
  PERFORM ci.sair();
  INSERT INTO restaurante_config (tenant_id, baixa_estoque, deposito_id) VALUES (demo, true, dep);

  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  -- 1,3 kg bruto - 0,3 de tara = 1 kg líquido: 1 x 0,4 / 0,8 = 0,5 kg de arroz
  r := restaurante_lancar_pesagem(cmd, kg, 1300, prato);
  PERFORM ci.sair();
  SELECT numero INTO n FROM comandas WHERE id = cmd;
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = arroz AND deposito_id = dep) = 1.5, 'a pesagem baixa o insumo pela ficha, com a perda de preparo');
  PERFORM ci.exige((SELECT count(*) = 1 AND bool_and(tipo = 'saida') AND bool_and(quantidade = 0.5) FROM estoque_movimentacoes WHERE documento = 'COMANDA-' || n), 'a baixa da pesagem gera uma movimentação de saída');

  -- sem saldo, a pesagem é recusada e nada é lançado
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_pesagem(%L, %L, 4300, %L)$c$, cmd, kg, prato), 'pesagem sem estoque suficiente do insumo');
  PERFORM ci.exige((SELECT count(*) = 1 FROM comanda_itens WHERE comanda_id = cmd), 'pesagem recusada não deixa item na comanda');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = arroz AND deposito_id = dep) = 1.5, 'pesagem recusada não mexe no estoque');

  -- baixa desligada: a pesagem não mexe no estoque
  UPDATE restaurante_config SET baixa_estoque = false, deposito_id = NULL WHERE tenant_id = demo;
  PERFORM ci.entrar(gar);
  r := restaurante_lancar_pesagem(cmd, kg, 1300, prato);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = arroz AND deposito_id = dep) = 1.5, 'sem baixa de estoque configurada a pesagem não baixa');
  DELETE FROM restaurante_config WHERE tenant_id = demo;
  DELETE FROM cardapio_ficha WHERE item_id = kg;
END $$;

-- 18. quantidade de mesas do restaurante
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gest   constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa    constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  r jsonb; mesa4 uuid; cmd uuid; fm uuid;
BEGIN
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, '22222222-2222-2222-2222-222222222222', 'Filial das mesas') RETURNING id INTO fm;
  -- numeração própria desta filial; mesa com nome (não numérica) não é tocada
  INSERT INTO mesas (tenant_id, filial_id, numero) VALUES (demo, fm, 'Varanda');

  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_definir_mesas(5, %L)$c$, fm), 'garçom define a quantidade de mesas');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT restaurante_definir_mesas(5, %L)$c$, fm), 'caixa define a quantidade de mesas');
  PERFORM ci.deve_falhar(gest, format($c$SELECT restaurante_definir_mesas(-1, %L)$c$, fm), 'quantidade negativa de mesas');
  PERFORM ci.deve_falhar(gest, format($c$SELECT restaurante_definir_mesas(501, %L)$c$, fm), 'mais de 500 mesas');
  PERFORM ci.deve_falhar(gest, format($c$SELECT restaurante_definir_mesas(3, %L)$c$, gen_random_uuid()), 'fm que não existe');

  PERFORM ci.entrar(gest);
  r := restaurante_definir_mesas(5, fm);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'criadas')::int = 5 AND (r ->> 'desativadas')::int = 0, 'cria as mesas de 1 a 5');
  PERFORM ci.exige((SELECT count(*) = 5 FROM mesas WHERE tenant_id = demo AND filial_id = fm AND ativa AND numero ~ '^[0-9]+$'), 'ficam 5 mesas numeradas ativas');

  -- repetir não duplica
  PERFORM ci.entrar(gest);
  r := restaurante_definir_mesas(5, fm);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'criadas')::int = 0 AND (r ->> 'reativadas')::int = 0, 'repetir a mesma quantidade não cria mesas');

  -- a mesa 4 está ocupada: reduzir para 2 desativa a 3 e a 5, mas mantém a 4
  SELECT id INTO mesa4 FROM mesas WHERE tenant_id = demo AND filial_id = fm AND numero = '4';
  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(mesa4, 2);
  PERFORM ci.sair();
  PERFORM ci.entrar(adm);
  r := restaurante_definir_mesas(2, fm);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'desativadas')::int = 2 AND (r ->> 'mantidas_ocupadas')::int = 1, 'reduzir desativa as livres e mantém a ocupada');
  PERFORM ci.exige((SELECT ativa FROM mesas WHERE id = mesa4), 'mesa com comanda aberta segue ativa');
  PERFORM ci.exige((SELECT ativa FROM mesas WHERE tenant_id = demo AND filial_id = fm AND numero = 'Varanda'), 'mesa com nome próprio não é tocada');
  PERFORM ci.exige((SELECT count(*) = 3 FROM mesas WHERE tenant_id = demo AND filial_id = fm AND ativa AND numero ~ '^[0-9]+$'), 'ficam as mesas 1, 2 e a ocupada 4');

  -- aumentar reativa as desativadas em vez de duplicar
  PERFORM ci.entrar(gest);
  r := restaurante_definir_mesas(5, fm);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'reativadas')::int = 2 AND (r ->> 'criadas')::int = 0, 'aumentar reativa as mesas desativadas');
  PERFORM ci.exige((SELECT count(*) = 5 FROM mesas WHERE tenant_id = demo AND filial_id = fm AND numero ~ '^[0-9]+$'), 'continuam 5 mesas, sem duplicar');

  -- zero desativa todas as livres; outra empresa não é afetada
  PERFORM ci.entrar(gest);
  r := restaurante_definir_mesas(0, fm);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 1 FROM mesas WHERE tenant_id = demo AND filial_id = fm AND ativa AND numero ~ '^[0-9]+$'), 'zero desativa tudo, menos a mesa ocupada');
  PERFORM ci.exige((SELECT count(*) = 0 FROM mesas WHERE tenant_id <> demo AND numero ~ '^[0-9]+$' AND NOT ativa), 'outra empresa não é afetada');
END $$;

-- 19. ficha técnica: baixa de insumos, custo e devolução
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz    constant uuid := 'a0000000-0000-0000-0000-000000000007';
  cxa    constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  dep uuid; carne uuid; pao uuid; bacon uuid; lata uuid; outro_tenant uuid; produto_alheio uuid;
  cat uuid; it_burger uuid; it_refri uuid; gr uuid; op_bacon uuid;
  cmd uuid; cmd2 uuid; i_burger uuid; i_refri uuid; i2 uuid; i3 uuid; n_cmd bigint;
BEGIN
  INSERT INTO depositos (tenant_id, nome, permite_negativo) VALUES (demo, 'Cozinha CI', false) RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'FT-CARNE', 'Carne moída CI', 'kg', 40) RETURNING id INTO carne;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'FT-PÃO', 'Pão CI', 'un', 1.5) RETURNING id INTO pao;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'FT-BACON', 'Bacon CI', 'kg', 60) RETURNING id INTO bacon;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'FT-LATA', 'Lata CI', 'un', 3) RETURNING id INTO lata;

  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Ficha CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Burger ficha', 30, 'cozinha') RETURNING id INTO it_burger;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao, produto_id) VALUES (demo, cat, 'Refri lata', 6, 'nenhuma', lata) RETURNING id INTO it_refri;
  INSERT INTO cardapio_grupos (tenant_id, item_id, nome) VALUES (demo, it_burger, 'Extras') RETURNING id INTO gr;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, gr, 'Bacon extra', 5) RETURNING id INTO op_bacon;

  -- permissões: só a gestão cadastra e lê a ficha
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade) VALUES (%L, %L, %L, 1)$c$, demo, it_burger, pao), 'garçom cadastra ficha técnica');
  PERFORM ci.deve_falhar(cxa, format($c$INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade) VALUES (%L, %L, %L, 1)$c$, demo, it_burger, pao), 'caixa cadastra ficha técnica');
  PERFORM ci.entrar(adm);
  INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade, perda_percentual) VALUES (demo, it_burger, carne, 0.15, 10);
  INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade) VALUES (demo, it_burger, pao, 1);
  INSERT INTO cardapio_ficha (tenant_id, opcao_id, produto_id, quantidade) VALUES (demo, op_bacon, bacon, 0.03);
  PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM cardapio_ficha') = 3, 'gestão lê a ficha técnica');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM cardapio_ficha') = 0, 'garçom não lê a ficha técnica');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM cardapio_ficha') = 0, 'cozinha não lê a ficha técnica');
  PERFORM ci.exige(ci.contar(cxa, 'SELECT count(*) FROM cardapio_ficha') = 0, 'caixa não lê a ficha técnica');

  -- restrições da ficha
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade) VALUES (%L, %L, %L, 1)$c$, demo, it_burger, carne), 'mesmo insumo duas vezes na ficha do item');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_ficha (tenant_id, produto_id, quantidade) VALUES (%L, %L, 1)$c$, demo, carne), 'ficha sem item nem opção');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_ficha (tenant_id, item_id, opcao_id, produto_id, quantidade) VALUES (%L, %L, %L, %L, 1)$c$, demo, it_burger, op_bacon, lata), 'ficha com item e opção ao mesmo tempo');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade) VALUES (%L, %L, %L, 0)$c$, demo, it_refri, lata), 'quantidade zero na ficha');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade, perda_percentual) VALUES (%L, %L, %L, 1, 95)$c$, demo, it_refri, lata), 'perda de 95%');
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade) VALUES (outro_tenant, 'FT-ALHEIO', 'Insumo de outra empresa', 'kg') RETURNING id INTO produto_alheio;
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_ficha (tenant_id, item_id, produto_id, quantidade) VALUES (%L, %L, %L, 1)$c$, demo, it_refri, produto_alheio), 'insumo de outra empresa na ficha');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_config (tenant_id, baixa_estoque) VALUES (%L, true)$c$, outro_tenant), 'baixa de estoque sem depósito');

  -- estoque inicial (entrada pelo fluxo normal) e configuração do restaurante
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(carne, dep, 'entrada'::mov_tipo, 10, 'ci', 'ci', NULL, 40);
  PERFORM registrar_movimentacao(pao, dep, 'entrada'::mov_tipo, 50, 'ci', 'ci', NULL, 1.5);
  PERFORM registrar_movimentacao(bacon, dep, 'entrada'::mov_tipo, 2, 'ci', 'ci', NULL, 60);
  PERFORM registrar_movimentacao(lata, dep, 'entrada'::mov_tipo, 24, 'ci', 'ci', NULL, 3);
  PERFORM ci.sair();
  INSERT INTO restaurante_config (tenant_id, baixa_estoque, deposito_id) VALUES (demo, true, dep);
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM restaurante_config') = 0, 'garçom não lê a configuração de estoque do restaurante');
  PERFORM ci.exige(ci.contar(gar, 'WITH u AS (UPDATE restaurante_config SET baixa_estoque = false RETURNING 1) SELECT count(*) FROM u') = 0, 'garçom não altera a configuração de estoque (nenhuma linha)');
  PERFORM ci.exige((SELECT baixa_estoque FROM restaurante_config WHERE tenant_id = demo), 'a configuração segue ligada');

  -- 1. enviar à cozinha baixa os insumos: 2 burgers com bacon extra + 3 refrigerantes
  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  i_burger := restaurante_lancar_item(cmd, it_burger, 2, ARRAY[op_bacon]);
  i_refri := restaurante_lancar_item(cmd, it_refri, 3);
  PERFORM ci.exige((SELECT opcoes -> 0 ? 'id' FROM comanda_itens WHERE id = i_burger), 'a comanda guarda o id da opção escolhida');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = carne AND deposito_id = dep) = 10, 'lançar o item ainda não baixa o estoque');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_enviar_cozinha(cmd);
  PERFORM ci.sair();
  SELECT numero INTO n_cmd FROM comandas WHERE id = cmd;
  -- carne: 2 × 0,15 ÷ 0,90 = 0,333; pão: 2; bacon: 2 × 0,03 = 0,06; lata (revenda, sem ficha): 3
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = carne AND deposito_id = dep) = 9.667, 'a carne baixa com a perda de preparo');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = pao AND deposito_id = dep) = 48, 'o pão baixa pela ficha');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = bacon AND deposito_id = dep) = 1.94, 'a opção escolhida baixa o próprio insumo');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = lata AND deposito_id = dep) = 21, 'bebida de revenda baixa 1 unidade por unidade vendida');
  PERFORM ci.exige((SELECT count(*) = 4 AND bool_and(tipo = 'saida') AND bool_and(documento = 'COMANDA-' || n_cmd) FROM estoque_movimentacoes WHERE documento = 'COMANDA-' || n_cmd),
                   'cada insumo gera uma movimentação de saída com o número da comanda');

  -- 2. cancelar o item ainda na fila da cozinha devolve os insumos; o que já foi entregue não volta
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_item(i_burger, 'cliente desistiu');
  PERFORM restaurante_cancelar_item(i_refri, 'refri já entregue');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = carne AND deposito_id = dep) = 10, 'cancelar na fila devolve a carne');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = bacon AND deposito_id = dep) = 2, 'cancelar na fila devolve o bacon');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = lata AND deposito_id = dep) = 21, 'item já entregue não devolve o estoque');

  -- 3. depois de iniciado o preparo, o insumo foi consumido e não volta
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  i2 := restaurante_lancar_item(cmd2, it_burger, 1);
  PERFORM restaurante_enviar_cozinha(cmd2);
  PERFORM ci.sair();
  PERFORM ci.entrar(coz);
  PERFORM restaurante_atualizar_item(i2, 'preparando');
  PERFORM ci.sair();
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_item(i2, 'queimou no preparo');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = carne AND deposito_id = dep) = 9.833, 'item cancelado já em preparo não devolve a carne');

  -- 4. cancelar a comanda devolve o que ainda estava na fila
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  PERFORM restaurante_lancar_item(cmd2, it_burger, 3);
  PERFORM restaurante_enviar_cozinha(cmd2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = pao AND deposito_id = dep) = 46, 'a comanda enviada baixou 3 pães');
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_comanda(cmd2, 'mesa foi embora');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = pao AND deposito_id = dep) = 49, 'cancelar a comanda devolve os 3 pães');

  -- 5. falta de insumo recusa o envio (depósito sem saldo negativo) e nada fica pela metade
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  i3 := restaurante_lancar_item(cmd2, it_burger, 100);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_enviar_cozinha(%L)$c$, cmd2), 'enviar pedido sem insumo suficiente');
  PERFORM ci.exige((SELECT situacao = 'pendente' FROM comanda_itens WHERE id = i3), 'o envio recusado deixa o item pendente');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = pao AND deposito_id = dep) = 49, 'o envio recusado não mexe no estoque');

  -- 6. com saldo negativo permitido, o envio passa e o estoque fica negativo
  UPDATE depositos SET permite_negativo = true WHERE id = dep;
  PERFORM ci.entrar(gar);
  PERFORM restaurante_enviar_cozinha(cmd2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = pao AND deposito_id = dep) = -51, 'depósito que permite negativo fica negativo');

  -- 7. com a baixa desligada, o estoque não muda
  UPDATE restaurante_config SET baixa_estoque = false WHERE tenant_id = demo;
  PERFORM ci.entrar(gar);
  cmd2 := restaurante_abrir_comanda(NULL, NULL, NULL, 0, 0);
  PERFORM restaurante_lancar_item(cmd2, it_burger, 1);
  PERFORM restaurante_enviar_cozinha(cmd2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = pao AND deposito_id = dep) = -51, 'com a baixa desligada o estoque não muda');
END $$;

-- 20. delivery do restaurante
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  filial constant uuid := '33333333-3333-3333-3333-333333333333';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz    constant uuid := 'a0000000-0000-0000-0000-000000000007';
  cxa    constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  cat uuid; it_pizza uuid; it_taxa uuid; mesa_x uuid; cx uuid; outro_tenant uuid;
  d1 uuid; d2 uuid; i1 uuid; r jsonb; n bigint;
BEGIN
  INSERT INTO cardapio_categorias (tenant_id, nome) VALUES (demo, 'Delivery CI') RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, estacao) VALUES (demo, cat, 'Pizza CI', 20, 'cozinha') RETURNING id INTO it_pizza;
  SELECT id INTO cx FROM caixas WHERE tenant_id = demo AND filial_id = filial AND situacao = 'aberto' LIMIT 1;

  -- validações do pedido
  PERFORM ci.deve_falhar(coz, $c$SELECT restaurante_abrir_delivery('Ana', '11999998888', 'Rua das Flores, 100')$c$, 'cozinha abre delivery');
  PERFORM ci.deve_falhar(gar, $c$SELECT restaurante_abrir_delivery('', '11999998888', 'Rua das Flores, 100')$c$, 'delivery sem nome do cliente');
  PERFORM ci.deve_falhar(gar, $c$SELECT restaurante_abrir_delivery('Ana', '11999998888', 'Rua')$c$, 'delivery com endereço curto');
  PERFORM ci.deve_falhar(gar, $c$SELECT restaurante_abrir_delivery('Ana', '1234', 'Rua das Flores, 100')$c$, 'delivery com telefone curto');
  PERFORM ci.deve_falhar(gar, $c$SELECT restaurante_abrir_delivery('Ana', '11999998888', 'Rua das Flores, 100', NULL, NULL, -5)$c$, 'taxa de entrega negativa');
  PERFORM ci.deve_falhar(gar, $c$SELECT restaurante_abrir_delivery('Ana', '11999998888', 'Rua das Flores, 100', NULL, NULL, 5000)$c$, 'taxa de entrega absurda');
  PERFORM ci.deve_falhar(gar, $c$SELECT restaurante_abrir_delivery('Ana', '11999998888', 'Rua das Flores, 100', NULL, NULL, 5, 'cheque')$c$, 'forma de pagamento inventada');

  -- pedido: taxa de 8, pagamento em dinheiro com troco para 100
  PERFORM ci.entrar(gar);
  d1 := restaurante_abrir_delivery('Ana Souza', '(11) 99999-8888', 'Rua das Flores, 100', 'Centro', 'Casa azul', 8, 'dinheiro', 100, 'Sem campainha');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tipo = 'delivery' AND entrega_situacao = 'aguardando' AND mesa_id IS NULL AND canal = 'proprio'
                         AND taxa_servico_percentual = 0 AND couvert_por_pessoa = 0 AND entrega_bairro = 'Centro'
                         AND entrega_troco_para = 100 AND entrega_pagamento = 'dinheiro'
                    FROM comandas WHERE id = d1), 'delivery nasce sem serviço nem couvert, aguardando, com os dados da entrega');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(total) = 8 AND bool_and(situacao = 'entregue') FROM comanda_itens WHERE comanda_id = d1),
                   'a taxa de entrega entra na conta como um item');
  SELECT id INTO it_taxa FROM cardapio_itens WHERE tenant_id = demo AND interno AND nome = 'Taxa de entrega';
  PERFORM ci.exige(it_taxa IS NOT NULL AND (SELECT NOT ativo FROM cardapio_itens WHERE id = it_taxa), 'o item da taxa é interno e inativo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_lancar_item(%L, %L, 1)$c$, d1, it_taxa), 'lançar o item interno da taxa à mão');

  -- itens, cozinha e saída
  PERFORM ci.entrar(gar);
  i1 := restaurante_lancar_item(d1, it_pizza, 2);
  PERFORM restaurante_enviar_cozinha(d1);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_avancar(%L, 'saiu', 'Zé')$c$, d1), 'sair com item ainda na cozinha');
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_delivery_avancar(%L, 'saiu', 'Zé')$c$, d1), 'cozinha despacha o delivery');
  PERFORM ci.entrar(coz);
  PERFORM restaurante_atualizar_item(i1, 'preparando');
  PERFORM restaurante_atualizar_item(i1, 'pronto');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_avancar(%L, 'entregue')$c$, d1), 'entregar ao cliente sem ter saído');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_delivery_avancar(d1, 'saiu', ' Zé da moto ');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT entrega_situacao = 'saiu' AND entregador = 'Zé da moto' AND saiu_em IS NOT NULL FROM comandas WHERE id = d1),
                   'o pedido sai com o entregador registrado');
  PERFORM ci.exige((SELECT situacao = 'entregue' FROM comanda_itens WHERE id = i1), 'os itens prontos passam a entregues na saída');

  -- voltar e sair de novo
  PERFORM ci.entrar(gar);
  PERFORM restaurante_delivery_avancar(d1, 'aguardando');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT entrega_situacao = 'aguardando' AND entregador IS NULL AND saiu_em IS NULL FROM comandas WHERE id = d1),
                   'entregador que volta devolve o pedido para aguardando');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_delivery_avancar(d1, 'saiu', 'Zé');
  PERFORM ci.sair();

  -- taxa: ajusta antes do recebimento, trava depois
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_delivery_taxa(%L, 12)$c$, d1), 'cozinha muda a taxa de entrega');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_taxa(%L, -1)$c$, d1), 'taxa negativa ao ajustar');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_delivery_taxa(d1, 12);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT sum(total) = 52 FROM comanda_itens WHERE comanda_id = d1 AND situacao <> 'cancelado'), 'taxa ajustada para 12: conta de 40 + 12');
  PERFORM ci.entrar(cxa);
  PERFORM restaurante_receber_parcial(d1, '[{"forma":"pix","valor":10}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_taxa(%L, 15)$c$, d1), 'mudar a taxa depois de receber pagamento');

  -- entrega ao cliente e fechamento no caixa (serviço zero: total 52, já recebido 10)
  PERFORM ci.entrar(gar);
  PERFORM restaurante_delivery_avancar(d1, 'entregue');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT entrega_situacao = 'entregue' AND entregue_cliente_em IS NOT NULL FROM comandas WHERE id = d1), 'pedido entregue ao cliente');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_avancar(%L, 'entregue')$c$, d1), 'entregar duas vezes');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_avancar(%L, 'aguardando')$c$, d1), 'voltar um pedido já entregue');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_avancar(%L, 'inventada')$c$, d1), 'situação de entrega inventada');
  PERFORM ci.entrar(cxa);
  r := restaurante_fechar_comanda(d1, '[{"forma":"dinheiro","valor":42}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 52 AND (r ->> 'taxa_servico')::numeric = 0 AND (r ->> 'restante')::numeric = 42,
                   'o delivery fecha sem serviço, com a taxa dentro do total');
  SELECT numero INTO n FROM comandas WHERE id = d1;
  PERFORM ci.exige((SELECT sum(valor) = 52 FROM caixa_movimentos WHERE tipo = 'venda' AND descricao LIKE 'Comanda ' || n || '%'), 'o caixa recebeu a conta do delivery');

  -- cancelar o pedido devolve nada quando já foi pago; pedido novo cancelado antes da cozinha
  PERFORM ci.entrar(gar);
  d2 := restaurante_abrir_delivery('Bruno', NULL, 'Av. Brasil, 2000', NULL, NULL, 0);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 0 FROM comanda_itens WHERE comanda_id = d2), 'taxa zero não cria item');
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_comanda(d2, 'cliente desistiu');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_delivery_avancar(%L, 'saiu')$c$, d2), 'despachar pedido cancelado');

  -- integridade: sem mesa, canal e código externo únicos
  SELECT id INTO mesa_x FROM mesas WHERE tenant_id = demo LIMIT 1;
  PERFORM ci.deve_falhar_dono(format($c$UPDATE comandas SET mesa_id = %L WHERE id = %L$c$, mesa_x, d1), 'delivery com mesa');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE comandas SET entrega_endereco = 'Rua' WHERE id = %L$c$, d1), 'delivery com endereço curto no banco');
  UPDATE comandas SET canal = 'ifood', codigo_externo = 'IF-1' WHERE id = d1;
  PERFORM ci.deve_falhar_dono(format($c$UPDATE comandas SET canal = 'ifood', codigo_externo = 'IF-1' WHERE id = %L$c$, d2), 'mesmo código externo duas vezes no mesmo canal');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE comandas SET canal = 'rappi' WHERE id = %L$c$, d2), 'canal inventado');

  -- zonas de entrega: a gestão cadastra, o atendimento lê, os outros não
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;
  PERFORM ci.entrar(adm);
  INSERT INTO restaurante_zonas_entrega (tenant_id, nome, taxa) VALUES (demo, 'Centro', 6), (demo, 'Zona Norte', 12);
  PERFORM ci.sair();
  INSERT INTO restaurante_zonas_entrega (tenant_id, nome, taxa) VALUES (outro_tenant, 'Centro', 9);
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM restaurante_zonas_entrega') = 2, 'atendimento lê só as zonas da própria empresa');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO restaurante_zonas_entrega (tenant_id, nome, taxa) VALUES (%L, 'Sul', 5)$c$, demo), 'garçom cadastra zona de entrega');
  PERFORM ci.deve_falhar(cxa, format($c$INSERT INTO restaurante_zonas_entrega (tenant_id, nome, taxa) VALUES (%L, 'Sul', 5)$c$, demo), 'caixa cadastra zona de entrega');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_zonas_entrega (tenant_id, nome, taxa) VALUES (%L, ' centro ', 5)$c$, demo), 'zona repetida (sem diferenciar maiúsculas)');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_zonas_entrega (tenant_id, nome, taxa) VALUES (%L, 'Cara', 5000)$c$, demo), 'taxa de zona absurda');
END $$;

-- 20b. praças de produção, mesa bloqueada e reserva de mesa
DO $$
DECLARE
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  coz    constant uuid := 'a0000000-0000-0000-0000-000000000007';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  outro_tenant uuid; m1 uuid; m2 uuid; it uuid; cmd uuid; res uuid; praca_churras uuid;
BEGIN
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'PZ1') RETURNING id INTO m1;
  INSERT INTO mesas (tenant_id, numero) VALUES (demo, 'PZ2') RETURNING id INTO m2;

  -- praças: a gestão cadastra; garçom e cozinha leem; o código nasce do nome
  PERFORM ci.entrar(adm);
  INSERT INTO restaurante_pracas (tenant_id, nome) VALUES (demo, 'Churrascaria Açougue') RETURNING id INTO praca_churras;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT codigo FROM restaurante_pracas WHERE id = praca_churras) = 'churrascaria_acougue', 'código da praça nasce do nome, sem acento');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM restaurante_pracas') = 1, 'cozinha lê as praças');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM restaurante_pracas') = 0, 'vendedor não lê as praças');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO restaurante_pracas (tenant_id, nome) VALUES (%L, 'Pizzaria')$c$, demo), 'garçom cadastra praça');
  PERFORM ci.deve_falhar(coz, format($c$INSERT INTO restaurante_pracas (tenant_id, nome) VALUES (%L, 'Pizzaria')$c$, demo), 'cozinha cadastra praça');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_pracas (tenant_id, nome) VALUES (%L, 'Bar')$c$, demo), 'praça com o nome da fixa (Bar)');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_pracas (tenant_id, nome) VALUES (%L, ' churrascaria  acougue ')$c$, demo), 'praça repetida pelo código');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO restaurante_pracas (tenant_id, nome) VALUES (%L, '!')$c$, demo), 'praça sem letras');
  UPDATE restaurante_pracas SET codigo = 'outro', nome = 'Churrasco' WHERE id = praca_churras;
  PERFORM ci.exige((SELECT codigo FROM restaurante_pracas WHERE id = praca_churras) = 'churrascaria_acougue', 'código da praça não muda ao renomear');

  -- item do cardápio: aceita praça ativa da própria empresa; recusa praça inexistente, de outra empresa ou inativa
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_itens (tenant_id, nome, preco, estacao) VALUES (%L, 'Fantasma', 10, 'nao_existe')$c$, demo), 'item em praça inexistente');
  INSERT INTO restaurante_pracas (tenant_id, nome) VALUES (outro_tenant, 'Pizzaria');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_itens (tenant_id, nome, preco, estacao) VALUES (%L, 'Pizza', 40, 'pizzaria')$c$, demo), 'item em praça de outra empresa');
  INSERT INTO cardapio_itens (tenant_id, nome, preco, estacao) VALUES (demo, 'Picanha', 80, 'churrascaria_acougue') RETURNING id INTO it;
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM restaurante_pracas WHERE id = %L$c$, praca_churras), 'excluir praça em uso por item');
  UPDATE restaurante_pracas SET ativo = false WHERE id = praca_churras;
  UPDATE cardapio_itens SET preco = 85 WHERE id = it;
  PERFORM ci.exige(true, 'item segue editável com a praça desativada');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO cardapio_itens (tenant_id, nome, preco, estacao) VALUES (%L, 'Costela', 70, 'churrascaria_acougue')$c$, demo), 'item novo em praça inativa');

  -- bloqueio de mesa
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_bloquear_mesa(%L, true, 'x')$c$, m1), 'vendedor bloqueia mesa');
  PERFORM ci.deve_falhar(coz, format($c$SELECT restaurante_bloquear_mesa(%L, true, 'x')$c$, m1), 'cozinha bloqueia mesa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_bloquear_mesa(%L, true, 'x')$c$, gen_random_uuid()), 'bloquear mesa que não existe');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_bloquear_mesa(m1, true, 'Mesa quebrada');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT bloqueada FROM mesas WHERE id = m1), 'garçom bloqueia mesa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_abrir_comanda(%L, 2)$c$, m1), 'abrir comanda em mesa bloqueada');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_reservar_mesa(%L, 'Ana', now() + interval '1 day')$c$, m1), 'reservar mesa bloqueada');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_bloquear_mesa(m1, false);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (SELECT bloqueada FROM mesas WHERE id = m1) AND (SELECT bloqueio_motivo FROM mesas WHERE id = m1) IS NULL, 'desbloquear limpa o motivo');

  -- mesa com comanda aberta não bloqueia; transferir para mesa bloqueada é recusado
  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(m1, 2);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_bloquear_mesa(%L, true)$c$, m1), 'bloquear mesa com comanda aberta');
  PERFORM ci.entrar(gar);
  PERFORM restaurante_bloquear_mesa(m2, true, 'Evento');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_transferir_mesa(%L, %L)$c$, cmd, m2), 'transferir para mesa bloqueada');
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_comanda(cmd, 'teste');
  PERFORM restaurante_bloquear_mesa(m2, false);
  PERFORM ci.sair();

  -- reservas
  PERFORM ci.deve_falhar(vend, format($c$SELECT restaurante_reservar_mesa(%L, 'Ana', now() + interval '1 day')$c$, m1), 'vendedor reserva mesa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_reservar_mesa(%L, '  ', now() + interval '1 day')$c$, m1), 'reserva sem nome');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_reservar_mesa(%L, 'Ana', now() - interval '3 hours')$c$, m1), 'reserva no passado');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_reservar_mesa(%L, 'Ana', now() + interval '2 years')$c$, m1), 'reserva distante demais');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_reservar_mesa(%L, 'Ana', now() + interval '1 day', NULL, 0)$c$, m1), 'reserva com zero pessoas');
  PERFORM ci.entrar(gar);
  res := restaurante_reservar_mesa(m1, 'Ana', now() + interval '10 minutes', '11999990000', 4, 'aniversário');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_reservar_mesa(%L, 'Bia', now() + interval '70 minutes')$c$, m1), 'duas reservas da mesma mesa com menos de 2 h');
  PERFORM ci.exige(ci.contar(coz, 'SELECT count(*) FROM mesa_reservas') >= 1, 'cozinha lê as reservas');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM mesa_reservas') = 0, 'vendedor não lê reservas');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO mesa_reservas (tenant_id, mesa_id, nome, reservada_para) VALUES (%L, %L, 'Z', now())$c$, demo, m1), 'reserva por escrita direta');
  PERFORM ci.entrar(gar);
  BEGIN
    UPDATE mesa_reservas SET situacao = 'cancelada' WHERE id = res;
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM mesa_reservas WHERE id = res) = 'ativa', 'cancelar reserva por escrita direta não altera nada');

  -- abrir a comanda na mesa reservada atende a reserva
  PERFORM ci.entrar(gar);
  cmd := restaurante_abrir_comanda(m1, 4);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM mesa_reservas WHERE id = res) = 'atendida', 'abrir a comanda atende a reserva');
  PERFORM ci.deve_falhar(gar, format($c$SELECT restaurante_cancelar_reserva(%L)$c$, res), 'cancelar reserva já atendida');
  PERFORM ci.entrar(adm);
  PERFORM restaurante_cancelar_comanda(cmd, 'teste');
  res := restaurante_reservar_mesa(m2, 'Caio', now() + interval '1 day');
  PERFORM restaurante_cancelar_reserva(res);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM mesa_reservas WHERE id = res) = 'cancelada', 'reserva cancelada');
END $$;

-- 20c. foto do item e cardápio online
DO $$
DECLARE
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  outro_tenant uuid; cat uuid; it1 uuid; it2 uuid; g1 uuid; r jsonb; emp record;
BEGIN
  SELECT id INTO outro_tenant FROM tenants WHERE id <> demo LIMIT 1;
  -- a empresa mais antiga da loja recebe o link (o espelho com o cadastro do assinante usa essa mesma)
  SELECT id, slug, nome_fantasia, ativo INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  IF emp.id IS NOT NULL THEN
    UPDATE empresas SET slug = 'bistro-ci', nome_fantasia = 'Bistrô CI', ativo = true
     WHERE id = (SELECT id FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1);
  ELSE
    INSERT INTO empresas (tenant_id, razao_social, nome_fantasia, slug) VALUES (demo, 'Cardápio CI LTDA', 'Bistrô CI', 'bistro-ci');
  END IF;
  INSERT INTO cardapio_categorias (tenant_id, nome, ordem) VALUES (demo, 'Pratos CI', 1) RETURNING id INTO cat;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, descricao, preco, ordem, foto_path)
    VALUES (demo, cat, 'Risoto CI', 'Cremoso', 52.5, 2, demo::text || '/risoto-1.jpg') RETURNING id INTO it1;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, ordem) VALUES (demo, cat, 'Filé CI', 70, 1) RETURNING id INTO it2;
  INSERT INTO cardapio_itens (tenant_id, categoria_id, nome, preco, ativo) VALUES (demo, cat, 'Item inativo CI', 9, false);
  INSERT INTO cardapio_grupos (tenant_id, item_id, nome) VALUES (demo, it2, 'Ponto') RETURNING id INTO g1;
  INSERT INTO cardapio_opcoes (tenant_id, grupo_id, nome, preco_adicional) VALUES (demo, g1, 'Ao ponto', 0), (demo, g1, 'Bem passado', 2);

  -- foto: caminho precisa ser da própria empresa e ter nome simples
  PERFORM ci.deve_falhar_dono(format($c$UPDATE cardapio_itens SET foto_path = %L WHERE id = %L$c$, outro_tenant::text || '/x.jpg', it1), 'foto no caminho de outra empresa');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE cardapio_itens SET foto_path = %L WHERE id = %L$c$, demo::text || '/../x.jpg', it1), 'foto com caminho fora da pasta');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE cardapio_itens SET foto_path = %L WHERE id = %L$c$, demo::text || '/a/b.jpg', it1), 'foto em subpasta');

  -- desligado por padrão
  PERFORM ci.entrar(NULL);
  r := restaurante_cardapio_publico('bistro-ci');
  PERFORM ci.sair();
  PERFORM ci.exige(r IS NULL, 'cardápio online desligado não aparece');

  -- só a gestão liga
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO restaurante_config (tenant_id, cardapio_online) VALUES (%L, true)$c$, demo), 'garçom liga o cardápio online');
  PERFORM ci.entrar(adm);
  INSERT INTO restaurante_config (tenant_id, cardapio_online) VALUES (demo, true)
    ON CONFLICT (tenant_id) DO UPDATE SET cardapio_online = true;
  PERFORM ci.sair();

  PERFORM ci.entrar(NULL);
  r := restaurante_cardapio_publico('BISTRO-ci');
  PERFORM ci.sair();
  PERFORM ci.exige(r IS NOT NULL AND r->'empresa'->>'nome' = 'Bistrô CI', 'anônimo vê o cardápio ligado (link sem diferenciar maiúsculas)');
  PERFORM ci.exige(jsonb_array_length(r->'cardapios') >= 1 AND jsonb_array_length(r->'cardapios'->0->'categorias') >= 1, 'cardápio público tem cardápios e categorias');
  PERFORM ci.exige((SELECT c->'itens'->0->>'nome' FROM jsonb_array_elements(r->'cardapios'->0->'categorias') c WHERE c->>'nome' = 'Pratos CI') = 'Filé CI', 'itens saem na ordem do cadastro');
  PERFORM ci.exige(NOT (r::text LIKE '%Item inativo CI%'), 'item inativo não aparece');
  PERFORM ci.exige((SELECT (c->'itens'->0->'grupos'->0->'opcoes'->1->>'preco_adicional')::numeric FROM jsonb_array_elements(r->'cardapios'->0->'categorias') c WHERE c->>'nome' = 'Pratos CI') = 2, 'adicionais saem com valor');
  PERFORM ci.exige(r::text LIKE '%risoto-1.jpg%', 'foto do item sai no cardápio');
  PERFORM ci.exige((SELECT (i->>'preco')::numeric FROM jsonb_array_elements(r->'cardapios') m, jsonb_array_elements(m->'categorias') c, jsonb_array_elements(c->'itens') i
                     WHERE m->>'nome' = 'Jantar CI' AND i->>'nome' = 'Prato A CI') = 50, 'cada cardápio público mostra o seu preço');
  PERFORM ci.exige((SELECT (i->>'preco')::numeric FROM jsonb_array_elements(r->'cardapios') m, jsonb_array_elements(m->'categorias') c, jsonb_array_elements(c->'itens') i
                     WHERE m->>'nome' = 'Principal CI' AND i->>'nome' = 'Prato A CI') = 45, 'cardápio sem preço próprio mostra o preço base');
  PERFORM ci.exige(NOT (r::text LIKE '%Parado CI%'), 'cardápio inativo não aparece no público');
  PERFORM ci.exige(r::text NOT LIKE '%custo%' AND r::text NOT LIKE '%estacao%' AND r::text NOT LIKE '%tenant%', 'cardápio público não expõe custo, estação nem empresa');

  -- categoria desativada some do cardápio
  UPDATE cardapio_categorias SET ativo = false WHERE id = cat;
  PERFORM ci.entrar(NULL);
  r := restaurante_cardapio_publico('bistro-ci');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r::text LIKE '%Filé CI%'), 'item de categoria desativada some do cardápio online');
  UPDATE cardapio_categorias SET ativo = true WHERE id = cat;

  -- link inválido ou desconhecido
  PERFORM ci.entrar(NULL);
  PERFORM ci.exige(restaurante_cardapio_publico('nao-existe-ci') IS NULL, 'link desconhecido');
  PERFORM ci.exige(restaurante_cardapio_publico('a b') IS NULL, 'link inválido');
  PERFORM ci.exige(restaurante_cardapio_publico(NULL) IS NULL, 'link vazio');
  PERFORM ci.sair();

  -- empresa inativa não publica
  UPDATE empresas SET ativo = false WHERE tenant_id = demo AND slug = 'bistro-ci';
  PERFORM ci.entrar(NULL);
  PERFORM ci.exige(restaurante_cardapio_publico('bistro-ci') IS NULL, 'empresa inativa não publica o cardápio');
  PERFORM ci.sair();
  UPDATE empresas SET ativo = true WHERE tenant_id = demo AND slug = 'bistro-ci';

  -- armazenamento: só a gestão da própria empresa mexe na pasta
  PERFORM ci.entrar(adm);
  INSERT INTO storage.objects (bucket_id, name) VALUES ('cardapio-fotos', demo::text || '/prato.jpg');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO storage.objects (bucket_id, name) VALUES ('cardapio-fotos', %L)$c$, outro_tenant::text || '/prato.jpg'), 'gestão envia foto na pasta de outra empresa');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO storage.objects (bucket_id, name) VALUES ('cardapio-fotos', %L)$c$, demo::text || '/garcom.jpg'), 'garçom envia foto do cardápio');
  PERFORM ci.deve_falhar(NULL, format($c$INSERT INTO storage.objects (bucket_id, name) VALUES ('cardapio-fotos', %L)$c$, demo::text || '/anon.jpg'), 'anônimo envia foto do cardápio');

  -- devolve a empresa ao que era, para não interferir nos testes seguintes
  UPDATE empresas SET slug = emp.slug, nome_fantasia = emp.nome_fantasia, ativo = emp.ativo WHERE id = emp.id;
END $$;

-- 21. pedido de obra com retirada parcial: saldo por item e trava de saída
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  dep uuid; cim uuid; areia uuid; cli uuid; obra uuid; ped uuid; num bigint;
  i_cim uuid; i_areia uuid; ent1 uuid; ent1b uuid; ent2 uuid; plan uuid;
  q_antes numeric; r_antes numeric; q numeric; r numeric;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Obras CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'OB-CIMENTO', 'Cimento CI', 'sc', 30) RETURNING id INTO cim;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'OB-AREIA', 'Areia CI', 'm3', 80) RETURNING id INTO areia;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Construtora CI') RETURNING id INTO cli;
  INSERT INTO obras (tenant_id, cliente_id, nome, endereco) VALUES (demo, cli, 'Obra Centro CI', 'Rua das Obras, 10') RETURNING id INTO obra;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(cim, dep, 'entrada'::mov_tipo, 100, 'ci', 'ci');
  PERFORM registrar_movimentacao(areia, dep, 'entrada'::mov_tipo, 20, 'ci', 'ci');
  PERFORM ci.sair();

  -- pedido real da obra: 10 sacos de cimento e 4 m³ de areia, com reserva de estoque
  PERFORM ci.entrar(vend);
  ped := criar_pedido_direto(cli, dep,
    jsonb_build_array(jsonb_build_object('produto_id', cim, 'quantidade', 10, 'preco_unitario', 40),
                      jsonb_build_object('produto_id', areia, 'quantidade', 4, 'preco_unitario', 120)),
    obra);
  PERFORM ci.sair();
  SELECT id INTO i_cim FROM pedido_itens WHERE pedido_id = ped AND produto_id = cim;
  SELECT id INTO i_areia FROM pedido_itens WHERE pedido_id = ped AND produto_id = areia;
  PERFORM ci.exige((SELECT reservado FROM estoques WHERE produto_id = cim AND deposito_id = dep) = 10, 'pedido da obra reserva o cimento');
  PERFORM ci.exige((SELECT total FROM pedidos WHERE id = ped) = 880, 'total do pedido da obra');

  -- sem separação e conferência completas o pedido não fica pronto para sair
  PERFORM ci.entrar(adm);
  PERFORM pedido_avancar_status(ped, 'aprovado');
  PERFORM pedido_avancar_status(ped, 'separacao');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_avancar_status(%L, 'separado')$c$, ped), 'separar sem separar os itens');
  UPDATE pedido_itens SET quantidade_separada = quantidade WHERE pedido_id = ped;
  PERFORM ci.entrar(adm);
  PERFORM pedido_avancar_status(ped, 'separado');
  PERFORM pedido_avancar_status(ped, 'conferencia');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_avancar_status(%L, 'pronto_entrega')$c$, ped), 'liberar sem conferir');
  UPDATE pedido_itens SET quantidade_conferida = quantidade WHERE pedido_id = ped;
  PERFORM ci.entrar(adm);
  PERFORM pedido_avancar_status(ped, 'pronto_entrega');
  PERFORM ci.sair();

  -- 1ª retirada parcial no balcão: 4 de 10 sacos
  SELECT quantidade, reservado INTO q_antes, r_antes FROM estoques WHERE produto_id = cim AND deposito_id = dep;
  PERFORM ci.entrar(adm);
  ent1 := pedido_registrar_saida(ped, jsonb_build_array(jsonb_build_object('pedido_item_id', i_cim, 'quantidade', 4)),
    'retirada', 'João Pedreiro', 'retirada na loja', 'chave-ret-1');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade_entregue FROM pedido_itens WHERE id = i_cim) = 4, 'retirada parcial soma no item');
  PERFORM ci.exige((SELECT quantidade_entregue FROM pedido_itens WHERE id = i_areia) = 0, 'o outro item não mexe');
  PERFORM ci.exige((SELECT tipo = 'retirada' AND situacao = 'entregue' AND recebedor = 'João Pedreiro' FROM entregas WHERE id = ent1), 'a retirada fica registrada com quem levou');
  SELECT quantidade, reservado INTO q, r FROM estoques WHERE produto_id = cim AND deposito_id = dep;
  PERFORM ci.exige(q = q_antes - 4 AND r = r_antes - 4, 'a retirada baixa o saldo e libera a reserva só do que saiu');
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = ped) = 'em_rota', 'pedido segue aberto depois da retirada parcial');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM pedido_historico WHERE pedido_id = ped AND situacao_nova = 'em_rota'
                            AND observacao = 'Retirada parcial registrada'), 'a retirada parcial entra no histórico do pedido');

  -- reenvio com a mesma chave (conexão que caiu) não duplica
  PERFORM ci.entrar(adm);
  ent1b := pedido_registrar_saida(ped, jsonb_build_array(jsonb_build_object('pedido_item_id', i_cim, 'quantidade', 4)),
    'retirada', 'João Pedreiro', NULL, 'chave-ret-1');
  PERFORM ci.sair();
  PERFORM ci.exige(ent1b = ent1 AND (SELECT quantidade_entregue FROM pedido_itens WHERE id = i_cim) = 4, 'mesma chave não retira duas vezes');

  -- trava de saldo: restam 6 sacos
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_registrar_saida(%L, jsonb_build_array(jsonb_build_object('pedido_item_id', %L, 'quantidade', 7)), 'retirada')$c$, ped, i_cim), 'retirar acima do saldo do item');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_registrar_saida(%L, jsonb_build_array(jsonb_build_object('pedido_item_id', %L, 'quantidade', 0)), 'retirada')$c$, ped, i_cim), 'retirada sem quantidade');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_registrar_saida(%L, '[]'::jsonb, 'retirada')$c$, ped), 'retirada sem itens');
  PERFORM ci.exige((SELECT quantidade_entregue FROM pedido_itens WHERE id = i_cim) = 4, 'retirada recusada não muda o saldo');

  -- o que está agendado também conta contra o saldo
  PERFORM ci.entrar(adm);
  plan := planejar_entrega(ped, jsonb_build_array(jsonb_build_object('pedido_item_id', i_cim, 'quantidade', 2)), NULL, NULL, current_date + 1);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_registrar_saida(%L, jsonb_build_array(jsonb_build_object('pedido_item_id', %L, 'quantidade', 5)), 'retirada')$c$, ped, i_cim), 'retirar o que já está agendado');
  PERFORM ci.deve_falhar(adm, format($c$SELECT planejar_entrega(%L, jsonb_build_array(jsonb_build_object('pedido_item_id', %L, 'quantidade', 5)))$c$, ped, i_cim), 'agendar acima do saldo livre');

  -- reagendar a entrega exige motivo e fica no histórico da obra
  PERFORM ci.deve_falhar(adm, format($c$SELECT entrega_agendar(%L, current_date + 3)$c$, plan), 'reagendar sem motivo');
  PERFORM ci.entrar(adm);
  PERFORM entrega_agendar(plan, current_date + 3, 'Rua das Obras, 10', 'Mestre Zé', 'chuva prevista');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT reagendamentos = 1 AND previsao_data = current_date + 3 AND responsavel = 'Mestre Zé' FROM entregas WHERE id = plan), 'reagendamento muda a data e conta uma vez');
  PERFORM ci.exige((SELECT count(*) FROM entrega_reagendamentos WHERE entrega_id = plan AND motivo = 'chuva prevista'
                       AND data_anterior = current_date + 1 AND data_nova = current_date + 3) = 1, 'reagendamento guarda de, para e motivo');

  -- cada insucesso fica guardado, mesmo depois de reagendar a entrega
  PERFORM ci.entrar(adm);
  PERFORM entrega_insucesso(plan, 'Obra fechada');
  PERFORM entrega_agendar(plan, current_date + 4, NULL, NULL, 'obra reabre');
  PERFORM entrega_insucesso(plan, 'Cliente ausente');
  PERFORM entrega_agendar(plan, current_date + 5, NULL, NULL, 'cliente confirmou');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM entregas WHERE id = plan) = 'planejada', 'entrega reagendada volta a planejada');
  PERFORM ci.exige((SELECT count(*) FROM entrega_tentativas WHERE entrega_id = plan) = 2, 'as duas tentativas que falharam ficam guardadas');
  PERFORM ci.exige((SELECT array_agg(motivo ORDER BY created_at, motivo) FROM entrega_tentativas WHERE entrega_id = plan) = ARRAY['Cliente ausente', 'Obra fechada'], 'cada tentativa guarda o seu motivo');
  PERFORM ci.exige(ci.contar(adm, format('SELECT count(*) FROM entrega_tentativas WHERE entrega_id = %L', plan)) = 2, 'gestão lê as tentativas');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM entrega_tentativas') = 0, 'garçom não lê as tentativas');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO entrega_tentativas (tenant_id, entrega_id, motivo) VALUES (%L, %L, 'x')$c$, demo, plan), 'inserir tentativa direto');

  -- ocorrências do pedido: avaria pede descrição, substituição pede o produto novo
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_registrar_ocorrencia(%L, 'avaria', 1, 'entrega')$c$, i_areia), 'avaria sem descrição');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_registrar_ocorrencia(%L, 'substituicao', 1, 'entrega')$c$, i_areia), 'substituição sem produto');
  PERFORM ci.entrar(adm);
  PERFORM pedido_registrar_ocorrencia(i_areia, 'avaria', 1, 'entrega', NULL, 'um m³ contaminado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM pedido_ocorrencias WHERE pedido_id = ped) = 1, 'ocorrência registrada no pedido');
  PERFORM ci.exige(ci.contar(adm, format('SELECT count(*) FROM entrega_reagendamentos WHERE entrega_id = %L', plan)) = 3, 'gestão lê o histórico de reagendamentos');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM pedido_ocorrencias') = 0, 'garçom não lê ocorrências');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM entrega_reagendamentos') = 0, 'garçom não lê reagendamentos');
  PERFORM ci.deve_falhar(gar, format($c$SELECT entrega_agendar(%L, current_date + 5, NULL, NULL, 'x')$c$, plan), 'garçom reagenda entrega');
  PERFORM ci.deve_falhar(gar, format($c$SELECT pedido_registrar_ocorrencia(%L, 'falta', 1, 'entrega', NULL, 'x')$c$, i_areia), 'garçom registra ocorrência');

  -- 2ª retirada: os 4 sacos livres e a areia toda
  PERFORM ci.entrar(adm);
  ent2 := pedido_registrar_saida(ped, jsonb_build_array(
      jsonb_build_object('pedido_item_id', i_cim, 'quantidade', 4),
      jsonb_build_object('pedido_item_id', i_areia, 'quantidade', 4)), 'retirada', 'Maria', NULL, 'chave-ret-2');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade_entregue FROM pedido_itens WHERE id = i_cim) = 8, 'cimento: 8 de 10 saíram');
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = ped) = 'em_rota', 'com o agendado ainda por sair o pedido continua aberto');

  -- os 2 sacos agendados saem pela própria entrega agendada (e não por uma retirada avulsa)
  PERFORM ci.entrar(adm);
  PERFORM entrega_concluir(plan, 'Zé');
  PERFORM ci.sair();
  SELECT quantidade, reservado INTO q, r FROM estoques WHERE produto_id = cim AND deposito_id = dep;
  PERFORM ci.exige(q = 90 AND r = 0, 'depois de tudo: 10 sacos baixados e nenhuma reserva sobrando');
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = ped) = 'entregue', 'pedido entregue quando não resta nada');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pedido_registrar_saida(%L, jsonb_build_array(jsonb_build_object('pedido_item_id', %L, 'quantidade', 1)), 'retirada')$c$, ped, i_cim), 'retirar depois de entregue');

  -- perfis sem acesso e outra empresa
  PERFORM ci.deve_falhar(gar, format($c$SELECT pedido_registrar_saida(%L, '[]'::jsonb)$c$, ped), 'garçom registra saída de pedido');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT pedido_registrar_saida(%L, '[]'::jsonb)$c$, ped), 'anon registra saída de pedido');
END $$;

-- 22. Fase 0: comissão só pelo fluxo, venda sem duplicar, nota protegida, referências da mesma empresa, papéis atômicos
DO $$
DECLARE
  demo   constant uuid := '11111111-1111-1111-1111-111111111111';
  emp    constant uuid := '22222222-2222-2222-2222-222222222222';
  adm    constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend   constant uuid := 'a0000000-0000-0000-0000-000000000002';
  novo   constant uuid := 'a0000000-0000-0000-0000-000000000004';
  gest   constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar    constant uuid := 'a0000000-0000-0000-0000-000000000006';
  dep uuid; prod uuid; cli uuid; ped uuid; ped2 uuid; nota uuid; cx uuid; v1 uuid; v2 uuid; v3 uuid;
  q_antes numeric; q_depois numeric; n_mov_antes bigint; n_mov_depois bigint;
  tb uuid; eb uuid; fb uuid; cb uuid; obb uuid; profb uuid; chave_venda uuid := gen_random_uuid();
  n_com bigint;
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  n_nota bigint;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Fase0 CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'F0-ITEM', 'Item Fase 0', 'un', 5) RETURNING id INTO prod;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Cliente Fase 0') RETURNING id INTO cli;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 100, 'ci', 'ci');
  PERFORM ci.sair();

  -- R3: comissão não se cria por chamada direta, e o fluxo do pedido entregue segue gerando
  INSERT INTO vendedor_comissao_regras (tenant_id, vendedor_id, percentual, base, ativo) VALUES (demo, vend, 10, 'venda', true);
  PERFORM ci.entrar(vend);
  ped := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 2, 'preco_unitario', 50)));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT comissionar_pedido_id(%L)$c$, ped), 'chamar comissionar_pedido_id direto');
  UPDATE pedidos SET situacao = 'entregue' WHERE id = ped;
  PERFORM ci.exige((SELECT count(*) FROM comissoes WHERE pedido_id = ped) = 1, 'pedido entregue gera a comissão pelo fluxo');
  PERFORM ci.exige((SELECT valor FROM comissoes WHERE pedido_id = ped) = 10, 'comissão de 10% sobre 100');

  -- R4: a mesma venda enviada duas vezes grava uma só
  PERFORM ci.entrar(adm);
  cx := frente_caixa_atual();
  PERFORM ci.exige(cx IS NOT NULL, 'o administrador está com um caixa aberto para a venda de teste');
  SELECT quantidade INTO q_antes FROM estoques WHERE produto_id = prod AND deposito_id = dep;
  SELECT count(*) INTO n_mov_antes FROM caixa_movimentos WHERE caixa_id = cx;
  v1 := frente_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 3, 'preco_unitario', 10)), 'dinheiro', NULL, 0, 1, NULL, NULL, chave_venda);
  v2 := frente_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 3, 'preco_unitario', 10)), 'dinheiro', NULL, 0, 1, NULL, NULL, chave_venda);
  PERFORM ci.sair();
  SELECT quantidade INTO q_depois FROM estoques WHERE produto_id = prod AND deposito_id = dep;
  SELECT count(*) INTO n_mov_depois FROM caixa_movimentos WHERE caixa_id = cx;
  PERFORM ci.exige(v1 = v2, 'reenviar a venda com a mesma chave devolve a mesma venda');
  PERFORM ci.exige((SELECT count(*) FROM pedidos WHERE chave_idempotencia = chave_venda) = 1, 'só uma venda gravada para a chave');
  PERFORM ci.exige(q_antes - q_depois = 3, 'o estoque saiu uma vez só');
  PERFORM ci.exige(n_mov_depois - n_mov_antes = 1, 'o caixa recebeu uma vez só');
  PERFORM ci.entrar(adm);
  v3 := frente_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10)), 'dinheiro', NULL, 0, 1, NULL, NULL, gen_random_uuid());
  PERFORM ci.sair();
  PERFORM ci.exige(v3 <> v1, 'outra chave é outra venda');
  PERFORM ci.exige(ci.contar(adm, format($c$SELECT count(*) FROM pedidos WHERE tenant_id = %L AND chave_idempotencia IS NOT NULL$c$, demo)) = 2, 'a chave fica guardada na venda');

  -- aviso de venda repetida: a tela pergunta se a chave já tem venda antes de reenviar
  PERFORM ci.entrar(adm);
  PERFORM ci.exige((frente_venda_existente(chave_venda) ->> 'pedido_id') = v1::text, 'a chave de uma venda já feita devolve o pedido');
  PERFORM ci.exige((frente_venda_existente(chave_venda) ->> 'numero')::bigint = (SELECT numero FROM pedidos WHERE id = v1), 'e o número dele');
  PERFORM ci.exige(frente_venda_existente(gen_random_uuid()) IS NULL, 'chave sem venda devolve nulo');
  PERFORM ci.exige(frente_venda_existente(NULL) IS NULL, 'sem chave devolve nulo');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(NULL, format($c$SELECT frente_venda_existente(%L)$c$, chave_venda), 'anon consulta venda por chave');
  PERFORM ci.deve_falhar(gar, format($c$SELECT frente_venda_existente(%L)$c$, chave_venda), 'garçom consulta venda por chave');

  -- R2: o andamento da nota não muda por escrita direta; o dono do banco (funções e servidor) muda
  PERFORM ci.entrar(adm);
  nota := gerar_nfe(ped);
  PERFORM ci.sair();
  -- vendedor e caixa emitem a nota do balcão pelas funções, mas não escrevem na tabela: zero linhas
  PERFORM ci.entrar(vend);
  UPDATE nfe SET situacao = 'autorizada' WHERE id = nota;
  GET DIAGNOSTICS n_com = ROW_COUNT;
  UPDATE nfe SET valor_total = 0.01 WHERE id = nota;
  GET DIAGNOSTICS n_nota = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n_com = 0 AND n_nota = 0 AND (SELECT situacao <> 'autorizada' AND valor_total <> 0.01 FROM nfe WHERE id = nota), 'vendedor não reescreve a nota direto na tabela');
  PERFORM ci.entrar(cxa);
  UPDATE nfe SET valor_total = 0.01 WHERE id = nota;
  GET DIAGNOSTICS n_nota = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n_nota = 0, 'caixa não reescreve a nota direto na tabela');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE nfe SET chave = '1234' WHERE id = %L$c$, nota), 'administrador altera a chave da nota');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE nfe SET retorno = '{"x":1}'::jsonb WHERE id = %L$c$, nota), 'administrador altera o retorno do emissor');
  UPDATE nfe SET situacao = 'autorizada', chave = 'CHAVE-CI' WHERE id = nota;
  PERFORM ci.exige((SELECT situacao = 'autorizada' AND chave = 'CHAVE-CI' FROM nfe WHERE id = nota), 'o servidor (dono do banco) registra o retorno da Sefaz');

  -- R5: referências de outra empresa
  INSERT INTO tenants (nome) VALUES ('Fase 0 B') RETURNING id INTO tb;
  INSERT INTO empresas (tenant_id, razao_social) VALUES (tb, 'B Fase 0') RETURNING id INTO eb;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (tb, eb, 'Filial B') RETURNING id INTO fb;
  INSERT INTO clientes (tenant_id, nome) VALUES (tb, 'Cliente B') RETURNING id INTO cb;
  INSERT INTO obras (tenant_id, cliente_id, nome) VALUES (tb, cb, 'Obra B') RETURNING id INTO obb;
  INSERT INTO profissionais (tenant_id, nome) VALUES (tb, 'Profissional B') RETURNING id INTO profb;
  PERFORM ci.deve_falhar(adm, format($c$SELECT abrir_caixa(%L, 0)$c$, fb), 'abrir caixa na filial de outra empresa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT criar_pedido_direto(%L, %L, jsonb_build_array(jsonb_build_object('produto_id', %L, 'quantidade', 1, 'preco_unitario', 10)), %L)$c$, cli, dep, prod, obb), 'pedido com obra de outra empresa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT criar_pedido_direto(%L, %L, jsonb_build_array(jsonb_build_object('produto_id', %L, 'quantidade', 1, 'preco_unitario', 10)), NULL, 0, 0, NULL, NULL, %L)$c$, cli, dep, prod, novo), 'pedido com vendedor de outra empresa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT criar_pedido_direto(%L, %L, jsonb_build_array(jsonb_build_object('produto_id', %L, 'quantidade', 1, 'preco_unitario', 10)), NULL, 0, 0, NULL, NULL, NULL, %L)$c$, cli, dep, prod, profb), 'pedido com profissional de outra empresa');
  -- da mesma empresa segue funcionando
  PERFORM ci.entrar(adm);
  ped2 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10)), NULL, 0, 0, NULL, NULL, vend);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT vendedor_id = vend FROM pedidos WHERE id = ped2), 'pedido com vendedor da própria empresa');

  -- R7: trocar os papéis é uma transação, só pelo administrador, só na própria empresa
  PERFORM ci.entrar(adm);
  PERFORM usuario_definir_papeis(gest, ARRAY['gestor', 'caixa', 'caixa']::app_role[]);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT array_agg(role::text ORDER BY role::text) FROM user_roles WHERE user_id = gest) = ARRAY['caixa', 'gestor'], 'papéis trocados por completo e sem repetir');
  PERFORM ci.deve_falhar(gest, format($c$SELECT usuario_definir_papeis(%L, ARRAY['administrador']::app_role[])$c$, gest), 'gestor se dá o papel de administrador');
  PERFORM ci.deve_falhar(adm, format($c$SELECT usuario_definir_papeis(%L, ARRAY[]::app_role[])$c$, gest), 'trocar para nenhum papel');
  PERFORM ci.deve_falhar(adm, format($c$SELECT usuario_definir_papeis(%L, ARRAY['gestor']::app_role[])$c$, novo), 'trocar papéis de usuário de outra empresa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT usuario_definir_papeis(%L, ARRAY['gestor']::app_role[])$c$, adm), 'administrador tira o próprio perfil de administrador');
  PERFORM ci.deve_falhar(gar, format($c$SELECT usuario_definir_papeis(%L, ARRAY['gestor']::app_role[])$c$, gest), 'garçom troca papéis');
  PERFORM ci.exige((SELECT count(*) FROM user_roles WHERE user_id = gest) = 2, 'tentativas recusadas não mexem nos papéis');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM user_roles WHERE user_id = novo AND role = 'gestor'), 'usuário de outra empresa segue como estava');
  DELETE FROM user_roles WHERE user_id = gest AND role = 'caixa';  -- volta ao que os outros blocos esperam
END $$;

-- 23. Fase 0: papéis valem no banco (tabela aprovada na seção 9 do diagnóstico)
DO $$
DECLARE
  msg_nota text;
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  fin  constant uuid := 'a0000000-0000-0000-0000-0000000000b2';
  logi constant uuid := 'a0000000-0000-0000-0000-0000000000b3';
  mt1  constant uuid := 'a0000000-0000-0000-0000-0000000000b4';
  mt2  constant uuid := 'a0000000-0000-0000-0000-0000000000b5';
  dep uuid; prod uuid; cli uuid; p1 uuid; p2 uuid; p3 uuid; p4 uuid; p5 uuid; nota uuid; mot1 uuid; mot2 uuid; ent uuid;
  item1 uuid; n bigint; contas_antes bigint; papel text; u uuid; q_antes numeric; q_depois numeric;
BEGIN
  INSERT INTO auth.users (id, email) VALUES
    (est, 'est@ci'), (fin, 'fin@ci'), (logi, 'log@ci'), (mt1, 'mt1@ci'), (mt2, 'mt2@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (est, fin, logi, mt1, mt2);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES
    (est, demo, 'estoquista'), (fin, demo, 'financeiro'), (logi, demo, 'logistica'),
    (mt1, demo, 'motorista'), (mt2, demo, 'motorista');
  INSERT INTO motoristas (tenant_id, empresa_id, filial_id, nome, cnh, categoria_cnh, validade_cnh, user_id)
    VALUES (demo, '22222222-2222-2222-2222-222222222222', '33333333-3333-3333-3333-333333333333', 'Motorista 1 CI', '1', 'B', '2030-01-01', mt1) RETURNING id INTO mot1;
  INSERT INTO motoristas (tenant_id, empresa_id, filial_id, nome, cnh, categoria_cnh, validade_cnh, user_id)
    VALUES (demo, '22222222-2222-2222-2222-222222222222', '33333333-3333-3333-3333-333333333333', 'Motorista 2 CI', '2', 'B', '2030-01-01', mt2) RETURNING id INTO mot2;

  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Papéis CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'PAP-ITEM', 'Item Papéis', 'un', 5, 10) RETURNING id INTO prod;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Cliente Papéis') RETURNING id INTO cli;
  PERFORM ci.entrar(est);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 100, 'ci', 'ci');
  PERFORM ci.sair();

  -- estoque: só administrador, gestor e estoquista fazem entrada e ajuste
  FOREACH papel IN ARRAY ARRAY['vendedor', 'caixa', 'financeiro', 'logistica', 'motorista'] LOOP
    u := CASE papel WHEN 'vendedor' THEN vend WHEN 'caixa' THEN cxa WHEN 'financeiro' THEN fin WHEN 'logistica' THEN logi ELSE mt1 END;
    PERFORM ci.deve_falhar(u, format($c$SELECT registrar_movimentacao(%L, %L, 'entrada'::mov_tipo, 1, 'ci', 'ci')$c$, prod, dep), papel || ' dá entrada de estoque');
  END LOOP;
  PERFORM ci.entrar(gest);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 1, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = prod AND deposito_id = dep) = 101, 'estoquista e gestor movimentam o estoque');

  -- quem vende segue baixando e reservando estoque pelo pedido (a função interna não passa pela conferência)
  PERFORM ci.entrar(vend);
  p1 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 2, 'preco_unitario', 10)));
  p2 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 2, 'preco_unitario', 10)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT reservado FROM estoques WHERE produto_id = prod AND deposito_id = dep) = 4, 'o vendedor reserva estoque ao criar o pedido');

  -- aprovar: administrador e gestor
  FOREACH papel IN ARRAY ARRAY['vendedor', 'caixa', 'financeiro', 'logistica', 'motorista', 'estoquista'] LOOP
    u := CASE papel WHEN 'vendedor' THEN vend WHEN 'caixa' THEN cxa WHEN 'financeiro' THEN fin WHEN 'logistica' THEN logi WHEN 'estoquista' THEN est ELSE mt1 END;
    PERFORM ci.deve_falhar(u, format($c$SELECT pedido_avancar_status(%L, 'aprovado')$c$, p1), papel || ' aprova pedido');
  END LOOP;
  PERFORM ci.entrar(gest);
  PERFORM pedido_avancar_status(p1, 'aprovado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = p1) = 'aprovado', 'gestor aprova o pedido');

  -- separar e conferir: administrador, gestor e estoquista (e só eles gravam a separação)
  PERFORM ci.deve_falhar(logi, format($c$SELECT pedido_avancar_status(%L, 'separacao')$c$, p1), 'logística inicia a separação');
  PERFORM ci.entrar(est);
  PERFORM pedido_avancar_status(p1, 'separacao');
  PERFORM ci.sair();
  SELECT id INTO item1 FROM pedido_itens WHERE pedido_id = p1;
  PERFORM ci.entrar(vend);
  UPDATE pedido_itens SET quantidade_separada = 2 WHERE id = item1;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'vendedor não grava a separação');
  PERFORM ci.entrar(est);
  UPDATE pedido_itens SET quantidade_separada = 2 WHERE id = item1;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 1, 'estoquista grava a separação');
  PERFORM ci.deve_falhar(est, format($c$UPDATE pedido_itens SET preco_unitario = 0.01 WHERE id = %L$c$, item1), 'estoquista altera o preço do item');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE pedido_itens SET total = 1 WHERE id = %L$c$, item1), 'administrador altera o total do item direto');
  PERFORM ci.entrar(est);
  PERFORM pedido_avancar_status(p1, 'separado');
  PERFORM pedido_avancar_status(p1, 'conferencia');
  UPDATE pedido_itens SET quantidade_conferida = 2 WHERE id = item1;
  PERFORM pedido_avancar_status(p1, 'pronto_entrega');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = p1) = 'pronto_entrega', 'estoquista leva o pedido até pronto para entrega');

  -- pedido: ninguém grava direto; só as funções
  PERFORM ci.deve_falhar(adm, format($c$UPDATE pedidos SET total = 1, situacao = 'concluido' WHERE id = %L$c$, p1), 'administrador altera o pedido direto');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM pedidos WHERE id = %L$c$, p1), 'administrador apaga o pedido direto');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO pedido_historico (tenant_id, pedido_id, situacao_nova) VALUES (%L, %L, 'concluido')$c$, demo, p1), 'escrever no histórico do pedido direto');

  -- planejar entrega e rota: administrador, gestor e logística; concluir: o motorista só a própria
  PERFORM ci.deve_falhar(vend, format($c$SELECT planejar_entrega(%L, jsonb_build_array(jsonb_build_object('pedido_item_id', %L, 'quantidade', 2)), NULL, %L, current_date)$c$, p1, item1, mot1), 'vendedor planeja entrega');
  PERFORM ci.deve_falhar(mt1, format($c$SELECT planejar_entrega(%L, jsonb_build_array(jsonb_build_object('pedido_item_id', %L, 'quantidade', 2)), NULL, %L, current_date)$c$, p1, item1, mot1), 'motorista planeja entrega');
  PERFORM ci.entrar(logi);
  ent := planejar_entrega(p1, jsonb_build_array(jsonb_build_object('pedido_item_id', item1, 'quantidade', 2)), NULL, mot1, current_date);
  PERFORM ci.sair();
  PERFORM ci.exige(ent IS NOT NULL, 'logística planeja a entrega');
  PERFORM ci.deve_falhar(mt2, format($c$SELECT entrega_concluir(%L, 'Fulano')$c$, ent), 'motorista conclui a entrega de outro');
  PERFORM ci.deve_falhar(mt2, format($c$SELECT entrega_insucesso(%L, 'Cliente ausente')$c$, ent), 'motorista registra insucesso na entrega de outro');
  PERFORM ci.deve_falhar(vend, format($c$SELECT entrega_concluir(%L, 'Fulano')$c$, ent), 'vendedor conclui entrega');
  PERFORM ci.entrar(mt1);
  PERFORM entrega_concluir(ent, 'Fulano');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM entregas WHERE id = ent) = 'entregue', 'o motorista conclui a própria entrega');
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = p1) = 'entregue', 'pedido entregue ao concluir a entrega');

  -- cancelar pedido: administrador e gestor
  PERFORM ci.deve_falhar(vend, format($c$SELECT pedido_avancar_status(%L, 'cancelado', 'x')$c$, p2), 'vendedor cancela pedido');
  PERFORM ci.deve_falhar(est, format($c$SELECT pedido_avancar_status(%L, 'cancelado', 'x')$c$, p2), 'estoquista cancela pedido');
  PERFORM ci.entrar(gest);
  PERFORM pedido_avancar_status(p2, 'cancelado', 'ci');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = p2) = 'cancelado', 'gestor cancela o pedido');

  -- receber o pagamento: caixa, financeiro, gestor e administrador; o recebimento aprova o pedido por dentro
  PERFORM ci.entrar(vend);
  p3 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10)));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pedido_checkout(%L, 10, 'dinheiro')$c$, p3), 'vendedor recebe o pagamento do pedido');
  PERFORM ci.deve_falhar(mt1, format($c$SELECT pedido_checkout(%L, 10, 'dinheiro')$c$, p3), 'motorista recebe o pagamento do pedido');
  PERFORM ci.entrar(cxa);
  PERFORM pedido_checkout(p3, 10, 'dinheiro');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM pedidos WHERE id = p3) = 'aprovado', 'o caixa recebe e o pedido é aprovado, sem ser administrador nem gestor');

  -- contas a receber
  PERFORM ci.entrar(vend);
  p4 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10)));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT gerar_contas_receber(%L, 1, current_date + 30, 'boleto')$c$, p4), 'vendedor gera contas a receber');
  PERFORM ci.deve_falhar(mt1, format($c$SELECT gerar_contas_receber(%L, 1, current_date + 30, 'boleto')$c$, p4), 'motorista gera contas a receber');
  PERFORM ci.entrar(fin);
  PERFORM gerar_contas_receber(p4, 2, current_date + 30, 'boleto');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM contas_receber WHERE pedido_id = p4) = 2, 'financeiro gera as contas a receber');
  PERFORM ci.exige((SELECT array_agg(vencimento ORDER BY parcela) = ARRAY[vencimento_parcela(current_date + 30, 1), vencimento_parcela(current_date + 30, 2)] AND sum(valor) = 10 FROM contas_receber WHERE pedido_id = p4), 'parcelas do pedido vencem mês a mês e somam o total');
  -- a venda a prazo de um vendedor no PDV segue gerando as parcelas (usa a função interna)
  PERFORM ci.entrar(vend);
  p5 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10)), 'crediario', cli, 0, 2, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM contas_receber WHERE pedido_id = p5) = 2, 'venda a prazo no PDV de um vendedor gera as parcelas');
  -- ninguém apaga conta a receber; só quem recebe altera
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM contas_receber WHERE pedido_id = %L$c$, p4), 'apagar conta a receber');
  PERFORM ci.entrar(mt1);
  UPDATE contas_receber SET observacoes = 'x' WHERE pedido_id = p4;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'motorista não altera conta a receber');
  PERFORM ci.entrar(fin);
  UPDATE contas_receber SET observacoes = 'ok' WHERE pedido_id = p4;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 2, 'financeiro altera conta a receber');

  -- nota fiscal: administrador, gestor, financeiro, vendedor e caixa (o balcão emite a nota do PDV)
  FOREACH papel IN ARRAY ARRAY['estoquista', 'logistica', 'motorista'] LOOP
    u := CASE papel WHEN 'estoquista' THEN est WHEN 'logistica' THEN logi ELSE mt1 END;
    PERFORM ci.deve_falhar(u, format($c$SELECT gerar_nfe(%L)$c$, p4), papel || ' emite nota');
  END LOOP;
  PERFORM ci.entrar(fin);
  nota := gerar_nfe(p4);
  PERFORM ci.sair();
  PERFORM ci.exige(nota IS NOT NULL, 'financeiro emite a nota');
  PERFORM ci.entrar(vend);
  PERFORM nfe_calcular_impostos(nota);
  PERFORM ci.sair();
  -- o caixa passa pela conferência de papel: a recusa que sobra é a de nota repetida, não a de permissão
  PERFORM ci.entrar(cxa);
  BEGIN
    PERFORM gerar_nfe(p4);
  EXCEPTION WHEN OTHERS THEN
    msg_nota := SQLERRM;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige(msg_nota LIKE '%já tem nota fiscal%', 'caixa chega à emissão da nota');
  PERFORM ci.deve_falhar(mt1, format($c$SELECT nfe_calcular_impostos(%L)$c$, nota), 'motorista recalcula os impostos da nota');
  PERFORM ci.entrar(fin);
  PERFORM nfe_calcular_impostos(nota);
  PERFORM ci.sair();
  PERFORM ci.entrar(est);
  UPDATE nfe_itens SET aliquota_icms = 99 WHERE nfe_id = nota;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'estoquista não altera item de nota');

  -- preço e custo de produto: administrador e gestor
  PERFORM ci.deve_falhar(est, format($c$UPDATE produtos SET preco_venda = 0.01 WHERE id = %L$c$, prod), 'estoquista muda o preço');
  PERFORM ci.deve_falhar(vend, format($c$UPDATE produtos SET custo = 0.01 WHERE id = %L$c$, prod), 'vendedor muda o custo');
  PERFORM ci.entrar(est);
  UPDATE produtos SET descricao = 'Item Papéis (ok)' WHERE id = prod;
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  UPDATE produtos SET preco_venda = 12 WHERE id = prod;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT preco_venda = 12 FROM produtos WHERE id = prod), 'gestor muda o preço; estoquista muda a descrição');

  -- dados fiscais da empresa e da filial: administrador
  PERFORM ci.entrar(gest);
  UPDATE empresas SET inscricao_estadual = 'GESTOR' WHERE tenant_id = demo;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'gestor não altera os dados da empresa');
  PERFORM ci.entrar(adm);
  UPDATE empresas SET inscricao_estadual = inscricao_estadual WHERE tenant_id = demo;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n >= 1, 'administrador altera os dados da empresa');
  PERFORM ci.deve_falhar(gest, format($c$INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (%L, '22222222-2222-2222-2222-222222222222', 'Filial do gestor')$c$, demo), 'gestor cria filial');

  -- caixa: administrador, gestor e caixa
  PERFORM ci.deve_falhar(fin, format($c$SELECT abrir_caixa('33333333-3333-3333-3333-333333333333', 0)$c$), 'financeiro abre caixa');

  -- inventário: administrador, gestor e estoquista
  PERFORM ci.deve_falhar(vend, format($c$SELECT inventario_aplicar(%L)$c$, gen_random_uuid()), 'vendedor aplica inventário');

  -- o garçom segue fora de tudo isso
  PERFORM ci.deve_falhar(gar, format($c$SELECT gerar_nfe(%L)$c$, p4), 'garçom emite nota');
END $$;

-- 24. Fase 0 / R13: acesso por filial (administrador, gestor e usuário sem filial veem todas; os demais só a própria)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  fa   constant uuid := '33333333-3333-3333-3333-333333333333';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  fb uuid; da uuid; db uuid; dsem uuid; prod uuid; cli uuid; pa uuid; pb uuid; item_b uuid; n bigint;
  itens jsonb;
BEGIN
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Filial R13') RETURNING id INTO fb;
  INSERT INTO depositos (tenant_id, filial_id, nome) VALUES (demo, fa, 'Dep A R13') RETURNING id INTO da;
  INSERT INTO depositos (tenant_id, filial_id, nome) VALUES (demo, fb, 'Dep B R13') RETURNING id INTO db;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Dep geral R13') RETURNING id INTO dsem;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'R13-ITEM', 'Item R13', 'un', 5, 10) RETURNING id INTO prod;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Cliente R13') RETURNING id INTO cli;
  itens := jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10));

  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, da, 'entrada'::mov_tipo, 50, 'ci', 'ci');
  PERFORM registrar_movimentacao(prod, db, 'entrada'::mov_tipo, 50, 'ci', 'ci');
  pa := criar_pedido_direto(cli, da, itens);
  pb := criar_pedido_direto(cli, db, itens);
  PERFORM ci.sair();
  SELECT id INTO item_b FROM pedido_itens WHERE pedido_id = pb;
  PERFORM ci.exige((SELECT filial_id = fb FROM pedidos WHERE id = pb), 'o pedido herda a filial do depósito');

  -- vendedor, caixa e estoquista da filial A
  UPDATE profiles SET filial_id = fa WHERE id IN (vend, cxa, est);
  -- gestor também tem filial no perfil, mas a gestão vê todas
  UPDATE profiles SET filial_id = fa WHERE id = gest;

  -- leitura: só a própria filial (e o que não tem filial)
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM pedidos WHERE id = %L$c$, pa)) = 1, 'vendedor vê o pedido da própria filial');
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM pedidos WHERE id = %L$c$, pb)) = 0, 'vendedor não vê o pedido de outra filial');
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM pedido_itens WHERE pedido_id = %L$c$, pb)) = 0, 'vendedor não vê os itens do pedido de outra filial');
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM depositos WHERE id IN (%L, %L, %L)$c$, da, db, dsem)) = 2, 'vendedor vê o depósito da filial e o geral, não o de outra filial');
  PERFORM ci.exige(ci.contar(est, format($c$SELECT count(*) FROM estoques WHERE deposito_id = %L$c$, db)) = 0, 'estoquista não vê o estoque de outra filial');
  PERFORM ci.exige(ci.contar(est, format($c$SELECT count(*) FROM estoques WHERE deposito_id = %L$c$, da)) = 1, 'estoquista vê o estoque da própria filial');

  -- escrita direta
  PERFORM ci.entrar(vend);
  UPDATE pedido_itens SET quantidade_separada = 1 WHERE id = item_b;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'vendedor não altera item de pedido de outra filial');
  PERFORM ci.entrar(est);
  UPDATE pedido_itens SET quantidade_separada = 1 WHERE id = item_b;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'estoquista da filial A não separa pedido da filial B');

  -- dentro das funções do banco
  PERFORM ci.deve_falhar(vend, format($c$SELECT criar_pedido_direto(%L, %L, %L::jsonb)$c$, cli, db, itens), 'vendedor cria pedido em depósito de outra filial');
  PERFORM ci.entrar(vend);
  PERFORM criar_pedido_direto(cli, da, itens);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(est, format($c$SELECT registrar_movimentacao(%L, %L, 'entrada'::mov_tipo, 5, 'ci', 'ci')$c$, prod, db), 'estoquista dá entrada em depósito de outra filial');
  PERFORM ci.entrar(est);
  PERFORM registrar_movimentacao(prod, da, 'entrada'::mov_tipo, 5, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(cxa, format($c$SELECT abrir_caixa(%L, 0)$c$, fb), 'caixa abre caixa em outra filial');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT pedido_checkout(%L, 10, 'dinheiro'::forma_pagamento, 1, NULL, NULL)$c$, pb), 'caixa recebe pedido de outra filial');

  -- gestão vê e opera todas as filiais, mesmo com filial no perfil
  PERFORM ci.exige(ci.contar(gest, format($c$SELECT count(*) FROM pedidos WHERE id IN (%L, %L)$c$, pa, pb)) = 2, 'gestor vê as duas filiais');
  PERFORM ci.exige(ci.contar(adm, format($c$SELECT count(*) FROM pedidos WHERE id IN (%L, %L)$c$, pa, pb)) = 2, 'administrador vê as duas filiais');
  PERFORM ci.entrar(gest);
  PERFORM pedido_avancar_status(pb, 'aprovado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'aprovado' FROM pedidos WHERE id = pb), 'gestor aprova pedido de outra filial');

  -- usuário sem filial no perfil (matriz) vê todas
  UPDATE profiles SET filial_id = NULL WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM pedidos WHERE id IN (%L, %L)$c$, pa, pb)) = 2, 'usuário sem filial no perfil vê todas');

  -- volta ao que os outros blocos esperam
  UPDATE profiles SET filial_id = NULL WHERE id IN (vend, cxa, est, gest);
END $$;

-- 25. Fase 0 / R10: gravações em etapas viram uma transação só
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  tb   uuid;
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  logi constant uuid := 'a0000000-0000-0000-0000-0000000000b3';
  dep uuid; prod uuid; cli uuid; cli_b uuid; fil uuid; orc uuid; ped1 uuid; ped2 uuid; it1 uuid; it2 uuid; it_outro uuid;
  compra uuid; n_antes bigint; n_depois bigint; itens jsonb; itens_ruins jsonb; prod_b uuid;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Dep R10') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'R10-A', 'Item R10 A', 'un', 5, 10) RETURNING id INTO prod;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Cliente R10') RETURNING id INTO cli;
  INSERT INTO tenants (nome) VALUES ('R10 B') RETURNING id INTO tb;
  INSERT INTO clientes (tenant_id, nome) VALUES (tb, 'Cliente R10 B') RETURNING id INTO cli_b;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (tb, 'R10-B', 'Item R10 B', 'un', 5, 10) RETURNING id INTO prod_b;

  -- filial extra: filial + depósito + configuração fiscal juntos, só o administrador
  UPDATE profiles SET empresa_id = '22222222-2222-2222-2222-222222222222' WHERE id IN (adm, gest);
  PERFORM ci.deve_falhar(gest, $c$SELECT filial_extra_criar('Filial R10')$c$, 'gestor cria filial extra');
  PERFORM ci.deve_falhar(adm, $c$SELECT filial_extra_criar(' ')$c$, 'filial extra sem nome');
  PERFORM ci.entrar(adm);
  fil := filial_extra_criar('Filial R10', 'F10', NULL, NULL, 'Cidade', 'SP');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'implantacao' AND cidade = 'Cidade' FROM filiais WHERE id = fil), 'filial extra criada em implantação');
  PERFORM ci.exige((SELECT count(*) = 1 FROM depositos WHERE filial_id = fil), 'filial extra com o depósito');
  PERFORM ci.exige((SELECT count(*) = 1 FROM fiscal_config WHERE filial_id = fil), 'filial extra com a configuração fiscal');
  UPDATE profiles SET empresa_id = NULL WHERE id IN (adm, gest);

  -- orçamento: cabeçalho + itens + total, ou nada
  itens := jsonb_build_array(
    jsonb_build_object('produto_id', prod, 'quantidade', 2, 'unidade', 'un', 'preco_unitario', 10, 'desconto', 1),
    jsonb_build_object('produto_id', prod, 'quantidade', 1, 'unidade', 'un', 'preco_unitario', 5, 'desconto', 0));
  itens_ruins := jsonb_build_array(
    jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10, 'desconto', 0),
    jsonb_build_object('produto_id', prod_b, 'quantidade', 1, 'preco_unitario', 10, 'desconto', 0));
  PERFORM ci.deve_falhar(est, format($c$SELECT orcamento_salvar(%L, %L::jsonb)$c$, cli, itens), 'estoquista cria orçamento');
  SELECT count(*) INTO n_antes FROM orcamentos WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vend, format($c$SELECT orcamento_salvar(%L, %L::jsonb)$c$, cli, itens_ruins), 'orçamento com produto de outra empresa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT orcamento_salvar(%L, '[]'::jsonb)$c$, cli), 'orçamento sem itens');
  PERFORM ci.deve_falhar(vend, format($c$SELECT orcamento_salvar(%L, %L::jsonb)$c$, cli_b, itens), 'orçamento com cliente de outra empresa');
  SELECT count(*) INTO n_depois FROM orcamentos WHERE tenant_id = demo;
  PERFORM ci.exige(n_antes = n_depois, 'orçamento recusado não deixa cabeçalho para trás');
  PERFORM ci.entrar(vend);
  orc := orcamento_salvar(cli, itens, NULL, NULL, NULL, NULL, '30 dias', NULL, 3, 2, NULL);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT subtotal = 24 AND total = 23 AND situacao = 'rascunho' FROM orcamentos WHERE id = orc), 'total do orçamento calculado no banco (24 - 3 + 2)');
  PERFORM ci.exige((SELECT count(*) = 2 FROM orcamento_itens WHERE orcamento_id = orc), 'orçamento com os dois itens');
  PERFORM ci.exige((SELECT vendedor_id = vend FROM orcamentos WHERE id = orc), 'vendedor padrão é quem salvou');

  -- separação e conferência: todos os itens ou nenhum
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 100, 'ci', 'ci');
  ped1 := criar_pedido_direto(cli, dep, jsonb_build_array(
    jsonb_build_object('produto_id', prod, 'quantidade', 3, 'preco_unitario', 10),
    jsonb_build_object('produto_id', prod, 'quantidade', 4, 'preco_unitario', 10)));
  ped2 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10)));
  PERFORM ci.sair();
  SELECT id INTO it1 FROM pedido_itens WHERE pedido_id = ped1 ORDER BY quantidade LIMIT 1;
  SELECT id INTO it2 FROM pedido_itens WHERE pedido_id = ped1 ORDER BY quantidade DESC LIMIT 1;
  SELECT id INTO it_outro FROM pedido_itens WHERE pedido_id = ped2;
  PERFORM ci.deve_falhar(vend, format($c$SELECT separacao_salvar(%L, '[{"id":"%s","quantidade_separada":1}]'::jsonb)$c$, ped1, it1), 'vendedor salva separação');
  PERFORM ci.deve_falhar(logi, format($c$SELECT conferencia_salvar(%L, '[{"id":"%s","quantidade_conferida":1}]'::jsonb)$c$, ped1, it1), 'logística salva conferência');
  PERFORM ci.deve_falhar(est, format($c$SELECT separacao_salvar(%L, '[{"id":"%s","quantidade_separada":1},{"id":"%s","quantidade_separada":1}]'::jsonb)$c$, ped1, it1, it_outro), 'separação com item de outro pedido');
  PERFORM ci.exige((SELECT quantidade_separada = 0 FROM pedido_itens WHERE id = it1), 'separação recusada não grava nem o item válido');
  PERFORM ci.deve_falhar(est, format($c$SELECT separacao_salvar(%L, '[{"id":"%s","quantidade_separada":-1}]'::jsonb)$c$, ped1, it1), 'separação negativa');
  PERFORM ci.entrar(est);
  PERFORM separacao_salvar(ped1, jsonb_build_array(
    jsonb_build_object('id', it1, 'quantidade_separada', 3), jsonb_build_object('id', it2, 'quantidade_separada', 4)));
  PERFORM conferencia_salvar(ped1, jsonb_build_array(
    jsonb_build_object('id', it1, 'quantidade_conferida', 3, 'divergencia', ''), jsonb_build_object('id', it2, 'quantidade_conferida', 3, 'divergencia', 'faltou 1')));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT sum(quantidade_separada) = 7 FROM pedido_itens WHERE pedido_id = ped1), 'separação grava os dois itens');
  PERFORM ci.exige((SELECT divergencia = 'faltou 1' FROM pedido_itens WHERE id = it2) AND (SELECT divergencia IS NULL FROM pedido_itens WHERE id = it1), 'conferência grava a divergência (vazia vira nula)');

  -- compra: o total acompanha os itens sem chamar o recálculo
  INSERT INTO compras (tenant_id, deposito_id) VALUES (demo, dep) RETURNING id INTO compra;
  INSERT INTO compra_itens (tenant_id, compra_id, produto_id, quantidade, custo_unitario, total) VALUES (demo, compra, prod, 2, 5, 10);
  INSERT INTO compra_itens (tenant_id, compra_id, produto_id, quantidade, custo_unitario, total) VALUES (demo, compra, prod, 1, 7, 7);
  PERFORM ci.exige((SELECT subtotal = 17 AND total = 17 FROM compras WHERE id = compra), 'total da compra acompanha os itens ao incluir');
  UPDATE compra_itens SET quantidade = 3, total = 15 WHERE compra_id = compra AND custo_unitario = 5;
  PERFORM ci.exige((SELECT total = 22 FROM compras WHERE id = compra), 'total da compra acompanha ao alterar o item');
  DELETE FROM compra_itens WHERE compra_id = compra AND custo_unitario = 7;
  PERFORM ci.exige((SELECT total = 15 FROM compras WHERE id = compra), 'total da compra acompanha ao remover o item');
END $$;

-- 26. Importação do XML de entrada: lotes na mesma transação e nota repetida recusada
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  dep uuid; r jsonb; r2 jsonb; prod uuid; nota jsonb; forn jsonb; itens jsonb; lote_qtd numeric; msg text;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Dep XML') RETURNING id INTO dep;
  nota := jsonb_build_object('chave', 'CHAVE-XML-CI-1', 'numero', '9001', 'emissao', current_date, 'frete', 0, 'desconto', 0);
  forn := jsonb_build_object('razao_social', 'Fornecedor XML CI', 'cnpj', '11222333000181');
  itens := jsonb_build_array(
    jsonb_build_object('codigo', 'XML-A', 'descricao', 'Porcelanato XML', 'unidade', 'M2', 'quantidade', 10, 'custo_unitario', 20,
                       'lote', 'L1', 'tonalidade', 'A', 'calibre', '2'),
    jsonb_build_object('codigo', 'XML-B', 'descricao', 'Argamassa XML', 'unidade', 'UN', 'quantidade', 5, 'custo_unitario', 8));

  PERFORM ci.deve_falhar(vend, format($c$SELECT importar_nfe_entrada(%L::jsonb, %L::jsonb, %L::jsonb, %L)$c$, nota, forn, itens, dep), 'vendedor importa nota de entrada');
  PERFORM ci.entrar(adm);
  r := importar_nfe_entrada(nota, forn, itens, dep);
  PERFORM ci.sair();
  PERFORM ci.exige((r->>'produtos_criados')::int = 2, 'a importação cadastra os dois produtos novos');
  SELECT id INTO prod FROM produtos WHERE tenant_id = demo AND codigo_interno = 'XML-A';
  PERFORM ci.exige((SELECT controla_lote FROM produtos WHERE id = prod), 'produto com lote passa a controlar lote');
  SELECT quantidade INTO lote_qtd FROM estoque_lotes WHERE produto_id = prod AND deposito_id = dep AND lote = 'L1' AND tonalidade = 'A' AND calibre = '2';
  PERFORM ci.exige(lote_qtd = 10, 'o lote do XML entra junto com a compra (10)');
  PERFORM ci.exige((SELECT count(*) = 0 FROM estoque_lotes l JOIN produtos p ON p.id = l.produto_id WHERE p.codigo_interno = 'XML-B'), 'item sem lote não cria lote');

  -- contas a pagar da nota: vencimento mensal no mesmo dia e o resto dos centavos na última parcela
  PERFORM ci.entrar(adm);
  r2 := importar_nfe_entrada(nota || jsonb_build_object('chave', 'CHAVE-XML-CI-PARC', 'numero', '9190'), forn, jsonb_build_array(itens -> 1), dep, true, 7, '2027-01-31');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT array_agg(vencimento ORDER BY parcela) = ARRAY['2027-01-31','2027-02-28','2027-03-31','2027-04-30','2027-05-31','2027-06-30','2027-07-31']::date[]
                           AND sum(valor) = (SELECT total FROM compras WHERE id = (r2->>'compra_id')::uuid)
                           AND max(valor) FILTER (WHERE parcela = 7) >= max(valor) FILTER (WHERE parcela = 1)
                      FROM contas_pagar WHERE compra_id = (r2->>'compra_id')::uuid), 'contas a pagar da nota vencem mês a mês e somam o total');

  -- a mesma nota de novo é recusada, e outra nota segue entrando
  PERFORM ci.deve_falhar(adm, format($c$SELECT importar_nfe_entrada(%L::jsonb, %L::jsonb, %L::jsonb, %L)$c$, nota, forn, itens, dep), 'a mesma nota importada de novo');
  PERFORM ci.exige((SELECT count(*) = 1 FROM compras WHERE tenant_id = demo AND nfe_chave = 'CHAVE-XML-CI-1'), 'a nota repetida não gera outra compra');
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoque_lotes WHERE produto_id = prod AND deposito_id = dep AND lote = 'L1'), 'a nota repetida não soma o lote de novo');
  -- mesma nota com outra chave digitada: barrada por número + série + fornecedor
  PERFORM ci.deve_falhar(adm, format($c$SELECT importar_nfe_entrada(%L::jsonb, %L::jsonb, %L::jsonb, %L)$c$,
    nota || jsonb_build_object('chave', 'CHAVE-XML-CI-OUTRA'), forn, itens, dep), 'mesmo número, série e fornecedor com outra chave');
  PERFORM ci.exige((SELECT count(*) = 1 FROM compras WHERE tenant_id = demo AND nfe_numero = '9001'), 'a nota repetida por número não gera outra compra');
  -- CNPJ alfanumérico: dois CNPJs que só mudam nas letras são fornecedores diferentes
  PERFORM ci.entrar(adm);
  PERFORM importar_nfe_entrada(nota || jsonb_build_object('chave', 'CHAVE-XML-CI-ALFA1', 'numero', '9101'),
    jsonb_build_object('razao_social', 'Fornecedor Alfa A', 'cnpj', '12ABC34501DE35'), itens, dep);
  PERFORM importar_nfe_entrada(nota || jsonb_build_object('chave', 'CHAVE-XML-CI-ALFA2', 'numero', '9102'),
    jsonb_build_object('razao_social', 'Fornecedor Alfa B', 'cnpj', '12XYZ34501DE35'), itens, dep);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 2 FROM fornecedores WHERE tenant_id = demo AND cnpj IN ('12ABC34501DE35', '12XYZ34501DE35')),
                   'CNPJs alfanuméricos que só diferem nas letras viram fornecedores distintos');
  -- a mensagem diz que a nota já está importada (pela chave e por número + série + fornecedor)
  PERFORM ci.entrar(adm);
  BEGIN
    PERFORM importar_nfe_entrada(nota, forn, itens, dep);
  EXCEPTION WHEN OTHERS THEN msg := SQLERRM;
  END;
  PERFORM ci.exige(msg LIKE '%já está importada%', 'mensagem da chave repetida: ' || coalesce(msg, 'sem erro'));
  msg := NULL;
  BEGIN
    PERFORM importar_nfe_entrada(nota || jsonb_build_object('chave', 'CHAVE-XML-CI-OUTRA'), forn, itens, dep);
  EXCEPTION WHEN OTHERS THEN msg := SQLERRM;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige(msg LIKE '%nº 9001%já está importada%', 'mensagem do número repetido: ' || coalesce(msg, 'sem erro'));
  -- a tela confere antes de importar, com a mesma regra
  PERFORM ci.entrar(adm);
  PERFORM ci.exige((nfe_entrada_ja_importada('CHAVE-XML-CI-1') ->> 'compra_id') = (r->>'compra_id'), 'conferência pela chave acha a compra');
  PERFORM ci.exige((nfe_entrada_ja_importada('OUTRA', '9001', NULL, '11.222.333/0001-81') ->> 'compra_id') = (r->>'compra_id'), 'conferência por número, série e CNPJ acha a compra');
  PERFORM ci.exige(nfe_entrada_ja_importada('OUTRA', '9001', '7', '11222333000181') IS NULL, 'outra série não é duplicada');
  PERFORM ci.exige(nfe_entrada_ja_importada('OUTRA', '9001', NULL, '55555555000155') IS NULL, 'outro fornecedor não é duplicada');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, $c$SELECT nfe_entrada_ja_importada('CHAVE-XML-CI-1')$c$, 'vendedor confere nota de entrada');
  -- outra série do mesmo número é outra nota
  PERFORM ci.entrar(adm);
  PERFORM importar_nfe_entrada(nota || jsonb_build_object('chave', 'CHAVE-XML-CI-S2', 'serie', '2'), forn,
    jsonb_build_array(jsonb_build_object('codigo', 'XML-D', 'descricao', 'Cimento XML', 'unidade', 'UN', 'quantidade', 1, 'custo_unitario', 3)), dep);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT nfe_serie = '2' FROM compras WHERE nfe_chave = 'CHAVE-XML-CI-S2'), 'a série da nota fica guardada na compra');
  PERFORM ci.deve_falhar(adm, format($c$SELECT importar_nfe_entrada(%L::jsonb, %L::jsonb, %L::jsonb, %L)$c$,
    nota || jsonb_build_object('chave', 'CHAVE-XML-CI-S2B', 'serie', '2'), forn, itens, dep), 'mesmo número e série 2 de novo');
  -- de outro fornecedor, o mesmo número é outra nota
  PERFORM ci.entrar(adm);
  PERFORM importar_nfe_entrada(nota || jsonb_build_object('chave', 'CHAVE-XML-CI-F2'), forn || jsonb_build_object('cnpj', '99888777000166', 'razao_social', 'Outro Fornecedor XML'),
    jsonb_build_array(jsonb_build_object('codigo', 'XML-E', 'descricao', 'Areia XML', 'unidade', 'UN', 'quantidade', 1, 'custo_unitario', 3)), dep);
  PERFORM ci.sair();
  PERFORM ci.entrar(adm);
  r2 := importar_nfe_entrada(nota || jsonb_build_object('chave', 'CHAVE-XML-CI-2', 'numero', '9002'), forn,
    jsonb_build_array(jsonb_build_object('codigo', 'XML-C', 'descricao', 'Rejunte XML', 'unidade', 'UN', 'quantidade', 3, 'custo_unitario', 4)), dep);
  PERFORM ci.sair();
  PERFORM ci.exige((r2->>'compra_id') <> (r->>'compra_id'), 'outra nota importa normalmente depois');
END $$;

-- 27. R11: peças da ordem de serviço baixam o estoque
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  dep uuid; prod uuid; os uuid; os2 uuid; os3 uuid; os4 uuid; it1 uuid; it2 uuid; it3 uuid;
  msg text;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Dep OS R11') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'R11-PECA', 'Peça R11', 'un', 5, 10) RETURNING id INTO prod;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 10, 'ci', 'ci');
  PERFORM ci.sair();

  INSERT INTO os_ordens (tenant_id, equipamento, deposito_id, situacao) VALUES (demo, 'Furadeira R11', dep, 'orcamento') RETURNING id INTO os;
  INSERT INTO os_itens (tenant_id, os_id, tipo, produto_id, descricao, quantidade, preco_unitario, total)
    VALUES (demo, os, 'peca', prod, 'Peça R11', 3, 10, 30) RETURNING id INTO it1;
  INSERT INTO os_itens (tenant_id, os_id, tipo, descricao, quantidade, preco_unitario, total) VALUES (demo, os, 'servico', 'Mão de obra', 1, 50, 50);
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'orçamento não baixa o estoque');

  -- aprovada: baixa uma vez
  PERFORM ci.entrar(adm);
  UPDATE os_ordens SET situacao = 'aprovada' WHERE id = os;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 7 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'aprovar a OS baixa a peça (10 - 3)');
  PERFORM ci.exige((SELECT baixa_quantidade = 3 FROM os_itens WHERE id = it1), 'o item guarda o que foi baixado');
  PERFORM ci.entrar(adm);
  UPDATE os_ordens SET situacao = 'em_reparo' WHERE id = os;
  UPDATE os_ordens SET situacao = 'pronta', diagnostico = 'x' WHERE id = os;
  PERFORM ci.exige((SELECT quantidade = 7 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'mudar de etapa não baixa de novo');
  PERFORM ci.exige((SELECT count(*) = 1 FROM estoque_movimentacoes WHERE produto_id = prod AND tipo = 'saida' AND documento LIKE 'OS nº%'), 'uma saída só no histórico de movimentações');

  -- peça incluída, alterada e removida depois da aprovação
  INSERT INTO os_itens (tenant_id, os_id, tipo, produto_id, descricao, quantidade, preco_unitario, total)
    VALUES (demo, os, 'peca', prod, 'Peça R11 extra', 2, 10, 20) RETURNING id INTO it2;
  PERFORM ci.exige((SELECT quantidade = 5 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'peça incluída depois da aprovação baixa na hora');
  UPDATE os_itens SET quantidade = 4, total = 40 WHERE id = it1;
  PERFORM ci.exige((SELECT quantidade = 4 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'quantidade alterada acompanha o estoque (3 vira 4)');
  DELETE FROM os_itens WHERE id = it2;
  PERFORM ci.exige((SELECT quantidade = 6 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'peça removida devolve ao estoque');

  -- o cliente não escreve o que foi baixado
  UPDATE os_itens SET baixa_quantidade = 0, baixa_produto_id = NULL WHERE id = it1;
  PERFORM ci.exige((SELECT baixa_quantidade = 4 AND baixa_produto_id = prod FROM os_itens WHERE id = it1), 'o usuário não altera o registro da baixa');

  -- cancelar devolve; reabrir baixa de novo
  UPDATE os_ordens SET situacao = 'cancelada' WHERE id = os;
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'cancelar a OS devolve as peças');
  PERFORM ci.exige((SELECT baixa_quantidade IS NULL FROM os_itens WHERE id = it1), 'cancelada: nada fica como baixado');
  UPDATE os_ordens SET situacao = 'aprovada' WHERE id = os;
  PERFORM ci.exige((SELECT quantidade = 6 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'reaprovar baixa de novo');
  UPDATE os_ordens SET situacao = 'orcamento' WHERE id = os;
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'voltar para orçamento devolve as peças');

  PERFORM ci.sair();

  -- sem depósito: não aprova
  INSERT INTO os_ordens (tenant_id, equipamento, situacao) VALUES (demo, 'Sem depósito R11', 'orcamento') RETURNING id INTO os2;
  INSERT INTO os_itens (tenant_id, os_id, tipo, produto_id, descricao, quantidade, preco_unitario, total) VALUES (demo, os2, 'peca', prod, 'Peça', 1, 10, 10);
  PERFORM ci.entrar(adm);
  BEGIN
    UPDATE os_ordens SET situacao = 'aprovada' WHERE id = os2;
  EXCEPTION WHEN OTHERS THEN msg := SQLERRM;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige(msg LIKE '%Escolha o depósito%', 'aprovar sem depósito é recusado: ' || coalesce(msg, 'sem erro'));
  PERFORM ci.exige((SELECT situacao = 'orcamento' FROM os_ordens WHERE id = os2), 'a OS recusada segue em orçamento');

  -- estoque insuficiente: não aprova e não baixa nada
  INSERT INTO os_ordens (tenant_id, equipamento, deposito_id, situacao) VALUES (demo, 'Sem saldo R11', dep, 'orcamento') RETURNING id INTO os3;
  INSERT INTO os_itens (tenant_id, os_id, tipo, produto_id, descricao, quantidade, preco_unitario, total) VALUES (demo, os3, 'peca', prod, 'Peça', 1, 10, 10);
  INSERT INTO os_itens (tenant_id, os_id, tipo, produto_id, descricao, quantidade, preco_unitario, total) VALUES (demo, os3, 'peca', prod, 'Peça demais', 500, 10, 5000);
  msg := NULL;
  PERFORM ci.entrar(adm);
  BEGIN
    UPDATE os_ordens SET situacao = 'aprovada' WHERE id = os3;
  EXCEPTION WHEN OTHERS THEN msg := SQLERRM;
  END;
  PERFORM ci.sair();
  PERFORM ci.exige(msg LIKE '%insuficiente%', 'aprovar sem saldo é recusado: ' || coalesce(msg, 'sem erro'));
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'a aprovação recusada não baixa nem a peça que tinha saldo');

  -- OS antiga (já existia antes da regra) não mexe no estoque
  INSERT INTO os_ordens (tenant_id, equipamento, deposito_id, situacao, controla_estoque) VALUES (demo, 'Antiga R11', dep, 'entregue', false) RETURNING id INTO os4;
  INSERT INTO os_itens (tenant_id, os_id, tipo, produto_id, descricao, quantidade, preco_unitario, total) VALUES (demo, os4, 'peca', prod, 'Peça', 1, 10, 10);
  UPDATE os_ordens SET situacao = 'pronta' WHERE id = os4;
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'OS antiga não movimenta o estoque');
END $$;

-- 28. R12: auditoria do financeiro, do fiscal, da empresa e dos papéis
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  fin  constant uuid := 'a0000000-0000-0000-0000-0000000000b2';
  cr uuid; cp uuid; nota uuid; cfg uuid; tx uuid; ux uuid; n_antes bigint; v jsonb;
BEGIN
  INSERT INTO contas_receber (tenant_id, descricao, vencimento, valor) VALUES (demo, 'Conta R12', current_date, 100) RETURNING id INTO cr;
  INSERT INTO contas_pagar (tenant_id, descricao, vencimento, valor) VALUES (demo, 'Pagar R12', current_date, 80) RETURNING id INTO cp;

  -- alteração feita por um usuário: quem, o quê (antes e depois)
  PERFORM ci.entrar(fin);
  -- a baixa passa pela função (o cliente não muda mais valor recebido nem situação direto)
  PERFORM baixar_conta('receber', cr, 100, 'pix');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT usuario_id = fin AND valor_novo ->> 'situacao' = 'pago' AND valor_anterior ->> 'situacao' IS NOT NULL
                      FROM auditoria WHERE entidade = 'contas_receber' AND entidade_id = cr AND operacao = 'update'),
                   'baixa de conta a receber fica registrada com o usuário, o antes e o depois');

  -- campo fora da lista não gera registro
  SELECT count(*) INTO n_antes FROM auditoria WHERE entidade = 'contas_receber' AND entidade_id = cr;
  UPDATE contas_receber SET observacoes = 'só uma nota' WHERE id = cr;
  PERFORM ci.exige((SELECT count(*) = n_antes FROM auditoria WHERE entidade = 'contas_receber' AND entidade_id = cr), 'campo fora da lista não gera registro');

  -- exclusão
  UPDATE contas_pagar SET valor = 90 WHERE id = cp;
  DELETE FROM contas_pagar WHERE id = cp;
  PERFORM ci.exige((SELECT (valor_anterior ->> 'valor')::numeric = 90 FROM auditoria WHERE entidade = 'contas_pagar' AND entidade_id = cp AND operacao = 'delete'),
                   'exclusão de conta a pagar fica registrada com os valores que tinha');
  PERFORM ci.exige((SELECT count(*) = 2 FROM auditoria WHERE entidade = 'contas_pagar' AND entidade_id = cp), 'conta a pagar: alteração e exclusão');

  -- nota fiscal
  SELECT id INTO nota FROM nfe WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE nfe SET cfop = '5949' WHERE id = nota;
  PERFORM ci.exige((SELECT valor_novo ->> 'cfop' = '5949' FROM auditoria WHERE entidade = 'nfe' AND entidade_id = nota AND operacao = 'update' ORDER BY created_at DESC LIMIT 1),
                   'mudança na nota fiscal fica registrada');

  -- configuração fiscal: segredo mascarado, contador de numeração fora
  INSERT INTO fiscal_config (tenant_id, empresa_id, filial_id) VALUES (demo, emp, '33333333-3333-3333-3333-333333333333')
    ON CONFLICT DO NOTHING;
  SELECT id INTO cfg FROM fiscal_config WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE fiscal_config SET nfse_token = 'SEGREDO-123', ambiente = 'producao' WHERE id = cfg;
  v := (SELECT valor_novo FROM auditoria WHERE entidade = 'fiscal_config' AND entidade_id = cfg AND operacao = 'update' AND valor_novo ? 'ambiente' LIMIT 1);
  PERFORM ci.exige(v ->> 'nfse_token' = '***' AND v ->> 'ambiente' = 'producao', 'configuração fiscal: ambiente registrado e token mascarado');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM auditoria WHERE valor_novo::text LIKE '%SEGREDO-123%' OR valor_anterior::text LIKE '%SEGREDO-123%'), 'o token não aparece em nenhum registro');
  -- alteração de um campo só da NFS-e também é registrada
  UPDATE fiscal_config SET nfse_iss_retido = NOT coalesce(nfse_iss_retido, false) WHERE id = cfg;
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'fiscal_config' AND entidade_id = cfg AND operacao = 'update'
                             AND valor_novo ? 'nfse_iss_retido' AND NOT (valor_novo ? 'ambiente')),
                   'mudança só de um campo da NFS-e fica registrada');
  SELECT count(*) INTO n_antes FROM auditoria WHERE entidade = 'fiscal_config' AND entidade_id = cfg;
  UPDATE fiscal_config SET proximo_numero_nfse = coalesce(proximo_numero_nfse, 1) + 1 WHERE id = cfg;
  UPDATE fiscal_config SET proximo_numero = proximo_numero + 1 WHERE id = cfg;
  PERFORM ci.exige((SELECT count(*) = n_antes FROM auditoria WHERE entidade = 'fiscal_config' AND entidade_id = cfg), 'o contador de numeração da nota não gera registro');

  -- empresa e filiais
  UPDATE empresas SET regime_tributario = 'lucro_presumido' WHERE id = emp;
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'empresas' AND entidade_id = emp AND valor_novo ->> 'regime_tributario' = 'lucro_presumido'),
                   'mudança de regime tributário da empresa fica registrada');
  UPDATE empresas SET regime_tributario = 'simples' WHERE id = emp;

  -- papéis dos usuários
  UPDATE profiles SET empresa_id = emp WHERE id = adm;
  PERFORM ci.entrar(adm);
  PERFORM usuario_definir_papeis(gest, ARRAY['gestor', 'financeiro']::app_role[]);
  PERFORM ci.sair();
  UPDATE profiles SET empresa_id = NULL WHERE id = adm;
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'user_roles' AND operacao = 'insert' AND usuario_id = adm
                             AND valor_novo ->> 'user_id' = gest::text AND valor_novo ->> 'role' = 'financeiro'),
                   'papel dado a um usuário fica registrado com quem deu');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'user_roles' AND operacao = 'delete' AND usuario_id = adm
                             AND valor_anterior ->> 'user_id' = gest::text),
                   'papel retirado de um usuário fica registrado');
  DELETE FROM user_roles WHERE user_id = gest AND role = 'financeiro';
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'user_roles' AND operacao = 'delete' AND valor_anterior ->> 'role' = 'financeiro'), 'remoção direta de papel também é registrada');

  -- só administrador e gestor leem; ninguém grava
  PERFORM ci.exige(ci.contar(fin, $c$SELECT count(*) FROM auditoria WHERE entidade = 'user_roles'$c$) = 0, 'financeiro não lê a auditoria');
  PERFORM ci.exige(ci.contar(adm, $c$SELECT count(*) FROM auditoria WHERE entidade = 'user_roles'$c$) > 0, 'administrador lê a auditoria dos papéis');

  -- apagar uma empresa inteira (cascata) não quebra pela auditoria
  INSERT INTO tenants (nome) VALUES ('R12 apagar') RETURNING id INTO tx;
  INSERT INTO empresas (tenant_id, razao_social) VALUES (tx, 'Empresa R12 apagar');
  DELETE FROM tenants WHERE id = tx;
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM tenants WHERE id = tx), 'apagar a empresa em cascata funciona com a auditoria ligada');
END $$;

-- 29. R14: formulário público de contato com limite de envios e CAPTCHA (só o servidor da aplicação envia)
DO $$
DECLARE
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  n_antes bigint; ok boolean; msg text; i int;
  antes timestamptz := now() - interval '10 seconds';
BEGIN
  DELETE FROM contatos;

  -- a gravação direta e a chamada pública fecharam: só o servidor (chave de serviço) envia
  PERFORM ci.deve_falhar(NULL, $c$INSERT INTO contatos (nome, email) VALUES ('Direto', 'a@b.co')$c$, 'anon grava direto em contatos');
  PERFORM ci.deve_falhar(NULL, $c$SELECT contato_enviar('Anon', 'a@b.co')$c$, 'anon chama contato_enviar');
  PERFORM ci.deve_falhar(adm, $c$SELECT contato_enviar('Logado', 'a@b.co')$c$, 'usuário logado chama contato_enviar');

  -- o servidor da aplicação (service_role) envia
  SET LOCAL ROLE service_role;
  ok := contato_enviar('Maria Souza', 'maria@loja.com.br', '(16) 99999-1234', 'loja', 'Quero conhecer', NULL, now() - interval '30 seconds', '203.0.113.50');
  RESET ROLE;
  PERFORM ci.exige(ok AND (SELECT count(*) = 1 FROM contatos WHERE email = 'maria@loja.com.br'), 'o servidor envia o contato');
  PERFORM ci.exige(ci.contar(NULL, 'SELECT count(*) FROM contatos') = 0, 'anon não enxerga os contatos');

  -- robô: campo escondido preenchido finge sucesso e não grava
  SELECT count(*) INTO n_antes FROM contatos;
  ok := contato_enviar('Robô', 'robo@spam.com', NULL, NULL, 'compre já', 'http://spam', now() - interval '30 seconds');
  PERFORM ci.exige(ok AND (SELECT count(*) = n_antes FROM contatos), 'campo escondido preenchido não grava');
  -- rápido demais
  PERFORM ci.deve_falhar_dono(format($c$SELECT contato_enviar('Rápido', 'r@r.co', NULL, NULL, NULL, NULL, %L)$c$, now()), 'envio antes de 3 segundos');

  -- validações
  PERFORM ci.deve_falhar_dono($c$SELECT contato_enviar('A', 'a@b.co')$c$, 'nome curto');
  PERFORM ci.deve_falhar_dono($c$SELECT contato_enviar('Fulano')$c$, 'sem e-mail nem WhatsApp');
  PERFORM ci.deve_falhar_dono($c$SELECT contato_enviar('Fulano', 'sem-arroba')$c$, 'e-mail inválido');
  PERFORM ci.deve_falhar_dono($c$SELECT contato_enviar('Fulano', NULL, '123')$c$, 'WhatsApp inválido');
  PERFORM ci.deve_falhar_dono(format($c$SELECT contato_enviar('Fulano', 'f@f.co', NULL, NULL, %L)$c$, repeat('x', 2001)), 'mensagem muito longa');

  -- o mesmo contato de novo em 10 minutos é um só
  SELECT count(*) INTO n_antes FROM contatos;
  ok := contato_enviar('Maria Souza', 'maria@loja.com.br', '(16) 99999-1234', 'loja', 'Quero conhecer', NULL, now() - interval '30 seconds', '203.0.113.50');
  PERFORM ci.exige(ok AND (SELECT count(*) = n_antes FROM contatos), 'contato repetido em 10 minutos não duplica');

  -- limite por origem (hash do IP informado pelo servidor, nunca o IP): 5 por hora
  FOR i IN 1..5 LOOP
    PERFORM contato_enviar('Origem ' || i, 'o' || i || '@teste.co', NULL, NULL, 'mensagem ' || i, NULL, antes, '203.0.113.9');
  END LOOP;
  PERFORM ci.exige((SELECT count(*) = 5 FROM contatos WHERE origem = md5('contato:203.0.113.9')), 'cinco envios do mesmo IP entram');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM contatos WHERE origem LIKE '%203.0.113%'), 'o IP não é guardado, só o hash');
  BEGIN
    PERFORM contato_enviar('Origem 6', 'o6@teste.co', NULL, NULL, 'mensagem 6', NULL, antes, '203.0.113.9');
  EXCEPTION WHEN OTHERS THEN msg := SQLERRM;
  END;
  PERFORM ci.exige(msg LIKE 'Muitos envios deste aparelho%', 'o sexto envio do mesmo IP é recusado: ' || coalesce(msg, 'sem erro'));
  -- outro IP segue entrando
  ok := contato_enviar('Outra origem', 'outra@teste.co', NULL, NULL, 'oi', NULL, antes, '198.51.100.7');
  PERFORM ci.exige(ok, 'outro IP não é afetado pelo limite');

  -- sem IP informado, vale o cabeçalho da chamada
  PERFORM set_config('request.headers', '{"x-forwarded-for":"192.0.2.44, 10.0.0.1"}', true);
  PERFORM contato_enviar('Pelo cabeçalho', 'cab@teste.co', NULL, NULL, 'oi cabeçalho', NULL, antes);
  PERFORM ci.exige(EXISTS (SELECT 1 FROM contatos WHERE email = 'cab@teste.co' AND origem = md5('contato:192.0.2.44')), 'sem IP informado usa o cabeçalho');

  -- limite total: 100 por hora
  PERFORM set_config('request.headers', '', true);
  INSERT INTO contatos (nome, email) SELECT 'Carga ' || g, 'c' || g || '@carga.co' FROM generate_series(1, 100) g;
  msg := NULL;
  BEGIN
    PERFORM contato_enviar('Fulano', 'novo@teste.co', NULL, NULL, 'uma a mais', NULL, antes, '198.51.100.99');
  EXCEPTION WHEN OTHERS THEN msg := SQLERRM;
  END;
  PERFORM ci.exige(msg LIKE 'Estamos recebendo muitos contatos%', 'passou de 100 por hora no total: recusa: ' || coalesce(msg, 'sem erro'));

  DELETE FROM contatos;
END $$;

-- 30. Salvar empresa numa transação só
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  novo_adm constant uuid := 'a0000000-0000-0000-0000-0000000000c1';
  emp uuid; emp2 uuid; razao_antes text; tel_antes text; tx uuid; n_antes bigint;
BEGIN
  SELECT id, razao_social, telefone INTO emp, razao_antes, tel_antes FROM empresas WHERE tenant_id = demo ORDER BY created_at, id LIMIT 1;

  -- só o administrador
  PERFORM ci.deve_falhar(gest, $c$SELECT empresa_salvar('{"razao_social":"Gestor muda"}'::jsonb)$c$, 'gestor salva a empresa');
  PERFORM ci.deve_falhar(vend, $c$SELECT empresa_salvar('{"razao_social":"Vendedor muda"}'::jsonb)$c$, 'vendedor salva a empresa');
  PERFORM ci.deve_falhar(NULL, $c$SELECT empresa_salvar('{"razao_social":"Anon muda"}'::jsonb)$c$, 'anon salva a empresa');

  -- recusas não mexem em nada
  PERFORM ci.deve_falhar(adm, $c$SELECT empresa_salvar('{"razao_social":"  "}'::jsonb)$c$, 'razão social em branco');
  PERFORM ci.deve_falhar(adm, $c$SELECT empresa_salvar('{"razao_social":"Cor ruim","cor_primaria":"vermelho"}'::jsonb)$c$, 'cor inválida');
  PERFORM ci.exige((SELECT razao_social = razao_antes FROM empresas WHERE id = emp), 'recusa não altera a empresa');

  -- atualização: empresa e regime da configuração fiscal juntos; o que não veio fica como estava
  PERFORM ci.entrar(adm);
  emp2 := empresa_salvar(jsonb_build_object('razao_social', 'Empresa Salva R8', 'regime_tributario', 'lucro_presumido',
                                            'cidade', 'Ribeirão Preto', 'cor_primaria', '#112233'));
  PERFORM ci.sair();
  PERFORM ci.exige(emp2 = emp, 'atualiza a empresa que já existe, sem criar outra');
  PERFORM ci.exige((SELECT razao_social = 'Empresa Salva R8' AND regime_tributario = 'lucro_presumido' AND cidade = 'Ribeirão Preto'
                           AND cor_primaria = '#112233' AND telefone IS NOT DISTINCT FROM tel_antes FROM empresas WHERE id = emp),
                   'dados salvos e campo ausente mantido');
  PERFORM ci.exige((SELECT count(*) = 1 AND bool_and(regime_tributario = 'lucro_presumido') FROM fiscal_config
                     WHERE empresa_id = emp AND filial_id IS NULL), 'o regime da configuração fiscal acompanha o cadastro');
  PERFORM ci.exige((SELECT count(*) = 1 FROM empresas WHERE tenant_id = demo AND razao_social = 'Empresa Salva R8'), 'continua uma empresa só');
  SELECT count(*) INTO n_antes FROM fiscal_config WHERE empresa_id = emp AND filial_id IS NULL;
  PERFORM ci.entrar(adm);
  PERFORM empresa_salvar(jsonb_build_object('razao_social', 'Empresa Salva R8', 'regime_tributario', 'simples'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = n_antes AND bool_and(regime_tributario = 'simples') FROM fiscal_config WHERE empresa_id = emp AND filial_id IS NULL),
                   'salvar de novo atualiza a mesma configuração fiscal');
  UPDATE empresas SET razao_social = razao_antes, regime_tributario = 'simples' WHERE id = emp;

  -- primeiro cadastro: cria a empresa, vincula o administrador e cria a configuração fiscal
  INSERT INTO tenants (nome) VALUES ('Primeiro acesso R8') RETURNING id INTO tx;
  INSERT INTO auth.users (id, email) VALUES (novo_adm, 'novoadm@ci');
  UPDATE profiles SET tenant_id = tx WHERE id = novo_adm;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (novo_adm, tx, 'administrador');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM empresas WHERE tenant_id = tx), 'o primeiro acesso começa sem empresa');
  PERFORM ci.entrar(novo_adm);
  emp2 := empresa_salvar(jsonb_build_object('razao_social', 'Loja Nova R8', 'cnpj', '12345678000195', 'regime_tributario', 'simples_excesso'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT razao_social = 'Loja Nova R8' AND tenant_id = tx AND cor_primaria = '#008037' AND ramo_atividade = 'construcao' FROM empresas WHERE id = emp2),
                   'primeiro cadastro cria a empresa na empresa do administrador, com os padrões');
  PERFORM ci.exige((SELECT empresa_id = emp2 FROM profiles WHERE id = novo_adm), 'o administrador passa a pertencer à empresa');
  PERFORM ci.exige((SELECT count(*) = 1 AND bool_and(regime_tributario = 'simples_excesso' AND tenant_id = tx) FROM fiscal_config
                     WHERE empresa_id = emp2 AND filial_id IS NULL), 'o primeiro cadastro cria a configuração fiscal com o regime');
  PERFORM ci.exige((SELECT razao_social = razao_antes FROM empresas WHERE id = emp), 'a empresa de outro cliente não foi tocada');
END $$;

-- 31. Fase 2 / NFC-e: configuração com CSC secreto, nota modelo 65 criada pelo pedido, numeração própria e eventos pendentes
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  dep uuid; prod uuid; cli uuid; ped uuid; ped2 uuid; ped3 uuid; ped4 uuid; ped5 uuid; ped6 uuid; ped7 uuid; ped8 uuid; n7 uuid; n8 uuid; aut1 uuid; aut2 uuid; aut3 uuid; fil_emit uuid; n1 uuid; n1b uuid; n2 uuid; n3 uuid; emp uuid; cfg uuid; tb uuid;
  n_linhas bigint;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'NFC-e CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, ncm, cst_csosn)
  VALUES (demo, 'NFCE-1', 'Item NFC-e', 'un', 5, '12345678', '102') RETURNING id INTO prod;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Cliente NFC-e') RETURNING id INTO cli;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 100, 'ci', 'ci');
  ped := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 2, 'preco_unitario', 50)));
  ped2 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 30)));
  ped3 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 20)));
  PERFORM ci.sair();
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at, id LIMIT 1;
  UPDATE empresas SET cnpj = '12345678000195', inscricao_estadual = '111222333', estado = 'SP' WHERE id = emp;

  -- papéis: quem emite no balcão pode; garçom e anon não
  PERFORM ci.deve_falhar(gar, format($c$SELECT nfce_criar(%L)$c$, ped), 'garçom cria NFC-e');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT nfce_criar(%L)$c$, ped), 'anon cria NFC-e');

  -- sem CSC, certificado e emissor: nota em rascunho, sem número (a sequência não é gasta)
  PERFORM ci.entrar(vend);
  n1 := nfce_criar(ped);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT modelo = 'nfce' AND situacao = 'rascunho' AND numero IS NULL AND valor_total = 100
                           AND 'CSC da NFC-e (código e token) não configurado' = ANY (pendencias)
                           AND 'Certificado digital A1 não configurado' = ANY (pendencias) FROM nfe WHERE id = n1),
                   'sem CSC e certificado a NFC-e fica em rascunho, com as pendências, sem número');
  PERFORM ci.exige((SELECT count(*) = 1 FROM nfe_itens WHERE nfe_id = n1), 'a NFC-e leva os itens do pedido');
  SELECT id INTO cfg FROM fiscal_config WHERE empresa_id = emp AND filial_id IS NULL ORDER BY created_at LIMIT 1;
  PERFORM ci.exige((SELECT proximo_numero = 1 FROM nfce_config WHERE fiscal_config_id = cfg), 'rascunho não gasta número');

  -- configura (como o dono do banco); o pedido volta a ser montado e fica pronto
  UPDATE fiscal_config SET certificado_nome = 'cert.pfx', emissor = 'acbr' WHERE id = cfg;
  UPDATE nfce_config SET csc_id = '1', csc_token = 'SEGREDOCSC0123456789', serie = 3 WHERE fiscal_config_id = cfg;
  PERFORM ci.entrar(vend);
  n1b := nfce_criar(ped);
  PERFORM ci.sair();
  PERFORM ci.exige(n1b <> n1 AND NOT EXISTS (SELECT 1 FROM nfe WHERE id = n1), 'o rascunho é refeito, não duplicado');
  PERFORM ci.exige((SELECT situacao = 'pronta' AND numero = 1 AND serie = 3 AND pendencias = '{}' FROM nfe WHERE id = n1b),
                   'com tudo configurado a NFC-e fica pronta, série 3, número 1');

  -- repetir devolve a mesma nota e não gasta outro número
  PERFORM ci.entrar(cxa);
  n2 := nfce_criar(ped);
  PERFORM ci.sair();
  PERFORM ci.exige(n2 = n1b, 'repetir a criação devolve a mesma NFC-e');
  PERFORM ci.exige((SELECT proximo_numero = 2 FROM nfce_config WHERE fiscal_config_id = cfg), 'a sequência andou uma vez só');

  -- outro pedido: próximo número; CPF identificado vai na nota; CPF ruim vira pendência
  PERFORM ci.entrar(adm);
  n3 := nfce_criar(ped2, '123.456.789-09');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT numero = 2 AND situacao = 'pronta' AND destinatario ->> 'cpf' = '12345678909' FROM nfe WHERE id = n3),
                   'segundo pedido leva o número 2 e o CPF do consumidor');
  PERFORM ci.entrar(adm);
  n3 := nfce_criar(ped3, '123');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'rascunho' AND numero IS NULL AND 'CPF do consumidor inválido' = ANY (pendencias) FROM nfe WHERE id = n3),
                   'CPF inválido deixa a nota em rascunho');

  -- venda do balcão (frente de caixa, sem cliente): o caixa e o vendedor também criam a NFC-e dela
  PERFORM ci.entrar(adm);
  ped6 := frente_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 2, 'preco_unitario', 12)), 'dinheiro', NULL, 0, 1, NULL, NULL, gen_random_uuid());
  PERFORM ci.sair();
  PERFORM ci.entrar(cxa);
  n3 := nfce_criar(ped6, '52998224725');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT modelo = 'nfce' AND valor_total = 24 AND destinatario ->> 'cpf' = '52998224725'
                      FROM nfe WHERE id = n3), 'o caixa cria a NFC-e da venda do balcão, com o CPF do consumidor');
  PERFORM ci.entrar(vend);
  PERFORM ci.exige(nfce_criar(ped6) = n3, 'repetir pelo vendedor devolve a mesma NFC-e');
  PERFORM ci.sair();

  -- cancelar a venda com NFC-e: pronta fica cancelada, rascunho é apagada, enviada à Sefaz impede
  INSERT INTO gestor_autorizacoes (tenant_id, gestor_id, operador_id, acao) VALUES (demo, gest, adm, 'cancelar_venda') RETURNING id INTO aut1;
  PERFORM ci.entrar(adm);
  PERFORM frente_cancelar_venda(ped6, aut1, 'Teste NFC-e pronta');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND motivo_cancelamento LIKE 'Venda cancelada%' FROM nfe WHERE id = n3), 'cancelar a venda cancela a NFC-e pronta');

  PERFORM ci.entrar(adm);
  ped7 := frente_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 9)), 'dinheiro', NULL, 0, 1, NULL, NULL, gen_random_uuid());
  n7 := nfce_criar(ped7, '123');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'rascunho' FROM nfe WHERE id = n7), 'NFC-e com CPF ruim fica em rascunho');
  INSERT INTO gestor_autorizacoes (tenant_id, gestor_id, operador_id, acao) VALUES (demo, gest, adm, 'cancelar_venda') RETURNING id INTO aut2;
  PERFORM ci.entrar(adm);
  PERFORM frente_cancelar_venda(ped7, aut2, 'Teste NFC-e rascunho');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM nfe WHERE id = n7), 'cancelar a venda apaga a NFC-e em rascunho');

  PERFORM ci.entrar(adm);
  ped8 := frente_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 8)), 'dinheiro', NULL, 0, 1, NULL, NULL, gen_random_uuid());
  n8 := nfce_criar(ped8);
  PERFORM ci.sair();
  UPDATE nfe SET situacao = 'autorizada', chave = 'CHAVE-CANC-CI' WHERE id = n8;
  INSERT INTO gestor_autorizacoes (tenant_id, gestor_id, operador_id, acao) VALUES (demo, gest, adm, 'cancelar_venda') RETURNING id INTO aut3;
  PERFORM ci.deve_falhar(adm, format($c$SELECT frente_cancelar_venda(%L, %L, 'Com NFC-e autorizada')$c$, ped8, aut3), 'cancelar venda com NFC-e já enviada à Sefaz');
  PERFORM ci.exige((SELECT situacao <> 'cancelado' FROM pedidos WHERE id = ped8) AND (SELECT situacao = 'autorizada' FROM nfe WHERE id = n8), 'a venda e a nota seguem como estavam');

  -- criar e cancelar usam o mesmo bloqueio por pedido, e a criação o toma antes de ler o pedido
  PERFORM ci.exige(position('pg_advisory_xact_lock' IN pg_get_functiondef('public.frente_cancelar_venda(uuid, uuid, text)'::regprocedure)) > 0
                   AND position('nfce:' IN pg_get_functiondef('public.frente_cancelar_venda(uuid, uuid, text)'::regprocedure)) > 0,
                   'cancelar a venda toma o bloqueio por pedido da NFC-e');
  PERFORM ci.exige(position('pg_advisory_xact_lock' IN pg_get_functiondef('public.nfce_criar(uuid, text)'::regprocedure))
                   < position('INTO v_ped FROM public.pedidos' IN pg_get_functiondef('public.nfce_criar(uuid, text)'::regprocedure)),
                   'nfce_criar toma o bloqueio antes de ler o pedido');

  -- emitente: a filial do pedido manda quando tem CNPJ, inscrição e endereço próprios; o que ela não tem vem da empresa
  INSERT INTO filiais (tenant_id, empresa_id, nome, cnpj, inscricao_estadual, endereco, cidade)
  VALUES (demo, emp, 'Filial emitente CI', '98765432000110', '999888777', 'Rua da Filial', NULL) RETURNING id INTO fil_emit;
  PERFORM ci.entrar(adm);
  ped5 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 15)));
  PERFORM ci.sair();
  UPDATE pedidos SET filial_id = fil_emit WHERE id = ped5;
  PERFORM ci.entrar(adm);
  n3 := nfce_criar(ped5);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT emitente ->> 'cnpj' = '98765432000110' AND emitente ->> 'inscricao_estadual' = '999888777'
                           AND emitente ->> 'endereco' = 'Rua da Filial' AND emitente ->> 'filial' = 'Filial emitente CI'
                           AND emitente ->> 'razao_social' IS NOT DISTINCT FROM (SELECT razao_social FROM empresas WHERE id = emp)
                           AND emitente ->> 'estado' IS NOT DISTINCT FROM (SELECT estado FROM empresas WHERE id = emp)
                      FROM nfe WHERE id = n3),
                   'o emitente usa o CNPJ, a inscrição e o endereço da filial, e a empresa no que a filial não tem');

  -- uma venda não leva NFC-e e NF-e ao mesmo tempo
  PERFORM ci.deve_falhar(adm, format($c$SELECT gerar_nfe(%L)$c$, ped3), 'NF-e de pedido que já tem NFC-e');
  PERFORM ci.entrar(adm);
  ped4 := criar_pedido_direto(cli, dep, jsonb_build_array(jsonb_build_object('produto_id', prod, 'quantidade', 1, 'preco_unitario', 10)));
  PERFORM gerar_nfe(ped4);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_criar(%L)$c$, ped4), 'NFC-e de pedido que já tem NF-e');

  -- número de NFC-e nunca repete na série
  BEGIN
    INSERT INTO nfe (tenant_id, empresa_id, modelo, serie, numero) SELECT tenant_id, empresa_id, 'nfce', serie, numero FROM nfe WHERE id = n1b;
    PERFORM ci.exige(false, 'inserir NFC-e com número repetido deveria falhar');
  EXCEPTION WHEN unique_violation THEN
    PERFORM ci.exige(true, 'número de NFC-e não repete na série');
  END;

  -- o andamento e a contingência só mudam pelo servidor
  PERFORM ci.entrar(vend);
  UPDATE nfe SET contingencia = true WHERE id = n1b;
  GET DIAGNOSTICS n_linhas = ROW_COUNT;
  PERFORM ci.sair();
  PERFORM ci.exige(n_linhas = 0 AND NOT (SELECT contingencia FROM nfe WHERE id = n1b), 'vendedor não marca contingência direto na tabela');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE nfe SET tentativas = 9 WHERE id = %L$c$, n1b), 'administrador altera as tentativas');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE nfe SET modelo = 'nfe' WHERE id = %L$c$, n1b), 'administrador troca o modelo da nota');
  UPDATE nfe SET situacao = 'contingencia', contingencia = true, tentativas = 1 WHERE id = n1b;
  PERFORM ci.exige((SELECT contingencia AND tentativas = 1 FROM nfe WHERE id = n1b), 'o servidor registra a contingência');

  -- CSC é segredo: o navegador não lê nem grava a tabela direto (só as funções da tela); a auditoria mascara o token
  PERFORM ci.deve_falhar(vend, $c$SELECT count(*) FROM nfce_config$c$, 'vendedor lê a tabela da NFC-e');
  PERFORM ci.deve_falhar(cxa, $c$SELECT count(*) FROM nfce_config$c$, 'caixa lê a tabela da NFC-e');
  PERFORM ci.deve_falhar(adm, $c$SELECT csc_token FROM nfce_config$c$, 'administrador lê o token direto da tabela');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE nfce_config SET proximo_numero = 1 WHERE fiscal_config_id = %L$c$, cfg), 'administrador volta a numeração');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE nfce_config SET csc_token = 'ROUBADOROUBADO0123' WHERE fiscal_config_id = %L$c$, cfg), 'administrador troca o CSC direto na tabela');
  PERFORM ci.deve_falhar(vend, format($c$UPDATE nfce_config SET csc_token = 'ROUBADOROUBADO0123' WHERE fiscal_config_id = %L$c$, cfg), 'vendedor troca o CSC direto na tabela');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO nfce_config (fiscal_config_id) VALUES (%L)$c$, gen_random_uuid()), 'administrador insere direto na tabela da NFC-e');
  PERFORM ci.entrar(adm);
  PERFORM nfce_config_salvar(cfg, 3, '1', 'NOVOSEGREDO01234567', true);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'nfce_config'
                                  AND (valor_anterior::text LIKE '%SEGREDO%' OR valor_novo::text LIKE '%SEGREDO%')),
                   'a auditoria não guarda o token do CSC');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'nfce_config' AND valor_novo ->> 'contingencia_ativa' = 'true'),
                   'a auditoria guarda a troca da contingência');

  -- eventos de pagamento pendentes: só os da empresa, só falhos/ignorados/presos, só financeiro, gestor e administrador
  INSERT INTO tenants (nome) VALUES ('NFC-e B') RETURNING id INTO tb;
  INSERT INTO webhook_eventos (provedor, event_id, tenant_id, status, erro, payload) VALUES
    ('pix', 'ev-erro', demo, 'erro', 'falhou a baixa', '{}'),
    ('pix', 'ev-ok', demo, 'processado', NULL, '{}'),
    ('pix', 'ev-ign', demo, 'ignorado', NULL, '{}'),
    ('pix', 'ev-novo', demo, 'recebido', NULL, '{}'),
    ('pix', 'ev-preso', demo, 'recebido', NULL, '{}'),
    ('pix', 'ev-outro', tb, 'erro', 'de outra empresa', '{}'),
    ('pix', 'ev-sem', NULL, 'erro', 'sem empresa', '{}');
  UPDATE webhook_eventos SET recebido_em = now() - interval '1 hour' WHERE event_id = 'ev-preso';
  PERFORM ci.exige(ci.contar(adm, $c$SELECT count(*) FROM eventos_pendentes()$c$) = 3, 'administrador vê erro, ignorado e preso da própria empresa');
  PERFORM ci.exige(ci.contar(adm, $c$SELECT count(*) FROM eventos_pendentes() WHERE event_id IN ('ev-ok', 'ev-novo', 'ev-outro', 'ev-sem')$c$) = 0,
                   'não vê processado, recente, de outra empresa nem sem empresa');
  PERFORM ci.exige(ci.contar(adm, $c$SELECT count(*) FROM eventos_pendentes() WHERE event_id = 'ev-erro' AND erro = 'falhou a baixa'$c$) = 1, 'mostra o erro');
  PERFORM ci.deve_falhar(vend, $c$SELECT * FROM eventos_pendentes()$c$, 'vendedor vê eventos pendentes');
  PERFORM ci.deve_falhar(cxa, $c$SELECT * FROM eventos_pendentes()$c$, 'caixa vê eventos pendentes');
  PERFORM ci.deve_falhar(NULL, $c$SELECT * FROM eventos_pendentes()$c$, 'anon vê eventos pendentes');
  PERFORM ci.deve_falhar(adm, $c$SELECT * FROM webhook_eventos$c$, 'administrador lê a tabela de eventos direto');
END $$;

-- 32. Tela de configuração da NFC-e: lista sem o token, grava com validação e só administrador e gestor
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  cfg uuid; emp uuid; outro uuid; tb uuid; num_antes integer;
BEGIN
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at, id LIMIT 1;
  SELECT id INTO cfg FROM fiscal_config WHERE empresa_id = emp AND filial_id IS NULL ORDER BY created_at LIMIT 1;
  SELECT proximo_numero INTO num_antes FROM nfce_config WHERE fiscal_config_id = cfg;

  -- quem pode
  PERFORM ci.deve_falhar(vend, $c$SELECT * FROM nfce_config_listar()$c$, 'vendedor lista a configuração da NFC-e');
  PERFORM ci.deve_falhar(cxa, $c$SELECT * FROM nfce_config_listar()$c$, 'caixa lista a configuração da NFC-e');
  PERFORM ci.deve_falhar(gar, $c$SELECT * FROM nfce_config_listar()$c$, 'garçom lista a configuração da NFC-e');
  PERFORM ci.deve_falhar(NULL, $c$SELECT * FROM nfce_config_listar()$c$, 'anon lista a configuração da NFC-e');
  PERFORM ci.deve_falhar(vend, format($c$SELECT nfce_config_salvar(%L, 1, '1', NULL, false)$c$, cfg), 'vendedor salva a configuração da NFC-e');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT nfce_config_salvar(%L, 1, '1', NULL, false)$c$, cfg), 'anon salva a configuração da NFC-e');

  -- a lista não devolve o token, só se está configurado
  PERFORM ci.exige(ci.contar(gest, format($c$SELECT count(*) FROM nfce_config_listar() WHERE fiscal_config_id = %L AND csc_configurado AND csc_id = '1'$c$, cfg)) = 1,
                   'a lista mostra o código e que o token está configurado');
  PERFORM ci.exige((SELECT count(*) = 0 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                     WHERE n.nspname = 'public' AND p.proname = 'nfce_config_listar' AND pg_get_function_result(p.oid) LIKE '%csc_token%'),
                   'o tipo de retorno da lista não tem o token');

  -- validações
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_config_salvar(%L, 1000, '1', NULL, false)$c$, cfg), 'série fora da faixa');
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_config_salvar(%L, 1, 'abc', NULL, false)$c$, cfg), 'código do CSC com letras');
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_config_salvar(%L, 1, '1234567', NULL, false)$c$, cfg), 'código do CSC com 7 números');
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_config_salvar(%L, 1, '1', 'curto', false)$c$, cfg), 'token curto');
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_config_salvar(%L, 1, '1', 'TOKEN-COM-TRACO-1234', false)$c$, cfg), 'token com símbolo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_config_salvar(%L, 1, '1', NULL, false)$c$, gen_random_uuid()), 'configuração inexistente');

  -- gravar: token em branco mantém o que existe; o contador não muda
  PERFORM ci.entrar(gest);
  PERFORM nfce_config_salvar(cfg, 7, '9', NULL, true);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT serie = 7 AND csc_id = '9' AND contingencia_ativa AND csc_token = 'NOVOSEGREDO01234567' AND proximo_numero = num_antes
                      FROM nfce_config WHERE fiscal_config_id = cfg), 'token em branco mantém o guardado; série, código e contingência mudam; contador intacto');
  PERFORM ci.entrar(adm);
  PERFORM nfce_config_salvar(cfg, 7, '9', 'TrocaDoToken0123456789', false);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT csc_token = 'TrocaDoToken0123456789' AND NOT contingencia_ativa FROM nfce_config WHERE fiscal_config_id = cfg), 'token novo substitui o antigo');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM auditoria WHERE entidade = 'nfce_config'
                                  AND (valor_anterior::text LIKE '%TrocaDoToken%' OR valor_novo::text LIKE '%TrocaDoToken%')),
                   'a auditoria da tela não guarda o token');

  -- configuração que ainda não tem linha de NFC-e: aparece com padrões e a gravação cria
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Filial NFC-e tela') RETURNING id INTO outro;
  INSERT INTO fiscal_config (tenant_id, empresa_id, filial_id) VALUES (demo, emp, outro) RETURNING id INTO cfg;
  PERFORM ci.exige(ci.contar(adm, format($c$SELECT count(*) FROM nfce_config_listar() WHERE fiscal_config_id = %L AND serie = 1 AND proximo_numero = 1 AND NOT csc_configurado AND filial_nome = 'Filial NFC-e tela'$c$, cfg)) = 1,
                   'configuração sem NFC-e aparece com os padrões');
  PERFORM ci.entrar(adm);
  PERFORM nfce_config_salvar(cfg, 2, '3', 'TokenDaFilial0123456789', false);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT serie = 2 AND csc_id = '3' AND proximo_numero = 1 FROM nfce_config WHERE fiscal_config_id = cfg), 'a gravação cria a linha da NFC-e');

  -- outra empresa não enxerga nem grava
  INSERT INTO tenants (nome) VALUES ('NFC-e tela B') RETURNING id INTO tb;
  PERFORM ci.exige(ci.contar(adm, format($c$SELECT count(*) FROM nfce_config_listar() WHERE fiscal_config_id = %L$c$, gen_random_uuid())) = 0, 'id solto não aparece');
  INSERT INTO fiscal_config (tenant_id) VALUES (tb);
  PERFORM ci.deve_falhar(adm, format($c$SELECT nfce_config_salvar(%L, 1, '1', NULL, false)$c$, (SELECT id FROM fiscal_config WHERE tenant_id = tb)), 'salvar configuração de outra empresa');
  PERFORM ci.exige(ci.contar(adm, format($c$SELECT count(*) FROM nfce_config_listar() WHERE fiscal_config_id = %L$c$, (SELECT id FROM fiscal_config WHERE tenant_id = tb))) = 0, 'não lista a configuração de outra empresa');
END $$;

-- 33. Fase 1: importação por planilha (produtos, clientes e saldos) numa transação, com simulação e limite
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  dep uuid; r jsonb; n_antes bigint; n_depois bigint; q numeric; linhas jsonb; i integer; tb uuid;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Import CI A'), (demo, 'Import CI B');
  SELECT id INTO dep FROM depositos WHERE tenant_id = demo AND nome = 'Import CI A';

  -- quem pode: produtos e clientes só administrador e gestor; saldos também o estoquista
  PERFORM ci.deve_falhar(vend, $c$SELECT importar_produtos('[{"linha":2,"codigo_interno":"IMP-X","descricao":"x"}]'::jsonb)$c$, 'vendedor importa produtos');
  PERFORM ci.deve_falhar(cxa, $c$SELECT importar_produtos('[{"linha":2,"codigo_interno":"IMP-X","descricao":"x"}]'::jsonb)$c$, 'caixa importa produtos');
  PERFORM ci.deve_falhar(gar, $c$SELECT importar_produtos('[{"linha":2,"codigo_interno":"IMP-X","descricao":"x"}]'::jsonb)$c$, 'garçom importa produtos');
  PERFORM ci.deve_falhar(NULL, $c$SELECT importar_produtos('[{"linha":2,"codigo_interno":"IMP-X","descricao":"x"}]'::jsonb)$c$, 'anon importa produtos');
  PERFORM ci.deve_falhar(est, $c$SELECT importar_produtos('[{"linha":2,"codigo_interno":"IMP-X","descricao":"x"}]'::jsonb)$c$, 'estoquista importa produtos');
  PERFORM ci.deve_falhar(vend, $c$SELECT importar_clientes('[{"linha":2,"nome":"x"}]'::jsonb)$c$, 'vendedor importa clientes');
  PERFORM ci.deve_falhar(est, $c$SELECT importar_clientes('[{"linha":2,"nome":"x"}]'::jsonb)$c$, 'estoquista importa clientes');
  PERFORM ci.deve_falhar(vend, $c$SELECT importar_saldos('[{"linha":2,"codigo_interno":"x","quantidade":1}]'::jsonb)$c$, 'vendedor importa saldos');
  PERFORM ci.deve_falhar(cxa, $c$SELECT importar_saldos('[{"linha":2,"codigo_interno":"x","quantidade":1}]'::jsonb)$c$, 'caixa importa saldos');

  -- limites de entrada
  PERFORM ci.deve_falhar(adm, $c$SELECT importar_produtos('[]'::jsonb)$c$, 'planilha vazia');
  PERFORM ci.deve_falhar(adm, $c$SELECT importar_produtos('{"a":1}'::jsonb)$c$, 'linhas que não são lista');
  SELECT jsonb_agg(jsonb_build_object('linha', g + 1, 'codigo_interno', 'LIM-' || g, 'descricao', 'x')) INTO linhas FROM generate_series(1, 5001) g;
  PERFORM ci.deve_falhar(adm, format($c$SELECT importar_produtos(%L::jsonb)$c$, linhas), 'mais de 5000 linhas');

  -- produtos: simulação não grava; erros por linha; nada entra se uma linha falha
  SELECT count(*) INTO n_antes FROM produtos WHERE tenant_id = demo;
  PERFORM ci.entrar(adm);
  r := importar_produtos('[{"linha":2,"codigo_interno":"IMP-1","descricao":"Cimento CP II","unidade":"sc","preco_venda":39.9,"custo":31,"ncm":"25232990","categoria":"Cimentos"},
                           {"linha":3,"codigo_interno":"IMP-2","descricao":"Areia média","unidade":"m3","preco_venda":120,"categoria":"cimentos"}]'::jsonb, false, true);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ok')::boolean AND (r ->> 'simulado')::boolean AND (r ->> 'criados')::int = 2 AND (r ->> 'categorias_novas')::int = 1,
                   'a simulação conta os produtos novos e a categoria nova (sem diferenciar maiúsculas)');
  SELECT count(*) INTO n_depois FROM produtos WHERE tenant_id = demo;
  PERFORM ci.exige(n_antes = n_depois AND NOT EXISTS (SELECT 1 FROM categorias WHERE tenant_id = demo AND lower(nome) = 'cimentos'),
                   'simular não grava produto nem categoria');

  PERFORM ci.entrar(adm);
  r := importar_produtos('[{"linha":2,"codigo_interno":"IMP-OK","descricao":"Bom"},
                           {"linha":3,"codigo_interno":"IMP-BAD","descricao":"Ruim","ncm":"123"},
                           {"linha":4,"codigo_interno":"imp-ok","descricao":"Repetido"},
                           {"linha":5,"codigo_interno":"","descricao":"Sem código"},
                           {"linha":6,"codigo_interno":"IMP-NEG","descricao":"Negativo","preco_venda":-1},
                           {"linha":7,"codigo_interno":"IMP-TXT","descricao":"Texto","preco_venda":"abc"}]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'ok')::boolean AND (r ->> 'n_erros')::int = 5, 'cada linha ruim vira um erro, cinco ao todo');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'erros') e WHERE (e ->> 'linha')::int = 3 AND e ->> 'mensagem' LIKE '%NCM%'), 'o erro diz a linha e o motivo');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM produtos WHERE tenant_id = demo AND codigo_interno = 'IMP-OK'), 'com erro em outra linha, nada entra (tudo ou nada)');

  -- produtos: importar de verdade, categoria criada, tipos e padrões
  PERFORM ci.entrar(gest);
  r := importar_produtos('[{"linha":2,"codigo_interno":"IMP-1","descricao":"Cimento CP II","unidade":"sc","preco_venda":39.9,"custo":31,"ncm":"2523.29.90","categoria":"Cimentos","estoque_minimo":10,"estoque_maximo":100},
                           {"linha":3,"codigo_interno":"IMP-2","descricao":"Areia média","unidade":"m3","preco_venda":120,"categoria":"cimentos"}]'::jsonb, false, false, 'produtos.csv');
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ok')::boolean AND (r ->> 'criados')::int = 2, 'o gestor importa produtos');
  PERFORM ci.exige((SELECT preco_venda = 39.9 AND custo = 31 AND ncm = '25232990' AND unidade = 'sc' AND estoque_minimo = 10 AND estoque_maximo = 100 AND tenant_id = demo
                      FROM produtos WHERE codigo_interno = 'IMP-1' AND tenant_id = demo), 'o produto entra com os dados da planilha (NCM só números)');
  PERFORM ci.exige((SELECT count(*) = 1 FROM categorias WHERE tenant_id = demo AND lower(nome) = 'cimentos'), 'a categoria nova é criada uma vez só');
  PERFORM ci.exige((SELECT p1.categoria_id = p2.categoria_id AND p1.categoria_id IS NOT NULL
                      FROM produtos p1, produtos p2 WHERE p1.codigo_interno = 'IMP-1' AND p2.codigo_interno = 'IMP-2' AND p1.tenant_id = demo AND p2.tenant_id = demo),
                   'os dois produtos usam a mesma categoria');
  PERFORM ci.exige((SELECT count(*) = 1 FROM importacoes WHERE tenant_id = demo AND tipo = 'produtos' AND arquivo = 'produtos.csv' AND criados = 2), 'a importação fica registrada');
  PERFORM ci.exige(ci.contar(adm, $c$SELECT count(*) FROM importacoes$c$) = 1 AND ci.contar(vend, $c$SELECT count(*) FROM importacoes$c$) = 0,
                   'o histórico é de administrador, gestor e estoquista');

  -- produtos: já existe; atualizar só os campos preenchidos
  PERFORM ci.entrar(adm);
  r := importar_produtos('[{"linha":2,"codigo_interno":"IMP-1","descricao":"Cimento novo","preco_venda":45}]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'ok')::boolean AND r -> 'erros' -> 0 ->> 'mensagem' LIKE '%já existe%', 'código existente sem pedir para atualizar é recusado');
  PERFORM ci.entrar(adm);
  r := importar_produtos('[{"linha":2,"codigo_interno":"imp-1","descricao":"Cimento novo","preco_venda":45}]'::jsonb, true);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ok')::boolean AND (r ->> 'atualizados')::int = 1 AND (r ->> 'criados')::int = 0, 'atualizar altera o produto existente (código sem diferenciar maiúsculas)');
  PERFORM ci.exige((SELECT descricao = 'Cimento novo' AND preco_venda = 45 AND custo = 31 AND unidade = 'sc' AND ncm = '25232990'
                      FROM produtos WHERE codigo_interno = 'IMP-1' AND tenant_id = demo), 'campo em branco na planilha mantém o valor que já existe');

  -- clientes
  PERFORM ci.entrar(adm);
  r := importar_clientes('[{"linha":2,"nome":"Construtora Alfa","documento":"11.222.333/0001-81","inscricao_estadual":"123","email":"alfa@x.com","estado":"sp","limite_credito":5000,"prazo_padrao_dias":30},
                           {"linha":3,"nome":"João da Silva","documento":"529.982.247-25","telefone":"(11) 99999-0000"},
                           {"linha":4,"nome":"Cliente sem documento"}]'::jsonb, false, false, 'clientes.csv');
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ok')::boolean AND (r ->> 'criados')::int = 3, 'importa clientes');
  PERFORM ci.exige((SELECT tipo = 'PJ' AND cnpj = '11222333000181' AND cpf IS NULL AND estado = 'SP' AND limite_credito = 5000 AND prazo_padrao_dias = 30
                      FROM clientes WHERE tenant_id = demo AND nome = 'Construtora Alfa'), 'CNPJ vira pessoa jurídica, só números; estado em maiúsculas; limite e prazo entram');
  PERFORM ci.exige((SELECT tipo = 'PF' AND cpf = '52998224725' AND cnpj IS NULL FROM clientes WHERE tenant_id = demo AND nome = 'João da Silva'), 'CPF vira pessoa física');
  PERFORM ci.entrar(adm);
  r := importar_clientes('[{"linha":2,"nome":"Outro nome","documento":"52998224725"},
                           {"linha":3,"nome":"Cliente sem documento"},
                           {"linha":4,"nome":"Novo","documento":"123"},
                           {"linha":5,"nome":"Mail","email":"sem-arroba"},
                           {"linha":6,"nome":"UF","estado":"SPP"},
                           {"linha":7,"nome":"Neg","limite_credito":-5}]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'ok')::boolean AND (r ->> 'n_erros')::int = 6, 'cliente que já existe (por CPF ou por nome) e dados ruins são erros');
  PERFORM ci.entrar(adm);
  r := importar_clientes('[{"linha":2,"nome":"João Silva Atualizado","documento":"52998224725","telefone":""}]'::jsonb, true);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ok')::boolean AND (r ->> 'atualizados')::int = 1, 'atualizar cliente pelo CPF');
  PERFORM ci.exige((SELECT nome = 'João Silva Atualizado' AND telefone = '(11) 99999-0000' FROM clientes WHERE tenant_id = demo AND cpf = '52998224725'),
                   'telefone em branco mantém o que já existe');
  PERFORM ci.entrar(adm);
  r := importar_clientes('[{"linha":2,"nome":"Alfa Numérica","documento":"12.abc.345/01de-35"}]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ok')::boolean AND (r ->> 'criados')::int = 1, 'importa cliente com CNPJ alfanumérico');
  PERFORM ci.exige((SELECT tipo = 'PJ' AND cnpj = '12ABC34501DE35' AND cpf IS NULL FROM clientes WHERE tenant_id = demo AND nome = 'Alfa Numérica'),
                   'CNPJ alfanumérico fica em maiúsculas e vira pessoa jurídica');
  PERFORM ci.entrar(adm);
  r := importar_clientes('[{"linha":2,"nome":"Cpf com letra","documento":"ABC12345678"}]'::jsonb, false, true);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'ok')::boolean AND (r ->> 'n_erros')::int = 1, 'CPF com letras é recusado na importação');

  -- saldos
  PERFORM ci.entrar(est);
  r := importar_saldos('[{"linha":2,"codigo_interno":"IMP-1","deposito":"Import CI A","quantidade":80},
                         {"linha":3,"codigo_interno":"IMP-2","deposito":"import ci b","quantidade":12.5}]'::jsonb, false, 'saldos.csv');
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ok')::boolean AND (r ->> 'atualizados')::int = 2, 'o estoquista importa saldos');
  SELECT quantidade INTO q FROM estoques e JOIN produtos p ON p.id = e.produto_id WHERE p.codigo_interno = 'IMP-1' AND p.tenant_id = demo AND e.deposito_id = dep;
  PERFORM ci.exige(q = 80, 'o saldo do depósito fica igual ao da planilha');
  PERFORM ci.exige((SELECT count(*) = 1 FROM estoque_movimentacoes m JOIN produtos p ON p.id = m.produto_id
                     WHERE p.codigo_interno = 'IMP-2' AND p.tenant_id = demo AND m.motivo = 'Importação por planilha'), 'o saldo entra como movimentação com histórico');
  PERFORM ci.entrar(adm);
  r := importar_saldos('[{"linha":2,"codigo_interno":"IMP-1","deposito":"Import CI A","quantidade":60},
                         {"linha":3,"codigo_interno":"NAO-EXISTE","deposito":"Import CI A","quantidade":1},
                         {"linha":4,"codigo_interno":"IMP-2","deposito":"","quantidade":1},
                         {"linha":5,"codigo_interno":"IMP-2","deposito":"Depósito fantasma","quantidade":1},
                         {"linha":6,"codigo_interno":"IMP-2","deposito":"Import CI B","quantidade":0},
                         {"linha":7,"codigo_interno":"IMP-1","deposito":"Import CI A","quantidade":5}]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'ok')::boolean AND (r ->> 'n_erros')::int = 5, 'produto inexistente, depósito em branco com vários, depósito inexistente, quantidade zero e linha repetida são erros');
  SELECT quantidade INTO q FROM estoques e JOIN produtos p ON p.id = e.produto_id WHERE p.codigo_interno = 'IMP-1' AND p.tenant_id = demo AND e.deposito_id = dep;
  PERFORM ci.exige(q = 80, 'com erro em outra linha, o saldo não muda');

  -- isolamento: nada do que foi importado aparece em outra empresa
  INSERT INTO tenants (nome) VALUES ('Importação B') RETURNING id INTO tb;
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM produtos WHERE tenant_id = tb), 'a outra empresa não recebeu produtos');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM clientes WHERE tenant_id = tb), 'a outra empresa não recebeu clientes');
END $$;

-- 34. Extrato bancário (OFX): linhas entram uma vez, conciliam o lançamento igual e o resto fica pendente
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  fin  constant uuid := 'a0000000-0000-0000-0000-0000000000b2';
  conta uuid; conta2 uuid; m1 uuid; m2 uuid; m3 uuid; r jsonb; lin uuid; mov uuid; tb uuid; contab uuid;
BEGIN
  INSERT INTO contas_bancarias (tenant_id, apelido, saldo_inicial) VALUES (demo, 'Extrato CI A', 0) RETURNING id INTO conta;
  INSERT INTO contas_bancarias (tenant_id, apelido, saldo_inicial) VALUES (demo, 'Extrato CI B', 0) RETURNING id INTO conta2;
  INSERT INTO banco_movimentos (tenant_id, conta_id, data, tipo, valor, descricao) VALUES (demo, conta, '2026-10-05', 'entrada', 1500, 'Recebimento cliente') RETURNING id INTO m1;
  INSERT INTO banco_movimentos (tenant_id, conta_id, data, tipo, valor, descricao) VALUES (demo, conta, '2026-10-07', 'saida', 300, 'Pagamento fornecedor') RETURNING id INTO m2;
  INSERT INTO banco_movimentos (tenant_id, conta_id, data, tipo, valor, descricao) VALUES (demo, conta, '2026-09-01', 'entrada', 99, 'Muito antigo') RETURNING id INTO m3;

  -- quem pode
  PERFORM ci.deve_falhar(vend, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-10-05","valor":1,"descricao":"x"}]'::jsonb)$c$, conta), 'vendedor importa extrato');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-10-05","valor":1,"descricao":"x"}]'::jsonb)$c$, conta), 'caixa importa extrato');
  PERFORM ci.deve_falhar(gar, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-10-05","valor":1,"descricao":"x"}]'::jsonb)$c$, conta), 'garçom importa extrato');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-10-05","valor":1,"descricao":"x"}]'::jsonb)$c$, conta), 'anon importa extrato');
  PERFORM ci.deve_falhar(adm, $c$SELECT banco_extrato_importar(gen_random_uuid(), '[{"fitid":"X","data":"2026-10-05","valor":1,"descricao":"x"}]'::jsonb)$c$, 'conta que não existe');
  PERFORM ci.deve_falhar(adm, format($c$SELECT banco_extrato_importar(%L, '[]'::jsonb)$c$, conta), 'extrato vazio');
  PERFORM ci.deve_falhar(adm, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-10-05","valor":0,"descricao":"x"}]'::jsonb)$c$, conta), 'valor zerado');
  PERFORM ci.deve_falhar(adm, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-13-45","valor":1,"descricao":"x"}]'::jsonb)$c$, conta), 'data inválida');
  PERFORM ci.deve_falhar(adm, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-10-05","valor":"1","descricao":"x"}]'::jsonb)$c$, conta), 'valor em texto');
  PERFORM ci.deve_falhar(adm, format($c$SELECT banco_extrato_importar(%L, '[{"fitid":"X","data":"2026-10-05","valor":1,"descricao":"x"},{"fitid":"X","data":"2026-10-05","valor":2,"descricao":"y"}]'::jsonb)$c$, conta), 'FITID repetido no arquivo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT banco_extrato_importar(%L, (SELECT jsonb_agg(jsonb_build_object('fitid','L'||g,'data','2026-10-05','valor',1,'descricao','x')) FROM generate_series(1,2001) g))$c$, conta), 'mais de 2000 lançamentos');

  -- simulação não grava nada
  PERFORM ci.entrar(fin);
  r := banco_extrato_importar(conta, '[{"fitid":"A1","data":"2026-10-06","valor":1500,"descricao":"PIX cliente"},
                                       {"fitid":"A2","data":"2026-10-07","valor":-300,"descricao":"Boleto fornecedor"},
                                       {"fitid":"A3","data":"2026-10-08","valor":-12.5,"descricao":"Tarifa"},
                                       {"fitid":"A4","data":"2026-10-09","valor":99,"descricao":"Longe demais"}]'::jsonb, 'out.ofx', true);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'simulado')::boolean AND (r ->> 'conciliadas')::int = 2 AND (r ->> 'pendentes')::int = 2 AND (r ->> 'repetidas')::int = 0,
                   'a simulação separa o que concilia sozinho (valor, sentido e até 3 dias) do que fica pendente');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM banco_extrato_linhas WHERE conta_id = conta) AND (SELECT NOT conciliado FROM banco_movimentos WHERE id = m1),
                   'simular não grava linha nem concilia');

  -- importação de verdade (financeiro)
  PERFORM ci.entrar(fin);
  r := banco_extrato_importar(conta, '[{"fitid":"A1","data":"2026-10-06","valor":1500,"descricao":"PIX cliente"},
                                       {"fitid":"A2","data":"2026-10-07","valor":-300,"descricao":"Boleto fornecedor"},
                                       {"fitid":"A3","data":"2026-10-08","valor":-12.5,"descricao":"Tarifa"},
                                       {"fitid":"A4","data":"2026-10-09","valor":99,"descricao":"Longe demais"}]'::jsonb, 'out.ofx');
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'conciliadas')::int = 2 AND (r ->> 'pendentes')::int = 2, 'importa e concilia');
  PERFORM ci.exige((SELECT conciliado FROM banco_movimentos WHERE id = m1) AND (SELECT conciliado FROM banco_movimentos WHERE id = m2),
                   'os lançamentos iguais ficam conciliados');
  PERFORM ci.exige(NOT (SELECT conciliado FROM banco_movimentos WHERE id = m3), 'lançamento de outra data não é tocado');
  PERFORM ci.exige((SELECT movimento_id = m1 AND situacao = 'conciliada' FROM banco_extrato_linhas WHERE conta_id = conta AND fitid = 'A1'), 'a linha guarda o lançamento que conciliou');

  -- importar de novo não duplica nem concilia outra vez
  PERFORM ci.entrar(adm);
  r := banco_extrato_importar(conta, '[{"fitid":"A1","data":"2026-10-06","valor":1500,"descricao":"PIX cliente"},
                                       {"fitid":"A5","data":"2026-10-10","valor":-300,"descricao":"Outro de 300"}]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetidas')::int = 1 AND (r ->> 'pendentes')::int = 1 AND (r ->> 'conciliadas')::int = 0, 'linha já importada é pulada; lançamento já conciliado não casa de novo');
  PERFORM ci.exige((SELECT count(*) = 5 FROM banco_extrato_linhas WHERE conta_id = conta), 'cada FITID existe uma vez só');

  -- a mesma linha em outra conta é outra linha
  PERFORM ci.entrar(adm);
  r := banco_extrato_importar(conta2, '[{"fitid":"A1","data":"2026-10-06","valor":1500,"descricao":"PIX cliente"}]'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetidas')::int = 0 AND (r ->> 'pendentes')::int = 1, 'o FITID vale por conta');

  -- tratar pendências
  SELECT id INTO lin FROM banco_extrato_linhas WHERE conta_id = conta AND fitid = 'A3';
  PERFORM ci.deve_falhar(vend, format($c$SELECT banco_extrato_lancar(%L)$c$, lin), 'vendedor lança linha do extrato');
  PERFORM ci.deve_falhar(cxa, format($c$SELECT banco_extrato_ignorar(%L)$c$, lin), 'caixa ignora linha do extrato');
  PERFORM ci.entrar(fin);
  mov := banco_extrato_lancar(lin, 'tarifa bancaria');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tipo = 'saida' AND valor = 12.5 AND conciliado AND origem = 'extrato' AND data = '2026-10-08' AND categoria = 'tarifa bancaria'
                      FROM banco_movimentos WHERE id = mov), 'linha negativa vira saída já conciliada');
  PERFORM ci.exige((SELECT situacao = 'conciliada' AND movimento_id = mov FROM banco_extrato_linhas WHERE id = lin), 'a linha passa a apontar para o lançamento');
  PERFORM ci.deve_falhar(fin, format($c$SELECT banco_extrato_lancar(%L)$c$, lin), 'lançar duas vezes a mesma linha');
  SELECT id INTO lin FROM banco_extrato_linhas WHERE conta_id = conta AND fitid = 'A4';
  PERFORM ci.entrar(fin);
  PERFORM banco_extrato_ignorar(lin);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'ignorada' FROM banco_extrato_linhas WHERE id = lin), 'ignorar');
  PERFORM ci.deve_falhar(fin, format($c$SELECT banco_extrato_lancar(%L)$c$, lin), 'linha ignorada não vira lançamento');
  PERFORM ci.entrar(fin);
  PERFORM banco_extrato_ignorar(lin, false);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'pendente' FROM banco_extrato_linhas WHERE id = lin), 'desfazer o ignorar');

  -- leitura só financeiro/gestão/administrador; sem escrita direta; outra empresa não vê
  PERFORM ci.exige(ci.contar(fin, 'SELECT count(*) FROM banco_extrato_linhas') > 0 AND ci.contar(vend, 'SELECT count(*) FROM banco_extrato_linhas') = 0
                   AND ci.contar(cxa, 'SELECT count(*) FROM banco_extrato_linhas') = 0, 'vendedor e caixa não leem o extrato importado');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO banco_extrato_linhas (conta_id, fitid, data, valor, descricao) VALUES (%L, 'DIRETO', current_date, 1, 'x')$c$, conta), 'escrita direta no extrato');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE banco_extrato_linhas SET situacao = 'ignorada' WHERE conta_id = %L$c$, conta), 'alteração direta no extrato');
  INSERT INTO tenants (nome) VALUES ('Extrato B') RETURNING id INTO tb;
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM banco_extrato_linhas WHERE tenant_id = tb), 'a outra empresa não recebeu linhas');
END $$;

-- 35. Pet shop (base): produto que é serviço não controla estoque; produto comum segue igual
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  dep uuid; serv uuid; merc uuid; cli uuid; ped uuid; mov_antes bigint; q numeric;
BEGIN
  INSERT INTO depositos (tenant_id, nome, permite_negativo) VALUES (demo, 'Pet CI', false) RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_estoque)
    VALUES (demo, 'PET-BANHO', 'Banho porte P', 'UN', 60, false) RETURNING id INTO serv;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda)
    VALUES (demo, 'PET-RACAO', 'Ração 1kg', 'UN', 20) RETURNING id INTO merc;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Tutor CI') RETURNING id INTO cli;
  PERFORM ci.exige((SELECT controla_estoque FROM produtos WHERE id = merc), 'produto comum controla estoque por padrão');
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(merc, dep, 'entrada'::mov_tipo, 5, 'ci', 'ci');

  -- chamada direta: serviço não cria saldo nem movimento, em nenhum tipo
  SELECT count(*) INTO mov_antes FROM estoque_movimentacoes WHERE produto_id = serv;
  PERFORM ci.exige(registrar_movimentacao(serv, dep, 'saida'::mov_tipo, 3, 'ci', 'ci') IS NULL, 'saída de serviço não movimenta');
  PERFORM registrar_movimentacao(serv, dep, 'entrada'::mov_tipo, 3, 'ci', 'ci');
  PERFORM registrar_movimentacao(serv, dep, 'reserva'::mov_tipo, 3, 'ci', 'ci');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM estoques WHERE produto_id = serv), 'serviço não tem linha de estoque');
  PERFORM ci.exige((SELECT count(*) FROM estoque_movimentacoes WHERE produto_id = serv) = mov_antes, 'serviço não tem movimentação');

  PERFORM ci.sair();

  -- venda de serviço + mercadoria no mesmo cupom, sem saldo do serviço
  PERFORM ci.entrar(vend);
  ped := pdv_venda(dep, jsonb_build_array(
            jsonb_build_object('produto_id', serv, 'quantidade', 1, 'preco_unitario', 60),
            jsonb_build_object('produto_id', merc, 'quantidade', 2, 'preco_unitario', 20)),
          'crediario', cli, 0, 1, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT total = 100 FROM pedidos WHERE id = ped), 'a venda soma serviço e mercadoria');
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 3, 'a mercadoria baixa o estoque normalmente');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM estoques WHERE produto_id = serv), 'o serviço continua sem estoque depois da venda');

  -- mercadoria sem saldo continua sendo recusada
  PERFORM ci.deve_falhar(vend, format($c$SELECT pdv_venda(%L, jsonb_build_array(jsonb_build_object('produto_id', %L, 'quantidade', 99, 'preco_unitario', 20)), 'crediario', %L, 0, 1, current_date + 30)$c$, dep, merc, cli),
                         'mercadoria sem saldo continua recusada');

  -- o cancelamento da venda devolve itens por registrar_movimentacao('entrada'): só a mercadoria volta
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(serv, dep, 'entrada'::mov_tipo, 1, 'Cancelamento de venda', 'CANC');
  PERFORM registrar_movimentacao(merc, dep, 'entrada'::mov_tipo, 2, 'Cancelamento de venda', 'CANC');
  PERFORM ci.sair();
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 5, 'cancelar devolve a mercadoria ao estoque');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM estoques WHERE produto_id = serv), 'cancelar não cria estoque do serviço');
END $$;

-- 36. Pet shop (cadastros): pets, serviços, preço por porte/raça/pelagem e profissionais
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cxa  constant uuid := 'a0000000-0000-0000-0000-0000000000a1';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  tutor uuid; tutor_b uuid; tb uuid; pet uuid; pet2 uuid; pet3 uuid; serv uuid; serv2 uuid; prod uuid; pr uuid; r jsonb; n bigint;
BEGIN
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Tutor Pet CI') RETURNING id INTO tutor;
  INSERT INTO tenants (nome) VALUES ('Pet B') RETURNING id INTO tb;
  INSERT INTO clientes (tenant_id, nome) VALUES (tb, 'Tutor de outra empresa') RETURNING id INTO tutor_b;

  -- quem cadastra pet: administrador, gestor, vendedor e caixa
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Rex'))$c$, tutor), 'garçom cadastra pet');
  PERFORM ci.deve_falhar(est, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Rex'))$c$, tutor), 'estoquista cadastra pet');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Rex'))$c$, tutor), 'anon cadastra pet');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', ''))$c$, tutor), 'pet sem nome');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Rex', 'porte', 'enorme'))$c$, tutor), 'porte inválido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Rex', 'peso_kg', 0))$c$, tutor), 'peso zero');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Rex'))$c$, tutor_b), 'tutor de outra empresa');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_salvar(jsonb_build_object('nome', 'Sem tutor'))$c$, 'pet sem tutor');

  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Thor', 'especie', 'cao', 'raca', ' Poodle ', 'porte', 'pequeno',
                                       'pelagem', 'longa', 'peso_kg', 6.5, 'nascimento', '2023-05-10', 'castrado', true, 'alergias', 'frango'));
  pet2 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Mel', 'raca', 'SRD', 'porte', 'grande', 'pelagem', 'curta'));
  pet3 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Bola', 'especie', 'gato'));
  PERFORM pet_salvar(jsonb_build_object('id', pet2, 'cliente_id', tutor, 'nome', 'Mel', 'raca', 'SRD', 'porte', 'medio', 'pelagem', 'curta'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT raca = 'Poodle' AND porte = 'pequeno' AND castrado FROM pets WHERE id = pet), 'o pet guarda os dados (raça sem espaços sobrando)');
  PERFORM ci.exige((SELECT porte = 'medio' FROM pets WHERE id = pet2), 'editar o pet atualiza');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM pets') = 3 AND ci.contar(gar, 'SELECT count(*) FROM pets') = 0, 'o garçom não lê pets');

  -- serviços e preços: só administrador e gestor
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_servico_salvar('{"nome":"Banho"}'::jsonb)$c$, 'vendedor cria serviço');
  PERFORM ci.deve_falhar(cxa, $c$SELECT pet_servico_salvar('{"nome":"Banho"}'::jsonb)$c$, 'caixa cria serviço');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_servico_salvar('{"nome":""}'::jsonb)$c$, 'serviço sem nome');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_servico_salvar('{"nome":"Banho","duracao_min":2}'::jsonb)$c$, 'duração curta demais');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_servico_salvar('{"nome":"Banho","categoria":"voo"}'::jsonb)$c$, 'categoria inválida');
  PERFORM ci.entrar(gest);
  serv := pet_servico_salvar('{"nome":"Banho","categoria":"banho","duracao_min":60,"preco_base":50}'::jsonb);
  serv2 := pet_servico_salvar('{"nome":"Tosa higiênica","categoria":"tosa","duracao_min":30}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO prod FROM pet_servicos WHERE id = serv;
  PERFORM ci.exige((SELECT NOT controla_estoque AND preco_venda = 50 AND descricao = 'Banho' AND codigo_interno <> '' FROM produtos WHERE id = prod),
                   'o serviço vira um produto sem controle de estoque, com código automático e preço de balcão');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_servico_salvar('{"nome":" banho "}'::jsonb)$c$, 'nome de serviço repetido (sem diferenciar maiúsculas)');

  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_preco_salvar(%L, NULL, NULL, NULL, 10)$c$, serv), 'vendedor grava preço');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_preco_salvar(%L, 'enorme', NULL, NULL, 10)$c$, serv), 'preço com porte inválido');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_preco_salvar(%L, NULL, NULL, NULL, -1)$c$, serv), 'preço negativo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_preco_salvar(%L, NULL, NULL, NULL, 10)$c$, gen_random_uuid()), 'serviço que não existe');

  PERFORM ci.entrar(adm);
  PERFORM pet_preco_salvar(serv, NULL, NULL, NULL, 50);                 -- qualquer pet
  PERFORM pet_preco_salvar(serv, 'pequeno', NULL, NULL, 60);
  PERFORM pet_preco_salvar(serv, NULL, NULL, 'longa', 70);
  PERFORM pet_preco_salvar(serv, 'pequeno', NULL, 'longa', 80);
  PERFORM pet_preco_salvar(serv, NULL, 'poodle', NULL, 90);
  pr := pet_preco_salvar(serv, 'pequeno', ' POODLE ', 'longa', 120);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 6 FROM pet_servico_precos WHERE servico_id = serv), 'seis combinações de preço');

  PERFORM ci.entrar(adm);
  PERFORM ci.exige(pet_preco_salvar(serv, 'pequeno', 'poodle', 'longa', 130) = pr, 'a mesma combinação (raça sem diferenciar maiúsculas) atualiza a linha');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 6 AND max(preco) = 130 FROM pet_servico_precos WHERE servico_id = serv), 'sem linha duplicada para a mesma combinação');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO pet_servico_precos (tenant_id, servico_id, porte, raca, pelagem, preco) VALUES (%L, %L, 'pequeno', 'POODLE ', 'longa', 1)$c$, demo, serv),
                              'o índice único barra a mesma combinação inserida direto');

  -- o preço calculado no banco segue a mesma regra do código
  PERFORM ci.entrar(vend);
  r := pet_preco_calcular(serv, pet);   -- poodle pequeno de pelagem longa
  PERFORM ci.exige((r ->> 'preco')::numeric = 130 AND (r ->> 'pontos')::int = 7, 'raça + pelagem + porte vence');
  r := pet_preco_calcular(serv, pet2);  -- SRD médio de pelagem curta
  PERFORM ci.exige((r ->> 'preco')::numeric = 50, 'cai no preço de qualquer pet');
  r := pet_preco_calcular(serv2, pet);  -- serviço sem nenhum preço
  PERFORM ci.exige(r IS NULL, 'serviço sem preço cadastrado não é oferecido');
  PERFORM ci.sair();

  PERFORM ci.deve_falhar(cxa, format($c$SELECT pet_preco_remover(%L)$c$, pr), 'caixa remove preço');
  PERFORM ci.entrar(adm);
  PERFORM pet_preco_remover(pr);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 5 FROM pet_servico_precos WHERE servico_id = serv), 'remover preço');
  PERFORM ci.entrar(vend);
  r := pet_preco_calcular(serv, pet);   -- sem a linha completa, vale "poodle"
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'preco')::numeric = 90, 'sem a combinação completa, vence a raça sozinha');
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_preco_calcular(%L, %L)$c$, serv, pet), 'garçom calcula preço');

  -- profissionais
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_profissional_salvar('{"nome":"Ana"}'::jsonb)$c$, 'vendedor cria profissional');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_profissional_salvar('{"nome":""}'::jsonb)$c$, 'profissional sem nome');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_profissional_salvar('{"nome":"Ana","funcao":"astronauta"}'::jsonb)$c$, 'função inválida');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_profissional_salvar('{"nome":"Ana","comissao_percentual":101}'::jsonb)$c$, 'comissão acima de 100');
  PERFORM ci.entrar(gest);
  PERFORM pet_profissional_salvar('{"nome":"Ana","funcao":"groomer","comissao_percentual":30}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT funcao = 'groomer' AND comissao_percentual = 30 FROM pet_profissionais WHERE nome = 'Ana' AND tenant_id = demo), 'grava o profissional');

  -- escrita direta negada e isolamento entre empresas
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO pets (cliente_id, nome) VALUES (%L, 'Direto')$c$, tutor), 'escrita direta em pets');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE pet_servicos SET nome = 'x' WHERE id = %L$c$, serv), 'alteração direta em serviços');
  PERFORM ci.deve_falhar(adm, $c$DELETE FROM pet_profissionais$c$, 'apagar profissional direto');
  SELECT count(*) INTO n FROM pets WHERE tenant_id = tb;
  PERFORM ci.exige(n = 0 AND NOT EXISTS (SELECT 1 FROM pet_servicos WHERE tenant_id = tb), 'a outra empresa não recebeu cadastros');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM pet_servicos') = 0 AND ci.contar(gar, 'SELECT count(*) FROM pet_profissionais') = 0
                   AND ci.contar(gar, 'SELECT count(*) FROM pet_servico_precos') = 0, 'o garçom não lê serviços, preços nem profissionais');
END $$;

-- 37. Pet shop (agenda): sem sobreposição por profissional, preço congelado, transições válidas e motivo
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  tutor uuid; pet uuid; pet_sem_preco uuid; pet_inativo uuid; prof uuid; prof2 uuid; prof_off uuid; serv uuid; serv2 uuid; serv_sem uuid; ag uuid; ag2 uuid; ag3 uuid;
  base timestamptz := date_trunc('day', now()) + interval '2 days' + interval '9 hours';
  r record; tb uuid; n bigint;
BEGIN
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Tutor Agenda CI') RETURNING id INTO tutor;
  INSERT INTO tenants (nome) VALUES ('Agenda B') RETURNING id INTO tb;
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Thor', 'raca', 'Poodle', 'porte', 'pequeno', 'pelagem', 'longa'));
  pet_sem_preco := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Gigante', 'porte', 'gigante'));
  pet_inativo := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Inativo', 'porte', 'pequeno', 'ativo', false));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := pet_servico_salvar('{"nome":"Banho Agenda","duracao_min":60}'::jsonb);
  serv2 := pet_servico_salvar('{"nome":"Tosa Agenda","categoria":"tosa","duracao_min":30}'::jsonb);
  serv_sem := pet_servico_salvar('{"nome":"Hidratação Agenda","categoria":"estetica","duracao_min":45}'::jsonb);
  PERFORM pet_preco_salvar(serv, 'pequeno', NULL, NULL, 60);
  PERFORM pet_preco_salvar(serv, NULL, 'poodle', NULL, 90);
  PERFORM pet_preco_salvar(serv2, NULL, NULL, NULL, 40);
  prof := pet_profissional_salvar('{"nome":"Ana Agenda","funcao":"tosador","comissao_percentual":30}'::jsonb);
  prof2 := pet_profissional_salvar('{"nome":"Beto Agenda","funcao":"banhista"}'::jsonb);
  prof_off := pet_profissional_salvar('{"nome":"Inativo Agenda","ativo":false}'::jsonb);
  PERFORM ci.sair();

  -- quem agenda: administrador, gestor, vendedor e caixa
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet, prof, base, serv), 'garçom agenda');
  PERFORM ci.deve_falhar(est, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet, prof, base, serv), 'estoquista agenda');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet, prof, base, serv), 'anon agenda');

  -- validações
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet, prof, serv), 'sem horário');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', '[]'::jsonb))$c$, pet, prof, base), 'sem serviço');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet_inativo, prof, base, serv), 'pet inativo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet, prof_off, base, serv), 'profissional inativo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L), jsonb_build_object('servico_id', %L))))$c$, pet, prof, base, serv, serv), 'serviço repetido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet_sem_preco, prof, base, serv), 'pet sem preço para o serviço');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L, 'preco_avulso', 55))))$c$, pet_sem_preco, prof, base, serv), 'vendedor informa preço avulso');

  -- agendar (preço da raça vence o do porte; duração soma os serviços)
  PERFORM ci.entrar(vend);
  ag := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof, 'inicio', base, 'taxi_dog', true,
                    'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv), jsonb_build_object('servico_id', serv2))));
  PERFORM ci.sair();
  SELECT * INTO r FROM pet_agendamentos WHERE id = ag;
  PERFORM ci.exige(r.fim - r.inicio = interval '90 minutes' AND r.situacao = 'agendado' AND r.taxi_dog AND r.cliente_id = tutor, 'o fim soma a duração dos serviços; o tutor vem do pet');
  PERFORM ci.exige((SELECT sum(preco_aplicado) = 130 FROM pet_agendamento_itens WHERE agendamento_id = ag), 'banho de poodle (90) + tosa (40): vale o preço mais específico');

  -- preço congelado: mudar a tabela não muda o agendamento
  PERFORM ci.entrar(gest);
  PERFORM pet_preco_salvar(serv, NULL, 'poodle', NULL, 200);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT sum(preco_aplicado) = 130 FROM pet_agendamento_itens WHERE agendamento_id = ag), 'o preço combinado fica congelado');

  -- sobreposição: mesmo profissional não pode; encostar pode; outro profissional pode
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet, prof, base + interval '30 minutes', serv2), 'sobrepõe o horário do mesmo profissional');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agendar(jsonb_build_object('pet_id', %L, 'profissional_id', %L, 'inicio', %L::timestamptz, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', %L))))$c$, pet, prof, base - interval '20 minutes', serv), 'termina depois que o outro começa');
  PERFORM ci.entrar(vend);
  ag2 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof, 'inicio', base + interval '90 minutes', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv2))));
  ag3 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof2, 'inicio', base, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv2))));
  PERFORM ci.sair();
  PERFORM ci.exige(ag2 IS NOT NULL AND ag3 IS NOT NULL, 'um começa quando o outro termina; outro profissional no mesmo horário');

  -- preço avulso só da gestão, marcado no item
  PERFORM ci.entrar(gest);
  ag := pet_agendar(jsonb_build_object('pet_id', pet_sem_preco, 'profissional_id', prof, 'inicio', base + interval '5 hours',
                    'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv_sem, 'preco_avulso', 75))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT preco_aplicado = 75 AND preco_avulso FROM pet_agendamento_itens WHERE agendamento_id = ag), 'a gestão informa preço avulso e ele fica marcado');

  -- transições
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_situacao(%L, 'pronto')$c$, ag2), 'agendado direto para pronto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_situacao(%L, 'retirado')$c$, ag2), 'retirado não sai da agenda');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_situacao(%L, 'cancelado')$c$, ag2), 'cancelar sem motivo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_agenda_situacao(%L, 'confirmado')$c$, ag2), 'garçom muda situação');
  PERFORM ci.entrar(vend);
  PERFORM pet_agenda_situacao(ag2, 'confirmado');
  PERFORM pet_agenda_situacao(ag2, 'em_atendimento');
  PERFORM pet_agenda_situacao(ag2, 'pronto');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao FROM pet_agendamentos WHERE id = ag2) = 'pronto', 'agendado → confirmado → em atendimento → pronto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_situacao(%L, 'cancelado', 'desistiu')$c$, ag2), 'cancelar depois de pronto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_reagendar(%L, %L::timestamptz)$c$, ag2, base + interval '8 hours'), 'remarcar depois de pronto');

  -- cancelar libera o horário
  PERFORM ci.entrar(vend);
  PERFORM pet_agenda_situacao(ag3, 'cancelado', 'tutor desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelado' AND motivo = 'tutor desistiu' FROM pet_agendamentos WHERE id = ag3), 'cancelar guarda o motivo');
  PERFORM ci.entrar(vend);
  PERFORM pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof2, 'inicio', base, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv2))));
  PERFORM ci.sair();
  PERFORM ci.exige(true, 'o horário cancelado volta a ficar livre');

  -- remarcar
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_reagendar(%L, %L::timestamptz, %L)$c$, ag, base + interval '30 minutes', prof), 'remarcar para cima de outro atendimento');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_reagendar(%L, %L::timestamptz, %L)$c$, ag, base + interval '7 hours', prof_off), 'remarcar para profissional inativo');
  PERFORM ci.entrar(vend);
  PERFORM pet_reagendar(ag, base + interval '6 hours');                    -- o mesmo profissional, outro horário
  PERFORM pet_reagendar(ag, base + interval '6 hours 10 minutes', prof2);  -- outro profissional
  PERFORM ci.sair();
  SELECT * INTO r FROM pet_agendamentos WHERE id = ag;
  PERFORM ci.exige(r.profissional_id = prof2 AND r.fim - r.inicio = interval '45 minutes', 'remarcar mantém a duração e troca o profissional');

  -- leitura e escrita direta
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM pet_agendamentos') >= 3 AND ci.contar(gar, 'SELECT count(*) FROM pet_agendamentos') = 0
                   AND ci.contar(gar, 'SELECT count(*) FROM pet_agendamento_itens') = 0, 'o garçom não lê a agenda');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE pet_agendamentos SET situacao = 'retirado' WHERE id = %L$c$, ag2), 'escrita direta na agenda');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM pet_agendamento_itens WHERE agendamento_id = %L$c$, ag2), 'apagar item da agenda direto');
  SELECT count(*) INTO n FROM pet_agendamentos WHERE tenant_id = tb;
  PERFORM ci.exige(n = 0, 'a outra empresa não recebeu agendamentos');
END $$;

-- 38. Pet shop (cobrança): retirar e cobrar, comissão, NFS-e em rascunho, NFC-e só de mercadoria e venda cancelada
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  fin  constant uuid := 'a0000000-0000-0000-0000-0000000000b2';
  tutor uuid; pet uuid; prof uuid; serv uuid; serv_prod uuid; merc uuid; dep uuid; ag uuid; ag2 uuid; ag3 uuid;
  ped uuid; ped2 uuid; ped_so_serv uuid; ped_errado uuid; r jsonb; com uuid; nfe_ct bigint; n bigint;
  t0 timestamptz := date_trunc('day', now()) + interval '3 days' + interval '9 hours';
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Pet Cobrança CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, ncm, cst_csosn) VALUES (demo, 'PET-COB-RACAO', 'Ração cobrança', 'UN', 20, '23091000', '102') RETURNING id INTO merc;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Cobrança CI', '52998224725') RETURNING id INTO tutor;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(merc, dep, 'entrada'::mov_tipo, 50, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := pet_servico_salvar('{"nome":"Banho Cobrança","duracao_min":60}'::jsonb);
  PERFORM pet_preco_salvar(serv, NULL, NULL, NULL, 60);
  prof := pet_profissional_salvar('{"nome":"Cris Cobrança","funcao":"tosador","comissao_percentual":30}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO serv_prod FROM pet_servicos WHERE id = serv;
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Rex Cobrança', 'porte', 'pequeno'));
  ag := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv))));
  ag2 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof, 'inicio', t0 + interval '2 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv))));
  ag3 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof, 'inicio', t0 + interval '4 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv))));
  -- venda do caixa: serviço (60) + 2 rações (40), desconto de 10 no total
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 60),
                                          jsonb_build_object('produto_id', merc, 'quantidade', 2, 'preco_unitario', 20)),
                   'crediario', tutor, 10, 1, current_date + 30);
  ped_so_serv := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 60)), 'crediario', tutor, 0, 1, current_date + 30);
  ped_errado := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 50)), 'crediario', tutor, 0, 1, current_date + 30);
  PERFORM ci.sair();

  -- só atendimento pronto é cobrado
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag, ped), 'cobrar atendimento que ainda não está pronto');
  PERFORM ci.entrar(vend);
  PERFORM pet_agenda_situacao(ag, 'em_atendimento'); PERFORM pet_agenda_situacao(ag, 'pronto');
  PERFORM pet_agenda_situacao(ag2, 'em_atendimento'); PERFORM pet_agenda_situacao(ag2, 'pronto');
  PERFORM ci.sair();

  -- a venda tem de ser a certa
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag, ped), 'garçom cobra');
  PERFORM ci.deve_falhar(est, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag, ped), 'estoquista cobra');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag, ped), 'anon cobra');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L)$c$, ag), 'sem informar a venda');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag, ped_errado), 'venda com o serviço por outro valor');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag, gen_random_uuid()), 'venda que não existe');

  -- cobrar: comissão sobre a parte do serviço já com o desconto proporcional (60 de 100 → 54 → 30% = 16,20)
  PERFORM ci.entrar(vend);
  r := pet_agenda_retirar(ag, ped);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'retirado' AND venda_id = ped FROM pet_agendamentos WHERE id = ag), 'o atendimento fica retirado e ligado à venda');
  PERFORM ci.exige((SELECT base = 54 AND percentual = 30 AND valor = 16.20 AND situacao = 'a_aprovar' FROM pet_comissoes WHERE agendamento_id = ag),
                   'comissão de 30% sobre o serviço líquido do desconto, sem contar a ração');
  PERFORM ci.exige((SELECT modelo = 'nfse' AND situacao = 'rascunho' AND valor_total = 54 AND valor_produtos = 60 AND valor_desconto = 6 AND array_length(pendencias, 1) > 0
                      FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'NFS-e do serviço em rascunho, com as pendências de configuração');
  PERFORM ci.exige((SELECT count(*) = 1 FROM nfe_itens WHERE nfe_id = (r ->> 'nfe_id')::uuid), 'a NFS-e leva o serviço');

  -- repetir a chamada não duplica nada
  PERFORM ci.entrar(vend);
  r := pet_agenda_retirar(ag, ped);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) = 1 FROM pet_comissoes WHERE agendamento_id = ag)
                   AND (SELECT count(*) = 1 FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'repetir a cobrança não duplica comissão nem nota');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag2, ped), 'a mesma venda cobrando dois atendimentos');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_situacao(%L, 'cancelado', 'x')$c$, ag), 'cancelar atendimento já retirado');

  -- NFC-e: só a ração entra (40 − 4 de desconto proporcional = 36); venda só de serviço não gera NFC-e
  PERFORM ci.entrar(vend);
  PERFORM nfce_criar(ped);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT valor_produtos = 40 AND valor_desconto = 4 AND valor_total = 36 FROM nfe WHERE pedido_id = ped AND modelo = 'nfce'), 'a NFC-e leva só a mercadoria e a parte do desconto dela');
  PERFORM ci.exige((SELECT count(*) = 1 FROM nfe_itens WHERE nfe_id = (SELECT id FROM nfe WHERE pedido_id = ped AND modelo = 'nfce')), 'a NFC-e não leva o serviço');
  PERFORM ci.deve_falhar(vend, format($c$SELECT nfce_criar(%L)$c$, ped_so_serv), 'NFC-e de venda só de serviço');

  -- venda cancelada: atendimento volta a pronto, comissão cancelada e NFS-e em rascunho sai
  UPDATE pedidos SET situacao = 'cancelado' WHERE id = ped;
  PERFORM ci.exige((SELECT situacao = 'pronto' AND venda_id IS NULL FROM pet_agendamentos WHERE id = ag), 'venda cancelada devolve o atendimento a pronto');
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM pet_comissoes WHERE agendamento_id = ag), 'venda cancelada cancela a comissão');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'venda cancelada tira o rascunho da NFS-e');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, %L)$c$, ag, ped), 'cobrar com venda cancelada');

  -- cobrar de novo o mesmo atendimento com outra venda: a comissão cancelada volta a valer
  PERFORM ci.entrar(vend);
  ped2 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 60)), 'crediario', tutor, 0, 1, current_date + 30);
  r := pet_agenda_retirar(ag, ped2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'a_aprovar' AND pedido_id = ped2 AND base = 60 AND valor = 18 FROM pet_comissoes WHERE agendamento_id = ag), 'cobrar de novo reativa a comissão cancelada, com a nova venda');
  PERFORM ci.exige((SELECT count(*) = 1 FROM pet_comissoes WHERE agendamento_id = ag) AND EXISTS (SELECT 1 FROM nfe WHERE pedido_id = ped2 AND modelo = 'nfse'), 'uma comissão por atendimento e nova NFS-e em rascunho');
  PERFORM ci.entrar(vend);
  -- ag2 (outro atendimento pronto) usa a venda só de serviço
  r := pet_agenda_retirar(ag2, ped_so_serv);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT base = 60 AND valor = 18 FROM pet_comissoes WHERE agendamento_id = ag2), 'sem desconto, a comissão é 30% do valor do serviço');

  -- comissões: aprovar e pagar
  SELECT id INTO com FROM pet_comissoes WHERE agendamento_id = ag2;
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_comissao_aprovar(%L)$c$, com), 'vendedor aprova comissão');
  PERFORM ci.deve_falhar(fin, format($c$SELECT pet_comissao_pagar(%L)$c$, com), 'pagar comissão não aprovada');
  PERFORM ci.entrar(fin);
  PERFORM pet_comissao_aprovar(com);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(fin, format($c$SELECT pet_comissao_aprovar(%L)$c$, com), 'aprovar duas vezes');
  PERFORM ci.entrar(gest);
  PERFORM pet_comissao_pagar(com, 'pix');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'paga' AND forma_pagamento = 'pix' AND pago_em IS NOT NULL AND pago_por IS NOT NULL FROM pet_comissoes WHERE id = com), 'comissão paga com registro de quem e quando');

  -- relatório por profissional (retirados no período)
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_servicos_por_profissional(current_date, current_date + 5)$c$), 'vendedor lê o relatório');
  PERFORM ci.entrar(fin);
  r := pet_servicos_por_profissional(current_date, current_date + 10);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT (e ->> 'atendimentos')::int = 2 AND (e ->> 'faturamento')::numeric = 120 AND (e ->> 'comissao_paga')::numeric = 18
                           AND (e ->> 'comissao_a_aprovar')::numeric = 18
                      FROM jsonb_array_elements(r) e WHERE e ->> 'nome' = 'Cris Cobrança'), 'relatório: dois atendimentos retirados, R$ 120, comissão paga de R$ 18 e R$ 18 a aprovar');

  -- leitura e escrita direta
  PERFORM ci.exige(ci.contar(fin, 'SELECT count(*) FROM pet_comissoes') >= 2 AND ci.contar(vend, 'SELECT count(*) FROM pet_comissoes') = 0
                   AND ci.contar(gar, 'SELECT count(*) FROM pet_comissoes') = 0, 'só administrador, gestor e financeiro leem comissões');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE pet_comissoes SET valor = 999 WHERE id = %L$c$, com), 'alterar comissão direto');
  SELECT count(*) INTO n FROM pet_comissoes WHERE tenant_id <> demo;
  PERFORM ci.exige(n = 0, 'nenhuma comissão fora da empresa');
END $$;

-- 39. Pet shop (contatos): aniversário e retorno de banho, uma vez por ocasião
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  tutor uuid; p_aniv uuid; p_aniv_longe uuid; p_bissexto uuid; p_ret uuid; p_ret_marcado uuid; p_recente uuid; p_inativo uuid; p_nunca uuid;
  prof uuid; serv uuid; ag uuid; r jsonb; tb uuid; n bigint; ref date;
BEGIN
  INSERT INTO clientes (tenant_id, nome, telefone) VALUES (demo, 'Tutor Contato CI', '(16) 99999-1234') RETURNING id INTO tutor;
  INSERT INTO tenants (nome) VALUES ('Contato B') RETURNING id INTO tb;
  PERFORM ci.entrar(adm);
  serv := pet_servico_salvar('{"nome":"Banho Contato","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(serv, NULL, NULL, NULL, 50);
  prof := pet_profissional_salvar('{"nome":"Dani Contato"}'::jsonb);
  p_aniv := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Aniv Hoje', 'nascimento', (hoje - interval '3 years')::date));
  p_aniv_longe := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Aniv Longe', 'nascimento', (hoje + interval '40 days' - interval '2 years')::date));
  p_bissexto := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Aniv Em 5 Dias', 'nascimento', (hoje + interval '5 days' - interval '1 year')::date));
  p_ret := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Retorno 40 dias'));
  p_ret_marcado := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Retorno com horário'));
  p_recente := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Banho recente'));
  p_inativo := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Inativo', 'ativo', false, 'nascimento', (hoje - interval '1 year')::date));
  p_nunca := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Nunca veio'));
  PERFORM ci.sair();

  -- atendimentos retirados no passado (inserção direta de teste, como dono) e um futuro
  INSERT INTO pet_agendamentos (tenant_id, pet_id, cliente_id, profissional_id, inicio, fim, situacao)
  VALUES (demo, p_ret, tutor, prof, now() - interval '40 days', now() - interval '40 days' + interval '30 minutes', 'retirado'),
         (demo, p_ret_marcado, tutor, prof, now() - interval '50 days', now() - interval '50 days' + interval '30 minutes', 'retirado'),
         (demo, p_ret_marcado, tutor, prof, now() + interval '3 days', now() + interval '3 days' + interval '30 minutes', 'agendado'),
         (demo, p_recente, tutor, prof, now() - interval '5 days', now() - interval '5 days' + interval '30 minutes', 'retirado');

  -- quem vê as listas
  PERFORM ci.deve_falhar(gar, $c$SELECT pet_contatos_pendentes('retorno')$c$, 'garçom vê contatos');
  PERFORM ci.deve_falhar(est, $c$SELECT pet_contatos_pendentes('retorno')$c$, 'estoquista vê contatos');
  PERFORM ci.deve_falhar(NULL, $c$SELECT pet_contatos_pendentes('retorno')$c$, 'anon vê contatos');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_contatos_pendentes('qualquer')$c$, 'tipo inválido');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_contatos_pendentes('retorno', 3)$c$, 'prazo curto demais');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_contatos_pendentes('aniversario', 30, 90)$c$, 'janela grande demais');

  -- aniversário: hoje e daqui a 5 dias entram; 40 dias e inativo não
  PERFORM ci.entrar(vend);
  r := pet_contatos_pendentes('aniversario', 30, 7);
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Aniv Hoje' AND (e ->> 'anos')::int = 3 AND (e ->> 'referencia')::date = hoje),
                   'o aniversário de hoje entra, com a idade');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Aniv Em 5 Dias'), 'o aniversário dos próximos dias entra');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' IN ('Aniv Longe', 'Inativo')), 'aniversário distante e pet inativo ficam de fora');
  PERFORM ci.exige((SELECT e ->> 'telefone' FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Aniv Hoje') = '(16) 99999-1234', 'traz o telefone do tutor');

  -- registrar o contato tira da lista, uma vez só por ocasião, e é idempotente
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_contato_registrar(%L, 'aniversario', %L)$c$, p_aniv, hoje), 'garçom registra contato');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_contato_registrar(%L, 'aniversario', %L, 'pombo')$c$, p_aniv, hoje), 'canal inválido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_contato_registrar(%L, 'aniversario', %L)$c$, gen_random_uuid(), hoje), 'pet que não existe');
  PERFORM ci.entrar(vend);
  PERFORM pet_contato_registrar(p_aniv, 'aniversario', hoje, 'whatsapp');
  PERFORM pet_contato_registrar(p_aniv, 'aniversario', hoje, 'telefone', 'repetido');
  r := pet_contatos_pendentes('aniversario', 30, 7);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Aniv Hoje'), 'quem já foi chamado sai da lista');
  PERFORM ci.exige((SELECT count(*) = 1 FROM pet_contatos WHERE pet_id = p_aniv), 'repetir o registro não duplica');

  -- retorno de banho: 40 dias sem vir entra; recente, com horário marcado, sem histórico e inativo não
  PERFORM ci.entrar(vend);
  r := pet_contatos_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Retorno 40 dias' AND (e ->> 'dias')::int >= 40), 'retorno de quem está há mais de 30 dias sem vir');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' IN ('Retorno com horário', 'Banho recente', 'Nunca veio', 'Inativo')),
                   'com horário marcado, atendimento recente, sem histórico e inativo ficam de fora');
  PERFORM ci.entrar(vend);
  r := pet_contatos_pendentes('retorno', 60);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Retorno 40 dias'), 'o prazo maior tira quem veio há 40 dias');

  -- contato do retorno vale para aquele último atendimento; um atendimento novo abre outra ocasião
  PERFORM ci.entrar(vend);
  r := pet_contatos_pendentes('retorno', 30);
  SELECT (e ->> 'referencia')::date INTO ref FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Retorno 40 dias';
  PERFORM pet_contato_registrar(p_ret, 'retorno', ref, 'telefone');
  r := pet_contatos_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Retorno 40 dias'), 'depois do contato, o retorno some da lista');

  -- leitura direta só da empresa, sem escrita direta, outra empresa sem registros
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM pet_contatos') = 2 AND ci.contar(gar, 'SELECT count(*) FROM pet_contatos') = 0, 'o garçom não lê contatos');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO pet_contatos (pet_id, tipo, referencia) VALUES (%L, 'retorno', current_date)$c$, p_ret), 'escrita direta em contatos');
  PERFORM ci.deve_falhar(adm, $c$DELETE FROM pet_contatos$c$, 'apagar contato direto');
  SELECT count(*) INTO n FROM pet_contatos WHERE tenant_id = tb;
  PERFORM ci.exige(n = 0, 'a outra empresa não recebeu contatos');

  -- a lista de retorno tem teto de 300 (mais antigos primeiro), mesmo com mais pets elegíveis
  INSERT INTO pets (tenant_id, cliente_id, nome) SELECT demo, tutor, 'Massa ' || g FROM generate_series(1, 305) g;
  INSERT INTO pet_agendamentos (tenant_id, pet_id, cliente_id, profissional_id, inicio, fim, situacao)
  SELECT demo, p.id, tutor, prof, now() - interval '100 days', now() - interval '100 days' + interval '30 minutes', 'retirado'
    FROM pets p WHERE p.tenant_id = demo AND p.nome LIKE 'Massa %';
  PERFORM ci.entrar(vend);
  r := pet_contatos_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 300, 'a lista de retorno é limitada a 300 pets');
END $$;

-- 40. Pet shop (pacotes): venda adiantada, uso na retirada, aviso do penúltimo banho, validade e cancelamento
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  t0 timestamptz := date_trunc('day', now()) + interval '5 days' + interval '8 hours';
  tutor uuid; pet_a uuid; pet_b uuid; prof uuid; banho uuid; tosa uuid; banho_prod uuid; tosa_prod uuid; mod uuid; mod_prod uuid; dep uuid; merc uuid;
  ped_pac uuid; ped_tosa uuid; ped_errada uuid; ped_sem uuid; pac uuid; pac2 uuid; ag1 uuid; ag2 uuid; ag3 uuid; ag4 uuid; ag5 uuid; agb uuid; agm uuid;
  r jsonb; n bigint; tb uuid;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Pet Pacote CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, ncm, cst_csosn) VALUES (demo, 'PET-PAC-RACAO', 'Ração pacote', 'UN', 20, '23091000', '102') RETURNING id INTO merc;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Pacote CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO tenants (nome) VALUES ('Pacote B') RETURNING id INTO tb;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(merc, dep, 'entrada'::mov_tipo, 20, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  banho := pet_servico_salvar('{"nome":"Banho Pacote","duracao_min":30}'::jsonb);
  tosa := pet_servico_salvar('{"nome":"Tosa Pacote","categoria":"tosa","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(banho, NULL, NULL, NULL, 60);
  PERFORM pet_preco_salvar(tosa, NULL, NULL, NULL, 40);
  prof := pet_profissional_salvar('{"nome":"Eli Pacote","comissao_percentual":30}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO banho_prod FROM pet_servicos WHERE id = banho;
  SELECT produto_id INTO tosa_prod FROM pet_servicos WHERE id = tosa;
  PERFORM ci.entrar(vend);
  pet_a := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Pacote A'));
  pet_b := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Pacote B'));
  PERFORM ci.sair();

  -- modelo de pacote: só administrador e gestor; validações
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pacote_modelo_salvar(jsonb_build_object('nome','P','servico_id',%L,'quantidade',4,'preco',200))$c$, banho), 'vendedor cria modelo de pacote');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_pacote_modelo_salvar(jsonb_build_object('nome','','servico_id',%L,'quantidade',4,'preco',200))$c$, banho), 'pacote sem nome');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_pacote_modelo_salvar(jsonb_build_object('nome','P','servico_id',%L,'quantidade',1,'preco',200))$c$, banho), 'pacote de um serviço só');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_pacote_modelo_salvar(jsonb_build_object('nome','P','servico_id',%L,'quantidade',4,'preco',0))$c$, banho), 'pacote sem preço');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_pacote_modelo_salvar(jsonb_build_object('nome','P','servico_id',%L,'quantidade',4,'preco',200))$c$, gen_random_uuid()), 'pacote de serviço que não existe');
  PERFORM ci.entrar(gest);
  mod := pet_pacote_modelo_salvar(jsonb_build_object('nome', 'Pacote 4 banhos', 'servico_id', banho, 'quantidade', 4, 'preco', 200));
  PERFORM ci.sair();
  SELECT produto_id INTO mod_prod FROM pet_pacote_modelos WHERE id = mod;
  PERFORM ci.exige((SELECT NOT controla_estoque AND preco_venda = 200 AND codigo_interno <> '' FROM produtos WHERE id = mod_prod), 'o pacote vira um produto sem estoque, com código automático');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_pacote_modelo_salvar(jsonb_build_object('nome',' pacote 4 BANHOS ','servico_id',%L,'quantidade',4,'preco',200))$c$, banho), 'nome de pacote repetido');

  -- venda do pacote no caixa (200 com 20 de desconto = 180)
  PERFORM ci.entrar(vend);
  ped_pac := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', mod_prod, 'quantidade', 1, 'preco_unitario', 200)), 'crediario', tutor, 20, 1, current_date + 30);
  ped_errada := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', mod_prod, 'quantidade', 1, 'preco_unitario', 150)), 'crediario', tutor, 0, 1, current_date + 30);
  ped_sem := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', banho_prod, 'quantidade', 1, 'preco_unitario', 60)), 'crediario', tutor, 0, 1, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_pacote_vender(%L, %L, 60, %L)$c$, mod, pet_a, ped_pac), 'garçom vende pacote');
  PERFORM ci.deve_falhar(est, format($c$SELECT pet_pacote_vender(%L, %L, 60, %L)$c$, mod, pet_a, ped_pac), 'estoquista vende pacote');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pacote_vender(%L, %L, 45, %L)$c$, mod, pet_a, ped_pac), 'validade de 45 dias');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pacote_vender(%L, %L, 60)$c$, mod, pet_a), 'sem informar a venda');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pacote_vender(%L, %L, 60, %L)$c$, mod, pet_a, ped_errada), 'venda com o pacote por outro valor');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pacote_vender(%L, %L, 60, %L)$c$, mod, pet_a, ped_sem), 'venda sem o pacote');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pacote_vender(%L, %L, 60, %L)$c$, mod, gen_random_uuid(), ped_pac), 'pet que não existe');
  PERFORM ci.entrar(vend);
  r := pet_pacote_vender(mod, pet_a, 60, ped_pac);
  PERFORM ci.sair();
  pac := (r ->> 'pacote_id')::uuid;
  PERFORM ci.deve_falhar(vend, format($c$SELECT nfce_criar(%L)$c$, ped_pac), 'NFC-e de venda só de pacote (a nota é de serviço)');
  PERFORM ci.exige(pg_get_functiondef('public.pet_agenda_retirar(uuid, uuid, uuid, boolean)'::regprocedure) LIKE '%pg_advisory_xact_lock(hashtextextended(''pet_pacote:''%',
                   'retirar trava o pacote do pet antes de gastar o saldo');
  PERFORM ci.exige((SELECT quantidade = 4 AND valor = 180 AND validade_dias = 60 AND vence_em = hoje + 60 AND situacao = 'ativo' AND pet_id = pet_a FROM pet_pacotes WHERE id = pac),
                   'o pacote guarda 4 banhos, o valor pago (180), a validade e o pet');
  PERFORM ci.exige((SELECT modelo = 'nfse' AND situacao = 'rascunho' AND valor_total = 180 AND valor_produtos = 200 FROM nfe WHERE pedido_id = ped_pac), 'a NFS-e do pacote nasce na venda, em rascunho');
  PERFORM ci.entrar(vend);
  r := pet_pacote_vender(mod, pet_a, 60, ped_pac);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) = 1 FROM pet_pacotes WHERE venda_id = ped_pac) AND (SELECT count(*) = 1 FROM nfe WHERE pedido_id = ped_pac AND modelo = 'nfse'),
                   'repetir a venda do pacote não duplica pacote nem nota');

  -- atendimentos do pet A (4 banhos) e do pet B (sem pacote)
  PERFORM ci.entrar(vend);
  ag1 := pet_agendar(jsonb_build_object('pet_id', pet_a, 'profissional_id', prof, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  ag2 := pet_agendar(jsonb_build_object('pet_id', pet_a, 'profissional_id', prof, 'inicio', t0 + interval '1 hour', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  ag3 := pet_agendar(jsonb_build_object('pet_id', pet_a, 'profissional_id', prof, 'inicio', t0 + interval '2 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  ag4 := pet_agendar(jsonb_build_object('pet_id', pet_a, 'profissional_id', prof, 'inicio', t0 + interval '3 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  ag5 := pet_agendar(jsonb_build_object('pet_id', pet_a, 'profissional_id', prof, 'inicio', t0 + interval '4 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  agb := pet_agendar(jsonb_build_object('pet_id', pet_b, 'profissional_id', prof, 'inicio', t0 + interval '5 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  agm := pet_agendar(jsonb_build_object('pet_id', pet_a, 'profissional_id', prof, 'inicio', t0 + interval '6 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho), jsonb_build_object('servico_id', tosa))));
  PERFORM pet_agenda_situacao(x, 'em_atendimento') FROM unnest(ARRAY[ag1, ag2, ag3, ag4, ag5, agb, agm]) x;
  PERFORM pet_agenda_situacao(x, 'pronto') FROM unnest(ARRAY[ag1, ag2, ag3, ag4, ag5, agb, agm]) x;
  PERFORM ci.sair();

  -- cobertura: só o pacote do próprio pet, dentro da validade e com saldo
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_agenda_cobertura(%L)$c$, ag1), 'garçom consulta cobertura');
  PERFORM ci.entrar(vend);
  r := pet_agenda_cobertura(ag1);
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND (r -> 0 ->> 'restam')::int = 4 AND (r -> 0 ->> 'pacote_id')::uuid = pac, 'o banho do pet A é coberto pelo pacote (restam 4)');
  PERFORM ci.exige(jsonb_array_length(pet_agenda_cobertura(agb)) = 0, 'o pacote não vale para outro pet, mesmo do mesmo tutor');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, NULL, NULL, true)$c$, agb), 'usar pacote que o pet não tem, sem venda');

  -- usar o pacote: sem venda, sem NFS-e; comissão sobre o valor do uso (180 / 4 = 45 → 13,50); avisa no penúltimo
  PERFORM ci.entrar(vend);
  r := pet_agenda_retirar(ag1, NULL, NULL, true);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'retirado' AND venda_id IS NULL FROM pet_agendamentos WHERE id = ag1), 'retirada só com pacote: sem venda');
  PERFORM ci.exige((r ->> 'nfe_id') IS NULL AND jsonb_array_length(r -> 'avisos') = 0 AND (r ->> 'usos')::int = 1, 'sem NFS-e do uso e sem aviso no primeiro banho');
  PERFORM ci.exige((SELECT base = 45 AND valor = 13.50 FROM pet_comissoes WHERE agendamento_id = ag1), 'comissão de 30% sobre o valor de um banho do pacote');
  PERFORM ci.exige((SELECT quantidade - (SELECT count(*)::int FROM pet_pacote_usos u WHERE u.pacote_id = pac AND NOT u.desfeito) FROM pet_pacotes WHERE id = pac) = 3, 'restam 3 banhos');
  PERFORM ci.entrar(vend);
  r := pet_agenda_retirar(ag1, NULL, NULL, true);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT quantidade - (SELECT count(*)::int FROM pet_pacote_usos u WHERE u.pacote_id = pac AND NOT u.desfeito) FROM pet_pacotes WHERE id = pac) = 3, 'repetir a retirada não gasta outro banho');

  PERFORM ci.entrar(vend);
  r := pet_agenda_retirar(ag2, NULL, NULL, true);
  PERFORM ci.exige(jsonb_array_length(r -> 'avisos') = 0 AND (SELECT quantidade - (SELECT count(*)::int FROM pet_pacote_usos u WHERE u.pacote_id = pac AND NOT u.desfeito) FROM pet_pacotes WHERE id = pac) = 2, 'segundo uso: restam 2, sem aviso ainda');
  r := pet_agenda_retirar(ag3, NULL, NULL, true);   -- penúltimo banho do pacote
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'avisos') = 1 AND (r -> 'avisos' -> 0 ->> 'restam')::int = 1 AND (r -> 'avisos' -> 0 ->> 'pet') = 'Pacote A',
                   'no penúltimo banho o sistema avisa que resta só 1');
  PERFORM ci.entrar(vend);
  r := pet_agenda_retirar(ag4, NULL, NULL, true);   -- último
  PERFORM ci.sair();
  PERFORM ci.exige((r -> 'avisos' -> 0 ->> 'restam')::int = 0 AND (SELECT quantidade - (SELECT count(*)::int FROM pet_pacote_usos u WHERE u.pacote_id = pac AND NOT u.desfeito) FROM pet_pacotes WHERE id = pac) = 0, 'o último banho esgota o pacote');
  PERFORM ci.entrar(vend);
  r := pet_agenda_cobertura(ag5);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 0, 'pacote esgotado não cobre mais');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, NULL, NULL, true)$c$, ag5), 'usar pacote esgotado sem venda');

  -- desfazer retirada feita só com pacote: só a gestão
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_desfazer_retirada(%L)$c$, ag4), 'vendedor desfaz retirada');
  PERFORM ci.entrar(gest);
  PERFORM pet_agenda_desfazer_retirada(ag4);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'pronto' FROM pet_agendamentos WHERE id = ag4) AND (SELECT quantidade - (SELECT count(*)::int FROM pet_pacote_usos u WHERE u.pacote_id = pac AND NOT u.desfeito) FROM pet_pacotes WHERE id = pac) = 1
                   AND (SELECT situacao = 'cancelada' FROM pet_comissoes WHERE agendamento_id = ag4), 'desfazer devolve o banho ao pacote e cancela a comissão');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_agenda_desfazer_retirada(%L)$c$, ag4), 'desfazer atendimento que não está retirado');

  -- atendimento misto: o banho sai do pacote e a tosa é cobrada no caixa (com uma ração junto)
  PERFORM ci.entrar(vend);
  ped_tosa := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', tosa_prod, 'quantidade', 1, 'preco_unitario', 40),
                                               jsonb_build_object('produto_id', merc, 'quantidade', 1, 'preco_unitario', 20)), 'crediario', tutor, 0, 1, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, NULL, NULL, true)$c$, agm), 'misto sem a venda da tosa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_agenda_retirar(%L, %L, NULL, true)$c$, agm, ped_sem), 'misto com venda que não traz a tosa');
  PERFORM ci.entrar(vend);
  r := pet_agenda_retirar(agm, ped_tosa, NULL, true);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade - (SELECT count(*)::int FROM pet_pacote_usos u WHERE u.pacote_id = pac AND NOT u.desfeito) FROM pet_pacotes WHERE id = pac) = 0 AND (r ->> 'usos')::int = 1, 'o banho do atendimento misto saiu do pacote');
  PERFORM ci.exige((SELECT base = 85 AND valor = 25.50 FROM pet_comissoes WHERE agendamento_id = agm), 'comissão: tosa cobrada (40) + banho do pacote (45) = 85 × 30%');
  PERFORM ci.exige((SELECT valor_total = 40 AND valor_produtos = 40 FROM nfe WHERE pedido_id = ped_tosa AND modelo = 'nfse'), 'a NFS-e do atendimento leva só o que foi cobrado agora (a tosa)');
  UPDATE pedidos SET situacao = 'cancelado' WHERE id = ped_tosa;
  PERFORM ci.exige((SELECT quantidade - (SELECT count(*)::int FROM pet_pacote_usos u WHERE u.pacote_id = pac AND NOT u.desfeito) FROM pet_pacotes WHERE id = pac) = 1 AND (SELECT situacao = 'pronto' AND venda_id IS NULL FROM pet_agendamentos WHERE id = agm), 'cancelar a venda devolve o banho ao pacote e o atendimento a pronto');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_agenda_desfazer_retirada(%L)$c$, agm), 'desfazer atendimento que não está retirado (misto cancelado)');

  -- validade e cancelamento do pacote
  UPDATE pet_pacotes SET vence_em = hoje - 1 WHERE id = pac;
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM _pet_cobertura(ag5)), 'pacote vencido não cobre');
  UPDATE pet_pacotes SET vence_em = hoje + 10 WHERE id = pac;
  PERFORM ci.exige(EXISTS (SELECT 1 FROM _pet_cobertura(ag5)), 'dentro da validade volta a cobrir');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pacote_cancelar(%L, 'x')$c$, pac), 'vendedor cancela pacote');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_pacote_cancelar(%L, '')$c$, pac), 'cancelar pacote sem motivo');
  PERFORM ci.entrar(gest);
  PERFORM pet_pacote_cancelar(pac, 'tutor desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM _pet_cobertura(ag5)), 'pacote cancelado não cobre');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_pacote_cancelar(%L, 'de novo')$c$, pac), 'cancelar duas vezes');

  -- venda do pacote cancelada no caixa: pacote cancelado e rascunho da NFS-e some
  PERFORM ci.entrar(vend);
  ped_errada := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', mod_prod, 'quantidade', 1, 'preco_unitario', 200)), 'crediario', tutor, 0, 1, current_date + 30);
  pac2 := (pet_pacote_vender(mod, pet_b, 30, ped_errada) ->> 'pacote_id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT vence_em = hoje + 30 AND valor = 200 FROM pet_pacotes WHERE id = pac2), 'pacote de 30 dias para o pet B, sem desconto');
  UPDATE pedidos SET situacao = 'cancelado' WHERE id = ped_errada;
  PERFORM ci.exige((SELECT situacao = 'cancelado' FROM pet_pacotes WHERE id = pac2) AND NOT EXISTS (SELECT 1 FROM nfe WHERE pedido_id = ped_errada AND modelo = 'nfse'),
                   'cancelar a venda cancela o pacote e tira a NFS-e em rascunho');

  -- leitura e escrita direta; outra empresa
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM pet_pacotes') >= 2 AND ci.contar(gar, 'SELECT count(*) FROM pet_pacotes') = 0
                   AND ci.contar(gar, 'SELECT count(*) FROM pet_pacote_usos') = 0 AND ci.contar(gar, 'SELECT count(*) FROM pet_pacote_modelos') = 0, 'o garçom não lê pacotes');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE pet_pacotes SET quantidade = 99 WHERE id = %L$c$, pac), 'alterar pacote direto');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM pet_pacote_usos WHERE pacote_id = %L$c$, pac), 'apagar uso direto');
  SELECT count(*) INTO n FROM pet_pacotes WHERE tenant_id = tb;
  PERFORM ci.exige(n = 0, 'a outra empresa não recebeu pacotes');
END $$;

-- 41. Pet shop (granel): abrir saco baixa o saco e dá entrada dos kg no granel pelo custo proporcional
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  saco uuid; gran uuid; solto uuid; servico uuid; dep uuid; tb uuid; prod_b uuid;
  r jsonb; n bigint;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Granel CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'GR-SACO', 'Ração saco 15kg', 'UN', 90, 150) RETURNING id INTO saco;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'GR-KG', 'Ração a granel', 'KG', 0, 12) RETURNING id INTO gran;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'GR-SOLTO', 'Produto sem granel', 'UN', 10, 20) RETURNING id INTO solto;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_estoque) VALUES (demo, 'GR-SERV', 'Serviço', 'UN', 10, false) RETURNING id INTO servico;
  INSERT INTO tenants (nome) VALUES ('Granel B') RETURNING id INTO tb;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda) VALUES (tb, 'GR-B', 'Granel de outra empresa', 'KG', 5) RETURNING id INTO prod_b;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(saco, dep, 'entrada'::mov_tipo, 3, 'ci', 'ci', NULL, 90);
  PERFORM ci.sair();

  -- cadastro do granel: restrições
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET granel_produto_id = %L WHERE id = %L$c$, gran, saco), 'granel sem o fator de kg');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET granel_produto_id = %L, granel_fator = 0 WHERE id = %L$c$, gran, saco), 'fator zero');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET granel_produto_id = %L, granel_fator = 15 WHERE id = %L$c$, saco, saco), 'saco que é o próprio granel');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET granel_produto_id = %L, granel_fator = 15 WHERE id = %L$c$, prod_b, saco), 'granel de outra empresa');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET granel_produto_id = %L, granel_fator = 15 WHERE id = %L$c$, servico, saco), 'granel que é serviço');
  UPDATE produtos SET granel_produto_id = gran, granel_fator = 15 WHERE id = saco;
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET granel_produto_id = %L, granel_fator = 10 WHERE id = %L$c$, saco, gran), 'cadeia: o granel virar saco');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET granel_produto_id = %L, granel_fator = 10 WHERE id = %L$c$, solto, gran), 'granel que já é granel de outro saco virar saco');

  -- quem pode abrir
  PERFORM ci.deve_falhar(vend, format($c$SELECT granel_abrir_saco(%L, %L, 1)$c$, saco, dep), 'vendedor abre saco');
  PERFORM ci.deve_falhar(gar, format($c$SELECT granel_abrir_saco(%L, %L, 1)$c$, saco, dep), 'garçom abre saco');
  PERFORM ci.deve_falhar(adm, format($c$SELECT granel_abrir_saco(%L, %L, 0)$c$, saco, dep), 'abrir zero sacos');
  PERFORM ci.deve_falhar(adm, format($c$SELECT granel_abrir_saco(%L, %L, 1)$c$, solto, dep), 'produto sem granel cadastrado');
  PERFORM ci.deve_falhar(adm, format($c$SELECT granel_abrir_saco(%L, %L, 1)$c$, saco, gen_random_uuid()), 'depósito que não existe');
  PERFORM ci.deve_falhar(adm, format($c$SELECT granel_abrir_saco(%L, %L, 4)$c$, saco, dep), 'abrir mais sacos do que há');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = saco AND deposito_id = dep) = 3 AND NOT EXISTS (SELECT 1 FROM estoques WHERE produto_id = gran AND deposito_id = dep AND quantidade > 0),
                   'abertura recusada não mexe no estoque');

  -- abrir 1 saco: 15 kg a 90 / 15 = 6 por kg
  PERFORM ci.entrar(est);
  r := granel_abrir_saco(saco, dep, 1);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'kg')::numeric = 15 AND (r ->> 'custo_kg')::numeric = 6, 'abrir 1 saco dá 15 kg a 6,00 o kg');
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = saco AND deposito_id = dep) = 2
                   AND (SELECT quantidade FROM estoques WHERE produto_id = gran AND deposito_id = dep) = 15
                   AND (SELECT custo_medio FROM estoques WHERE produto_id = gran AND deposito_id = dep) = 6, 'saldo: 2 sacos e 15 kg a custo médio 6');

  -- vender 2,5 kg pelo caminho normal de estoque
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(gran, dep, 'saida'::mov_tipo, 2.5, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = gran AND deposito_id = dep) = 12.5, 'a venda por kg baixa casas decimais');

  -- abrir 2 sacos de uma vez: o custo médio do granel se mantém
  PERFORM ci.entrar(gest);
  r := granel_abrir_saco(saco, dep, 2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoques WHERE produto_id = saco AND deposito_id = dep) = 0
                   AND (SELECT quantidade FROM estoques WHERE produto_id = gran AND deposito_id = dep) = 42.5
                   AND (SELECT custo_medio FROM estoques WHERE produto_id = gran AND deposito_id = dep) = 6, 'abrir 2 sacos soma 30 kg ao granel');
  PERFORM ci.exige((SELECT count(*) FROM estoque_movimentacoes WHERE produto_id = gran AND documento = 'Abertura de saco') = 2
                   AND (SELECT sum(sacos) FROM granel_aberturas WHERE saco_produto_id = saco) = 3, 'as aberturas ficam no histórico do estoque e na tabela de aberturas');

  -- leitura e escrita direta; outra empresa
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM granel_aberturas') = 2 AND ci.contar(gar, 'SELECT count(*) FROM granel_aberturas') = 0, 'o garçom não lê aberturas');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM granel_aberturas WHERE saco_produto_id = %L$c$, saco), 'apagar abertura direto');
  SELECT count(*) INTO n FROM granel_aberturas WHERE tenant_id = tb;
  PERFORM ci.exige(n = 0, 'a outra empresa não recebeu aberturas');
END $$;

-- 42. Pet shop (agenda do profissional): conta ligada ao cadastro, só a agenda dele, isolamento do perfil
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  p1   constant uuid := 'a0000000-0000-0000-0000-0000000000d1';
  p2   constant uuid := 'a0000000-0000-0000-0000-0000000000d2';
  psem constant uuid := 'a0000000-0000-0000-0000-0000000000d3';
  pmix constant uuid := 'a0000000-0000-0000-0000-0000000000d4';
  pout constant uuid := 'a0000000-0000-0000-0000-0000000000d5';
  t0 timestamptz := date_trunc('day', now()) + interval '9 days' + interval '8 hours';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  tutor uuid; pet uuid; serv uuid; prof1 uuid; prof2 uuid; ag1 uuid; ag2 uuid; ag3 uuid; tb uuid;
  r jsonb; n bigint;
BEGIN
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Maria Tutora CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO tenants (nome) VALUES ('Prof B') RETURNING id INTO tb;
  INSERT INTO auth.users (id, email) VALUES (p1, 'prof1@ci'), (p2, 'prof2@ci'), (psem, 'profsem@ci'), (pmix, 'profmix@ci'), (pout, 'profout@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (p1, p2, psem, pmix);
  UPDATE profiles SET tenant_id = tb WHERE id = pout;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (p1, demo, 'profissional'), (p2, demo, 'profissional'), (psem, demo, 'profissional'),
    (pmix, demo, 'profissional'), (pmix, demo, 'vendedor'), (pout, tb, 'profissional');

  PERFORM ci.entrar(gest);
  serv := pet_servico_salvar('{"nome":"Banho Agenda Prof","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(serv, NULL, NULL, NULL, 60);
  prof1 := pet_profissional_salvar('{"nome":"Ana Banhista CI","comissao_percentual":30}'::jsonb);
  prof2 := pet_profissional_salvar('{"nome":"Beto Tosador CI","comissao_percentual":30}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Rex Agenda Prof', 'alergias', 'frango'));
  ag1 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof1, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv))));
  ag2 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof1, 'inicio', t0 + interval '2 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv))));
  ag3 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', prof2, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', serv))));
  PERFORM ci.sair();

  -- vínculo: só a gestão; a conta precisa ser da empresa, ativa e com o perfil profissional; uma conta por cadastro
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, prof1, p1), 'vendedor liga conta ao profissional');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, prof1, p1), 'o próprio profissional se liga');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, prof1, vend), 'conta sem o perfil profissional');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, prof1, pout), 'conta de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, gen_random_uuid(), p1), 'profissional que não existe');
  PERFORM ci.entrar(gest);
  PERFORM pet_profissional_vincular(prof1, p1);
  PERFORM pet_profissional_vincular(prof2, p2);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, prof2, p1), 'mesma conta em dois profissionais');

  -- agenda: só a dele, sem preço nem telefone
  PERFORM ci.entrar(p1);
  r := pet_minha_agenda(hoje, hoje + 30);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 2 AND r -> 0 ->> 'tutor' = 'Maria' AND r -> 0 -> 'pet' ->> 'alergias' = 'frango'
                   AND (r -> 0 -> 'servicos' -> 0 ->> 'nome') = 'Banho Agenda Prof', 'o profissional vê os 2 atendimentos dele, com pet, alergia e serviço');
  PERFORM ci.exige(r::text NOT LIKE '%preco%' AND r::text NOT LIKE '%cpf%' AND r::text NOT LIKE '%telefone%' AND r::text NOT LIKE '%Tutora%', 'a agenda não traz preço, documento, telefone nem o sobrenome do tutor');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_minha_agenda(%L, %L)$c$, hoje, hoje + 60), 'período maior que 31 dias');
  PERFORM ci.deve_falhar(psem, format($c$SELECT pet_minha_agenda(%L, %L)$c$, hoje, hoje + 1), 'conta sem cadastro ligado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_minha_agenda(%L, %L)$c$, hoje, hoje + 1), 'quem não é profissional chama a agenda');

  -- avançar: começar e dar como pronto; nada além, nada dos outros
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_minha_situacao(%L, 'em_atendimento')$c$, ag3), 'atendimento de outro profissional');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_minha_situacao(%L, 'pronto')$c$, ag1), 'pronto sem ter começado');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_minha_situacao(%L, 'cancelado')$c$, ag1), 'profissional cancela');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_minha_situacao(%L, 'retirado')$c$, ag1), 'profissional dá como retirado');
  PERFORM ci.entrar(p1);
  PERFORM pet_minha_situacao(ag1, 'em_atendimento');
  PERFORM pet_minha_situacao(ag1, 'pronto');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'pronto' FROM pet_agendamentos WHERE id = ag1) AND (SELECT situacao = 'agendado' FROM pet_agendamentos WHERE id = ag3), 'o profissional avançou só o atendimento dele');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_minha_situacao(%L, 'em_atendimento')$c$, ag1), 'voltar atendimento pronto');

  -- cadastro inativo perde o acesso
  PERFORM ci.entrar(gest);
  PERFORM pet_profissional_salvar(jsonb_build_object('id', prof2, 'nome', 'Beto Tosador CI', 'ativo', false));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(p2, format($c$SELECT pet_minha_agenda(%L, %L)$c$, hoje, hoje + 1), 'cadastro do profissional inativo');

  -- isolamento: o perfil não enxerga nada da loja nem do salão; quem acumula outro papel enxerga
  PERFORM ci.exige(ci.contar(p1, 'SELECT count(*) FROM produtos') = 0 AND ci.contar(p1, 'SELECT count(*) FROM clientes') = 0
                   AND ci.contar(p1, 'SELECT count(*) FROM pedidos') = 0 AND ci.contar(p1, 'SELECT count(*) FROM pets') = 0
                   AND ci.contar(p1, 'SELECT count(*) FROM pet_agendamentos') = 0 AND ci.contar(p1, 'SELECT count(*) FROM pet_profissionais') = 0
                   AND ci.contar(p1, 'SELECT count(*) FROM pet_comissoes') = 0, 'o profissional não lê as tabelas da loja nem as do pet shop');
  PERFORM ci.exige(ci.contar(p1, 'SELECT count(*) FROM cardapio_itens') = 0 AND ci.contar(p1, 'SELECT count(*) FROM mesas') = 0 AND ci.contar(p1, 'SELECT count(*) FROM comandas') = 0,
                   'o profissional também não lê cardápio, mesas e comandas');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM mesas') >= 0 AND ci.contar(gar, 'SELECT count(*) FROM cardapio_itens') > 0, 'o garçom segue lendo o cardápio');
  PERFORM ci.exige(ci.contar(p1, 'SELECT count(*) FROM profiles WHERE id = auth.uid()') = 1, 'o profissional lê o próprio perfil (sessão)');
  PERFORM ci.exige(ci.contar(pmix, 'SELECT count(*) FROM clientes') > 0, 'profissional que também é vendedor enxerga a loja');
  PERFORM ci.deve_falhar(p1, 'SELECT frente_caixa_atual()', 'profissional usa o caixa');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_agenda_situacao(%L, 'confirmado')$c$, ag2), 'profissional usa a função da recepção');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_reagendar(%L, %L::timestamptz)$c$, ag2, t0 + interval '5 hours'), 'profissional remarca');
  PERFORM ci.deve_falhar(p1, format($c$SELECT pet_agenda_retirar(%L)$c$, ag1), 'profissional cobra');
  PERFORM ci.deve_falhar(p1, format($c$UPDATE pet_agendamentos SET situacao = 'retirado' WHERE id = %L$c$, ag1), 'profissional altera a agenda direto');
  PERFORM ci.deve_falhar(p1, format($c$UPDATE pet_profissionais SET profile_id = %L WHERE id = %L$c$, p1, prof2), 'profissional liga a própria conta direto');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM pet_profissionais WHERE profile_id = p1 AND id = prof2), 'o vínculo direto não pegou');
  SELECT count(*) INTO n FROM pet_profissionais WHERE tenant_id = tb;
  PERFORM ci.exige(n = 0, 'a outra empresa não recebeu profissionais');
END $$;

-- 43. Clínica (base): perfil Veterinário, CRMV no cadastro, conta combinando com a função, isolamento e categorias de serviço
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  v1   constant uuid := 'a0000000-0000-0000-0000-0000000000e1';
  vmix constant uuid := 'a0000000-0000-0000-0000-0000000000e2';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  t0 timestamptz := date_trunc('day', now()) + interval '11 days' + interval '9 hours';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  tutor uuid; pet uuid; cons uuid; vet uuid; ban uuid; ag uuid; r jsonb; ramo_ant text; cnae_ant text; cnae2_ant text;
BEGIN
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Clinica CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (v1, 'vet1@ci'), (vmix, 'vetmix@ci'), (pban, 'banhista@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (v1, vmix, pban);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (v1, demo, 'veterinario'), (vmix, demo, 'veterinario'), (vmix, demo, 'vendedor'), (pban, demo, 'profissional');

  -- liberação da clínica no banco: sem CNAE 7500 nem ramo clínica, não cadastra veterinário
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.exige(NOT ci.contar(gest, 'SELECT clinica_liberada()::int') = 1, 'pet shop sem CNAE 7500 não tem a clínica liberada');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_servico_salvar('{"nome":"Consulta Sem Clinica CI","categoria":"consulta"}'::jsonb)$c$, 'serviço de consulta em empresa sem clínica');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_servico_salvar('{"nome":"Vacina Sem Clinica CI","categoria":"vacina"}'::jsonb)$c$, 'serviço de vacina em empresa sem clínica');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Vet Sem Clinica","funcao":"veterinario","crmv":"12345","crmv_uf":"SP"}'::jsonb)$c$, 'veterinário em empresa sem clínica');
  UPDATE empresas SET cnae_secundarios = '9609-2/08; 7500-1/00' WHERE tenant_id = demo;
  PERFORM ci.exige(ci.contar(gest, 'SELECT clinica_liberada()::int') = 1, 'CNAE 7500 entre os secundários libera a clínica');
  UPDATE empresas SET cnae_secundarios = NULL, ramo_atividade = 'clinica' WHERE tenant_id = demo;
  PERFORM ci.exige(ci.contar(gest, 'SELECT clinica_liberada()::int') = 1, 'ramo Clínica veterinária libera a clínica');

  -- categorias de serviço da clínica
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_servico_salvar('{"nome":"Serviço X CI","categoria":"cirurgia"}'::jsonb)$c$, 'categoria que não existe');
  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Clinica CI","categoria":"consulta","duracao_min":30}'::jsonb);
  PERFORM pet_servico_salvar('{"nome":"Vacina Clinica CI","categoria":"vacina","duracao_min":15}'::jsonb);
  PERFORM pet_servico_salvar('{"nome":"Exame Clinica CI","categoria":"exame","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 150);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM pet_servicos WHERE categoria IN ('consulta', 'vacina', 'exame') AND tenant_id = demo) = 3, 'consulta, vacina e exame são categorias de serviço');

  -- CRMV: obrigatório para veterinário, normalizado, e só para ele
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Vet Sem Crmv","funcao":"veterinario"}'::jsonb)$c$, 'veterinário sem CRMV');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Vet Sem UF","funcao":"veterinario","crmv":"12345"}'::jsonb)$c$, 'veterinário sem UF do CRMV');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Vet UF Errada","funcao":"veterinario","crmv":"12345","crmv_uf":"XX"}'::jsonb)$c$, 'UF do CRMV inválida');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Vet Curto","funcao":"veterinario","crmv":"1","crmv_uf":"SP"}'::jsonb)$c$, 'CRMV curto demais');
  PERFORM ci.deve_falhar_dono($c$INSERT INTO pet_profissionais (tenant_id, nome, crmv) VALUES ('11111111-1111-1111-1111-111111111111', 'Sem UF', '12345')$c$, 'CRMV sem UF direto no banco');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_profissional_salvar('{"nome":"Vet Vendedor","funcao":"veterinario","crmv":"12345","crmv_uf":"SP"}'::jsonb)$c$, 'vendedor cadastra veterinário');
  PERFORM ci.entrar(gest);
  vet := pet_profissional_salvar('{"nome":"Dra Vet CI","funcao":"veterinario","crmv":"sp-12.345","crmv_uf":"sp"}'::jsonb);
  ban := pet_profissional_salvar('{"nome":"Banhista CRMV CI","funcao":"banhista","crmv":"99999","crmv_uf":"RJ"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT crmv = 'SP12345' AND crmv_uf = 'SP' FROM pet_profissionais WHERE id = vet), 'o CRMV é normalizado (maiúsculas, sem pontuação)');
  PERFORM ci.exige((SELECT crmv IS NULL AND crmv_uf IS NULL FROM pet_profissionais WHERE id = ban), 'quem não é veterinário não guarda CRMV');

  -- a conta combina com a função
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, vet, pban), 'veterinário ligado à conta de profissional');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, ban, v1), 'banhista ligado à conta de veterinário');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, vet, v1), 'vendedor liga a conta do veterinário');
  PERFORM ci.entrar(gest);
  PERFORM pet_profissional_vincular(vet, v1);
  PERFORM pet_profissional_vincular(ban, pban);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_salvar(jsonb_build_object('id', %L, 'nome', 'Banhista CRMV CI', 'funcao', 'veterinario', 'crmv', '5555', 'crmv_uf', 'SP'))$c$, ban), 'virar veterinário com a conta de profissional ligada');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_profissional_salvar(jsonb_build_object('id', %L, 'nome', 'Dra Vet CI', 'funcao', 'tosador'))$c$, vet), 'deixar de ser veterinário com a conta de veterinário ligada');

  -- agenda do veterinário: a consulta agendada pela recepção aparece só para ele, e ele avança
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Paciente CI'));
  ag := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', vet, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  PERFORM ci.sair();
  PERFORM ci.entrar(v1);
  r := pet_minha_agenda(hoje, hoje + 30);
  PERFORM pet_minha_situacao(ag, 'em_atendimento');
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 -> 'servicos' -> 0 ->> 'nome' = 'Consulta Clinica CI', 'o veterinário vê a consulta dele na agenda');
  PERFORM ci.exige((SELECT situacao = 'em_atendimento' FROM pet_agendamentos WHERE id = ag), 'o veterinário começa a consulta');
  PERFORM ci.deve_falhar(pban, format($c$SELECT pet_minha_situacao(%L, 'pronto')$c$, ag), 'banhista mexe na consulta do veterinário');

  -- isolamento: o veterinário não lê a loja nem o restaurante; quem acumula outro papel lê
  PERFORM ci.exige(ci.contar(v1, 'SELECT count(*) FROM produtos') = 0 AND ci.contar(v1, 'SELECT count(*) FROM clientes') = 0
                   AND ci.contar(v1, 'SELECT count(*) FROM pedidos') = 0 AND ci.contar(v1, 'SELECT count(*) FROM pet_agendamentos') = 0
                   AND ci.contar(v1, 'SELECT count(*) FROM mesas') = 0 AND ci.contar(v1, 'SELECT count(*) FROM cardapio_itens') = 0, 'o veterinário não lê a loja, o pet shop nem o restaurante');
  PERFORM ci.exige(ci.contar(vmix, 'SELECT count(*) FROM clientes') > 0, 'veterinário que também é vendedor enxerga a loja');
  PERFORM ci.deve_falhar(v1, 'SELECT frente_caixa_atual()', 'veterinário usa o caixa');
  PERFORM ci.deve_falhar(v1, format($c$SELECT pet_agenda_situacao(%L, 'pronto')$c$, ag), 'veterinário usa a função da recepção');
  PERFORM ci.deve_falhar(v1, format($c$SELECT pet_profissional_vincular(%L, %L)$c$, ban, pban), 'veterinário liga contas');
  PERFORM ci.deve_falhar(v1, format($c$UPDATE pet_profissionais SET crmv = '1', crmv_uf = 'SP' WHERE id = %L$c$, vet), 'veterinário altera o CRMV direto');
  -- a clínica deixa de estar liberada: o veterinário já ligado perde a agenda; o banhista segue
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(v1, format($c$SELECT pet_minha_agenda(%L, %L)$c$, hoje, hoje + 30), 'veterinário sem a clínica liberada vê a agenda');
  PERFORM ci.deve_falhar(v1, format($c$SELECT pet_minha_situacao(%L, 'pronto')$c$, ag), 'veterinário sem a clínica liberada avança atendimento');
  PERFORM ci.entrar(pban);
  r := pet_minha_agenda(hoje, hoje + 30);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_typeof(r) = 'array', 'o profissional de banho segue com a agenda sem a clínica');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 44. Clínica (consulta e prontuário): só o veterinário lê e escreve; fechado é imutável; adendo; auditoria; liberação da clínica
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  va   constant uuid := 'a0000000-0000-0000-0000-0000000000f1';
  vb   constant uuid := 'a0000000-0000-0000-0000-0000000000f2';
  t0 timestamptz := date_trunc('day', now()) + interval '12 days' + interval '9 hours';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  tutor uuid; tutor_b uuid; pet uuid; pet_b uuid; cons uuid; banho uuid; pva uuid; pvb uuid; ag1 uuid; ag2 uuid; ag3 uuid; tb uuid;
  ramo_ant text; cnae_ant text; cnae2_ant text; r jsonb; at1 uuid; at2 uuid; n bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Joana Tutora Prontuario CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO tenants (nome) VALUES ('Clinica B CI') RETURNING id INTO tb;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (tb, 'Tutor Outra Empresa', '11144477735') RETURNING id INTO tutor_b;
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (tb, tutor_b, 'Pet Outra Empresa') RETURNING id INTO pet_b;
  INSERT INTO auth.users (id, email) VALUES (va, 'veta@ci'), (vb, 'vetb@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (va, vb);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (va, demo, 'veterinario'), (vb, demo, 'veterinario');

  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Prontuario CI","categoria":"consulta","duracao_min":30}'::jsonb);
  banho := pet_servico_salvar('{"nome":"Banho Prontuario CI","categoria":"banho","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 150);
  PERFORM pet_preco_salvar(banho, NULL, NULL, NULL, 60);
  pva := pet_profissional_salvar('{"nome":"Vet A Prontuario","funcao":"veterinario","crmv":"1111","crmv_uf":"SP"}'::jsonb);
  pvb := pet_profissional_salvar('{"nome":"Vet B Prontuario","funcao":"veterinario","crmv":"2222","crmv_uf":"RJ"}'::jsonb);
  PERFORM pet_profissional_vincular(pva, va);
  PERFORM pet_profissional_vincular(pvb, vb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Rex Prontuario CI', 'alergias', 'dipirona'));
  ag1 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', pva, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag2 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', pvb, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag3 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', pva, 'inicio', t0 + interval '3 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  PERFORM ci.sair();

  -- ninguém além do veterinário lê ou escreve o prontuário
  PERFORM ci.deve_falhar(adm, format($c$SELECT clinica_historico(%L)$c$, pet), 'administrador lê o prontuário');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_historico(%L)$c$, pet), 'gestor lê o prontuário');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_historico(%L)$c$, pet), 'vendedor lê o prontuário');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_historico(%L)$c$, pet), 'garçom lê o prontuário');
  PERFORM ci.deve_falhar(pban, format($c$SELECT clinica_historico(%L)$c$, pet), 'profissional de banho lê o prontuário');
  PERFORM ci.deve_falhar(gest, $c$SELECT clinica_pacientes('rex')$c$, 'gestor busca paciente na clínica');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_atendimento_abrir(%L)$c$, ag1), 'gestor abre atendimento');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_pet_alergias(%L, 'x')$c$, pet), 'gestor altera alergia pela clínica');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM pet_atendimentos_clinicos', 'leitura direta do atendimento');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM pet_atendimento_adendos', 'leitura direta do adendo');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM pet_atendimentos_clinicos', 'leitura direta do atendimento pelo próprio veterinário');
  PERFORM ci.deve_falhar(va, format($c$INSERT INTO pet_atendimentos_clinicos (tenant_id, pet_id, cliente_id, agendamento_id, veterinario_id, crmv, crmv_uf) VALUES (%L, %L, %L, %L, %L, '1111', 'SP')$c$, demo, pet, tutor, ag1, pva), 'escrita direta do atendimento');

  -- abrir: só a consulta do próprio veterinário
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_abrir(%L)$c$, ag2), 'consulta de outro veterinário');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_abrir(%L)$c$, ag3), 'agendamento sem serviço de consulta');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_abrir(%L)$c$, gen_random_uuid()), 'agendamento que não existe');
  PERFORM ci.entrar(va);
  r := clinica_atendimento_abrir(ag1);
  at1 := (r ->> 'id')::uuid;
  PERFORM ci.exige(clinica_atendimento_abrir(ag1) ->> 'id' = at1::text, 'abrir de novo devolve o mesmo atendimento');
  PERFORM ci.sair();
  PERFORM ci.exige(r -> 'veterinario' ->> 'crmv' = '1111' AND r ->> 'tutor' = 'Joana Tutora Prontuario CI' AND r -> 'pet' ->> 'alergias' = 'dipirona', 'o atendimento traz o CRMV da abertura, o tutor e a alergia do pet');
  PERFORM ci.exige((SELECT situacao = 'em_atendimento' FROM pet_agendamentos WHERE id = ag1), 'abrir o prontuário começa a consulta');

  -- preencher
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_atendimento_salvar(%L, '{"queixa":"x"}'::jsonb)$c$, at1), 'outro veterinário preenche');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_salvar(%L, '{"queixa":"x","peso_kg":"500"}'::jsonb)$c$, at1), 'peso absurdo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_salvar(%L, '{"queixa":"x","temperatura_c":"20"}'::jsonb)$c$, at1), 'temperatura absurda');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_salvar(%L, '{"queixa":"x","peso_kg":"abc"}'::jsonb)$c$, at1), 'peso que não é número');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_salvar(%L, jsonb_build_object('queixa','x','retorno_em', %L))$c$, at1, hoje - 1), 'retorno no passado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_fechar(%L)$c$, at1), 'fechar sem queixa nem conduta');
  PERFORM ci.entrar(va);
  PERFORM clinica_atendimento_salvar(at1, '{"queixa":"Vômito há 2 dias"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_fechar(%L)$c$, at1), 'fechar sem conduta');
  PERFORM ci.entrar(va);
  r := clinica_atendimento_salvar(at1, jsonb_build_object('queixa', 'Vômito há 2 dias', 'anamnese', 'Comeu algo na rua', 'peso_kg', '12,5', 'temperatura_c', '38.7',
                                  'freq_cardiaca', '110', 'freq_respiratoria', '24', 'exame_fisico', 'Mucosas normocoradas', 'diagnostico', 'Gastrite',
                                  'conduta', 'Dieta leve e protetor gástrico', 'retorno_em', hoje + 7));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'peso_kg')::numeric = 12.5 AND (r ->> 'temperatura_c')::numeric = 38.7 AND r ->> 'diagnostico' = 'Gastrite', 'o atendimento guarda os sinais vitais e o texto');

  -- fechar: imutável, consulta vai para pronto
  PERFORM ci.entrar(va);
  r := clinica_atendimento_fechar(at1);
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'situacao' = 'fechado' AND r ->> 'fechado_em' IS NOT NULL, 'atendimento fechado');
  PERFORM ci.exige((SELECT situacao = 'pronto' FROM pet_agendamentos WHERE id = ag1), 'fechar o prontuário dá a consulta como pronta (a recepção cobra)');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_salvar(%L, '{"queixa":"mudou"}'::jsonb)$c$, at1), 'alterar atendimento fechado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_fechar(%L)$c$, at1), 'fechar duas vezes');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_atendimentos_clinicos SET diagnostico = 'outro' WHERE id = %L$c$, at1), 'UPDATE direto em atendimento fechado (nem o dono do banco)');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_atendimentos_clinicos WHERE id = %L$c$, at1), 'apagar atendimento');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM pet_agendamentos WHERE situacao = ''pronto''') >= 1, 'a recepção vê a consulta pronta na agenda, sem texto clínico');

  -- adendo
  PERFORM ci.entrar(vb);
  r := clinica_atendimento_abrir(ag2);
  at2 := (r ->> 'id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_adendo_criar(%L, 'não pode')$c$, at2), 'adendo em atendimento aberto');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_adendo_criar(%L, '   ')$c$, at1), 'adendo vazio');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_adendo_criar(%L, 'gestor')$c$, at1), 'gestor cria adendo');
  PERFORM ci.entrar(vb);
  r := clinica_adendo_criar(at1, 'Tutor relatou melhora após 3 dias.');
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'adendos') = 1 AND r -> 'adendos' -> 0 ->> 'crmv' = '2222' AND r ->> 'diagnostico' = 'Gastrite', 'o adendo identifica quem escreveu e não muda o original');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_atendimento_adendos SET texto = 'x' WHERE atendimento_id = %L$c$, at1), 'alterar adendo');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_atendimento_adendos WHERE atendimento_id = %L$c$, at1), 'apagar adendo');

  -- histórico, busca, alergia e auditoria
  PERFORM ci.entrar(vb);
  r := clinica_historico(pet);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'atendimentos') = 2 AND r ->> 'tutor' = 'Joana Tutora Prontuario CI', 'o veterinário vê o histórico completo do paciente (dois atendimentos)');
  PERFORM ci.entrar(vb);
  r := clinica_pacientes('rex joana');
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 0, 'a busca olha o nome do pet ou do tutor, não os dois juntos');
  PERFORM ci.entrar(vb);
  r := clinica_pacientes('Joana');
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 ->> 'nome' = 'Rex Prontuario CI', 'a busca acha o paciente pelo nome do tutor');
  PERFORM ci.deve_falhar(vb, $c$SELECT clinica_pacientes('r')$c$, 'busca de uma letra');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_historico(%L)$c$, pet_b), 'paciente de outra empresa');
  PERFORM ci.entrar(vb);
  PERFORM clinica_pet_alergias(pet, 'dipirona e frango');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT alergias = 'dipirona e frango' FROM pets WHERE id = pet), 'o veterinário atualiza a alergia do pet');
  SELECT count(*) INTO n FROM clinica_acessos WHERE tenant_id = demo;
  PERFORM ci.exige(n >= 5 AND ci.contar(gest, 'SELECT count(*) FROM clinica_acessos') = n AND ci.contar(vend, 'SELECT count(*) FROM clinica_acessos') = 0 AND ci.contar(va, 'SELECT count(*) FROM clinica_acessos') = 0,
                   'os acessos ficam registrados e só a gestão os vê (sem texto clínico)');

  -- a agenda do veterinário informa a categoria do serviço
  PERFORM ci.entrar(va);
  r := pet_minha_agenda(hoje, hoje + 30);
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e, jsonb_array_elements(e -> 'servicos') s WHERE s ->> 'categoria' = 'consulta'), 'a agenda traz a categoria dos serviços');

  -- clínica deixa de estar liberada: nada do prontuário funciona
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_historico(%L)$c$, pet), 'prontuário sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_abrir(%L)$c$, ag1), 'abrir atendimento sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 45. Clínica (vacinas e vermífugos): catálogo, aplicação com lote, série e reforço, cancelamento, aplicada fora, cartão
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  vg   constant uuid := 'a0000000-0000-0000-0000-0000000000f3';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  t0 timestamptz := date_trunc('day', now()) + interval '13 days' + interval '9 hours';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; cao uuid; gato uuid; cao2 uuid; vacserv uuid; banho uuid; pvet uuid; ag uuid; ag_banho uuid;
  prod uuid; prod_b uuid; prod_serv uuid; prod_sem_lote uuid; dep uuid; dep_x uuid; fx uuid; fy uuid; l_ok uuid; l_venc uuid; l_zero uuid; l_outro uuid; l_semval uuid; l_fil uuid; cat uuid; cat_gato uuid; cat_verm uuid;
  r jsonb; a1 uuid; a2 uuid; a3 uuid; a4 uuid; ext uuid; n numeric; est0 numeric;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Vacina CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (vg, 'vetvac@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = vg;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (vg, demo, 'veterinario');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Vacinas CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_lote) VALUES (demo, 'VAC-V10-CI', 'Vacina V10 CI', 'UN', 0, true) RETURNING id INTO prod;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_lote) VALUES (demo, 'VAC-OUTRO-CI', 'Outro produto CI', 'UN', 0, true) RETURNING id INTO prod_b;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_estoque) VALUES (demo, 'VAC-SERV-CI', 'Serviço CI', 'UN', 10, false) RETURNING id INTO prod_serv;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda) VALUES (demo, 'VAC-SEMLOTE-CI', 'Produto sem controle de lote CI', 'UN', 0) RETURNING id INTO prod_sem_lote;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, '22222222-2222-2222-2222-222222222222', 'Filial Vacina X') RETURNING id INTO fx;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, '22222222-2222-2222-2222-222222222222', 'Filial Vacina Y') RETURNING id INTO fy;
  INSERT INTO depositos (tenant_id, filial_id, nome) VALUES (demo, fx, 'Vacinas filial X CI') RETURNING id INTO dep_x;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 10, 'ci', 'ci');
  l_ok := estoque_lote_lancar(prod, dep, 'L-OK', '', '', 'entrada', 5, 'ci');
  l_venc := estoque_lote_lancar(prod, dep, 'L-VENC', '', '', 'entrada', 3, 'ci');
  l_zero := estoque_lote_lancar(prod, dep, 'L-ZERO', '', '', 'entrada', 1, 'ci');
  l_outro := estoque_lote_lancar(prod_b, dep, 'L-OUTRO', '', '', 'entrada', 2, 'ci');
  PERFORM estoque_lote_lancar(prod, dep, 'L-ZERO', '', '', 'saida', 1, 'ci');
  l_semval := estoque_lote_lancar(prod, dep, 'L-SEMVAL', '', '', 'entrada', 4, 'ci');
  PERFORM registrar_movimentacao(prod, dep_x, 'entrada'::mov_tipo, 2, 'ci', 'ci');
  l_fil := estoque_lote_lancar(prod, dep_x, 'L-FILIAL', '', '', 'entrada', 2, 'ci');
  PERFORM ci.sair();
  UPDATE estoque_lotes SET validade = hoje + 90 WHERE id = l_ok;
  UPDATE estoque_lotes SET validade = hoje - 1 WHERE id = l_venc;
  UPDATE estoque_lotes SET validade = hoje + 90 WHERE id = l_fil;

  PERFORM ci.entrar(gest);
  vacserv := pet_servico_salvar('{"nome":"Vacinação Clinica CI","categoria":"vacina","duracao_min":15}'::jsonb);
  banho := pet_servico_salvar('{"nome":"Banho Vacina CI","categoria":"banho","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(vacserv, NULL, NULL, NULL, 120);
  PERFORM pet_preco_salvar(banho, NULL, NULL, NULL, 60);
  pvet := pet_profissional_salvar('{"nome":"Vet Vacina CI","funcao":"veterinario","crmv":"3333","crmv_uf":"MG"}'::jsonb);
  PERFORM pet_profissional_vincular(pvet, vg);
  PERFORM ci.sair();

  -- catálogo: gestão e veterinário editam; validações
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome','V10 CI','produto_id',%L,'reforco_dias',365))$c$, prod), 'vendedor edita o catálogo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome','V10 CI','doses_serie',3,'reforco_dias',365,'produto_id',%L))$c$, prod), 'série sem intervalo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome','V10 CI','reforco_dias',0,'produto_id',%L))$c$, prod), 'reforço zero');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome','','reforco_dias',365,'produto_id',%L))$c$, prod), 'item sem nome');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome','V10 CI','reforco_dias',365,'produto_id',%L))$c$, prod_serv), 'produto que é serviço');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome','V10 CI','reforco_dias',365,'produto_id',%L))$c$, prod_sem_lote), 'produto que não controla lote');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome','V10 CI','reforco_dias',365,'produto_id',%L,'tipo','soro'))$c$, prod), 'tipo inválido');
  PERFORM ci.entrar(gest);
  cat := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'V10 CI', 'tipo', 'vacina', 'especie', 'cao', 'doses_serie', 3, 'intervalo_serie_dias', 21,
                                        'reforco_dias', 365, 'idade_minima_dias', 42, 'produto_id', prod));
  cat_gato := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'Quadrupla CI', 'especie', 'gato', 'reforco_dias', 365, 'produto_id', prod));
  PERFORM ci.sair();
  PERFORM ci.entrar(vg);
  cat_verm := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'Vermífugo CI', 'tipo', 'vermifugo', 'reforco_dias', 90, 'produto_id', prod));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_catalogo_salvar(jsonb_build_object('nome',' v10 ci ','especie','cao','reforco_dias',365,'produto_id',%L))$c$, prod), 'nome repetido para a mesma espécie');
  PERFORM ci.entrar(vend);
  r := clinica_vacinas_catalogo();
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) >= 3, 'a recepção lê o catálogo');
  PERFORM ci.deve_falhar(gar, 'SELECT clinica_vacinas_catalogo()', 'garçom lê o catálogo');
  PERFORM ci.deve_falhar(pban, 'SELECT clinica_vacinas_catalogo()', 'profissional de banho lê o catálogo');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM pet_vacinas_catalogo', 'leitura direta do catálogo');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM pet_vacinacoes', 'leitura direta das aplicações');

  -- pacientes e consulta de vacina agendada
  PERFORM ci.entrar(vend);
  cao := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Filhote Vacina CI', 'especie', 'cao', 'nascimento', hoje - 30));
  cao2 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Adulto Vacina CI', 'especie', 'cao'));
  gato := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Gato Vacina CI', 'especie', 'gato'));
  ag := pet_agendar(jsonb_build_object('pet_id', cao, 'profissional_id', pvet, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', vacserv))));
  ag_banho := pet_agendar(jsonb_build_object('pet_id', cao, 'profissional_id', pvet, 'inicio', t0 + interval '2 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  PERFORM ci.sair();

  -- aplicar: só o veterinário, com lote válido, dentro do atendimento de vacina
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat, l_ok), 'gestor aplica vacina');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag_banho, cat, l_ok), 'agendamento sem serviço de vacina');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat, l_venc), 'lote vencido');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat, l_zero), 'lote sem saldo');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat, l_semval), 'lote sem validade registrada');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat, l_outro), 'lote de outro produto');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat_gato, l_ok), 'vacina de gato em cão');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L,'aplicada_em',%L))$c$, ag, cat, l_ok, hoje + 1), 'aplicação no futuro');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L,'aplicada_em',%L))$c$, ag, cat, l_ok, hoje - 30), 'aplicação antiga fora do registro externo');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L,'aplicador_id',%L))$c$, ag, cat, l_ok, gen_random_uuid()), 'aplicador que não existe');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L,'proxima_dose_em',%L))$c$, ag, cat, l_ok, hoje - 1), 'próxima dose antes da aplicação');
  PERFORM ci.exige((SELECT quantidade FROM estoque_lotes WHERE id = l_ok) = 5, 'aplicação recusada não baixa o lote');
  -- veterinário preso a uma filial: não vê nem usa lote de depósito de outra filial
  UPDATE profiles SET filial_id = fy WHERE id = vg;
  PERFORM ci.entrar(vg);
  r := clinica_lotes_vacina(cat);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'lote' IN ('L-FILIAL', 'L-SEMVAL', 'L-VENC', 'L-ZERO')) AND jsonb_array_length(r) = 1,
                   'a lista de lotes some com lote sem validade, vencido, zerado e de outra filial');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat, l_fil), 'lote de depósito de outra filial');
  UPDATE profiles SET filial_id = NULL WHERE id = vg;
  UPDATE estoque_lotes SET quantidade = 0 WHERE id = l_fil;
  SELECT quantidade INTO est0 FROM estoques WHERE produto_id = prod AND deposito_id = dep;

  PERFORM ci.entrar(vg);
  r := clinica_vacina_aplicar(ag, jsonb_build_object('catalogo_id', cat, 'estoque_lote_id', l_ok, 'local_aplicacao', 'Subcutânea, dorso'));
  PERFORM ci.sair();
  a1 := (r ->> 'id')::uuid;
  PERFORM ci.exige(r ->> 'dose_tipo' = 'serie' AND (r ->> 'dose_numero')::int = 1 AND (r ->> 'proxima_dose_em')::date = hoje + 21, '1ª dose da série: próxima em 21 dias');
  PERFORM ci.exige(jsonb_array_length(r -> 'avisos') = 1 AND r -> 'avisos' ->> 0 LIKE '%idade mínima%', 'aviso (que não bloqueia) de idade mínima');
  PERFORM ci.exige((SELECT quantidade FROM estoque_lotes WHERE id = l_ok) = 4 AND (SELECT quantidade FROM estoques WHERE produto_id = prod AND deposito_id = dep) = est0 - 1,
                   'a aplicação baixa 1 dose do lote e do estoque');
  PERFORM ci.exige((SELECT situacao = 'em_atendimento' FROM pet_agendamentos WHERE id = ag), 'registrar a vacina começa o atendimento');
  PERFORM ci.exige((SELECT lote = 'L-OK' AND aplicador_id = veterinario_id AND origem = 'clinica' FROM pet_vacinacoes WHERE id = a1), 'a aplicação guarda o lote e, sem auxiliar, o veterinário como aplicador');

  PERFORM ci.entrar(vg);
  r := clinica_vacina_aplicar(ag, jsonb_build_object('catalogo_id', cat, 'estoque_lote_id', l_ok, 'aplicada_em', hoje));
  a2 := (r ->> 'id')::uuid;
  PERFORM ci.exige(r ->> 'dose_tipo' = 'serie' AND (r ->> 'dose_numero')::int = 2 AND (r ->> 'proxima_dose_em')::date = hoje + 21 AND (r -> 'avisos') @> '["Já existe uma aplicação deste item para o pet nesta data."]'::jsonb, '2ª dose; aviso de aplicação repetida no dia');
  r := clinica_vacina_aplicar(ag, jsonb_build_object('catalogo_id', cat, 'estoque_lote_id', l_ok));
  a3 := (r ->> 'id')::uuid;
  PERFORM ci.exige(r ->> 'dose_tipo' = 'serie' AND (r ->> 'dose_numero')::int = 3 AND (r ->> 'proxima_dose_em')::date = hoje + 365, 'última dose da série: a próxima já é o reforço (365 dias)');
  r := clinica_vacina_aplicar(ag, jsonb_build_object('catalogo_id', cat, 'estoque_lote_id', l_ok, 'proxima_dose_em', ''));
  a4 := (r ->> 'id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'dose_tipo' = 'reforco' AND (r ->> 'dose_numero')::int = 1 AND r ->> 'proxima_dose_em' IS NULL, 'depois da série vem o reforço; próxima dose pode ficar em branco');
  PERFORM ci.exige((SELECT quantidade FROM estoque_lotes WHERE id = l_ok) = 1, 'quatro aplicações baixaram quatro doses do lote');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_vacinacoes SET lote = 'X' WHERE id = %L$c$, a1), 'alterar aplicação');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_vacinacoes SET situacao = 'cancelada', cancelada_em = now() WHERE id = %L$c$, a1), 'cancelar sem motivo no banco');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_vacinacoes WHERE id = %L$c$, a1), 'apagar aplicação');

  -- cancelar: motivo, só o veterinário, devolve a dose
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_cancelar(%L, 'erro')$c$, a4), 'gestor cancela aplicação');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_cancelar(%L, '  ')$c$, a4), 'cancelar sem motivo');
  PERFORM ci.entrar(vg);
  PERFORM clinica_vacina_cancelar(a4, 'Registrado no pet errado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade FROM estoque_lotes WHERE id = l_ok) = 2 AND (SELECT quantidade FROM estoques WHERE produto_id = prod AND deposito_id = dep) = est0 - 3,
                   'cancelar devolve a dose ao lote e ao estoque');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_cancelar(%L, 'de novo')$c$, a4), 'cancelar duas vezes');

  -- aplicada em outro local: sem baixa
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_registrar_externa(%L, jsonb_build_object('catalogo_id',%L,'aplicada_em',%L,'informado_por','Tutor'))$c$, cao2, cat, hoje - 60), 'gestor registra vacina externa');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_registrar_externa(%L, jsonb_build_object('catalogo_id',%L,'aplicada_em',%L))$c$, cao2, cat, hoje - 60), 'externa sem dizer quem informou');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_registrar_externa(%L, jsonb_build_object('catalogo_id',%L,'aplicada_em',%L,'informado_por','Tutor'))$c$, cao2, cat, hoje + 5), 'externa no futuro');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_registrar_externa(%L, jsonb_build_object('catalogo_id',%L,'aplicada_em','2020-02-30','informado_por','Tutor'))$c$, cao2, cat), 'externa com data inválida');
  PERFORM ci.entrar(vg);
  r := clinica_vacina_registrar_externa(cao2, jsonb_build_object('catalogo_id', cat, 'aplicada_em', hoje - 60, 'informado_por', 'Carteira de vacinação (Clínica Boa Vida)', 'lote', 'X123'));
  ext := (r ->> 'id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'dose_tipo' = 'serie' AND (r ->> 'dose_numero')::int = 1 AND (r ->> 'proxima_dose_em')::date = hoje - 60 + 21, 'externa também conta como dose da série');
  PERFORM ci.exige((SELECT quantidade FROM estoque_lotes WHERE id = l_ok) = 2 AND (SELECT origem = 'outro_local' AND estoque_lote_id IS NULL FROM pet_vacinacoes WHERE id = ext), 'externa não baixa estoque');

  -- apoio da tela
  PERFORM ci.entrar(vg);
  r := clinica_lotes_vacina(cat);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 ->> 'lote' = 'L-OK', 'a lista de lotes mostra só lote com saldo e na validade');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_lotes_vacina(%L)$c$, cat), 'gestor lista lotes da vacina');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_aplicadores()', 'recepção lista aplicadores');

  -- cartão: gestão, veterinário e recepção; sem texto do prontuário
  PERFORM ci.entrar(vend);
  r := clinica_cartao_vacinacao(cao);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'aplicacoes') = 3 AND jsonb_array_length(r -> 'proximas') = 1 AND r -> 'proximas' -> 0 ->> 'proxima_dose_em' = (hoje + 365)::text,
                   'o cartão traz as 3 aplicações ativas (a cancelada fica de fora) e a próxima dose da mais recente (reforço em 365 dias)');
  PERFORM ci.exige(r::text NOT LIKE '%queixa%' AND r::text NOT LIKE '%diagnostico%' AND r -> 'aplicacoes' -> 0 ->> 'crmv' = '3333', 'o cartão não traz prontuário e identifica o veterinário (CRMV)');
  PERFORM ci.entrar(gest);
  r := clinica_cartao_vacinacao(cao2);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'aplicacoes') = 1 AND r -> 'aplicacoes' -> 0 ->> 'origem' = 'outro_local' AND r -> 'aplicacoes' -> 0 ->> 'informado_por' LIKE 'Carteira%',
                   'a vacina aplicada fora aparece no cartão, marcada como de outro local');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_cartao_vacinacao(%L)$c$, cao), 'garçom lê o cartão');
  PERFORM ci.deve_falhar(pban, format($c$SELECT clinica_cartao_vacinacao(%L)$c$, cao), 'profissional de banho lê o cartão');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_cartao_vacinacao(%L)$c$, gen_random_uuid()), 'cartão de paciente que não existe');

  -- o aviso interno da baixa de dose não abre o estoque para perfil restrito (a função pública continua barrando)
  PERFORM ci.deve_falhar(gar, format($c$SET app.clinica_baixa = 'on'; SELECT registrar_movimentacao(%L, %L, 'saida'::mov_tipo, 1, 'x', 'x')$c$, prod, dep), 'garçom baixa estoque ligando o aviso interno');
  PERFORM ci.deve_falhar(vg, format($c$SET app.clinica_baixa = 'on'; SELECT registrar_movimentacao(%L, %L, 'saida'::mov_tipo, 1, 'x', 'x')$c$, prod, dep), 'veterinário baixa estoque pela função pública');

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_cartao_vacinacao(%L)$c$, cao), 'cartão sem a clínica liberada');
  PERFORM ci.deve_falhar(vg, format($c$SELECT clinica_vacina_aplicar(%L, jsonb_build_object('catalogo_id',%L,'estoque_lote_id',%L))$c$, ag, cat, l_ok), 'aplicar sem a clínica liberada');
  PERFORM ci.deve_falhar(gest, 'SELECT clinica_vacinas_catalogo()', 'catálogo sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 46. Clínica (reforços): lista de vacinas e vermífugos a tomar, com WhatsApp e "já falei", sem prontuário
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  vh   constant uuid := 'a0000000-0000-0000-0000-0000000000f4';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  t0 timestamptz := date_trunc('day', now()) + interval '14 days' + interval '9 hours';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pa uuid; pb uuid; pc uuid; pd uuid; pe uuid; pf uuid; prod uuid; vacserv uuid; pvet uuid;
  c_v10 uuid; c_verm uuid; c_off uuid; r jsonb; ext_e uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone) VALUES (demo, 'Ana Souza Reforco CI', '52998224725', '(16) 99999-1234') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (vh, 'vetref@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = vh;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (vh, demo, 'veterinario');
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_lote) VALUES (demo, 'REF-PROD-CI', 'Produto reforço CI', 'UN', 0, true) RETURNING id INTO prod;

  PERFORM ci.entrar(gest);
  vacserv := pet_servico_salvar('{"nome":"Vacinação Reforço CI","categoria":"vacina","duracao_min":15}'::jsonb);
  PERFORM pet_preco_salvar(vacserv, NULL, NULL, NULL, 100);
  pvet := pet_profissional_salvar('{"nome":"Vet Reforço CI","funcao":"veterinario","crmv":"4444","crmv_uf":"RS"}'::jsonb);
  PERFORM pet_profissional_vincular(pvet, vh);
  c_v10 := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'V10 Reforço CI', 'especie', 'cao', 'doses_serie', 3, 'intervalo_serie_dias', 21, 'reforco_dias', 365, 'produto_id', prod));
  c_verm := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'Vermífugo Reforço CI', 'tipo', 'vermifugo', 'reforco_dias', 90, 'produto_id', prod));
  c_off := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'Item inativo CI', 'reforco_dias', 30, 'produto_id', prod, 'ativo', false));
  PERFORM ci.sair();

  PERFORM ci.entrar(vend);
  pa := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Atrasado Ref CI', 'especie', 'cao'));
  pb := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Quase Ref CI', 'especie', 'cao'));
  pc := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Muito Atrasado Ref CI', 'especie', 'cao'));
  pd := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Sem Proxima Ref CI', 'especie', 'cao'));
  pe := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Cancelada Ref CI', 'especie', 'cao'));
  pf := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Agendado Ref CI', 'especie', 'cao'));
  PERFORM pet_agendar(jsonb_build_object('pet_id', pf, 'profissional_id', pvet, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', vacserv))));
  PERFORM ci.sair();

  -- aplicações (registradas como feitas fora, para não depender de lote): datas escolhidas para cair em hoje - 9 etc.
  PERFORM ci.entrar(vh);
  PERFORM clinica_vacina_registrar_externa(pa, jsonb_build_object('catalogo_id', c_v10, 'aplicada_em', hoje - 30, 'informado_por', 'Carteira'));      -- série 1ª: próxima hoje-9
  PERFORM clinica_vacina_registrar_externa(pa, jsonb_build_object('catalogo_id', c_verm, 'aplicada_em', hoje - 99, 'informado_por', 'Carteira'));    -- reforço 90: próxima hoje-9
  PERFORM clinica_vacina_registrar_externa(pb, jsonb_build_object('catalogo_id', c_v10, 'aplicada_em', hoje - 5, 'informado_por', 'Carteira'));      -- próxima hoje+16
  PERFORM clinica_vacina_registrar_externa(pc, jsonb_build_object('catalogo_id', c_verm, 'aplicada_em', hoje - 300, 'informado_por', 'Carteira'));   -- próxima hoje-210
  PERFORM clinica_vacina_registrar_externa(pd, jsonb_build_object('catalogo_id', c_v10, 'aplicada_em', hoje - 30, 'informado_por', 'Carteira', 'proxima_dose_em', ''));
  ext_e := (clinica_vacina_registrar_externa(pe, jsonb_build_object('catalogo_id', c_v10, 'aplicada_em', hoje - 30, 'informado_por', 'Carteira')) ->> 'id')::uuid;
  PERFORM clinica_vacina_cancelar(ext_e, 'registrado no pet errado');
  PERFORM clinica_vacina_registrar_externa(pf, jsonb_build_object('catalogo_id', c_v10, 'aplicada_em', hoje - 30, 'informado_por', 'Carteira'));
  PERFORM ci.sair();

  -- quem vê a lista
  PERFORM ci.deve_falhar(gar, 'SELECT clinica_reforcos_pendentes()', 'garçom vê os reforços');
  PERFORM ci.deve_falhar(pban, 'SELECT clinica_reforcos_pendentes()', 'profissional de banho vê os reforços');
  PERFORM ci.deve_falhar(vh, 'SELECT clinica_reforcos_pendentes()', 'veterinário (perfil restrito) usa a lista da recepção');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_reforcos_pendentes(61, 10)', 'janela maior que 60 dias');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_reforcos_pendentes(10, 731)', 'atraso maior que 730 dias');

  PERFORM ci.entrar(vend);
  r := clinica_reforcos_pendentes();
  PERFORM ci.sair();
  r := (SELECT coalesce(jsonb_agg(e), '[]'::jsonb) FROM jsonb_array_elements(r) e WHERE (e ->> 'pet_id')::uuid IN (pa, pb, pc, pd, pe, pf));
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 ->> 'pet_id' = pa::text AND (r -> 0 ->> 'referencia')::date = hoje - 9 AND (r -> 0 ->> 'dias')::int = -9,
                   'padrão (15 dias à frente, 180 de atraso): só o pet com os dois itens vencidos, numa linha só');
  PERFORM ci.exige(jsonb_array_length(r -> 0 -> 'itens') = 2 AND r -> 0 ->> 'telefone' = '(16) 99999-1234', 'a linha traz os 2 itens e o telefone do tutor');
  PERFORM ci.exige(r::text NOT LIKE '%queixa%' AND r::text NOT LIKE '%diagnostico%' AND r::text NOT LIKE '%lote%', 'a lista não traz prontuário nem lote');
  PERFORM ci.entrar(vend);
  r := clinica_reforcos_pendentes(20, 180);
  PERFORM ci.sair();
  r := (SELECT coalesce(jsonb_agg(e), '[]'::jsonb) FROM jsonb_array_elements(r) e WHERE (e ->> 'pet_id')::uuid IN (pa, pb, pc, pd, pe, pf));
  PERFORM ci.exige(jsonb_array_length(r) = 2 AND EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet_id' = pb::text), 'com janela de 20 dias entra o pet cuja dose é daqui a 16');
  PERFORM ci.entrar(gest);
  r := clinica_reforcos_pendentes(15, 365);
  PERFORM ci.sair();
  r := (SELECT coalesce(jsonb_agg(e), '[]'::jsonb) FROM jsonb_array_elements(r) e WHERE (e ->> 'pet_id')::uuid IN (pa, pb, pc, pd, pe, pf));
  PERFORM ci.exige(jsonb_array_length(r) = 2 AND EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet_id' = pc::text), 'com 365 dias de atraso entra o pet muito atrasado');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet_id' IN (pd::text, pe::text, pf::text)),
                   'ficam de fora: sem próxima dose, aplicação cancelada e pet com vacina já agendada');

  -- item inativo no catálogo não gera lembrete
  PERFORM ci.entrar(vh);
  PERFORM clinica_vacina_registrar_externa(pd, jsonb_build_object('catalogo_id', c_v10, 'aplicada_em', hoje - 30, 'informado_por', 'Carteira', 'proxima_dose_em', (hoje + 3)::text));
  PERFORM ci.sair();
  UPDATE pet_vacinas_catalogo SET ativo = false WHERE id = c_v10;
  PERFORM ci.entrar(vend);
  r := clinica_reforcos_pendentes(15, 180);
  PERFORM ci.sair();
  r := (SELECT coalesce(jsonb_agg(e), '[]'::jsonb) FROM jsonb_array_elements(r) e WHERE (e ->> 'pet_id')::uuid IN (pa, pb, pc, pd, pe, pf));
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 -> 'itens' -> 0 ->> 'nome' = 'Vermífugo Reforço CI', 'item inativo no catálogo sai da lista');
  UPDATE pet_vacinas_catalogo SET ativo = true WHERE id = c_v10;

  -- chamar / já falei: some da lista naquela data; idempotente; só a recepção e a gestão
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_contato_registrar(%L, 'reforco', %L, 'whatsapp')$c$, pa, hoje - 9), 'garçom registra contato de reforço');
  PERFORM ci.deve_falhar(vh, format($c$SELECT pet_contato_registrar(%L, 'reforco', %L, 'whatsapp')$c$, pa, hoje - 9), 'veterinário registra contato de reforço');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_contato_registrar(%L, 'outro_tipo', %L, 'whatsapp')$c$, pa, hoje - 9), 'tipo de contato inválido');
  PERFORM ci.entrar(vend);
  PERFORM pet_contato_registrar(pa, 'reforco', hoje - 9, 'whatsapp');
  PERFORM pet_contato_registrar(pa, 'reforco', hoje - 9, 'telefone');
  r := clinica_reforcos_pendentes(15, 180);
  PERFORM ci.sair();
  r := (SELECT coalesce(jsonb_agg(e), '[]'::jsonb) FROM jsonb_array_elements(r) e WHERE (e ->> 'pet_id')::uuid IN (pa, pb, pc, pd, pe, pf));
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet_id' = pa::text), 'quem já foi chamado sai da lista naquela data');
  PERFORM ci.exige((SELECT count(*) FROM pet_contatos WHERE pet_id = pa AND tipo = 'reforco') = 1, 'registrar duas vezes não duplica');

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_reforcos_pendentes()', 'reforços sem a clínica liberada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_contato_registrar(%L, 'reforco', %L, 'whatsapp')$c$, pb, hoje + 16), 'contato de reforço sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 47. Clínica (modelos de exame): gestão e veterinário mantêm; modelos iniciais; campo calculado; faixa por espécie; sem acesso direto
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  novo constant uuid := 'a0000000-0000-0000-0000-000000000004';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  vh   constant uuid := 'a0000000-0000-0000-0000-0000000000f5';
  ramo_ant text; cnae_ant text; cnae2_ant text; emp_novo uuid; t_novo uuid;
  r jsonb; m_hemo uuid; m_prop uuid; m_novo uuid; c_hb uuid; c_ht uuid; c_leuco uuid; c_seg uuid; c_abs uuid; c_txt uuid; c_esc uuid; c_outro uuid;
  o_hb int; o_ht int; n int; c_primeiro uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO auth.users (id, email) VALUES (vh, 'vetexame@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = vh;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (vh, demo, 'veterinario');

  -- quem mexe nos modelos: gestão e veterinário; recepção, garçom e profissional não
  PERFORM ci.deve_falhar(gar, 'SELECT clinica_exame_modelos()', 'garçom lê modelos de exame');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_exame_modelos()', 'recepção lê modelos de exame');
  PERFORM ci.deve_falhar(pban, 'SELECT clinica_exame_modelos()', 'profissional de banho lê modelos de exame');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_exame_modelos_iniciais()', 'recepção cria modelos iniciais');
  PERFORM ci.deve_falhar(gar, $c$SELECT clinica_exame_modelo_salvar('{"nome":"X","tipo":"outro"}'::jsonb)$c$, 'garçom cria modelo');
  PERFORM ci.deve_falhar(gest, 'SELECT count(*) FROM pet_exame_modelos', 'gestão lê a tabela de modelos direto');
  PERFORM ci.deve_falhar(vh, 'SELECT count(*) FROM pet_exame_campos', 'veterinário lê a tabela de campos direto');
  PERFORM ci.deve_falhar(vh, 'SELECT count(*) FROM pet_exame_referencias', 'veterinário lê a tabela de faixas direto');
  PERFORM ci.deve_falhar(gest, $c$INSERT INTO pet_exame_modelos (nome, tipo) VALUES ('Direto', 'outro')$c$, 'gestão grava modelo direto na tabela');

  -- modelos iniciais: três modelos, idempotente
  PERFORM ci.entrar(gest);
  n := clinica_exame_modelos_iniciais();
  PERFORM ci.exige(n = 3, 'modelos iniciais criam hemograma, bioquímica e urina');
  PERFORM ci.exige(clinica_exame_modelos_iniciais() = 0, 'chamar de novo não duplica');
  r := clinica_exame_modelos();
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 3, 'a empresa tem 3 modelos');
  m_hemo := (SELECT (e ->> 'id')::uuid FROM jsonb_array_elements(r) e WHERE e ->> 'nome' = 'Hemograma');
  PERFORM ci.exige((SELECT jsonb_array_length(e -> 'campos') FROM jsonb_array_elements(r) e WHERE e ->> 'nome' = 'Hemograma') = 26, 'hemograma inicial tem 26 campos');
  PERFORM ci.exige((SELECT jsonb_array_length(e -> 'campos') FROM jsonb_array_elements(r) e WHERE e ->> 'nome' = 'Bioquímica sanguínea') = 22, 'bioquímica inicial tem os 21 itens e as observações');
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_campos WHERE modelo_id = m_hemo AND forma = 'calculado' AND total_campo_id IS NOT NULL AND pct_campo_id IS NOT NULL) = 7,
                   'o hemograma tem 7 absolutos calculados, ligados ao total e ao percentual');
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome IN ('VCM', 'HCM', 'CHCM', 'RDW')) = 4, 'hemograma traz VCM, HCM, CHCM e RDW');
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_referencias WHERE tenant_id = demo) = 0, 'o sistema não traz faixa de referência pronta');
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_campos c JOIN pet_exame_modelos m ON m.id = c.modelo_id WHERE m.tenant_id = demo AND m.nome = 'Urina' AND c.forma = 'escolha') = 6,
                   'a urina tem 6 campos de escolha');

  SELECT id INTO c_hb FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Hemoglobina';
  SELECT id INTO c_ht FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Hematócrito';
  SELECT id INTO c_leuco FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Leucócitos totais';
  SELECT id INTO c_seg FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Segmentados (%)';
  SELECT id INTO c_abs FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Segmentados (abs.)';
  SELECT id INTO c_txt FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Observações';

  -- veterinário (perfil restrito) também mantém os modelos
  PERFORM ci.entrar(vh);
  m_prop := clinica_exame_modelo_salvar(jsonb_build_object('nome', 'Exame próprio CI', 'tipo', 'outro', 'material', 'Soro'));
  PERFORM ci.sair();
  PERFORM ci.exige(m_prop IS NOT NULL, 'veterinário cria um modelo');
  PERFORM ci.deve_falhar(gest, $c$SELECT clinica_exame_modelo_salvar('{"nome":" exame PRÓPRIO ci ","tipo":"outro"}'::jsonb)$c$, 'nome de modelo repetido (sem diferenciar maiúsculas)');
  PERFORM ci.deve_falhar(gest, $c$SELECT clinica_exame_modelo_salvar('{"nome":"Tipo ruim","tipo":"raiox"}'::jsonb)$c$, 'tipo de modelo inválido');
  PERFORM ci.deve_falhar(gest, $c$SELECT clinica_exame_modelo_salvar('{"nome":"","tipo":"outro"}'::jsonb)$c$, 'modelo sem nome');

  -- campos: regras de cada forma
  PERFORM ci.entrar(vh);
  c_esc := clinica_exame_campo_salvar(jsonb_build_object('modelo_id', m_prop, 'nome', 'Resultado', 'forma', 'escolha', 'opcoes', jsonb_build_array('Reagente', 'Não reagente', 'Reagente')));
  c_outro := clinica_exame_campo_salvar(jsonb_build_object('modelo_id', m_prop, 'nome', 'Valor', 'unidade', 'mg/dL', 'forma', 'numero', 'casas', 1));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT jsonb_array_length(opcoes) FROM pet_exame_campos WHERE id = c_esc) = 2, 'opção repetida entra uma vez só');
  PERFORM ci.exige((SELECT opcoes FROM pet_exame_campos WHERE id = c_esc) = '["Reagente", "Não reagente"]'::jsonb, 'as opções ficam na ordem digitada, sem repetir');
  PERFORM ci.exige((SELECT c.opcoes FROM pet_exame_campos c JOIN pet_exame_modelos m ON m.id = c.modelo_id WHERE m.tenant_id = demo AND m.nome = 'Urina' AND c.nome = 'Corpos cetônicos') = '["Negativo", "Traços", "+", "++", "+++"]'::jsonb,
                   'a ordem das opções dos modelos iniciais é a da semente');
  PERFORM ci.exige((SELECT ordem FROM pet_exame_campos WHERE id = c_outro) = (SELECT ordem + 1 FROM pet_exame_campos WHERE id = c_esc), 'campo novo vai para o fim do modelo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Casas', 'forma', 'numero', 'casas', 7))$c$, m_prop), 'casas decimais acima de 6');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Sem opção', 'forma', 'escolha'))$c$, m_prop), 'escolha sem opções');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Forma ruim', 'forma', 'imagem'))$c$, m_prop), 'forma de valor inválida');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', ' valor ', 'forma', 'numero'))$c$, m_prop), 'nome de campo repetido no mesmo grupo');
  PERFORM ci.deve_falhar(gest, $c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', gen_random_uuid(), 'nome', 'Órfão', 'forma', 'texto'))$c$, 'campo em modelo que não existe');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Garçom', 'forma', 'texto'))$c$, m_prop), 'garçom cria campo');
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_campo_salvar(jsonb_build_object('modelo_id', m_prop, 'nome', 'Valor', 'grupo', 'Outro grupo', 'forma', 'texto'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_campos WHERE modelo_id = m_prop AND nome = 'Valor') = 2, 'o mesmo nome vale em grupos diferentes');

  -- campo calculado: total e percentual numéricos, do mesmo modelo
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Calc texto', 'forma', 'calculado', 'total_campo_id', %L, 'pct_campo_id', %L))$c$, m_hemo, c_leuco, c_txt), 'calculado apontando para campo de texto');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Calc igual', 'forma', 'calculado', 'total_campo_id', %L, 'pct_campo_id', %L))$c$, m_hemo, c_leuco, c_leuco), 'calculado com o mesmo campo no total e no percentual');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Calc de fora', 'forma', 'calculado', 'total_campo_id', %L, 'pct_campo_id', %L))$c$, m_prop, c_leuco, c_seg), 'calculado com campos de outro modelo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Calc sem ligação', 'forma', 'calculado'))$c$, m_hemo), 'calculado sem total e percentual');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('id', %L, 'nome', 'Leucócitos totais', 'grupo', 'Leucograma', 'forma', 'texto'))$c$, c_leuco), 'campo que alimenta um cálculo virar texto');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('id', %L, 'nome', 'Segmentados (%%)', 'grupo', 'Leucograma — relativo', 'forma', 'numero', 'casas', 0, 'ativo', false))$c$, c_seg), 'campo que alimenta um cálculo sair de uso');
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_campo_salvar(jsonb_build_object('id', c_abs, 'nome', 'Segmentados (abs.)', 'grupo', 'Leucograma — absoluto', 'unidade', 'cél/mm³', 'forma', 'calculado', 'casas', 0,
                                                       'total_campo_id', c_leuco, 'pct_campo_id', c_seg, 'ativo', true));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT unidade FROM pet_exame_campos WHERE id = c_abs) = 'cél/mm³', 'campo calculado editável (unidade)');

  -- faixa de referência por espécie
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_exame_referencia_salvar(%L, 'cao', 1, 2)$c$, c_hb), 'recepção grava faixa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_referencia_salvar(%L, 'passaro', 1, 2)$c$, c_hb), 'espécie inválida na faixa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_referencia_salvar(%L, 'cao', 5, 2)$c$, c_hb), 'mínimo maior que o máximo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_referencia_salvar(%L, 'cao', 1, 2)$c$, c_txt), 'faixa em campo de texto');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_referencia_salvar(%L, 'cao', 1, 2)$c$, c_esc), 'faixa em campo de escolha');
  PERFORM ci.entrar(vh);
  PERFORM clinica_exame_referencia_salvar(c_hb, 'cao', 12, 18);
  PERFORM clinica_exame_referencia_salvar(c_hb, 'gato', 8, 15);
  PERFORM clinica_exame_referencia_salvar(c_hb, 'cao', 11, 19);
  PERFORM clinica_exame_referencia_salvar(c_abs, 'outro', NULL, 9000);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_referencias WHERE campo_id = c_hb) = 2, 'uma faixa por espécie (gravar de novo troca)');
  PERFORM ci.exige((SELECT minimo FROM pet_exame_referencias WHERE campo_id = c_hb AND especie = 'cao') = 11, 'a faixa do cão ficou com o último valor');
  PERFORM ci.exige((SELECT minimo IS NULL AND maximo = 9000 FROM pet_exame_referencias WHERE campo_id = c_abs AND especie = 'outro'), 'faixa só com máximo, em campo calculado e espécie outro');
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_referencia_salvar(c_hb, 'gato', NULL, NULL);
  r := clinica_exame_modelos();
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_referencias WHERE campo_id = c_hb) = 1, 'mínimo e máximo em branco tiram a faixa');
  PERFORM ci.exige((SELECT jsonb_array_length(c -> 'referencias') FROM jsonb_array_elements(r) e, jsonb_array_elements(e -> 'campos') c WHERE (c ->> 'id')::uuid = c_hb) = 1,
                   'a lista de modelos traz as faixas de cada campo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('id', %L, 'nome', 'Hemoglobina', 'grupo', 'Eritrograma', 'forma', 'texto'))$c$, c_hb), 'trocar para texto um campo que tem faixa');

  -- ordem dos campos
  SELECT ordem INTO o_hb FROM pet_exame_campos WHERE id = c_hb;
  SELECT ordem INTO o_ht FROM pet_exame_campos WHERE id = c_ht;
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_exame_campo_mover(%L, 1)$c$, c_hb), 'recepção reordena campo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_mover(%L, 2)$c$, c_hb), 'mover mais de uma posição');
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_campo_mover(c_hb, 1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT ordem FROM pet_exame_campos WHERE id = c_hb) = o_ht AND (SELECT ordem FROM pet_exame_campos WHERE id = c_ht) = o_hb, 'mover desce o campo e sobe o vizinho');
  SELECT id INTO c_primeiro FROM pet_exame_campos WHERE modelo_id = m_hemo ORDER BY ordem, id LIMIT 1;
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_campo_mover(c_hb, -1);
  PERFORM clinica_exame_campo_mover(c_primeiro, -1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT ordem FROM pet_exame_campos WHERE id = c_hb) = o_hb, 'mover de volta restaura a ordem');
  PERFORM ci.exige((SELECT min(ordem) FROM pet_exame_campos WHERE modelo_id = m_hemo) = 0, 'subir o primeiro campo não faz nada');

  -- outra empresa não enxerga nem mexe
  SELECT tenant_id INTO t_novo FROM profiles WHERE id = novo;
  INSERT INTO empresas (tenant_id, razao_social, ramo_atividade) VALUES (t_novo, 'Outra clínica exame CI', 'clinica') RETURNING id INTO emp_novo;
  PERFORM ci.entrar(novo);
  r := clinica_exame_modelos();
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 0, 'outra empresa não vê os modelos');
  PERFORM ci.deve_falhar(novo, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('id', %L, 'nome', 'Invasor', 'forma', 'texto'))$c$, c_txt), 'outra empresa edita campo alheio');
  PERFORM ci.deve_falhar(novo, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Invasor', 'forma', 'texto'))$c$, m_hemo), 'outra empresa cria campo em modelo alheio');
  PERFORM ci.deve_falhar(novo, format($c$SELECT clinica_exame_referencia_salvar(%L, 'cao', 1, 2)$c$, c_hb), 'outra empresa grava faixa em campo alheio');
  PERFORM ci.deve_falhar(novo, format($c$SELECT clinica_exame_campo_mover(%L, 1)$c$, c_hb), 'outra empresa reordena campo alheio');
  PERFORM ci.entrar(novo);
  PERFORM ci.exige(clinica_exame_modelos_iniciais() = 3, 'outra empresa tem os próprios modelos iniciais');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_modelos WHERE tenant_id = demo) = 4, 'os modelos da empresa não mudaram');
  DELETE FROM empresas WHERE id = emp_novo;

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(gest, 'SELECT clinica_exame_modelos()', 'modelos sem a clínica liberada');
  PERFORM ci.deve_falhar(vh, 'SELECT clinica_exame_modelos_iniciais()', 'modelos iniciais sem a clínica liberada');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_campo_salvar(jsonb_build_object('modelo_id', %L, 'nome', 'Sem clínica', 'forma', 'texto'))$c$, m_prop), 'campo sem a clínica liberada');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_referencia_salvar(%L, 'cao', 1, 2)$c$, c_hb), 'faixa sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 48. Clínica (resultados de exame): só o veterinário; cópia dos campos na abertura; calculado; fechado imutável; adendo; cancelar; evolução
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  va   constant uuid := 'a0000000-0000-0000-0000-0000000000f6';
  vb   constant uuid := 'a0000000-0000-0000-0000-0000000000f7';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  t0 timestamptz := date_trunc('day', now()) + interval '16 days' + interval '9 hours';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet uuid; gato uuid; cons uuid; pva uuid; pvb uuid; ag1 uuid; ag2 uuid; at1 uuid; at2 uuid; tb uuid; tutor_b uuid; pet_b uuid;
  m_hemo uuid; m_urina uuid; m_bioq uuid; c_hb uuid; c_leuco uuid; c_seg uuid; c_ht uuid; c_aspecto uuid;
  r jsonb; ex1 uuid; ex2 uuid; ex3 uuid; ex4 uuid; ex5 uuid; ex6 uuid;
  r_hb uuid; r_leuco uuid; r_seg uuid; r_eos uuid; r_lin uuid; r_hemac uuid; r_obs uuid; r_asp uuid; r_vol uuid;
  n bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Exame CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO tenants (nome) VALUES ('Clinica B Exame CI') RETURNING id INTO tb;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (tb, 'Tutor Outra Empresa Exame', '11144477735') RETURNING id INTO tutor_b;
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (tb, tutor_b, 'Pet Outra Empresa Exame') RETURNING id INTO pet_b;
  INSERT INTO auth.users (id, email) VALUES (va, 'vetexa@ci'), (vb, 'vetexb@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (va, vb);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (va, demo, 'veterinario'), (vb, demo, 'veterinario');

  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Exame CI","categoria":"consulta","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 150);
  pva := pet_profissional_salvar('{"nome":"Vet A Exame","funcao":"veterinario","crmv":"7771","crmv_uf":"SP"}'::jsonb);
  pvb := pet_profissional_salvar('{"nome":"Vet B Exame","funcao":"veterinario","crmv":"7772","crmv_uf":"RJ"}'::jsonb);
  PERFORM pet_profissional_vincular(pva, va);
  PERFORM pet_profissional_vincular(pvb, vb);
  PERFORM clinica_exame_modelos_iniciais();
  PERFORM ci.sair();
  SELECT id INTO m_hemo FROM pet_exame_modelos WHERE tenant_id = demo AND nome = 'Hemograma';
  SELECT id INTO m_urina FROM pet_exame_modelos WHERE tenant_id = demo AND nome = 'Urina';
  SELECT id INTO m_bioq FROM pet_exame_modelos WHERE tenant_id = demo AND nome = 'Bioquímica sanguínea';
  SELECT id INTO c_hb FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Hemoglobina';
  SELECT id INTO c_ht FROM pet_exame_campos WHERE modelo_id = m_hemo AND nome = 'Hematócrito';
  SELECT id INTO c_aspecto FROM pet_exame_campos WHERE modelo_id = m_urina AND nome = 'Aspecto';
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_referencia_salvar(c_hb, 'cao', 12, 18);
  PERFORM clinica_exame_referencia_salvar(c_hb, 'gato', 8, 15);
  PERFORM ci.sair();

  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Rex Exame CI', 'especie', 'cao'));
  gato := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Mimi Exame CI', 'especie', 'gato'));
  ag1 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', pva, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag2 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', pvb, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  PERFORM ci.sair();
  PERFORM ci.entrar(va);
  at1 := (clinica_atendimento_abrir(ag1) ->> 'id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.entrar(vb);
  at2 := (clinica_atendimento_abrir(ag2) ->> 'id')::uuid;
  PERFORM ci.sair();

  -- ninguém além do veterinário lê ou escreve resultado de exame
  PERFORM ci.deve_falhar(adm, format($c$SELECT clinica_exames_do_pet(%L)$c$, pet), 'administrador lê a lista de exames');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exames_do_pet(%L)$c$, pet), 'gestor lê a lista de exames');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_exames_do_pet(%L)$c$, pet), 'recepção lê a lista de exames');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_exames_do_pet(%L)$c$, pet), 'garçom lê a lista de exames');
  PERFORM ci.deve_falhar(pban, format($c$SELECT clinica_exames_do_pet(%L)$c$, pet), 'profissional de banho lê a lista de exames');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_abrir(%L, %L, '{"laboratorio":"Lab"}'::jsonb)$c$, pet, m_hemo), 'gestor abre exame');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_evolucao(%L, 'Hemoglobina', 'g/dL')$c$, pet), 'gestor lê a evolução');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM pet_exames', 'leitura direta do exame');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM pet_exame_resultados', 'leitura direta do resultado pelo próprio veterinário');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM pet_exame_adendos', 'leitura direta do adendo de exame');
  PERFORM ci.deve_falhar(va, format($c$INSERT INTO pet_exames (tenant_id, pet_id, modelo_id, veterinario_id, crmv, crmv_uf, nome, tipo, laboratorio, data_coleta) VALUES (%L, %L, %L, %L, '7771', 'SP', 'x', 'outro', 'L', current_date)$c$, demo, pet, m_hemo, pva), 'escrita direta do exame');

  -- abrir: regras
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, '{}'::jsonb)$c$, pet, m_hemo), 'exame avulso sem laboratório');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, jsonb_build_object('laboratorio', 'Lab', 'data_coleta', %L))$c$, pet, m_hemo, hoje + 1), 'coleta no futuro');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, jsonb_build_object('laboratorio', 'Lab', 'data_coleta', 'ontem'))$c$, pet, m_hemo), 'data da coleta que não é data');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, '{"laboratorio":"Lab"}'::jsonb)$c$, pet_b, m_hemo), 'paciente de outra empresa');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, '{"laboratorio":"Lab"}'::jsonb)$c$, pet, gen_random_uuid()), 'modelo que não existe');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, jsonb_build_object('atendimento_id', %L))$c$, pet, m_hemo, at2), 'atendimento de outro veterinário');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, jsonb_build_object('atendimento_id', %L))$c$, gato, m_hemo, at1), 'atendimento de outro paciente');
  UPDATE pet_exame_modelos SET ativo = false WHERE id = m_bioq;
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, '{"laboratorio":"Lab"}'::jsonb)$c$, pet, m_bioq), 'modelo inativo');
  UPDATE pet_exame_modelos SET ativo = true WHERE id = m_bioq;

  PERFORM ci.entrar(va);
  r := clinica_exame_abrir(pet, m_hemo, jsonb_build_object('atendimento_id', at1));
  ex1 := (r ->> 'id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'resultados') = 26 AND r ->> 'situacao' = 'aberto' AND r ->> 'atendimento_id' = at1::text, 'o exame nasce aberto, ligado ao atendimento e com os 26 campos do modelo');
  PERFORM ci.exige(r -> 'veterinario' ->> 'crmv' = '7771' AND r ->> 'material' = 'Sangue total em EDTA' AND r ->> 'tutor' = 'Tutor Exame CI', 'traz o CRMV da abertura, o material do modelo e o tutor');
  PERFORM ci.exige((SELECT (x ->> 'faixa_min')::numeric = 12 AND (x ->> 'faixa_max')::numeric = 18 FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'),
                   'a faixa da espécie do paciente (cão) é copiada para o exame');
  PERFORM ci.exige((SELECT count(*) FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'forma' = 'calculado' AND x ->> 'total_id' IS NOT NULL AND x ->> 'pct_id' IS NOT NULL) = 7,
                   'os 7 absolutos calculados apontam para o total e o percentual do próprio exame');
  PERFORM ci.exige((SELECT count(*) FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'valor_num' IS NOT NULL OR x ->> 'valor_texto' IS NOT NULL) = 0, 'tudo em branco: não feito');
  SELECT (x ->> 'id')::uuid INTO r_hb FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina';
  SELECT (x ->> 'id')::uuid INTO r_leuco FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Leucócitos totais';
  SELECT (x ->> 'id')::uuid INTO r_seg FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Segmentados (%)';
  SELECT (x ->> 'id')::uuid INTO r_eos FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Eosinófilos (%)';
  SELECT (x ->> 'id')::uuid INTO r_lin FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Linfócitos (%)';
  SELECT (x ->> 'id')::uuid INTO r_hemac FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemácias';
  SELECT (x ->> 'id')::uuid INTO r_obs FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Observações';

  -- a faixa do gato vem da faixa do gato
  PERFORM ci.entrar(va);
  r := clinica_exame_abrir(gato, m_hemo, '{"laboratorio":"Laboratório Externo CI","data_coleta":"2026-01-10"}'::jsonb);
  ex2 := (r ->> 'id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT (x ->> 'faixa_max')::numeric = 15 FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'), 'gato recebe a faixa do gato');
  PERFORM ci.exige(r ->> 'laboratorio' = 'Laboratório Externo CI' AND r ->> 'atendimento_id' IS NULL AND r ->> 'data_coleta' = '2026-01-10', 'exame avulso guarda laboratório e data da coleta');

  -- preencher
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('observacoes', 'x'))$c$, ex1), 'outro veterinário preenche o exame');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', %L, 'valor', 'abc'))))$c$, ex1, r_hb), 'valor que não é número');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', %L, 'valor', '-3'))))$c$, ex1, r_hb), 'valor negativo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', %L, 'valor', '1'))))$c$, ex1, (SELECT id FROM pet_exame_resultados WHERE exame_id = ex2 LIMIT 1)), 'resultado de outro exame');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', %L, 'faixa_min', '9', 'faixa_max', '3'))))$c$, ex1, r_hb), 'faixa com mínimo maior que o máximo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('data_coleta', %L))$c$, ex1, hoje + 2), 'data da coleta no futuro ao salvar');
  PERFORM ci.entrar(va);
  r := clinica_exame_salvar(ex1, jsonb_build_object('resultados', jsonb_build_array(
         jsonb_build_object('id', r_hb, 'valor', '13,3', 'nota', 'conferido'),
         jsonb_build_object('id', r_leuco, 'valor', '6600'),
         jsonb_build_object('id', r_seg, 'valor', '40'),
         jsonb_build_object('id', r_eos, 'valor', '5'),
         jsonb_build_object('id', r_lin, 'valor', '55'),
         jsonb_build_object('id', r_obs, 'valor', 'Plaquetas em agregados'),
         jsonb_build_object('id', r_hemac, 'faixa_min', '5', 'faixa_max', '10'))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT (x ->> 'valor_num')::numeric = 13.3 AND x ->> 'nota' = 'conferido' FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'), 'valor com vírgula e nota gravados');
  PERFORM ci.exige((SELECT (x ->> 'valor_num')::numeric FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Segmentados (abs.)') = 2640
               AND (SELECT (x ->> 'valor_num')::numeric FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Eosinófilos (abs.)') = 330
               AND (SELECT (x ->> 'valor_num')::numeric FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Linfócitos (abs.)') = 3630,
               'os absolutos são calculados: 6600 × 40% = 2640, 5% = 330, 55% = 3630');
  PERFORM ci.exige((SELECT x ->> 'valor_num' IS NULL FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Monócitos (abs.)'), 'absoluto sem o percentual fica em branco');
  PERFORM ci.exige((SELECT (x ->> 'faixa_min')::numeric = 5 AND (x ->> 'faixa_max')::numeric = 10 FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemácias'), 'a faixa do exame pode ser ajustada (a do laudo externo)');
  PERFORM ci.exige((SELECT x ->> 'valor_texto' = 'Plaquetas em agregados' FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Observações'), 'campo de texto gravado');

  -- chave ausente não apaga; em branco apaga; mudar o total refaz os absolutos
  PERFORM ci.entrar(va);
  r := clinica_exame_salvar(ex1, jsonb_build_object('observacoes', 'Coleta em jejum'));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'observacoes' = 'Coleta em jejum' AND (SELECT (x ->> 'valor_num')::numeric = 13.3 FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'),
                   'salvar só as observações do exame não apaga os valores');
  PERFORM ci.entrar(va);
  r := clinica_exame_salvar(ex1, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', r_leuco, 'valor', '10000'), jsonb_build_object('id', r_hb, 'valor', ''))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT (x ->> 'valor_num')::numeric FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Segmentados (abs.)') = 4000, 'mudar o total refaz os absolutos');
  PERFORM ci.exige((SELECT x ->> 'valor_num' IS NULL FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'), 'valor em branco volta a "não feito"');
  PERFORM ci.entrar(va);
  r := clinica_exame_salvar(ex1, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', r_hb, 'valor', '14'))));
  PERFORM ci.sair();

  -- editar o modelo depois não muda o exame já aberto
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_campo_salvar(jsonb_build_object('id', c_hb, 'nome', 'Hemoglobina renomeada', 'grupo', 'Eritrograma', 'unidade', 'g%', 'forma', 'numero', 'casas', 1));
  PERFORM clinica_exame_referencia_salvar(c_hb, 'cao', 1, 2);
  PERFORM ci.sair();
  PERFORM ci.entrar(va);
  r := clinica_exame_get(ex1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT x ->> 'unidade' = 'g/dL' AND (x ->> 'faixa_min')::numeric = 12 FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'),
                   'o exame mantém nome, unidade e faixa de quando foi aberto');
  PERFORM ci.entrar(gest);
  PERFORM clinica_exame_campo_salvar(jsonb_build_object('id', c_hb, 'nome', 'Hemoglobina', 'grupo', 'Eritrograma', 'unidade', 'g/dL', 'forma', 'numero', 'casas', 1));
  PERFORM clinica_exame_referencia_salvar(c_hb, 'cao', 12, 18);
  PERFORM ci.sair();

  -- fechar
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_exame_fechar(%L)$c$, ex1), 'outro veterinário fecha o exame');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_fechar(%L)$c$, ex2), 'fechar exame sem nenhum resultado');
  PERFORM ci.entrar(va);
  r := clinica_exame_fechar(ex1);
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'situacao' = 'fechado' AND r ->> 'fechado_em' IS NOT NULL, 'exame fechado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('observacoes', 'x'))$c$, ex1), 'preencher exame fechado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_fechar(%L)$c$, ex1), 'fechar duas vezes');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_cancelar(%L, 'erro')$c$, ex1), 'cancelar exame fechado');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exame_resultados SET valor_num = 99 WHERE id = %L$c$, r_hb), 'alterar resultado de exame fechado, nem o dono do banco');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exames SET observacoes = 'x' WHERE id = %L$c$, ex1), 'alterar exame fechado, nem o dono do banco');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_exame_resultados WHERE exame_id = %L$c$, ex1), 'apagar resultado de exame fechado');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_exames WHERE id = %L$c$, ex1), 'apagar exame');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exame_resultados SET nome = 'Outro nome' WHERE exame_id = %L$c$, ex2), 'trocar a cópia do campo mesmo com o exame aberto');
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_resultados WHERE exame_id = ex1 AND valor_num = 99) = 0, 'o resultado fechado continua o mesmo');

  -- adendo
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_exame_adendo_criar(%L, 'x')$c$, ex1), 'gestor faz adendo de exame');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_exame_adendo_criar(%L, '   ')$c$, ex1), 'adendo vazio');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_exame_adendo_criar(%L, 'x')$c$, ex2), 'adendo em exame aberto');
  PERFORM ci.entrar(vb);
  r := clinica_exame_adendo_criar(ex1, 'Hemoglobina digitada errada: o laudo traz 14,0 g/dL.');
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'adendos') = 1 AND r -> 'adendos' -> 0 ->> 'crmv' = '7772' AND r -> 'adendos' -> 0 ->> 'veterinario' = 'Vet B Exame', 'o adendo traz o nome e o CRMV de quem fez');
  PERFORM ci.deve_falhar_dono('UPDATE pet_exame_adendos SET texto = ''x''', 'alterar adendo de exame');
  PERFORM ci.deve_falhar_dono('DELETE FROM pet_exame_adendos', 'apagar adendo de exame');

  -- cancelar
  PERFORM ci.entrar(va);
  r := clinica_exame_abrir(pet, m_urina, '{"laboratorio":"Lab Urina CI"}'::jsonb);
  ex3 := (r ->> 'id')::uuid;
  PERFORM ci.sair();
  SELECT (x ->> 'id')::uuid INTO r_asp FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Aspecto';
  SELECT (x ->> 'id')::uuid INTO r_vol FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Volume';
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', %L, 'valor', 'Verde'))))$c$, ex3, r_asp), 'escolha fora da lista');
  PERFORM ci.entrar(va);
  r := clinica_exame_salvar(ex3, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', r_asp, 'valor', 'Turvo'), jsonb_build_object('id', r_vol, 'valor', '45'))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT x ->> 'valor_texto' = 'Turvo' FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Aspecto'), 'escolha dentro da lista gravada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_cancelar(%L, '  ')$c$, ex3), 'cancelar sem motivo');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_exame_cancelar(%L, 'aberto por engano')$c$, ex3), 'outro veterinário cancela o exame');
  PERFORM ci.entrar(va);
  r := clinica_exame_cancelar(ex3, 'Aberto no paciente errado');
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'situacao' = 'cancelado' AND r ->> 'cancelado_motivo' = 'Aberto no paciente errado', 'exame cancelado com motivo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('observacoes', 'x'))$c$, ex3), 'preencher exame cancelado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_fechar(%L)$c$, ex3), 'fechar exame cancelado');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exames SET cancelado_motivo = 'outro' WHERE id = %L$c$, ex3), 'mudar o motivo do cancelamento');

  -- lista e auditoria
  SELECT count(*) INTO n FROM clinica_acessos WHERE tenant_id = demo AND acao = 'exame';
  PERFORM ci.entrar(va);
  r := clinica_exames_do_pet(pet);
  PERFORM ci.sair();
  PERFORM ci.exige(r -> 'pet' ->> 'nome' = 'Rex Exame CI' AND r ->> 'tutor' = 'Tutor Exame CI', 'a lista traz o paciente e o tutor');
  PERFORM ci.exige(jsonb_array_length(r -> 'exames') = 2 AND EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'exames') x WHERE x ->> 'id' = ex1::text AND x ->> 'situacao' = 'fechado' AND (x ->> 'preenchidos')::int = 6)
                   AND EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'exames') x WHERE x ->> 'id' = ex3::text AND x ->> 'situacao' = 'cancelado'),
                   'a lista do paciente traz o fechado (6 campos preenchidos) e o cancelado, sem valores');
  PERFORM ci.exige(r::text NOT LIKE '%valor_num%' AND r::text NOT LIKE '%queixa%', 'a lista não traz valores nem prontuário');
  PERFORM ci.exige((SELECT count(*) FROM clinica_acessos WHERE tenant_id = demo AND acao = 'exame') > n, 'abrir a lista de exames fica na auditoria de acessos');
  PERFORM ci.exige((SELECT count(*) FROM clinica_acessos WHERE tenant_id = demo AND acao = 'exame' AND profile_id = va) >= 3, 'a auditoria guarda quem abriu');

  -- evolução: só exames fechados, mesmo campo e unidade, do mais antigo para o mais novo
  PERFORM ci.entrar(va);
  r := clinica_exame_abrir(pet, m_hemo, '{"laboratorio":"Lab Antigo CI","data_coleta":"2026-02-01"}'::jsonb);
  ex4 := (r ->> 'id')::uuid;
  PERFORM ci.sair();
  SELECT (x ->> 'id')::uuid INTO r_hb FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina';
  PERFORM ci.entrar(va);
  PERFORM clinica_exame_salvar(ex4, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', r_hb, 'valor', '12,5'))));
  PERFORM clinica_exame_fechar(ex4);
  r := clinica_exame_abrir(pet, m_hemo, '{"laboratorio":"Lab Aberto CI","data_coleta":"2026-03-01"}'::jsonb);
  ex5 := (r ->> 'id')::uuid;
  PERFORM clinica_exame_salvar(ex5, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', (SELECT (x ->> 'id')::uuid FROM jsonb_array_elements(r -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'), 'valor', '99'))));
  r := clinica_exame_evolucao(pet, 'hemoglobina', 'g/dL');
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 2 AND (r -> 0 ->> 'data_coleta') < (r -> 1 ->> 'data_coleta') AND (r -> 0 ->> 'valor')::numeric = 12.5 AND (r -> 1 ->> 'valor')::numeric = 14,
                   'a evolução traz só os exames fechados do pet, do mais antigo para o mais novo');
  PERFORM ci.entrar(va);
  PERFORM ci.exige(jsonb_array_length(clinica_exame_evolucao(pet, 'Hemoglobina', 'g%')) = 0, 'unidade diferente não entra na mesma evolução');
  PERFORM ci.exige(jsonb_array_length(clinica_exame_evolucao(gato, 'Hemoglobina', 'g/dL')) = 0, 'a evolução é do paciente (o gato não tem exame fechado)');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_evolucao(%L, 'Hemoglobina', 'g/dL')$c$, pet_b), 'evolução de paciente de outra empresa');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_get(%L)$c$, gen_random_uuid()), 'exame que não existe');

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exames_do_pet(%L)$c$, pet), 'lista de exames sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_abrir(%L, %L, '{"laboratorio":"Lab"}'::jsonb)$c$, pet, m_hemo), 'abrir exame sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_salvar(%L, jsonb_build_object('observacoes', 'x'))$c$, ex5), 'preencher exame sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_exame_get(%L)$c$, ex1), 'ler exame sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 49. Clínica (anexos de exame): armazenamento privado, envio só em caminho reservado, link só depois de registrar a abertura, imutável
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  va   constant uuid := 'a0000000-0000-0000-0000-0000000000f8';
  vb   constant uuid := 'a0000000-0000-0000-0000-0000000000f9';
  t0 timestamptz := date_trunc('day', now()) + interval '18 days' + interval '9 hours';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet uuid; cons uuid; pva uuid; pvb uuid; ag1 uuid; at1 uuid; m_hemo uuid; ex1 uuid; ex2 uuid;
  r jsonb; an1 uuid; an2 uuid; an3 uuid; an4 uuid; c1 text; c2 text; c3 text; c4 text; n bigint; i int;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Anexo CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (va, 'vetana@ci'), (vb, 'vetanb@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (va, vb);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (va, demo, 'veterinario'), (vb, demo, 'veterinario');

  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Anexo CI","categoria":"consulta","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 150);
  pva := pet_profissional_salvar('{"nome":"Vet A Anexo","funcao":"veterinario","crmv":"8881","crmv_uf":"SP"}'::jsonb);
  pvb := pet_profissional_salvar('{"nome":"Vet B Anexo","funcao":"veterinario","crmv":"8882","crmv_uf":"RJ"}'::jsonb);
  PERFORM pet_profissional_vincular(pva, va);
  PERFORM pet_profissional_vincular(pvb, vb);
  PERFORM clinica_exame_modelos_iniciais();
  PERFORM ci.sair();
  SELECT id INTO m_hemo FROM pet_exame_modelos WHERE tenant_id = demo AND nome = 'Hemograma';
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Rex Anexo CI', 'especie', 'cao'));
  ag1 := pet_agendar(jsonb_build_object('pet_id', pet, 'profissional_id', pva, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  PERFORM ci.sair();
  PERFORM ci.entrar(va);
  at1 := (clinica_atendimento_abrir(ag1) ->> 'id')::uuid;
  ex1 := (clinica_exame_abrir(pet, m_hemo, jsonb_build_object('atendimento_id', at1)) ->> 'id')::uuid;
  ex2 := (clinica_exame_abrir(pet, m_hemo, '{"laboratorio":"Lab Anexo CI"}'::jsonb) ->> 'id')::uuid;
  PERFORM clinica_exame_cancelar(ex2, 'Aberto por engano');
  PERFORM ci.sair();

  -- bucket privado, só JPEG, PNG e PDF até 15 MB
  PERFORM ci.exige((SELECT NOT public AND file_size_limit = 15728640 AND allowed_mime_types @> ARRAY['image/jpeg', 'image/png', 'application/pdf'] AND cardinality(allowed_mime_types) = 3
                      FROM storage.buckets WHERE id = 'clinica-anexos'), 'o bucket de anexos é privado, com 15 MB e só JPEG, PNG e PDF');

  -- só o veterinário usa os anexos
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, ex1), 'gestor prepara anexo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, ex1), 'recepção prepara anexo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_anexos(%L, NULL)$c$, ex1), 'garçom lista anexos');
  PERFORM ci.deve_falhar(pban, format($c$SELECT clinica_anexos(%L, NULL)$c$, ex1), 'profissional de banho lista anexos');
  PERFORM ci.deve_falhar(gest, 'SELECT count(*) FROM pet_exame_anexos', 'leitura direta da tabela de anexos');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM pet_exame_anexos', 'leitura direta da tabela de anexos pelo veterinário');
  PERFORM ci.deve_falhar(va, format($c$INSERT INTO pet_exame_anexos (tenant_id, pet_id, exame_id, categoria, descricao, nome_arquivo, mime, tamanho, caminho, veterinario_id, crmv, crmv_uf) VALUES (%L, %L, %L, 'laudo', 'x', 'x.pdf', 'application/pdf', 10, 'x/y/z.pdf', %L, '8881', 'SP')$c$, demo, pet, ex1, pva), 'escrita direta de anexo');

  -- preparar: regras
  PERFORM ci.deve_falhar(va, 'SELECT clinica_anexo_preparar(''{"categoria":"laudo","descricao":"x","nome_arquivo":"x.pdf","mime":"application/pdf","tamanho":100}''::jsonb)', 'sem exame nem atendimento');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'atendimento_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, ex1, at1), 'exame e atendimento ao mesmo tempo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'foto', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, ex1), 'tipo de anexo inválido');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', '  ', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, ex1), 'anexo sem descrição');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.zip', 'mime', 'application/zip', 'tamanho', 100))$c$, ex1), 'formato não aceito');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/dicom', 'tamanho', 100))$c$, ex1), 'DICOM fica de fora');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 0))$c$, ex1), 'arquivo vazio');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 15728641))$c$, ex1), 'arquivo acima de 15 MB');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 'grande'))$c$, ex1), 'tamanho que não é número');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, ex2), 'anexo em exame cancelado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, gen_random_uuid()), 'anexo em exame que não existe');

  PERFORM ci.entrar(va);
  r := clinica_anexo_preparar(jsonb_build_object('exame_id', ex1, 'categoria', 'imagem', 'descricao', 'Ultrassom abdominal', 'nome_arquivo', 'ultra.png', 'mime', 'image/png', 'tamanho', 2048));
  PERFORM ci.sair();
  an1 := (r ->> 'id')::uuid; c1 := r ->> 'caminho';
  PERFORM ci.exige(c1 LIKE demo::text || '/' || pet::text || '/' || an1::text || '.png', 'o caminho é empresa/paciente/id.extensão');
  PERFORM ci.exige((SELECT situacao = 'pendente' FROM pet_exame_anexos WHERE id = an1), 'o anexo nasce pendente');
  PERFORM ci.entrar(va);
  PERFORM ci.exige(jsonb_array_length(clinica_anexos(ex1, NULL)) = 0, 'anexo pendente não aparece na lista');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_confirmar(%L)$c$, an1), 'confirmar sem o arquivo enviado');

  -- envio: só no caminho reservado, só pelo veterinário que reservou
  PERFORM ci.deve_falhar(va, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":2048,"mimetype":"image/png"}')$c$, demo::text || '/' || pet::text || '/outro.png', va), 'upload em caminho que não foi reservado');
  PERFORM ci.deve_falhar(vb, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":2048,"mimetype":"image/png"}')$c$, c1, vb), 'upload de outro veterinário no caminho reservado');
  PERFORM ci.deve_falhar(gest, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":2048,"mimetype":"image/png"}')$c$, c1, gest), 'upload da gestão no caminho reservado');
  PERFORM ci.deve_falhar(vend, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":2048,"mimetype":"image/png"}')$c$, c1, vend), 'upload da recepção no caminho reservado');
  PERFORM ci.deve_falhar(va, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('outro-bucket', %L, %L, '{"size":2048,"mimetype":"image/png"}')$c$, c1, va), 'o caminho reservado não vale em outro bucket');
  PERFORM ci.entrar(va);
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":2048,"mimetype":"image/png"}')$c$, c1, va);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM storage.objects WHERE bucket_id = 'clinica-anexos' AND name = c1) = 1, 'o veterinário envia o arquivo no caminho reservado');

  -- confirmar: só quem reservou, e só se o arquivo confere
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_anexo_confirmar(%L)$c$, an1), 'outro veterinário confirma o anexo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_anexo_confirmar(%L)$c$, an1), 'gestor confirma o anexo');
  PERFORM ci.entrar(va);
  r := clinica_anexo_preparar(jsonb_build_object('exame_id', ex1, 'categoria', 'laudo', 'descricao', 'Laudo do ultrassom', 'nome_arquivo', 'laudo.pdf', 'mime', 'application/pdf', 'tamanho', 5000));
  PERFORM ci.sair();
  an2 := (r ->> 'id')::uuid; c2 := r ->> 'caminho';
  PERFORM ci.entrar(va);
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":9999,"mimetype":"application/pdf"}')$c$, c2, va);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_confirmar(%L)$c$, an2), 'confirmar arquivo com tamanho diferente do informado');
  PERFORM ci.entrar(va);
  PERFORM clinica_anexo_confirmar(an1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'ativo' AND confirmado_em IS NOT NULL FROM pet_exame_anexos WHERE id = an1), 'anexo confirmado fica ativo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_confirmar(%L)$c$, an1), 'confirmar duas vezes');

  -- lista: sem o caminho do arquivo; só veterinário; qualquer veterinário da clínica enxerga
  PERFORM ci.entrar(vb);
  r := clinica_anexos(ex1, NULL);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 ->> 'descricao' = 'Ultrassom abdominal' AND r -> 0 ->> 'crmv' = '8881' AND r -> 0 ->> 'categoria' = 'imagem', 'a lista traz o anexo ativo, de quem enviou');
  PERFORM ci.exige((r -> 0 ->> 'pode_cancelar')::boolean = false, 'outro veterinário não recebe a opção de cancelar o anexo');
  PERFORM ci.entrar(va);
  PERFORM ci.exige((clinica_anexos(ex1, NULL) -> 0 ->> 'pode_cancelar')::boolean = true, 'quem enviou recebe a opção de cancelar o anexo');
  PERFORM ci.sair();
  PERFORM ci.exige(r::text NOT LIKE '%caminho%' AND r::text NOT LIKE '%' || c1 || '%', 'a lista não traz o caminho do arquivo');

  -- ler o arquivo (gerar o link temporário): só logo depois de registrar a abertura
  PERFORM ci.exige(ci.contar(va, 'SELECT count(*) FROM storage.objects WHERE bucket_id = ''clinica-anexos''') = 0, 'sem abrir pela função, o veterinário não enxerga o arquivo');
  PERFORM ci.exige(ci.contar(gest, 'SELECT count(*) FROM storage.objects WHERE bucket_id = ''clinica-anexos''') = 0, 'a gestão não enxerga o arquivo');
  SELECT count(*) INTO n FROM clinica_acessos WHERE tenant_id = demo AND acao = 'anexo' AND anexo_id = an1;
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_anexo_abrir(%L)$c$, an1), 'gestor abre anexo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_anexo_abrir(%L)$c$, an1), 'recepção abre anexo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_abrir(%L)$c$, an2), 'abrir anexo que ainda é pendente');
  PERFORM ci.entrar(va);
  r := clinica_anexo_abrir(an1);
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'caminho' = c1 AND r ->> 'mime' = 'image/png' AND r ->> 'nome_arquivo' = 'ultra.png', 'abrir devolve o caminho para o link temporário');
  PERFORM ci.exige((SELECT count(*) FROM clinica_acessos WHERE tenant_id = demo AND acao = 'anexo' AND anexo_id = an1 AND profile_id = va) = n + 1, 'a abertura do anexo fica registrada com quem abriu');
  PERFORM ci.exige(ci.contar(va, 'SELECT count(*) FROM storage.objects WHERE bucket_id = ''clinica-anexos''') = 1, 'depois de abrir, o veterinário gera o link do arquivo aberto');
  PERFORM ci.exige(ci.contar(vb, 'SELECT count(*) FROM storage.objects WHERE bucket_id = ''clinica-anexos''') = 0, 'a abertura de um veterinário não libera o arquivo para outro');
  PERFORM ci.exige(ci.contar(gest, 'SELECT count(*) FROM storage.objects WHERE bucket_id = ''clinica-anexos''') = 0, 'a abertura do veterinário não libera para a gestão');
  UPDATE clinica_acessos SET created_at = now() - interval '3 minutes' WHERE acao = 'anexo' AND anexo_id = an1;
  PERFORM ci.exige(ci.contar(va, 'SELECT count(*) FROM storage.objects WHERE bucket_id = ''clinica-anexos''') = 0, 'a liberação do link vale por 2 minutos');

  -- o arquivo enviado não se troca nem se apaga
  PERFORM ci.entrar(va);
  PERFORM clinica_anexo_abrir(an1);
  UPDATE storage.objects SET name = name || 'x' WHERE bucket_id = 'clinica-anexos';
  DELETE FROM storage.objects WHERE bucket_id = 'clinica-anexos';
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM storage.objects WHERE bucket_id = 'clinica-anexos' AND name = c1) = 1, 'nem o veterinário altera ou apaga o arquivo no armazenamento');
  PERFORM ci.deve_falhar(va, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":2048,"mimetype":"image/png"}')$c$, c1, va), 'enviar de novo por cima do arquivo');

  -- cancelar: só quem enviou, com motivo; continua no registro
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_cancelar(%L, '   ')$c$, an1), 'cancelar anexo sem motivo');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_anexo_cancelar(%L, 'não é meu')$c$, an1), 'outro veterinário cancela o anexo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_anexo_cancelar(%L, 'gestor')$c$, an1), 'gestor cancela o anexo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_cancelar(%L, 'x')$c$, an2), 'cancelar anexo pendente');
  PERFORM ci.entrar(va);
  PERFORM clinica_anexo_cancelar(an1, 'Imagem do paciente errado');
  r := clinica_anexos(ex1, NULL);
  PERFORM ci.sair();
  PERFORM ci.exige(r -> 0 ->> 'situacao' = 'cancelado' AND r -> 0 ->> 'cancelado_motivo' = 'Imagem do paciente errado', 'anexo cancelado fica na lista com o motivo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_cancelar(%L, 'de novo')$c$, an1), 'cancelar duas vezes');
  PERFORM ci.exige((SELECT count(*) FROM storage.objects WHERE bucket_id = 'clinica-anexos' AND name = c1) = 1, 'o arquivo do anexo cancelado continua no armazenamento');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_exame_anexos WHERE id = %L$c$, an1), 'apagar anexo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exame_anexos SET descricao = 'outra' WHERE id = %L$c$, an1), 'mudar a descrição do anexo cancelado');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exame_anexos SET descricao = 'outra' WHERE id = %L$c$, an2), 'mudar a descrição de anexo pendente');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exame_anexos SET caminho = 'outro' WHERE id = %L$c$, an2), 'mudar o caminho do anexo');

  -- anexo do atendimento e de exame fechado
  PERFORM ci.entrar(va);
  PERFORM clinica_exame_salvar(ex1, jsonb_build_object('resultados', jsonb_build_array(jsonb_build_object('id', (SELECT (x ->> 'id')::uuid FROM jsonb_array_elements(clinica_exame_get(ex1) -> 'resultados') x WHERE x ->> 'nome' = 'Hemoglobina'), 'valor', '14'))));
  PERFORM clinica_exame_fechar(ex1);
  r := clinica_anexo_preparar(jsonb_build_object('atendimento_id', at1, 'categoria', 'laboratorial', 'descricao', 'Hemograma do laboratório', 'nome_arquivo', 'hemo.pdf', 'mime', 'application/pdf', 'tamanho', 7000));
  an3 := (r ->> 'id')::uuid; c3 := r ->> 'caminho';
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":7000,"mimetype":"application/pdf"}')$c$, c3, va);
  PERFORM clinica_anexo_confirmar(an3);
  r := clinica_anexo_preparar(jsonb_build_object('exame_id', ex1, 'categoria', 'laudo', 'descricao', 'Laudo depois de fechar', 'nome_arquivo', 'l.jpg', 'mime', 'image/jpeg', 'tamanho', 300));
  an4 := (r ->> 'id')::uuid; c4 := r ->> 'caminho';
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":300,"mimetype":"image/jpeg"}')$c$, c4, va);
  PERFORM clinica_anexo_confirmar(an4);
  PERFORM ci.exige(jsonb_array_length(clinica_anexos(NULL, at1)) = 1, 'o anexo do atendimento aparece na lista do atendimento');
  PERFORM ci.exige(jsonb_array_length(clinica_anexos(ex1, NULL)) = 2, 'exame fechado ainda recebe anexo (imagem cancelada e laudo novo)');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) FROM pet_exame_resultados WHERE exame_id = ex1 AND valor_num = 14) = 1, 'anexar não altera o resultado do exame fechado');
  PERFORM ci.deve_falhar(va, 'SELECT clinica_anexos(NULL, NULL)', 'lista sem exame nem atendimento');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexos(%L, %L)$c$, ex1, at1), 'lista com exame e atendimento juntos');

  -- limite de 20 anexos por exame
  PERFORM ci.entrar(va);
  FOR i IN 1..17 LOOP
    PERFORM clinica_anexo_preparar(jsonb_build_object('exame_id', ex1, 'categoria', 'laudo', 'descricao', 'Enchendo ' || i, 'nome_arquivo', 'e.pdf', 'mime', 'application/pdf', 'tamanho', 10));
  END LOOP;
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'Passou', 'nome_arquivo', 'e.pdf', 'mime', 'application/pdf', 'tamanho', 10))$c$, ex1), 'mais de 20 anexos no mesmo exame');
  -- pendentes de mais de uma hora não contam no limite (o teste envelhece os registros desligando a trava só nesta linha)
  ALTER TABLE pet_exame_anexos DISABLE TRIGGER trg_clinica_anexo_guarda;
  UPDATE pet_exame_anexos SET created_at = now() - interval '2 hours' WHERE exame_id = ex1 AND situacao = 'pendente' AND descricao LIKE 'Enchendo%';
  ALTER TABLE pet_exame_anexos ENABLE TRIGGER trg_clinica_anexo_guarda;
  PERFORM ci.entrar(va);
  PERFORM clinica_anexo_preparar(jsonb_build_object('exame_id', ex1, 'categoria', 'laudo', 'descricao', 'Cabe de novo', 'nome_arquivo', 'e.pdf', 'mime', 'application/pdf', 'tamanho', 10));
  PERFORM ci.sair();

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexos(%L, NULL)$c$, ex1), 'lista de anexos sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_abrir(%L)$c$, an3), 'abrir anexo sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_anexo_preparar(jsonb_build_object('exame_id', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'e.pdf', 'mime', 'application/pdf', 'tamanho', 10))$c$, ex1), 'preparar anexo sem a clínica liberada');
  PERFORM ci.exige(ci.contar(va, 'SELECT count(*) FROM storage.objects WHERE bucket_id = ''clinica-anexos''') = 0, 'sem a clínica liberada o veterinário não enxerga os arquivos');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 50. Clínica (preparar visita, trabalho sem internet): só o veterinário baixa a cópia, só da própria agenda, com auditoria
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  va   constant uuid := 'a0000000-0000-0000-0000-0000000000fa';
  vb   constant uuid := 'a0000000-0000-0000-0000-0000000000fb';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  t_hoje timestamptz := date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo' + interval '19 hours';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; p1 uuid; p2 uuid; p3 uuid; p4 uuid; cons uuid; pva uuid; pvb uuid; ag1 uuid; ag2 uuid; ag3 uuid; ag4 uuid; ag5 uuid; prod uuid; dep uuid; cat uuid;
  r jsonb; n bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone) VALUES (demo, 'Tutor Visita CI', '52998224725', '(16) 98888-7777') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (va, 'vetvisa@ci'), (vb, 'vetvisb@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (va, vb);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (va, demo, 'veterinario'), (vb, demo, 'veterinario');
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_lote) VALUES (demo, 'VIS-PROD-CI', 'Produto visita CI', 'UN', 0, true) RETURNING id INTO prod;
  SELECT id INTO dep FROM depositos WHERE tenant_id = demo ORDER BY created_at LIMIT 1;

  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Visita CI","categoria":"consulta","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 150);
  pva := pet_profissional_salvar('{"nome":"Vet A Visita","funcao":"veterinario","crmv":"9991","crmv_uf":"SP"}'::jsonb);
  pvb := pet_profissional_salvar('{"nome":"Vet B Visita","funcao":"veterinario","crmv":"9992","crmv_uf":"RJ"}'::jsonb);
  PERFORM pet_profissional_vincular(pva, va);
  PERFORM pet_profissional_vincular(pvb, vb);
  PERFORM clinica_exame_modelos_iniciais();
  cat := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'V10 Visita CI', 'especie', 'cao', 'doses_serie', 3, 'intervalo_serie_dias', 21, 'reforco_dias', 365, 'produto_id', prod));
  PERFORM clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'Item inativo Visita CI', 'reforco_dias', 30, 'produto_id', prod, 'ativo', false));
  PERFORM ci.sair();
  INSERT INTO estoque_lotes (tenant_id, produto_id, deposito_id, lote, validade, quantidade) VALUES (demo, prod, dep, 'LOTE-VIS-1', hoje + 200, 5), (demo, prod, dep, 'LOTE-VIS-VAZIO', hoje + 200, 0);

  PERFORM ci.entrar(vend);
  p1 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Rex Visita CI', 'especie', 'cao', 'alergias', 'dipirona'));
  p2 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Mimi Visita CI', 'especie', 'gato'));
  p3 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Outro Vet Visita CI', 'especie', 'cao'));
  p4 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Cancelado Visita CI', 'especie', 'cao'));
  ag1 := pet_agendar(jsonb_build_object('pet_id', p1, 'profissional_id', pva, 'inicio', t_hoje, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag2 := pet_agendar(jsonb_build_object('pet_id', p2, 'profissional_id', pva, 'inicio', t_hoje + interval '1 hour', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag3 := pet_agendar(jsonb_build_object('pet_id', p3, 'profissional_id', pvb, 'inicio', t_hoje, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag4 := pet_agendar(jsonb_build_object('pet_id', p4, 'profissional_id', pva, 'inicio', t_hoje + interval '2 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag5 := pet_agendar(jsonb_build_object('pet_id', p1, 'profissional_id', pva, 'inicio', t_hoje + interval '3 days', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  PERFORM pet_agenda_situacao(ag4, 'cancelado', 'tutor desistiu');
  PERFORM ci.sair();

  -- só o veterinário baixa a cópia
  PERFORM ci.deve_falhar(gest, 'SELECT clinica_visita_preparar()', 'gestor baixa a cópia da visita');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_visita_preparar()', 'recepção baixa a cópia da visita');
  PERFORM ci.deve_falhar(gar, 'SELECT clinica_visita_preparar()', 'garçom baixa a cópia da visita');
  PERFORM ci.deve_falhar(pban, 'SELECT clinica_visita_preparar()', 'profissional de banho baixa a cópia da visita');
  PERFORM ci.deve_falhar(va, 'SELECT clinica_visita_preparar(0)', 'zero dias de agenda');
  PERFORM ci.deve_falhar(va, 'SELECT clinica_visita_preparar(8)', 'mais de 7 dias de agenda');
  PERFORM ci.deve_falhar(va, 'SELECT clinica_visita_preparar(NULL)', 'dias em branco');

  SELECT count(*) INTO n FROM clinica_acessos WHERE tenant_id = demo AND acao = 'visita';
  PERFORM ci.entrar(va);
  r := clinica_visita_preparar();
  PERFORM ci.sair();
  PERFORM ci.exige(r -> 'veterinario' ->> 'crmv' = '9991' AND r -> 'veterinario' ->> 'nome' = 'Vet A Visita', 'a cópia traz o veterinário e o CRMV');
  PERFORM ci.exige(jsonb_array_length(r -> 'agenda') = 2 AND r -> 'agenda' -> 0 -> 'pet' ->> 'nome' = 'Rex Visita CI' AND r -> 'agenda' -> 1 -> 'pet' ->> 'nome' = 'Mimi Visita CI',
                   'a agenda de hoje traz só as consultas do veterinário, em ordem, sem cancelada e sem as de outro dia');
  PERFORM ci.exige(r -> 'agenda' -> 0 -> 'tutor' ->> 'telefone' = '(16) 98888-7777' AND r -> 'agenda' -> 0 -> 'pet' ->> 'alergias' = 'dipirona'
                   AND r -> 'agenda' -> 0 -> 'servicos' -> 0 ->> 'categoria' = 'consulta', 'a cópia traz tutor, telefone, alergia e serviço');
  PERFORM ci.exige(r::text NOT LIKE '%Outro Vet Visita CI%' AND r::text NOT LIKE '%Cancelado Visita CI%', 'a cópia não traz paciente de outro veterinário nem de consulta cancelada');
  PERFORM ci.exige(r::text NOT LIKE '%queixa%' AND r::text NOT LIKE '%diagnostico%', 'a cópia não traz texto de prontuário');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'catalogo_vacinas') i WHERE i ->> 'nome' = 'V10 Visita CI' AND jsonb_array_length(i -> 'lotes') = 1 AND i -> 'lotes' -> 0 ->> 'lote' = 'LOTE-VIS-1'),
                   'o catálogo traz os lotes com saldo (sem o lote zerado)');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'catalogo_vacinas') i WHERE i ->> 'nome' = 'Item inativo Visita CI'), 'item inativo do catálogo não vai na cópia');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'modelos_exame') m WHERE m ->> 'nome' = 'Hemograma' AND jsonb_array_length(m -> 'campos') = 26), 'a cópia traz os modelos de exame com os campos');
  PERFORM ci.exige(jsonb_array_length(r -> 'aplicadores') >= 2, 'a cópia traz os aplicadores');
  PERFORM ci.exige((SELECT count(*) FROM clinica_acessos WHERE tenant_id = demo AND acao = 'visita') = n + 2 AND (SELECT count(DISTINCT pet_id) FROM clinica_acessos WHERE tenant_id = demo AND acao = 'visita' AND profile_id = va AND pet_id IN (p1, p2)) = 2,
                   'baixar a cópia registra um acesso por paciente da agenda, com quem baixou');

  PERFORM ci.entrar(va);
  r := clinica_visita_preparar(7);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'agenda') = 3 AND r ->> 'ate' = (hoje + 6)::text, 'com 7 dias entra também a consulta de daqui a 3 dias');
  PERFORM ci.entrar(vb);
  r := clinica_visita_preparar();
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'agenda') = 1 AND r -> 'agenda' -> 0 -> 'pet' ->> 'nome' = 'Outro Vet Visita CI', 'cada veterinário baixa só a própria agenda');

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(va, 'SELECT clinica_visita_preparar()', 'preparar visita sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 51. Clínica (cadastro rápido, trabalho sem internet): só o veterinário; ids nascidos no notebook; reenvio não duplica; duplicado é marcado
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  novo constant uuid := 'a0000000-0000-0000-0000-000000000004';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  va   constant uuid := 'a0000000-0000-0000-0000-0000000000fc';
  ramo_ant text; cnae_ant text; cnae2_ant text; t_novo uuid; emp_novo uuid;
  k1 uuid := gen_random_uuid(); k2 uuid := gen_random_uuid(); k3 uuid := gen_random_uuid(); k4 uuid := gen_random_uuid();
  c1 uuid := gen_random_uuid(); p1 uuid := gen_random_uuid(); p2 uuid := gen_random_uuid(); c3 uuid := gen_random_uuid(); p3 uuid := gen_random_uuid();
  c4 uuid := gen_random_uuid(); p4 uuid := gen_random_uuid();
  existente uuid; r jsonb; r2 jsonb; n_cli bigint; n_pet bigint; n_reg bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO auth.users (id, email) VALUES (va, 'vetcad@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = va;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (va, demo, 'veterinario');
  INSERT INTO clientes (tenant_id, nome, telefone) VALUES (demo, 'Tutor Antigo Cadastro CI', '(16) 97777-6666') RETURNING id INTO existente;
  PERFORM ci.entrar(gest);
  PERFORM pet_profissional_vincular(pet_profissional_salvar('{"nome":"Vet Cadastro CI","funcao":"veterinario","crmv":"5551","crmv_uf":"SP"}'::jsonb), va);
  PERFORM ci.sair();

  -- só o veterinário usa o cadastro rápido
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_cadastro_rapido(%L, '{"cliente":{"id":"%s","nome":"X Y"},"pet":{"id":"%s","nome":"P"}}'::jsonb)$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'gestor usa o cadastro rápido da clínica');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_cadastro_rapido(%L, '{"cliente":{"id":"%s","nome":"X Y"},"pet":{"id":"%s","nome":"P"}}'::jsonb)$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'recepção usa o cadastro rápido da clínica');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_cadastro_rapido(%L, '{"cliente":{"id":"%s","nome":"X Y"},"pet":{"id":"%s","nome":"P"}}'::jsonb)$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'garçom usa o cadastro rápido da clínica');
  PERFORM ci.deve_falhar(pban, format($c$SELECT clinica_cadastro_rapido(%L, '{"cliente":{"id":"%s","nome":"X Y"},"pet":{"id":"%s","nome":"P"}}'::jsonb)$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'profissional de banho usa o cadastro rápido da clínica');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM clinica_cadastros_rapidos', 'leitura direta do registro dos cadastros rápidos');

  -- tutor e pet novos, com os ids nascidos no notebook
  PERFORM ci.entrar(va);
  r := clinica_cadastro_rapido(k1, jsonb_build_object('cliente', jsonb_build_object('id', c1, 'nome', 'Maria da Fazenda CI', 'telefone', '(16) 98888-1111'),
         'pet', jsonb_build_object('id', p1, 'nome', 'Toby Fazenda CI', 'especie', 'cao', 'raca', 'SRD', 'sexo', 'macho', 'porte', 'medio',
                                   'nascimento', '2023-03-10', 'peso_kg', '12,5', 'castrado', true, 'alergias', 'frango')));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'cliente_id' = c1::text AND r ->> 'pet_id' = p1::text AND (r ->> 'repetido')::boolean = false AND r -> 'possivel_duplicado_de' = 'null'::jsonb,
                   'o cadastro usa os ids do notebook e não tem duplicado');
  PERFORM ci.exige((SELECT nome = 'Maria da Fazenda CI' AND telefone = '(16) 98888-1111' AND whatsapp = '(16) 98888-1111' AND observacoes LIKE 'Cadastro rápido da clínica%' AND observacoes NOT LIKE '%duplicado%'
                      FROM clientes WHERE id = c1 AND tenant_id = demo), 'tutor criado com nome, telefone e a marca de cadastro rápido');
  PERFORM ci.exige((SELECT nome = 'Toby Fazenda CI' AND especie = 'cao' AND peso_kg = 12.5 AND castrado AND alergias = 'frango' AND cliente_id = c1 AND ativo
                      FROM pets WHERE id = p1 AND tenant_id = demo), 'pet criado com os dados e ligado ao tutor');
  PERFORM ci.exige(ci.contar(va, format($c$SELECT count(*) FROM jsonb_array_elements(clinica_pacientes('Toby Fazenda')) x WHERE x ->> 'id' = %L$c$, p1)) = 1, 'o pet novo aparece na busca de pacientes do veterinário');

  -- reenvio da mesma chave: devolve o mesmo e não duplica
  SELECT count(*) INTO n_cli FROM clientes WHERE tenant_id = demo;
  SELECT count(*) INTO n_pet FROM pets WHERE tenant_id = demo;
  SELECT count(*) INTO n_reg FROM clinica_cadastros_rapidos WHERE tenant_id = demo;
  PERFORM ci.entrar(va);
  r2 := clinica_cadastro_rapido(k1, jsonb_build_object('cliente', jsonb_build_object('id', c1, 'nome', 'Maria da Fazenda CI'), 'pet', jsonb_build_object('id', p1, 'nome', 'Toby Fazenda CI')));
  PERFORM ci.sair();
  PERFORM ci.exige(r2 ->> 'cliente_id' = c1::text AND r2 ->> 'pet_id' = p1::text AND (r2 ->> 'repetido')::boolean, 'reenviar a mesma chave devolve o mesmo resultado');
  PERFORM ci.exige((SELECT count(*) FROM clientes WHERE tenant_id = demo) = n_cli AND (SELECT count(*) FROM pets WHERE tenant_id = demo) = n_pet
               AND (SELECT count(*) FROM clinica_cadastros_rapidos WHERE tenant_id = demo) = n_reg, 'o reenvio não cria tutor, pet nem registro de novo');

  -- outro pet para o tutor que já existe
  PERFORM ci.entrar(va);
  r := clinica_cadastro_rapido(k2, jsonb_build_object('cliente_id', c1, 'pet', jsonb_build_object('id', p2, 'nome', 'Mimi Fazenda CI', 'especie', 'gato')));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'cliente_id' = c1::text AND (SELECT cliente_id = c1 AND especie = 'gato' FROM pets WHERE id = p2), 'segundo pet para o mesmo tutor');
  PERFORM ci.exige((SELECT count(*) FROM clientes WHERE tenant_id = demo) = n_cli, 'o segundo pet não cria outro tutor');

  -- mesmo telefone de um cadastro existente: cria e marca para a recepção unir
  PERFORM ci.entrar(va);
  r := clinica_cadastro_rapido(k3, jsonb_build_object('cliente', jsonb_build_object('id', c3, 'nome', 'Tutor Novo Mesmo Fone CI', 'telefone', '16 97777 6666'),
         'pet', jsonb_build_object('id', p3, 'nome', 'Bidu CI')));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'possivel_duplicado_de' = existente::text, 'o telefone igual aponta o cadastro existente');
  PERFORM ci.exige((SELECT observacoes LIKE '%Possível duplicado do cadastro "Tutor Antigo Cadastro CI"%' FROM clientes WHERE id = c3), 'a marca de duplicado fica nas observações do cadastro novo, para a recepção');
  PERFORM ci.exige((SELECT nome = 'Tutor Antigo Cadastro CI' AND observacoes IS NULL AND ativo FROM clientes WHERE id = existente), 'o cadastro antigo não é alterado');
  PERFORM ci.exige((SELECT possivel_duplicado_de = existente FROM clinica_cadastros_rapidos WHERE chave = k3), 'o registro guarda o possível duplicado');

  -- o mesmo telefone com o código do país (+55) também é duplicado, nos dois sentidos
  UPDATE clientes SET created_at = now() - interval '2 days' WHERE id = existente;  -- o cadastro antigo é o mais antigo de verdade (o teste roda numa transação só)
  PERFORM ci.entrar(va);
  r := clinica_cadastro_rapido(k4, jsonb_build_object('cliente', jsonb_build_object('id', c4, 'nome', 'Tutor Com Codigo Pais CI', 'telefone', '+55 (16) 97777-6666'),
         'pet', jsonb_build_object('id', p4, 'nome', 'Fido CI')));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'possivel_duplicado_de' = existente::text, 'telefone com +55 é reconhecido como o mesmo número');
  PERFORM ci.exige(public._fone_normalizado('+55 (16) 98888-1111') = '16988881111' AND public._fone_normalizado('(16) 98888-1111') = '16988881111'
               AND public._fone_normalizado('55 16 3333-4444') = '1633334444' AND public._fone_normalizado('5511') = '5511' AND public._fone_normalizado(NULL) = '',
               'a normalização tira só o 55 do país');
  UPDATE clientes SET telefone = '+55 16 95555-4444' WHERE id = existente;
  PERFORM ci.entrar(va);
  r := clinica_cadastro_rapido(gen_random_uuid(), jsonb_build_object('cliente', jsonb_build_object('id', gen_random_uuid(), 'nome', 'Tutor Sem Codigo Pais CI', 'telefone', '(16) 95555-4444'),
         'pet', jsonb_build_object('id', gen_random_uuid(), 'nome', 'Rex2 CI')));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'possivel_duplicado_de' = existente::text, 'cadastro antigo com +55 e telefone novo sem o código também casam');

  -- regras
  PERFORM ci.deve_falhar(va, 'SELECT clinica_cadastro_rapido(NULL, ''{}''::jsonb)', 'cadastro sem chave de repetição');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, '{"cliente":{"id":"%s","nome":"Fulano Tal"}}'::jsonb)$c$, gen_random_uuid(), gen_random_uuid()), 'cadastro sem pet');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Vaca', 'especie', 'outro')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'espécie fora de cão e gato');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', '  ')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'pet sem nome');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'F'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'tutor com nome curto demais');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal', 'telefone', '12345'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'telefone sem DDD');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex', 'peso_kg', '-3')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'peso negativo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex', 'sexo', 'indefinido')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'sexo inválido');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex', 'nascimento', current_date + 5)))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'nascimento no futuro');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex', 'castrado', 'talvez')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'castrado que não é sim ou não');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente_id', %L, 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid()), 'tutor que não existe');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente_id', %L, 'cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), c1, gen_random_uuid(), gen_random_uuid()), 'tutor existente e tutor novo ao mesmo tempo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), c1, gen_random_uuid()), 'identificador de tutor já usado por outra chave');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), gen_random_uuid(), p1), 'identificador de pet já usado por outra chave');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente', jsonb_build_object('id', %L, 'nome', 'Fulano Tal'), 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), 'não-é-uuid', gen_random_uuid()), 'identificador que não é UUID');
  PERFORM ci.exige((SELECT count(*) FROM clientes WHERE tenant_id = demo AND nome = 'Fulano Tal') = 0, 'cadastro recusado não deixa tutor para trás');

  -- outra empresa não usa tutor nem chave alheios
  SELECT tenant_id INTO t_novo FROM profiles WHERE id = novo;
  INSERT INTO empresas (tenant_id, razao_social, ramo_atividade) VALUES (t_novo, 'Outra clínica cadastro CI', 'clinica') RETURNING id INTO emp_novo;
  PERFORM ci.deve_falhar(novo, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente_id', %L, 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), c1, gen_random_uuid()), 'perfil sem veterinário em outra empresa');
  DELETE FROM empresas WHERE id = emp_novo;

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_cadastro_rapido(%L, jsonb_build_object('cliente_id', %L, 'pet', jsonb_build_object('id', %L, 'nome', 'Rex')))$c$, gen_random_uuid(), c1, gen_random_uuid()), 'cadastro rápido sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 52. Clínica (atendimento sem internet): visita avulsa e consulta marcada com o id do notebook; salvar e fechar aceitam repetição
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  pban constant uuid := 'a0000000-0000-0000-0000-0000000000e3';
  va   constant uuid := 'a0000000-0000-0000-0000-0000000000fd';
  vb   constant uuid := 'a0000000-0000-0000-0000-0000000000fe';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  t0 timestamptz := date_trunc('day', now()) + interval '20 days' + interval '9 hours';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet1 uuid; pet2 uuid; pet3 uuid; pet4 uuid; cons uuid; cons_sempreco uuid; banho uuid; pva uuid; pvb uuid;
  ag_cons uuid; ag_banho uuid; ag_canc uuid; ag_outro uuid; ag_novo uuid;
  k1 uuid := gen_random_uuid(); k2 uuid := gen_random_uuid(); k3 uuid := gen_random_uuid(); k4 uuid := gen_random_uuid();
  a1 uuid := gen_random_uuid(); a2 uuid := gen_random_uuid(); a3 uuid := gen_random_uuid();
  r jsonb; r2 jsonb; n bigint; agv uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Atendimento Offline CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (va, 'vetoffa@ci'), (vb, 'vetoffb@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (va, vb);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (va, demo, 'veterinario'), (vb, demo, 'veterinario');

  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Offline CI","categoria":"consulta","duracao_min":40}'::jsonb);
  cons_sempreco := pet_servico_salvar('{"nome":"Consulta Sem Preco Offline CI","categoria":"consulta","duracao_min":30}'::jsonb);
  banho := pet_servico_salvar('{"nome":"Banho Offline CI","categoria":"banho","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 150);
  PERFORM pet_preco_salvar(banho, NULL, NULL, NULL, 60);
  pva := pet_profissional_salvar('{"nome":"Vet A Offline","funcao":"veterinario","crmv":"6661","crmv_uf":"SP"}'::jsonb);
  pvb := pet_profissional_salvar('{"nome":"Vet B Offline","funcao":"veterinario","crmv":"6662","crmv_uf":"RJ"}'::jsonb);
  PERFORM pet_profissional_vincular(pva, va);
  PERFORM pet_profissional_vincular(pvb, vb);
  PERFORM ci.sair();

  PERFORM ci.entrar(vend);
  pet1 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Visita Avulsa CI', 'especie', 'cao'));
  pet2 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Consulta Marcada CI', 'especie', 'gato'));
  pet3 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Outro Vet Offline CI', 'especie', 'cao'));
  pet4 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Banho Offline CI', 'especie', 'cao'));
  ag_cons := pet_agendar(jsonb_build_object('pet_id', pet2, 'profissional_id', pva, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  ag_banho := pet_agendar(jsonb_build_object('pet_id', pet4, 'profissional_id', pva, 'inicio', t0 + interval '2 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', banho))));
  ag_canc := pet_agendar(jsonb_build_object('pet_id', pet1, 'profissional_id', pva, 'inicio', t0 + interval '4 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  PERFORM pet_agenda_situacao(ag_canc, 'cancelado', 'tutor desistiu');
  ag_outro := pet_agendar(jsonb_build_object('pet_id', pet3, 'profissional_id', pvb, 'inicio', t0 + interval '5 hours', 'servicos', jsonb_build_array(jsonb_build_object('servico_id', cons))));
  PERFORM ci.sair();

  -- só o veterinário usa as duas funções
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet1, cons), 'gestor registra visita');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet1, cons), 'recepção registra visita');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet1, cons), 'garçom registra visita');
  PERFORM ci.deve_falhar(pban, format($c$SELECT clinica_atendimento_offline(%L, 'salvar', %L, '{}'::jsonb)$c$, gen_random_uuid(), a1), 'profissional de banho preenche atendimento');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_atendimento_offline(%L, 'salvar', %L, '{}'::jsonb)$c$, gen_random_uuid(), a1), 'gestor preenche atendimento');

  -- a cópia da visita passa a levar os serviços de consulta
  PERFORM ci.entrar(va);
  r := clinica_visita_preparar();
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'servicos_consulta') x WHERE x ->> 'id' = cons::text AND x ->> 'nome' = 'Consulta Offline CI')
               AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'servicos_consulta') x WHERE x ->> 'id' = banho::text), 'a cópia da visita traz os serviços de consulta (e só eles)');

  -- visita avulsa: cria a consulta (já em atendimento) e o atendimento, com o id do notebook
  PERFORM ci.entrar(va);
  r := clinica_visita_registrar(k1, jsonb_build_object('atendimento_id', a1, 'pet_id', pet1, 'servico_id', cons, 'aberto_em', now() - interval '3 hours'));
  PERFORM ci.sair();
  agv := (r ->> 'agendamento_id')::uuid;
  PERFORM ci.exige(r ->> 'atendimento_id' = a1::text AND r ->> 'modo' = 'visita_avulsa' AND (r ->> 'repetido')::boolean = false, 'a visita avulsa usa o id do atendimento nascido no notebook');
  PERFORM ci.exige((SELECT situacao = 'em_atendimento' AND profissional_id = pva AND pet_id = pet1 AND fim - inicio = interval '40 minutes' AND observacoes LIKE 'Visita registrada pela clínica%'
                      FROM pet_agendamentos WHERE id = agv), 'a consulta da visita nasce em atendimento, com a duração do serviço');
  PERFORM ci.exige((SELECT preco_aplicado = 150 AND servico_id = cons FROM pet_agendamento_itens WHERE agendamento_id = agv), 'o preço da consulta fica congelado como a agenda calcularia');
  PERFORM ci.exige((SELECT veterinario_id = pva AND crmv = '6661' AND agendamento_id = agv AND situacao = 'aberto' AND aberto_em < now() - interval '2 hours' FROM pet_atendimentos_clinicos WHERE id = a1),
                   'o atendimento guarda o veterinário, o CRMV e a hora em que foi aberto no notebook');
  PERFORM ci.exige((SELECT count(*) FROM clinica_acessos WHERE atendimento_id = a1 AND acao = 'atendimento' AND profile_id = va) = 1, 'abrir a visita fica na auditoria');

  -- reenvio da mesma chave: devolve o mesmo e não duplica
  SELECT count(*) INTO n FROM pet_agendamentos WHERE tenant_id = demo;
  PERFORM ci.entrar(va);
  r2 := clinica_visita_registrar(k1, jsonb_build_object('atendimento_id', a1, 'pet_id', pet1, 'servico_id', cons));
  PERFORM ci.sair();
  PERFORM ci.exige(r2 ->> 'agendamento_id' = agv::text AND (r2 ->> 'repetido')::boolean, 'reenviar a mesma chave devolve a mesma visita');
  PERFORM ci.exige((SELECT count(*) FROM pet_agendamentos WHERE tenant_id = demo) = n AND (SELECT count(*) FROM pet_atendimentos_clinicos WHERE pet_id = pet1) = 1, 'o reenvio não cria consulta nem atendimento');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), a1, pet1, cons), 'identificador do atendimento já usado por outra chave');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, k1, gen_random_uuid(), pet1, cons), 'chave de repetição de outro veterinário');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_atendimento_offline(%L, 'fechar', %L)$c$, k1, a1), 'chave de uma operação usada em outro tipo');

  -- regras da visita avulsa
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet3, banho), 'serviço que não é de consulta');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet3, cons_sempreco), 'consulta sem preço cadastrado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L, 'aberto_em', now() + interval '1 hour'))$c$, gen_random_uuid(), gen_random_uuid(), pet3, cons), 'hora do atendimento no futuro');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L, 'aberto_em', now() - interval '40 days'))$c$, gen_random_uuid(), gen_random_uuid(), pet3, cons), 'hora do atendimento de mais de 30 dias atrás');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet3), 'sem consulta marcada nem serviço');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L, 'agendamento_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet2, cons, ag_cons), 'consulta marcada e serviço ao mesmo tempo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), cons), 'paciente que não existe');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', 'não-é-uuid', 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), pet3, cons), 'identificador que não é UUID');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(NULL, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), pet3, cons), 'visita sem chave de repetição');
  PERFORM ci.exige((SELECT count(*) FROM pet_agendamentos WHERE tenant_id = demo AND pet_id = pet3 AND observacoes LIKE 'Visita registrada%') = 0, 'visita recusada não deixa consulta para trás');

  -- a visita avulsa não passa pela regra de horário livre: o atendimento já aconteceu (o veterinário B já tem consulta a partir de t0 + 5h)
  PERFORM ci.entrar(vb);
  r := clinica_visita_registrar(gen_random_uuid(), jsonb_build_object('atendimento_id', gen_random_uuid(), 'pet_id', pet3, 'servico_id', cons, 'aberto_em', now() - interval '1 hour'));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'modo' = 'visita_avulsa', 'visita avulsa de quem já tem outra consulta marcada no mesmo período');

  -- consulta já marcada na agenda do veterinário abre com o id do notebook
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'agendamento_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet2, ag_cons), 'consulta marcada de outro veterinário');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'agendamento_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet2, ag_banho), 'agendamento sem serviço de consulta (ou de outro paciente)');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'agendamento_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet4, ag_banho), 'agendamento de banho');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'agendamento_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet1, ag_canc), 'consulta cancelada');
  PERFORM ci.entrar(va);
  r := clinica_visita_registrar(k2, jsonb_build_object('atendimento_id', a2, 'pet_id', pet2, 'agendamento_id', ag_cons));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'modo' = 'consulta_marcada' AND r ->> 'agendamento_id' = ag_cons::text, 'consulta marcada abre o atendimento com o id do notebook');
  PERFORM ci.exige((SELECT situacao = 'em_atendimento' FROM pet_agendamentos WHERE id = ag_cons), 'abrir começa a consulta marcada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'agendamento_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet2, ag_cons), 'consulta já aberta em outro aparelho');

  -- preencher e fechar, com chave de repetição
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_offline(%L, 'apagar', %L, '{}'::jsonb)$c$, gen_random_uuid(), a1), 'ação inválida');
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_atendimento_offline(%L, 'salvar', %L, '{"queixa":"x"}'::jsonb)$c$, gen_random_uuid(), a1), 'outro veterinário preenche o atendimento');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_offline(%L, 'salvar', %L, '{"queixa":"x","peso_kg":"500"}'::jsonb)$c$, gen_random_uuid(), a1), 'peso absurdo (a regra do prontuário vale também aqui)');
  PERFORM ci.entrar(va);
  r := clinica_atendimento_offline(k3, 'salvar', a1, '{"queixa":"Tosse há 3 dias","peso_kg":"12,5","temperatura_c":"38,6","conduta":"Repouso e hidratação"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'situacao' = 'aberto' AND (r ->> 'repetido')::boolean = false, 'preencher sem internet grava e segue aberto');
  PERFORM ci.exige((SELECT queixa = 'Tosse há 3 dias' AND peso_kg = 12.5 AND temperatura_c = 38.6 AND conduta = 'Repouso e hidratação' FROM pet_atendimentos_clinicos WHERE id = a1), 'o atendimento ficou com o que foi preenchido');
  PERFORM ci.entrar(va);
  r2 := clinica_atendimento_offline(k3, 'salvar', a1, '{"queixa":"OUTRA COISA"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r2 ->> 'repetido')::boolean AND (SELECT queixa = 'Tosse há 3 dias' FROM pet_atendimentos_clinicos WHERE id = a1), 'reenviar a mesma chave não regrava o atendimento');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_offline(%L, 'fechar', %L)$c$, gen_random_uuid(), a2), 'fechar atendimento sem queixa nem conduta');
  PERFORM ci.entrar(va);
  r := clinica_atendimento_offline(k4, 'fechar', a1);
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'situacao' = 'fechado' AND (SELECT situacao = 'fechado' FROM pet_atendimentos_clinicos WHERE id = a1) AND (SELECT situacao = 'pronto' FROM pet_agendamentos WHERE id = agv),
                   'fechar sem internet fecha o atendimento e leva a consulta para pronto (a recepção cobra)');
  PERFORM ci.entrar(va);
  r2 := clinica_atendimento_offline(k4, 'fechar', a1);
  PERFORM ci.sair();
  PERFORM ci.exige((r2 ->> 'repetido')::boolean AND r2 ->> 'situacao' = 'fechado', 'reenviar o fechamento devolve o mesmo resultado em vez de recusar');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_offline(%L, 'salvar', %L, '{"queixa":"depois de fechado"}'::jsonb)$c$, gen_random_uuid(), a1), 'preencher atendimento já fechado');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_offline(%L, 'fechar', %L)$c$, gen_random_uuid(), a1), 'fechar de novo com outra chave');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_atendimentos_clinicos SET queixa = 'x' WHERE id = %L$c$, a1), 'alterar atendimento fechado, nem o dono do banco');
  PERFORM ci.exige((SELECT queixa = 'Tosse há 3 dias' FROM pet_atendimentos_clinicos WHERE id = a1), 'o atendimento fechado continua o mesmo');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM clinica_operacoes_offline', 'leitura direta do registro das operações sem internet');

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_visita_registrar(%L, jsonb_build_object('atendimento_id', %L, 'pet_id', %L, 'servico_id', %L))$c$, gen_random_uuid(), gen_random_uuid(), pet3, cons), 'registrar visita sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_atendimento_offline(%L, 'salvar', %L, '{}'::jsonb)$c$, gen_random_uuid(), a2), 'preencher atendimento sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 53. Clínica (vacina e exame sem internet): aplicar com ou sem agendamento, vacina de outro local, lote que acabou, exame aberto no notebook
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vc   constant uuid := 'a0000000-0000-0000-0000-0000000000ff';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  t0 timestamptz := date_trunc('day', now()) + interval '22 days' + interval '9 hours';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet1 uuid; pet2 uuid; pet3 uuid; vacserv uuid; vacserv_sempreco uuid; pvc uuid; ag_vac uuid;
  prod uuid; dep uuid; l_a uuid; l_b uuid; cat uuid; m uuid; c_num uuid; c_txt uuid; atend uuid := gen_random_uuid();
  k uuid[] := ARRAY(SELECT gen_random_uuid() FROM generate_series(1, 14));
  r jsonb; r2 jsonb; n bigint; ex uuid; saldo0 numeric;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Vacina Offline CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (vc, 'vetvacoff@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = vc;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (vc, demo, 'veterinario');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Vacinas Offline CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_lote) VALUES (demo, 'VAC-OFF-CI', 'Vacina Offline CI', 'UN', 0, true) RETURNING id INTO prod;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 10, 'ci', 'ci');
  l_a := estoque_lote_lancar(prod, dep, 'OFF-A', '', '', 'entrada', 1, 'ci');
  l_b := estoque_lote_lancar(prod, dep, 'OFF-B', '', '', 'entrada', 5, 'ci');
  PERFORM ci.sair();
  UPDATE estoque_lotes SET validade = hoje + 90 WHERE id IN (l_a, l_b);

  PERFORM ci.entrar(gest);
  vacserv := pet_servico_salvar('{"nome":"Vacina Offline CI","categoria":"vacina","duracao_min":15}'::jsonb);
  vacserv_sempreco := pet_servico_salvar('{"nome":"Vacina Sem Preco Offline CI","categoria":"vacina","duracao_min":15}'::jsonb);
  PERFORM pet_preco_salvar(vacserv, NULL, NULL, NULL, 90);
  pvc := pet_profissional_salvar('{"nome":"Vet Vacina Offline","funcao":"veterinario","crmv":"7771","crmv_uf":"SP"}'::jsonb);
  PERFORM pet_profissional_vincular(pvc, vc);
  cat := clinica_vacina_catalogo_salvar(jsonb_build_object('nome', 'V10 Offline CI', 'tipo', 'vacina', 'especie', 'cao', 'doses_serie', 3, 'intervalo_serie_dias', 21, 'reforco_dias', 365, 'produto_id', prod));
  m := clinica_exame_modelo_salvar(jsonb_build_object('nome', 'Exame Offline CI', 'tipo', 'outro', 'material', 'Soro'));
  c_num := clinica_exame_campo_salvar(jsonb_build_object('modelo_id', m, 'nome', 'Glicose', 'unidade', 'mg/dL', 'forma', 'numero', 'casas', 1));
  c_txt := clinica_exame_campo_salvar(jsonb_build_object('modelo_id', m, 'nome', 'Observação do laudo', 'forma', 'texto'));
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  pet1 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Vacina Avulsa Offline CI', 'especie', 'cao'));
  pet2 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Vacina Agenda Offline CI', 'especie', 'cao'));
  pet3 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Exame Offline CI', 'especie', 'cao'));
  ag_vac := pet_agendar(jsonb_build_object('pet_id', pet2, 'profissional_id', pvc, 'inicio', t0, 'servicos', jsonb_build_array(jsonb_build_object('servico_id', vacserv))));
  PERFORM ci.sair();

  -- só o veterinário
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_vacina_offline(%L, 'aplicar', jsonb_build_object('agendamento_id', %L, 'catalogo_id', %L, 'estoque_lote_id', %L))$c$, gen_random_uuid(), ag_vac, cat, l_b), 'gestor aplica vacina sem internet');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_exame_offline(%L, 'abrir', jsonb_build_object('pet_id', %L, 'modelo_id', %L, 'laboratorio', 'Lab'))$c$, gen_random_uuid(), pet3, m), 'recepção abre exame sem internet');

  -- a cópia leva os serviços de vacina
  PERFORM ci.entrar(vc);
  r := clinica_visita_preparar();
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'servicos_vacina') x WHERE x ->> 'id' = vacserv::text), 'a cópia da visita traz os serviços de vacina');

  -- aplicar numa consulta de vacina da agenda
  PERFORM ci.entrar(vc);
  r := clinica_vacina_offline(k[1], 'aplicar', jsonb_build_object('agendamento_id', ag_vac, 'catalogo_id', cat, 'estoque_lote_id', l_b, 'aplicada_em', hoje));
  r2 := clinica_vacina_offline(k[1], 'aplicar', jsonb_build_object('agendamento_id', ag_vac, 'catalogo_id', cat, 'estoque_lote_id', l_b, 'aplicada_em', hoje));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'dose_tipo') = 'serie' AND (r ->> 'dose_numero')::int = 1 AND (r ->> 'repetido')::boolean = false, 'aplicar na agenda registra a primeira dose da série');
  PERFORM ci.exige((r2 ->> 'repetido')::boolean AND r2 ->> 'vacinacao_id' = r ->> 'vacinacao_id', 'reenviar a mesma chave devolve a mesma aplicação');
  PERFORM ci.exige((SELECT count(*) FROM pet_vacinacoes WHERE pet_id = pet2) = 1 AND (SELECT quantidade = 4 FROM estoque_lotes WHERE id = l_b), 'reenviar não aplica nem baixa de novo');

  -- sem agendamento: a função cria o atendimento de vacina, com o preço do serviço
  PERFORM ci.entrar(vc);
  r := clinica_vacina_offline(k[2], 'aplicar', jsonb_build_object('pet_id', pet1, 'servico_id', vacserv, 'catalogo_id', cat, 'estoque_lote_id', l_b, 'aplicada_em', hoje - 2));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT a.situacao = 'em_atendimento' AND a.profissional_id = pvc AND i.preco_aplicado = 90 AND i.servico_id = vacserv
                      FROM pet_agendamentos a JOIN pet_agendamento_itens i ON i.agendamento_id = a.id WHERE a.id = (r ->> 'agendamento_id')::uuid),
                   'aplicar sem agendamento cria o atendimento de vacina em andamento com o preço do serviço');
  PERFORM ci.exige((SELECT aplicada_em = hoje - 2 AND estoque_lote_id = l_b FROM pet_vacinacoes WHERE id = (r ->> 'vacinacao_id')::uuid), 'a aplicação guarda a data e o lote do notebook');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_vacina_offline(%L, 'aplicar', jsonb_build_object('pet_id', %L, 'servico_id', %L, 'catalogo_id', %L, 'estoque_lote_id', %L, 'aplicada_em', %L))$c$, gen_random_uuid(), pet1, vacserv_sempreco, cat, l_b, hoje), 'serviço de vacina sem preço');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_vacina_offline(%L, 'aplicar', jsonb_build_object('pet_id', %L, 'servico_id', %L, 'agendamento_id', %L, 'catalogo_id', %L, 'estoque_lote_id', %L))$c$, gen_random_uuid(), pet1, vacserv, ag_vac, cat, l_b), 'agendamento e serviço ao mesmo tempo');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_vacina_offline(%L, 'aplicar', jsonb_build_object('pet_id', %L, 'catalogo_id', %L, 'estoque_lote_id', %L))$c$, gen_random_uuid(), pet1, cat, l_b), 'sem agendamento nem serviço');
  PERFORM ci.exige((SELECT count(*) FROM pet_agendamentos WHERE pet_id = pet1) = 1, 'operação recusada não deixa atendimento para trás');

  -- lote que acabou: recusa sem gravar nada; a mesma chave serve depois com outro lote
  PERFORM ci.entrar(vc);
  r := clinica_vacina_offline(k[3], 'aplicar', jsonb_build_object('agendamento_id', ag_vac, 'catalogo_id', cat, 'estoque_lote_id', l_a, 'aplicada_em', hoje));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 0 FROM estoque_lotes WHERE id = l_a), 'o último frasco do lote foi usado');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_vacina_offline(%L, 'aplicar', jsonb_build_object('agendamento_id', %L, 'catalogo_id', %L, 'estoque_lote_id', %L, 'aplicada_em', %L))$c$, k[4], ag_vac, cat, l_a, hoje), 'lote que acabou antes do envio');
  SELECT count(*) INTO n FROM clinica_operacoes_offline WHERE chave = k[4];
  PERFORM ci.exige(n = 0, 'a recusa não grava a chave');
  PERFORM ci.entrar(vc);
  r := clinica_vacina_offline(k[4], 'aplicar', jsonb_build_object('agendamento_id', ag_vac, 'catalogo_id', cat, 'estoque_lote_id', l_b, 'aplicada_em', hoje));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean = false AND (SELECT estoque_lote_id = l_b FROM pet_vacinacoes WHERE id = (r ->> 'vacinacao_id')::uuid), 'reenviar com outro lote, pela mesma chave, aplica');

  -- outro local
  PERFORM ci.entrar(vc);
  r := clinica_vacina_offline(k[5], 'externa', jsonb_build_object('pet_id', pet3, 'catalogo_id', cat, 'aplicada_em', hoje - 30, 'informado_por', 'Carteira do tutor', 'lote', 'X1'));
  r2 := clinica_vacina_offline(k[5], 'externa', jsonb_build_object('pet_id', pet3, 'catalogo_id', cat, 'aplicada_em', hoje - 30, 'informado_por', 'Carteira do tutor'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT origem = 'outro_local' AND aplicada_em = hoje - 30 FROM pet_vacinacoes WHERE id = (r ->> 'vacinacao_id')::uuid) AND (r2 ->> 'repetido')::boolean, 'vacina de outro local entra uma vez só');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_vacina_offline(%L, 'externa', jsonb_build_object('pet_id', %L, 'catalogo_id', %L, 'aplicada_em', %L))$c$, gen_random_uuid(), pet3, cat, hoje - 3), 'vacina de outro local sem quem informou');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_vacina_offline(%L, 'aplicar', jsonb_build_object('agendamento_id', %L, 'catalogo_id', %L, 'estoque_lote_id', %L))$c$, k[5], ag_vac, cat, l_b), 'chave de outro tipo de operação');

  -- exame aberto no notebook: abrir, salvar pelo campo do modelo, fechar
  PERFORM ci.entrar(vc);
  r := clinica_exame_offline(k[6], 'abrir', jsonb_build_object('pet_id', pet3, 'modelo_id', m, 'laboratorio', 'Lab Offline', 'data_coleta', hoje - 1));
  r2 := clinica_exame_offline(k[6], 'abrir', jsonb_build_object('pet_id', pet3, 'modelo_id', m, 'laboratorio', 'Lab Offline', 'data_coleta', hoje - 1));
  PERFORM ci.sair();
  ex := (r ->> 'exame_id')::uuid;
  PERFORM ci.exige((r2 ->> 'repetido')::boolean AND (SELECT count(*) FROM pet_exames WHERE pet_id = pet3) = 1, 'reenviar a abertura não abre outro exame');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_exame_offline(%L, 'salvar', jsonb_build_object('abrir_chave', %L))$c$, gen_random_uuid(), gen_random_uuid()), 'salvar exame cuja abertura não chegou');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_exame_offline(%L, 'salvar', jsonb_build_object('abrir_chave', %L, 'resultados', jsonb_build_array(jsonb_build_object('campo_id', %L, 'valor', '90'))))$c$, gen_random_uuid(), k[6], gen_random_uuid()), 'campo que não é do exame');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_exame_offline(%L, 'fechar', jsonb_build_object('abrir_chave', %L))$c$, gen_random_uuid(), k[6]), 'fechar exame sem nenhum resultado');
  PERFORM ci.entrar(vc);
  r := clinica_exame_offline(k[7], 'salvar', jsonb_build_object('abrir_chave', k[6], 'observacoes', 'coletado em jejum',
         'resultados', jsonb_build_array(jsonb_build_object('campo_id', c_num, 'valor', '92,5'), jsonb_build_object('campo_id', c_txt, 'valor', 'normal', 'nota', 'sem hemólise'))));
  r2 := clinica_exame_offline(k[7], 'salvar', jsonb_build_object('abrir_chave', k[6], 'resultados', jsonb_build_array(jsonb_build_object('campo_id', c_num, 'valor', '1'))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT valor_num = 92.5 FROM pet_exame_resultados WHERE exame_id = ex AND campo_id = c_num)
               AND (SELECT valor_texto = 'normal' AND nota = 'sem hemólise' FROM pet_exame_resultados WHERE exame_id = ex AND campo_id = c_txt)
               AND (SELECT observacoes = 'coletado em jejum' FROM pet_exames WHERE id = ex), 'salvar grava os resultados pelo campo do modelo');
  PERFORM ci.exige((r2 ->> 'repetido')::boolean AND (SELECT valor_num = 92.5 FROM pet_exame_resultados WHERE exame_id = ex AND campo_id = c_num), 'reenviar o salvamento não regrava');
  PERFORM ci.entrar(vc);
  r := clinica_exame_offline(k[8], 'fechar', jsonb_build_object('abrir_chave', k[6]));
  r2 := clinica_exame_offline(k[8], 'fechar', jsonb_build_object('abrir_chave', k[6]));
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'situacao' = 'fechado' AND (r2 ->> 'repetido')::boolean AND r2 ->> 'situacao' = 'fechado', 'fechar o exame aceita repetição');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_exame_offline(%L, 'salvar', jsonb_build_object('abrir_chave', %L, 'resultados', jsonb_build_array(jsonb_build_object('campo_id', %L, 'valor', '5'))))$c$, gen_random_uuid(), k[6], c_num), 'salvar exame já fechado');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_exame_resultados SET valor_num = 1 WHERE exame_id = %L AND campo_id = %L$c$, ex, c_num), 'alterar resultado de exame fechado, nem o dono do banco');

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_vacina_offline(%L, 'externa', jsonb_build_object('pet_id', %L, 'catalogo_id', %L, 'aplicada_em', %L, 'informado_por', 'x'))$c$, gen_random_uuid(), pet3, cat, hoje - 40), 'vacina sem a clínica liberada');
  PERFORM ci.deve_falhar(vc, format($c$SELECT clinica_exame_offline(%L, 'abrir', jsonb_build_object('pet_id', %L, 'modelo_id', %L, 'laboratorio', 'L'))$c$, gen_random_uuid(), pet3, m), 'exame sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 54. Login por usuário: usuário único por empresa, formato, só o administrador troca, repetido em outra empresa vale
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  outro constant uuid := 'a0000000-0000-0000-0000-0000000000f0';
  tenant_x uuid;
  n bigint;
BEGIN
  INSERT INTO tenants (nome) VALUES ('Empresa X usuarios CI') RETURNING id INTO tenant_x;
  INSERT INTO auth.users (id, email) VALUES (outro, 'outro-usuario@ci');
  UPDATE profiles SET tenant_id = tenant_x WHERE id = outro;

  -- o administrador define; dois usuários da mesma empresa não repetem
  PERFORM ci.entrar(adm);
  UPDATE profiles SET usuario = 'maria.ci' WHERE id = vend;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT usuario = 'maria.ci' FROM profiles WHERE id = vend), 'o administrador define o usuário de acesso');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE profiles SET usuario = 'maria.ci' WHERE id = %L$c$, gest), 'mesmo usuário duas vezes na mesma empresa');

  -- formato: minúsculas, números, ponto, hífen e sublinhado, de 3 a 30
  PERFORM ci.deve_falhar(adm, format($c$UPDATE profiles SET usuario = 'Maria' WHERE id = %L$c$, gest), 'usuário com maiúscula');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE profiles SET usuario = 'ab' WHERE id = %L$c$, gest), 'usuário curto demais');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE profiles SET usuario = 'joao silva' WHERE id = %L$c$, gest), 'usuário com espaço');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE profiles SET usuario = %L WHERE id = %L$c$, repeat('a', 31), gest), 'usuário com mais de 30 letras');

  -- a própria pessoa não troca o usuário pelo perfil, mas segue mexendo no resto
  PERFORM ci.deve_falhar(vend, format($c$UPDATE profiles SET usuario = 'outro.nome' WHERE id = %L$c$, vend), 'o próprio usuário troca o seu usuário de acesso');
  PERFORM ci.entrar(vend);
  UPDATE profiles SET telefone = '11999990000' WHERE id = vend;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT usuario = 'maria.ci' AND telefone = '11999990000' FROM profiles WHERE id = vend), 'a pessoa ainda edita os próprios dados, sem mexer no usuário');

  -- outra empresa pode ter o mesmo usuário
  UPDATE profiles SET usuario = 'maria.ci' WHERE id = outro;
  SELECT count(*) INTO n FROM profiles WHERE usuario = 'maria.ci';
  PERFORM ci.exige(n = 2, 'o mesmo usuário vale em empresas diferentes');

  -- o e-mail é só contato: pode se repetir entre usuários da mesma empresa
  UPDATE profiles SET email = 'contato.repetido@ci' WHERE id IN (vend, gest);
  SELECT count(*) INTO n FROM profiles WHERE email = 'contato.repetido@ci';
  PERFORM ci.exige(n = 2, 'o e-mail de contato pode se repetir');
END $$;

-- 55. Locação (vistoria na devolução): dano sai da caução e a diferença vira conta a receber; equipamento com dano vai para manutenção
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cli uuid; eq_e uuid; loc5 uuid; eq_a uuid; eq_b uuid; eq_c uuid; eq_d uuid; loc1 uuid; loc2 uuid; loc3 uuid; loc4 uuid;
  r jsonb; n bigint;
BEGIN
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Vistoria CI', '52998224725') RETURNING id INTO cli;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria, valor_aquisicao) VALUES (demo, 'Betoneira Vistoria CI', 100, 4000) RETURNING id INTO eq_a;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria, valor_aquisicao) VALUES (demo, 'Andaime Vistoria CI', 50, 1000) RETURNING id INTO eq_b;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria, valor_aquisicao) VALUES (demo, 'Furadeira Vistoria CI', 30, 600) RETURNING id INTO eq_c;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria, valor_aquisicao) VALUES (demo, 'Serra Vistoria CI', 40, 800) RETURNING id INTO eq_d;

  -- locação 1: dois equipamentos, caução de 100; locação 2: perda total; locação 3: sem dano; locação 4: ainda reservada
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, caucao, situacao)
    VALUES (demo, cli, eq_a, current_date - 5, current_date - 5, 3, 150, 450, 450, 100, 'em_andamento') RETURNING id INTO loc1;
  INSERT INTO locacao_itens (tenant_id, locacao_id, equipamento_id, quantidade, dias, valor_diaria, total) VALUES (demo, loc1, eq_a, 1, 3, 100, 300), (demo, loc1, eq_b, 1, 3, 50, 150);
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, caucao, situacao)
    VALUES (demo, cli, eq_c, current_date - 2, current_date - 2, 2, 30, 60, 60, 500, 'em_andamento') RETURNING id INTO loc2;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, caucao, situacao)
    VALUES (demo, cli, eq_d, current_date - 1, current_date - 1, 1, 40, 40, 40, 0, 'em_andamento') RETURNING id INTO loc3;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, dias, valor_diaria, valor_total, valor_faturado, caucao, situacao)
    VALUES (demo, cli, eq_a, current_date + 5, 1, 100, 100, 100, 0, 'reservada') RETURNING id INTO loc4;

  -- perfis e regras de entrada
  PERFORM ci.deve_falhar(gar, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, '[]'::jsonb)$c$, loc1), 'perfil do salão devolve locação');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver(%L, current_date, NULL, 0)$c$, loc1), 'devolução antiga, sem vistoria, não é mais chamável');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, '[]'::jsonb)$c$, loc1), 'devolver sem vistoriar nenhum equipamento');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L)))$c$, loc1, eq_a), 'devolver sem vistoriar todos os equipamentos');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L), jsonb_build_object('equipamento_id', %L), jsonb_build_object('equipamento_id', %L)))$c$, loc1, eq_a, eq_b, eq_c), 'vistoriar equipamento que não é da locação');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L), jsonb_build_object('equipamento_id', %L), jsonb_build_object('equipamento_id', %L)))$c$, loc1, eq_a, eq_b, eq_b), 'vistoriar o mesmo equipamento duas vezes');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L, 'avarias', jsonb_build_array(jsonb_build_object('descricao', 'Cabo', 'valor', 'abc'))), jsonb_build_object('equipamento_id', %L)))$c$, loc1, eq_a, eq_b), 'valor da avaria que não é número');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L, 'avarias', jsonb_build_array(jsonb_build_object('descricao', '', 'valor', '10'))), jsonb_build_object('equipamento_id', %L)))$c$, loc1, eq_a, eq_b), 'avaria sem descrição');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L, 'avarias', jsonb_build_array(jsonb_build_object('descricao', 'Cabo', 'valor', '-5'))), jsonb_build_object('equipamento_id', %L)))$c$, loc1, eq_a, eq_b), 'avaria com valor negativo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date + 1, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L), jsonb_build_object('equipamento_id', %L)))$c$, loc1, eq_a, eq_b), 'devolução com data no futuro');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L)))$c$, loc4, eq_a), 'devolver locação que ainda não foi entregue');
  SELECT count(*) INTO n FROM locacao_vistorias WHERE locacao_id = loc1;
  PERFORM ci.exige(n = 0, 'devolução recusada não deixa vistoria para trás');
  PERFORM ci.exige((SELECT situacao = 'em_andamento' FROM locacoes WHERE id = loc1), 'devolução recusada mantém a locação em andamento');

  -- dano de 150 com caução de 100: abate a caução e cobra 50; só o equipamento danificado vai para manutenção
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(loc1, current_date, 'Devolvido com um cabo partido', jsonb_build_array(
         jsonb_build_object('equipamento_id', eq_a, 'observacoes', 'Cabo do motor partido',
                            'avarias', jsonb_build_array(jsonb_build_object('descricao', 'Cabo do motor', 'valor', '120,50'), jsonb_build_object('descricao', 'Pintura', 'valor', '29,50'))),
         jsonb_build_object('equipamento_id', eq_b)), current_date + 7);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'valor_avarias')::numeric = 150 AND (r ->> 'caucao_abatida')::numeric = 100 AND (r ->> 'a_cobrar')::numeric = 50 AND (r ->> 'caucao_a_devolver')::numeric = 0,
                   'dano maior que a caução: abate a caução toda e cobra a diferença');
  PERFORM ci.exige((SELECT valor = 50 AND cliente_id = cli AND vencimento = current_date + 7 FROM contas_receber WHERE id = (r ->> 'conta_receber_id')::uuid),
                   'a diferença vira conta a receber do cliente, com o vencimento escolhido');
  PERFORM ci.exige((SELECT situacao = 'devolvida' AND valor_avarias = 150 AND caucao_abatida = 100 AND vistoria_em IS NOT NULL AND avarias_conta_receber_id IS NOT NULL FROM locacoes WHERE id = loc1),
                   'a locação guarda o acerto da devolução');
  PERFORM ci.exige((SELECT situacao = 'manutencao' AND ativo FROM locacao_equipamentos WHERE id = eq_a), 'equipamento com dano vai para manutenção');
  PERFORM ci.exige((SELECT situacao = 'disponivel' FROM locacao_equipamentos WHERE id = eq_b), 'equipamento sem dano volta a ficar disponível');
  PERFORM ci.exige((SELECT count(*) = 2 AND sum(valor_avarias) = 150 FROM locacao_vistorias WHERE locacao_id = loc1), 'cada equipamento tem a sua vistoria');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, '[]'::jsonb)$c$, loc1), 'devolver de novo');

  -- a reserva futura de um equipamento que voltou danificado não sai para o cliente, nem pela função nem por ajuste direto
  UPDATE locacoes SET aprovada = true WHERE id = loc4;
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_entregar(%L)$c$, loc4), 'entregar reserva de equipamento em manutenção');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE locacoes SET situacao = 'em_andamento' WHERE id = %L$c$, loc4), 'pôr em andamento locação de equipamento em manutenção, nem o dono do banco');
  PERFORM ci.exige((SELECT situacao = 'reservada' FROM locacoes WHERE id = loc4), 'a reserva do equipamento danificado segue parada');

  -- perda total com caução maior que o dano: não cobra e devolve o resto; o equipamento sai de uso
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(loc2, current_date, NULL, jsonb_build_array(
         jsonb_build_object('equipamento_id', eq_c, 'avarias', jsonb_build_array(jsonb_build_object('descricao', 'Furadeira perdida', 'valor', '300', 'perda_total', true)))));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'a_cobrar')::numeric = 0 AND (r ->> 'caucao_abatida')::numeric = 300 AND (r ->> 'caucao_a_devolver')::numeric = 200 AND r ->> 'conta_receber_id' IS NULL,
                   'dano menor que a caução: não cobra e mostra o resto a devolver');
  PERFORM ci.exige((SELECT NOT ativo AND situacao = 'manutencao' FROM locacao_equipamentos WHERE id = eq_c), 'perda total tira o equipamento de uso');

  -- caução negativa conta como zero: devolução sem dano não vira cobrança
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria, valor_aquisicao) VALUES (demo, 'Esmerilhadeira Vistoria CI', 20, 300) RETURNING id INTO eq_e;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, caucao, situacao)
    VALUES (demo, cli, eq_e, current_date - 1, current_date - 1, 1, 20, 20, 20, -100, 'em_andamento') RETURNING id INTO loc5;
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(loc5, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', eq_e)));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'a_cobrar')::numeric = 0 AND (r ->> 'caucao_abatida')::numeric = 0 AND (r ->> 'caucao_a_devolver')::numeric = 0 AND r ->> 'conta_receber_id' IS NULL,
                   'caução negativa conta como zero e não gera cobrança');

  -- sem dano: nada a cobrar e o equipamento volta a ficar disponível
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(loc3, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', eq_d)));
  PERFORM ci.exige((SELECT situacao = 'disponivel' FROM locacao_equipamentos WHERE id = eq_d), 'equipamento devolvido sem dano volta a ficar disponível');
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'valor_avarias')::numeric = 0 AND r ->> 'conta_receber_id' IS NULL AND (SELECT situacao = 'sem_avarias' FROM locacao_vistorias WHERE locacao_id = loc3), 'vistoria sem dano não cobra nada');

  -- a vistoria registrada não muda nem some, e não se grava à mão
  PERFORM ci.deve_falhar_dono(format($c$UPDATE locacao_vistorias SET valor_avarias = 0 WHERE locacao_id = %L$c$, loc1), 'alterar vistoria registrada, nem o dono do banco');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM locacao_vistoria_avarias WHERE vistoria_id IN (SELECT id FROM locacao_vistorias WHERE locacao_id = %L)$c$, loc1), 'apagar avaria registrada, nem o dono do banco');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO locacao_vistorias (locacao_id, equipamento_id, situacao) VALUES (%L, %L, 'sem_avarias')$c$, loc4, eq_a), 'gravar vistoria direto na tabela');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM locacao_vistorias') >= 4, 'a empresa lê as vistorias dela');
END $$;

-- 56. Locação (plano de manutenção): dias locados acumulados, aviso e bloqueio ao vencer, registro recomeça a contagem
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  cli uuid; eq1 uuid; eq2 uuid; eq3 uuid; plano uuid; plano2 uuid; plano3 uuid; locb uuid; loca uuid; locc uuid; locd uuid;
  r jsonb; s jsonb; n bigint;
BEGIN
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Manutencao CI', '52998224725') RETURNING id INTO cli;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria) VALUES (demo, 'Compactador Manut CI', 100) RETURNING id INTO eq1;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria, situacao) VALUES (demo, 'Gerador Manut CI', 100, 'manutencao') RETURNING id INTO eq2;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria, situacao, ativo) VALUES (demo, 'Perdido Manut CI', 100, 'manutencao', false) RETURNING id INTO eq3;

  -- perfil do salão não mexe
  PERFORM ci.deve_falhar(gar, format($c$SELECT locacao_plano_salvar(jsonb_build_object('equipamento_id', %L, 'nome', 'Troca de óleo', 'intervalo_dias', 10))$c$, eq1), 'perfil do salão cria plano de manutenção');
  PERFORM ci.deve_falhar(gar, 'SELECT locacao_manutencao_situacao()', 'perfil do salão vê a situação dos planos');
  PERFORM ci.deve_falhar(gar, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'descricao', 'Revisão'))$c$, eq1), 'perfil do salão registra manutenção');

  -- regras do plano
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_plano_salvar(jsonb_build_object('equipamento_id', %L, 'nome', 'X', 'intervalo_dias', 10))$c$, eq1), 'plano com nome curto demais');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_plano_salvar(jsonb_build_object('equipamento_id', %L, 'nome', 'Troca de óleo', 'intervalo_dias', 0))$c$, eq1), 'plano com intervalo zero');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_plano_salvar(jsonb_build_object('equipamento_id', %L, 'nome', 'Troca de óleo', 'intervalo_dias', 4000))$c$, eq1), 'plano com intervalo acima de 3650');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_plano_salvar(jsonb_build_object('equipamento_id', %L, 'nome', 'Troca de óleo', 'intervalo_dias', 10, 'referencia_em', current_date + 1))$c$, eq1), 'última manutenção no futuro');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_plano_salvar(jsonb_build_object('equipamento_id', %L, 'nome', 'Troca de óleo', 'intervalo_dias', 10))$c$, gen_random_uuid()), 'plano de equipamento que não existe');

  PERFORM ci.entrar(adm);
  plano := locacao_plano_salvar(jsonb_build_object('equipamento_id', eq1, 'nome', 'Troca de óleo', 'intervalo_dias', 12, 'referencia_em', current_date - 30));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_plano_salvar(jsonb_build_object('equipamento_id', %L, 'nome', ' troca de ÓLEO ', 'intervalo_dias', 5))$c$, eq1), 'dois planos ativos com o mesmo nome no equipamento');

  -- sem locação nenhuma: em dia
  PERFORM ci.entrar(adm);
  s := locacao_manutencao_situacao(eq1);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(s) = 1 AND (s -> 0 ->> 'dias')::int = 0 AND s -> 0 ->> 'situacao' = 'em_dia' AND (s -> 0 ->> 'restantes')::int = 12, 'sem locação, o plano está em dia e com o intervalo todo pela frente');

  -- locação que começou antes da última manutenção só conta os dias depois dela (5); a seguinte conta inteira (6): 11 de 12 = próxima
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, devolvido_em, dias, valor_diaria, valor_total, situacao)
    VALUES (demo, cli, eq1, current_date - 35, current_date - 35, current_date - 25, 10, 100, 1000, 'devolvida') RETURNING id INTO locb;
  PERFORM ci.entrar(adm);
  s := locacao_manutencao_situacao(eq1);
  PERFORM ci.sair();
  PERFORM ci.exige((s -> 0 ->> 'dias')::int = 5 AND s -> 0 ->> 'situacao' = 'em_dia', 'locação que começou antes da última manutenção conta só os dias depois dela');
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, devolvido_em, dias, valor_diaria, valor_total, situacao)
    VALUES (demo, cli, eq1, current_date - 20, current_date - 20, current_date - 14, 6, 100, 600, 'devolvida') RETURNING id INTO loca;
  PERFORM ci.entrar(adm);
  s := locacao_manutencao_situacao(eq1);
  PERFORM ci.sair();
  PERFORM ci.exige((s -> 0 ->> 'dias')::int = 11 AND (s -> 0 ->> 'restantes')::int = 1 AND s -> 0 ->> 'situacao' = 'proxima', 'faltando 20% ou menos do intervalo, o plano avisa (próxima)');

  -- a locação em andamento conta até hoje e vence o plano
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, situacao)
    VALUES (demo, cli, eq1, current_date - 2, current_date - 2, 5, 100, 500, 'em_andamento') RETURNING id INTO locc;
  PERFORM ci.entrar(adm);
  s := locacao_manutencao_situacao(eq1);
  PERFORM ci.sair();
  PERFORM ci.exige((s -> 0 ->> 'dias')::int = 13 AND s -> 0 ->> 'situacao' = 'vencida', 'a locação em andamento conta os dias até hoje e vence o plano');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM locacao_planos_manutencao') >= 1, 'a empresa lê os planos dela');

  -- vencido: não sai para um novo cliente (nem pela função, nem por ajuste direto)
  UPDATE locacoes SET situacao = 'devolvida', devolvido_em = current_date WHERE id = locc;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, dias, valor_diaria, valor_total, situacao, aprovada)
    VALUES (demo, cli, eq1, current_date, 1, 100, 100, 'reservada', true) RETURNING id INTO locd;
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_entregar(%L)$c$, locd), 'entregar equipamento com manutenção vencida');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE locacoes SET situacao = 'em_andamento' WHERE id = %L$c$, locd), 'pôr em andamento equipamento com manutenção vencida, nem o dono do banco');

  -- registrar a manutenção: validações
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'plano_id', %L, 'descricao', ''))$c$, eq1, plano), 'manutenção sem descrição');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'plano_id', %L, 'descricao', 'Troca de óleo', 'realizada_em', current_date + 1))$c$, eq1, plano), 'manutenção no futuro');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'plano_id', %L, 'descricao', 'Troca de óleo', 'realizada_em', current_date - 40))$c$, eq1, plano), 'manutenção anterior à última do plano');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'plano_id', %L, 'descricao', 'Troca de óleo', 'custo', 'abc'))$c$, eq1, plano), 'custo que não é número');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'plano_id', %L, 'descricao', 'Troca de óleo', 'custo', '-1'))$c$, eq1, plano), 'custo negativo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'plano_id', %L, 'descricao', 'Troca de óleo', 'tipo', 'qualquer'))$c$, eq1, plano), 'tipo de manutenção inválido');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'plano_id', %L, 'descricao', 'Troca de óleo'))$c$, eq2, plano), 'plano de outro equipamento');

  -- registro recomeça a contagem, soma o custo e libera a entrega
  PERFORM ci.entrar(adm);
  r := locacao_manutencao_registrar(jsonb_build_object('equipamento_id', eq1, 'plano_id', plano, 'descricao', 'Troca de óleo e filtro', 'custo', '150,50', 'responsavel', 'Oficina CI'));
  s := locacao_manutencao_situacao(eq1);
  PERFORM ci.sair();
  PERFORM ci.exige((s -> 0 ->> 'dias')::int = 0 AND s -> 0 ->> 'situacao' = 'em_dia' AND (s -> 0 ->> 'restantes')::int = 12, 'registrar a manutenção recomeça a contagem do plano');
  PERFORM ci.exige((SELECT referencia_em = current_date FROM locacao_planos_manutencao WHERE id = plano), 'o plano passa a contar da data da manutenção');
  PERFORM ci.exige((SELECT custo_manutencao = 150.5 FROM locacao_equipamentos WHERE id = eq1), 'o custo da manutenção soma ao do equipamento');
  PERFORM ci.exige((SELECT tipo = 'preventiva' AND plano_id = plano AND responsavel = 'Oficina CI' FROM locacao_manutencoes WHERE id = (r ->> 'manutencao_id')::uuid), 'a manutenção fica registrada como preventiva do plano');
  PERFORM ci.entrar(adm);
  PERFORM locacao_entregar(locd);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'em_andamento' FROM locacoes WHERE id = locd), 'depois da manutenção o equipamento volta a poder ser entregue');
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_manutencao_registrar(jsonb_build_object('equipamento_id', %L, 'descricao', 'Revisão'))$c$, eq1), 'registrar manutenção de equipamento locado');

  -- reparo de avaria libera o equipamento; equipamento fora de uso não volta
  PERFORM ci.entrar(adm);
  r := locacao_manutencao_registrar(jsonb_build_object('equipamento_id', eq2, 'tipo', 'corretiva', 'descricao', 'Troca do cabo', 'custo', '80'));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'liberado')::boolean AND (SELECT situacao = 'disponivel' FROM locacao_equipamentos WHERE id = eq2), 'reparo de avaria tira o equipamento de manutenção');
  PERFORM ci.entrar(adm);
  r := locacao_manutencao_registrar(jsonb_build_object('equipamento_id', eq3, 'tipo', 'corretiva', 'descricao', 'Tentativa de reparo'));
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'liberado')::boolean AND (SELECT situacao = 'manutencao' AND NOT ativo FROM locacao_equipamentos WHERE id = eq3), 'equipamento fora de uso não volta para a locação');

  -- registro de manutenção não muda nem some, e não se grava à mão
  PERFORM ci.deve_falhar_dono(format($c$UPDATE locacao_manutencoes SET custo = 0 WHERE equipamento_id = %L$c$, eq1), 'alterar manutenção registrada, nem o dono do banco');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM locacao_manutencoes WHERE equipamento_id = %L$c$, eq1), 'apagar manutenção registrada, nem o dono do banco');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO locacao_manutencoes (equipamento_id, tipo, realizada_em, descricao) VALUES (%L, 'preventiva', current_date, 'Direto')$c$, eq1), 'gravar manutenção direto na tabela');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO locacao_planos_manutencao (equipamento_id, nome, intervalo_dias) VALUES (%L, 'Direto', 5)$c$, eq1), 'gravar plano direto na tabela');

  -- reparo de defeito ligado a um plano não recomeça a contagem dele (só a preventiva recomeça)
  UPDATE locacoes SET situacao = 'devolvida', devolvido_em = current_date WHERE id = locd;
  PERFORM ci.entrar(adm);
  plano3 := locacao_plano_salvar(jsonb_build_object('equipamento_id', eq1, 'nome', 'Revisão do motor', 'intervalo_dias', 1, 'referencia_em', current_date - 30));
  PERFORM locacao_manutencao_registrar(jsonb_build_object('equipamento_id', eq1, 'plano_id', plano3, 'tipo', 'corretiva', 'descricao', 'Conserto do cabo'));
  s := locacao_manutencao_situacao(eq1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT referencia_em = current_date - 30 FROM locacao_planos_manutencao WHERE id = plano3)
               AND EXISTS (SELECT 1 FROM jsonb_array_elements(s) x WHERE x ->> 'plano_id' = plano3::text AND x ->> 'situacao' = 'vencida'), 'reparo corretivo não recomeça a contagem do plano (só a preventiva)');

  -- plano desativado sai da conta e do bloqueio
  PERFORM ci.entrar(adm);
  plano2 := locacao_plano_salvar(jsonb_build_object('id', plano, 'nome', 'Troca de óleo', 'intervalo_dias', 1, 'ativo', false));
  s := locacao_manutencao_situacao(eq1);
  PERFORM ci.sair();
  PERFORM ci.exige(plano2 = plano AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(s) x WHERE x ->> 'plano_id' = plano::text), 'plano desativado deixa de aparecer e de bloquear');
END $$;

-- 57. Locação (cobrança na devolução): locação não cobrada gera as contas pelo valor final; já cobrada e atrasada gera só os dias a mais
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  cli uuid; f1 uuid; f2 uuid; f3 uuid; f4 uuid; f5 uuid; l1 uuid; l2 uuid; l3 uuid; l4 uuid; l5 uuid;
  n1 integer; n2 integer; n3 integer; n4 integer; n5 integer; r jsonb;
BEGIN
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Cobranca Devolucao CI', '52998224725') RETURNING id INTO cli;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria) VALUES (demo, 'Cobranca 1 CI', 100) RETURNING id INTO f1;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria) VALUES (demo, 'Cobranca 2 CI', 100) RETURNING id INTO f2;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria) VALUES (demo, 'Cobranca 3 CI', 100) RETURNING id INTO f3;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria) VALUES (demo, 'Cobranca 4 CI', 100) RETURNING id INTO f4;
  INSERT INTO locacao_equipamentos (tenant_id, nome, valor_diaria) VALUES (demo, 'Cobranca 5 CI', 0) RETURNING id INTO f5;

  -- l1: não cobrada, no prazo; l2: não cobrada, atrasada; l3: cobrada e atrasada; l4: cobrada e no prazo; l5: sem valor
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, situacao)
    VALUES (demo, cli, f1, current_date - 3, current_date - 3, 3, 100, 300, 0, 'em_andamento') RETURNING id INTO l1;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, situacao)
    VALUES (demo, cli, f2, current_date - 5, current_date - 5, 2, 100, 200, 0, 'em_andamento') RETURNING id INTO l2;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, situacao)
    VALUES (demo, cli, f3, current_date - 5, current_date - 5, 2, 100, 200, 200, 'em_andamento') RETURNING id INTO l3;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, situacao)
    VALUES (demo, cli, f4, current_date - 2, current_date - 2, 2, 100, 200, 200, 'em_andamento') RETURNING id INTO l4;
  INSERT INTO locacoes (tenant_id, cliente_id, equipamento_id, inicio, entregue_em, dias, valor_diaria, valor_total, valor_faturado, situacao)
    VALUES (demo, cli, f5, current_date - 1, current_date - 1, 1, 0, 0, 0, 'em_andamento') RETURNING id INTO l5;

  -- locação ainda não cobrada exige a forma de pagamento na devolução, e a recusa não deixa nada para trás
  PERFORM ci.deve_falhar(adm, format($c$SELECT locacao_devolver_vistoriada(%L, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', %L)))$c$, l1, f1), 'devolver locação não cobrada sem informar a forma de pagamento');
  PERFORM ci.exige((SELECT situacao = 'em_andamento' FROM locacoes WHERE id = l1) AND NOT EXISTS (SELECT 1 FROM locacao_vistorias WHERE locacao_id = l1), 'devolução recusada pela cobrança não deixa vistoria nem encerra a locação');

  -- l1: gera as contas pelo valor final (2 parcelas de 150)
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(l1, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', f1)), current_date + 5, 'boleto'::forma_pagamento, 2);
  PERFORM ci.sair();
  SELECT count(*) INTO n1 FROM contas_receber WHERE cliente_id = cli AND descricao LIKE 'Locação nº ' || (SELECT numero FROM locacoes WHERE id = l1) || ' %';
  PERFORM ci.exige(n1 = 2 AND (SELECT sum(valor) = 300 FROM contas_receber WHERE cliente_id = cli AND descricao LIKE 'Locação nº ' || (SELECT numero FROM locacoes WHERE id = l1) || ' %'), 'devolver locação não cobrada gera as contas a receber pelo valor final');
  PERFORM ci.exige((SELECT valor_faturado = 300 AND situacao = 'devolvida' FROM locacoes WHERE id = l1) AND r ->> 'locacao_conta_receber_id' IS NOT NULL AND r ->> 'extras_conta_receber_id' IS NULL, 'a locação fica faturada e devolvida');
  PERFORM ci.exige((SELECT vencimento = current_date + 5 FROM contas_receber WHERE id = (r ->> 'locacao_conta_receber_id')::uuid), 'a primeira conta vence na data escolhida');

  -- l2: atrasada e não cobrada: cobra tudo pelos dias reais (5 x 100)
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(l2, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', f2)), current_date, 'boleto'::forma_pagamento, 1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT sum(valor) = 500 FROM contas_receber WHERE cliente_id = cli AND descricao LIKE 'Locação nº ' || (SELECT numero FROM locacoes WHERE id = l2) || ' %')
               AND (SELECT valor_faturado = 500 FROM locacoes WHERE id = l2) AND r ->> 'extras_conta_receber_id' IS NULL, 'locação atrasada e não cobrada é cobrada pelos dias reais, numa conta só');

  -- l3: já cobrada e atrasada: gera só os dias a mais (3 x 100)
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(l3, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', f3)), current_date + 3);
  PERFORM ci.sair();
  SELECT count(*) INTO n3 FROM contas_receber WHERE cliente_id = cli AND descricao = 'Dias a mais da locação nº ' || (SELECT numero FROM locacoes WHERE id = l3);
  PERFORM ci.exige(n3 = 1 AND (SELECT valor = 300 AND vencimento = current_date + 3 FROM contas_receber WHERE id = (r ->> 'extras_conta_receber_id')::uuid), 'locação já cobrada e atrasada gera uma conta só com os dias a mais');
  PERFORM ci.exige((SELECT valor_faturado = 500 FROM locacoes WHERE id = l3) AND r ->> 'locacao_conta_receber_id' IS NULL, 'o faturado sobe pelos dias a mais e a locação não é cobrada de novo');

  -- l4: já cobrada e no prazo: nada de novo
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(l4, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', f4)));
  PERFORM ci.sair();
  SELECT count(*) INTO n4 FROM contas_receber WHERE cliente_id = cli AND descricao LIKE '%locação nº ' || (SELECT numero FROM locacoes WHERE id = l4);
  PERFORM ci.exige(n4 = 0 AND r ->> 'extras_conta_receber_id' IS NULL AND r ->> 'locacao_conta_receber_id' IS NULL AND (SELECT valor_faturado = 200 FROM locacoes WHERE id = l4), 'locação já cobrada e devolvida no prazo não gera conta nova');

  -- l5: sem valor: devolve sem exigir cobrança
  PERFORM ci.entrar(adm);
  r := locacao_devolver_vistoriada(l5, current_date, NULL, jsonb_build_array(jsonb_build_object('equipamento_id', f5)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'devolvida' FROM locacoes WHERE id = l5) AND r ->> 'locacao_conta_receber_id' IS NULL, 'locação sem valor devolve sem cobrança');
END $$;

-- 58. Clínica (anexo sem internet): reserva pela chave da operação, sem repetir; aponta para o exame aberto no notebook; reserva velha é refeita
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  vx   constant uuid := 'a0000000-0000-0000-0000-0000000000e0';
  vy   constant uuid := 'a0000000-0000-0000-0000-0000000000e4';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet uuid; modelo uuid; campo uuid; pvx uuid; pvy uuid; atend uuid := gen_random_uuid(); cons uuid;
  ka uuid := gen_random_uuid(); kb uuid := gen_random_uuid(); kc uuid := gen_random_uuid(); kd uuid := gen_random_uuid(); ke uuid := gen_random_uuid();
  kf uuid := gen_random_uuid(); kex uuid := gen_random_uuid(); kreg uuid := gen_random_uuid();
  r jsonb; r2 jsonb; an uuid; an2 uuid; ex uuid; n bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Anexo Offline CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (vx, 'vetanexooff@ci'), (vy, 'vetanexooffb@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (vx, vy);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (vx, demo, 'veterinario'), (vy, demo, 'veterinario');
  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Anexo Offline CI","categoria":"consulta","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 100);
  pvx := pet_profissional_salvar('{"nome":"Vet X Anexo","funcao":"veterinario","crmv":"8881","crmv_uf":"SP"}'::jsonb);
  pvy := pet_profissional_salvar('{"nome":"Vet Y Anexo","funcao":"veterinario","crmv":"8882","crmv_uf":"RJ"}'::jsonb);
  PERFORM pet_profissional_vincular(pvx, vx);
  PERFORM pet_profissional_vincular(pvy, vy);
  modelo := clinica_exame_modelo_salvar(jsonb_build_object('nome', 'Exame Anexo Offline CI', 'tipo', 'outro'));
  campo := clinica_exame_campo_salvar(jsonb_build_object('modelo_id', modelo, 'nome', 'Valor', 'forma', 'numero'));
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Paciente Anexo Offline CI', 'especie', 'cao'));
  PERFORM ci.sair();

  -- só o veterinário
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('atendimento_id', %L, 'categoria', 'imagem', 'descricao', 'x', 'nome_arquivo', 'x.png', 'mime', 'image/png', 'tamanho', 100))$c$, gen_random_uuid(), atend), 'gestor reserva anexo sem internet');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('atendimento_id', %L, 'categoria', 'imagem', 'descricao', 'x', 'nome_arquivo', 'x.png', 'mime', 'image/png', 'tamanho', 100))$c$, gen_random_uuid(), atend), 'recepção reserva anexo sem internet');

  -- o atendimento nasce no notebook; o anexo aponta para o id dele
  PERFORM ci.entrar(vx);
  PERFORM clinica_visita_registrar(kreg, jsonb_build_object('atendimento_id', atend, 'pet_id', pet, 'servico_id', cons));
  r := clinica_anexo_offline_preparar(ka, jsonb_build_object('atendimento_id', atend, 'categoria', 'imagem', 'descricao', 'Raio-x do tórax', 'nome_arquivo', 'rx.png', 'mime', 'image/png', 'tamanho', 4096));
  r2 := clinica_anexo_offline_preparar(ka, jsonb_build_object('atendimento_id', atend, 'categoria', 'imagem', 'descricao', 'Raio-x do tórax', 'nome_arquivo', 'rx.png', 'mime', 'image/png', 'tamanho', 4096));
  PERFORM ci.sair();
  an := (r ->> 'anexo_id')::uuid;
  PERFORM ci.exige((r ->> 'situacao') = 'pendente' AND NOT (r ->> 'repetido')::boolean AND (SELECT atendimento_id = atend AND situacao = 'pendente' AND tamanho = 4096 FROM pet_exame_anexos WHERE id = an), 'a reserva do anexo aponta para o atendimento nascido no notebook');
  PERFORM ci.exige((r2 ->> 'repetido')::boolean AND r2 ->> 'anexo_id' = r ->> 'anexo_id' AND r2 ->> 'caminho' = r ->> 'caminho' AND (SELECT count(*) = 1 FROM pet_exame_anexos WHERE atendimento_id = atend), 'reenviar a mesma chave devolve a mesma reserva, sem criar outra');

  -- depois do envio e da confirmação, repetir a operação só avisa que o anexo já vale
  PERFORM ci.entrar(vx);
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":4096,"mimetype":"image/png"}')$c$, r ->> 'caminho', vx);
  PERFORM clinica_anexo_confirmar(an);
  r2 := clinica_anexo_offline_preparar(ka, jsonb_build_object('atendimento_id', atend, 'categoria', 'imagem', 'descricao', 'Raio-x do tórax', 'nome_arquivo', 'rx.png', 'mime', 'image/png', 'tamanho', 4096));
  PERFORM ci.sair();
  PERFORM ci.exige((r2 ->> 'situacao') = 'ativo' AND (r2 ->> 'repetido')::boolean AND (SELECT count(*) = 1 FROM pet_exame_anexos WHERE atendimento_id = atend), 'anexo já confirmado: repetir a operação não reserva outro');

  -- chave de outro veterinário ou de outro tipo de operação é recusada
  PERFORM ci.deve_falhar(vy, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('atendimento_id', %L, 'categoria', 'imagem', 'descricao', 'x', 'nome_arquivo', 'x.png', 'mime', 'image/png', 'tamanho', 100))$c$, ka, atend), 'chave de reserva de outro veterinário');
  PERFORM ci.deve_falhar(vx, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('atendimento_id', %L, 'categoria', 'imagem', 'descricao', 'x', 'nome_arquivo', 'x.png', 'mime', 'image/png', 'tamanho', 100))$c$, kreg, atend), 'chave de outro tipo de operação');

  -- regras do anexo normal continuam valendo (a reserva falha inteira e a chave fica livre)
  PERFORM ci.deve_falhar(vx, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('atendimento_id', %L, 'categoria', 'imagem', 'descricao', 'x', 'nome_arquivo', 'x.zip', 'mime', 'application/zip', 'tamanho', 100))$c$, kb, atend), 'formato que não é JPEG, PNG nem PDF');
  PERFORM ci.deve_falhar(vx, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('atendimento_id', %L, 'categoria', 'imagem', 'descricao', 'x', 'nome_arquivo', 'x.png', 'mime', 'image/png', 'tamanho', 15728641))$c$, kb, atend), 'arquivo acima de 15 MB');
  SELECT count(*) INTO n FROM clinica_operacoes_offline WHERE chave = kb;
  PERFORM ci.exige(n = 0, 'reserva recusada não grava a chave');
  PERFORM ci.deve_falhar(vx, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('exame_abrir_chave', %L, 'categoria', 'laudo', 'descricao', 'x', 'nome_arquivo', 'x.pdf', 'mime', 'application/pdf', 'tamanho', 100))$c$, kc, gen_random_uuid()), 'anexo de exame cuja abertura não chegou ao servidor');

  -- exame aberto no notebook: o anexo aponta para a chave da abertura
  PERFORM ci.entrar(vx);
  r := clinica_exame_offline(kex, 'abrir', jsonb_build_object('pet_id', pet, 'modelo_id', modelo, 'atendimento_id', atend));
  ex := (r ->> 'exame_id')::uuid;
  r := clinica_anexo_offline_preparar(kd, jsonb_build_object('exame_abrir_chave', kex, 'categoria', 'laboratorial', 'descricao', 'Hemograma do laboratório', 'nome_arquivo', 'hemo.pdf', 'mime', 'application/pdf', 'tamanho', 8000));
  PERFORM ci.sair();
  an2 := (r ->> 'anexo_id')::uuid;
  PERFORM ci.exige((SELECT exame_id = ex AND atendimento_id IS NULL AND categoria = 'laboratorial' FROM pet_exame_anexos WHERE id = an2), 'o anexo do exame aberto no notebook aponta para o exame criado pela chave da abertura');

  -- reserva de mais de 50 minutos sem envio é refeita (o armazenamento só aceita o envio na primeira hora); a chave guarda a mais nova
  ALTER TABLE pet_exame_anexos DISABLE TRIGGER trg_clinica_anexo_guarda;
  UPDATE pet_exame_anexos SET created_at = now() - interval '2 hours' WHERE id = an2;
  ALTER TABLE pet_exame_anexos ENABLE TRIGGER trg_clinica_anexo_guarda;
  PERFORM ci.entrar(vx);
  r2 := clinica_anexo_offline_preparar(kd, jsonb_build_object('exame_abrir_chave', kex, 'categoria', 'laboratorial', 'descricao', 'Hemograma do laboratório', 'nome_arquivo', 'hemo.pdf', 'mime', 'application/pdf', 'tamanho', 8000));
  PERFORM ci.sair();
  PERFORM ci.exige((r2 ->> 'anexo_id') <> (r ->> 'anexo_id') AND NOT (r2 ->> 'repetido')::boolean AND (SELECT (resultado ->> 'anexo_id') = r2 ->> 'anexo_id' FROM clinica_operacoes_offline WHERE chave = kd),
                   'reserva antiga sem envio é refeita e a chave passa a apontar para a nova');

  -- reserva velha cujo arquivo já chegou ao armazenamento (só a confirmação se perdeu): continua a mesma, não se refaz
  ALTER TABLE pet_exame_anexos DISABLE TRIGGER trg_clinica_anexo_guarda;
  UPDATE pet_exame_anexos SET created_at = now() - interval '2 hours' WHERE id = (r2 ->> 'anexo_id')::uuid;
  ALTER TABLE pet_exame_anexos ENABLE TRIGGER trg_clinica_anexo_guarda;
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('clinica-anexos', %L, %L, '{"size":8000,"mimetype":"application/pdf"}')$c$, r2 ->> 'caminho', vx);
  PERFORM ci.entrar(vx);
  r := clinica_anexo_offline_preparar(kd, jsonb_build_object('exame_abrir_chave', kex, 'categoria', 'laboratorial', 'descricao', 'Hemograma do laboratório', 'nome_arquivo', 'hemo.pdf', 'mime', 'application/pdf', 'tamanho', 8000));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'anexo_id') = (r2 ->> 'anexo_id') AND (r ->> 'repetido')::boolean AND (r ->> 'caminho') = (r2 ->> 'caminho'),
                   'reserva velha com o arquivo já no armazenamento é reaproveitada para só confirmar');

  -- clínica deixa de estar liberada
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vx, format($c$SELECT clinica_anexo_offline_preparar(%L, jsonb_build_object('atendimento_id', %L, 'categoria', 'imagem', 'descricao', 'x', 'nome_arquivo', 'x.png', 'mime', 'image/png', 'tamanho', 100))$c$, ke, atend), 'anexo sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 59. Clínica (Prontuário): serviços de consulta para iniciar atendimento sem consulta marcada; só o veterinário, só com a clínica liberada
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  vz   constant uuid := 'a0000000-0000-0000-0000-0000000000e5';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet uuid; cons uuid; pvz uuid; atend uuid := gen_random_uuid(); chave uuid := gen_random_uuid();
  r jsonb; lista jsonb;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Iniciar Atendimento CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO auth.users (id, email) VALUES (vz, 'vetiniciar@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = vz;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (vz, demo, 'veterinario');
  PERFORM ci.entrar(gest);
  cons := pet_servico_salvar('{"nome":"Consulta Iniciar CI","categoria":"consulta","duracao_min":30}'::jsonb);
  PERFORM pet_preco_salvar(cons, NULL, NULL, NULL, 120);
  pvz := pet_profissional_salvar('{"nome":"Vet Z Iniciar","funcao":"veterinario","crmv":"8883","crmv_uf":"SP"}'::jsonb);
  PERFORM pet_profissional_vincular(pvz, vz);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Paciente Iniciar CI', 'especie', 'gato'));
  PERFORM ci.sair();

  PERFORM ci.entrar(vz);
  lista := clinica_servicos_consulta();
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(lista) x WHERE x ->> 'id' = cons::text AND (x ->> 'duracao_min')::int = 30), 'o veterinário lista o serviço de consulta ativo');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(lista) x WHERE x ->> 'id' IN (SELECT id::text FROM pet_servicos WHERE categoria <> 'consulta')), 'só serviços de consulta');
  PERFORM ci.entrar(vz);
  PERFORM ci.exige(clinica_meu_veterinario() = pvz, 'o veterinário recebe o próprio cadastro profissional');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, 'SELECT clinica_meu_veterinario()', 'gestor pede o cadastro de veterinário');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_meu_veterinario()', 'recepção pede o cadastro de veterinário');
  PERFORM ci.deve_falhar(gest, 'SELECT clinica_servicos_consulta()', 'gestor lista os serviços de consulta da clínica');
  PERFORM ci.deve_falhar(vend, 'SELECT clinica_servicos_consulta()', 'recepção lista os serviços de consulta da clínica');

  -- iniciar o atendimento no Prontuário é a mesma visita avulsa do trabalho sem internet; repetir a chave não duplica
  PERFORM ci.entrar(vz);
  r := clinica_visita_registrar(chave, jsonb_build_object('atendimento_id', atend, 'pet_id', pet, 'servico_id', cons, 'aberto_em', now()));
  PERFORM ci.exige(r ->> 'modo' = 'visita_avulsa' AND NOT (r ->> 'repetido')::boolean, 'atendimento iniciado sem consulta marcada');
  r := clinica_visita_registrar(chave, jsonb_build_object('atendimento_id', atend, 'pet_id', pet, 'servico_id', cons, 'aberto_em', now()));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) FROM pet_atendimentos_clinicos WHERE pet_id = pet) = 1, 'repetir o início do atendimento não cria outro');

  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vz, 'SELECT clinica_servicos_consulta()', 'serviços de consulta sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 60. Assinante: link de acesso combinado no cadastro vale para a empresa (já existente ou futura) e acompanha a mudança feita na empresa
DO $$
DECLARE
  t1 uuid; t2 uuid; c1 uuid; c2 uuid; e1 uuid; e2 uuid;
BEGIN
  INSERT INTO tenants (nome) VALUES ('Assinante Link CI 1') RETURNING id INTO t1;
  INSERT INTO tenants (nome) VALUES ('Assinante Link CI 2') RETURNING id INTO t2;
  INSERT INTO saas_clientes (nome, link_acesso, tenant_id) VALUES ('Assinante Link 1', ' Loja-Link-CI ', t1) RETURNING id INTO c1;
  PERFORM ci.exige((SELECT link_acesso FROM saas_clientes WHERE id = c1) = 'loja-link-ci', 'o link é gravado em minúsculas e sem espaços');

  -- empresa criada depois nasce com o link do assinante
  INSERT INTO empresas (tenant_id, razao_social) VALUES (t1, 'Loja Link 1') RETURNING id INTO e1;
  PERFORM ci.exige((SELECT slug FROM empresas WHERE id = e1) = 'loja-link-ci', 'a empresa nova usa o link combinado no cadastro');

  -- mudar o link no cadastro muda a empresa existente
  UPDATE saas_clientes SET link_acesso = 'loja-link-novo' WHERE id = c1;
  PERFORM ci.exige((SELECT slug FROM empresas WHERE id = e1) = 'loja-link-novo', 'mudar o link no cadastro muda o da empresa');

  -- mudar o link na empresa muda o cadastro do assinante
  UPDATE empresas SET slug = 'loja-link-admin' WHERE id = e1;
  PERFORM ci.exige((SELECT link_acesso FROM saas_clientes WHERE id = c1) = 'loja-link-admin', 'o link mudado pelo administrador volta para o cadastro');

  -- outro assinante não pode repetir o link nem usar o de uma empresa
  INSERT INTO saas_clientes (nome, tenant_id) VALUES ('Assinante Link 2', t2) RETURNING id INTO c2;
  PERFORM ci.deve_falhar_dono(format($c$UPDATE saas_clientes SET link_acesso = 'loja-link-admin' WHERE id = %L$c$, c2), 'link de outra empresa');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE saas_clientes SET link_acesso = 'admin' WHERE id = %L$c$, c2), 'link reservado pelo sistema');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE saas_clientes SET link_acesso = '-loja-x' WHERE id = %L$c$, c2), 'link com hífen na ponta');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE saas_clientes SET link_acesso = 'ab' WHERE id = %L$c$, c2), 'link curto demais');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE saas_clientes SET link_acesso = 'Com Espaço' WHERE id = %L$c$, c2), 'link com espaço');

  -- limpa o link: a empresa fica sem link
  UPDATE saas_clientes SET link_acesso = NULL WHERE id = c1;
  PERFORM ci.exige((SELECT slug FROM empresas WHERE id = e1) IS NULL, 'sem link no cadastro, a empresa fica sem link');

  -- assinante antigo (empresa com link, cadastro sem): editar outro dado, com o campo do link igual, não apaga o link da empresa
  ALTER TABLE empresas DISABLE TRIGGER trg_empresas_link_para_assinante;
  UPDATE empresas SET slug = 'link-legado-ci' WHERE id = e1;
  ALTER TABLE empresas ENABLE TRIGGER trg_empresas_link_para_assinante;
  UPDATE saas_clientes SET nome = 'Assinante Link 1 editado', link_acesso = NULL WHERE id = c1;
  PERFORM ci.exige((SELECT slug FROM empresas WHERE id = e1) = 'link-legado-ci', 'editar o assinante sem mexer no link não apaga o link da empresa');

  DELETE FROM empresas WHERE id = e1;
  DELETE FROM saas_clientes WHERE id IN (c1, c2);
  DELETE FROM tenants WHERE id IN (t1, t2);
END $$;

-- 61. Link do assinante abre a tela de login antes de a empresa existir; a empresa tem prioridade; cancelado não abre
DO $$
DECLARE t uuid; c uuid; e uuid; r record;
BEGIN
  INSERT INTO tenants (nome) VALUES ('Assinante Link Login CI') RETURNING id INTO t;
  INSERT INTO saas_clientes (nome, link_acesso, tenant_id) VALUES ('Loja Sem Empresa CI', 'loja-sem-empresa-ci', t) RETURNING id INTO c;
  SELECT * INTO r FROM empresa_por_slug('Loja-Sem-Empresa-CI');
  PERFORM ci.exige(r.nome = 'Loja Sem Empresa CI', 'o link do assinante abre o login antes de a empresa ser cadastrada');
  INSERT INTO empresas (tenant_id, razao_social, nome_fantasia) VALUES (t, 'Razão Loja CI', 'Fantasia Loja CI') RETURNING id INTO e;
  SELECT * INTO r FROM empresa_por_slug('loja-sem-empresa-ci');
  PERFORM ci.exige(r.nome = 'Fantasia Loja CI', 'com a empresa cadastrada, a marca da empresa tem prioridade');
  -- outra empresa não toma o link reservado no cadastro deste assinante
  PERFORM ci.deve_falhar_dono(format($c$UPDATE empresas SET slug = 'loja-sem-empresa-ci' WHERE tenant_id = '11111111-1111-1111-1111-111111111111'$c$), 'empresa de outro tenant toma o link reservado do assinante');
  DELETE FROM empresas WHERE id = e;
  UPDATE saas_clientes SET situacao = 'cancelado' WHERE id = c;
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM empresa_por_slug('loja-sem-empresa-ci')), 'assinante cancelado não abre a tela de login');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM empresa_por_slug('link-que-nao-existe-ci')), 'link inexistente não abre');
  DELETE FROM saas_clientes WHERE id = c;
  DELETE FROM tenants WHERE id = t;
END $$;

-- 62. Link sugerido no primeiro acesso: só o do próprio tenant
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  c uuid; v text;
BEGIN
  INSERT INTO saas_clientes (nome, link_acesso, tenant_id) VALUES ('Assinante Sugestão CI', 'sugestao-link-ci', demo) RETURNING id INTO c;
  PERFORM ci.entrar(gest);
  v := assinante_link_sugerido();
  PERFORM ci.sair();
  PERFORM ci.exige(v = 'sugestao-link-ci', 'o administrador vê o link combinado para o próprio tenant');
  DELETE FROM saas_clientes WHERE id = c;
  PERFORM ci.entrar(gest);
  v := assinante_link_sugerido();
  PERFORM ci.sair();
  PERFORM ci.exige(v IS NULL OR v <> 'sugestao-link-ci', 'sem assinante ligado ao tenant não há sugestão');
END $$;

-- 63. Estoque: o lançamento de lote grava e corrige a validade; sem validade informada, a do lote não muda
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  prod uuid; dep uuid; l1 uuid; l2 uuid;
BEGIN
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Validade de lote CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_lote) VALUES (demo, 'VAL-LOTE-CI', 'Produto validade CI', 'UN', 0, true) RETURNING id INTO prod;
  PERFORM ci.entrar(adm);
  l1 := estoque_lote_lancar(prod, dep, 'V1', '', '', 'entrada', 5, 'ci', NULL, hoje + 200);
  l2 := estoque_lote_lancar(prod, dep, 'V2', '', '', 'entrada', 2, 'ci');
  PERFORM ci.exige((SELECT validade FROM estoque_lotes WHERE id = l1) = hoje + 200, 'o lançamento grava a validade do lote');
  PERFORM ci.exige((SELECT validade FROM estoque_lotes WHERE id = l2) IS NULL, 'sem validade informada, o lote fica sem validade');
  PERFORM estoque_lote_lancar(prod, dep, 'V1', '', '', 'entrada', 1, 'ci');
  PERFORM ci.exige((SELECT validade FROM estoque_lotes WHERE id = l1) = hoje + 200, 'um lançamento sem validade não apaga a validade do lote');
  PERFORM estoque_lote_lancar(prod, dep, 'V2', '', '', 'entrada', 1, 'ci', NULL, hoje + 90);
  PERFORM ci.exige((SELECT validade FROM estoque_lotes WHERE id = l2) = hoje + 90, 'informar a validade corrige um lote que estava sem ela');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT estoque_lote_lancar(%L, %L, 'V3', '', '', 'entrada', 1, 'ci', NULL, DATE '1990-01-01')$c$, prod, dep), 'validade absurda');
  PERFORM ci.deve_falhar(vend, format($c$SELECT estoque_lote_lancar(%L, %L, 'V4', '', '', 'entrada', 1, 'ci', NULL, CURRENT_DATE + 30)$c$, prod, dep), 'vendedor lança lote');
END $$;

-- 64. Mensagens ao tutor: confirmar agenda e pet pronto, WhatsApp do tutor, quem não quer mensagens, modelos da empresa
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  tutor uuid; p_agenda uuid; p_pronto uuid; prof uuid; r jsonb; ref date;
BEGIN
  INSERT INTO clientes (tenant_id, nome, telefone, whatsapp) VALUES (demo, 'Tutor Mensagem CI', '(16) 3333-4444', '(16) 99888-7777') RETURNING id INTO tutor;
  PERFORM ci.entrar(adm);
  prof := pet_profissional_salvar('{"nome":"Dani Mensagem"}'::jsonb);
  p_agenda := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Msg Agendado'));
  p_pronto := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Msg Pronto'));
  PERFORM ci.sair();
  INSERT INTO pet_agendamentos (tenant_id, pet_id, cliente_id, profissional_id, inicio, fim, situacao)
  VALUES (demo, p_agenda, tutor, prof, (date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 day 10 hours') AT TIME ZONE 'America/Sao_Paulo',
          (date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 day 10 hours 30 minutes') AT TIME ZONE 'America/Sao_Paulo', 'agendado'),
         (demo, p_agenda, tutor, prof, (date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 day 15 hours') AT TIME ZONE 'America/Sao_Paulo',
          (date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 day 15 hours 30 minutes') AT TIME ZONE 'America/Sao_Paulo', 'agendado'),
         (demo, p_pronto, tutor, prof, now() - interval '1 hour', now() - interval '30 minutes', 'pronto');

  PERFORM ci.deve_falhar(gar, $c$SELECT pet_mensagens_pendentes('confirmacao')$c$, 'garçom vê avisos');
  PERFORM ci.deve_falhar(NULL, $c$SELECT pet_mensagens_pendentes('confirmacao')$c$, 'anon vê avisos');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_mensagens_pendentes('qualquer')$c$, 'tipo de aviso inválido');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_mensagens_pendentes('confirmacao', 99)$c$, 'janela grande demais');

  PERFORM ci.entrar(vend);
  r := pet_mensagens_pendentes('confirmacao', 1);
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Agendado' AND e ->> 'telefone' = '(16) 99888-7777'),
                   'o agendamento de amanhã entra, com o WhatsApp do tutor');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Pronto'), 'pet pronto não entra na lista de confirmação');
  PERFORM ci.exige((SELECT count(*) = 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Agendado'),
                   'dois agendamentos do mesmo pet no mesmo dia entram numa linha só');
  PERFORM ci.exige((SELECT e ->> 'hora' = '10:00 e 15:00' FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Agendado'),
                   'a linha traz os horários do dia');

  PERFORM ci.entrar(vend);
  r := pet_mensagens_pendentes('pronto');
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Pronto'), 'pet pronto entra na lista de retirada');

  -- registrar tira da lista, só daquela ocasião
  PERFORM ci.entrar(vend);
  r := pet_mensagens_pendentes('confirmacao', 1);
  SELECT (e ->> 'referencia')::date INTO ref FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Agendado';
  PERFORM pet_contato_registrar(p_agenda, 'confirmacao', ref, 'whatsapp');
  r := pet_mensagens_pendentes('confirmacao', 1);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Agendado'), 'depois de avisar, o agendamento some da lista');

  -- tutor que não quer mensagens não aparece em nenhuma lista
  UPDATE clientes SET aceita_mensagens = false WHERE id = tutor;
  PERFORM ci.entrar(vend);
  r := pet_mensagens_pendentes('pronto');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' = 'Msg Pronto'), 'tutor que não aceita mensagens sai da lista de pronto');
  PERFORM ci.entrar(vend);
  r := pet_contatos_pendentes('retorno', 7);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'pet' IN ('Msg Agendado', 'Msg Pronto')), 'e também das listas antigas');
  UPDATE clientes SET aceita_mensagens = true WHERE id = tutor;

  -- modelos da empresa: só administrador e gestor guardam; texto em branco volta ao padrão
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_mensagem_modelo_salvar('pronto', 'Oi, {tutor}! O {pet} está pronto.')$c$, 'vendedor guarda modelo');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_mensagem_modelo_salvar('qualquer', 'Oi, {tutor}! Tudo bem?')$c$, 'tipo de modelo inválido');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_mensagem_modelo_salvar('pronto', 'Oi')$c$, 'modelo curto demais');
  PERFORM ci.entrar(adm);
  PERFORM pet_mensagem_modelo_salvar('pronto', 'Oi, {tutor}! O {pet} está pronto.');
  PERFORM pet_mensagem_modelo_salvar('pronto', 'Oi, {tutor}! O {pet} já pode ser retirado.');
  PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(vend, $c$SELECT count(*) FROM pet_mensagem_modelos WHERE tipo = 'pronto' AND texto LIKE '%já pode ser retirado%'$c$) = 1,
                   'o modelo guardado vale para a equipe (um por tipo)');
  PERFORM ci.entrar(adm);
  PERFORM pet_mensagem_modelo_salvar('pronto', '');
  PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(vend, $c$SELECT count(*) FROM pet_mensagem_modelos WHERE tipo = 'pronto'$c$) = 0, 'texto em branco volta ao padrão');
  PERFORM ci.deve_falhar(adm, $c$INSERT INTO pet_mensagem_modelos (tipo, texto) VALUES ('pronto', 'texto direto na tabela')$c$, 'escrita direta em modelos');
END $$;

-- 65. Clínica (receituário e documentos): só o veterinário emite e lê; numeração; controlado recusado; imutável; cancelar com motivo; modelos
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  va   constant uuid := 'a0000000-0000-0000-0000-0000000000f1';
  vb   constant uuid := 'a0000000-0000-0000-0000-0000000000f2';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet uuid; tutor_b uuid; pet_b uuid; tb uuid; r jsonb; r2 jsonb; doc1 uuid; doc2 uuid; modelo uuid; n bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutora Documento CI', '52998224725') RETURNING id INTO tutor;
  INSERT INTO pets (tenant_id, cliente_id, nome, especie) VALUES (demo, tutor, 'Rex Documento CI', 'cao') RETURNING id INTO pet;
  INSERT INTO tenants (nome) VALUES ('Clinica Documento B CI') RETURNING id INTO tb;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (tb, 'Tutor Doc Outra Empresa', '11144477735') RETURNING id INTO tutor_b;
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (tb, tutor_b, 'Pet Doc Outra Empresa') RETURNING id INTO pet_b;

  -- ninguém além do veterinário emite ou lê
  PERFORM ci.deve_falhar(adm, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'titulo','Atestado','corpo','Texto do atestado'))$c$, pet), 'administrador emite documento');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'titulo','Atestado','corpo','Texto do atestado'))$c$, pet), 'gestor emite documento');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_documentos_do_pet(%L)$c$, pet), 'vendedor lista documentos');
  PERFORM ci.deve_falhar(gest, 'SELECT clinica_documento_contexto()', 'gestor abre o contexto de documentos');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT clinica_documentos_do_pet(%L)$c$, pet), 'anon lista documentos');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM pet_documentos', 'leitura direta de documentos pelo administrador');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM pet_documentos', 'leitura direta de documentos pelo veterinário');
  PERFORM ci.deve_falhar(va, 'SELECT count(*) FROM pet_documento_modelos', 'leitura direta de modelos');
  PERFORM ci.deve_falhar(va, format($c$INSERT INTO pet_documentos (tenant_id, pet_id, cliente_id, veterinario_id, crmv, crmv_uf, tipo, ano, numero, titulo, corpo) SELECT %L, %L, %L, id, '1', 'SP', 'atestado', 2026, 1, 'Direto', 'texto direto' FROM pet_profissionais LIMIT 1$c$, demo, pet, tutor), 'escrita direta de documento');

  -- contexto: o veterinário da conta
  PERFORM ci.entrar(va);
  r := clinica_documento_contexto();
  PERFORM ci.sair();
  PERFORM ci.exige(r -> 'veterinario' ->> 'crmv' = '1111' AND r -> 'veterinario' ->> 'crmv_uf' = 'SP', 'o contexto traz o veterinário da conta com o CRMV');

  -- validações
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','qualquer','pet_id',%L,'titulo','Doc','corpo','x'))$c$, pet), 'tipo inválido');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'titulo','Ab','corpo','Texto do atestado'))$c$, pet), 'título curto');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'titulo','Atestado'))$c$, pet), 'atestado sem texto');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','receita','pet_id',%L,'titulo','Receita','itens','[]'::jsonb))$c$, pet), 'receita sem medicamento');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','receita','pet_id',%L,'titulo','Receita','itens',jsonb_build_array(jsonb_build_object('medicamento','Amoxicilina'))))$c$, pet), 'medicamento sem posologia');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','receita','pet_id',%L,'titulo','Receita','itens',jsonb_build_array(jsonb_build_object('medicamento','Fenobarbital','posologia','1 comprimido','controlado',true))))$c$, pet), 'receita de controle especial');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','solicitacao_exame','pet_id',%L,'titulo','Exames','itens','[]'::jsonb))$c$, pet), 'solicitação sem exame');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'titulo','Atestado','corpo','Texto','itens',jsonb_build_array(jsonb_build_object('exame','x'))))$c$, pet), 'atestado com itens');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'titulo','Atestado','corpo','Texto do atestado'))$c$, pet_b), 'paciente de outra empresa');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'atendimento_id',%L,'titulo','Atestado','corpo','Texto do atestado'))$c$, pet, gen_random_uuid()), 'atendimento que não existe');

  -- emitir: receita e solicitação de exames, com numeração sequencial por empresa e ano
  PERFORM ci.entrar(va);
  r := clinica_documento_emitir(jsonb_build_object('tipo', 'receita', 'pet_id', pet, 'titulo', 'Receita', 'corpo', 'Repouso por 5 dias',
          'itens', jsonb_build_array(jsonb_build_object('medicamento', 'Amoxicilina 250 mg', 'posologia', '1 comprimido a cada 12 horas', 'via', 'oral', 'duracao', '7 dias'))));
  r2 := clinica_documento_emitir(jsonb_build_object('tipo', 'solicitacao_exame', 'pet_id', pet, 'titulo', 'Exames',
          'itens', jsonb_build_array(jsonb_build_object('exame', 'Hemograma completo'))));
  PERFORM ci.sair();
  doc1 := (r ->> 'id')::uuid;
  doc2 := (r2 ->> 'id')::uuid;
  PERFORM ci.exige((r2 ->> 'numero')::int = (r ->> 'numero')::int + 1 AND (r ->> 'ano')::int = extract(year FROM (now() AT TIME ZONE 'America/Sao_Paulo'))::int,
                   'a numeração segue em sequência dentro do ano');
  PERFORM ci.exige(r -> 'veterinario' ->> 'crmv' = '1111' AND r -> 'tutor' ->> 'nome' = 'Tutora Documento CI' AND r -> 'pet' ->> 'nome' = 'Rex Documento CI',
                   'o documento traz o CRMV da emissão, o tutor e o paciente');
  PERFORM ci.exige(r -> 'itens' -> 0 ->> 'medicamento' = 'Amoxicilina 250 mg' AND r ->> 'situacao' = 'emitido', 'a receita guarda os itens e fica emitida');

  -- ler e listar: qualquer veterinário da empresa; cada leitura fica registrada
  SELECT count(*) INTO n FROM clinica_acessos WHERE tenant_id = demo AND acao = 'documento';
  PERFORM ci.entrar(vb);
  r := clinica_documento_obter(doc1);
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'titulo' = 'Receita', 'outro veterinário da empresa lê o documento');
  PERFORM ci.exige((SELECT count(*) FROM clinica_acessos WHERE tenant_id = demo AND acao = 'documento') = n + 1, 'a leitura do documento fica registrada');
  PERFORM ci.entrar(va);
  r := clinica_documentos_do_pet(pet);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 2 AND NOT (r -> 0 ? 'itens'), 'a lista traz o resumo dos dois documentos, sem o conteúdo');

  -- o documento guarda paciente, tutor e clínica da emissão: mudar o cadastro depois não muda o documento
  UPDATE pets SET nome = 'Nome Trocado CI', raca = 'Raça Trocada' WHERE id = pet;
  UPDATE clientes SET nome = 'Tutora Trocada CI' WHERE id = tutor;
  PERFORM ci.entrar(va);
  r := clinica_documento_obter(doc1);
  PERFORM ci.sair();
  PERFORM ci.exige(r -> 'pet' ->> 'nome' = 'Rex Documento CI' AND r -> 'tutor' ->> 'nome' = 'Tutora Documento CI' AND r -> 'pet' ->> 'id' = pet::text,
                   'o documento reaberto traz paciente e tutor da emissão, não os cadastros de hoje');
  PERFORM ci.entrar(va);
  r := clinica_documentos_do_pet(pet);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT bool_and((e ->> 'pode_cancelar')::boolean) FROM jsonb_array_elements(r) e), 'quem emitiu vê a opção de cancelar');
  PERFORM ci.entrar(vb);
  r := clinica_documentos_do_pet(pet);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT NOT bool_or((e ->> 'pode_cancelar')::boolean) FROM jsonb_array_elements(r) e), 'outro veterinário não recebe a opção de cancelar');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_documentos SET snapshot = '{}'::jsonb WHERE id = %L$c$, doc1), 'trocar o retrato do documento emitido');

  -- imutável: nem o dono altera o conteúdo ou apaga
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_documentos SET titulo = 'Outro título' WHERE id = %L$c$, doc1), 'alterar documento emitido');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_documentos SET corpo = 'trocado' WHERE id = %L$c$, doc1), 'trocar o texto do documento emitido');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_documentos WHERE id = %L$c$, doc1), 'apagar documento emitido');

  -- cancelar: só quem emitiu, com motivo, uma vez
  PERFORM ci.deve_falhar(vb, format($c$SELECT clinica_documento_cancelar(%L, 'emitido por engano')$c$, doc1), 'outro veterinário cancela');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_documento_cancelar(%L, 'emitido por engano')$c$, doc1), 'gestor cancela');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_cancelar(%L, 'erro')$c$, doc1), 'motivo curto');
  PERFORM ci.entrar(va);
  r := clinica_documento_cancelar(doc1, 'emitido por engano');
  PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'situacao' = 'cancelado' AND r ->> 'cancelado_motivo' = 'emitido por engano', 'cancelar guarda o motivo');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_cancelar(%L, 'de novo o mesmo')$c$, doc1), 'cancelar de novo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_documentos SET situacao = 'emitido', cancelado_em = NULL, cancelado_motivo = NULL WHERE id = %L$c$, doc1), 'reativar documento cancelado');

  -- modelos da clínica: só o veterinário; mesmo título troca o texto
  PERFORM ci.deve_falhar(vend, $c$SELECT clinica_documento_modelo_salvar('termo', 'Meu termo', 'Texto do meu termo de consentimento')$c$, 'vendedor guarda modelo');
  PERFORM ci.deve_falhar(va, $c$SELECT clinica_documento_modelo_salvar('receita', 'Meu modelo', 'Texto do meu modelo de receita')$c$, 'modelo de receita');
  PERFORM ci.deve_falhar(va, $c$SELECT clinica_documento_modelo_salvar('termo', 'Meu termo', 'curto')$c$, 'modelo curto');
  PERFORM ci.entrar(va);
  modelo := clinica_documento_modelo_salvar('termo', 'Meu termo', 'Texto do meu termo de consentimento');
  PERFORM clinica_documento_modelo_salvar('termo', 'Meu termo', 'Texto novo do meu termo de consentimento');
  r := clinica_documento_contexto();
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'modelos') = 1 AND r -> 'modelos' -> 0 ->> 'corpo' LIKE 'Texto novo%', 'o modelo guardado aparece no contexto, um por título');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_documento_modelo_excluir(%L)$c$, modelo), 'vendedor exclui modelo');
  PERFORM ci.entrar(va);
  PERFORM clinica_documento_modelo_excluir(modelo);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 0 FROM pet_documento_modelos WHERE tenant_id = demo), 'o modelo excluído sai');

  -- clínica deixa de estar liberada: nada funciona
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/04', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_emitir(jsonb_build_object('tipo','atestado','pet_id',%L,'titulo','Atestado','corpo','Texto do atestado'))$c$, pet), 'emitir sem a clínica liberada');
  PERFORM ci.deve_falhar(va, format($c$SELECT clinica_documento_obter(%L)$c$, doc2), 'ler documento sem a clínica liberada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 66. Reforma tributária: a classificação do produto no IBS/CBS vem em par (CST + cClassTrib) e o cClassTrib pertence ao CST
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
BEGIN
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, cst_ibs_cbs, cclasstrib)
  VALUES (demo, 'IBS-OK-CI', 'Produto alíquota reduzida CI', 'UN', 0, '200', '200003');
  PERFORM ci.exige((SELECT cclasstrib = '200003' FROM produtos WHERE tenant_id = demo AND codigo_interno = 'IBS-OK-CI'), 'produto guarda a classificação do IBS/CBS');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, cst_ibs_cbs, cclasstrib) VALUES (%L, 'IBS-X1', 'x', 'UN', 0, '000', '200003')$c$, demo), 'cClassTrib de outro CST');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, cst_ibs_cbs) VALUES (%L, 'IBS-X2', 'x', 'UN', 0, '000')$c$, demo), 'CST sem cClassTrib');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, cst_ibs_cbs, cclasstrib) VALUES (%L, 'IBS-X3', 'x', 'UN', 0, 'AB1', '000001')$c$, demo), 'CST fora do formato');
END $$;

-- 67. Lava rápido: módulo liberado por CNAE, veículos (placa e prefixo de aeronave), preço por tipo, quadro do pátio,
--     entregar e cobrar com comissão e NFS-e em rascunho, venda cancelada e permissões
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  fin  constant uuid := 'a0000000-0000-0000-0000-0000000000b2';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  cli uuid; dep uuid; carro uuid; moto uuid; aviao uuid; heli uuid; serv uuid; serv_prod uuid; lav uuid;
  o1 uuid; o2 uuid; o3 uuid; ped uuid; ped2 uuid; ped_errado uuid; r jsonb; com uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Lava CI') RETURNING id INTO dep;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Lava CI', '52998224725') RETURNING id INTO cli;

  -- sem a atividade de lavagem, nada funciona
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4789-0/99', cnae_secundarios = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_servico_salvar('{"nome":"Lavagem"}'::jsonb)$c$, 'cadastrar serviço sem o módulo liberado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'identificacao', 'ABC1234', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, cli), 'cadastrar veículo sem o módulo liberado');
  UPDATE empresas SET cnae = '4520-0/06' WHERE tenant_id = demo;
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM (SELECT lava_rapido_liberado() AS l) x WHERE l') = 1, 'o CNAE 45.20-0/06 libera o lava rápido');

  -- veículos: placa nos três tipos terrestres, prefixo nas aeronaves
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'identificacao', 'ABC1234', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, cli), 'garçom cadastra veículo');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'identificacao', 'ABC1234', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, cli), 'estoquista cadastra veículo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'identificacao', '1234ABC', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, cli), 'placa fora do padrão');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'tipo', 'barco', 'identificacao', 'ABC1234', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, cli), 'tipo inválido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'tipo', 'aviao', 'identificacao', 'PT', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, cli), 'prefixo curto demais');
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_veiculo_salvar(jsonb_build_object('identificacao', 'ABC1234', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, 'veículo sem cliente');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'identificacao', 'ABC1234', 'modelo', 'Civic'))$c$, cli), 'veículo sem fabricante');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'identificacao', 'ABC1234', 'fabricante', 'Honda', 'modelo', '  '))$c$, cli), 'veículo sem modelo');
  PERFORM ci.entrar(vend);
  carro := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'abc-1d23', 'fabricante', 'Honda', 'modelo', 'Civic'));
  moto := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'moto', 'identificacao', 'XYZ 9876', 'fabricante', 'Honda', 'modelo', 'Civic'));
  aviao := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'aviao', 'identificacao', 'pt-abc', 'fabricante', 'Honda', 'modelo', 'Civic'));
  heli := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'helicoptero', 'identificacao', 'PRXYZ', 'fabricante', 'Honda', 'modelo', 'Civic'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT identificacao = 'ABC1D23' FROM lr_veiculos WHERE id = carro), 'a placa é guardada em maiúsculas e sem separador');
  PERFORM ci.exige((SELECT identificacao = 'PTABC' AND tipo = 'aviao' FROM lr_veiculos WHERE id = aviao), 'o prefixo da aeronave é guardado em maiúsculas');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_veiculo_salvar(jsonb_build_object('cliente_id', %L, 'identificacao', 'ABC1D23', 'fabricante', 'Honda', 'modelo', 'Civic'))$c$, cli), 'identificação repetida');

  -- serviços e preço por tipo
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_servico_salvar('{"nome":"Lavagem completa"}'::jsonb)$c$, 'vendedor cria serviço');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_servico_salvar('{"nome":""}'::jsonb)$c$, 'serviço sem nome');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_servico_salvar('{"nome":"X","categoria":"voo"}'::jsonb)$c$, 'categoria inválida');
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem completa","categoria":"lavagem","duracao_min":45,"preco_base":25}'::jsonb);
  PERFORM lr_preco_salvar(serv, NULL, 30);
  PERFORM lr_preco_salvar(serv, 'carro', 40);
  PERFORM lr_preco_salvar(serv, 'aviao', 900);
  lav := lr_lavador_salvar('{"nome":"Beto Lavador","comissao_percentual":20}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO serv_prod FROM lr_servicos WHERE id = serv;
  PERFORM ci.exige((SELECT NOT controla_estoque AND preco_venda = 25 FROM produtos WHERE id = serv_prod), 'o serviço vira produto sem controle de estoque');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_servico_salvar('{"nome":" LAVAGEM completa "}'::jsonb)$c$, 'nome de serviço repetido');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_preco_salvar(%L, 'barco', 10)$c$, serv), 'preço com tipo inválido');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_preco_salvar(%L, 'carro', -1)$c$, serv), 'preço negativo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_preco_salvar(%L, 'carro', 10)$c$, serv), 'vendedor grava preço');
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_lavador_salvar('{"nome":"Fulano"}'::jsonb)$c$, 'vendedor cria lavador');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_lavador_salvar('{"nome":"Fulano","comissao_percentual":101}'::jsonb)$c$, 'comissão acima de 100');

  -- ordens: o preço congela pelo tipo do veículo (carro 40, moto cai no geral 30, avião 900)
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_criar(jsonb_build_object('veiculo_id', %L, 'servicos', '[]'::jsonb))$c$, carro), 'ordem sem serviço');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_ordem_criar(jsonb_build_object('veiculo_id', %L, 'servicos', jsonb_build_array(%L)))$c$, carro, serv), 'garçom abre ordem');
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', carro, 'lavador_id', lav, 'box', 'Box 1', 'servicos', jsonb_build_array(serv)));
  o2 := lr_ordem_criar(jsonb_build_object('veiculo_id', moto, 'servicos', jsonb_build_array(serv)));
  o3 := lr_ordem_criar(jsonb_build_object('veiculo_id', aviao, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT preco_aplicado = 40 FROM lr_ordem_itens WHERE ordem_id = o1), 'carro usa o preço do tipo');
  PERFORM ci.exige((SELECT preco_aplicado = 30 FROM lr_ordem_itens WHERE ordem_id = o2), 'moto sem preço próprio usa o preço geral');
  PERFORM ci.exige((SELECT preco_aplicado = 900 FROM lr_ordem_itens WHERE ordem_id = o3), 'avião usa o preço do tipo');
  PERFORM ci.entrar(gest);
  PERFORM lr_preco_salvar(serv, 'carro', 55);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT preco_aplicado = 40 FROM lr_ordem_itens WHERE ordem_id = o1), 'mudar o preço depois não altera a ordem aberta');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_criar(jsonb_build_object('veiculo_id', %L, 'servicos', jsonb_build_array(%L)))$c$, carro, serv), 'segunda ordem aberta do mesmo veículo');

  -- quadro do pátio
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_situacao(%L, 'lavando')$c$, o2), 'começar a lavar sem lavador');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_situacao(%L, 'pronto')$c$, o1), 'pular de aguardando para pronto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_situacao(%L, 'entregue')$c$, o1), 'entregar sem cobrar');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_ordem_situacao(%L, 'lavando')$c$, o1), 'garçom mexe no pátio');
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o1, 'lavando'); PERFORM lr_ordem_situacao(o1, 'secando'); PERFORM lr_ordem_situacao(o1, 'pronto');
  PERFORM lr_ordem_atribuir(o2, lav, 'Box 2');
  PERFORM lr_ordem_situacao(o2, 'lavando'); PERFORM lr_ordem_situacao(o2, 'pronto');
  PERFORM lr_ordem_situacao(o3, 'cancelada', 'cliente desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'pronto' AND pronto_em IS NOT NULL FROM lr_ordens WHERE id = o1), 'a ordem pronta guarda a hora');
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND motivo_cancelamento = 'cliente desistiu' FROM lr_ordens WHERE id = o3), 'cancelar guarda o motivo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_situacao(%L, 'lavando')$c$, o3), 'reabrir ordem cancelada');
  -- o veículo da ordem cancelada pode ter nova ordem
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_criar(jsonb_build_object('veiculo_id', aviao, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();

  -- entregar e cobrar: venda do caixa com o serviço pelo valor combinado e uma mercadoria, desconto de 10
  PERFORM ci.entrar(vend);
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 40)),
                   'crediario', cli, 4, 1, current_date + 30);
  ped_errado := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 55)),
                          'crediario', cli, 0, 1, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_retirar(%L)$c$, o1), 'sem informar a venda');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_retirar(%L, %L)$c$, o1, ped_errado), 'venda com o serviço por outro valor');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_ordem_retirar(%L, %L)$c$, o1, ped), 'garçom cobra');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_ordem_retirar(%L, %L)$c$, o1, ped), 'anon cobra');
  PERFORM ci.entrar(vend);
  r := lr_ordem_retirar(o1, ped);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'entregue' AND venda_id = ped AND entregue_em IS NOT NULL FROM lr_ordens WHERE id = o1), 'a ordem fica entregue e ligada à venda');
  -- 40 com desconto proporcional (36) → comissão de 20% = 7,20
  PERFORM ci.exige((SELECT base = 36 AND percentual = 20 AND valor = 7.20 AND situacao = 'a_aprovar' FROM lr_comissoes WHERE ordem_id = o1), 'comissão do lavador sobre o serviço líquido do desconto');
  PERFORM ci.exige((SELECT situacao = 'rascunho' AND valor_total = 36 AND valor_produtos = 40 AND valor_desconto = 4 FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'NFS-e do serviço em rascunho');
  PERFORM ci.entrar(vend);
  r := lr_ordem_retirar(o1, ped);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) = 1 FROM lr_comissoes WHERE ordem_id = o1)
                   AND (SELECT count(*) = 1 FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'repetir a cobrança não duplica comissão nem nota');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_retirar(%L, %L)$c$, o2, ped), 'a mesma venda cobrando duas ordens');

  -- venda cancelada: ordem volta a pronta, comissão cancelada, rascunho sai; cobrar de novo reativa a comissão
  UPDATE pedidos SET situacao = 'cancelado' WHERE id = ped;
  PERFORM ci.exige((SELECT situacao = 'pronto' AND venda_id IS NULL FROM lr_ordens WHERE id = o1), 'venda cancelada devolve a ordem a pronta');
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM lr_comissoes WHERE ordem_id = o1), 'venda cancelada cancela a comissão');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'venda cancelada tira o rascunho da NFS-e');
  PERFORM ci.entrar(vend);
  ped2 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 0, 1, current_date + 30);
  PERFORM lr_ordem_retirar(o1, ped2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'a_aprovar' AND pedido_id = ped2 AND base = 40 AND valor = 8 FROM lr_comissoes WHERE ordem_id = o1), 'cobrar de novo reativa a comissão, com a nova venda');

  -- comissões: aprovar e pagar; leitura só da gestão e do financeiro
  SELECT id INTO com FROM lr_comissoes WHERE ordem_id = o1;
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_comissao_aprovar(%L)$c$, com), 'vendedor aprova comissão');
  PERFORM ci.deve_falhar(fin, format($c$SELECT lr_comissao_pagar(%L)$c$, com), 'pagar comissão não aprovada');
  PERFORM ci.entrar(fin);
  PERFORM lr_comissao_aprovar(com);
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  PERFORM lr_comissao_pagar(com, 'pix');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'paga' AND pago_em IS NOT NULL AND pago_por IS NOT NULL FROM lr_comissoes WHERE id = com), 'comissão paga com registro de quem e quando');
  PERFORM ci.exige(ci.contar(fin, 'SELECT count(*) FROM lr_comissoes') >= 1 AND ci.contar(vend, 'SELECT count(*) FROM lr_comissoes') = 0
                   AND ci.contar(gar, 'SELECT count(*) FROM lr_comissoes') = 0, 'só administrador, gestor e financeiro leem comissões');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM lr_ordens') >= 3 AND ci.contar(gar, 'SELECT count(*) FROM lr_ordens') = 0, 'o garçom não lê ordens');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE lr_comissoes SET valor = 999 WHERE id = %L$c$, com), 'alterar comissão direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE lr_ordens SET situacao = 'pronto' WHERE id = %L$c$, o2), 'alterar ordem direto');

  -- módulo desligado de novo: nada funciona
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_situacao(%L, 'lavando')$c$, o2), 'mexer no pátio com o módulo desligado');
END $$;

-- 68. Lava rápido (planos e fidelidade): venda do plano, lavagem coberta, saldo, validade, ordem só coberta, brinde e venda cancelada
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  cli uuid; cli2 uuid; dep uuid; v1 uuid; v2 uuid; moto uuid; serv uuid; serv2 uuid; serv_prod uuid; plano uuid; plano_moto uuid; plano_prod uuid;
  f jsonb; lav uuid; ped uuid; ped_errado uuid; ped_ord uuid; ass uuid; r jsonb; o uuid; o2 uuid; o3 uuid; o4 uuid; i1 uuid; n int;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Lava Planos CI') RETURNING id INTO dep;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Plano CI', '52998224725') RETURNING id INTO cli;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Fiel CI', '11144477735') RETURNING id INTO cli2;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'PLA1A11', 'fabricante', 'Fiat', 'modelo', 'Uno'));
  moto := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'moto', 'identificacao', 'PLA2B22', 'fabricante', 'Honda', 'modelo', 'CG'));
  v2 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli2, 'tipo', 'carro', 'identificacao', 'FID1C33', 'fabricante', 'VW', 'modelo', 'Gol'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem do plano","duracao_min":30,"preco_base":40}'::jsonb);
  serv2 := lr_servico_salvar('{"nome":"Cera do plano","duracao_min":30,"preco_base":30}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador Plano CI","comissao_percentual":10}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO serv_prod FROM lr_servicos WHERE id = serv;

  -- cadastro do plano: só administrador e gestor
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_plano_salvar(jsonb_build_object('nome','Mensal','servico_id',%L,'lavagens',4,'preco',120))$c$, serv), 'vendedor cria plano');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_plano_salvar(jsonb_build_object('nome','Mensal','servico_id',%L,'lavagens',4,'preco',120))$c$, serv), 'garçom cria plano');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_plano_salvar(jsonb_build_object('nome','','servico_id',%L,'lavagens',4,'preco',120))$c$, serv), 'plano sem nome');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_plano_salvar(jsonb_build_object('nome','X','servico_id',%L,'lavagens',1,'preco',120))$c$, serv), 'plano de uma lavagem só');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_plano_salvar(jsonb_build_object('nome','X','servico_id',%L,'lavagens',4,'preco',0))$c$, serv), 'plano sem preço');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_plano_salvar(jsonb_build_object('nome','X','servico_id',%L,'lavagens',4,'preco',50,'validade_dias',3))$c$, serv), 'validade curta demais');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_plano_salvar(jsonb_build_object('nome','X','servico_id',gen_random_uuid(),'lavagens',4,'preco',50))$c$, 'serviço que não existe');
  PERFORM ci.entrar(gest);
  plano := lr_plano_salvar(jsonb_build_object('nome','Mensal 2 lavagens','servico_id',serv,'lavagens',2,'preco',60,'validade_dias',30,'tipo','carro'));
  plano_moto := lr_plano_salvar(jsonb_build_object('nome','Mensal moto','servico_id',serv,'lavagens',3,'preco',45,'tipo','moto'));
  PERFORM ci.sair();
  SELECT produto_id INTO plano_prod FROM lr_planos WHERE id = plano;
  PERFORM ci.exige((SELECT NOT controla_estoque AND preco_venda = 60 FROM produtos WHERE id = plano_prod), 'o plano vira um produto sem estoque, com o preço do plano');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_plano_salvar(jsonb_build_object('nome',' mensal 2 LAVAGENS ','servico_id',%L,'lavagens',2,'preco',60))$c$, serv), 'nome de plano repetido');

  -- venda do plano: a venda do caixa precisa trazer o plano uma vez, pelo preço
  PERFORM ci.entrar(vend);
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', plano_prod, 'quantidade', 1, 'preco_unitario', 60)), 'crediario', cli, 0, 1, current_date + 30);
  ped_errado := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', plano_prod, 'quantidade', 1, 'preco_unitario', 50)), 'crediario', cli, 0, 1, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_plano_vender(%L, %L, %L)$c$, plano, v1, ped_errado), 'plano vendido por outro valor');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_plano_vender(%L, %L)$c$, plano, v1), 'plano sem informar a venda');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_plano_vender(%L, %L, %L)$c$, plano, moto, ped), 'plano de carro para uma moto');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_plano_vender(%L, %L, %L)$c$, plano, v1, ped), 'garçom vende plano');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_plano_vender(%L, %L, %L)$c$, plano, v1, ped), 'estoquista vende plano');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_plano_vender(%L, %L, %L)$c$, plano, v1, ped), 'anon vende plano');
  PERFORM ci.entrar(vend);
  r := lr_plano_vender(plano, v1, ped);
  ass := (r ->> 'assinatura_id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT lavagens = 2 AND valor = 60 AND situacao = 'ativa' AND vence_em = current_date + 30 AND veiculo_id = v1 FROM lr_assinaturas WHERE id = ass), 'a assinatura nasce ativa, com validade e valor da venda');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'a venda do plano deixa a NFS-e em rascunho');
  PERFORM ci.entrar(vend);
  r := lr_plano_vender(plano, v1, ped);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) = 1 FROM lr_assinaturas WHERE venda_id = ped), 'repetir a venda do plano não duplica a assinatura');

  -- lavagem coberta: não entra na cobrança, na NFS-e nem na comissão
  PERFORM ci.entrar(vend);
  o := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'servicos', jsonb_build_array(serv, serv2)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura = 'assinatura' AND assinatura_id = ass FROM lr_ordem_itens WHERE ordem_id = o AND servico_id = serv), 'o serviço do plano sai da assinatura');
  PERFORM ci.exige((SELECT cobertura IS NULL FROM lr_ordem_itens WHERE ordem_id = o AND servico_id = serv2), 'outro serviço segue cobrado');
  PERFORM ci.exige(_lr_assinatura_restam(ass) = 1, 'sobra uma lavagem no plano');

  -- cancelar a ordem devolve a lavagem
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o, 'cancelada', 'desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige(_lr_assinatura_restam(ass) = 2, 'cancelar a ordem devolve a lavagem ao plano');

  -- ordem só de itens cobertos é entregue sem caixa, sem comissão e sem nota
  PERFORM ci.entrar(vend);
  o2 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o2, 'lavando'); PERFORM lr_ordem_situacao(o2, 'pronto');
  r := lr_ordem_retirar(o2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'entregue' AND venda_id IS NULL FROM lr_ordens WHERE id = o2), 'ordem só coberta é entregue sem venda');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM lr_comissoes WHERE ordem_id = o2) AND r ->> 'pedido_id' IS NULL, 'ordem só coberta não gera comissão nem pede venda');
  PERFORM ci.entrar(vend);
  r := lr_ordem_retirar(o2);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean, 'repetir a entrega da ordem coberta devolve o mesmo resultado');

  -- esgota o saldo: a lavagem seguinte é cobrada
  PERFORM ci.entrar(vend);
  o3 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o3, 'cancelada', 'passo');
  PERFORM ci.sair();
  PERFORM ci.exige(_lr_assinatura_restam(ass) = 1, 'cancelar de novo mantém o saldo (uma já foi entregue)');
  PERFORM ci.entrar(vend);
  o3 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o3, 'lavando'); PERFORM lr_ordem_situacao(o3, 'pronto'); PERFORM lr_ordem_retirar(o3);
  o4 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();
  PERFORM ci.exige(_lr_assinatura_restam(ass) = 0, 'o plano de 2 lavagens termina na segunda');
  PERFORM ci.exige((SELECT cobertura IS NULL FROM lr_ordem_itens WHERE ordem_id = o4), 'sem saldo, a lavagem é cobrada');
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o4, 'cancelada', 'teste');
  PERFORM ci.sair();

  -- plano vencido não cobre
  UPDATE lr_assinaturas SET vence_em = current_date - 1 WHERE id = ass;
  UPDATE lr_assinatura_usos SET desfeito = true WHERE assinatura_id = ass;
  PERFORM ci.entrar(vend);
  o := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura IS NULL FROM lr_ordem_itens WHERE ordem_id = o), 'plano vencido não cobre a lavagem');
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o, 'cancelada', 'teste');
  PERFORM ci.sair();

  -- venda do plano cancelada: a assinatura é cancelada e a nota em rascunho sai
  UPDATE lr_assinaturas SET vence_em = current_date + 10 WHERE id = ass;
  UPDATE pedidos SET situacao = 'cancelado' WHERE id = ped;
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM lr_assinaturas WHERE id = ass), 'venda cancelada cancela a assinatura');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM nfe WHERE pedido_id = ped AND modelo = 'nfse'), 'venda cancelada tira a NFS-e do plano');
  PERFORM ci.entrar(vend);
  o := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura IS NULL FROM lr_ordem_itens WHERE ordem_id = o), 'assinatura cancelada não cobre');
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o, 'cancelada', 'teste');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_assinatura_cancelar(%L, 'x')$c$, ass), 'vendedor cancela assinatura');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_assinatura_cancelar(%L, '')$c$, ass), 'cancelar assinatura sem motivo');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_assinatura_cancelar(%L, 'já cancelada')$c$, ass), 'cancelar assinatura já cancelada');

  -- fidelidade: a cada 2 lavagens entregues, a próxima do serviço-brinde é grátis
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_fidelidade_salvar(true, 2, %L)$c$, serv), 'vendedor liga a fidelidade');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_fidelidade_salvar(true, 1, %L)$c$, serv), 'brinde na 1ª lavagem');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_fidelidade_salvar(true, 5, NULL)$c$, 'fidelidade sem serviço-brinde');
  PERFORM ci.entrar(gest);
  PERFORM lr_fidelidade_salvar(true, 2, serv);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend); f := lr_fidelidade_cliente(cli2); PERFORM ci.sair();
  PERFORM ci.exige((f ->> 'selos')::int = 0, 'recomeça sem selos');
  FOR n IN 1..2 LOOP
    PERFORM ci.entrar(vend);
    o := lr_ordem_criar(jsonb_build_object('veiculo_id', v2, 'lavador_id', lav, 'servicos', jsonb_build_array(serv2)));
    PERFORM lr_ordem_situacao(o, 'lavando'); PERFORM lr_ordem_situacao(o, 'pronto');
    ped_ord := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', (SELECT produto_id FROM lr_servicos WHERE id = serv2), 'quantidade', 1, 'preco_unitario', 30)), 'crediario', cli2, 0, 1, current_date + 30);
    PERFORM lr_ordem_retirar(o, ped_ord);
    PERFORM ci.sair();
  END LOOP;
  PERFORM ci.entrar(vend); f := lr_fidelidade_cliente(cli2); PERFORM ci.sair();
  PERFORM ci.exige((f ->> 'disponiveis')::int = 1, 'duas lavagens entregues dão um brinde');
  PERFORM ci.entrar(vend);
  o := lr_ordem_criar(jsonb_build_object('veiculo_id', v2, 'servicos', jsonb_build_array(serv, serv2)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura = 'fidelidade' FROM lr_ordem_itens WHERE ordem_id = o AND servico_id = serv), 'o serviço-brinde sai de graça');
  PERFORM ci.exige((SELECT cobertura IS NULL FROM lr_ordem_itens WHERE ordem_id = o AND servico_id = serv2), 'os outros serviços seguem cobrados');
  PERFORM ci.entrar(vend); f := lr_fidelidade_cliente(cli2); PERFORM ci.sair();
  PERFORM ci.exige((f ->> 'disponiveis')::int = 0, 'o brinde usado não fica disponível de novo');
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o, 'cancelada', 'desistiu');
  PERFORM ci.sair();
  PERFORM ci.entrar(vend); f := lr_fidelidade_cliente(cli2); PERFORM ci.sair();
  PERFORM ci.exige((f ->> 'disponiveis')::int = 1, 'cancelar a ordem devolve o brinde');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_fidelidade_cliente(%L)$c$, cli2), 'garçom consulta fidelidade');

  -- prévia da cobertura
  PERFORM ci.entrar(vend);
  r := lr_cobertura_previa(v2, jsonb_build_array(serv, serv2));
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'cobertura' = 'fidelidade'), 'a prévia mostra o brinde');

  -- fidelidade desligada: nada de brinde
  PERFORM ci.entrar(gest);
  PERFORM lr_fidelidade_salvar(false, 2, serv);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend); f := lr_fidelidade_cliente(cli2); PERFORM ci.sair();
  PERFORM ci.exige((f ->> 'ativo')::boolean = false, 'fidelidade desligada não tem brinde');

  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM lr_assinaturas') = 0 AND ci.contar(vend, 'SELECT count(*) FROM lr_assinaturas') >= 1, 'o garçom não lê assinaturas');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE lr_assinaturas SET lavagens = 999 WHERE id = %L$c$, ass), 'alterar assinatura direto');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 69. Lava rápido (avisos): pronto, plano vencendo e retorno; quem já foi chamado sai da lista; cliente que não quer mensagens não entra; modelos
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  cli uuid; cli_no uuid; dep uuid; v1 uuid; v2 uuid; v3 uuid; serv uuid; serv_prod uuid; lav uuid; plano uuid; ass uuid; ass2 uuid;
  o1 uuid; o2 uuid; o3 uuid; ped uuid; r jsonb; n int;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Lava Avisos CI') RETURNING id INTO dep;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone, whatsapp) VALUES (demo, 'Cliente Aviso CI', '52998224725', '11999990000', '11988887777') RETURNING id INTO cli;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone, aceita_mensagens) VALUES (demo, 'Cliente Sem Msg CI', '11144477735', '11977776666', false) RETURNING id INTO cli_no;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'AVI1A11', 'fabricante', 'Fiat', 'modelo', 'Argo'));
  v2 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'moto', 'identificacao', 'AVI2B22', 'fabricante', 'Honda', 'modelo', 'Biz'));
  v3 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_no, 'tipo', 'carro', 'identificacao', 'AVI3C33', 'fabricante', 'VW', 'modelo', 'Polo'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem avisos","preco_base":40}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador Avisos CI","comissao_percentual":0}'::jsonb);
  plano := lr_plano_salvar(jsonb_build_object('nome','Plano avisos','servico_id',serv,'lavagens',4,'preco',100));
  PERFORM ci.sair();
  SELECT produto_id INTO serv_prod FROM lr_servicos WHERE id = serv;

  -- permissões e validações
  PERFORM ci.deve_falhar(gar, $c$SELECT lr_mensagens_pendentes('pronto')$c$, 'garçom lê avisos');
  PERFORM ci.deve_falhar(est, $c$SELECT lr_mensagens_pendentes('pronto')$c$, 'estoquista lê avisos');
  PERFORM ci.deve_falhar(NULL, $c$SELECT lr_mensagens_pendentes('pronto')$c$, 'anon lê avisos');
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_mensagens_pendentes('aniversario')$c$, 'tipo de aviso inválido');
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_mensagens_pendentes('retorno', 3)$c$, 'retorno com menos de 7 dias');
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_mensagens_pendentes('plano_vencendo', 90)$c$, 'janela de plano acima de 60');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_contato_registrar('pronto', %L)$c$, gen_random_uuid()::text), 'garçom registra contato');
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_contato_registrar('pronto', 'não-é-uuid')$c$, 'referência inválida');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_contato_registrar('pronto', %L)$c$, gen_random_uuid()::text), 'referência que não existe');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_contato_registrar('pronto', %L, 'pombo')$c$, gen_random_uuid()::text), 'canal inválido');

  -- pronto: entra quando fica pronto, usa o WhatsApp do cliente, sai depois de chamado; quem não quer mensagens não entra
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  o3 := lr_ordem_criar(jsonb_build_object('veiculo_id', v3, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  r := lr_mensagens_pendentes('pronto');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' IN (o1::text, o3::text)), 'ordem ainda não pronta não gera aviso');
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o1, 'lavando'); PERFORM lr_ordem_situacao(o1, 'pronto');
  PERFORM lr_ordem_situacao(o3, 'lavando'); PERFORM lr_ordem_situacao(o3, 'pronto');
  r := lr_mensagens_pendentes('pronto');
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o1::text AND e ->> 'telefone' = '11988887777' AND e ->> 'veiculo' = 'AVI1A11'),
                   'veículo pronto entra no aviso, com o WhatsApp do cliente');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o3::text), 'cliente que não quer mensagens não entra');
  PERFORM ci.entrar(vend);
  PERFORM lr_contato_registrar('pronto', o1::text);
  PERFORM lr_contato_registrar('pronto', o1::text);
  r := lr_mensagens_pendentes('pronto');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o1::text), 'quem já foi chamado sai da lista');
  PERFORM ci.exige((SELECT count(*) = 1 FROM lr_contatos WHERE tipo = 'pronto' AND referencia = o1::text AND canal = 'whatsapp'), 'registrar duas vezes grava um contato só');

  -- plano vencendo
  INSERT INTO lr_assinaturas (tenant_id, plano_id, veiculo_id, cliente_id, servico_id, lavagens, valor, comprado_em, vence_em)
  VALUES (demo, plano, v2, cli, serv, 4, 100, current_date - 27, current_date + 3) RETURNING id INTO ass;
  PERFORM ci.entrar(vend);
  r := lr_mensagens_pendentes('plano_vencendo', 7);
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = ass::text AND e ->> 'plano' = 'Plano avisos' AND (e ->> 'restam')::int = 4),
                   'plano que vence em 3 dias entra, com o saldo');
  PERFORM ci.entrar(vend);
  r := lr_mensagens_pendentes('plano_vencendo', 1);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = ass::text), 'janela menor que o vencimento deixa o plano de fora');
  -- renovado: outra assinatura ativa do mesmo veículo vence depois
  INSERT INTO lr_assinaturas (tenant_id, plano_id, veiculo_id, cliente_id, servico_id, lavagens, valor, comprado_em, vence_em)
  VALUES (demo, plano, v2, cli, serv, 4, 100, current_date, current_date + 30) RETURNING id INTO ass2;
  PERFORM ci.entrar(vend);
  r := lr_mensagens_pendentes('plano_vencendo', 7);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = ass::text), 'plano já renovado não é cobrado');
  UPDATE lr_assinaturas SET situacao = 'cancelada', motivo = 'teste' WHERE id = ass2;
  PERFORM ci.entrar(vend);
  PERFORM lr_contato_registrar('plano_vencendo', ass::text, 'telefone');
  r := lr_mensagens_pendentes('plano_vencendo', 7);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = ass::text), 'plano chamado sai da lista');

  -- retorno: última entrega antiga, sem ordem aberta nem plano valendo
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o1, 'cancelada', 'libera o veículo');
  o2 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o2, 'lavando'); PERFORM lr_ordem_situacao(o2, 'pronto');
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 0, 1, current_date + 30);
  PERFORM lr_ordem_retirar(o2, ped);
  r := lr_mensagens_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o2::text), 'entrega de hoje ainda não pede retorno');
  UPDATE lr_ordens SET entregue_em = now() - interval '40 days' WHERE id = o2;
  PERFORM ci.entrar(vend);
  r := lr_mensagens_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o2::text AND (e ->> 'dias')::int = 40 AND e ->> 'veiculo' = 'AVI1A11'),
                   'veículo sem voltar há 40 dias entra no retorno de 30');
  PERFORM ci.entrar(vend);
  r := lr_mensagens_pendentes('retorno', 60);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o2::text), 'retorno de 60 dias deixa de fora quem veio há 40');
  UPDATE lr_ordens SET entregue_em = now() - interval '400 days' WHERE id = o2;
  PERFORM ci.entrar(vend);
  r := lr_mensagens_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o2::text), 'mais de um ano sem voltar já não é chamado');
  UPDATE lr_ordens SET entregue_em = now() - interval '40 days' WHERE id = o2;
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'servicos', jsonb_build_array(serv)));
  r := lr_mensagens_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o2::text), 'veículo com ordem aberta não é chamado');
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o1, 'cancelada', 'teste');
  PERFORM lr_contato_registrar('retorno', o2::text);
  r := lr_mensagens_pendentes('retorno', 30);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o2::text), 'retorno chamado sai da lista');
  PERFORM ci.exige((SELECT count(*) = 3 FROM lr_contatos WHERE cliente_id = cli), 'um contato por ocasião (pronto, plano e retorno)');

  -- modelos por empresa
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_mensagem_modelo_salvar('pronto', 'Seu veículo está pronto!')$c$, 'vendedor altera modelo');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_mensagem_modelo_salvar('aniversario', 'Oi, tudo bem?')$c$, 'modelo de tipo inválido');
  PERFORM ci.deve_falhar(adm, $c$SELECT lr_mensagem_modelo_salvar('pronto', 'Oi')$c$, 'modelo curto demais');
  PERFORM ci.entrar(gest);
  PERFORM lr_mensagem_modelo_salvar('pronto', 'Oi, {cliente}! O {veiculo} já está pronto.');
  PERFORM lr_mensagem_modelo_salvar('pronto', 'Oi, {cliente}! O {veiculo} está pronto na {loja}.');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 1 AND bool_and(texto LIKE '%na {loja}%') FROM lr_mensagem_modelos WHERE tipo = 'pronto'), 'o modelo guardado é um por tipo e empresa');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM lr_mensagem_modelos') = 1 AND ci.contar(gar, 'SELECT count(*) FROM lr_mensagem_modelos') = 0, 'o garçom não lê modelos');
  PERFORM ci.entrar(gest);
  PERFORM lr_mensagem_modelo_salvar('pronto', '   ');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM lr_mensagem_modelos WHERE tipo = 'pronto'), 'texto em branco volta ao padrão');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM lr_contatos') = 0, 'o garçom não lê contatos');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE lr_contatos SET canal = 'outro' WHERE cliente_id = %L$c$, cli), 'alterar contato direto');

  -- módulo desligado: nada funciona
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_mensagens_pendentes('pronto')$c$, 'avisos com o módulo desligado');
END $$;

-- 70. Lava rápido (insumos): receita por serviço, baixa na entrega, falta de saldo não trava a entrega, refazer, sem baixa em dobro
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  cli uuid; dep uuid; dep_b uuid; v1 uuid; serv uuid; serv_prod uuid; lav uuid; shampoo uuid; cera uuid; sv_prod uuid; ins uuid;
  o1 uuid; o2 uuid; o3 uuid; ped uuid; ped2 uuid; baixa uuid; r jsonb;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO depositos (tenant_id, nome, permite_negativo) VALUES (demo, 'Lava Insumos CI', false) RETURNING id INTO dep;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Outro depósito CI') RETURNING id INTO dep_b;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_estoque) VALUES (demo, 'LR-SHAMPOO-CI', 'Shampoo automotivo CI', 'L', 0, true) RETURNING id INTO shampoo;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, controla_estoque) VALUES (demo, 'LR-CERA-CI', 'Cera CI', 'UN', 0, true) RETURNING id INTO cera;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Insumo CI', '52998224725') RETURNING id INTO cli;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(shampoo, dep, 'entrada'::mov_tipo, 1, 'ci', 'ci');
  PERFORM registrar_movimentacao(cera, dep, 'entrada'::mov_tipo, 5, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'INS1A11', 'fabricante', 'Fiat', 'modelo', 'Mobi'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem insumos","preco_base":40}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador Insumos CI","comissao_percentual":0}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO serv_prod FROM lr_servicos WHERE id = serv;

  -- cadastro: só administrador e gestor; o insumo é produto com estoque
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_insumo_config_salvar(%L)$c$, dep), 'vendedor escolhe o depósito');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_servico_insumo_salvar(%L, %L, 1)$c$, serv, shampoo), 'estoquista cadastra receita');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_servico_insumo_salvar(%L, %L, 1)$c$, serv, shampoo), 'garçom cadastra receita');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_servico_insumo_salvar(%L, %L, 0)$c$, serv, shampoo), 'quantidade zero');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_servico_insumo_salvar(%L, %L, 1)$c$, serv, serv_prod), 'serviço como insumo (sem controle de estoque)');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_servico_insumo_salvar(%L, %L, 1)$c$, gen_random_uuid(), shampoo), 'serviço que não existe');
  PERFORM ci.deve_falhar(adm, format($c$SELECT lr_insumo_config_salvar(%L)$c$, gen_random_uuid()), 'depósito que não existe');
  PERFORM ci.entrar(gest);
  ins := lr_servico_insumo_salvar(serv, shampoo, 0.5);
  PERFORM lr_servico_insumo_salvar(serv, shampoo, 0.4);
  PERFORM lr_servico_insumo_salvar(serv, cera, 1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 2 AND bool_or(quantidade = 0.4) FROM lr_servico_insumos WHERE servico_id = serv), 'a receita guarda uma linha por insumo, com a última quantidade');

  -- sem configuração do depósito: entrega sem baixar nada
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o1, 'lavando'); PERFORM lr_ordem_situacao(o1, 'pronto');
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 0, 1, current_date + 30);
  PERFORM lr_ordem_retirar(o1, ped);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM lr_insumo_baixas WHERE ordem_id = o1), 'sem depósito configurado nada é baixado');

  -- configurado: baixa na entrega. Shampoo 0,4 (saldo 1) e cera 1 (saldo 5)
  PERFORM ci.entrar(gest);
  PERFORM lr_insumo_config_salvar(dep);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  o2 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o2, 'lavando'); PERFORM lr_ordem_situacao(o2, 'pronto');
  ped2 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 0, 1, current_date + 30);
  PERFORM lr_ordem_retirar(o2, ped2);
  PERFORM lr_ordem_retirar(o2, ped2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 2 AND bool_and(situacao = 'baixado') FROM lr_insumo_baixas WHERE ordem_id = o2), 'a entrega baixa os dois insumos, uma vez');
  PERFORM ci.exige((SELECT quantidade = 0.6 FROM estoques WHERE produto_id = shampoo AND deposito_id = dep) AND (SELECT quantidade = 4 FROM estoques WHERE produto_id = cera AND deposito_id = dep), 'o estoque do depósito baixou');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM estoque_movimentacoes WHERE produto_id = shampoo AND documento = 'LR-' || upper(left(o2::text, 8))), 'o movimento fica ligado à ordem pelo documento');

  -- venda cancelada e nova cobrança: a lavagem já foi feita, não baixa de novo
  UPDATE pedidos SET situacao = 'cancelado' WHERE id = ped2;
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_retirar(o2, pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 0, 1, current_date + 30));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 0.6 FROM estoques WHERE produto_id = shampoo AND deposito_id = dep), 'cobrar de novo depois de venda cancelada não baixa em dobro');

  -- falta de saldo: a entrega acontece, a falha fica registrada e dá para refazer
  PERFORM ci.entrar(gest);
  PERFORM lr_servico_insumo_salvar(serv, shampoo, 5);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  o3 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o3, 'lavando'); PERFORM lr_ordem_situacao(o3, 'pronto');
  r := lr_ordem_retirar(o3, pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 0, 1, current_date + 30));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'entregue' FROM lr_ordens WHERE id = o3), 'saldo insuficiente não trava a entrega');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM lr_comissoes WHERE ordem_id = o3) OR EXISTS (SELECT 1 FROM nfe WHERE pedido_id = (r ->> 'pedido_id')::uuid AND modelo = 'nfse'), 'a cobrança e a NFS-e seguem normais');
  PERFORM ci.exige((SELECT situacao = 'falhou' AND erro IS NOT NULL FROM lr_insumo_baixas WHERE ordem_id = o3 AND produto_id = shampoo), 'a baixa que faltou saldo fica como falhou, com o motivo');
  PERFORM ci.exige((SELECT situacao = 'baixado' FROM lr_insumo_baixas WHERE ordem_id = o3 AND produto_id = cera), 'o outro insumo da mesma ordem baixa normalmente');
  PERFORM ci.exige((SELECT quantidade = 0.6 FROM estoques WHERE produto_id = shampoo AND deposito_id = dep), 'a baixa que falhou não mexe no estoque');
  SELECT id INTO baixa FROM lr_insumo_baixas WHERE ordem_id = o3 AND produto_id = shampoo;
  PERFORM ci.deve_falhar(gest, format($c$SELECT lr_insumo_baixa_refazer(%L)$c$, baixa), 'refazer sem repor o estoque');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_insumo_baixa_refazer(%L)$c$, baixa), 'vendedor refaz baixa');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_insumo_baixa_refazer(%L)$c$, baixa), 'garçom refaz baixa');
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(shampoo, dep, 'entrada'::mov_tipo, 10, 'reposição', 'ci');
  PERFORM ci.sair();
  PERFORM ci.entrar(est);
  PERFORM lr_insumo_baixa_refazer(baixa);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'baixado' AND erro IS NULL FROM lr_insumo_baixas WHERE id = baixa), 'depois de repor, a baixa refeita fica baixada');
  PERFORM ci.exige((SELECT quantidade = 5.6 FROM estoques WHERE produto_id = shampoo AND deposito_id = dep), 'o estoque baixou na baixa refeita (0,6 + 10 − 5)');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_insumo_baixa_refazer(%L)$c$, baixa), 'refazer baixa que já foi feita');

  -- desligar: nada baixa
  PERFORM ci.entrar(gest);
  PERFORM lr_insumo_config_salvar(dep, false);
  PERFORM lr_servico_insumo_remover(ins);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM lr_servico_insumos WHERE id = ins), 'insumo removido da receita');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_servico_insumo_remover(%L)$c$, ins), 'vendedor remove insumo');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM lr_insumo_baixas') = 0 AND ci.contar(vend, 'SELECT count(*) FROM lr_insumo_baixas') >= 3, 'o garçom não lê baixas');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE lr_insumo_baixas SET situacao = 'baixado' WHERE id = %L$c$, baixa), 'alterar baixa direto');

  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_insumo_baixa_refazer(%L)$c$, baixa), 'refazer baixa com o módulo desligado');
END $$;

-- 71. Lava rápido (checklist de avarias): registrar, conferir "sem avarias", imutável depois de concluído, obrigatoriedade por empresa
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  cli uuid; v1 uuid; v2 uuid; serv uuid; lav uuid; o1 uuid; o2 uuid; av uuid; av2 uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Checklist CI', '52998224725') RETURNING id INTO cli;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'CHK1A11', 'fabricante', 'Fiat', 'modelo', 'Palio'));
  v2 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'helicoptero', 'identificacao', 'PRCHK', 'fabricante', 'Robinson', 'modelo', 'R44'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem checklist","preco_base":40}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador Checklist CI","comissao_percentual":0}'::jsonb);
  PERFORM ci.sair();

  -- sem exigência: lavar sem checklist continua valendo
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o1, 'lavando');
  PERFORM lr_ordem_situacao(o1, 'aguardando');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'aguardando' AND checklist_em IS NULL FROM lr_ordens WHERE id = o1), 'por padrão o checklist não é exigido');

  -- registrar avarias
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_avaria_registrar(%L, 'Capô', 'risco')$c$, o1), 'garçom registra avaria');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_avaria_registrar(%L, 'Capô', 'risco')$c$, o1), 'estoquista registra avaria');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_avaria_registrar(%L, 'Capô', 'risco')$c$, o1), 'anon registra avaria');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_avaria_registrar(%L, 'C', 'risco')$c$, o1), 'local curto demais');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_avaria_registrar(%L, 'Capô', 'quebrado')$c$, o1), 'tipo de avaria inválido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_avaria_registrar(%L, 'Capô', 'risco', repeat('x', 301))$c$, o1), 'descrição longa demais');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_avaria_registrar(%L, 'Capô', 'risco')$c$, gen_random_uuid()), 'ordem que não existe');
  PERFORM ci.entrar(vend);
  av := lr_avaria_registrar(o1, ' Capô ', 'risco', 'Risco de 10 cm');
  av2 := lr_avaria_registrar(o1, 'Porta direita', 'amassado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT lugar = 'Capô' AND tipo = 'risco' AND descricao = 'Risco de 10 cm' AND registrada_por = vend FROM lr_avarias WHERE id = av), 'a avaria guarda local, tipo, descrição e quem registrou');

  -- conferir: com avarias não dá para dizer que não há, e vice-versa
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_checklist_concluir(%L, true)$c$, o1), 'concluir sem avarias havendo avarias');
  PERFORM ci.entrar(vend);
  PERFORM lr_avaria_remover(av2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 1 FROM lr_avarias WHERE ordem_id = o1), 'enquanto o checklist está aberto dá para remover um engano');
  PERFORM ci.entrar(vend);
  PERFORM lr_checklist_concluir(o1, false);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT checklist_em IS NOT NULL AND checklist_por = vend AND NOT checklist_sem_avarias FROM lr_ordens WHERE id = o1), 'checklist concluído com avarias, com quem e quando');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_avaria_remover(%L)$c$, av), 'apagar avaria depois de concluído');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_checklist_concluir(%L, false)$c$, o1), 'concluir o checklist duas vezes');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM lr_avarias WHERE id = %L$c$, av), 'apagar avaria direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE lr_ordens SET checklist_em = NULL WHERE id = %L$c$, o1), 'desfazer o checklist direto');

  -- sem avarias
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_checklist_concluir(%L, false)$c$, (SELECT 'x')), 'ordem inválida no checklist');
  PERFORM ci.entrar(vend);
  o2 := lr_ordem_criar(jsonb_build_object('veiculo_id', v2, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_checklist_concluir(%L, false)$c$, o2), 'concluir com avarias sem registrar nenhuma');
  PERFORM ci.entrar(vend);
  PERFORM lr_checklist_concluir(o2, true);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT checklist_sem_avarias FROM lr_ordens WHERE id = o2), 'checklist concluído sem avarias');
  -- uma avaria achada depois: entra e o checklist deixa de dizer "sem avarias"
  PERFORM ci.entrar(vend);
  PERFORM lr_avaria_registrar(o2, 'Rotor de cauda', 'trinca', 'Achada na lavagem');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT NOT checklist_sem_avarias FROM lr_ordens WHERE id = o2), 'avaria achada depois tira o "sem avarias"');

  -- exigência por empresa
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_config_salvar(true)$c$, 'vendedor liga a exigência');
  PERFORM ci.deve_falhar(gar, $c$SELECT lr_config_salvar(true)$c$, 'garçom liga a exigência');
  PERFORM ci.entrar(gest);
  PERFORM lr_config_salvar(true);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o1, 'cancelada', 'libera');
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_situacao(%L, 'lavando')$c$, o1), 'lavar sem checklist quando a empresa exige');
  PERFORM ci.entrar(vend);
  PERFORM lr_checklist_concluir(o1, true);
  PERFORM lr_ordem_situacao(o1, 'lavando');
  PERFORM lr_ordem_situacao(o2, 'lavando');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'lavando' FROM lr_ordens WHERE id = o1) AND (SELECT situacao = 'lavando' FROM lr_ordens WHERE id = o2), 'com o checklist concluído a lavagem começa');

  -- encerrada: não registra mais
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o1, 'cancelada', 'teste');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_avaria_registrar(%L, 'Capô', 'risco')$c$, o1), 'avaria em ordem cancelada');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM lr_avarias') = 0 AND ci.contar(vend, 'SELECT count(*) FROM lr_avarias') >= 2, 'o garçom não lê avarias');
  PERFORM ci.entrar(gest);
  PERFORM lr_config_salvar(false);
  PERFORM ci.sair();

  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 72. Lava rápido (fotos): caminho reservado, envio só no caminho e por quem reservou, confirmação confere o arquivo, leitura só da empresa, cancelar sem apagar
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  cli uuid; v1 uuid; serv uuid; lav uuid; o1 uuid; o2 uuid; r jsonb; f1 uuid; f2 uuid; f3 uuid; c1 text; c2 text; c3 text; n int; tb uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Foto CI', '52998224725') RETURNING id INTO cli;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'aviao', 'identificacao', 'PTFOT', 'fabricante', 'Cessna', 'modelo', '172'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem fotos","preco_base":40}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador Fotos CI","comissao_percentual":0}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM ci.sair();

  -- reservar o caminho
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_foto_preparar(%L, 'antes', 'frente.jpg', 'image/jpeg', 2048)$c$, o1), 'garçom reserva foto');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_foto_preparar(%L, 'antes', 'frente.jpg', 'image/jpeg', 2048)$c$, o1), 'estoquista reserva foto');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_foto_preparar(%L, 'antes', 'frente.jpg', 'image/jpeg', 2048)$c$, o1), 'anon reserva foto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'durante', 'frente.jpg', 'image/jpeg', 2048)$c$, o1), 'momento inválido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'antes', 'doc.pdf', 'application/pdf', 2048)$c$, o1), 'formato que não é imagem');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'antes', 'grande.jpg', 'image/jpeg', 9000000)$c$, o1), 'foto de mais de 8 MB');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'antes', 'vazia.jpg', 'image/jpeg', 0)$c$, o1), 'foto vazia');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'antes', '', 'image/jpeg', 2048)$c$, o1), 'foto sem nome');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'antes', 'frente.jpg', 'image/jpeg', 2048)$c$, gen_random_uuid()), 'ordem que não existe');
  PERFORM ci.entrar(vend);
  r := lr_foto_preparar(o1, 'antes', 'frente.jpg', 'image/jpeg', 2048);
  PERFORM ci.sair();
  f1 := (r ->> 'id')::uuid; c1 := r ->> 'caminho';
  PERFORM ci.exige(c1 = demo::text || '/' || o1::text || '/' || f1::text || '.jpg', 'o caminho é empresa/ordem/id.extensão');
  PERFORM ci.exige((SELECT situacao = 'pendente' FROM lr_fotos WHERE id = f1), 'a foto nasce pendente');
  PERFORM ci.entrar(vend);
  PERFORM ci.exige(jsonb_array_length(lr_fotos_da_ordem(o1)) = 0, 'foto pendente não aparece na lista');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_confirmar(%L)$c$, f1), 'confirmar sem o arquivo enviado');

  -- envio: só no caminho reservado, só por quem reservou, só neste bucket
  PERFORM ci.deve_falhar(vend, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('lava-fotos', %L, %L, '{"size":2048,"mimetype":"image/jpeg"}')$c$, demo::text || '/' || o1::text || '/outra.jpg', vend), 'upload em caminho que não foi reservado');
  PERFORM ci.deve_falhar(gest, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('lava-fotos', %L, %L, '{"size":2048,"mimetype":"image/jpeg"}')$c$, c1, gest), 'upload de outra pessoa no caminho reservado');
  PERFORM ci.deve_falhar(gar, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('lava-fotos', %L, %L, '{"size":2048,"mimetype":"image/jpeg"}')$c$, c1, gar), 'upload do garçom no caminho reservado');
  PERFORM ci.deve_falhar(vend, format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('outro-bucket', %L, %L, '{"size":2048,"mimetype":"image/jpeg"}')$c$, c1, vend), 'o caminho reservado não vale em outro bucket');
  PERFORM ci.entrar(vend);
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('lava-fotos', %L, %L, '{"size":2048,"mimetype":"image/jpeg"}')$c$, c1, vend);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 1 FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = c1), 'quem reservou envia o arquivo no caminho reservado');

  -- confirmar: só quem reservou, e só se o arquivo confere
  PERFORM ci.deve_falhar(gest, format($c$SELECT lr_foto_confirmar(%L)$c$, f1), 'outra pessoa confirma a foto');
  PERFORM ci.entrar(vend);
  r := lr_foto_preparar(o1, 'depois', 'traseira.jpg', 'image/jpeg', 5000);
  PERFORM ci.sair();
  f2 := (r ->> 'id')::uuid; c2 := r ->> 'caminho';
  PERFORM ci.entrar(vend);
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('lava-fotos', %L, %L, '{"size":9999,"mimetype":"image/jpeg"}')$c$, c2, vend);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_confirmar(%L)$c$, f2), 'confirmar arquivo com tamanho diferente do informado');
  PERFORM ci.entrar(vend);
  PERFORM lr_foto_confirmar(f1);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'ativa' AND confirmada_em IS NOT NULL FROM lr_fotos WHERE id = f1), 'foto confirmada fica ativa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_confirmar(%L)$c$, f1), 'confirmar duas vezes');

  -- leitura: foto ativa da própria empresa e só para o pátio
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = %L$c$, c1)) = 1, 'o pátio lê a foto ativa');
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = %L$c$, c2)) = 0, 'foto ainda não confirmada não abre');
  PERFORM ci.exige(ci.contar(gar, format($c$SELECT count(*) FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = %L$c$, c1)) = 0, 'o garçom não lê foto');
  PERFORM ci.exige(ci.contar(est, format($c$SELECT count(*) FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = %L$c$, c1)) = 0, 'o estoquista não lê foto');
  INSERT INTO tenants (nome) VALUES ('Lava Fotos B') RETURNING id INTO tb;
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM lr_fotos WHERE tenant_id = tb), 'nenhuma foto de outra empresa');
  PERFORM ci.entrar(vend);
  r := lr_fotos_da_ordem(o1);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 ->> 'momento' = 'antes' AND (r -> 0 ->> 'pode_cancelar')::boolean, 'a lista traz só a foto ativa, com o caminho para o link temporário');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_fotos_da_ordem(%L)$c$, o1), 'garçom lista fotos');
  PERFORM ci.entrar(vend);
  r := lr_foto_preparar(o1, 'depois', 'lateral.jpg', 'image/jpeg', 3000);
  f3 := (r ->> 'id')::uuid; c3 := r ->> 'caminho';
  EXECUTE format($c$INSERT INTO storage.objects (bucket_id, name, owner, metadata) VALUES ('lava-fotos', %L, %L, '{"size":3000,"mimetype":"image/jpeg"}')$c$, c3, vend);
  PERFORM lr_foto_confirmar(f3);
  r := lr_fotos_contagem(ARRAY[o1]);
  PERFORM ci.sair();
  PERFORM ci.exige((r -> o1::text ->> 'antes')::int = 1 AND (r -> o1::text ->> 'depois')::int = 1, 'a contagem por ordem separa antes e depois');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_fotos_contagem(ARRAY[%L]::uuid[])$c$, o1), 'garçom conta fotos');

  -- nada de alterar nem apagar
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM lr_fotos WHERE id = %L$c$, f1), 'apagar foto direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE lr_fotos SET momento = 'depois' WHERE id = %L$c$, f1), 'trocar dados da foto direto');
  PERFORM ci.exige(ci.contar(vend, format($c$WITH d AS (DELETE FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = %L RETURNING 1) SELECT count(*) FROM d$c$, c1)) = 0, 'apagar o arquivo não afeta nenhuma linha');
  PERFORM ci.exige(ci.contar(adm, format($c$WITH u AS (UPDATE storage.objects SET name = 'x' WHERE bucket_id = 'lava-fotos' AND name = %L RETURNING 1) SELECT count(*) FROM u$c$, c1)) = 0, 'trocar o arquivo não afeta nenhuma linha');
  PERFORM ci.exige((SELECT count(*) = 1 FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = c1), 'o arquivo continua no armazenamento');

  -- cancelar com motivo: quem enviou ou gestão
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_cancelar(%L, '')$c$, f1), 'cancelar sem motivo');
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_foto_cancelar(%L, 'engano')$c$, f1), 'garçom cancela foto');
  PERFORM ci.entrar(gest);
  PERFORM lr_foto_cancelar(f1, 'foto de outro veículo');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND cancelada_motivo = 'foto de outro veículo' AND cancelada_por = gest FROM lr_fotos WHERE id = f1), 'foto cancelada guarda motivo e quem cancelou');
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM storage.objects WHERE bucket_id = 'lava-fotos' AND name = %L$c$, c1)) = 0, 'foto cancelada deixa de abrir');
  PERFORM ci.deve_falhar(gest, format($c$SELECT lr_foto_cancelar(%L, 'de novo')$c$, f1), 'cancelar foto já cancelada');

  -- limite de 12 por ordem e momento
  PERFORM ci.entrar(vend);
  FOR n IN 1..10 LOOP
    PERFORM lr_foto_preparar(o1, 'depois', 'f' || n || '.jpg', 'image/jpeg', 1000 + n);
  END LOOP;
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'depois', 'excesso.jpg', 'image/jpeg', 1000)$c$, o1), 'passar de 12 fotos por ordem e momento');

  -- ordem cancelada e módulo desligado
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o1, 'cancelada', 'teste');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_foto_preparar(%L, 'antes', 'x.jpg', 'image/jpeg', 1000)$c$, o1), 'foto em ordem cancelada');
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 73. Lava rápido (painel Ze Tech): só a equipe Ze Tech, só lojas com o módulo liberado, números do período
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  op   constant uuid := 'a0000000-0000-0000-0000-0000000000c7';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  cs uuid; cli uuid; dep uuid; v1 uuid; serv uuid; serv_prod uuid; lav uuid; o1 uuid; ped uuid; r jsonb; l jsonb; t_sem uuid; c_sem uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO auth.users (id, email) VALUES (op, 'operador-lava@ci');
  INSERT INTO saas_operadores (user_id) VALUES (op);
  INSERT INTO saas_clientes (nome, tenant_id) VALUES ('Lava Painel CI', demo) RETURNING id INTO cs;
  INSERT INTO tenants (nome) VALUES ('Loja sem lava CI') RETURNING id INTO t_sem;
  INSERT INTO saas_clientes (nome, tenant_id) VALUES ('Sem Lava Painel CI', t_sem) RETURNING id INTO c_sem;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Lava Painel CI') RETURNING id INTO dep;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Painel CI', '52998224725') RETURNING id INTO cli;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'PNL1A11', 'fabricante', 'Fiat', 'modelo', 'Uno'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem painel","preco_base":50}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador Painel CI","comissao_percentual":10}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO serv_prod FROM lr_servicos WHERE id = serv;
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o1, 'lavando'); PERFORM lr_ordem_situacao(o1, 'pronto');
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 50)), 'crediario', cli, 0, 1, current_date + 30);
  PERFORM lr_ordem_retirar(o1, ped);
  PERFORM ci.sair();

  -- acesso
  PERFORM ci.deve_falhar(adm, $c$SELECT saas_lava_rapido_por_cliente(current_date - 30, current_date)$c$, 'administrador da loja lê o painel Ze Tech');
  PERFORM ci.deve_falhar(vend, $c$SELECT saas_lava_rapido_por_cliente(current_date - 30, current_date)$c$, 'vendedor lê o painel Ze Tech');
  PERFORM ci.deve_falhar(gar, $c$SELECT saas_lava_rapido_por_cliente(current_date - 30, current_date)$c$, 'garçom lê o painel Ze Tech');
  PERFORM ci.deve_falhar(NULL, $c$SELECT saas_lava_rapido_por_cliente(current_date - 30, current_date)$c$, 'anon lê o painel Ze Tech');
  PERFORM ci.deve_falhar(op, $c$SELECT saas_lava_rapido_por_cliente(current_date, current_date - 1)$c$, 'período invertido');
  PERFORM ci.deve_falhar(op, $c$SELECT saas_lava_rapido_por_cliente(NULL, current_date)$c$, 'período sem início');

  -- números
  PERFORM ci.entrar(op);
  r := saas_lava_rapido_por_cliente(current_date - 30, current_date);
  PERFORM ci.sair();
  SELECT e INTO l FROM jsonb_array_elements(r) e WHERE e ->> 'cliente_id' = cs::text;
  PERFORM ci.exige(l IS NOT NULL, 'a loja com o módulo liberado aparece');
  PERFORM ci.exige((l ->> 'entregues')::int >= 1 AND (l ->> 'faturamento')::numeric >= 50 AND (l ->> 'veiculos')::int >= 1, 'entregues, faturamento e veículos');
  PERFORM ci.exige((l ->> 'comissoes_a_pagar')::numeric >= 5, 'comissão a pagar da loja');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'cliente_id' = c_sem::text), 'loja sem o módulo não aparece');
  PERFORM ci.entrar(op);
  r := saas_lava_rapido_por_cliente(current_date + 5, current_date + 10);
  PERFORM ci.sair();
  SELECT e INTO l FROM jsonb_array_elements(r) e WHERE e ->> 'cliente_id' = cs::text;
  PERFORM ci.exige((l ->> 'entregues')::int = 0 AND (l ->> 'faturamento')::numeric = 0 AND (l ->> 'ticket_medio')::numeric = 0, 'período sem movimento zera entregues e faturamento');

  -- módulo desligado: a loja sai do painel
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
  PERFORM ci.entrar(op);
  r := saas_lava_rapido_por_cliente(current_date - 30, current_date);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'cliente_id' = cs::text), 'sem o módulo a loja sai do painel');
END $$;

-- 74. Lava rápido (NFS-e com desconto): o ISS é calculado sobre o valor líquido, com o desconto rateado entre os itens da nota
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  ramo_ant text; cnae_ant text; cnae2_ant text; iss_ant numeric; criou_cfg boolean := false;
  cli uuid; dep uuid; v1 uuid; v2 uuid; s1 uuid; s2 uuid; s3 uuid; p1 uuid; p2 uuid; p3 uuid; plano uuid; plano_prod uuid; lav uuid;
  o1 uuid; ped uuid; r jsonb; nf uuid; ass uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  IF NOT EXISTS (SELECT 1 FROM fiscal_config WHERE tenant_id = demo AND filial_id IS NULL) THEN
    INSERT INTO fiscal_config (tenant_id, empresa_id) SELECT demo, id FROM empresas WHERE tenant_id = demo ORDER BY created_at, id LIMIT 1;
    criou_cfg := true;
  END IF;
  SELECT aliquota_iss INTO iss_ant FROM fiscal_config WHERE tenant_id = demo AND filial_id IS NULL ORDER BY (empresa_id IS NULL), created_at LIMIT 1;
  UPDATE fiscal_config SET aliquota_iss = 5 WHERE tenant_id = demo;

  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Lava NFSe CI') RETURNING id INTO dep;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente NFSe CI', '52998224725') RETURNING id INTO cli;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'NFS1A11', 'fabricante', 'Fiat', 'modelo', 'Argo'));
  v2 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'moto', 'identificacao', 'NFS2B22', 'fabricante', 'Honda', 'modelo', 'Biz'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  s1 := lr_servico_salvar('{"nome":"NFSe serviço A","preco_base":30}'::jsonb);
  s2 := lr_servico_salvar('{"nome":"NFSe serviço B","preco_base":30}'::jsonb);
  s3 := lr_servico_salvar('{"nome":"NFSe serviço C","preco_base":40}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador NFSe CI","comissao_percentual":0}'::jsonb);
  plano := lr_plano_salvar(jsonb_build_object('nome','Plano NFSe CI','servico_id',s1,'lavagens',4,'preco',100));
  PERFORM ci.sair();
  SELECT produto_id INTO p1 FROM lr_servicos WHERE id = s1;
  SELECT produto_id INTO p2 FROM lr_servicos WHERE id = s2;
  SELECT produto_id INTO p3 FROM lr_servicos WHERE id = s3;
  SELECT produto_id INTO plano_prod FROM lr_planos WHERE id = plano;

  -- três serviços (30 + 30 + 40 = 100) com desconto de 10: líquido 90, ISS de 5% = 4,50
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(s1, s2, s3)));
  PERFORM lr_ordem_situacao(o1, 'lavando'); PERFORM lr_ordem_situacao(o1, 'pronto');
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', p1, 'quantidade', 1, 'preco_unitario', 30),
                                          jsonb_build_object('produto_id', p2, 'quantidade', 1, 'preco_unitario', 30),
                                          jsonb_build_object('produto_id', p3, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 10, 1, current_date + 30);
  r := lr_ordem_retirar(o1, ped);
  PERFORM ci.sair();
  nf := (r ->> 'nfe_id')::uuid;
  PERFORM ci.exige((SELECT valor_total = 90 AND valor_produtos = 100 AND valor_desconto = 10 FROM nfe WHERE id = nf), 'a NFS-e mostra bruto, desconto e líquido');
  PERFORM ci.exige((SELECT sum(total) = 90 AND sum(desconto) = 10 FROM nfe_itens WHERE nfe_id = nf), 'o desconto é rateado entre os itens e os totais somam o líquido');
  PERFORM ci.exige((SELECT sum(valor_iss) = 4.50 FROM nfe_itens WHERE nfe_id = nf), 'o ISS dos itens é sobre o valor líquido');
  PERFORM ci.exige((SELECT valor_iss = 4.50 FROM nfe WHERE id = nf), 'o ISS do cabeçalho é sobre o valor líquido');

  -- plano de 100 vendido com desconto de 10: a nota do plano também fica com 90 e ISS de 4,50
  PERFORM ci.entrar(vend);
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', plano_prod, 'quantidade', 1, 'preco_unitario', 100)), 'crediario', cli, 10, 1, current_date + 30);
  r := lr_plano_vender(plano, v2, ped);
  PERFORM ci.sair();
  nf := (r ->> 'nfe_id')::uuid;
  ass := (r ->> 'assinatura_id')::uuid;
  PERFORM ci.exige((SELECT valor = 90 FROM lr_assinaturas WHERE id = ass), 'a assinatura guarda o valor líquido');
  PERFORM ci.exige((SELECT valor_total = 90 AND valor_iss = 4.50 FROM nfe WHERE id = nf), 'a NFS-e do plano tem total e ISS sobre o valor líquido');
  PERFORM ci.exige((SELECT total = 90 AND desconto = 10 AND valor_iss = 4.50 FROM nfe_itens WHERE nfe_id = nf), 'o item da NFS-e do plano guarda o desconto e o total líquido');

  -- sem desconto: o item fica com o preço cheio e sem desconto
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v2, 'lavador_id', lav, 'servicos', jsonb_build_array(s3)));
  PERFORM lr_ordem_situacao(o1, 'lavando'); PERFORM lr_ordem_situacao(o1, 'pronto');
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', p3, 'quantidade', 1, 'preco_unitario', 40)), 'crediario', cli, 0, 1, current_date + 30);
  r := lr_ordem_retirar(o1, ped);
  PERFORM ci.sair();
  nf := (r ->> 'nfe_id')::uuid;
  PERFORM ci.exige((SELECT total = 40 AND desconto = 0 AND valor_iss = 2.00 FROM nfe_itens WHERE nfe_id = nf), 'sem desconto o item fica com o preço cheio e ISS de 5%');

  UPDATE fiscal_config SET aliquota_iss = coalesce(iss_ant, 0) WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 75. Módulos (cadastro de produto): campos próprios em dados_modulo conferidos pelo módulo da empresa, Lava-Rápido liberado pelo módulo principal
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  p uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;

  -- Pet Shop
  UPDATE empresas SET ramo_atividade = 'petshop', cnae = '4789-0/99', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, dados_modulo)
  VALUES (demo, 'MOD-PET-CI', 'Ração CI', 'UN', 10, '{"especie":"cao","porte":"medio","fase_vida":"adulto","sabor_linha":"frango","peso_embalagem_kg":15,"registro_mapa":"123"}')
  RETURNING id INTO p;
  PERFORM ci.exige((SELECT dados_modulo ->> 'especie' = 'cao' AND (dados_modulo ->> 'peso_embalagem_kg')::numeric = 15 FROM produtos WHERE id = p), 'pet shop guarda os campos do módulo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"especie":"dragao"}' WHERE id = %L$c$, p), 'espécie fora da lista');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"principio_ativo":"x"}' WHERE id = %L$c$, p), 'campo de outro módulo no pet shop');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"peso_embalagem_kg":-1}' WHERE id = %L$c$, p), 'peso negativo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"peso_embalagem_kg":"quinze"}' WHERE id = %L$c$, p), 'peso em texto');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = jsonb_build_object('sabor_linha', repeat('x', 121)) WHERE id = %L$c$, p), 'texto com mais de 120 caracteres');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '["cao"]' WHERE id = %L$c$, p), 'dados do módulo que não são um objeto');
  -- atualizar o produto sem mexer nos dados do módulo nunca é barrado
  UPDATE produtos SET custo = 5 WHERE id = p;
  PERFORM ci.exige((SELECT custo = 5 FROM produtos WHERE id = p), 'atualizar outro campo do produto continua valendo');

  -- Clínica Veterinária
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  UPDATE produtos SET dados_modulo = '{"tipo":"vacina","conservacao":"refrigerado","controlado":false,"via_administracao":"injetavel"}' WHERE id = p;
  PERFORM ci.exige((SELECT dados_modulo ->> 'tipo' = 'vacina' FROM produtos WHERE id = p), 'clínica guarda tipo, conservação e via');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"tipo":"brinquedo"}' WHERE id = %L$c$, p), 'tipo de produto da clínica fora da lista');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"controlado":"sim"}' WHERE id = %L$c$, p), 'controlado que não é sim ou não');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"especie":"cao"}' WHERE id = %L$c$, p), 'campo do pet shop na clínica');

  -- Material de Construção
  UPDATE empresas SET ramo_atividade = 'construcao' WHERE tenant_id = demo;
  UPDATE produtos SET dados_modulo = '{"linha_aplicacao":"hidráulica","bitola_medida":"3/4\"","venda_fracionada":"m"}' WHERE id = p;
  PERFORM ci.exige((SELECT dados_modulo ->> 'venda_fracionada' = 'm' FROM produtos WHERE id = p), 'construção guarda os campos do módulo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"venda_fracionada":"litro"}' WHERE id = %L$c$, p), 'venda fracionada fora da lista');
  -- o padrão da empresa sem ramo definido é construção
  PERFORM ci.exige(public._produto_dados_modulo_erro(NULL, '{"cor_acabamento":"branco"}') IS NULL, 'sem ramo vale o cadastro de construção');

  -- Lava-Rápido
  UPDATE empresas SET ramo_atividade = 'lavarapido' WHERE tenant_id = demo;
  UPDATE produtos SET dados_modulo = '{"tipo":"insumo","rendimento_lavagens":40,"perigoso":true}' WHERE id = p;
  PERFORM ci.exige((SELECT dados_modulo ->> 'tipo' = 'insumo' AND (dados_modulo ->> 'perigoso')::boolean FROM produtos WHERE id = p), 'lava-rápido guarda os campos do módulo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"tipo":"servico"}' WHERE id = %L$c$, p), 'tipo do lava-rápido fora da lista');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM (SELECT lava_rapido_liberado() AS l) x WHERE l') = 1, 'o módulo principal Lava-Rápido libera o módulo sem CNAE');

  -- ramo sem cadastro próprio (restaurante, roupas…): nada de dados de módulo
  UPDATE empresas SET ramo_atividade = 'roupas' WHERE tenant_id = demo;
  PERFORM ci.deve_falhar_dono(format($c$UPDATE produtos SET dados_modulo = '{"tipo":"insumo"}' WHERE id = %L$c$, p), 'dados de módulo em empresa de outro ramo');
  UPDATE produtos SET dados_modulo = '{}' WHERE id = p;
  PERFORM ci.exige((SELECT dados_modulo = '{}'::jsonb FROM produtos WHERE id = p), 'limpar os dados do módulo é sempre possível');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM (SELECT lava_rapido_liberado() AS l) x WHERE l') = 0, 'sem o módulo Lava-Rápido, ramo de roupas não libera');

  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 76. WhatsApp automático: fila só pelo banco, número vem do cadastro do cliente, uma mensagem por ocasião, resultado e entrega só pelo serviço, SAIR, automático depois de ligar
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  inst text := public.wa_nome_instancia('11111111-1111-1111-1111-111111111111');
  cli uuid; cli_no uuid; cli_tel uuid; cli_lid uuid; v1 uuid; v2 uuid; v3 uuid; v4 uuid; v5 uuid; serv uuid; lav uuid;
  o1 uuid; o2 uuid; o3 uuid; o4 uuid; o5 uuid; m1 uuid; m2 uuid; r jsonb; n int;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone, whatsapp) VALUES (demo, 'Cliente WhatsApp CI', '52998224725', '11999990000', '(11) 98888-7777') RETURNING id INTO cli;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone, aceita_mensagens) VALUES (demo, 'Cliente Sem Msg WA CI', '11144477735', '11977776666', false) RETURNING id INTO cli_no;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone) VALUES (demo, 'Cliente Sem Telefone WA CI', '39053344705', '123') RETURNING id INTO cli_tel;
  INSERT INTO clientes (tenant_id, nome, cpf, telefone) VALUES (demo, 'Cliente Lid WA CI', '12345678909', '21955554444') RETURNING id INTO cli_lid;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'WAP1A11', 'fabricante', 'Fiat', 'modelo', 'Argo'));
  v2 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_no, 'tipo', 'carro', 'identificacao', 'WAP2B22', 'fabricante', 'VW', 'modelo', 'Polo'));
  v3 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_tel, 'tipo', 'carro', 'identificacao', 'WAP3C33', 'fabricante', 'GM', 'modelo', 'Onix'));
  v4 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'moto', 'identificacao', 'WAP4D44', 'fabricante', 'Honda', 'modelo', 'Biz'));
  v5 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_lid, 'tipo', 'carro', 'identificacao', 'WAP5E55', 'fabricante', 'Fiat', 'modelo', 'Mobi'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := lr_servico_salvar('{"nome":"Lavagem WhatsApp","preco_base":40}'::jsonb);
  lav := lr_lavador_salvar('{"nome":"Lavador WhatsApp CI","comissao_percentual":0}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  o1 := lr_ordem_criar(jsonb_build_object('veiculo_id', v1, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  o2 := lr_ordem_criar(jsonb_build_object('veiculo_id', v2, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  o3 := lr_ordem_criar(jsonb_build_object('veiculo_id', v3, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  o4 := lr_ordem_criar(jsonb_build_object('veiculo_id', v4, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  o5 := lr_ordem_criar(jsonb_build_object('veiculo_id', v5, 'lavador_id', lav, 'servicos', jsonb_build_array(serv)));
  PERFORM lr_ordem_situacao(o1, 'lavando'); PERFORM lr_ordem_situacao(o1, 'pronto');
  PERFORM lr_ordem_situacao(o2, 'lavando'); PERFORM lr_ordem_situacao(o2, 'pronto');
  PERFORM lr_ordem_situacao(o3, 'lavando'); PERFORM lr_ordem_situacao(o3, 'pronto');
  PERFORM lr_ordem_situacao(o5, 'lavando'); PERFORM lr_ordem_situacao(o5, 'pronto');
  PERFORM ci.sair();

  PERFORM ci.exige(inst = 'zt-' || left(replace(demo::text, '-', ''), 16), 'nome da instância derivado da empresa');

  -- sem conexão não enfileira; quem não é do atendimento não enfileira
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o1::text), 'enfileirar com o WhatsApp desconectado');
  INSERT INTO wa_config (tenant_id, instancia, estado, numero, conectada_em) VALUES (demo, inst, 'conectada', '5511900001111', now());
  PERFORM ci.deve_falhar(gar, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o1::text), 'garçom enfileira');
  PERFORM ci.deve_falhar(est, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o1::text), 'estoquista enfileira');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o1::text), 'anon enfileira');
  PERFORM ci.deve_falhar(vend, $c$SELECT wa_enfileirar('aniversario', gen_random_uuid()::text)$c$, 'tipo inválido');
  PERFORM ci.deve_falhar(vend, $c$SELECT wa_enfileirar('pronto', 'não-é-uuid')$c$, 'referência inválida');
  PERFORM ci.deve_falhar(vend, $c$SELECT wa_enfileirar('pronto', gen_random_uuid()::text)$c$, 'referência que não existe');
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o2::text), 'cliente que não aceita mensagens');
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o3::text), 'cliente sem telefone válido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_enfileirar('retorno', %L)$c$, o1::text), 'retorno de ordem que não foi entregue');

  -- tabelas e rotinas de serviço não se mexem como usuário
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO wa_mensagens (tenant_id, tipo, referencia, cliente_id, veiculo_id, numero) VALUES (%L, 'pronto', 'x', %L, %L, '5511999990000')$c$, demo, cli, v1), 'inserir mensagem direto');
  PERFORM ci.deve_falhar(adm, $c$UPDATE wa_config SET estado = 'conectada'$c$, 'alterar a conexão direto');
  PERFORM ci.deve_falhar(adm, $c$SELECT wa_reservar(10, 2, true)$c$, 'reservar como usuário');
  PERFORM ci.deve_falhar(adm, $c$SELECT wa_auto_varrer()$c$, 'varrer como usuário');
  PERFORM ci.deve_falhar(adm, $c$SELECT wa_saida_registrar('x', '5511999990000', NULL)$c$, 'registrar saída como usuário');
  PERFORM ci.deve_falhar(adm, $c$SELECT wa_status('x', 'y', 'lida')$c$, 'registrar entrega como usuário');
  PERFORM ci.deve_falhar(adm, format($c$SELECT wa_resultado(%L, true, 'x', NULL, NULL, NULL)$c$, gen_random_uuid()), 'registrar resultado como usuário');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM wa_mensagens') = 0, 'garçom não lê a fila');

  PERFORM ci.deve_falhar(vend, $c$SELECT wa_exige_gestor()$c$, 'vendedor passa pela conferência de gestor');
  PERFORM ci.deve_falhar(gar, $c$SELECT wa_exige_gestor()$c$, 'garçom passa pela conferência de gestor');
  PERFORM ci.deve_falhar(NULL, $c$SELECT wa_exige_gestor()$c$, 'anon passa pela conferência de gestor');
  PERFORM ci.exige(ci.contar(gest, 'SELECT count(*) FROM (SELECT wa_exige_gestor() AS t) x WHERE t = ''11111111-1111-1111-1111-111111111111''') = 1, 'gestor passa pela conferência e recebe a empresa');

  -- enfileirar: número vem do cadastro do cliente (só dígitos, com DDI), uma mensagem por ocasião
  PERFORM ci.entrar(vend);
  m1 := wa_enfileirar('pronto', o1::text);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT numero = '5511988887777' AND situacao = 'na_fila' AND origem = 'manual' AND variaveis ->> 'veiculo' = 'WAP1A11' AND variaveis ->> 'cliente' = 'Cliente WhatsApp CI'
                      FROM wa_mensagens WHERE id = m1), 'mensagem na fila com o WhatsApp do cadastro e os dados do aviso');
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o1::text), 'enfileirar a mesma ocasião duas vezes');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM wa_mensagens') >= 1, 'recepção lê a fila');

  -- reservar: só o que é da hora, uma vez só, automático respeita o horário
  r := wa_reservar(10, 2, false);
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 ->> 'id' = m1::text AND r -> 0 ->> 'instancia' = inst AND r -> 0 ->> 'numero' = '5511988887777'
                     AND r -> 0 ->> 'loja' IS NOT NULL AND (r -> 0 ->> 'tentativas')::int = 1, 'reservar traz o envio com instância, número e loja');
  PERFORM ci.exige(jsonb_array_length(wa_reservar(10, 2, false)) = 0, 'reservar de novo não repete o envio');
  PERFORM ci.exige((SELECT situacao = 'enviando' FROM wa_mensagens WHERE id = m1), 'mensagem reservada fica enviando');

  -- falha com nova tentativa volta para a fila só na hora marcada
  PERFORM wa_resultado(m1, false, NULL, NULL, 'servidor fora do ar', now() + interval '10 minutes');
  PERFORM ci.exige((SELECT situacao = 'na_fila' AND erro = 'servidor fora do ar' AND tentativas = 1 FROM wa_mensagens WHERE id = m1), 'falha com nova tentativa volta para a fila');
  PERFORM ci.exige(jsonb_array_length(wa_reservar(10, 2, false)) = 0, 'antes da hora marcada não reserva');
  UPDATE wa_mensagens SET proxima_tentativa = now() - interval '1 minute' WHERE id = m1;
  r := wa_reservar(10, 2, false);
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND (r -> 0 ->> 'tentativas')::int = 2, 'na hora marcada reserva de novo, na segunda tentativa');

  -- enviada: sai da lista de chamadas do lava rápido, e resultado repetido não faz nada
  PERFORM wa_resultado(m1, true, 'EVO-1', '5511988887777@s.whatsapp.net', NULL, NULL);
  PERFORM wa_resultado(m1, false, NULL, NULL, 'repetido', NULL);
  PERFORM ci.exige((SELECT situacao = 'enviada' AND id_externo = 'EVO-1' AND enviada_em IS NOT NULL AND erro IS NULL FROM wa_mensagens WHERE id = m1), 'enviada guarda o id do WhatsApp e ignora resultado repetido');
  PERFORM ci.exige((SELECT count(*) = 1 FROM lr_contatos WHERE tipo = 'pronto' AND referencia = o1::text AND canal = 'whatsapp'), 'enviada registra o contato do lava rápido');
  PERFORM ci.entrar(vend);
  r := lr_mensagens_pendentes('pronto');
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'referencia' = o1::text), 'enviado pelo sistema sai da lista de avisos');

  -- entrega e leitura só avançam
  PERFORM wa_status(inst, 'EVO-1', 'entregue');
  PERFORM ci.exige((SELECT situacao = 'entregue' FROM wa_mensagens WHERE id = m1), 'entrega registrada');
  PERFORM wa_status(inst, 'EVO-1', 'lida');
  PERFORM wa_status(inst, 'EVO-1', 'entregue');
  PERFORM wa_status('outra-instancia', 'EVO-1', 'lida');
  PERFORM ci.exige((SELECT situacao = 'lida' FROM wa_mensagens WHERE id = m1), 'leitura registrada e nunca volta para entregue');

  -- esgotou as tentativas: falhou, e a recepção pode reenviar
  PERFORM ci.entrar(vend);
  m2 := wa_enfileirar('pronto', o5::text);
  PERFORM ci.sair();
  PERFORM wa_reservar(10, 2, false);
  PERFORM wa_resultado(m2, false, NULL, NULL, 'número não existe no WhatsApp', NULL);
  PERFORM ci.exige((SELECT situacao = 'falhou' AND erro LIKE 'número não existe%' FROM wa_mensagens WHERE id = m2), 'sem nova tentativa a mensagem fica como falha');
  PERFORM ci.deve_falhar(gar, format($c$SELECT wa_mensagem_reenviar(%L)$c$, m2), 'garçom reenvia');
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_mensagem_reenviar(%L)$c$, m1), 'reenviar mensagem já lida');
  PERFORM ci.entrar(vend);
  PERFORM wa_mensagem_reenviar(m2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'na_fila' AND tentativas = 0 AND erro IS NULL FROM wa_mensagens WHERE id = m2), 'reenviar põe a falha de volta na fila, zerando as tentativas');
  PERFORM ci.deve_falhar(gar, format($c$SELECT wa_mensagem_cancelar(%L)$c$, m2), 'garçom cancela');
  PERFORM ci.entrar(vend);
  PERFORM wa_mensagem_cancelar(m2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM wa_mensagens WHERE id = m2), 'cancelar tira da fila');
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_mensagem_cancelar(%L)$c$, m1), 'cancelar mensagem já enviada');

  -- envio interrompido há mais de 5 minutos vira falha (não reenvia sozinho)
  PERFORM ci.entrar(vend);
  PERFORM wa_mensagem_reenviar(m2);
  PERFORM ci.sair();
  PERFORM wa_reservar(10, 2, false);
  ALTER TABLE wa_mensagens DISABLE TRIGGER trg_wa_mensagens_updated;
  UPDATE wa_mensagens SET updated_at = now() - interval '10 minutes' WHERE id = m2;
  ALTER TABLE wa_mensagens ENABLE TRIGGER trg_wa_mensagens_updated;
  PERFORM wa_reservar(10, 2, false);
  PERFORM ci.exige((SELECT situacao = 'falhou' AND erro LIKE 'Envio interrompido%' FROM wa_mensagens WHERE id = m2), 'envio travado vira falha para conferência');

  -- automático: só quem gerencia liga, só vale depois de ligar, só dentro do horário
  PERFORM ci.deve_falhar(vend, $c$SELECT wa_automatico_salvar(true, false)$c$, 'vendedor liga o automático');
  PERFORM ci.deve_falhar(gar, $c$SELECT wa_automatico_salvar(true, false)$c$, 'garçom liga o automático');
  UPDATE lr_ordens SET pronto_em = now() - interval '2 hours' WHERE id = o3;
  UPDATE lr_ordens SET pronto_em = now() - interval '3 hours' WHERE id = o2;
  PERFORM ci.exige(wa_auto_varrer() = 0, 'sem o automático ligado a varredura não enfileira nada');
  PERFORM ci.entrar(gest);
  PERFORM wa_automatico_salvar(true, false);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT auto_pronto AND NOT auto_plano AND auto_desde IS NOT NULL FROM wa_config WHERE tenant_id = demo), 'automático de pronto ligado');
  UPDATE lr_ordens SET pronto_em = now() - interval '2 hours' WHERE id IN (o1, o5);
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o4, 'lavando'); PERFORM lr_ordem_situacao(o4, 'pronto');
  PERFORM ci.sair();
  n := wa_auto_varrer();
  PERFORM ci.exige(n = 1, 'a varredura enfileira só o veículo que ficou pronto depois de ligar (e que pode receber)');
  PERFORM ci.exige((SELECT origem = 'automatico' AND situacao = 'na_fila' FROM wa_mensagens WHERE tipo = 'pronto' AND referencia = o4::text), 'mensagem automática na fila');
  PERFORM ci.exige(wa_auto_varrer() = 0, 'varrer de novo não duplica');
  PERFORM ci.exige(jsonb_array_length(wa_reservar(10, 2, false)) = 0, 'automático fora do horário espera');
  -- consentimento reconferido na hora de enviar: quem deixou de aceitar mensagens depois de entrar na fila não recebe
  UPDATE wa_mensagens SET situacao = 'na_fila', erro = NULL, tentativas = 0, proxima_tentativa = now() - interval '1 minute' WHERE tipo = 'pronto' AND referencia = o4::text;
  UPDATE clientes SET aceita_mensagens = false WHERE id = cli;
  PERFORM ci.exige(jsonb_array_length(wa_reservar(10, 2, true)) = 0, 'cliente que deixou de aceitar mensagens não recebe o que estava na fila');
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND erro LIKE 'O cliente não pode mais receber%' FROM wa_mensagens WHERE tipo = 'pronto' AND referencia = o4::text), 'mensagem da fila é cancelada quando o cliente deixa de aceitar');
  UPDATE clientes SET aceita_mensagens = true, whatsapp = '(11) 97777-1234' WHERE id = cli;
  UPDATE wa_mensagens SET situacao = 'na_fila', erro = NULL, tentativas = 0, proxima_tentativa = now() - interval '1 minute' WHERE tipo = 'pronto' AND referencia = o4::text;
  r := wa_reservar(10, 2, true);
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 ->> 'numero' = '5511977771234', 'telefone trocado depois de entrar na fila: envia para o número de agora');
  UPDATE wa_mensagens SET situacao = 'na_fila', tentativas = 0 WHERE id = (r -> 0 ->> 'id')::uuid;
  UPDATE clientes SET whatsapp = '(11) 98888-7777' WHERE id = cli;

  -- desligar o automático cancela o que ficou na fila, sem mexer no manual
  PERFORM ci.entrar(gest);
  PERFORM wa_automatico_salvar(false, false);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(wa_reservar(10, 2, true)) = 0, 'automático desligado não envia o que ficou na fila');
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND erro = 'Envio automático desligado' FROM wa_mensagens WHERE tipo = 'pronto' AND referencia = o4::text), 'mensagem automática da fila é cancelada ao desligar');
  PERFORM ci.entrar(gest);
  PERFORM wa_automatico_salvar(true, false);
  PERFORM ci.sair();
  UPDATE wa_mensagens SET situacao = 'na_fila', erro = NULL, tentativas = 0 WHERE tipo = 'pronto' AND referencia = o4::text;
  PERFORM ci.exige(jsonb_array_length(wa_reservar(10, 2, true)) = 1, 'automático dentro do horário sai');
  PERFORM wa_resultado((SELECT id FROM wa_mensagens WHERE tipo = 'pronto' AND referencia = o4::text), true, 'EVO-4', '5511988887777@s.whatsapp.net', NULL, NULL);

  -- desconectar desliga o envio: nada é reservado
  UPDATE wa_config SET estado = 'desconectada' WHERE tenant_id = demo;
  PERFORM ci.exige(wa_auto_varrer() = 0, 'desconectada não varre');
  UPDATE wa_config SET estado = 'conectada' WHERE tenant_id = demo;

  -- SAIR: some das mensagens, cancela a fila, vale por número e por endereço oculto
  UPDATE clientes SET aceita_mensagens = true WHERE id = cli_lid;
  INSERT INTO wa_mensagens (tenant_id, tipo, referencia, cliente_id, veiculo_id, numero, situacao, jid, id_externo, enviada_em)
  VALUES (demo, 'retorno', gen_random_uuid()::text, cli_lid, v5, '5521955554444', 'enviada', '99887766@lid', 'EVO-9', now());
  PERFORM ci.exige(wa_saida_registrar(inst, NULL, '99887766@lid') = 1, 'SAIR por endereço oculto acha o cliente pelo envio anterior');
  PERFORM ci.exige((SELECT NOT aceita_mensagens FROM clientes WHERE id = cli_lid), 'cliente que pediu SAIR deixa de aceitar mensagens');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM clientes WHERE tenant_id = demo AND NOT aceita_mensagens AND id <> cli_lid AND id <> cli_no AND telefone LIKE '%95555-4444'), 'SAIR não descadastra quem tem os mesmos dígitos finais em outro DDD');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM wa_saidas WHERE tenant_id = demo AND chave = '5521955554444'), 'saída guardada pelo número');
  INSERT INTO wa_mensagens (tenant_id, tipo, referencia, cliente_id, veiculo_id, numero)
  VALUES (demo, 'retorno', gen_random_uuid()::text, cli, v1, '5511988887777') RETURNING id INTO m2;
  PERFORM ci.exige(wa_saida_registrar(inst, '5511988887777', NULL) >= 1, 'SAIR por número descadastra o cliente');
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND erro = 'Cliente pediu para sair' FROM wa_mensagens WHERE id = m2), 'SAIR cancela o que estava na fila para o número');
  PERFORM ci.exige((SELECT count(*) = 0 FROM clientes WHERE id = cli AND aceita_mensagens), 'cliente do número deixa de aceitar mensagens');
  PERFORM ci.deve_falhar(vend, format($c$SELECT wa_enfileirar('pronto', %L)$c$, o4::text), 'enfileirar para quem pediu para sair');
  PERFORM ci.exige(wa_saida_registrar('instancia-desconhecida', '5511988887777', NULL) = 0, 'saída de instância desconhecida não faz nada');

  DELETE FROM wa_mensagens WHERE tenant_id = demo;
  DELETE FROM wa_saidas WHERE tenant_id = demo;
  DELETE FROM wa_config WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 77. Links de acesso personalizados: só a equipe Ze Tech cria e lê, conflito com os outros links, link desativado, uso por usuário
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  op2  constant uuid := 'a0000000-0000-0000-0000-000000007701';
  t1 uuid; t2 uuid; u1 uuid := 'a0000000-0000-0000-0000-000000007702'; u2 uuid := 'a0000000-0000-0000-0000-000000007703';
  c1 uuid; c2 uuid; l1 uuid; l2 uuid; l3 uuid; r jsonb; x jsonb;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (op2, 'operador-links@ci'), (u1, 'usuario-link-1@ci'), (u2, 'usuario-link-2@ci');
  INSERT INTO saas_operadores (user_id) VALUES (op2);
  INSERT INTO tenants (nome) VALUES ('Loja Links 1 CI') RETURNING id INTO t1;
  INSERT INTO tenants (nome) VALUES ('Loja Links 2 CI') RETURNING id INTO t2;
  INSERT INTO saas_clientes (nome, tenant_id, link_acesso) VALUES ('Cliente Links 1', t1, 'combinado-links-ci') RETURNING id INTO c1;
  INSERT INTO saas_clientes (nome, tenant_id) VALUES ('Cliente Links 2', t2) RETURNING id INTO c2;
  UPDATE profiles SET nome = 'Ana Links', tenant_id = t1, usuario = 'ana.links', ativo = true WHERE id = u1;
  UPDATE profiles SET nome = 'Beto Links', tenant_id = t2, usuario = 'beto.links', ativo = true WHERE id = u2;

  -- acesso: só a equipe Ze Tech
  PERFORM ci.deve_falhar(adm, format($c$SELECT saas_link_criar(%L, 'meu-link-ci', 'x')$c$, t1), 'administrador da loja cria link');
  PERFORM ci.deve_falhar(vend, format($c$SELECT saas_link_criar(%L, 'meu-link-ci', 'x')$c$, t1), 'vendedor cria link');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT saas_link_criar(%L, 'meu-link-ci', 'x')$c$, t1), 'anon cria link');
  PERFORM ci.deve_falhar(adm, $c$SELECT saas_links_listar()$c$, 'administrador da loja lista links');
  PERFORM ci.deve_falhar(vend, format($c$SELECT saas_link_usuarios(%L)$c$, t1), 'vendedor lê o uso dos links');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM empresa_links') = 0, 'administrador da loja não lê a tabela de links');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM link_acesso_usuarios') = 0, 'administrador da loja não lê o uso dos links');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO empresa_links (tenant_id, slug) VALUES (%L, 'direto-ci')$c$, t1), 'inserir link direto na tabela');
  PERFORM ci.deve_falhar(adm, format($c$SELECT link_acesso_registrar(%L, 'combinado-links-ci')$c$, u1), 'registrar uso como usuário');

  -- criar: formato, reservado, empresa fora da rede
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'ab', 'x')$c$, t1), 'link curto demais');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'Com Espaço', 'x')$c$, t1), 'link com espaço');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, '-começa-com-hifen', 'x')$c$, t1), 'link com hífen na ponta');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'admin', 'x')$c$, t1), 'link reservado');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'meu-link-ci', 'x')$c$, gen_random_uuid()), 'empresa que não é cliente da rede');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'combinado-links-ci', 'x')$c$, t2), 'link igual ao combinado no cadastro de outro assinante');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'combinado-links-ci', 'x')$c$, t1), 'link igual ao combinado no cadastro da própria empresa');

  -- criar de verdade: texto livre, sem relação com o nome da empresa
  PERFORM ci.entrar(op2);
  l1 := saas_link_criar(t1, ' Caixa-Rapido-77 ', 'Equipe do caixa');
  l2 := saas_link_criar(t1, 'filial-centro-77', NULL);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT slug = 'caixa-rapido-77' AND rotulo = 'Equipe do caixa' AND ativo FROM empresa_links WHERE id = l1), 'link gravado em minúsculas, sem espaços, com o nome dado');
  PERFORM ci.exige((SELECT count(*) = 2 FROM empresa_links WHERE tenant_id = t1), 'uma empresa pode ter vários links');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'CAIXA-rapido-77', 'repetido')$c$, t2), 'link repetido (outra empresa)');
  PERFORM ci.deve_falhar(op2, format($c$SELECT saas_link_criar(%L, 'caixa-rapido-77', 'repetido')$c$, t1), 'link repetido (mesma empresa)');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE empresa_links SET slug = 'outro-link-77' WHERE id = %L$c$, l1), 'trocar o texto do link');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE empresa_links SET tenant_id = %L WHERE id = %L$c$, t2, l1), 'mudar o link de empresa');

  -- os outros tipos de link não tomam um link personalizado
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO empresas (tenant_id, razao_social, slug) VALUES (%L, 'Empresa Tomando Link', 'caixa-rapido-77')$c$, t2), 'empresa toma link personalizado');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE saas_clientes SET link_acesso = 'filial-centro-77' WHERE id = %L$c$, c2), 'cadastro de assinante toma link personalizado');

  -- loja sem empresa cadastrada ainda: o link abre com o nome do cadastro do assinante
  PERFORM ci.entrar(op2);
  l3 := saas_link_criar(t1, 'primeiro-acesso-77', NULL);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT nome FROM empresa_por_slug('primeiro-acesso-77')) = 'Cliente Links 1', 'link personalizado abre antes de a empresa ser cadastrada');
  UPDATE empresa_links SET ativo = false WHERE id = l3;

  -- tela de login: o link abre a marca da empresa, desativado deixa de abrir
  INSERT INTO empresas (tenant_id, razao_social, nome_fantasia) VALUES (t1, 'Razao Links 1 Ltda', 'Marca Links 1');
  PERFORM ci.exige((SELECT nome FROM empresa_por_slug('caixa-rapido-77')) = 'Marca Links 1', 'o link personalizado abre a tela da empresa');
  PERFORM ci.exige((SELECT nome FROM empresa_por_slug('CAIXA-RAPIDO-77')) = 'Marca Links 1', 'o link não diferencia maiúsculas');
  PERFORM ci.deve_falhar(adm, $c$SELECT saas_link_atualizar(gen_random_uuid(), 'x', false)$c$, 'administrador da loja desativa link');
  PERFORM ci.deve_falhar(op2, $c$SELECT saas_link_atualizar(gen_random_uuid(), 'x', false)$c$, 'atualizar link que não existe');
  PERFORM ci.entrar(op2);
  PERFORM saas_link_atualizar(l2, 'Filial Centro', false);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 0 FROM empresa_por_slug('filial-centro-77')), 'link desativado não abre a tela de login');
  PERFORM ci.exige((SELECT rotulo = 'Filial Centro' AND NOT ativo FROM empresa_links WHERE id = l2), 'nome e situação do link atualizados');

  -- uso: só conta se o link é da empresa do usuário
  PERFORM link_acesso_registrar(u1, 'caixa-rapido-77');
  PERFORM link_acesso_registrar(u1, 'Caixa-Rapido-77');
  PERFORM link_acesso_registrar(u1, 'combinado-links-ci');
  PERFORM link_acesso_registrar(u1, t1::text);
  PERFORM link_acesso_registrar(u1, 'filial-centro-77');
  PERFORM link_acesso_registrar(u2, 'caixa-rapido-77');
  PERFORM link_acesso_registrar(u1, 'nao-existe-77');
  PERFORM link_acesso_registrar(gen_random_uuid(), 'caixa-rapido-77');
  PERFORM ci.exige((SELECT acessos = 2 AND link_id = l1 AND origem = 'personalizado' FROM link_acesso_usuarios WHERE user_id = u1 AND link_slug = 'caixa-rapido-77'), 'duas entradas pelo link personalizado contam 2');
  PERFORM ci.exige((SELECT origem = 'principal' FROM link_acesso_usuarios WHERE user_id = u1 AND link_slug = 'combinado-links-ci'), 'uso do link principal da empresa (herdado do cadastro do assinante)');
  PERFORM ci.exige((SELECT origem = 'codigo' AND link_id IS NULL FROM link_acesso_usuarios WHERE user_id = u1 AND link_slug = t1::text), 'uso do código da empresa');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM link_acesso_usuarios WHERE user_id = u1 AND link_slug IN ('filial-centro-77', 'nao-existe-77')), 'link desativado ou inexistente não conta');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM link_acesso_usuarios WHERE user_id = u2), 'link de outra empresa não conta para o usuário');

  -- telas da equipe
  PERFORM ci.entrar(op2);
  r := saas_links_listar();
  PERFORM ci.sair();
  SELECT e INTO x FROM jsonb_array_elements(r) e WHERE e ->> 'link_id' = l1::text;
  PERFORM ci.exige(x IS NOT NULL AND x ->> 'cliente' = 'Cliente Links 1' AND (x ->> 'usuarios')::int = 1 AND (x ->> 'acessos')::int = 2 AND x ->> 'origem' = 'personalizado', 'lista traz o link, a empresa e o uso');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'slug' = 'combinado-links-ci' AND e ->> 'origem' = 'principal'), 'lista traz o link principal da empresa');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'link_id' = l2::text AND (e ->> 'ativo')::boolean = false), 'lista traz o link desativado');
  PERFORM ci.entrar(op2);
  r := saas_link_usuarios(t1);
  PERFORM ci.sair();
  SELECT e INTO x FROM jsonb_array_elements(r) e WHERE e ->> 'user_id' = u1::text;
  PERFORM ci.exige(x ->> 'nome' = 'Ana Links' AND jsonb_array_length(x -> 'links') = 3 AND x -> 'links' -> 0 ->> 'slug' IS NOT NULL, 'usuários da empresa com os links que usaram');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'user_id' = u2::text), 'usuário de outra empresa não aparece');

  -- link desativado e depois reativado volta a valer; remover a empresa leva os links junto
  PERFORM ci.entrar(op2);
  PERFORM saas_link_atualizar(l2, 'Filial Centro', true);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 1 FROM empresa_por_slug('filial-centro-77')), 'link reativado volta a abrir a tela');

  DELETE FROM link_acesso_usuarios WHERE tenant_id = t1;
  DELETE FROM empresa_links WHERE tenant_id = t1;
  DELETE FROM empresas WHERE tenant_id = t1;
  DELETE FROM profiles WHERE id IN (u1, u2);
  DELETE FROM saas_clientes WHERE id IN (c1, c2);
  DELETE FROM saas_operadores WHERE user_id = op2;
END $$;

-- 78. Nomes de exibição dos planos: troca só o nome, mantém código, preços e limites, não sobrescreve nome editado
DO $$
BEGIN
  PERFORM ci.exige((SELECT nome FROM saas_planos WHERE codigo = 'balcao') = 'Essencial', 'balcao exibido como Essencial');
  PERFORM ci.exige((SELECT nome FROM saas_planos WHERE codigo = 'loja') = 'Profissional', 'loja exibido como Profissional');
  PERFORM ci.exige((SELECT nome FROM saas_planos WHERE codigo = 'rede') = 'Empresarial', 'rede exibido como Empresarial');
  PERFORM ci.exige('Tudo do Essencial' = ANY (SELECT unnest(recursos) FROM saas_planos WHERE codigo = 'loja'), 'item "Tudo do" do plano Profissional cita o Essencial');
  PERFORM ci.exige('Tudo do Profissional' = ANY (SELECT unnest(recursos) FROM saas_planos WHERE codigo = 'rede'), 'item "Tudo do" do plano Empresarial cita o Profissional');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM saas_planos, unnest(recursos) r WHERE r IN ('Tudo do Balcão', 'Tudo do Loja')), 'nenhum item cita os nomes antigos');
  PERFORM ci.exige((SELECT count(*) = 3 FROM saas_planos WHERE codigo IN ('balcao', 'loja', 'rede')), 'os três códigos internos seguem existindo');
  PERFORM ci.exige((SELECT valor_mensal FROM saas_planos WHERE codigo = 'balcao') = 149
                   AND (SELECT valor_mensal FROM saas_planos WHERE codigo = 'loja') = 299
                   AND (SELECT valor_mensal FROM saas_planos WHERE codigo = 'rede') = 599, 'preços iguais');
  PERFORM ci.exige((SELECT resumo FROM saas_planos WHERE codigo = 'loja') = '1 loja, depósitos ilimitados, 15 usuários', 'a legenda de limites segue com "1 loja"');
  PERFORM ci.exige((SELECT plano FROM assinaturas LIMIT 1) IN ('balcao', 'loja', 'rede'), 'assinaturas seguem apontando para o código interno');
END $$;

-- 79. Taxa inicial por segmento: R$ 299 de treinamento e configuração para pet shop, clínica e lava-rápido; o resto segue igual
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  op   constant uuid := 'a0000000-0000-0000-0000-0000000000d9';
  ramo_ant text; cs uuid; impl_assin numeric; impl_plano numeric; r record;
BEGIN
  SELECT ramo_atividade INTO ramo_ant FROM empresas WHERE tenant_id = demo;
  INSERT INTO auth.users (id, email) VALUES (op, 'operador-taxa@ci');
  INSERT INTO saas_operadores (user_id) VALUES (op);
  INSERT INTO saas_clientes (nome, tenant_id, plano_id) VALUES ('Taxa Inicial CI', demo, (SELECT id FROM saas_planos WHERE codigo = 'loja')) RETURNING id INTO cs;
  SELECT valor_implantacao INTO impl_plano FROM saas_planos WHERE codigo = 'loja';

  -- regra: só clínica e lava-rápido têm taxa própria
  PERFORM ci.exige((SELECT count(*) = 1 AND min(valor) = 299 FROM taxa_inicial_segmento('clinica')), 'clínica: R$ 299');
  PERFORM ci.exige((SELECT count(*) = 1 AND min(valor) = 299 FROM taxa_inicial_segmento('lavarapido')), 'lava-rápido: R$ 299');
  PERFORM ci.exige((SELECT count(*) = 1 AND min(valor) = 299 FROM taxa_inicial_segmento('petshop')), 'pet shop: R$ 299');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM taxa_inicial_segmento('construcao')), 'demais segmentos sem taxa própria');

  -- empresa de segmento comum: mantém a implantação do plano
  UPDATE empresas SET ramo_atividade = 'construcao' WHERE tenant_id = demo;
  PERFORM ci.entrar(adm);
  SELECT * INTO r FROM assinatura_taxa_inicial();
  PERFORM ci.exige(r.rotulo = 'Implantação' AND NOT r.excecao, 'segmento comum mostra Implantação');
  PERFORM ci.exige(r.valor = (SELECT valor_implantacao FROM assinaturas LIMIT 1), 'segmento comum mantém o valor da assinatura');
  PERFORM ci.sair();
  PERFORM ci.entrar(op);
  SELECT * INTO r FROM saas_taxa_inicial_cliente(cs);
  PERFORM ci.sair();
  PERFORM ci.exige(r.valor = impl_plano AND NOT r.excecao AND r.rotulo = 'Implantação', 'operador: segmento comum mantém a implantação do plano');

  -- clínica e lava-rápido: R$ 299, sem mexer no valor de expansão guardado na assinatura
  SELECT valor_implantacao INTO impl_assin FROM assinaturas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  PERFORM ci.entrar(adm);
  SELECT * INTO r FROM assinatura_taxa_inicial();
  PERFORM ci.exige(r.valor = 299 AND r.excecao AND r.rotulo = 'Treinamento e configuração inicial', 'clínica: assinatura mostra R$ 299');
  PERFORM ci.sair();
  UPDATE empresas SET ramo_atividade = 'lavarapido' WHERE tenant_id = demo;
  PERFORM ci.entrar(op);
  SELECT * INTO r FROM saas_taxa_inicial_cliente(cs);
  PERFORM ci.sair();
  PERFORM ci.exige(r.valor = 299 AND r.excecao, 'lava-rápido: operador sugere R$ 299');
  PERFORM ci.exige((SELECT valor_implantacao FROM assinaturas WHERE tenant_id = demo) = impl_assin, 'a implantação guardada na assinatura (expansão) não muda');
  PERFORM ci.exige((SELECT valor_implantacao FROM saas_planos WHERE codigo = 'loja') = impl_plano, 'a implantação do plano não muda');
  PERFORM ci.exige((SELECT valor_filial_extra FROM saas_planos WHERE codigo = 'loja') = 390, 'a filial extra segue em R$ 390');

  -- quem não é da equipe não consulta a taxa de um assinante
  PERFORM ci.deve_falhar(adm, format($c$SELECT * FROM saas_taxa_inicial_cliente(%L)$c$, cs), 'não operador consultando a taxa de assinante');

  UPDATE empresas SET ramo_atividade = ramo_ant WHERE tenant_id = demo;
  DELETE FROM saas_clientes WHERE id = cs;
  DELETE FROM saas_operadores WHERE user_id = op;
END $$;

-- 80. Manufatura (fase 1): só abre por liberação explícita; lista de materiais, ordem, reserva, consumo, entrada do acabado, custo, idempotência e perfis
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  prod constant uuid := 'a0000000-0000-0000-0000-0000000001a1';
  u2   constant uuid := 'a0000000-0000-0000-0000-0000000001a2';
  t2 uuid; emp uuid; emp2 uuid; cnae_ant text; ramo_ant text; sem_ant text[];
  dep_i uuid; dep_d uuid; arm uuid; chapa uuid; ferr uuid;
  b1 uuid; b2 uuid; op uuid; op_med uuid; op_grande uuid; ap uuid; ap2 uuid; ordem_prod mf_ordens; r record; n bigint;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (prod, 'producao@ci'), (u2, 'manuf2@ci');
  INSERT INTO tenants (nome) VALUES ('Manufatura CI 2') RETURNING id INTO t2;
  INSERT INTO empresas (tenant_id, razao_social) VALUES (t2, 'Marcenaria CI 2') RETURNING id INTO emp2;
  UPDATE profiles SET tenant_id = demo WHERE id = prod;
  UPDATE profiles SET tenant_id = t2 WHERE id = u2;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (prod, demo, 'producao'), (u2, t2, 'administrador');
  SELECT id, cnae, ramo_atividade, modulos_sem_cnpj INTO emp, cnae_ant, ramo_ant, sem_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;

  INSERT INTO depositos (tenant_id, nome, permite_negativo) VALUES (demo, 'MF Insumos CI', false) RETURNING id INTO dep_i;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Acabados CI') RETURNING id INTO dep_d;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-ARM', 'Armário padrão CI', 'un', 0) RETURNING id INTO arm;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-MDF', 'Chapa MDF CI', 'chapa', 100) RETURNING id INTO chapa;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-FER', 'Ferragem CI', 'un', 5) RETURNING id INTO ferr;
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade, reservado, custo_medio) VALUES (demo, chapa, dep_i, 10, 0, 100), (demo, ferr, dep_i, 50, 0, 5);

  -- sem liberação explícita nada abre, nem com CNAE de móveis, ramo ou escolha sem CNPJ
  UPDATE empresas SET cnae = '3101-2/00', modulos_sem_cnpj = ARRAY[]::text[] WHERE id = emp;
  PERFORM ci.entrar(adm);
  PERFORM ci.exige(NOT manufatura_liberada(), 'CNAE de móveis não libera a manufatura no piloto');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, format($c$SELECT mf_bom_salvar(jsonb_build_object('produto_id', %L))$c$, arm), 'lista de materiais sem o módulo liberado');
  PERFORM ci.deve_falhar_dono($c$UPDATE empresas SET modulos_sem_cnpj = ARRAY['manufatura'] WHERE cnpj IS NULL$c$, 'escolha sem CNPJ não aceita manufatura');
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  PERFORM ci.entrar(adm);
  PERFORM ci.exige(manufatura_liberada(), 'a liberação explícita abre a manufatura');
  PERFORM ci.sair();
  PERFORM ci.entrar(u2);
  PERFORM ci.exige(NOT manufatura_liberada(), 'a liberação de uma empresa não vale para outra');
  PERFORM ci.sair();

  -- perfis: só administrador e gestor mantêm lista e ordem; produção e vendedor não
  PERFORM ci.deve_falhar(vend, format($c$SELECT mf_bom_salvar(jsonb_build_object('produto_id', %L))$c$, arm), 'vendedor cria lista de materiais');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_bom_salvar(jsonb_build_object('produto_id', %L))$c$, arm), 'produção cria lista de materiais');

  -- lista de materiais: versão, rascunho editável, ativa congelada, nova versão deixa a anterior obsoleta
  PERFORM ci.entrar(gest);
  b1 := mf_bom_salvar(jsonb_build_object('produto_id', arm, 'rotulo', 'Armário v1', 'rendimento', 1,
          'itens', jsonb_build_array(jsonb_build_object('insumo_id', chapa, 'quantidade', 2, 'perda_percentual', 10),
                                     jsonb_build_object('insumo_id', ferr, 'quantidade', 8, 'perda_percentual', 0))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT versao = 1 AND situacao = 'rascunho' FROM mf_boms WHERE id = b1), 'primeira versão nasce em rascunho');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_bom_salvar(jsonb_build_object('produto_id', %L, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', %L, 'quantidade', 1), jsonb_build_object('insumo_id', %L, 'quantidade', 1))))$c$, arm, chapa, chapa), 'insumo repetido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_bom_salvar(jsonb_build_object('produto_id', %L, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', %L, 'quantidade', 1))))$c$, arm, arm), 'produto como insumo dele mesmo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_bom_salvar(jsonb_build_object('produto_id', %L, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', %L, 'quantidade', 1, 'perda_percentual', 95))))$c$, arm, chapa), 'perda de 95%');
  PERFORM ci.entrar(gest); PERFORM mf_bom_ativar(b1); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'ativa' FROM mf_boms WHERE id = b1), 'lista ativada');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_bom_salvar(jsonb_build_object('id', %L, 'produto_id', %L))$c$, b1, arm), 'editar lista ativa');
  PERFORM ci.entrar(gest);
  b2 := mf_bom_salvar(jsonb_build_object('produto_id', arm, 'rotulo', 'Armário v2', 'itens', jsonb_build_array(jsonb_build_object('insumo_id', chapa, 'quantidade', 3))));
  PERFORM mf_bom_ativar(b2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'obsoleta' FROM mf_boms WHERE id = b1) AND (SELECT versao = 2 AND situacao = 'ativa' FROM mf_boms WHERE id = b2), 'nova versão ativa deixa a anterior obsoleta');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO mf_boms (tenant_id, produto_id, versao, situacao) VALUES (%L, %L, 9, 'ativa')$c$, demo, arm), 'duas listas ativas do mesmo produto');

  -- escrita direta é negada: só pelas funções
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO mf_ordens (numero, descricao, quantidade_planejada, deposito_insumos_id) VALUES (999, 'direto', 1, %L)$c$, dep_i), 'inserir ordem direto na tabela');

  -- ordem de linha padrão a partir da lista v1 (obsoleta, ainda usável): itens por unidade = item ÷ rendimento
  PERFORM ci.entrar(gest);
  op := mf_ordem_criar(jsonb_build_object('descricao', 'Armários de linha', 'produto_id', arm, 'bom_id', b1, 'quantidade_planejada', 2,
          'entrada_estoque', true, 'deposito_insumos_id', dep_i, 'deposito_destino_id', dep_d));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'planejada' AND numero >= 1 AND custo_padrao = 524.40 FROM mf_ordens WHERE id = op), 'ordem planejada com custo padrão dos itens (4,444 chapas x 100 + 16 ferragens x 5)');
  PERFORM ci.exige((SELECT quantidade_planejada = 4.444 FROM mf_ordem_insumos WHERE ordem_id = op AND insumo_id = chapa), 'necessidade da chapa com perda de 10%');

  -- produção não vê custo nem as tabelas da ordem; vê só pela função
  PERFORM ci.exige(ci.contar(prod, 'SELECT count(*) FROM mf_ordens') = 0, 'produção não lê custo das ordens');
  PERFORM ci.exige(ci.contar(prod, 'SELECT count(*) FROM mf_ordem_insumos') = 0, 'produção não lê custo dos insumos da ordem');
  PERFORM ci.exige(ci.contar(adm, 'SELECT count(*) FROM mf_ordens') >= 1, 'administrador lê as ordens');
  PERFORM ci.exige(ci.contar(u2, 'SELECT count(*) FROM mf_ordens') = 0, 'outra empresa não lê as ordens');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_liberar(%L)$c$, op), 'produção libera ordem');
  PERFORM ci.deve_falhar(u2, format($c$SELECT mf_ordem_liberar(%L)$c$, op), 'outra empresa libera a ordem');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_ordem_apontar(%L, 1, 0, NULL, 'antes-da-liberacao')$c$, op), 'apontar ordem ainda planejada');

  -- liberação: reserva os insumos; ordem grande demais não libera
  PERFORM ci.entrar(gest); PERFORM mf_ordem_liberar(op); PERFORM ci.sair();
  PERFORM ci.exige((SELECT reservado = 4.444 FROM estoques WHERE produto_id = chapa AND deposito_id = dep_i), 'liberar reserva a chapa');
  PERFORM ci.exige((SELECT reservado = 16 FROM estoques WHERE produto_id = ferr AND deposito_id = dep_i), 'liberar reserva a ferragem');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_ordem_itens_salvar(%L, '[]'::jsonb)$c$, op), 'alterar itens depois da liberação');
  PERFORM ci.entrar(gest);
  op_grande := mf_ordem_criar(jsonb_build_object('descricao', 'Pedido enorme', 'quantidade_planejada', 100, 'deposito_insumos_id', dep_i,
                 'itens', jsonb_build_array(jsonb_build_object('insumo_id', chapa, 'quantidade', 1, 'perda_percentual', 0))));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_ordem_liberar(%L)$c$, op_grande), 'liberar sem estoque para a reserva');
  PERFORM ci.exige((SELECT reservado = 4.444 FROM estoques WHERE produto_id = chapa AND deposito_id = dep_i), 'ordem recusada não reserva nada');

  -- apontamento da produção: consome proporcional, usa a reserva, dá entrada do acabado com o custo dos insumos
  PERFORM ci.entrar(prod); ap := mf_ordem_apontar(op, 1, 0, 30, 'ap-1'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 7.778 AND reservado = 2.222 FROM estoques WHERE produto_id = chapa AND deposito_id = dep_i), 'consumo da chapa e reserva que sobra');
  PERFORM ci.exige((SELECT quantidade = 42 AND reservado = 8 FROM estoques WHERE produto_id = ferr AND deposito_id = dep_i), 'consumo da ferragem e reserva que sobra');
  PERFORM ci.exige((SELECT quantidade = 1 FROM estoques WHERE produto_id = arm AND deposito_id = dep_d), 'entrada do produto acabado');
  PERFORM ci.exige((SELECT custo_medio = 262.2 FROM estoques WHERE produto_id = arm AND deposito_id = dep_d), 'custo do acabado vem dos insumos consumidos');
  PERFORM ci.exige((SELECT situacao = 'em_producao' AND quantidade_produzida = 1 AND custo_real = 262.20 FROM mf_ordens WHERE id = op), 'ordem em produção com custo real');
  PERFORM ci.exige((SELECT count(*) = 2 FROM estoque_movimentacoes WHERE documento = ('OP-' || (SELECT numero FROM mf_ordens WHERE id = op)) AND tipo = 'saida'), 'movimentações de saída com o documento da ordem');

  -- idempotência: a mesma chave não consome de novo; outra ordem não reaproveita a chave
  PERFORM ci.entrar(prod); ap2 := mf_ordem_apontar(op, 1, 0, 30, 'ap-1'); PERFORM ci.sair();
  PERFORM ci.exige(ap2 = ap, 'a mesma chave devolve o mesmo apontamento');
  PERFORM ci.exige((SELECT quantidade = 7.778 FROM estoques WHERE produto_id = chapa AND deposito_id = dep_i)
                   AND (SELECT quantidade = 1 FROM estoques WHERE produto_id = arm AND deposito_id = dep_d)
                   AND (SELECT count(*) = 1 FROM mf_apontamentos WHERE ordem_id = op), 'repetir a chave não consome nem dá entrada de novo');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_apontar(%L, 1, 0, NULL, 'ap-1')$c$, op_grande), 'chave de outra ordem');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_apontar(%L, 0, 0, NULL, 'ap-zero')$c$, op), 'apontamento sem quantidade');
  PERFORM ci.deve_falhar(u2, format($c$SELECT mf_ordem_apontar(%L, 1, 0, NULL, 'ap-u2')$c$, op), 'outra empresa aponta a ordem');

  -- refugo consome insumo e não entra no estoque do acabado; o arredondamento não acumula erro
  PERFORM ci.entrar(prod); PERFORM mf_ordem_apontar(op, 1, 1, NULL, 'ap-2'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 3.333 AND reservado = 0 FROM estoques WHERE produto_id = chapa AND deposito_id = dep_i), 'consumo acumulado bate com 3 peças (2 boas e 1 refugo)');
  PERFORM ci.exige((SELECT quantidade = 2 FROM estoques WHERE produto_id = arm AND deposito_id = dep_d), 'refugo não entra no estoque do acabado');
  PERFORM ci.exige((SELECT quantidade_produzida = 2 AND quantidade_refugo = 1 FROM mf_ordens WHERE id = op), 'totais da ordem');

  -- produção lê pela função, sem custo
  PERFORM ci.entrar(prod);
  SELECT count(*) INTO n FROM mf_ordens_producao();
  PERFORM ci.exige(n = 1, 'produção enxerga a ordem em produção pela função');
  SELECT count(*) INTO n FROM mf_ordem_insumos_producao(op);
  PERFORM ci.exige(n = 2, 'produção enxerga os insumos da ordem pela função');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_ordem_cancelar(%L)$c$, op), 'cancelar ordem em produção');

  -- concluir: solta a reserva e fecha o custo real (insumos + mão de obra)
  PERFORM ci.entrar(gest); PERFORM mf_ordem_concluir(op); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'concluida' FROM mf_ordens WHERE id = op), 'ordem concluída');
  PERFORM ci.exige((SELECT reservado = 0 FROM estoques WHERE produto_id = ferr AND deposito_id = dep_i), 'concluir solta a reserva que sobrou');
  PERFORM ci.exige((SELECT custo_real = (SELECT sum(custo_consumido) FROM mf_ordem_insumos WHERE ordem_id = op) + mao_de_obra FROM mf_ordens WHERE id = op), 'custo real = insumos consumidos + mão de obra');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_apontar(%L, 1, 0, NULL, 'ap-depois')$c$, op), 'apontar ordem concluída');

  -- encomenda sob medida: sem produto cadastrado, sem entrada no estoque, itens editáveis até liberar, cancelar solta a reserva
  PERFORM ci.entrar(gest);
  op_med := mf_ordem_criar(jsonb_build_object('descricao', 'Armário de cozinha, Sra. Ana', 'quantidade_planejada', 1, 'deposito_insumos_id', dep_i,
              'medidas', '2,40 x 0,60 x 2,10 m', 'acabamento', 'MDF branco', 'mao_de_obra', 300,
              'itens', jsonb_build_array(jsonb_build_object('insumo_id', ferr, 'quantidade', 4, 'perda_percentual', 0))));
  PERFORM mf_ordem_itens_salvar(op_med, jsonb_build_array(jsonb_build_object('insumo_id', ferr, 'quantidade', 6, 'perda_percentual', 0)), 350);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT NOT entrada_estoque AND produto_id IS NULL AND mao_de_obra = 350 AND custo_padrao = 380 FROM mf_ordens WHERE id = op_med), 'encomenda sem produto e custo padrão com a mão de obra');
  PERFORM ci.entrar(gest); PERFORM mf_ordem_liberar(op_med); PERFORM ci.sair();
  PERFORM ci.exige((SELECT reservado = 6 FROM estoques WHERE produto_id = ferr AND deposito_id = dep_i), 'encomenda reserva a ferragem');
  PERFORM ci.entrar(gest); PERFORM mf_ordem_cancelar(op_med); PERFORM ci.sair();
  PERFORM ci.exige((SELECT reservado = 0 FROM estoques WHERE produto_id = ferr AND deposito_id = dep_i), 'cancelar solta a reserva');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM estoques WHERE deposito_id = dep_d AND produto_id <> arm), 'a encomenda não entra no estoque');

  -- estoque insuficiente no consumo desfaz o apontamento inteiro
  PERFORM ci.entrar(gest);
  op_grande := mf_ordem_criar(jsonb_build_object('descricao', 'Ordem que passa do estoque', 'quantidade_planejada', 1, 'deposito_insumos_id', dep_i,
                 'itens', jsonb_build_array(jsonb_build_object('insumo_id', chapa, 'quantidade', 3, 'perda_percentual', 0))));
  PERFORM mf_ordem_liberar(op_grande);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_apontar(%L, 5, 0, NULL, 'ap-excesso')$c$, op_grande), 'consumir além do estoque disponível');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM mf_apontamentos WHERE chave_idempotente = 'ap-excesso')
                   AND (SELECT quantidade_produzida = 0 FROM mf_ordens WHERE id = op_grande)
                   AND (SELECT quantidade = 3.333 FROM estoques WHERE produto_id = chapa AND deposito_id = dep_i), 'apontamento recusado não grava nada');

  -- limpeza do que o teste criou (movimentações de estoque são imutáveis: produtos, depósitos e saldos ficam)
  DELETE FROM mf_apontamentos WHERE tenant_id = demo;
  DELETE FROM mf_ordens WHERE tenant_id = demo;
  DELETE FROM mf_bom_itens WHERE tenant_id = demo;
  DELETE FROM mf_boms WHERE tenant_id = demo;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
  UPDATE empresas SET cnae = cnae_ant, ramo_atividade = ramo_ant, modulos_sem_cnpj = sem_ant WHERE id = emp;
  DELETE FROM user_roles WHERE user_id IN (prod, u2);
  DELETE FROM empresas WHERE id = emp2;
END $$;

-- 81. Manufatura: o custo do acabado não depende de como a produção agrupa os apontamentos (refugo antes, sozinho ou junto da peça boa)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  emp uuid; dep_i uuid; dep_d uuid; a1 uuid; a2 uuid; ins uuid; op1 uuid; op2 uuid;
BEGIN
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Insumos CI 2') RETURNING id INTO dep_i;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Acabados CI 2') RETURNING id INTO dep_d;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-ARM-A', 'Armário A CI', 'un', 0) RETURNING id INTO a1;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-ARM-B', 'Armário B CI', 'un', 0) RETURNING id INTO a2;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-INS-2', 'Chapa 2 CI', 'chapa', 100) RETURNING id INTO ins;
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade, reservado, custo_medio) VALUES (demo, ins, dep_i, 20, 0, 100);

  PERFORM ci.entrar(gest);
  op1 := mf_ordem_criar(jsonb_build_object('descricao', 'Refugo junto', 'produto_id', a1, 'quantidade_planejada', 2, 'entrada_estoque', true,
           'deposito_insumos_id', dep_i, 'deposito_destino_id', dep_d, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 1))));
  op2 := mf_ordem_criar(jsonb_build_object('descricao', 'Refugo antes', 'produto_id', a2, 'quantidade_planejada', 2, 'entrada_estoque', true,
           'deposito_insumos_id', dep_i, 'deposito_destino_id', dep_d, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 1))));
  PERFORM mf_ordem_liberar(op1); PERFORM mf_ordem_liberar(op2);
  -- mesma produção (1 peça boa e 1 de refugo), apontada de duas formas
  PERFORM mf_ordem_apontar(op1, 1, 1, NULL, 'agrup-junto');
  PERFORM mf_ordem_apontar(op2, 0, 1, NULL, 'agrup-refugo');
  PERFORM ci.exige((SELECT custo_a_alocar = 100 FROM mf_ordens WHERE id = op2), 'o custo do refugo sozinho fica para alocar');
  PERFORM mf_ordem_apontar(op2, 1, 0, NULL, 'agrup-boa');
  PERFORM ci.sair();

  PERFORM ci.exige((SELECT custo_medio = 200 FROM estoques WHERE produto_id = a1 AND deposito_id = dep_d), 'refugo junto da peça boa: acabado custa 200');
  PERFORM ci.exige((SELECT custo_medio = 200 FROM estoques WHERE produto_id = a2 AND deposito_id = dep_d), 'refugo antes da peça boa: acabado também custa 200');
  PERFORM ci.exige((SELECT custo_a_alocar = 0 FROM mf_ordens WHERE id = op2), 'nada sobra para alocar depois da peça boa');
  PERFORM ci.exige((SELECT custo_real FROM mf_ordens WHERE id = op1) = (SELECT custo_real FROM mf_ordens WHERE id = op2), 'o custo real da ordem é o mesmo nas duas formas');

  DELETE FROM mf_apontamentos WHERE tenant_id = demo;
  DELETE FROM mf_ordens WHERE tenant_id = demo;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
END $$;

-- 82. Manufatura (fase 2): roteiro de etapas, apontamento por etapa e custo de mão de obra por hora
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  prod constant uuid := 'a0000000-0000-0000-0000-0000000001b1';
  emp uuid; dep_i uuid; dep_d uuid; arm uuid; ins uuid; op uuid; op2 uuid; et_corte uuid; et_mont uuid; oe_corte uuid; oe_outro uuid; n integer;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (prod, 'producao-etapas@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = prod;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (prod, demo, 'producao');
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Insumos CI 3') RETURNING id INTO dep_i;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Acabados CI 3') RETURNING id INTO dep_d;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-ARM-E', 'Armário etapas CI', 'un', 0) RETURNING id INTO arm;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-INS-E', 'Chapa etapas CI', 'chapa', 100) RETURNING id INTO ins;
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade, reservado, custo_medio) VALUES (demo, ins, dep_i, 50, 0, 100);

  -- roteiro-padrão: só a gestão cria; criar de novo não duplica
  PERFORM ci.deve_falhar(prod, $c$SELECT mf_etapas_iniciais()$c$, 'produção cria o roteiro');
  PERFORM ci.deve_falhar(prod, $c$SELECT mf_etapa_salvar('{"nome":"Lixamento"}'::jsonb)$c$, 'produção cria etapa');
  PERFORM ci.entrar(gest); n := mf_etapas_iniciais(); PERFORM ci.sair();
  PERFORM ci.exige(n = 5, 'o roteiro inicial de marcenaria tem 5 etapas');
  PERFORM ci.entrar(gest); n := mf_etapas_iniciais(); PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'criar o roteiro de novo não duplica');
  PERFORM ci.deve_falhar(gest, $c$SELECT mf_etapa_salvar('{"nome":"Corte"}'::jsonb)$c$, 'etapa com nome repetido');
  PERFORM ci.deve_falhar(gest, $c$SELECT mf_etapa_salvar('{"nome":"Nova","custo_hora":-5}'::jsonb)$c$, 'custo por hora negativo');
  SELECT id INTO et_corte FROM mf_etapas WHERE tenant_id = demo AND nome = 'Corte';
  SELECT id INTO et_mont FROM mf_etapas WHERE tenant_id = demo AND nome = 'Montagem';
  PERFORM ci.entrar(gest);
  PERFORM mf_etapa_salvar(jsonb_build_object('id', et_corte, 'nome', 'Corte', 'ordem', 10, 'custo_hora', 60));
  PERFORM mf_etapa_salvar(jsonb_build_object('id', et_mont, 'nome', 'Montagem', 'ordem', 30, 'custo_hora', 120));
  PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(prod, 'SELECT count(*) FROM mf_etapas') = 0, 'produção não lê o custo por hora das etapas');

  -- a ordem recebe uma cópia do roteiro ao liberar, com o custo por hora daquele momento
  PERFORM ci.entrar(gest);
  op := mf_ordem_criar(jsonb_build_object('descricao', 'Armários com etapas', 'produto_id', arm, 'quantidade_planejada', 2, 'entrada_estoque', true,
          'deposito_insumos_id', dep_i, 'deposito_destino_id', dep_d, 'mao_de_obra', 50,
          'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 1))));
  op2 := mf_ordem_criar(jsonb_build_object('descricao', 'Outra ordem', 'quantidade_planejada', 1, 'deposito_insumos_id', dep_i,
          'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 1))));
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM mf_ordem_etapas WHERE ordem_id = op), 'ordem planejada ainda sem roteiro');
  PERFORM mf_ordem_liberar(op); PERFORM mf_ordem_liberar(op2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 5 FROM mf_ordem_etapas WHERE ordem_id = op), 'a ordem liberada recebe as 5 etapas');
  PERFORM ci.exige((SELECT custo_hora = 60 FROM mf_ordem_etapas WHERE ordem_id = op AND nome = 'Corte'), 'cópia com o custo por hora da liberação');
  PERFORM ci.entrar(gest); PERFORM mf_etapa_salvar(jsonb_build_object('id', et_corte, 'nome', 'Corte', 'ordem', 10, 'custo_hora', 999)); PERFORM ci.sair();
  PERFORM ci.exige((SELECT custo_hora = 60 FROM mf_ordem_etapas WHERE ordem_id = op AND nome = 'Corte'), 'mudar o custo por hora depois não altera ordem já liberada');
  SELECT id INTO oe_corte FROM mf_ordem_etapas WHERE ordem_id = op AND nome = 'Corte';
  SELECT id INTO oe_outro FROM mf_ordem_etapas WHERE ordem_id = op2 AND nome = 'Corte';

  -- produção lê as etapas pela função, sem custo
  PERFORM ci.exige(ci.contar(prod, 'SELECT count(*) FROM mf_ordem_etapas') = 0, 'produção não lê a tabela de etapas da ordem (tem custo por hora)');
  PERFORM ci.entrar(prod); SELECT count(*) INTO n FROM mf_ordem_etapas_producao(op); PERFORM ci.sair();
  PERFORM ci.exige(n = 5, 'produção vê as etapas da ordem pela função');

  -- apontar com etapa: mão de obra = minutos x custo por hora; entra no custo real e no custo do acabado
  PERFORM ci.entrar(prod); PERFORM mf_ordem_apontar(op, 1, 0, 30, 'et-1', oe_corte); PERFORM ci.sair();
  PERFORM ci.exige((SELECT custo_mao_obra_apontada = 30 AND custo_real = 130 FROM mf_ordens WHERE id = op), 'custo real = insumo (100) + mão de obra de 30 min a 60/h (30)');
  PERFORM ci.exige((SELECT minutos_apontados = 30 FROM mf_ordem_etapas WHERE id = oe_corte), 'minutos da etapa somados');
  PERFORM ci.exige((SELECT custo_medio = 130 FROM estoques WHERE produto_id = arm AND deposito_id = dep_d), 'o acabado leva a mão de obra no custo');
  PERFORM ci.exige((SELECT ordem_etapa_id = oe_corte FROM mf_apontamentos WHERE chave_idempotente = 'et-1'), 'o apontamento guarda a etapa');

  -- repetir a chave não soma minutos nem custo de novo; etapa de outra ordem é recusada
  PERFORM ci.entrar(prod); PERFORM mf_ordem_apontar(op, 1, 0, 30, 'et-1', oe_corte); PERFORM ci.sair();
  PERFORM ci.exige((SELECT minutos_apontados = 30 FROM mf_ordem_etapas WHERE id = oe_corte) AND (SELECT custo_mao_obra_apontada = 30 FROM mf_ordens WHERE id = op), 'chave repetida não soma mão de obra');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_apontar(%L, 1, 0, 10, 'et-outra', %L)$c$, op, oe_outro), 'etapa de outra ordem');

  -- sem etapa os minutos ficam só registrados, sem custo
  PERFORM ci.entrar(prod); PERFORM mf_ordem_apontar(op, 1, 0, 10, 'et-2', NULL); PERFORM ci.sair();
  PERFORM ci.exige((SELECT custo_mao_obra_apontada = 30 AND custo_real = 230 FROM mf_ordens WHERE id = op), 'sem etapa não há custo de mão de obra');
  PERFORM ci.exige((SELECT minutos = 10 AND ordem_etapa_id IS NULL FROM mf_apontamentos WHERE chave_idempotente = 'et-2'), 'minutos sem etapa ficam registrados');
  PERFORM ci.exige((SELECT custo_medio = 115 FROM estoques WHERE produto_id = arm AND deposito_id = dep_d), 'custo médio do acabado: (130 + 100) / 2');

  -- concluir soma a mão de obra apontada e a manual da ordem
  PERFORM ci.entrar(gest); PERFORM mf_ordem_concluir(op); PERFORM ci.sair();
  PERFORM ci.exige((SELECT custo_real = 280 FROM mf_ordens WHERE id = op), 'custo real final = insumos (200) + mão de obra apontada (30) + manual (50)');

  -- só existe uma versão da função de apontar
  PERFORM ci.exige((SELECT count(*) = 1 FROM pg_proc WHERE proname = 'mf_ordem_apontar' AND pronamespace = 'public'::regnamespace), 'só uma versão de mf_ordem_apontar');

  DELETE FROM mf_apontamentos WHERE tenant_id = demo;
  DELETE FROM mf_ordens WHERE tenant_id = demo;
  DELETE FROM mf_etapas WHERE tenant_id = demo;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
  DELETE FROM user_roles WHERE user_id = prod;
END $$;

-- 83. Manufatura: tempo de uma etapa sem repetir a produção (a mesma peça passa por mais de uma etapa)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  prod constant uuid := 'a0000000-0000-0000-0000-0000000001b2';
  emp uuid; dep_i uuid; dep_d uuid; arm uuid; ins uuid; op uuid; et1 uuid; et2 uuid; oe1 uuid; oe2 uuid; est_ins numeric; est_arm numeric;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (prod, 'producao-tempo@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = prod;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (prod, demo, 'producao');
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Insumos CI 4') RETURNING id INTO dep_i;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Acabados CI 4') RETURNING id INTO dep_d;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-ARM-T', 'Armário tempo CI', 'un', 0) RETURNING id INTO arm;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-INS-T', 'Chapa tempo CI', 'chapa', 100) RETURNING id INTO ins;
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade, reservado, custo_medio) VALUES (demo, ins, dep_i, 50, 0, 100);
  INSERT INTO mf_etapas (tenant_id, nome, ordem, custo_hora) VALUES (demo, 'Corte T', 10, 60), (demo, 'Montagem T', 20, 120);
  SELECT id INTO et1 FROM mf_etapas WHERE tenant_id = demo AND nome = 'Corte T';
  SELECT id INTO et2 FROM mf_etapas WHERE tenant_id = demo AND nome = 'Montagem T';

  PERFORM ci.entrar(gest);
  op := mf_ordem_criar(jsonb_build_object('descricao', 'Armários com tempo por etapa', 'produto_id', arm, 'quantidade_planejada', 2, 'entrada_estoque', true,
          'deposito_insumos_id', dep_i, 'deposito_destino_id', dep_d, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 1))));
  PERFORM mf_ordem_liberar(op);
  PERFORM ci.sair();
  SELECT id INTO oe1 FROM mf_ordem_etapas WHERE ordem_id = op AND nome = 'Corte T';
  SELECT id INTO oe2 FROM mf_ordem_etapas WHERE ordem_id = op AND nome = 'Montagem T';

  -- as 2 peças são produzidas uma vez (na última etapa); o tempo das duas etapas entra sem repetir a produção
  PERFORM ci.entrar(prod);
  PERFORM mf_ordem_apontar(op, 0, 0, 60, 'tempo-corte', oe1);
  PERFORM mf_ordem_apontar(op, 2, 0, 90, 'tempo-montagem-e-producao', oe2);
  PERFORM ci.sair();
  SELECT quantidade INTO est_ins FROM estoques WHERE produto_id = ins AND deposito_id = dep_i;
  SELECT quantidade INTO est_arm FROM estoques WHERE produto_id = arm AND deposito_id = dep_d;
  PERFORM ci.exige(est_ins = 48, 'só a produção das 2 peças consome insumo (50 - 2), o tempo sozinho não consome');
  PERFORM ci.exige(est_arm = 2, 'só a produção dá entrada no estoque do acabado');
  PERFORM ci.exige((SELECT minutos_apontados = 60 FROM mf_ordem_etapas WHERE id = oe1) AND (SELECT minutos_apontados = 90 FROM mf_ordem_etapas WHERE id = oe2), 'minutos de cada etapa registrados');
  -- 60 min a 60/h = 60; 90 min a 120/h = 180; insumos 2 x 100 = 200
  PERFORM ci.exige((SELECT custo_mao_obra_apontada = 240 AND custo_real = 440 AND quantidade_produzida = 2 FROM mf_ordens WHERE id = op), 'custo real = insumos (200) + mão de obra das 2 etapas (60 + 180)');
  PERFORM ci.exige((SELECT custo_medio = 220 FROM estoques WHERE produto_id = arm AND deposito_id = dep_d), 'o custo do acabado leva a mão de obra do tempo apontado antes: (200 + 240) / 2');

  -- repetir a chave do tempo não soma de novo
  PERFORM ci.entrar(prod); PERFORM mf_ordem_apontar(op, 0, 0, 60, 'tempo-corte', oe1); PERFORM ci.sair();
  PERFORM ci.exige((SELECT minutos_apontados = 60 FROM mf_ordem_etapas WHERE id = oe1), 'repetir a chave do tempo não soma minutos');

  -- sem etapa ou sem minutos, ainda é preciso informar peça boa ou refugo
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_apontar(%L, 0, 0, 30, 'so-minutos-sem-etapa', NULL)$c$, op), 'só minutos sem etapa');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_ordem_apontar(%L, 0, 0, 0, 'etapa-sem-minutos', %L)$c$, op, oe1), 'etapa sem minutos nem produção');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO mf_apontamentos (tenant_id, ordem_id, chave_idempotente, minutos) VALUES (%L, %L, 'direto-sem-etapa', 30)$c$, demo, op), 'tabela aceita só minutos sem etapa');

  DELETE FROM mf_apontamentos WHERE tenant_id = demo;
  DELETE FROM mf_ordens WHERE tenant_id = demo;
  DELETE FROM mf_etapas WHERE tenant_id = demo;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
  DELETE FROM user_roles WHERE user_id = prod;
END $$;

-- 84. Manufatura: necessidade de materiais (demanda sem reserva, saldo livre, o que já está pedido) e o pedido de compra em rascunho
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  prod constant uuid := 'a0000000-0000-0000-0000-0000000001b3';
  comp constant uuid := 'a0000000-0000-0000-0000-0000000001b4';
  u2   constant uuid := 'a0000000-0000-0000-0000-0000000001b5';
  emp uuid; t2 uuid; emp2 uuid; dep uuid; dep_n uuid; ins uuid; ins2 uuid; opa uuid; opb uuid; opc uuid; compra uuid; r record; n integer; numa bigint;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (prod, 'prod-nec@ci'), (comp, 'comprador-nec@ci'), (u2, 'outra-nec@ci');
  INSERT INTO tenants (nome) VALUES ('Necessidade CI 2') RETURNING id INTO t2;
  INSERT INTO empresas (tenant_id, razao_social) VALUES (t2, 'Marcenaria Nec CI 2') RETURNING id INTO emp2;
  UPDATE profiles SET tenant_id = demo WHERE id IN (prod, comp);
  UPDATE profiles SET tenant_id = t2 WHERE id = u2;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (prod, demo, 'producao'), (comp, demo, 'comprador'), (u2, t2, 'administrador');
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Necessidade CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-NEC-1', 'Chapa necessidade CI', 'chapa', 100) RETURNING id INTO ins;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-NEC-2', 'Ferragem necessidade CI', 'un', 5) RETURNING id INTO ins2;
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade, reservado, custo_medio) VALUES (demo, ins, dep, 10, 0, 100), (demo, ins2, dep, 1000, 0, 5);

  -- ordem B liberada reserva 6 chapas (saldo livre cai para 4); ordem A planejada precisa de 15
  PERFORM ci.entrar(gest);
  opb := mf_ordem_criar(jsonb_build_object('descricao', 'Ordem B liberada', 'quantidade_planejada', 1, 'deposito_insumos_id', dep,
           'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 6))));
  PERFORM mf_ordem_liberar(opb);
  opa := mf_ordem_criar(jsonb_build_object('descricao', 'Ordem A planejada', 'quantidade_planejada', 1, 'deposito_insumos_id', dep,
           'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 15), jsonb_build_object('insumo_id', ins2, 'quantidade', 20))));
  PERFORM ci.sair();
  SELECT numero INTO numa FROM mf_ordens WHERE id = opa;

  PERFORM ci.entrar(gest);
  SELECT * INTO r FROM mf_necessidade() WHERE insumo_id = ins;
  PERFORM ci.sair();
  PERFORM ci.exige(r.necessario = 21 AND r.disponivel = 10 AND r.em_compra = 0 AND r.falta = 11, 'chapa: precisam 21 (15 da planejada + 6 da liberada), há 10 no físico, falta 11');
  PERFORM ci.exige(r.ordens @> ARRAY['OP-' || numa] AND cardinality(r.ordens) = 2, 'as duas ordens abertas aparecem na necessidade');
  PERFORM ci.exige(r.custo_unitario = 100 AND r.deposito = 'MF Necessidade CI', 'custo de referência e depósito da necessidade');
  PERFORM ci.entrar(gest);
  SELECT * INTO r FROM mf_necessidade() WHERE insumo_id = ins2;
  PERFORM ci.sair();
  PERFORM ci.exige(r.necessario = 20 AND r.falta = 0, 'ferragem com saldo de sobra aparece como coberta (falta 0)');

  -- o que já está pedido ao fornecedor abate a falta (pedido de compra em rascunho pela função de compras já existente)
  PERFORM ci.entrar(comp);
  compra := compra_criar_de_sugestao(dep, NULL, jsonb_build_array(jsonb_build_object('produto_id', ins, 'quantidade', 5)), 'Necessidade da manufatura CI');
  SELECT * INTO r FROM mf_necessidade() WHERE insumo_id = ins;
  PERFORM ci.sair();
  PERFORM ci.exige(r.em_compra = 5 AND r.falta = 6, 'pedido de compra aberto de 5 abate a falta: 21 - 10 - 5 = 6');
  PERFORM ci.exige((SELECT origem = 'sugestao_reposicao' AND situacao NOT IN ('recebido', 'cancelado') FROM compras WHERE id = compra), 'o pedido de compra nasce em rascunho para conferência');

  -- cancelar a ordem planejada tira o insumo da necessidade
  PERFORM ci.entrar(gest); PERFORM mf_ordem_cancelar(opa); SELECT count(*) INTO n FROM mf_necessidade() WHERE falta > 0; PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'sem a ordem planejada nada falta (a liberada está coberta pelo estoque)');

  -- depósito que permite saldo negativo: ordem liberada sem estoque físico reserva além do saldo e a compra continua necessária
  INSERT INTO depositos (tenant_id, nome, permite_negativo) VALUES (demo, 'MF Necessidade negativo CI', true) RETURNING id INTO dep_n;
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade, reservado, custo_medio) VALUES (demo, ins, dep_n, 0, 0, 100);
  PERFORM ci.entrar(gest);
  opc := mf_ordem_criar(jsonb_build_object('descricao', 'Ordem C sem estoque físico', 'quantidade_planejada', 1, 'deposito_insumos_id', dep_n,
           'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 6))));
  PERFORM mf_ordem_liberar(opc);
  SELECT * INTO r FROM mf_necessidade() WHERE insumo_id = ins AND deposito_id = dep_n;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT reservado = 6 FROM estoques WHERE produto_id = ins AND deposito_id = dep_n), 'a ordem reservou 6 sem saldo físico (depósito permite negativo)');
  PERFORM ci.exige(r.necessario = 6 AND r.disponivel = 0 AND r.falta = 6, 'a reserva sem estoque físico continua aparecendo como falta de compra');

  -- perfis: produção e vendedor não consultam; comprador consulta; outra empresa não tem o módulo
  PERFORM ci.deve_falhar(prod, $c$SELECT * FROM mf_necessidade()$c$, 'produção consulta a necessidade');
  PERFORM ci.deve_falhar(vend, $c$SELECT * FROM mf_necessidade()$c$, 'vendedor consulta a necessidade');
  PERFORM ci.deve_falhar(u2, $c$SELECT * FROM mf_necessidade()$c$, 'empresa sem o módulo consulta a necessidade');
  PERFORM ci.entrar(comp); SELECT count(*) INTO n FROM mf_necessidade(); PERFORM ci.sair();
  PERFORM ci.exige(n >= 1, 'comprador consulta a necessidade');

  DELETE FROM mf_ordens WHERE tenant_id = demo;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
  DELETE FROM user_roles WHERE user_id IN (prod, comp, u2);
  DELETE FROM empresas WHERE id = emp2;
END $$;

-- 85. Manufatura: margem do pedido sob medida (receita do pedido x custo real das ordens ligadas a ele)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  prod constant uuid := 'a0000000-0000-0000-0000-0000000001b6';
  u2 constant uuid := 'a0000000-0000-0000-0000-0000000001b7';
  emp uuid; emp2 uuid; dep uuid; ins uuid; cli uuid; ped uuid; ped2 uuid; op uuid; op2 uuid; op3 uuid; r record; n integer;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (prod, 'producao-margem@ci'), (u2, 'outra-margem@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = prod;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (prod, demo, 'producao');
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Margem CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-INS-M', 'Chapa margem CI', 'chapa', 100) RETURNING id INTO ins;
  INSERT INTO estoques (tenant_id, produto_id, deposito_id, quantidade, reservado, custo_medio) VALUES (demo, ins, dep, 50, 0, 100);
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Cliente margem CI') RETURNING id INTO cli;
  INSERT INTO pedidos (tenant_id, cliente_id, deposito_id, situacao, subtotal, total) VALUES (demo, cli, dep, 'aprovado', 1000, 1000) RETURNING id INTO ped;
  INSERT INTO pedidos (tenant_id, cliente_id, deposito_id, situacao, subtotal, total) VALUES (demo, cli, dep, 'cancelado', 500, 500) RETURNING id INTO ped2;

  PERFORM ci.entrar(gest);
  op := mf_ordem_criar(jsonb_build_object('descricao', 'Armário do pedido', 'quantidade_planejada', 1, 'deposito_insumos_id', dep, 'pedido_id', ped,
          'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 3))));
  op2 := mf_ordem_criar(jsonb_build_object('descricao', 'Painel do pedido', 'quantidade_planejada', 1, 'deposito_insumos_id', dep, 'pedido_id', ped,
          'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 1))));
  op3 := mf_ordem_criar(jsonb_build_object('descricao', 'Ordem de pedido cancelado', 'quantidade_planejada', 1, 'deposito_insumos_id', dep, 'pedido_id', ped2,
          'itens', jsonb_build_array(jsonb_build_object('insumo_id', ins, 'quantidade', 1))));
  PERFORM mf_ordem_liberar(op);
  PERFORM mf_ordem_apontar(op, 1, 0, NULL, 'mg-1', NULL);
  PERFORM mf_ordem_concluir(op);
  SELECT * INTO r FROM mf_margem_pedidos(current_date, current_date) WHERE pedido_id = ped;
  SELECT count(*) INTO n FROM mf_margem_pedidos(current_date, current_date) WHERE pedido_id = ped2;
  PERFORM ci.sair();
  PERFORM ci.exige(r.receita = 1000 AND r.cliente = 'Cliente margem CI', 'a receita é o total do pedido');
  PERFORM ci.exige(r.custo_real = 300 AND r.ordens = 2 AND r.ordens_abertas = 1, 'custo real só da ordem concluída (3 x 100) e a outra segue aberta');
  PERFORM ci.exige(r.custo_estimado = 400, 'custo estimado soma as duas ordens (3 + 1 chapas)');
  PERFORM ci.exige(n = 0, 'pedido cancelado não entra na margem');

  PERFORM ci.deve_falhar(prod, $c$SELECT * FROM mf_margem_pedidos(current_date, current_date)$c$, 'produção consulta a margem');
  PERFORM ci.deve_falhar(u2, $c$SELECT * FROM mf_margem_pedidos(current_date, current_date)$c$, 'empresa sem o módulo consulta a margem');
  PERFORM ci.deve_falhar(gest, $c$SELECT * FROM mf_margem_pedidos(current_date, current_date - 1)$c$, 'período invertido');

  DELETE FROM mf_apontamentos WHERE tenant_id = demo;
  DELETE FROM mf_ordens WHERE tenant_id = demo;
  DELETE FROM pedidos WHERE id IN (ped, ped2);
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
  DELETE FROM user_roles WHERE user_id = prod;
END $$;

-- 86. Manufatura: semiacabado (matéria-prima total abrindo as listas ativas) e bloqueio de ciclo entre listas
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  prod constant uuid := 'a0000000-0000-0000-0000-0000000001b8';
  emp uuid; arm uuid; porta uuid; gav uuid; chapa uuid; ferr uuid; b_porta uuid; b_arm uuid; b_gav uuid; b_porta2 uuid; r record; n integer;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (prod, 'producao-semi@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = prod;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (prod, demo, 'producao');
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-ARM-S', 'Armário semi CI', 'un', 0) RETURNING id INTO arm;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-POR-S', 'Porta semi CI', 'un', 0) RETURNING id INTO porta;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-GAV-S', 'Gaveta semi CI', 'un', 0) RETURNING id INTO gav;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-CHA-S', 'Chapa semi CI', 'chapa', 100) RETURNING id INTO chapa;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-FER-S', 'Ferragem semi CI', 'un', 5) RETURNING id INTO ferr;

  PERFORM ci.entrar(gest);
  -- porta: 3 chapas rendem 2 portas; armário: 2 portas + 4 ferragens + 1 chapa com 20% de perda
  b_porta := mf_bom_salvar(jsonb_build_object('produto_id', porta, 'rendimento', 2, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', chapa, 'quantidade', 3))));
  PERFORM mf_bom_ativar(b_porta);
  b_arm := mf_bom_salvar(jsonb_build_object('produto_id', arm, 'itens', jsonb_build_array(
             jsonb_build_object('insumo_id', porta, 'quantidade', 2), jsonb_build_object('insumo_id', ferr, 'quantidade', 4),
             jsonb_build_object('insumo_id', chapa, 'quantidade', 1, 'perda_percentual', 20))));
  PERFORM mf_bom_ativar(b_arm);
  SELECT * INTO r FROM mf_bom_explodir(b_arm, 1) WHERE insumo_id = chapa;
  SELECT count(*) INTO n FROM mf_bom_explodir(b_arm, 1);
  PERFORM ci.sair();
  PERFORM ci.exige(r.quantidade = 4.25, 'chapa total: 2 portas (3 chapas por 2 portas = 3) + 1 chapa com 20% de perda (1,25) = 4,25');
  PERFORM ci.exige(r.valor = 425 AND r.custo_unitario = 100, 'valor da chapa pelo custo de referência');
  PERFORM ci.exige(n = 2, 'só a matéria-prima volta (chapa e ferragem), a porta foi aberta');
  PERFORM ci.entrar(gest);
  SELECT * INTO r FROM mf_bom_explodir(b_arm, 2) WHERE insumo_id = ferr;
  PERFORM ci.sair();
  PERFORM ci.exige(r.quantidade = 8 AND r.valor = 40, 'a quantidade multiplica: 2 armários = 8 ferragens');

  -- ciclo direto no salvar: a porta ativa não chega ao armário, mas o armário ativo chega à porta
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_bom_salvar(jsonb_build_object('produto_id', %L::uuid, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', %L::uuid, 'quantidade', 1))))$c$, porta, arm), 'porta usando o armário que usa a porta');

  -- ciclo só na ativação: rascunho da porta usa a gaveta (ainda sem lista); depois a gaveta passa a usar a porta; ativar a porta fecha o ciclo
  PERFORM ci.entrar(gest);
  b_porta2 := mf_bom_salvar(jsonb_build_object('produto_id', porta, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', gav, 'quantidade', 1))));
  b_gav := mf_bom_salvar(jsonb_build_object('produto_id', gav, 'itens', jsonb_build_array(jsonb_build_object('insumo_id', porta, 'quantidade', 1))));
  PERFORM mf_bom_ativar(b_gav);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_bom_ativar(%L::uuid)$c$, b_porta2), 'ativar a porta quando a gaveta ativa já usa a porta');
  PERFORM ci.exige((SELECT situacao = 'rascunho' FROM mf_boms WHERE id = b_porta2), 'a lista que fecharia o ciclo continua rascunho');
  PERFORM ci.exige((SELECT situacao = 'ativa' FROM mf_boms WHERE id = b_porta), 'a versão ativa anterior da porta não foi trocada');

  -- perfis: produção não abre a lista (tem custo)
  PERFORM ci.deve_falhar(prod, format($c$SELECT * FROM mf_bom_explodir(%L::uuid, 1)$c$, b_arm), 'produção abre a matéria-prima total');
  PERFORM ci.deve_falhar(gest, format($c$SELECT * FROM mf_bom_explodir(%L::uuid, 0)$c$, b_arm), 'quantidade zero');

  DELETE FROM mf_bom_itens WHERE tenant_id = demo;
  DELETE FROM mf_boms WHERE tenant_id = demo;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
  DELETE FROM user_roles WHERE user_id = prod;
END $$;

-- 87. Manufatura: semiacabado em níveis demais é recusado em vez de devolver total incompleto
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  emp uuid; raw uuid; p uuid[] := ARRAY[]::uuid[]; b uuid[] := ARRAY[]::uuid[]; i integer; r record; n integer;
BEGIN
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-RAW-N', 'Matéria-prima nível CI', 'un', 10) RETURNING id INTO raw;
  FOR i IN 0..9 LOOP
    INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo) VALUES (demo, 'MF-N' || i, 'Nível ' || i || ' CI', 'un', 0) RETURNING id INTO r;
    p := p || r.id;
  END LOOP;
  PERFORM ci.entrar(gest);
  -- cadeia p0 -> p1 -> ... -> p9 -> matéria-prima (10 níveis); cria de baixo para cima, ativando cada lista
  b := b || mf_bom_salvar(jsonb_build_object('produto_id', p[10], 'itens', jsonb_build_array(jsonb_build_object('insumo_id', raw, 'quantidade', 1))));
  PERFORM mf_bom_ativar(b[1]);
  FOR i IN REVERSE 9..1 LOOP
    b := b || mf_bom_salvar(jsonb_build_object('produto_id', p[i], 'itens', jsonb_build_array(jsonb_build_object('insumo_id', p[i + 1], 'quantidade', 1))));
    PERFORM mf_bom_ativar(b[array_length(b, 1)]);
  END LOOP;
  -- a partir de p6 (4 níveis até a matéria-prima) calcula; p0 (10 níveis) é recusado
  SELECT * INTO r FROM mf_bom_explodir(b[array_length(b, 1) - 3], 1);
  PERFORM ci.sair();
  PERFORM ci.exige(r.quantidade = 1 AND r.valor = 10, 'cadeia curta calcula a matéria-prima');
  PERFORM ci.deve_falhar(gest, format($c$SELECT * FROM mf_bom_explodir(%L::uuid, 1)$c$, b[array_length(b, 1)]), 'cadeia de 10 níveis é recusada em vez de dar total incompleto');

  DELETE FROM mf_bom_itens WHERE tenant_id = demo;
  DELETE FROM mf_boms WHERE tenant_id = demo;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
END $$;

-- 88. Manufatura: agenda de entrega e instalação
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  prod constant uuid := 'a0000000-0000-0000-0000-0000000001b9';
  vend constant uuid := 'a0000000-0000-0000-0000-0000000001ba';
  u2 constant uuid := 'a0000000-0000-0000-0000-0000000001bb';
  emp uuid; dep uuid; cli uuid; ped uuid; op uuid; op_can uuid; op_np uuid; ent uuid; ent2 uuid; r record; n integer;
BEGIN
  INSERT INTO auth.users (id, email) VALUES (prod, 'producao-agenda@ci'), (vend, 'vendedor-agenda@ci'), (u2, 'outra-agenda@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (prod, vend);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (prod, demo, 'producao'), (vend, demo, 'vendedor');
  SELECT id INTO emp FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'manufatura');
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'MF Agenda CI') RETURNING id INTO dep;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Cliente agenda CI') RETURNING id INTO cli;
  INSERT INTO pedidos (tenant_id, cliente_id, deposito_id, situacao, subtotal, total, entrega_endereco, entrega_numero, entrega_bairro, entrega_cidade, entrega_estado)
    VALUES (demo, cli, dep, 'aprovado', 100, 100, 'Rua das Flores', '120', 'Centro', 'Recife', 'PE') RETURNING id INTO ped;

  PERFORM ci.entrar(gest);
  op := mf_ordem_criar(jsonb_build_object('descricao', 'Armário agenda', 'quantidade_planejada', 1, 'deposito_insumos_id', dep, 'pedido_id', ped,
          'itens', '[]'::jsonb));
  op_can := mf_ordem_criar(jsonb_build_object('descricao', 'Ordem cancelada agenda', 'quantidade_planejada', 1, 'deposito_insumos_id', dep, 'itens', '[]'::jsonb));
  PERFORM mf_ordem_cancelar(op_can);
  op_np := mf_ordem_criar(jsonb_build_object('descricao', 'Ordem sem pedido agenda', 'quantidade_planejada', 1, 'deposito_insumos_id', dep, 'itens', '[]'::jsonb));
  -- endereço vazio usa o do pedido da ordem
  ent := mf_entrega_salvar(jsonb_build_object('ordem_id', op, 'tipo', 'entrega_instalacao', 'data', current_date + 3, 'hora', '09:30', 'responsavel', 'Equipe 1'));
  SELECT * INTO r FROM mf_entregas_agenda(current_date, current_date + 7) WHERE id = ent;
  PERFORM ci.sair();
  PERFORM ci.exige(r.endereco = 'Rua das Flores, 120, Centro, Recife, PE' AND r.cliente = 'Cliente agenda CI' AND r.ordem_numero IS NOT NULL, 'endereço e cliente vêm do pedido da ordem');
  PERFORM ci.exige(r.situacao = 'agendada' AND r.hora = '09:30'::time AND r.responsavel = 'Equipe 1', 'compromisso nasce agendado com hora e responsável');

  -- validações
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_entrega_salvar(jsonb_build_object('ordem_id', %L::uuid, 'tipo', 'entrega', 'data', current_date, 'endereco', 'Rua X'))$c$, op_can), 'agendar para ordem cancelada');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_entrega_salvar(jsonb_build_object('ordem_id', %L::uuid, 'tipo', 'voo', 'data', current_date, 'endereco', 'Rua X'))$c$, op), 'tipo inválido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_entrega_salvar(jsonb_build_object('ordem_id', %L::uuid, 'tipo', 'entrega', 'data', current_date))$c$, op_np), 'ordem sem pedido e sem endereço informado');

  -- ordem sem pedido e sem endereço informado: exige o endereço; informado, salva
  PERFORM ci.entrar(gest);
  ent2 := mf_entrega_salvar(jsonb_build_object('ordem_id', op, 'tipo', 'instalacao', 'data', current_date + 5, 'endereco', 'Av. Brasil, 10'));
  PERFORM mf_entrega_salvar(jsonb_build_object('id', ent2, 'ordem_id', op, 'tipo', 'instalacao', 'data', current_date + 6, 'endereco', 'Av. Brasil, 10'));
  SELECT data INTO r FROM mf_entregas WHERE id = ent2;
  PERFORM ci.sair();
  PERFORM ci.exige(r.data = current_date + 6, 'reagendar muda a data');

  -- produção lê a agenda e avança, mas não cria nem cancela
  PERFORM ci.entrar(prod); SELECT count(*) INTO n FROM mf_entregas_agenda(current_date, current_date + 10); PERFORM ci.sair();
  PERFORM ci.exige(n = 2, 'produção lê a agenda');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_entrega_salvar(jsonb_build_object('ordem_id', %L::uuid, 'tipo', 'entrega', 'data', current_date, 'endereco', 'Rua X'))$c$, op), 'produção cria compromisso');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_entrega_situacao(%L::uuid, 'cancelada')$c$, ent), 'produção cancela');
  PERFORM ci.entrar(prod); PERFORM mf_entrega_situacao(ent, 'em_andamento'); PERFORM mf_entrega_situacao(ent, 'concluida'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'concluida' AND concluida_em IS NOT NULL FROM mf_entregas WHERE id = ent), 'produção conclui e registra quando');
  PERFORM ci.deve_falhar(prod, format($c$SELECT mf_entrega_situacao(%L::uuid, 'em_andamento')$c$, ent), 'compromisso concluído não volta');
  PERFORM ci.deve_falhar(gest, format($c$SELECT mf_entrega_salvar(jsonb_build_object('id', %L::uuid, 'tipo', 'entrega', 'data', current_date, 'endereco', 'Rua X'))$c$, ent), 'reagendar compromisso concluído');
  PERFORM ci.entrar(gest); PERFORM mf_entrega_situacao(ent2, 'cancelada'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM mf_entregas WHERE id = ent2), 'gestão cancela');

  -- leitura direta da tabela só da gestão; vendedor e outra empresa não leem pela função
  PERFORM ci.entrar(gest); SELECT count(*) INTO n FROM mf_entregas; PERFORM ci.sair();
  PERFORM ci.exige(n = 2, 'gestão lê a tabela');
  PERFORM ci.entrar(prod); SELECT count(*) INTO n FROM mf_entregas; PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'produção não lê a tabela direto');
  PERFORM ci.deve_falhar(vend, $c$SELECT * FROM mf_entregas_agenda(current_date, current_date + 1)$c$, 'vendedor lê a agenda');
  PERFORM ci.deve_falhar(u2, $c$SELECT * FROM mf_entregas_agenda(current_date, current_date + 1)$c$, 'empresa sem o módulo lê a agenda');
  PERFORM ci.deve_falhar(gest, $c$SELECT * FROM mf_entregas_agenda(current_date, current_date + 400)$c$, 'período maior que um ano');

  DELETE FROM mf_entregas WHERE tenant_id = demo;
  DELETE FROM mf_ordens WHERE tenant_id = demo;
  DELETE FROM pedidos WHERE id = ped;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'manufatura';
  DELETE FROM user_roles WHERE user_id IN (prod, vend);
END $$;

-- 89. Pet: microchip, foto, pesagens e farmacêutico (CRF)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  ub   constant uuid := 'a0000000-0000-0000-0000-0000000001c1';
  tb uuid; tutor uuid; tutor_b uuid; pet uuid; pet2 uuid; pet_b uuid; pes uuid; pes2 uuid; prof uuid; v_foto text;
BEGIN
  v_foto := 'data:image/jpeg;base64,' || repeat('A', 400);
  INSERT INTO tenants (nome) VALUES ('Pet ficha B') RETURNING id INTO tb;
  INSERT INTO auth.users (id, email) VALUES (ub, 'pet-ficha-b@ci');
  UPDATE profiles SET tenant_id = tb WHERE id = ub;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (ub, tb, 'administrador');
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Tutor ficha CI') RETURNING id INTO tutor;
  INSERT INTO clientes (tenant_id, nome) VALUES (tb, 'Tutor ficha B') RETURNING id INTO tutor_b;

  -- microchip e foto
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Chip', 'microchip', '123'))$c$, tutor), 'microchip curto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Chip', 'foto', 'data:image/png;base64,AAAA'))$c$, tutor), 'foto que não é JPEG');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Chip', 'foto', 'data:image/jpeg;base64,' || repeat('A', 130000)))$c$, tutor), 'foto grande demais');
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Chipado', 'microchip', '985 112-345.678', 'foto', v_foto, 'peso_kg', 4));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT microchip = '985112345678' AND foto = v_foto FROM pets WHERE id = pet), 'microchip só com números e foto guardados');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_salvar(jsonb_build_object('cliente_id', %L, 'nome', 'Outro', 'microchip', '985112345678'))$c$, tutor), 'microchip repetido na empresa');
  PERFORM ci.entrar(vend);
  pet2 := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Outro', 'microchip', '985112345679'));
  -- editar sem as chaves não apaga foto nem microchip; com a chave nula remove
  PERFORM pet_salvar(jsonb_build_object('id', pet, 'cliente_id', tutor, 'nome', 'Chipado', 'peso_kg', 4));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT microchip = '985112345678' AND foto IS NOT NULL FROM pets WHERE id = pet), 'salvar sem as chaves mantém foto e microchip');
  PERFORM ci.entrar(vend);
  PERFORM pet_salvar(jsonb_build_object('id', pet, 'cliente_id', tutor, 'nome', 'Chipado', 'peso_kg', 4, 'foto', NULL, 'microchip', NULL));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT microchip IS NULL AND foto IS NULL FROM pets WHERE id = pet), 'chave nula remove foto e microchip');
  PERFORM ci.entrar(ub);
  pet_b := pet_salvar(jsonb_build_object('cliente_id', tutor_b, 'nome', 'Outra empresa', 'microchip', '985112345679'));
  PERFORM ci.sair();
  PERFORM ci.exige(pet_b IS NOT NULL, 'o mesmo microchip vale em outra empresa');

  -- pesagens
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_pesagem_registrar(%L, 5)$c$, pet), 'garçom pesa');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT pet_pesagem_registrar(%L, 5)$c$, pet), 'anon pesa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pesagem_registrar(%L, 0)$c$, pet), 'peso zero');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pesagem_registrar(%L, 250)$c$, pet), 'peso acima de 200 kg');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pesagem_registrar(%L, 5, current_date + 10)$c$, pet), 'pesagem no futuro');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pesagem_registrar(%L, 5)$c$, pet_b), 'pet de outra empresa');
  PERFORM ci.entrar(vend);
  pes := pet_pesagem_registrar(pet, 5.2, current_date - 10, 'primeira');
  pes2 := pet_pesagem_registrar(pet, 5.8, current_date, NULL);
  PERFORM pet_pesagem_registrar(pet, 4.9, current_date - 30);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT peso_kg = 5.8 FROM pets WHERE id = pet), 'o peso do cadastro acompanha a pesagem mais recente (mesmo lançada fora de ordem)');
  PERFORM ci.exige(ci.contar(vend, format('SELECT count(*) FROM pet_pesagens WHERE pet_id = %L', pet)) = 3, 'vendedor lê as pesagens');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM pet_pesagens') = 0, 'garçom não lê pesagens');
  PERFORM ci.exige(ci.contar(ub, 'SELECT count(*) FROM pet_pesagens') = 0, 'outra empresa não lê as pesagens');
  PERFORM ci.deve_falhar(vend, format($c$INSERT INTO pet_pesagens (pet_id, peso_kg) VALUES (%L, 9)$c$, pet), 'gravar pesagem direto na tabela');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_pesagem_excluir(%L)$c$, pes2), 'vendedor exclui pesagem');
  PERFORM ci.deve_falhar(ub, format($c$SELECT pet_pesagem_excluir(%L)$c$, pes2), 'outra empresa exclui pesagem');
  PERFORM ci.entrar(gest);
  PERFORM pet_pesagem_excluir(pes2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT peso_kg = 5.2 FROM pets WHERE id = pet), 'excluir a mais recente volta o peso para a anterior');

  -- farmacêutico com CRF
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_profissional_salvar('{"nome":"Farma","funcao":"farmaceutico"}'::jsonb)$c$, 'farmacêutico sem CRF');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_profissional_salvar('{"nome":"Farma","funcao":"farmaceutico","crf":"12345","crf_uf":"XX"}'::jsonb)$c$, 'farmacêutico com UF inválida');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_profissional_salvar('{"nome":"Farma","funcao":"farmaceutico","crf":"12345","crf_uf":"PE"}'::jsonb)$c$, 'vendedor cria farmacêutico');
  PERFORM ci.entrar(adm);
  prof := pet_profissional_salvar('{"nome":"Farma CI","funcao":"farmaceutico","crf":"12.345","crf_uf":"PE","crmv":"999","crmv_uf":"PE","cpf":"529.982.247-25"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT crf = '12345' AND crf_uf = 'PE' AND crmv IS NULL FROM pet_profissionais WHERE id = prof), 'farmacêutico guarda o CRF (sem CRMV)');
  PERFORM ci.entrar(adm);
  PERFORM pet_profissional_salvar(jsonb_build_object('id', prof, 'nome', 'Farma CI', 'funcao', 'banhista'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT crf IS NULL AND crf_uf IS NULL FROM pet_profissionais WHERE id = prof), 'mudar a função limpa o CRF');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_profissionais SET crf = '123' WHERE id = %L$c$, prof), 'CRF sem UF na tabela');

  DELETE FROM pet_pesagens WHERE tenant_id IN (demo, tb);
  DELETE FROM pet_profissionais WHERE id = prof;
  DELETE FROM pets WHERE tenant_id IN (demo, tb) AND nome IN ('Chipado', 'Outro', 'Outra empresa');
END $$;

-- 90. Pet: campos personalizados do animal e do tutor
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  ub   constant uuid := 'a0000000-0000-0000-0000-0000000001c1';
  tb uuid; tutor uuid; tutor_b uuid; pet uuid; pet_b uuid;
  c_txt uuid; c_num uuid; c_data uuid; c_sn uuid; c_lista uuid; c_obr uuid; c_tutor uuid; c_b uuid;
BEGIN
  SELECT tenant_id INTO tb FROM profiles WHERE id = ub;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Tutor campos CI') RETURNING id INTO tutor;
  SELECT id INTO tutor_b FROM clientes WHERE tenant_id = tb LIMIT 1;
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (demo, tutor, 'Campos CI') RETURNING id INTO pet;
  SELECT id INTO pet_b FROM pets WHERE tenant_id = tb LIMIT 1;

  -- definição: só administrador e gestor
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":"X","tipo":"texto"}'::jsonb)$c$, 'vendedor cria campo');
  PERFORM ci.deve_falhar(gar, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":"X","tipo":"texto"}'::jsonb)$c$, 'garçom cria campo');
  PERFORM ci.deve_falhar(NULL, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":"X","tipo":"texto"}'::jsonb)$c$, 'anon cria campo');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":"","tipo":"texto"}'::jsonb)$c$, 'campo sem nome');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_campo_salvar('{"entidade":"clinica","nome":"X","tipo":"texto"}'::jsonb)$c$, 'entidade inválida');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":"X","tipo":"cor"}'::jsonb)$c$, 'tipo inválido');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":"L","tipo":"lista","opcoes":["A"]}'::jsonb)$c$, 'lista com uma opção');
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":"L","tipo":"lista","opcoes":["A","A "]}'::jsonb)$c$, 'lista com opção repetida');

  PERFORM ci.entrar(gest);
  c_txt := pet_campo_salvar('{"entidade":"pet","nome":"Pedigree","tipo":"texto","ordem":2}'::jsonb);
  c_num := pet_campo_salvar('{"entidade":"pet","nome":"Altura (cm)","tipo":"numero"}'::jsonb);
  c_data := pet_campo_salvar('{"entidade":"pet","nome":"Última vermifugação","tipo":"data"}'::jsonb);
  c_sn := pet_campo_salvar('{"entidade":"pet","nome":"Dócil","tipo":"sim_nao"}'::jsonb);
  c_lista := pet_campo_salvar('{"entidade":"pet","nome":"Plano","tipo":"lista","opcoes":["Básico","Premium"]}'::jsonb);
  c_tutor := pet_campo_salvar('{"entidade":"tutor","nome":"Como nos conheceu","tipo":"texto"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(adm, $c$SELECT pet_campo_salvar('{"entidade":"pet","nome":" pedigree ","tipo":"texto"}'::jsonb)$c$, 'nome repetido (sem diferenciar maiúsculas)');
  PERFORM ci.entrar(ub);
  c_b := pet_campo_salvar('{"entidade":"pet","nome":"Pedigree","tipo":"texto"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(c_b IS NOT NULL, 'o mesmo nome vale em outra empresa');

  -- valores
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'x'))$c$, pet, c_txt), 'garçom grava valores');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'abc'))$c$, pet, c_num), 'número inválido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, '2026-02-30'))$c$, pet, c_data), 'data inexistente');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'talvez'))$c$, pet, c_sn), 'sim/não inválido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'Ouro'))$c$, pet, c_lista), 'opção que não está na lista');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'x'))$c$, pet, c_tutor), 'campo do tutor gravado no pet');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'x'))$c$, pet, c_b), 'campo de outra empresa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'x'))$c$, pet_b, c_txt), 'pet de outra empresa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('tutor', %L, jsonb_build_object(%L::text, 'x'))$c$, tutor_b, c_tutor), 'tutor de outra empresa');

  PERFORM ci.entrar(vend);
  PERFORM pet_campos_valores_salvar('pet', pet, jsonb_build_object(c_txt::text, ' CBKC 123 ', c_num::text, '45.5', c_data::text, '2026-03-09',
                                                                  c_sn::text, 'sim', c_lista::text, 'Premium'));
  PERFORM pet_campos_valores_salvar('tutor', tutor, jsonb_build_object(c_tutor::text, 'Indicação'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT valor = 'CBKC 123' FROM pet_campos_valores WHERE campo_id = c_txt AND registro_id = pet), 'o valor é guardado sem espaços nas pontas');
  PERFORM ci.exige(ci.contar(vend, format('SELECT count(*) FROM pet_campos_valores WHERE registro_id IN (%L, %L)', pet, tutor)) = 6, 'vendedor lê os valores do pet e do tutor');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM pet_campos') = 0 AND ci.contar(gar, 'SELECT count(*) FROM pet_campos_valores') = 0, 'garçom não lê campos nem valores');
  PERFORM ci.exige(ci.contar(ub, 'SELECT count(*) FROM pet_campos WHERE nome <> ''Pedigree''') = 0 AND ci.contar(ub, 'SELECT count(*) FROM pet_campos_valores') = 0, 'outra empresa não lê campos nem valores da demo');
  PERFORM ci.deve_falhar(vend, format($c$INSERT INTO pet_campos_valores (campo_id, registro_id, valor) VALUES (%L, %L, 'x')$c$, c_txt, pet), 'gravar valor direto na tabela');
  PERFORM ci.deve_falhar(vend, $c$UPDATE pet_campos SET nome = 'Outro'$c$, 'alterar campo direto na tabela');

  -- valor vazio apaga; o que não veio no pacote fica
  PERFORM ci.entrar(vend);
  PERFORM pet_campos_valores_salvar('pet', pet, jsonb_build_object(c_sn::text, ''));
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM pet_campos_valores WHERE campo_id = c_sn AND registro_id = pet), 'valor vazio apaga');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM pet_campos_valores WHERE campo_id = c_txt AND registro_id = pet), 'o que não veio no pacote continua');

  -- obrigatório
  PERFORM ci.entrar(adm);
  c_obr := pet_campo_salvar('{"entidade":"pet","nome":"Origem","tipo":"texto","obrigatorio":true}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, '{}'::jsonb)$c$, pet), 'obrigatório sem valor (nem veio no pacote)');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, ''))$c$, pet, c_obr), 'obrigatório com valor vazio');
  PERFORM ci.entrar(vend);
  PERFORM pet_campos_valores_salvar('pet', pet, jsonb_build_object(c_obr::text, 'Canil X'));
  PERFORM pet_campos_valores_salvar('pet', pet, '{}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(true, 'obrigatório preenchido salva e deixa salvar de novo sem ele no pacote');

  -- mudar tipo e retirar opção em uso
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_campo_salvar(jsonb_build_object('id', %L::text, 'nome', 'Pedigree', 'tipo', 'numero'))$c$, c_txt), 'mudar o tipo com valores guardados');
  PERFORM ci.deve_falhar(adm, format($c$SELECT pet_campo_salvar(jsonb_build_object('id', %L::text, 'nome', 'Plano', 'tipo', 'lista', 'opcoes', jsonb_build_array('Básico', 'Ouro')))$c$, c_lista), 'retirar da lista uma opção em uso');
  PERFORM ci.entrar(adm);
  PERFORM pet_campo_salvar(jsonb_build_object('id', c_lista, 'nome', 'Plano', 'tipo', 'lista', 'opcoes', jsonb_build_array('Básico', 'Premium', 'Ouro')));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT jsonb_array_length(opcoes) = 3 FROM pet_campos WHERE id = c_lista), 'acrescentar opção na lista');

  -- campo desativado: não aceita valor novo, mas o antigo fica
  PERFORM ci.entrar(adm);
  PERFORM pet_campo_salvar(jsonb_build_object('id', c_txt, 'nome', 'Pedigree', 'tipo', 'texto', 'ativo', false));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_campos_valores_salvar('pet', %L, jsonb_build_object(%L::text, 'novo'))$c$, pet, c_txt), 'valor novo em campo desativado');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM pet_campos_valores WHERE campo_id = c_txt AND registro_id = pet), 'campo desativado mantém o valor antigo');

  DELETE FROM pet_campos WHERE tenant_id IN (demo, tb);
  DELETE FROM pets WHERE id = pet;
  DELETE FROM clientes WHERE id = tutor;
END $$;

-- 91. Pet: ordem de serviço com os dados do animal
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  ub   constant uuid := 'a0000000-0000-0000-0000-0000000001c1';
  tb uuid; tutor uuid; pet uuid; pet_b uuid; dep uuid; prod uuid; serv uuid; prof uuid;
  os uuid; os2 uuid; it_prod uuid; it_serv uuid; it_livre uuid; r jsonb;
BEGIN
  SELECT tenant_id INTO tb FROM profiles WHERE id = ub;
  SELECT id INTO pet_b FROM pets WHERE tenant_id = tb LIMIT 1;
  IF pet_b IS NULL THEN
    INSERT INTO clientes (tenant_id, nome) VALUES (tb, 'Tutor OS B') RETURNING id INTO tutor;
    INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (tb, tutor, 'Pet OS B') RETURNING id INTO pet_b;
  END IF;
  INSERT INTO clientes (tenant_id, nome, telefone) VALUES (demo, 'Tutor OS CI', '81999990000') RETURNING id INTO tutor;
  INSERT INTO pets (tenant_id, cliente_id, nome, especie, raca, alergias, microchip, peso_kg)
    VALUES (demo, tutor, 'Rex OS CI', 'cao', 'Beagle', 'frango', '985000000000001', 12) RETURNING id INTO pet;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Dep OS Pet CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'OSP-RACAO', 'Ração OS Pet', 'un', 20, 35) RETURNING id INTO prod;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda, controla_estoque) VALUES (demo, 'OSP-BANHO', 'Banho OS Pet', 'un', 0, 60, false) RETURNING id INTO serv;
  INSERT INTO pet_profissionais (tenant_id, nome, funcao) VALUES (demo, 'Banhista OS CI', 'banhista') RETURNING id INTO prof;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 10, 'ci', 'ci');
  PERFORM ci.sair();

  -- quem abre a OS do pet
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_os_salvar(jsonb_build_object('pet_id', %L))$c$, pet), 'garçom abre OS do pet');
  PERFORM ci.deve_falhar(est, format($c$SELECT pet_os_salvar(jsonb_build_object('pet_id', %L))$c$, pet), 'estoquista abre OS do pet');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT pet_os_salvar(jsonb_build_object('pet_id', %L))$c$, pet), 'anon abre OS do pet');
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_os_salvar('{}'::jsonb)$c$, 'OS sem animal');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_salvar(jsonb_build_object('pet_id', %L))$c$, pet_b), 'animal de outra empresa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_salvar(jsonb_build_object('pet_id', %L, 'prioridade', 'ontem'))$c$, pet), 'prioridade inválida');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_salvar(jsonb_build_object('pet_id', %L, 'desconto', -1))$c$, pet), 'desconto negativo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_salvar(jsonb_build_object('pet_id', %L, 'profissional_id', %L))$c$, pet, gen_random_uuid()), 'profissional que não existe');

  PERFORM ci.entrar(vend);
  os := pet_os_salvar(jsonb_build_object('pet_id', pet, 'queixa', 'Banho e corte de unhas', 'prioridade', 'alta', 'profissional_id', prof, 'deposito_id', dep));
  PERFORM ci.sair();
  r := (SELECT pet_resumo FROM os_ordens WHERE id = os);
  PERFORM ci.exige(r ->> 'nome' = 'Rex OS CI' AND r ->> 'raca' = 'Beagle' AND r ->> 'alergias' = 'frango' AND r ->> 'tutor' = 'Tutor OS CI'
                   AND r ->> 'microchip' = '985000000000001' AND r ->> 'tutor_telefone' = '81999990000', 'a OS guarda os dados do animal e do tutor');
  PERFORM ci.exige((SELECT numero > 0 AND situacao = 'aberta' AND tecnico_nome = 'Banhista OS CI' AND pet_id = pet AND cliente_id = (SELECT cliente_id FROM pets WHERE id = pet)
                      FROM os_ordens WHERE id = os), 'OS nasce aberta, numerada, com tutor e profissional');

  -- o retrato acompanha o cadastro enquanto a OS está aberta e congela depois da aprovação
  UPDATE pets SET alergias = 'frango e milho' WHERE id = pet;
  PERFORM ci.entrar(vend);
  PERFORM pet_os_salvar(jsonb_build_object('id', os, 'queixa', 'Banho', 'deposito_id', dep, 'profissional_id', prof));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT pet_resumo ->> 'alergias' = 'frango e milho' FROM os_ordens WHERE id = os), 'OS aberta atualiza o retrato do animal');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_salvar(jsonb_build_object('id', %L, 'pet_id', %L))$c$, os, (SELECT id FROM pets WHERE tenant_id = demo AND id <> pet LIMIT 1)), 'trocar o animal da OS');

  -- itens: produto (peça), serviço sem estoque e item livre
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_os_item_adicionar(%L, '{"descricao":"x"}'::jsonb)$c$, os), 'garçom inclui item');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_item_adicionar(%L, '{"descricao":"x","quantidade":0}'::jsonb)$c$, os), 'quantidade zero');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_item_adicionar(%L, '{}'::jsonb)$c$, os), 'item sem produto nem descrição');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_item_adicionar(%L, '{"descricao":"x","preco":-5}'::jsonb)$c$, os), 'preço negativo');
  PERFORM ci.deve_falhar(ub, format($c$SELECT pet_os_item_adicionar(%L, '{"descricao":"x"}'::jsonb)$c$, os), 'outra empresa inclui item');
  PERFORM ci.entrar(vend);
  it_prod := pet_os_item_adicionar(os, jsonb_build_object('produto_id', prod, 'quantidade', 2));
  it_serv := pet_os_item_adicionar(os, jsonb_build_object('produto_id', serv));
  it_livre := pet_os_item_adicionar(os, '{"descricao":"Tosa higiênica","quantidade":1,"preco":25.5}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tipo = 'peca' AND preco_unitario = 35 AND total = 70 FROM os_itens WHERE id = it_prod), 'produto com estoque vira peça, com o preço de venda');
  PERFORM ci.exige((SELECT tipo = 'servico' AND total = 60 FROM os_itens WHERE id = it_serv), 'produto sem controle de estoque vira serviço');
  PERFORM ci.exige((SELECT tipo = 'servico' AND total = 25.5 FROM os_itens WHERE id = it_livre), 'item livre vira serviço');
  PERFORM ci.exige((SELECT valor_pecas = 70 AND valor_servicos = 85.5 AND valor_total = 155.5 FROM os_ordens WHERE id = os), 'totais da OS recalculados');
  PERFORM ci.entrar(vend);
  PERFORM pet_os_salvar(jsonb_build_object('id', os, 'queixa', 'Banho', 'deposito_id', dep, 'desconto', 5.5));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT valor_total = 150 FROM os_ordens WHERE id = os), 'desconto abate do total');
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'antes da aprovação o estoque não muda');

  -- andamento e estoque
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_os_situacao(%L, 'aprovada')$c$, os), 'garçom muda a situação');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_situacao(%L, 'voando')$c$, os), 'situação inválida');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_situacao(%L, 'entregue')$c$, os), 'entregar sem estar pronta');
  PERFORM ci.deve_falhar(ub, format($c$SELECT pet_os_situacao(%L, 'aprovada')$c$, os), 'outra empresa muda a situação');
  PERFORM ci.entrar(vend);
  PERFORM pet_os_situacao(os, 'aprovada', dep);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 8 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'aprovar baixa o produto do estoque (10 - 2)');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM estoques WHERE produto_id = serv), 'o serviço não cria estoque');
  PERFORM ci.entrar(vend);
  PERFORM pet_os_item_remover(it_prod);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'remover o produto devolve o estoque');
  PERFORM ci.exige((SELECT valor_pecas = 0 AND valor_total = 80 FROM os_ordens WHERE id = os), 'remover o item recalcula o total');
  PERFORM ci.entrar(vend);
  PERFORM pet_os_situacao(os, 'em_reparo');
  PERFORM pet_os_situacao(os, 'pronta');
  -- ordem com valor só sai pela cobrança no caixa (seção 95); aqui o valor é zerado por desconto
  PERFORM pet_os_salvar(jsonb_build_object('id', os, 'deposito_id', dep, 'desconto', 85.5));
  PERFORM pet_os_situacao(os, 'entregue');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'entregue' AND entregue_em IS NOT NULL FROM os_ordens WHERE id = os), 'entrega registra quando');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_situacao(%L, 'cancelada')$c$, os), 'cancelar OS entregue');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_item_adicionar(%L, '{"descricao":"x"}'::jsonb)$c$, os), 'incluir item em OS encerrada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_item_remover(%L)$c$, it_serv), 'remover item de OS encerrada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_salvar(jsonb_build_object('id', %L, 'queixa', 'x'))$c$, os), 'editar OS encerrada');

  -- cancelar devolve o estoque
  PERFORM ci.entrar(vend);
  os2 := pet_os_salvar(jsonb_build_object('pet_id', pet, 'deposito_id', dep));
  PERFORM pet_os_item_adicionar(os2, jsonb_build_object('produto_id', prod, 'quantidade', 3));
  PERFORM pet_os_situacao(os2, 'aprovada', dep);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 7 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'segunda OS baixa 3');
  PERFORM ci.entrar(vend);
  PERFORM pet_os_situacao(os2, 'cancelada');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'cancelar a OS devolve o estoque');

  -- leitura e proteção direta
  PERFORM ci.exige(ci.contar(vend, format('SELECT count(*) FROM os_ordens WHERE pet_id = %L', pet)) = 2, 'vendedor lê as OS do pet');
  PERFORM ci.exige(ci.contar(ub, format('SELECT count(*) FROM os_ordens WHERE pet_id = %L', pet)) = 0, 'outra empresa não lê as OS do pet');
  PERFORM ci.entrar(vend);
  UPDATE os_ordens SET pet_id = NULL, pet_resumo = NULL WHERE id = os2;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT pet_id = pet AND pet_resumo IS NOT NULL FROM os_ordens WHERE id = os2), 'o cliente não desfaz o vínculo com o animal pela tabela');
  PERFORM ci.entrar(adm);
  INSERT INTO os_ordens (tenant_id, equipamento, pet_id) VALUES (demo, 'Furadeira direta', pet);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM os_ordens WHERE equipamento = 'Furadeira direta' AND pet_id IS NOT NULL), 'o cliente não cria OS de pet pela tabela');

  DELETE FROM os_itens WHERE os_id IN (os, os2);
  DELETE FROM os_ordens WHERE tenant_id = demo AND (pet_id = pet OR equipamento = 'Furadeira direta');
  DELETE FROM pet_profissionais WHERE id = prof;
  DELETE FROM pets WHERE id = pet;
END $$;

-- 92. Clínica: internação (admissão, box, pesagem, relato, ocorrência, alta e óbito)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  ub   constant uuid := 'a0000000-0000-0000-0000-0000000001c1';
  vet  constant uuid := 'a0000000-0000-0000-0000-0000000001d1';
  aux  constant uuid := 'a0000000-0000-0000-0000-0000000001d2';
  ban  constant uuid := 'a0000000-0000-0000-0000-0000000001d3';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet uuid; pet2 uuid; pet3 uuid; pv uuid; pa uuid; pb uuid; b1 uuid; b2 uuid; b3 uuid; i1 uuid; i2 uuid; r jsonb; n bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO auth.users (id, email) VALUES (vet, 'vet-int@ci'), (aux, 'aux-int@ci'), (ban, 'ban-int@ci');
  UPDATE profiles SET tenant_id = demo WHERE id IN (vet, aux, ban);
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (vet, demo, 'veterinario'), (aux, demo, 'profissional'), (ban, demo, 'profissional');
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Tutor Internação CI') RETURNING id INTO tutor;
  INSERT INTO pets (tenant_id, cliente_id, nome, alergias) VALUES (demo, tutor, 'Paciente Int CI', 'dipirona') RETURNING id INTO pet;
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (demo, tutor, 'Paciente Int 2 CI') RETURNING id INTO pet2;
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (demo, tutor, 'Paciente Int 3 CI') RETURNING id INTO pet3;
  PERFORM ci.entrar(gest);
  pv := pet_profissional_salvar('{"nome":"Vet Int CI","funcao":"veterinario","crmv":"7777","crmv_uf":"PE"}'::jsonb);
  pa := pet_profissional_salvar('{"nome":"Aux Int CI","funcao":"auxiliar"}'::jsonb);
  pb := pet_profissional_salvar('{"nome":"Banhista Int CI","funcao":"banhista"}'::jsonb);
  PERFORM pet_profissional_vincular(pv, vet);
  PERFORM pet_profissional_vincular(pa, aux);
  PERFORM pet_profissional_vincular(pb, ban);
  b1 := pet_box_salvar('{"nome":"Box 1 CI"}'::jsonb);
  b2 := pet_box_salvar('{"nome":"Box 2 CI"}'::jsonb);
  b3 := pet_box_salvar('{"nome":"Box 3 CI","ativo":false}'::jsonb);
  PERFORM ci.sair();

  -- boxes
  PERFORM ci.deve_falhar(vend, $c$SELECT pet_box_salvar('{"nome":"X"}'::jsonb)$c$, 'vendedor cria box');
  PERFORM ci.deve_falhar(aux, $c$SELECT pet_box_salvar('{"nome":"X"}'::jsonb)$c$, 'auxiliar cria box');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_box_salvar('{"nome":" "}'::jsonb)$c$, 'box sem nome');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_box_salvar('{"nome":" box 1 ci "}'::jsonb)$c$, 'nome de box repetido');
  PERFORM ci.deve_falhar(ub, $c$SELECT pet_box_salvar('{"nome":"Outra empresa"}'::jsonb)$c$, 'empresa sem clínica liberada cria box');
  PERFORM ci.deve_falhar(gar, $c$SELECT clinica_boxes()$c$, 'garçom lista boxes');
  PERFORM ci.entrar(aux); SELECT jsonb_array_length(clinica_boxes()) INTO n; PERFORM ci.sair();
  PERFORM ci.exige(n = 3, 'auxiliar lista os boxes');

  -- admissão: só o veterinário com CRMV
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet, b1), 'gestor admite');
  PERFORM ci.deve_falhar(adm, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet, b1), 'administrador admite');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet, b1), 'auxiliar admite');
  PERFORM ci.deve_falhar(ban, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet, b1), 'banhista admite');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', ' '))$c$, pet, b1), 'admissão sem motivo');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet, b3), 'box desativado');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('motivo', 'x'))$c$, pet), 'admissão sem box');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x', 'peso_kg', 300))$c$, pet, b1), 'peso acima de 200 kg');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, gen_random_uuid(), b1), 'animal que não existe');
  PERFORM ci.entrar(vet);
  i1 := clinica_internacao_admitir(pet, jsonb_build_object('box_id', b1, 'motivo', 'Gastroenterite com desidratação', 'peso_kg', 8.4, 'observacoes', 'Dieta zero 12h'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'internado' AND crmv = '7777' AND crmv_uf = 'PE' AND box_id = b1 FROM pet_internacoes WHERE id = i1), 'admissão guarda box, veterinário e o CRMV da hora');
  PERFORM ci.exige((SELECT peso_kg = 8.4 AND internacao_id = i1 FROM pet_pesagens WHERE pet_id = pet), 'o peso da admissão entra no histórico de pesagens');
  PERFORM ci.exige((SELECT peso_kg = 8.4 FROM pets WHERE id = pet), 'o peso do cadastro acompanha');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet, b2), 'animal já internado');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet2, b1), 'box ocupado');

  -- nenhuma leitura direta das tabelas, nem para quem opera
  PERFORM ci.deve_falhar(vet, 'SELECT count(*) FROM pet_internacoes', 'veterinário lê as internações direto');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM pet_internacoes', 'administrador lê as internações direto');
  PERFORM ci.deve_falhar(gest, 'SELECT count(*) FROM pet_internacao_relatos', 'gestor lê os relatos direto');
  PERFORM ci.deve_falhar(aux, 'SELECT count(*) FROM pet_internacao_ocorrencias', 'auxiliar lê as ocorrências direto');
  PERFORM ci.deve_falhar(gest, 'SELECT count(*) FROM pet_boxes', 'gestor lê os boxes direto');
  PERFORM ci.deve_falhar(vet, format($c$INSERT INTO pet_internacao_relatos (internacao_id, veterinario_id, crmv, crmv_uf, texto) VALUES (%L, %L, '1', 'PE', 'x')$c$, i1, pv), 'gravar relato direto na tabela');

  -- mapa
  PERFORM ci.deve_falhar(gest, $c$SELECT clinica_internacoes()$c$, 'gestor lê o mapa');
  PERFORM ci.deve_falhar(ban, $c$SELECT clinica_internacoes()$c$, 'banhista lê o mapa');
  PERFORM ci.entrar(aux); r := clinica_internacoes(); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND r -> 0 -> 'box' ->> 'nome' = 'Box 1 CI' AND r -> 0 -> 'pet' ->> 'alergias' = 'dipirona' AND (r -> 0 ->> 'ultimo_peso')::numeric = 8.4
                   AND NOT (r -> 0 ? 'motivo'), 'auxiliar vê o mapa com box, alergia e peso, sem o motivo');

  -- pesagem e ocorrência: veterinário e auxiliar
  PERFORM ci.deve_falhar(ban, format($c$SELECT clinica_internacao_pesagem(%L, 8)$c$, i1), 'banhista pesa');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_pesagem(%L, 0)$c$, i1), 'pesagem zero');
  PERFORM ci.entrar(aux);
  PERFORM clinica_internacao_pesagem(i1, 8.1);
  PERFORM clinica_internacao_ocorrencia(i1, 'alimentacao', 'Aceitou ração úmida');
  PERFORM clinica_internacao_ocorrencia(i1, 'intercorrencia', 'Vomitou uma vez às 14h');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT peso_kg = 8.1 FROM pets WHERE id = pet), 'a pesagem da internação atualiza o peso do cadastro');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_ocorrencia(%L, 'transferencia', 'x')$c$, i1), 'ocorrência de transferência feita à mão');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_ocorrencia(%L, 'outro', ' ')$c$, i1), 'ocorrência vazia');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_ocorrencia(%L, 'festa', 'x')$c$, i1), 'tipo de ocorrência inválido');

  -- relato médico: só o veterinário
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_relato(%L, 'tentativa')$c$, i1), 'auxiliar escreve relato médico');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_internacao_relato(%L, 'tentativa')$c$, i1), 'gestor escreve relato médico');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_relato(%L, '  ')$c$, i1), 'relato vazio');
  PERFORM ci.entrar(vet);
  PERFORM clinica_internacao_relato(i1, 'Hidratação em curso, abdome menos doloroso.');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacao_relatos SET texto = 'outro' WHERE internacao_id = %L$c$, i1), 'alterar relato');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_internacao_ocorrencias WHERE internacao_id = %L$c$, i1), 'apagar ocorrência');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_internacoes WHERE id = %L$c$, i1), 'apagar internação');

  -- ficha: o auxiliar não lê o texto clínico
  PERFORM ci.entrar(vet); r := clinica_internacao_obter(i1); PERFORM ci.sair();
  PERFORM ci.exige(r -> 'internacao' ->> 'motivo' = 'Gastroenterite com desidratação' AND jsonb_array_length(r -> 'relatos') = 1
                   AND jsonb_array_length(r -> 'ocorrencias') = 2 AND jsonb_array_length(r -> 'pesagens') = 2 AND (r ->> 'sou_veterinario')::boolean, 'o veterinário vê a ficha completa');
  PERFORM ci.entrar(aux); r := clinica_internacao_obter(i1); PERFORM ci.sair();
  PERFORM ci.exige(r -> 'internacao' -> 'motivo' = 'null'::jsonb AND r -> 'relatos' = 'null'::jsonb AND jsonb_array_length(r -> 'ocorrencias') = 2
                   AND r -> 'pet' ->> 'alergias' = 'dipirona', 'o auxiliar vê alergia e ocorrências, sem motivo nem relatos');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_internacao_obter(%L)$c$, i1), 'gestor lê a ficha da internação');
  PERFORM ci.exige((SELECT count(*) >= 3 FROM clinica_acessos WHERE pet_id = pet AND acao = 'internacao'), 'abrir a ficha e admitir ficam na auditoria de acessos');

  -- troca de box
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_box_trocar(%L, %L)$c$, i1, b2), 'auxiliar troca o box');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_box_trocar(%L, %L)$c$, i1, b1), 'trocar para o mesmo box');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_box_trocar(%L, %L)$c$, i1, b3), 'trocar para box desativado');
  PERFORM ci.entrar(vet);
  i2 := clinica_internacao_admitir(pet2, jsonb_build_object('box_id', b2, 'motivo', 'Pós-operatório'));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_box_trocar(%L, %L)$c$, i1, b2), 'trocar para box ocupado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT pet_box_salvar(jsonb_build_object('id', %L, 'nome', 'Box 1 CI', 'ativo', false))$c$, b1), 'desativar box com animal');
  PERFORM ci.entrar(vet);
  PERFORM clinica_internacao_encerrar(i2, 'alta', 'Alta no mesmo dia');
  PERFORM clinica_internacao_box_trocar(i1, b2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT box_id = b2 FROM pet_internacoes WHERE id = i1), 'troca de box');
  PERFORM ci.exige((SELECT count(*) = 1 FROM pet_internacao_ocorrencias WHERE internacao_id = i1 AND tipo = 'transferencia' AND texto = 'Transferido do box Box 1 CI para o box Box 2 CI'), 'a troca fica registrada como ocorrência');

  -- alta e óbito
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_encerrar(%L, 'alta', 'x')$c$, i1), 'auxiliar dá alta');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_internacao_encerrar(%L, 'alta', 'x')$c$, i1), 'gestor dá alta');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_encerrar(%L, 'alta', ' ')$c$, i1), 'alta sem resumo');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_encerrar(%L, 'saiu', 'x')$c$, i1), 'tipo de encerramento inválido');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_encerrar(%L, 'alta', 'x', now() + interval '2 days')$c$, i1), 'alta no futuro');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_encerrar(%L, 'alta', 'x', now() - interval '5 days')$c$, i1), 'alta antes da admissão');
  PERFORM ci.entrar(vet);
  PERFORM clinica_internacao_encerrar(i1, 'obito', 'Parada cardiorrespiratória apesar das manobras.');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'obito' AND encerrado_em IS NOT NULL AND encerrado_por = pv FROM pet_internacoes WHERE id = i1), 'óbito encerra a internação');
  PERFORM ci.exige((SELECT NOT ativo AND obito_em IS NOT NULL FROM pets WHERE id = pet), 'óbito inativa o cadastro do animal e guarda a data');
  PERFORM ci.entrar(gest); r := clinica_boxes(); PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE (e ->> 'id')::uuid = b2 AND NOT (e ->> 'ocupado')::boolean), 'depois do óbito o box fica livre');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_relato(%L, 'tarde demais')$c$, i1), 'relato em internação encerrada');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_pesagem(%L, 8)$c$, i1), 'pesagem em internação encerrada');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_encerrar(%L, 'alta', 'x')$c$, i1), 'encerrar de novo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacoes SET observacoes = 'mexi' WHERE id = %L$c$, i1), 'alterar internação encerrada');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacoes SET motivo = 'outro' WHERE id = %L$c$, i2), 'alterar o motivo');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_admitir(%L, jsonb_build_object('box_id', %L, 'motivo', 'x'))$c$, pet, b1), 'internar animal falecido (inativo)');
  PERFORM ci.entrar(vet);
  PERFORM clinica_internacao_admitir(pet3, jsonb_build_object('box_id', b2, 'motivo', 'Reinternação no box liberado'));
  r := clinica_internacoes('todas', NULL);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 3, 'o histórico lista internadas e encerradas');
  PERFORM ci.entrar(vet); r := clinica_internacoes('obito', pet); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1, 'histórico filtrado por animal e situação');

  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 93. Clínica: internação, fase 2 (prescrição, mapa de execuções e itens)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  vet  constant uuid := 'a0000000-0000-0000-0000-0000000001d1';
  aux  constant uuid := 'a0000000-0000-0000-0000-0000000001d2';
  ban  constant uuid := 'a0000000-0000-0000-0000-0000000001d3';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  tutor uuid; pet uuid; b4 uuid; i1 uuid; dep uuid; prod uuid; serv uuid;
  p1 uuid; p2 uuid; p3 uuid; p4 uuid; e1 uuid; e2 uuid; it_prod uuid; it_serv uuid; it_livre uuid; r jsonb; n bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO clientes (tenant_id, nome) VALUES (demo, 'Tutor Prescrição CI') RETURNING id INTO tutor;
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (demo, tutor, 'Paciente Presc CI') RETURNING id INTO pet;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Dep Internação CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'INT-SORO', 'Soro Ringer Internação CI', 'un', 8, 20) RETURNING id INTO prod;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda, controla_estoque) VALUES (demo, 'INT-DIARIA', 'Diária de internação CI', 'un', 0, 120, false) RETURNING id INTO serv;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(prod, dep, 'entrada'::mov_tipo, 10, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  b4 := pet_box_salvar('{"nome":"Box 4 CI"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vet);
  i1 := clinica_internacao_admitir(pet, jsonb_build_object('box_id', b4, 'motivo', 'Pós-cirúrgico'));
  PERFORM ci.sair();

  -- prescrever: só o veterinário, com dados válidos
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"Dipirona","dose":"25 mg/kg"}'::jsonb)$c$, i1), 'auxiliar prescreve');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"Dipirona","dose":"25 mg/kg"}'::jsonb)$c$, i1), 'gestor prescreve');
  PERFORM ci.deve_falhar(ban, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"Dipirona","dose":"25 mg/kg"}'::jsonb)$c$, i1), 'banhista prescreve');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, '{"dose":"1 ml"}'::jsonb)$c$, i1), 'prescrição sem medicamento');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"X"}'::jsonb)$c$, i1), 'prescrição sem dose');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"X","dose":"1","frequencia_horas":8}'::jsonb)$c$, i1), 'frequência sem duração');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"X","dose":"1","frequencia_horas":8,"dias":20}'::jsonb)$c$, i1), 'duração de 20 dias');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"X","dose":"1","frequencia_horas":0,"dias":1}'::jsonb)$c$, i1), 'frequência zero');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, jsonb_build_object('medicamento','X','dose','1','inicio', now() - interval '10 days'))$c$, i1), 'início antes da admissão');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, jsonb_build_object('medicamento','X','dose','1','inicio', now() + interval '3 days'))$c$, i1), 'início a mais de 24 horas');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"X","dose":"1"}'::jsonb)$c$, gen_random_uuid()), 'internação que não existe');

  PERFORM ci.entrar(vet);
  p1 := clinica_internacao_prescrever(i1, '{"medicamento":"Dipirona","dose":"25 mg/kg","via":"IV","frequencia_horas":8,"dias":1,"observacao":"Diluir"}'::jsonb);
  p2 := clinica_internacao_prescrever(i1, '{"medicamento":"Ringer lactato","dose":"20 ml/kg/h"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 3 FROM pet_internacao_execucoes WHERE prescricao_id = p1 AND situacao = 'pendente'), 'a cada 8 horas durante 1 dia dá 3 doses');
  PERFORM ci.exige((SELECT max(previsto_em) - min(previsto_em) = interval '16 hours' FROM pet_internacao_execucoes WHERE prescricao_id = p1), 'as doses ficam 8 horas uma da outra');
  PERFORM ci.exige((SELECT count(*) = 1 FROM pet_internacao_execucoes WHERE prescricao_id = p2), 'sem frequência é dose única');
  PERFORM ci.exige((SELECT crmv = '7777' AND situacao = 'ativa' FROM pet_internacao_prescricoes WHERE id = p1), 'a prescrição guarda o CRMV de quem prescreveu');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacao_prescricoes SET dose = '1 g' WHERE id = %L$c$, p1), 'alterar a prescrição');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_internacao_prescricoes WHERE id = %L$c$, p1), 'apagar a prescrição');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_internacao_execucoes WHERE prescricao_id = %L$c$, p1), 'apagar doses');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacao_execucoes SET previsto_em = now() WHERE prescricao_id = %L$c$, p1), 'mudar o horário de uma dose');
  PERFORM ci.deve_falhar(vet, 'SELECT count(*) FROM pet_internacao_prescricoes', 'ler as prescrições direto');

  -- mapa
  PERFORM ci.deve_falhar(gest, $c$SELECT clinica_execucoes_mapa()$c$, 'gestor lê o mapa de execuções');
  PERFORM ci.deve_falhar(gar, $c$SELECT clinica_execucoes_mapa()$c$, 'garçom lê o mapa de execuções');
  PERFORM ci.deve_falhar(ban, $c$SELECT clinica_execucoes_mapa()$c$, 'banhista lê o mapa de execuções');
  PERFORM ci.deve_falhar(aux, $c$SELECT clinica_execucoes_mapa(0)$c$, 'mapa de 0 horas');
  PERFORM ci.deve_falhar(aux, $c$SELECT clinica_execucoes_mapa(100)$c$, 'mapa de 100 horas');
  PERFORM ci.entrar(aux); r := clinica_execucoes_mapa(24); PERFORM ci.sair();
  SELECT count(*) INTO n FROM jsonb_array_elements(r -> 'itens') e WHERE e -> 'pet' ->> 'nome' = 'Paciente Presc CI';
  PERFORM ci.exige(n = 4 AND r ? 'agora', 'o auxiliar vê as 4 doses do paciente no mapa');
  PERFORM ci.entrar(aux); r := clinica_execucoes_mapa(1); PERFORM ci.sair();
  SELECT count(*) INTO n FROM jsonb_array_elements(r -> 'itens') e WHERE e -> 'pet' ->> 'nome' = 'Paciente Presc CI';
  PERFORM ci.exige(n = 2, 'o mapa de 1 hora só traz as doses desta hora (as duas de agora)');

  -- execução
  SELECT id INTO e1 FROM pet_internacao_execucoes WHERE prescricao_id = p1 ORDER BY previsto_em LIMIT 1;
  SELECT id INTO e2 FROM pet_internacao_execucoes WHERE prescricao_id = p1 ORDER BY previsto_em OFFSET 1 LIMIT 1;
  PERFORM ci.deve_falhar(ban, format($c$SELECT clinica_execucao_registrar(%L, 'executada')$c$, e1), 'banhista executa dose');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_execucao_registrar(%L, 'executada')$c$, e1), 'gestor executa dose');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_execucao_registrar(%L, 'feita')$c$, e1), 'situação de dose inválida');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_execucao_registrar(%L, 'executada')$c$, e2), 'adiantar dose de 8 horas');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_execucao_registrar(%L, 'nao_executada')$c$, e2), 'dose não feita sem motivo');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_execucao_registrar(%L, 'executada')$c$, gen_random_uuid()), 'dose que não existe');
  PERFORM ci.entrar(aux);
  PERFORM clinica_execucao_registrar(e1, 'executada', 'Sem intercorrência');
  PERFORM clinica_execucao_registrar(e2, 'nao_executada', 'Animal em jejum para exame');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'executada' AND executado_por IS NOT NULL AND executado_em IS NOT NULL AND observacao = 'Sem intercorrência' FROM pet_internacao_execucoes WHERE id = e1), 'a execução guarda quem fez e quando');
  PERFORM ci.exige((SELECT situacao = 'nao_executada' FROM pet_internacao_execucoes WHERE id = e2), 'dose não feita guarda o motivo');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_execucao_registrar(%L, 'executada')$c$, e1), 'executar a mesma dose de novo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacao_execucoes SET situacao = 'pendente' WHERE id = %L$c$, e1), 'reabrir dose resolvida');
  PERFORM ci.entrar(aux); r := clinica_execucoes_mapa(1); PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'itens') e WHERE (e ->> 'id')::uuid = e1 AND e ->> 'situacao' = 'executada' AND e ->> 'executado_por' = 'Aux Int CI'),
                   'o mapa mostra a dose feita há pouco, com quem fez');

  -- suspensão
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_prescricao_suspender(%L, 'x')$c$, p1), 'auxiliar suspende prescrição');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_prescricao_suspender(%L, ' ')$c$, p1), 'suspender sem motivo');
  PERFORM ci.entrar(vet);
  PERFORM clinica_prescricao_suspender(p1, 'Trocar por tramadol');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'suspensa' AND suspensa_motivo = 'Trocar por tramadol' FROM pet_internacao_prescricoes WHERE id = p1), 'suspensão guarda o motivo');
  PERFORM ci.exige((SELECT count(*) = 1 FROM pet_internacao_execucoes WHERE prescricao_id = p1 AND situacao = 'cancelada')
                   AND (SELECT count(*) = 1 FROM pet_internacao_execucoes WHERE prescricao_id = p1 AND situacao = 'executada')
                   AND (SELECT count(*) = 1 FROM pet_internacao_execucoes WHERE prescricao_id = p1 AND situacao = 'nao_executada'), 'suspender cancela só as doses pendentes');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_prescricao_suspender(%L, 'de novo')$c$, p1), 'suspender duas vezes');

  -- itens
  PERFORM ci.deve_falhar(ban, $c$SELECT clinica_internacao_catalogo('soro')$c$, 'banhista consulta o catálogo');
  PERFORM ci.deve_falhar(aux, $c$SELECT clinica_internacao_catalogo('s')$c$, 'catálogo com 1 letra');
  PERFORM ci.entrar(aux); r := clinica_internacao_catalogo('soro ringer'); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND (r -> 0 ->> 'preco_venda')::numeric = 20 AND (r -> 0 ->> 'controla_estoque')::boolean, 'o auxiliar acha o produto no catálogo');
  PERFORM ci.deve_falhar(ban, format($c$SELECT clinica_internacao_item_lancar(%L, '{"descricao":"x"}'::jsonb)$c$, i1), 'banhista lança item');
  PERFORM ci.deve_falhar(gest, format($c$SELECT clinica_internacao_item_lancar(%L, '{"descricao":"x"}'::jsonb)$c$, i1), 'gestor lança item');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_item_lancar(%L, '{}'::jsonb)$c$, i1), 'item sem produto nem descrição');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_item_lancar(%L, '{"descricao":"x","quantidade":0}'::jsonb)$c$, i1), 'item com quantidade zero');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_item_lancar(%L, '{"descricao":"x","preco":-1}'::jsonb)$c$, i1), 'item com preço negativo');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_item_lancar(%L, jsonb_build_object('produto_id', %L))$c$, i1, gen_random_uuid()), 'produto que não existe');
  PERFORM ci.entrar(aux);
  it_prod := clinica_internacao_item_lancar(i1, jsonb_build_object('produto_id', prod, 'quantidade', 2, 'deposito_id', dep));
  it_serv := clinica_internacao_item_lancar(i1, jsonb_build_object('produto_id', serv));
  it_livre := clinica_internacao_item_lancar(i1, '{"descricao":"Curativo","quantidade":2,"preco":15.5}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 8 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'lançar produto baixa o estoque (10 - 2)');
  PERFORM ci.exige((SELECT tipo = 'produto' AND total = 40 AND baixa_quantidade = 2 FROM pet_internacao_itens WHERE id = it_prod), 'produto com estoque: tipo, total e baixa guardados');
  PERFORM ci.exige((SELECT tipo = 'servico' AND total = 120 AND baixa_deposito_id IS NULL FROM pet_internacao_itens WHERE id = it_serv), 'serviço não baixa estoque');
  PERFORM ci.exige((SELECT tipo = 'servico' AND total = 31 FROM pet_internacao_itens WHERE id = it_livre), 'item livre vira serviço');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM estoques WHERE produto_id = serv), 'serviço não cria estoque');
  PERFORM ci.entrar(aux); r := clinica_internacao_obter(i1); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'itens') = 3 AND (r ->> 'total_itens')::numeric = 191 AND jsonb_array_length(r -> 'prescricoes') = 2
                   AND r -> 'relatos' = 'null'::jsonb, 'a ficha traz itens, total e prescrições, sem os relatos para o auxiliar');
  PERFORM ci.exige(jsonb_array_length((SELECT p -> 'execucoes' FROM jsonb_array_elements(r -> 'prescricoes') p WHERE p ->> 'medicamento' = 'Dipirona')) = 3, 'a prescrição vem com as suas doses');

  -- cancelar item: só o veterinário, com motivo, e devolve o estoque
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_item_cancelar(%L, 'x')$c$, it_prod), 'auxiliar cancela item');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_item_cancelar(%L, ' ')$c$, it_prod), 'cancelar item sem motivo');
  PERFORM ci.entrar(vet);
  PERFORM clinica_internacao_item_cancelar(it_prod, 'Lançado no animal errado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 10 FROM estoques WHERE produto_id = prod AND deposito_id = dep), 'cancelar o item devolve o estoque');
  PERFORM ci.exige((SELECT cancelado_em IS NOT NULL AND baixa_deposito_id IS NULL AND cancelado_motivo = 'Lançado no animal errado' FROM pet_internacao_itens WHERE id = it_prod), 'o item cancelado fica registrado com o motivo');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_item_cancelar(%L, 'de novo')$c$, it_prod), 'cancelar item duas vezes');
  PERFORM ci.entrar(vet); r := clinica_internacao_obter(i1); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total_itens')::numeric = 151, 'o total não conta o item cancelado');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM pet_internacao_itens WHERE id = %L$c$, it_serv), 'apagar item');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacao_itens SET quantidade = 9 WHERE id = %L$c$, it_serv), 'mudar a quantidade do item');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacao_itens SET descricao = 'x' WHERE id = %L$c$, it_prod), 'mexer em item cancelado');

  -- duração que não é múltiplo da frequência: toda dose que cabe na duração entra (5 h por 1 dia = 0, 5, 10, 15 e 20 h)
  PERFORM ci.entrar(vet);
  p3 := clinica_internacao_prescrever(i1, '{"medicamento":"Omeprazol","dose":"1 mg/kg","frequencia_horas":5,"dias":1}'::jsonb);
  p4 := clinica_internacao_prescrever(i1, '{"medicamento":"Tramadol","dose":"2 mg/kg","frequencia_horas":7,"dias":1}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 5 AND max(previsto_em) - min(previsto_em) = interval '20 hours' FROM pet_internacao_execucoes WHERE prescricao_id = p3), 'a cada 5 h por 1 dia dá 5 doses, a última na hora 20');
  PERFORM ci.exige((SELECT count(*) = 4 AND max(previsto_em) - min(previsto_em) = interval '21 hours' FROM pet_internacao_execucoes WHERE prescricao_id = p4), 'a cada 7 h por 1 dia dá 4 doses, a última na hora 21');

  -- alta: as doses que faltam são canceladas e nada mais entra
  PERFORM ci.entrar(vet);
  PERFORM clinica_internacao_encerrar(i1, 'alta', 'Alta com medicação oral');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 0 FROM pet_internacao_execucoes WHERE internacao_id = i1 AND situacao = 'pendente'), 'a alta cancela as doses pendentes');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_prescrever(%L, '{"medicamento":"X","dose":"1"}'::jsonb)$c$, i1), 'prescrever em internação encerrada');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_item_lancar(%L, '{"descricao":"x"}'::jsonb)$c$, i1), 'lançar item em internação encerrada');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_item_cancelar(%L, 'tarde')$c$, it_serv), 'cancelar item de internação encerrada');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_prescricao_suspender(%L, 'tarde')$c$, p2), 'suspender prescrição de internação encerrada');
  PERFORM ci.entrar(aux); r := clinica_execucoes_mapa(72); PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'itens') e WHERE e -> 'pet' ->> 'nome' = 'Paciente Presc CI'), 'o mapa não traz internação encerrada');
  PERFORM ci.entrar(vet); r := clinica_internacao_obter(i1); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'prescricoes') = 4 AND jsonb_array_length(r -> 'itens') = 3, 'o histórico continua completo depois da alta');

  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 94. SNGPC: medicamentos controlados, livro, período, inventário e envios
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  vet  constant uuid := 'a0000000-0000-0000-0000-0000000001d1';
  aux  constant uuid := 'a0000000-0000-0000-0000-0000000001d2';
  ub   constant uuid := 'a0000000-0000-0000-0000-0000000001c1';
  hoje constant date := current_date;
  ramo_ant text; cnae_ant text; cnae2_ant text; cnpj_ant text;
  p1 uuid; p2 uuid; p3 uuid; m1 uuid; m2 uuid; farma uuid; farma_off uuid;
  d_saldo uuid; d_ent uuid; d_venda uuid; d_perda uuid; env1 uuid; env2 uuid; r jsonb; n bigint; x text;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios, cnpj INTO ramo_ant, cnae_ant, cnae2_ant, cnpj_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica', cnpj = '11222333000181' WHERE tenant_id = demo;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'SNG-DIAZ', 'Diazepam 10 mg SNGPC CI', 'un', 5, 12) RETURNING id INTO p1;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'SNG-CETA', 'Cetamina 50 mg/ml SNGPC CI', 'un', 30, 60) RETURNING id INTO p2;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, custo, preco_venda) VALUES (demo, 'SNG-OUTRO', 'Outro SNGPC CI', 'un', 1, 2) RETURNING id INTO p3;

  -- CPF do farmacêutico
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Farma sem CPF","funcao":"farmaceutico","crf":"1234","crf_uf":"PE"}'::jsonb)$c$, 'farmacêutico sem CPF');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Farma CPF ruim","funcao":"farmaceutico","crf":"1234","crf_uf":"PE","cpf":"11111111111"}'::jsonb)$c$, 'farmacêutico com CPF inválido');
  PERFORM ci.deve_falhar(gest, $c$SELECT pet_profissional_salvar('{"nome":"Farma CPF ruim","funcao":"farmaceutico","crf":"1234","crf_uf":"PE","cpf":"52998224726"}'::jsonb)$c$, 'farmacêutico com dígito do CPF errado');
  PERFORM ci.entrar(gest);
  farma := pet_profissional_salvar('{"nome":"Farma SNGPC CI","funcao":"farmaceutico","crf":"4321","crf_uf":"PE","cpf":"529.982.247-25"}'::jsonb);
  farma_off := pet_profissional_salvar('{"nome":"Farma Inativa CI","funcao":"farmaceutico","crf":"4322","crf_uf":"PE","cpf":"52998224725","ativo":false}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cpf = '52998224725' FROM pet_profissionais WHERE id = farma), 'o CPF do farmacêutico é guardado só com números');
  PERFORM ci.entrar(gest);
  PERFORM pet_profissional_salvar(jsonb_build_object('id', farma_off, 'nome', 'Farma Inativa CI', 'funcao', 'banhista'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cpf IS NULL FROM pet_profissionais WHERE id = farma_off), 'mudar a função limpa o CPF');

  -- quem opera
  PERFORM ci.deve_falhar(vend, $c$SELECT sngpc_saldo()$c$, 'vendedor lê o saldo do SNGPC');
  PERFORM ci.deve_falhar(aux, $c$SELECT sngpc_livro()$c$, 'auxiliar lê o livro do SNGPC');
  PERFORM ci.deve_falhar(gar, $c$SELECT sngpc_medicamentos()$c$, 'garçom lê os medicamentos controlados');
  PERFORM ci.deve_falhar(NULL, $c$SELECT sngpc_envios()$c$, 'anon lê os envios');
  PERFORM ci.deve_falhar(ub, $c$SELECT sngpc_medicamentos()$c$, 'empresa sem clínica liberada usa o SNGPC');
  PERFORM ci.deve_falhar(vet, 'SELECT count(*) FROM sngpc_documentos', 'ler o livro direto na tabela');
  PERFORM ci.deve_falhar(adm, 'SELECT count(*) FROM sngpc_envios', 'ler os envios direto na tabela');

  -- cadastro do medicamento controlado
  PERFORM ci.deve_falhar(vend, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('produto_id', %L, 'registro_ms', '1234567890123', 'lista', 'B1', 'unidade_medida', 1))$c$, p1), 'vendedor cadastra controlado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('produto_id', %L, 'registro_ms', '123456789012', 'lista', 'B1', 'unidade_medida', 1))$c$, p1), 'registro com 12 números');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('produto_id', %L, 'registro_ms', '1234567890123', 'lista', 'Z9', 'unidade_medida', 1))$c$, p1), 'lista inválida');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('produto_id', %L, 'registro_ms', '1234567890123', 'lista', 'B1', 'unidade_medida', 3))$c$, p1), 'unidade inválida');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('produto_id', %L, 'registro_ms', '1234567890123', 'lista', 'B1', 'unidade_medida', 1))$c$, gen_random_uuid()), 'produto que não existe');
  PERFORM ci.entrar(gest);
  m1 := sngpc_medicamento_salvar(jsonb_build_object('produto_id', p1, 'registro_ms', '1.234.567.890.123', 'lista', 'b1', 'unidade_medida', 1));
  PERFORM ci.sair();
  PERFORM ci.entrar(vet);
  m2 := sngpc_medicamento_salvar(jsonb_build_object('produto_id', p2, 'registro_ms', '9876543210987', 'lista', 'A1', 'unidade_medida', 2));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT registro_ms = '1234567890123' AND lista = 'B1' FROM sngpc_medicamentos WHERE id = m1), 'registro só com números e lista em maiúsculas');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('produto_id', %L, 'registro_ms', '1234567890123', 'lista', 'B1', 'unidade_medida', 1))$c$, p1), 'o mesmo produto de novo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('produto_id', %L, 'registro_ms', '1234567890123', 'lista', 'B1', 'unidade_medida', 1))$c$, p3), 'o mesmo registro em outro produto');

  -- saldo inicial, entrada, dispensação e perda
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('saldo_inicial', jsonb_build_object('data', current_date, 'itens', '[]'::jsonb))$c$), 'lançamento sem itens');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('compra', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'A1', 'quantidade', 1))))$c$, m1), 'tipo de lançamento inválido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('saldo_inicial', jsonb_build_object('data', current_date + 3, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'A1', 'quantidade', 1))))$c$, m1), 'lançamento no futuro');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('saldo_inicial', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'A1', 'quantidade', 0))))$c$, m1), 'quantidade zero');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('saldo_inicial', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'A1', 'quantidade', 1000))))$c$, m1), 'quantidade acima de 999');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('saldo_inicial', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', '  ', 'quantidade', 1))))$c$, m1), 'lote vazio');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('saldo_inicial', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'A1', 'quantidade', 1))))$c$, gen_random_uuid()), 'medicamento controlado que não existe');
  PERFORM ci.deve_falhar(vend, format($c$SELECT sngpc_registrar('saldo_inicial', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'A1', 'quantidade', 1))))$c$, m1), 'vendedor lança no livro');

  PERFORM ci.entrar(gest);
  d_saldo := sngpc_registrar('saldo_inicial', jsonb_build_object('data', hoje - 6, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', m1, 'lote', ' l1 ', 'quantidade', 10, 'validade', hoje + 200))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT lote = 'L1' FROM sngpc_itens WHERE documento_id = d_saldo), 'o lote é guardado sem espaços e em maiúsculas');

  -- entrada: nota fiscal de compra completa
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('entrada', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 5))))$c$, m1), 'entrada sem nota fiscal');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('entrada', jsonb_build_object('data', current_date, 'nf_numero', 55, 'nf_data', current_date, 'cnpj_origem', '123', 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 5))))$c$, m1), 'entrada com CNPJ de origem curto');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('entrada', jsonb_build_object('data', current_date - 4, 'nf_numero', 55, 'nf_data', current_date, 'cnpj_origem', '12345678000195', 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 5))))$c$, m1), 'nota fiscal posterior ao recebimento');
  PERFORM ci.entrar(vet);
  d_ent := sngpc_registrar('entrada', jsonb_build_object('data', hoje - 3, 'nf_numero', 123, 'nf_data', hoje - 4, 'cnpj_origem', '12.345.678/0001-95',
             'itens', jsonb_build_array(jsonb_build_object('medicamento_id', m1, 'lote', 'L2', 'quantidade', 20, 'validade', hoje + 300),
                                        jsonb_build_object('medicamento_id', m2, 'lote', 'K1', 'quantidade', 8, 'validade', hoje + 100))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cnpj_origem = '12345678000195' AND nf_numero = 123 FROM sngpc_documentos WHERE id = d_ent), 'a entrada guarda a nota fiscal e o CNPJ só com números');

  -- dispensação (venda): receita, prescritor CRMV, comprador e animal
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('venda', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'dispensação sem receita');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('venda', jsonb_build_object(
      'data', current_date, 'tipo_receituario', 5, 'numero_notificacao', '12345', 'data_prescricao', current_date, 'prescritor_nome', 'Dr. A', 'prescritor_registro', '1234',
      'prescritor_uf', 'PE', 'comprador_nome', 'Tutor', 'comprador_tipo_documento', 1, 'comprador_documento', '1234567', 'comprador_orgao', 'SSP', 'comprador_uf', 'PE',
      'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'receituário de antimicrobiano (tipo 5)');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('venda', jsonb_build_object(
      'data', current_date, 'tipo_receituario', 2, 'numero_notificacao', '12345', 'data_prescricao', current_date, 'prescritor_nome', 'Dr. A', 'prescritor_registro', '1234',
      'prescritor_uf', 'XX', 'comprador_nome', 'Tutor', 'comprador_tipo_documento', 1, 'comprador_documento', '1234567', 'comprador_orgao', 'SSP', 'comprador_uf', 'PE',
      'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'prescritor com UF inválida');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('venda', jsonb_build_object(
      'data', current_date, 'tipo_receituario', 2, 'numero_notificacao', '12345', 'data_prescricao', current_date, 'prescritor_nome', 'Dr. A', 'prescritor_registro', '1234',
      'prescritor_uf', 'PE', 'comprador_nome', 'Tutor', 'comprador_tipo_documento', 2, 'comprador_documento', '1234567', 'comprador_orgao', 'SSP', 'comprador_uf', 'PE',
      'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'tipo de documento do comprador fora do que o guia confirma');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('venda', jsonb_build_object(
      'data', current_date, 'tipo_receituario', 2, 'data_prescricao', current_date, 'prescritor_nome', 'Dr. A', 'prescritor_registro', '1234',
      'prescritor_uf', 'PE', 'comprador_nome', 'Tutor', 'comprador_tipo_documento', 1, 'comprador_documento', '1234567', 'comprador_orgao', 'SSP', 'comprador_uf', 'PE',
      'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'receita sem número de notificação');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('venda', jsonb_build_object(
      'data', current_date - 1, 'tipo_receituario', 2, 'numero_notificacao', '12345', 'data_prescricao', current_date, 'prescritor_nome', 'Dr. A', 'prescritor_registro', '1234',
      'prescritor_uf', 'PE', 'comprador_nome', 'Tutor', 'comprador_tipo_documento', 1, 'comprador_documento', '1234567', 'comprador_orgao', 'SSP', 'comprador_uf', 'PE',
      'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'receita datada depois da dispensação');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('venda', jsonb_build_object(
      'data', current_date, 'tipo_receituario', 2, 'numero_notificacao', '12345', 'data_prescricao', current_date, 'prescritor_nome', 'Dr. A', 'prescritor_registro', '1234',
      'prescritor_uf', 'PE', 'comprador_nome', 'Tutor', 'comprador_tipo_documento', 1, 'comprador_documento', '1234567', 'comprador_orgao', 'SSP', 'comprador_uf', 'PE',
      'paciente_nome', 'Rex', 'paciente_idade', 3, 'paciente_unidade_idade', 1,
      'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'animal sem sexo');

  PERFORM ci.entrar(gest);
  d_venda := sngpc_registrar('venda', jsonb_build_object(
      'data', hoje - 1, 'tipo_receituario', 2, 'numero_notificacao', '0012345', 'data_prescricao', hoje - 2, 'prescritor_nome', 'Dra. Vet Silva', 'prescritor_registro', '12.345',
      'prescritor_uf', 'pe', 'comprador_nome', 'Maria Tutora', 'comprador_tipo_documento', 1, 'comprador_documento', '1234567', 'comprador_orgao', 'SSP', 'comprador_uf', 'PE',
      'paciente_nome', 'Rex', 'paciente_idade', 3, 'paciente_unidade_idade', 1, 'paciente_sexo', 1,
      'itens', jsonb_build_array(jsonb_build_object('medicamento_id', m1, 'lote', 'L1', 'quantidade', 4))));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT prescritor_registro = '12345' AND prescritor_uf = 'PE' AND numero_notificacao = '0012345' FROM sngpc_documentos WHERE id = d_venda), 'a dispensação guarda o prescritor (registro só com números, UF em maiúsculas)');

  -- perda
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 1))))$c$, m1), 'perda sem motivo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date, 'motivo_perda', 10, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 1))))$c$, m1), 'motivo de perda inexistente');
  PERFORM ci.entrar(gest);
  d_perda := sngpc_registrar('perda', jsonb_build_object('data', hoje - 1, 'motivo_perda', 2, 'observacao', 'Frasco quebrado', 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', m1, 'lote', 'L2', 'quantidade', 1))));
  r := sngpc_saldo();
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT (e ->> 'saldo')::integer FROM jsonb_array_elements(r) e WHERE e ->> 'lote' = 'L1' AND e ->> 'registro_ms' = '1234567890123') = 6, 'saldo do lote L1: 10 - 4');
  PERFORM ci.exige((SELECT (e ->> 'saldo')::integer FROM jsonb_array_elements(r) e WHERE e ->> 'lote' = 'L2') = 19, 'saldo do lote L2: 20 - 1');
  PERFORM ci.exige((SELECT (e ->> 'saldo')::integer FROM jsonb_array_elements(r) e WHERE e ->> 'lote' = 'K1') = 8, 'saldo do lote da cetamina');
  PERFORM ci.exige(jsonb_array_length(r) = 3, 'só os lotes com saldo aparecem');

  -- o saldo nunca fica negativo
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date, 'motivo_perda', 3, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 7))))$c$, m1), 'perda maior que o saldo do lote');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date, 'motivo_perda', 3, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'NAOEXISTE', 'quantidade', 1))))$c$, m1), 'perda de lote que não existe');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date - 5, 'motivo_perda', 3, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 1))))$c$, m1), 'perda de lote antes da entrada dele');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date, 'motivo_perda', 3, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 4), jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 4))))$c$, m1, m1), 'duas linhas do mesmo lote que passam do saldo juntas');
  PERFORM ci.exige((SELECT count(*) = 4 FROM sngpc_documentos WHERE tenant_id = demo AND cancelado_em IS NULL), 'lançamento recusado não deixa rastro (continuam 4)');

  -- cancelar
  PERFORM ci.deve_falhar(aux, format($c$SELECT sngpc_cancelar(%L, 'x')$c$, d_perda), 'auxiliar cancela lançamento');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_cancelar(%L, ' ')$c$, d_perda), 'cancelar sem motivo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_cancelar(%L, 'x')$c$, gen_random_uuid()), 'cancelar lançamento que não existe');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_cancelar(%L, 'Lançado errado')$c$, d_saldo), 'cancelar o saldo inicial que a dispensação já usou');
  PERFORM ci.entrar(gest);
  PERFORM sngpc_cancelar(d_perda, 'Lançada em duplicidade');
  r := sngpc_saldo();
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT (e ->> 'saldo')::integer FROM jsonb_array_elements(r) e WHERE e ->> 'lote' = 'L2') = 20, 'cancelar a perda devolve o saldo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_cancelar(%L, 'de novo')$c$, d_perda), 'cancelar duas vezes');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM sngpc_documentos WHERE id = %L$c$, d_venda), 'apagar lançamento');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE sngpc_documentos SET numero_notificacao = '999' WHERE id = %L$c$, d_venda), 'alterar lançamento');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE sngpc_itens SET quantidade = 9 WHERE documento_id = %L$c$, d_venda), 'alterar item');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM sngpc_itens WHERE documento_id = %L$c$, d_venda), 'apagar item');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE sngpc_documentos SET cancelado_motivo = 'mexi' WHERE id = %L$c$, d_perda), 'alterar lançamento cancelado');

  -- medicamento com movimento não muda o registro nem a unidade
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('id', %L, 'registro_ms', '1111111111111', 'lista', 'B1', 'unidade_medida', 1))$c$, m1), 'mudar o registro com movimento');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_medicamento_salvar(jsonb_build_object('id', %L, 'registro_ms', '1234567890123', 'lista', 'B1', 'unidade_medida', 2))$c$, m1), 'mudar a unidade com movimento');

  -- livro
  PERFORM ci.entrar(vet); r := sngpc_livro(); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'documentos') = 4 AND r -> 'fechado_ate' = 'null'::jsonb, 'o livro traz os 4 lançamentos (um cancelado) e nenhum período fechado');
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'documentos') d WHERE d ->> 'id' = d_perda::text AND d ->> 'cancelado_motivo' = 'Lançada em duplicidade'), 'o cancelado aparece marcado, com o motivo');

  -- período e inventário (dados para o XML)
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_periodo(current_date, current_date - 1)$c$), 'período invertido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_periodo(current_date - 40, current_date)$c$), 'período de 41 dias');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_periodo(current_date, current_date + 2)$c$), 'período no futuro');
  PERFORM ci.deve_falhar(aux, format($c$SELECT sngpc_periodo(current_date - 3, current_date)$c$), 'auxiliar gera o período');
  PERFORM ci.entrar(gest); r := sngpc_periodo(hoje - 6, hoje); PERFORM ci.sair();
  PERFORM ci.exige(r ->> 'cnpj' = '11222333000181' AND jsonb_array_length(r -> 'documentos') = 2, 'o período traz entrada e dispensação (sem saldo inicial nem cancelados)');
  PERFORM ci.exige((r -> 'documentos' -> 0 ->> 'tipo') = 'entrada' AND jsonb_array_length(r -> 'documentos' -> 0 -> 'itens') = 2, 'a entrada vem primeiro, com os 2 itens');
  PERFORM ci.exige((r -> 'documentos' -> 1 -> 'itens' -> 0 ->> 'registro_ms') = '1234567890123' AND (r -> 'documentos' -> 1 -> 'itens' -> 0 ->> 'quantidade') = '4', 'o item traz o registro na Anvisa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_inventario(current_date - 10)$c$), 'inventário de 10 dias atrás');
  PERFORM ci.entrar(gest); r := sngpc_inventario(hoje); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'itens') = 3, 'o inventário lista os 3 lotes com saldo');
  PERFORM ci.entrar(gest); r := sngpc_inventario(hoje - 5); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'itens') = 1 AND (r -> 'itens' -> 0 ->> 'quantidade') = '10', 'o inventário de 5 dias atrás só tem o saldo inicial');
  UPDATE empresas SET cnpj = NULL WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_periodo(current_date - 3, current_date)$c$), 'gerar sem CNPJ da empresa');
  UPDATE empresas SET cnpj = '11222333000181' WHERE tenant_id = demo;

  -- responsáveis
  PERFORM ci.entrar(gest); r := sngpc_responsaveis(); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) >= 1 AND EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE (e ->> 'id')::uuid = farma AND e ->> 'cpf' = '52998224725')
                   AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE (e ->> 'id')::uuid = farma_off), 'só farmacêutico ativo com CPF válido responde pelo envio');

  -- envios
  x := '<?xml version="1.0" encoding="iso-8859-1" ?><mensagemSNGPC xmlns="urn:sngpc-schema"><cabecalho/></mensagemSNGPC>';
  PERFORM ci.deve_falhar(aux, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 6, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'auxiliar registra envio');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 6, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', %L))$c$, farma_off, x), 'envio com farmacêutico inativo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 6, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', 'texto qualquer'))$c$, farma), 'envio que não é XML');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 1, 'fim', current_date - 6, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'envio com período invertido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 60, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'envio com período de 60 dias');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'remessa', 'inicio', current_date - 6, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'tipo de envio inválido');
  -- o arquivo só vale para o livro como estava na montagem: assinatura errada, ou livro que mudou depois, recusa
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 6, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', %L, 'assinatura', 'errada'))$c$, farma, x), 'envio com assinatura errada');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 6, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'envio sem assinatura');
  PERFORM ci.entrar(gest);
  r := sngpc_periodo(hoje - 6, hoje - 1);
  PERFORM sngpc_registrar('perda', jsonb_build_object('data', hoje - 1, 'motivo_perda', 2, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', m1, 'lote', 'L1', 'quantidade', 1))));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 6, 'fim', current_date - 1, 'farmaceutico_id', %L, 'xml', %L, 'assinatura', %L))$c$, farma, x, r ->> 'assinatura'), 'arquivo montado antes de um lançamento novo no período');
  PERFORM ci.entrar(gest);
  r := sngpc_periodo(hoje - 6, hoje - 1);
  env1 := sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', hoje - 6, 'fim', hoje - 1, 'farmaceutico_id', farma, 'xml', x, 'assinatura', r ->> 'assinatura'));
  PERFORM ci.sair();
  -- enquanto há arquivo gerado, o livro das datas dele não muda
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date - 2, 'motivo_perda', 2, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L1', 'quantidade', 1))))$c$, m1), 'lançar em período com arquivo gerado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_cancelar(%L, 'Receita errada')$c$, d_venda), 'cancelar lançamento de período com arquivo gerado');
  PERFORM ci.entrar(vet); r := sngpc_livro(); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'periodos_travados') = 1 AND (r -> 'periodos_travados' -> 0 ->> 'situacao') = 'gerado', 'o livro mostra o período travado pelo arquivo gerado');
  PERFORM ci.exige((SELECT length(sha256) = 64 AND situacao = 'gerado' AND gerado_por_nome <> '' FROM sngpc_envios WHERE id = env1), 'o envio guarda o hash do arquivo e quem gerou');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', current_date - 3, 'fim', current_date, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'envio que se sobrepõe a outro gerado');
  PERFORM ci.entrar(vet); r := sngpc_envios(); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r) = 1 AND NOT (r -> 0 ? 'xml'), 'a lista de envios não carrega o arquivo');
  PERFORM ci.entrar(vet); x := sngpc_envio_xml(env1); PERFORM ci.sair();
  PERFORM ci.exige(x LIKE '<?xml version="1.0" encoding="iso-8859-1" ?><mensagemSNGPC%', 'o arquivo gerado pode ser baixado de novo, igual ao que foi guardado');
  PERFORM ci.deve_falhar(aux, format($c$SELECT sngpc_envio_xml(%L)$c$, env1), 'auxiliar baixa o arquivo');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE sngpc_envios SET xml = '<?xml outro ?>............................................' WHERE id = %L$c$, env1), 'trocar o arquivo gerado');
  PERFORM ci.deve_falhar_dono(format($c$DELETE FROM sngpc_envios WHERE id = %L$c$, env1), 'apagar o envio');

  -- transmitir: sem o protocolo não vale, e fecha o período
  PERFORM ci.deve_falhar(aux, format($c$SELECT sngpc_envio_transmitir(%L, 'ABC123')$c$, env1), 'auxiliar marca como transmitido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_transmitir(%L, ' ')$c$, env1), 'transmitir sem protocolo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_transmitir(%L, 'ABC123')$c$, gen_random_uuid()), 'transmitir envio que não existe');
  PERFORM ci.entrar(gest);
  PERFORM sngpc_envio_transmitir(env1, 'SNGPC-2026-0001');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'transmitido' AND protocolo = 'SNGPC-2026-0001' AND transmitido_em IS NOT NULL FROM sngpc_envios WHERE id = env1), 'transmitido guarda o protocolo e quando');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_transmitir(%L, 'OUTRO')$c$, env1), 'transmitir duas vezes');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_cancelar(%L, 'engano')$c$, env1), 'cancelar envio já transmitido');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE sngpc_envios SET protocolo = 'X' WHERE id = %L$c$, env1), 'alterar envio transmitido');
  PERFORM ci.entrar(vet); r := sngpc_livro(); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'fechado_ate')::date = hoje - 1, 'o livro mostra até onde o período está fechado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date - 1, 'motivo_perda', 2, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 1))))$c$, m1), 'lançar em período já transmitido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_cancelar(%L, 'Receita errada')$c$, d_venda), 'cancelar lançamento de período já transmitido');
  PERFORM ci.entrar(gest);
  d_perda := sngpc_registrar('perda', jsonb_build_object('data', hoje, 'motivo_perda', 3, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', m1, 'lote', 'L2', 'quantidade', 2))));
  PERFORM ci.sair();
  PERFORM ci.exige(d_perda IS NOT NULL, 'depois do período fechado, lançar com data nova continua valendo');

  -- novo período: o seguinte ao transmitido; cancelar o gerado libera o período
  PERFORM ci.entrar(gest);
  r := sngpc_periodo(hoje, hoje);
  env2 := sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', hoje, 'fim', hoje, 'farmaceutico_id', farma, 'xml', x, 'assinatura', r ->> 'assinatura'));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_registrar('perda', jsonb_build_object('data', current_date, 'motivo_perda', 2, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', %L, 'lote', 'L2', 'quantidade', 1))))$c$, m1), 'lançar no dia de um arquivo gerado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_cancelar(%L, ' ')$c$, env2), 'cancelar envio sem motivo');
  PERFORM ci.entrar(gest);
  PERFORM sngpc_envio_cancelar(env2, 'Faltou lançar uma nota');
  -- cancelado o arquivo gerado, o livro da data volta a aceitar lançamento; o arquivo novo precisa da assinatura nova
  PERFORM sngpc_registrar('perda', jsonb_build_object('data', hoje, 'motivo_perda', 2, 'itens', jsonb_build_array(jsonb_build_object('medicamento_id', m1, 'lote', 'L2', 'quantidade', 1))));
  r := sngpc_periodo(hoje, hoje);
  env2 := sngpc_envio_registrar(jsonb_build_object('tipo', 'movimentacao', 'inicio', hoje, 'fim', hoje, 'farmaceutico_id', farma, 'xml', x, 'assinatura', r ->> 'assinatura'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 3 FROM sngpc_envios WHERE tenant_id = demo), 'cancelar o gerado libera o período para um arquivo novo');

  -- inventário: uma data por vez
  PERFORM ci.entrar(gest);
  r := sngpc_inventario(hoje);
  PERFORM sngpc_envio_registrar(jsonb_build_object('tipo', 'inventario', 'inicio', hoje, 'fim', hoje, 'farmaceutico_id', farma, 'xml', x, 'assinatura', r ->> 'assinatura'));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'inventario', 'inicio', current_date - 3, 'fim', current_date, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'inventário com período em vez de uma data');
  PERFORM ci.deve_falhar(gest, format($c$SELECT sngpc_envio_registrar(jsonb_build_object('tipo', 'inventario', 'inicio', current_date - 9, 'fim', current_date - 9, 'farmaceutico_id', %L, 'xml', %L))$c$, farma, x), 'inventário de 9 dias atrás');

  -- limpeza (os registros do SNGPC não se apagam pelo cliente; aqui só o dono do banco desfaz o teste)
  ALTER TABLE sngpc_envios DISABLE TRIGGER trg_sngpc_envio_guarda;
  ALTER TABLE sngpc_itens DISABLE TRIGGER trg_sngpc_item_guarda;
  ALTER TABLE sngpc_documentos DISABLE TRIGGER trg_sngpc_documento_guarda;
  DELETE FROM sngpc_envios WHERE tenant_id = demo;
  DELETE FROM sngpc_itens WHERE tenant_id = demo;
  DELETE FROM sngpc_documentos WHERE tenant_id = demo;
  ALTER TABLE sngpc_envios ENABLE TRIGGER trg_sngpc_envio_guarda;
  ALTER TABLE sngpc_itens ENABLE TRIGGER trg_sngpc_item_guarda;
  ALTER TABLE sngpc_documentos ENABLE TRIGGER trg_sngpc_documento_guarda;
  DELETE FROM sngpc_medicamentos WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant, cnpj = cnpj_ant WHERE tenant_id = demo;
END $$;

-- 95. Pet: cobrança no caixa da ordem de serviço e da internação (vínculo, estoque e venda cancelada)
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  vet  constant uuid := 'a0000000-0000-0000-0000-0000000001d1';
  aux  constant uuid := 'a0000000-0000-0000-0000-0000000001d2';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  dep uuid; merc uuid; serv uuid; serv_prod uuid; avulso uuid; tutor uuid; pet uuid; pet2 uuid; box uuid; box2 uuid;
  os uuid; os2 uuid; os3 uuid; it uuid; ped uuid; ped2 uuid; ped3 uuid; ped_errado uuid; ped_cancelado uuid; aut uuid; i1 uuid; i2 uuid; r jsonb; q numeric;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo ORDER BY created_at LIMIT 1;
  UPDATE empresas SET ramo_atividade = 'clinica' WHERE tenant_id = demo;
  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Cobrança OS CI') RETURNING id INTO dep;
  INSERT INTO produtos (tenant_id, codigo_interno, descricao, unidade, preco_venda, ncm, cst_csosn) VALUES (demo, 'COB-RACAO', 'Ração cobrança OS', 'UN', 20, '23091000', '102') RETURNING id INTO merc;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Tutor Cobrança OS CI', '52998224725') RETURNING id INTO tutor;
  PERFORM ci.entrar(adm);
  PERFORM registrar_movimentacao(merc, dep, 'entrada'::mov_tipo, 50, 'ci', 'ci');
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  serv := pet_servico_salvar('{"nome":"Banho Cobrança OS","duracao_min":60}'::jsonb);
  PERFORM ci.sair();
  SELECT produto_id INTO serv_prod FROM pet_servicos WHERE id = serv;
  PERFORM ci.entrar(vend);
  pet := pet_salvar(jsonb_build_object('cliente_id', tutor, 'nome', 'Rex Cobrança OS'));
  PERFORM ci.sair();

  -- ===== ordem de serviço =====
  PERFORM ci.entrar(vend);
  os := pet_os_salvar(jsonb_build_object('pet_id', pet, 'queixa', 'Banho e tosa', 'deposito_id', dep));
  PERFORM pet_os_item_adicionar(os, jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco', 60));
  PERFORM pet_os_item_adicionar(os, jsonb_build_object('produto_id', merc, 'quantidade', 2));
  PERFORM pet_os_item_adicionar(os, '{"descricao":"Tosa higiênica","quantidade":1,"preco":25.5}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_cobranca(%L)$c$, os), 'cobrar ordem que ainda não está pronta');
  PERFORM ci.entrar(vend);
  PERFORM pet_os_situacao(os, 'aprovada', dep);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 48 FROM estoques WHERE produto_id = merc AND deposito_id = dep), 'aprovar a ordem baixa a ração (50 - 2)');
  PERFORM ci.entrar(vend);
  PERFORM pet_os_situacao(os, 'em_reparo'); PERFORM pet_os_situacao(os, 'pronta');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_situacao(%L, 'entregue')$c$, os), 'entregar ordem com valor sem cobrar no caixa');

  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_os_cobranca(%L)$c$, os), 'garçom abre a cobrança da ordem');
  PERFORM ci.deve_falhar(est, format($c$SELECT pet_os_cobranca(%L)$c$, os), 'estoquista abre a cobrança da ordem');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT pet_os_cobranca(%L)$c$, os), 'anon abre a cobrança da ordem');
  PERFORM ci.entrar(vend); r := pet_os_cobranca(os); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'linhas') = 3 AND (r ->> 'cliente_id')::uuid = tutor AND r ->> 'pet' = 'Rex Cobrança OS', 'a cobrança da ordem traz 3 linhas, o tutor e o animal');
  avulso := (SELECT (e ->> 'produto_id')::uuid FROM jsonb_array_elements(r -> 'linhas') e WHERE e ->> 'descricao' = 'Tosa higiênica');
  PERFORM ci.exige(avulso = (SELECT id FROM produtos WHERE tenant_id = demo AND codigo_interno = 'PET-AVULSO') AND NOT (SELECT controla_estoque FROM produtos WHERE id = avulso),
                   'o item avulso vai no produto de apoio, que não controla estoque');

  PERFORM ci.entrar(vend);
  ped := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 60),
                                          jsonb_build_object('produto_id', merc, 'quantidade', 2, 'preco_unitario', 20),
                                          jsonb_build_object('produto_id', avulso, 'quantidade', 1, 'preco_unitario', 25.5)), 'crediario', tutor, 0, 1, current_date + 30);
  ped_errado := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 60),
                                                 jsonb_build_object('produto_id', merc, 'quantidade', 1, 'preco_unitario', 20),
                                                 jsonb_build_object('produto_id', avulso, 'quantidade', 1, 'preco_unitario', 25.5)), 'crediario', tutor, 0, 1, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT quantidade = 45 FROM estoques WHERE produto_id = merc AND deposito_id = dep), 'as duas vendas baixam 2 + 1 (48 - 3): hoje a baixa está em dobro');

  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_cobrar(%L, %L)$c$, os, ped_errado), 'venda com menos ração do que a ordem');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_cobrar(%L, %L)$c$, os, gen_random_uuid()), 'venda que não existe');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_cobrar(%L)$c$, os), 'cobrar sem informar a venda');
  PERFORM ci.deve_falhar(gar, format($c$SELECT pet_os_cobrar(%L, %L)$c$, os, ped), 'garçom cobra a ordem');
  PERFORM ci.entrar(vend);
  r := pet_os_cobrar(os, ped);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'entregue' AND venda_id = ped AND entregue_em IS NOT NULL AND NOT controla_estoque FROM os_ordens WHERE id = os), 'cobrada: a ordem fica entregue, ligada à venda');
  PERFORM ci.exige((SELECT quantidade = 47 FROM estoques WHERE produto_id = merc AND deposito_id = dep), 'a baixa da ordem foi devolvida: sobra a da venda (45 + 2)');
  PERFORM ci.entrar(vend); r := pet_os_cobrar(os, ped); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT quantidade = 47 FROM estoques WHERE produto_id = merc AND deposito_id = dep), 'repetir a cobrança não mexe no estoque');
  PERFORM ci.entrar(vend);
  os2 := pet_os_salvar(jsonb_build_object('pet_id', pet, 'deposito_id', dep));
  PERFORM pet_os_item_adicionar(os2, jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco', 60));
  PERFORM pet_os_situacao(os2, 'aprovada', dep); PERFORM pet_os_situacao(os2, 'em_reparo'); PERFORM pet_os_situacao(os2, 'pronta');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_cobrar(%L, %L)$c$, os2, ped), 'a mesma venda cobrando duas ordens');
  PERFORM ci.entrar(vend);
  UPDATE os_ordens SET venda_id = NULL, situacao = 'pronta', controla_estoque = true WHERE id = os;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT venda_id = ped AND situacao = 'entregue' AND NOT controla_estoque FROM os_ordens WHERE id = os), 'o cliente não desfaz o vínculo nem anda a ordem pela tabela');
  PERFORM ci.entrar(vend);
  UPDATE os_ordens SET situacao = 'entregue' WHERE id = os2;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'pronta' FROM os_ordens WHERE id = os2), 'marcar a ordem do pet como entregue pela tabela não vale (a cobrança não se contorna)');
  PERFORM ci.deve_falhar(vend, format($c$INSERT INTO os_itens (tenant_id, os_id, tipo, descricao, quantidade, preco_unitario, total) VALUES (%L, %L, 'servico', 'Item por fora', 1, 5, 5)$c$, demo, os), 'incluir item na ordem do pet pela tabela');
  PERFORM ci.deve_falhar(vend, format($c$DELETE FROM os_itens WHERE os_id = %L$c$, os), 'apagar item da ordem do pet pela tabela');
  PERFORM ci.deve_falhar(vend, format($c$UPDATE os_itens SET preco_unitario = 1 WHERE os_id = %L$c$, os), 'alterar item da ordem do pet pela tabela');

  -- venda cancelada: a ordem volta a pronta e a baixa dela é refeita
  INSERT INTO gestor_autorizacoes (tenant_id, gestor_id, operador_id, acao) VALUES (demo, gest, adm, 'cancelar_venda') RETURNING id INTO aut;
  PERFORM ci.entrar(adm);
  PERFORM frente_cancelar_venda(ped, aut, 'Teste da cobrança da ordem');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'pronta' AND venda_id IS NULL AND entregue_em IS NULL AND controla_estoque FROM os_ordens WHERE id = os), 'venda cancelada devolve a ordem a pronta');
  PERFORM ci.exige((SELECT baixa_quantidade = 2 FROM os_itens WHERE os_id = os AND produto_id = merc), 'a ordem baixa a ração de novo');
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 47, 'estoque depois do cancelamento: 47 + 2 (venda devolvida) - 2 (a ordem baixa de novo) = 47');
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_cobrar(%L, %L)$c$, os, ped), 'cobrar com venda cancelada');
  PERFORM ci.entrar(vend);
  ped2 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 60),
                                           jsonb_build_object('produto_id', merc, 'quantidade', 2, 'preco_unitario', 20),
                                           jsonb_build_object('produto_id', avulso, 'quantidade', 1, 'preco_unitario', 25.5)), 'crediario', tutor, 0, 1, current_date + 30);
  PERFORM pet_os_cobrar(os, ped2);
  PERFORM ci.sair();
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 47, 'cobrar de novo: a venda baixa 2 e a ordem devolve 2 (continua 47)');

  -- o mesmo produto com dois valores na ordem não dá para cobrar de uma vez
  PERFORM ci.entrar(vend);
  os3 := pet_os_salvar(jsonb_build_object('pet_id', pet, 'deposito_id', dep));
  PERFORM pet_os_item_adicionar(os3, jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco', 60));
  PERFORM pet_os_item_adicionar(os3, jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco', 70));
  PERFORM pet_os_situacao(os3, 'aprovada', dep); PERFORM pet_os_situacao(os3, 'em_reparo'); PERFORM pet_os_situacao(os3, 'pronta');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT pet_os_cobranca(%L)$c$, os3), 'mesmo produto com dois valores na ordem');

  -- ordem sem valor entrega direto, sem caixa
  PERFORM ci.entrar(vend);
  PERFORM pet_os_salvar(jsonb_build_object('id', os2, 'desconto', 60));
  PERFORM pet_os_situacao(os2, 'entregue');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'entregue' AND valor_total = 0 FROM os_ordens WHERE id = os2), 'ordem zerada por desconto entrega sem cobrança');

  -- ===== internação =====
  INSERT INTO pets (tenant_id, cliente_id, nome) VALUES (demo, tutor, 'Paciente Cobrança CI') RETURNING id INTO pet2;
  PERFORM ci.entrar(gest);
  box := pet_box_salvar('{"nome":"Box Cobrança CI"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vet);
  i1 := clinica_internacao_admitir(pet2, jsonb_build_object('box_id', box, 'motivo', 'Cobrança'));
  PERFORM ci.sair();
  PERFORM ci.entrar(aux);
  PERFORM clinica_internacao_item_lancar(i1, jsonb_build_object('produto_id', merc, 'quantidade', 3, 'deposito_id', dep));
  PERFORM clinica_internacao_item_lancar(i1, jsonb_build_object('produto_id', serv_prod, 'preco', 80));
  PERFORM clinica_internacao_item_lancar(i1, '{"descricao":"Curativo","quantidade":2,"preco":15}'::jsonb);
  PERFORM ci.sair();
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 44, 'a internação baixou 3 ração (47 - 3)');

  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_internacao_cobranca(%L)$c$, i1), 'cobrar animal ainda internado');
  PERFORM ci.entrar(vet);
  PERFORM clinica_internacao_encerrar(i1, 'alta', 'Alta no mesmo dia');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_cobranca(%L)$c$, i1), 'veterinário abre a cobrança');
  PERFORM ci.deve_falhar(aux, format($c$SELECT clinica_internacao_cobranca(%L)$c$, i1), 'auxiliar abre a cobrança');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_internacao_cobranca(%L)$c$, i1), 'garçom abre a cobrança');
  PERFORM ci.deve_falhar(vet, 'SELECT clinica_internacoes_a_cobrar()', 'veterinário lista as internações a cobrar');
  PERFORM ci.entrar(vend); r := clinica_internacoes_a_cobrar(); PERFORM ci.sair();
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE (e ->> 'id')::uuid = i1 AND (e ->> 'total')::numeric = 170 AND (e ->> 'itens')::int = 3 AND e ->> 'pet' = 'Paciente Cobrança CI'),
                   'a recepção vê a internação a cobrar: ração 3 × 20 + serviço 80 + curativo 2 × 15 = 170');
  PERFORM ci.entrar(vend); r := clinica_internacao_cobranca(i1); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'linhas') = 3 AND NOT (r::text ILIKE '%motivo%') AND (r ->> 'cliente_id')::uuid = tutor, 'a cobrança traz só itens, tutor e animal (nada do texto clínico)');

  PERFORM ci.entrar(vend);
  ped3 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', merc, 'quantidade', 3, 'preco_unitario', 20),
                                           jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 80),
                                           jsonb_build_object('produto_id', avulso, 'quantidade', 2, 'preco_unitario', 15)), 'crediario', tutor, 0, 1, current_date + 30);
  ped_cancelado := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', merc, 'quantidade', 1, 'preco_unitario', 20)), 'crediario', tutor, 0, 1, current_date + 30);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_internacao_cobrar(%L, %L)$c$, i1, ped_cancelado), 'venda que não traz os itens da internação');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_internacao_cobrar(%L, %L)$c$, i1, ped), 'venda cancelada');
  PERFORM ci.deve_falhar(gar, format($c$SELECT clinica_internacao_cobrar(%L, %L)$c$, i1, ped3), 'garçom cobra a internação');
  PERFORM ci.deve_falhar(vet, format($c$SELECT clinica_internacao_cobrar(%L, %L)$c$, i1, ped3), 'veterinário cobra a internação');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_internacao_cobrar(%L, %L)$c$, i1, ped2), 'venda que já cobrou uma ordem');
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 40, 'antes do vínculo a baixa está em dobro (44 - 3 da venda - 1 da venda extra)');
  PERFORM ci.entrar(vend); r := clinica_internacao_cobrar(i1, ped3); PERFORM ci.sair();
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(NOT (r ->> 'repetido')::boolean AND q = 43, 'vínculo: a baixa da internação (3) volta ao estoque e fica a da venda');
  PERFORM ci.exige((SELECT (devolvido -> 0 ->> 'quantidade')::numeric = 3 FROM pet_internacao_cobrancas WHERE internacao_id = i1), 'o que foi devolvido fica registrado');
  PERFORM ci.entrar(vend); r := clinica_internacao_cobrar(i1, ped3); PERFORM ci.sair();
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige((r ->> 'repetido')::boolean AND q = 43, 'repetir não devolve de novo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT clinica_internacao_cobranca(%L)$c$, i1), 'abrir a cobrança de internação já cobrada');
  PERFORM ci.entrar(vend); r := clinica_internacoes_a_cobrar(); PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE (e ->> 'id')::uuid = i1), 'cobrada, sai da lista');
  PERFORM ci.deve_falhar_dono(format($c$UPDATE pet_internacoes SET observacoes = 'x' WHERE id = %L$c$, i1), 'a internação cobrada segue imutável');

  -- venda cancelada: a internação volta a ficar por cobrar e a baixa dela é refeita
  INSERT INTO gestor_autorizacoes (tenant_id, gestor_id, operador_id, acao) VALUES (demo, gest, adm, 'cancelar_venda') RETURNING id INTO aut;
  PERFORM ci.entrar(adm);
  PERFORM frente_cancelar_venda(ped3, aut, 'Teste da cobrança da internação');
  PERFORM ci.sair();
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 43, 'cancelada: a venda devolve 3 e a internação baixa 3 de novo (43)');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM pet_internacao_cobrancas WHERE internacao_id = i1), 'cancelada: a internação volta a ficar por cobrar');
  PERFORM ci.entrar(vend);
  ped3 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', merc, 'quantidade', 3, 'preco_unitario', 20),
                                           jsonb_build_object('produto_id', serv_prod, 'quantidade', 1, 'preco_unitario', 80),
                                           jsonb_build_object('produto_id', avulso, 'quantidade', 2, 'preco_unitario', 15)), 'crediario', tutor, 0, 1, current_date + 30);
  PERFORM clinica_internacao_cobrar(i1, ped3);
  PERFORM ci.sair();
  SELECT quantidade INTO q FROM estoques WHERE produto_id = merc AND deposito_id = dep;
  PERFORM ci.exige(q = 43, 'cobrar de novo: a venda baixa 3, a internação devolve 3 (43)');

  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;

-- 96. Hotelaria (base): módulo liberado por ramo, liberação, CNAE e escolha sem CNPJ; cadastros só por função, só gestão, só do próprio hotel e da própria empresa; tarifa certa pela prioridade; hóspede com CPF conferido
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  f1   constant uuid := '33333333-3333-3333-3333-333333333333';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  hgar constant uuid := 'a0000000-0000-0000-0000-0000000002a0';
  bges constant uuid := 'a0000000-0000-0000-0000-0000000002a1';
  ramo_ant text; cnae_ant text; cnae2_ant text; sem_ant text[];
  f2 uuid; tb uuid; eb uuid; fb uuid;
  t1 uuid; t2 uuid; tb1 uuid; u1 uuid; u2 uuid; hb uuid;
  ta uuid; tbw uuid; tc uuid; td uuid; h1 uuid; h2 uuid; cfg uuid; cfg2 uuid;
  lib boolean;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios, modulos_sem_cnpj INTO ramo_ant, cnae_ant, cnae2_ant, sem_ant FROM empresas WHERE id = emp;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = NULL, cnae_secundarios = NULL, modulos_sem_cnpj = '{}' WHERE id = emp;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';

  INSERT INTO auth.users (id, email) VALUES (hgar, 'garcom-hotel@ci'), (bges, 'gestor-hotel-b@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = hgar;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (hgar, demo, 'garcom');
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI 2') RETURNING id INTO f2;

  -- sem o módulo nada abre
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('filial_id', %L, 'nome', 'Standard'))$c$, f1), 'tipo de acomodação sem o módulo liberado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_config_salvar(%L, '{}'::jsonb)$c$, f1), 'configuração do hotel sem o módulo liberado');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Sem módulo"}'::jsonb)$c$, 'hóspede sem o módulo liberado');

  -- como o módulo é liberado: ramo, CNAE (5510 e 5590), escolha sem CNPJ e liberação explícita; outros CNAE e ramos não liberam
  PERFORM ci.entrar(gest); lib := hotelaria_liberada(); PERFORM ci.sair();
  PERFORM ci.exige(lib IS FALSE, 'empresa de outro ramo e sem CNAE de hospedagem não tem o módulo');
  UPDATE empresas SET ramo_atividade = 'hotelaria' WHERE id = emp;
  PERFORM ci.entrar(gest); lib := hotelaria_liberada(); PERFORM ci.sair();
  PERFORM ci.exige(lib IS TRUE, 'ramo Hotelaria libera o módulo');
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '5510-8/01' WHERE id = emp;
  PERFORM ci.entrar(gest); lib := hotelaria_liberada(); PERFORM ci.sair();
  PERFORM ci.exige(lib IS TRUE, 'CNAE 55.10-8 (hotéis) libera o módulo');
  UPDATE empresas SET cnae = NULL, cnae_secundarios = '4711-3/02, 5590-6/01' WHERE id = emp;
  PERFORM ci.entrar(gest); lib := hotelaria_liberada(); PERFORM ci.sair();
  PERFORM ci.exige(lib IS TRUE, 'CNAE secundário 55.90-6 (outros alojamentos) libera o módulo');
  UPDATE empresas SET cnae = '5611-2/01', cnae_secundarios = '5620-1/04' WHERE id = emp;
  PERFORM ci.entrar(gest); lib := hotelaria_liberada(); PERFORM ci.sair();
  PERFORM ci.exige(lib IS FALSE, 'restaurante (56.xx) não libera hotelaria');
  UPDATE empresas SET cnae = NULL, cnae_secundarios = NULL WHERE id = emp;
  UPDATE empresas SET modulos_sem_cnpj = ARRAY['hotelaria'] WHERE id = emp;
  PERFORM ci.deve_falhar_dono(format($c$UPDATE empresas SET modulos_sem_cnpj = ARRAY['hotel'] WHERE id = %L$c$, emp), 'módulo sem CNPJ com nome fora da lista');
  UPDATE empresas SET modulos_sem_cnpj = '{}' WHERE id = emp;
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'hotelaria');
  PERFORM ci.entrar(gest); lib := hotelaria_liberada(); PERFORM ci.sair();
  PERFORM ci.exige(lib IS TRUE, 'liberação explícita abre o módulo');
  PERFORM ci.deve_falhar(NULL, $c$SELECT hotelaria_liberada()$c$, 'anônimo consulta o módulo');
  PERFORM ci.deve_falhar(gest, $c$SELECT _hs_exige_liberado()$c$, 'usuário chama a trava interna do módulo');

  -- cadastros: só gestão
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('filial_id', %L, 'nome', 'Standard'))$c$, f1), 'vendedor cria tipo de acomodação');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('filial_id', %L, 'nome', 'Standard'))$c$, f1), 'garçom cria tipo de acomodação');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_config_salvar(%L, '{}'::jsonb)$c$, f1), 'vendedor mexe na configuração do hotel');
  PERFORM ci.deve_falhar(hgar, $c$SELECT hs_hospede_salvar('{"nome":"Garçom"}'::jsonb)$c$, 'garçom cadastra hóspede');

  PERFORM ci.entrar(gest);
  t1 := hs_tipo_uh_salvar(jsonb_build_object('filial_id', f1, 'nome', 'Standard casal', 'capacidade_adultos', 2, 'capacidade_criancas', 1,
                                             'comodidades', jsonb_build_array('Ar-condicionado', ' TV ', 'tv', '')));
  t2 := hs_tipo_uh_salvar(jsonb_build_object('filial_id', f2, 'nome', 'Standard casal'));
  PERFORM ci.sair();
  -- a lista sai de array_agg(DISTINCT ...), cuja ordem depende da collation do banco ("TV, tv" em C, "tv, TV" em en_US): compara na ordem de C
  PERFORM ci.exige((SELECT (SELECT array_agg(c ORDER BY c COLLATE "C") FROM unnest(comodidades) c) = ARRAY['Ar-condicionado', 'TV', 'tv'] AND capacidade_criancas = 1 FROM hs_tipos_uh WHERE id = t1), 'tipo guarda capacidade e comodidades sem vazios');
  PERFORM ci.exige(t1 <> t2, 'o mesmo nome vale em hotéis diferentes');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('filial_id', %L, 'nome', ' standard CASAL '))$c$, f1), 'tipo com nome repetido no mesmo hotel');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('filial_id', %L, 'nome', 'X', 'capacidade_adultos', 0))$c$, f1), 'tipo sem adulto');
  PERFORM ci.deve_falhar(gest, $c$SELECT hs_tipo_uh_salvar('{"nome":"Sem hotel"}'::jsonb)$c$, 'tipo sem hotel');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('id', %L, 'filial_id', %L, 'nome', 'Mudou'))$c$, t1, f2), 'tipo trocado de hotel');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO hs_tipos_uh (tenant_id, filial_id, nome) VALUES (%L, %L, 'Direto')$c$, demo, f1), 'administrador insere tipo direto na tabela');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_tipos_uh SET nome = 'Direto' WHERE id = %L$c$, t1), 'administrador altera tipo direto na tabela');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM hs_tipos_uh WHERE id = %L$c$, t1), 'administrador apaga tipo direto na tabela');

  -- acomodações
  PERFORM ci.entrar(gest);
  u1 := hs_uh_salvar(jsonb_build_object('tipo_id', t1, 'numero', '101', 'andar', '1'));
  u2 := hs_uh_salvar(jsonb_build_object('tipo_id', t1, 'numero', '102', 'interditada', true, 'motivo_interdicao', 'Infiltração'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT filial_id = f1 AND situacao_limpeza = 'limpo' AND NOT interditada FROM hs_uhs WHERE id = u1), 'a UH nasce limpa e no hotel do tipo');
  PERFORM ci.exige((SELECT interditada AND motivo_interdicao = 'Infiltração' FROM hs_uhs WHERE id = u2), 'UH interditada guarda o motivo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('tipo_id', %L, 'numero', ' 101 '))$c$, t1), 'UH com número repetido');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('tipo_id', %L, 'numero', '103', 'interditada', true))$c$, t1), 'UH interditada sem motivo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('tipo_id', %L, 'numero', ''))$c$, t1), 'UH sem número');
  PERFORM ci.deve_falhar(gest, $c$SELECT hs_uh_salvar('{"numero":"200"}'::jsonb)$c$, 'UH sem tipo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('id', %L, 'tipo_id', %L, 'numero', '101'))$c$, u1, t2), 'UH trocada para o tipo de outro hotel');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('id', %L, 'filial_id', %L, 'nome', 'Standard casal', 'ativo', false))$c$, t1, f1), 'inativar tipo que ainda tem UH ativa');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_uhs SET situacao_limpeza = 'sujo' WHERE id = %L$c$, u1), 'administrador suja a UH direto na tabela');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_uhs (tenant_id, filial_id, tipo_id, numero) VALUES (%L, %L, %L, '999')$c$, demo, f2, t1), 'UH de um hotel com tipo de outro hotel');
  -- tipo inativo não recebe UH nova
  PERFORM ci.entrar(gest);
  PERFORM hs_uh_salvar(jsonb_build_object('id', u1, 'tipo_id', t1, 'numero', '101', 'ativo', false));
  PERFORM hs_uh_salvar(jsonb_build_object('id', u2, 'tipo_id', t1, 'numero', '102', 'ativo', false, 'interditada', true, 'motivo_interdicao', 'Infiltração'));
  PERFORM hs_tipo_uh_salvar(jsonb_build_object('id', t1, 'filial_id', f1, 'nome', 'Standard casal', 'ativo', false));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('tipo_id', %L, 'numero', '104'))$c$, t1), 'UH ativa num tipo inativo');
  PERFORM ci.entrar(gest);
  PERFORM hs_tipo_uh_salvar(jsonb_build_object('id', t1, 'filial_id', f1, 'nome', 'Standard casal', 'ativo', true));
  PERFORM hs_uh_salvar(jsonb_build_object('id', u1, 'tipo_id', t1, 'numero', '101', 'ativo', true));
  PERFORM ci.sair();

  -- tarifas: A todo ano (100), B fim de semana (150, prioridade 1), C réveillon (300, prioridade 5), D julho (120, mesma prioridade da A, vigência menor)
  PERFORM ci.entrar(gest);
  ta  := hs_tarifa_salvar(jsonb_build_object('tipo_id', t1, 'nome', 'Balcão 2027', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-12-31', 'valor_diaria', 100));
  tbw := hs_tarifa_salvar(jsonb_build_object('tipo_id', t1, 'nome', 'Fim de semana', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-12-31',
                                             'dias_semana', jsonb_build_array(6, 5, 6), 'valor_diaria', 150, 'prioridade', 1));
  tc  := hs_tarifa_salvar(jsonb_build_object('tipo_id', t1, 'nome', 'Réveillon', 'vigencia_de', '2027-12-30', 'vigencia_ate', '2027-12-31',
                                             'valor_diaria', 300, 'prioridade', 5, 'minimo_noites', 3));
  td  := hs_tarifa_salvar(jsonb_build_object('tipo_id', t1, 'nome', 'Julho', 'vigencia_de', '2027-07-01', 'vigencia_ate', '2027-07-31', 'valor_diaria', 120));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT dias_semana = ARRAY[5, 6]::smallint[] FROM hs_tarifas WHERE id = tbw), 'dias da semana saem sem repetir e em ordem');
  PERFORM ci.exige(_hs_tarifa(t1, date '2027-01-04') = ta, 'segunda-feira: tarifa de balcão');
  PERFORM ci.exige(_hs_tarifa(t1, date '2027-01-01') = tbw, 'sexta-feira: a de fim de semana vence pela prioridade');
  PERFORM ci.exige(_hs_tarifa(t1, date '2027-01-02') = tbw, 'sábado: a de fim de semana');
  PERFORM ci.exige(_hs_tarifa(t1, date '2027-07-14') = td, 'quarta de julho: empate de prioridade, vence a de menor vigência');
  PERFORM ci.exige(_hs_tarifa(t1, date '2027-07-17') = tbw, 'sábado de julho: maior prioridade vence a de menor vigência');
  PERFORM ci.exige(_hs_tarifa(t1, date '2027-12-31') = tc, 'réveillon: a de maior prioridade');
  PERFORM ci.exige(_hs_tarifa(t1, date '2026-12-31') IS NULL AND _hs_tarifa(t1, date '2028-01-01') IS NULL, 'fora de toda vigência não há tarifa');
  PERFORM ci.entrar(gest);
  PERFORM hs_tarifa_salvar(jsonb_build_object('id', td, 'tipo_id', t1, 'nome', 'Julho', 'vigencia_de', '2027-07-01', 'vigencia_ate', '2027-07-31', 'valor_diaria', 120, 'ativo', false));
  PERFORM ci.sair();
  PERFORM ci.exige(_hs_tarifa(t1, date '2027-07-14') = ta, 'tarifa inativa não vale');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-02-01', 'vigencia_ate', '2027-01-01', 'valor_diaria', 1))$c$, t1), 'vigência invertida');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02'))$c$, t1), 'tarifa sem valor');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', -5))$c$, t1), 'diária negativa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', 1, 'dias_semana', jsonb_build_array(7)))$c$, t1), 'dia da semana 7');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', 1, 'minimo_noites', 0))$c$, t1), 'mínimo de noites zero');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', 1))$c$, t1), 'vendedor cria tarifa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('id', %L, 'tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', 1))$c$, ta, t1), 'vendedor altera tarifa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_tarifa_remover(%L)$c$, ta), 'vendedor remove tarifa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('id', %L, 'tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', 1))$c$, ta, t2), 'tarifa trocada para o tipo de outro hotel');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_tarifas SET valor_diaria = 1 WHERE id = %L$c$, ta), 'administrador muda o preço direto na tabela');
  PERFORM ci.entrar(gest); PERFORM hs_tarifa_remover(tc); PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM hs_tarifas WHERE id = tc), 'a gestão remove a tarifa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_remover(%L)$c$, tc), 'remover tarifa que já não existe');

  -- configuração do hotel
  PERFORM ci.entrar(gest);
  cfg := hs_config_salvar(f1, '{"checkin_hora":"15:00","taxa_turismo_por_hospede_noite":"3.50","exige_documento_checkin":false}'::jsonb);
  cfg2 := hs_config_salvar(f1, '{"checkout_hora":"11:00","cobra_diaria_no_checkout_tardio":true}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(cfg = cfg2 AND (SELECT count(*) FROM hs_config WHERE filial_id = f1) = 1, 'a configuração é uma por hotel e salvar de novo atualiza');
  PERFORM ci.exige((SELECT checkin_hora = '14:00' AND checkout_hora = '11:00' AND taxa_turismo_por_hospede_noite = 0 AND exige_documento_checkin AND cobra_diaria_no_checkout_tardio
                      FROM hs_config WHERE filial_id = f1), 'salvar de novo traz o que foi enviado e o padrão do resto');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_config_salvar(%L, '{"taxa_turismo_por_hospede_noite":-1}'::jsonb)$c$, f1), 'taxa de turismo negativa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_config_salvar(%L, '{"fuso":"Marte/Olimpo"}'::jsonb)$c$, f1), 'fuso horário inexistente');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_config SET taxa_turismo_por_hospede_noite = 99 WHERE filial_id = %L$c$, f1), 'administrador muda a configuração direto na tabela');

  -- hóspedes
  PERFORM ci.entrar(vend);
  h1 := hs_hospede_salvar('{"nome":"Maria Silva","documento_tipo":"cpf","documento_numero":"529.982.247-25","sexo":"F","motivo_viagem":"lazer","meio_transporte":"automovel","estado_residencia":"pe","email":"maria@ex.com"}'::jsonb);
  h2 := hs_hospede_salvar('{"nome":"John Smith","documento_tipo":"passaporte","documento_numero":"ab-123 456","nacionalidade":"Americana","pais_residencia":"Estados Unidos"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT documento_numero = '52998224725' AND estado_residencia = 'PE' AND pais_residencia = 'Brasil' FROM hs_hospedes WHERE id = h1), 'CPF guardado só com dígitos e UF em maiúsculas');
  PERFORM ci.exige((SELECT documento_numero = 'AB123456' AND pais_residencia = 'Estados Unidos' FROM hs_hospedes WHERE id = h2), 'passaporte guardado em maiúsculas e sem pontuação; estrangeiro sem CPF é aceito');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Dup","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb)$c$, 'hóspede com CPF repetido (outra pontuação)');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Dup","documento_tipo":"passaporte","documento_numero":"AB 123456"}'::jsonb)$c$, 'hóspede com passaporte repetido');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"CPF ruim","documento_tipo":"cpf","documento_numero":"12345678900"}'::jsonb)$c$, 'CPF com dígito verificador errado');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"CPF ruim","documento_tipo":"cpf","documento_numero":"11111111111"}'::jsonb)$c$, 'CPF de dígitos repetidos');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Sem número","documento_tipo":"rg"}'::jsonb)$c$, 'tipo de documento sem número');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Sem tipo","documento_numero":"123456"}'::jsonb)$c$, 'número de documento sem tipo');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"  "}'::jsonb)$c$, 'hóspede sem nome');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Futuro","data_nascimento":"2999-01-01"}'::jsonb)$c$, 'nascimento no futuro');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Mail","email":"sem-arroba"}'::jsonb)$c$, 'e-mail inválido');
  PERFORM ci.deve_falhar(vend, $c$SELECT hs_hospede_salvar('{"nome":"Motivo","motivo_viagem":"turismo-espacial"}'::jsonb)$c$, 'motivo de viagem fora da lista');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_hospede_salvar(jsonb_build_object('id', %L, 'nome', 'Troca', 'documento_tipo', 'cpf', 'documento_numero', '52998224725'))$c$, h2), 'passar para o hóspede o CPF de outro');
  PERFORM ci.entrar(vend);
  PERFORM hs_hospede_salvar(jsonb_build_object('id', h1, 'nome', 'Maria Silva Souza', 'documento_tipo', 'cpf', 'documento_numero', '52998224725'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT nome = 'Maria Silva Souza' AND (SELECT count(*) FROM hs_hospedes WHERE tenant_id = demo AND documento_numero = '52998224725') = 1 FROM hs_hospedes WHERE id = h1), 'editar o hóspede com o próprio CPF não conta como repetido');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_hospedes SET nome = 'Direto' WHERE id = %L$c$, h1), 'administrador altera hóspede direto na tabela');
  PERFORM ci.deve_falhar(hgar, $c$SELECT hs_hospede_salvar('{"nome":"Garçom"}'::jsonb)$c$, 'garçom cadastra hóspede (com o módulo liberado)');

  -- o salão (garçom e cozinha) não enxerga nada do hotel; anônimo também não
  PERFORM ci.exige(ci.contar(hgar, 'SELECT count(*) FROM hs_hospedes') = 0, 'garçom não lê os hóspedes');
  PERFORM ci.exige(ci.contar(hgar, 'SELECT count(*) FROM hs_tipos_uh') = 0, 'garçom não lê os tipos de acomodação');
  PERFORM ci.exige(ci.contar(hgar, 'SELECT count(*) FROM hs_tarifas') = 0, 'garçom não lê as tarifas');
  PERFORM ci.deve_falhar(NULL, 'SELECT count(*) FROM hs_uhs', 'anônimo lê as acomodações');
  PERFORM ci.deve_falhar(NULL, $c$SELECT hs_hospede_salvar('{"nome":"Anon"}'::jsonb)$c$, 'anônimo cadastra hóspede');

  -- quem só acessa um hotel só enxerga o cadastro dele
  UPDATE profiles SET filial_id = f2 WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_tipos_uh') = 1, 'recepção do hotel 2 só lê os tipos do hotel 2');
  PERFORM ci.exige(ci.contar(vend, format('SELECT count(*) FROM hs_uhs WHERE filial_id = %L', f1)) = 0, 'recepção do hotel 2 não lê as acomodações do hotel 1');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_tarifas') = 0, 'recepção do hotel 2 não lê as tarifas do hotel 1');
  UPDATE profiles SET filial_id = f1 WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_tipos_uh') = 1 AND ci.contar(vend, 'SELECT count(*) FROM hs_tarifas') > 0, 'recepção do hotel 1 lê o cadastro do hotel 1');
  UPDATE profiles SET filial_id = NULL WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_tipos_uh') = 2, 'recepção sem filial fixa lê todos os hotéis da empresa');

  -- outra empresa: não vê, não usa e não altera
  INSERT INTO tenants (nome) VALUES ('Hotel B') RETURNING id INTO tb;
  INSERT INTO empresas (tenant_id, razao_social, ramo_atividade) VALUES (tb, 'Hotel B Ltda', 'hotelaria') RETURNING id INTO eb;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (tb, eb, 'Hotel B Centro') RETURNING id INTO fb;
  UPDATE profiles SET tenant_id = tb WHERE id = bges;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (bges, tb, 'gestor');
  PERFORM ci.entrar(bges);
  tb1 := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fb, 'nome', 'Standard casal'));
  PERFORM hs_hospede_salvar('{"nome":"Hóspede B","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb);
  PERFORM ci.sair();
  SELECT id INTO hb FROM hs_hospedes WHERE tenant_id = tb LIMIT 1;
  PERFORM ci.exige(ci.contar(bges, 'SELECT count(*) FROM hs_tipos_uh') = 1 AND ci.contar(bges, 'SELECT count(*) FROM hs_hospedes') = 1, 'o gestor B só lê o que é do hotel B');
  PERFORM ci.exige(ci.contar(gest, format('SELECT count(*) FROM hs_tipos_uh WHERE tenant_id = %L', tb)) = 0, 'o gestor A não lê o tipo do hotel B');
  PERFORM ci.exige(ci.contar(gest, 'SELECT count(*) FROM hs_hospedes WHERE nome = ''Hóspede B''') = 0, 'o gestor A não lê o hóspede da outra empresa');
  PERFORM ci.exige(ci.contar(bges, 'SELECT count(*) FROM hs_tarifas') = 0 AND ci.contar(bges, 'SELECT count(*) FROM hs_uhs') = 0, 'o gestor B não lê tarifas nem UHs do hotel A');
  PERFORM ci.exige((SELECT count(*) FROM hs_hospedes WHERE documento_numero = '52998224725') = 2, 'o mesmo CPF vale em empresas diferentes');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tipo_uh_salvar(jsonb_build_object('filial_id', %L, 'nome', 'Invasor'))$c$, fb), 'criar tipo no hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_config_salvar(%L, '{}'::jsonb)$c$, fb), 'configurar o hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('tipo_id', %L, 'numero', '1'))$c$, tb1), 'criar UH num tipo de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', 1))$c$, tb1), 'criar tarifa num tipo de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_hospede_salvar(jsonb_build_object('id', %L, 'nome', 'Invasor'))$c$, hb), 'editar o hóspede de outra empresa');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_tarifas (tenant_id, tipo_id, nome, vigencia_de, vigencia_ate, valor_diaria) VALUES (%L, %L, 'x', '2027-01-01', '2027-01-02', 1)$c$, demo, tb1), 'tarifa da empresa A num tipo da empresa B');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_tipos_uh (tenant_id, filial_id, nome) VALUES (%L, %L, 'Cruzado')$c$, demo, fb), 'tipo da empresa A num hotel da empresa B');

  -- limpeza
  DELETE FROM hs_tarifas WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_uhs WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_tipos_uh WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_hospedes WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_config WHERE tenant_id IN (demo, tb);
  DELETE FROM user_roles WHERE user_id IN (hgar, bges);
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant, modulos_sem_cnpj = sem_ant WHERE id = emp;
END $$;

-- 97. Hotelaria (reservas): calendário sem cruzar (o banco recusa), cotação e disponibilidade, reserva atômica e idempotente, preço guardado por noite,
-- alterar, trocar de acomodação, cancelar, não comparecimento, interdição por período, permissões e isolamento por hotel e por empresa
CREATE FUNCTION ci.quarto(p_uh uuid, p_entrada text, p_saida text, p_adultos integer DEFAULT 2, p_criancas integer DEFAULT 0, p_acordo numeric DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object('uh_id', p_uh, 'entrada', p_entrada, 'saida', p_saida, 'adultos', p_adultos, 'criancas', p_criancas, 'valor_acordado_total', p_acordo))
$$;
CREATE FUNCTION ci.reserva(p_filial uuid, p_titular uuid, VARIADIC p_quartos jsonb[]) RETURNS jsonb LANGUAGE sql AS $$
  SELECT jsonb_build_object('filial_id', p_filial, 'titular_id', p_titular, 'quartos', to_jsonb(p_quartos))
$$;
CREATE FUNCTION ci.n_calendario() RETURNS bigint LANGUAGE sql AS $$
  SELECT (SELECT count(*) FROM hs_reservas) + (SELECT count(*) FROM hs_reserva_uhs) + (SELECT count(*) FROM hs_diarias) + (SELECT count(*) FROM hs_ocupacoes)
$$;

DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  f1   constant uuid := '33333333-3333-3333-3333-333333333333';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  hgar constant uuid := 'a0000000-0000-0000-0000-0000000002a2';
  bges constant uuid := 'a0000000-0000-0000-0000-0000000002a3';
  hoje date := current_date;
  ramo_ant text; cnae_ant text; cnae2_ant text; sem_ant text[];
  f2 uuid; tb uuid; eb uuid; fb uuid;
  t1 uuid; t2 uuid; t3 uuid; tbx uuid;
  u101 uuid; u102 uuid; u103 uuid; u104 uuid; u201 uuid; u301 uuid; ubx uuid;
  ta1 uuid; tarb uuid; ta2 uuid; ta3 uuid; tabx uuid;
  h1 uuid; h2 uuid; hbx uuid;
  r jsonb; r1 uuid; r2 uuid; r3 uuid; r4 uuid; r5 uuid; r6 uuid; rns uuid; rhoje uuid; rbx uuid;
  ru1 uuid; ru2 uuid; ru3 uuid; ru4 uuid; ru5a uuid; ru5b uuid; ru6 uuid; rune uuid; ruhoje uuid; rubx uuid; ruac uuid;
  k1 uuid := 'c0000000-0000-0000-0000-000000000001';
  n0 bigint; blq uuid; el jsonb; racordo uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios, modulos_sem_cnpj INTO ramo_ant, cnae_ant, cnae2_ant, sem_ant FROM empresas WHERE id = emp;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = NULL, cnae_secundarios = NULL, modulos_sem_cnpj = '{}' WHERE id = emp;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'hotelaria');
  INSERT INTO auth.users (id, email) VALUES (hgar, 'garcom-reservas@ci'), (bges, 'gestor-reservas-b@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = hgar;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (hgar, demo, 'garcom');
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Reservas 2') RETURNING id INTO f2;

  -- cadastro base
  PERFORM ci.entrar(gest);
  t1 := hs_tipo_uh_salvar(jsonb_build_object('filial_id', f1, 'nome', 'Duplo', 'capacidade_adultos', 3, 'capacidade_criancas', 1));
  t2 := hs_tipo_uh_salvar(jsonb_build_object('filial_id', f1, 'nome', 'Suíte', 'capacidade_adultos', 2, 'capacidade_criancas', 0));
  t3 := hs_tipo_uh_salvar(jsonb_build_object('filial_id', f2, 'nome', 'Duplo', 'capacidade_adultos', 2));
  u101 := hs_uh_salvar(jsonb_build_object('tipo_id', t1, 'numero', '101'));
  u102 := hs_uh_salvar(jsonb_build_object('tipo_id', t1, 'numero', '102'));
  u103 := hs_uh_salvar(jsonb_build_object('tipo_id', t1, 'numero', '103'));
  u104 := hs_uh_salvar(jsonb_build_object('tipo_id', t1, 'numero', '104', 'interditada', true, 'motivo_interdicao', 'Reforma'));
  u201 := hs_uh_salvar(jsonb_build_object('tipo_id', t2, 'numero', '201'));
  u301 := hs_uh_salvar(jsonb_build_object('tipo_id', t3, 'numero', '301'));
  ta1 := hs_tarifa_salvar(jsonb_build_object('tipo_id', t1, 'nome', 'Março', 'vigencia_de', '2027-03-01', 'vigencia_ate', '2027-03-31', 'valor_diaria', 100,
                                             'valor_adulto_extra', 40, 'valor_crianca', 20, 'pessoas_incluidas', 2));
  tarb := hs_tarifa_salvar(jsonb_build_object('tipo_id', t1, 'nome', 'Abril 3 noites', 'vigencia_de', '2027-04-01', 'vigencia_ate', '2027-04-30', 'valor_diaria', 90, 'minimo_noites', 3));
  ta2 := hs_tarifa_salvar(jsonb_build_object('tipo_id', t2, 'nome', 'Março suíte', 'vigencia_de', '2027-03-01', 'vigencia_ate', '2027-03-31', 'valor_diaria', 200));
  ta3 := hs_tarifa_salvar(jsonb_build_object('tipo_id', t3, 'nome', 'Março hotel 2', 'vigencia_de', '2027-03-01', 'vigencia_ate', '2027-03-31', 'valor_diaria', 80));
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  h1 := hs_hospede_salvar('{"nome":"Hóspede Reserva Um"}'::jsonb);
  h2 := hs_hospede_salvar('{"nome":"Hóspede Reserva Dois"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT pessoas_incluidas = 2 FROM hs_tarifas WHERE id = ta1) AND (SELECT pessoas_incluidas = 2 FROM hs_tarifas WHERE id = tarb), 'a tarifa guarda as pessoas incluídas (padrão 2)');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_tarifa_salvar(jsonb_build_object('tipo_id', %L, 'nome', 'x', 'vigencia_de', '2027-01-01', 'vigencia_ate', '2027-01-02', 'valor_diaria', 1, 'pessoas_incluidas', 0))$c$, t1), 'tarifa sem nenhuma pessoa incluída');

  -- cotação: diária + adulto além do incluído + crianças; mínimo de noites; sem tarifa; capacidade
  PERFORM ci.entrar(vend);
  r := hs_cotar(f1, t1, date '2027-03-01', date '2027-03-04', 2, 0);
  PERFORM ci.exige((r ->> 'total')::numeric = 300 AND (r ->> 'quantidade')::integer = 3, 'cotação de 3 noites para 2 adultos: 300');
  r := hs_cotar(f1, t1, date '2027-03-01', date '2027-03-04', 3, 1);
  PERFORM ci.exige((r ->> 'total')::numeric = 480, 'cotação com adulto extra (40) e criança (20) por noite: 3 × 160');
  r := hs_cotar(f1, t1, date '2027-04-01', date '2027-04-04');
  PERFORM ci.exige((r ->> 'total')::numeric = 270, 'tarifa de 3 noites mínimas: 3 × 90');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-04-01', date '2027-04-03')$c$, f1, t1), 'cotar abaixo do mínimo de noites da tarifa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-02-27', date '2027-03-02')$c$, f1, t1), 'cotar noite sem tarifa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2027-03-03', 4, 0)$c$, f1, t1), 'cotar acima da capacidade de adultos');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2027-03-03', 2, 2)$c$, f1, t1), 'cotar acima da capacidade de crianças');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-03-03', date '2027-03-03')$c$, f1, t1), 'cotar sem noite');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2027-03-03')$c$, f1, t3), 'cotar com tipo de outro hotel');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2028-03-05')$c$, f1, t1), 'cotar estadia de mais de 365 noites');

  -- disponibilidade antes de reservar: 3 vendáveis no Duplo (a 104 está interditada)
  PERFORM ci.entrar(vend);
  r := hs_disponibilidade(f1, date '2027-03-01', date '2027-03-04');
  PERFORM ci.sair();
  SELECT e INTO el FROM jsonb_array_elements(r) e WHERE e ->> 'tipo_id' = t1::text;
  PERFORM ci.exige((el ->> 'total')::integer = 3 AND (el ->> 'disponiveis')::integer = 3 AND (el ->> 'preco_total')::numeric = 300, 'disponibilidade: 3 livres e preço do período');
  SELECT e INTO el FROM jsonb_array_elements(r) e WHERE e ->> 'tipo_id' = t2::text;
  PERFORM ci.exige((el ->> 'disponiveis')::integer = 1 AND (el ->> 'preco_total')::numeric = 200 * 3, 'disponibilidade da suíte');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r) e WHERE e ->> 'tipo_id' = t3::text), 'disponibilidade só traz os tipos do hotel pedido');

  -- reserva R1: grava reserva, quarto, diárias por noite e a ocupação no calendário
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u101, '2027-03-01', '2027-03-04')), k1);
  PERFORM ci.sair();
  r1 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.exige((r ->> 'total')::numeric = 300 AND (r ->> 'numero')::bigint > 0 AND (r ->> 'repetido')::boolean IS FALSE, 'reserva criada com total e número');
  SELECT id INTO ru1 FROM hs_reserva_uhs WHERE reserva_id = r1;
  PERFORM ci.exige((SELECT situacao = 'confirmada' AND origem = 'balcao' AND criada_por = vend FROM hs_reservas WHERE id = r1), 'reserva nasce confirmada, do balcão e com quem criou');
  PERFORM ci.exige((SELECT count(*) = 3 AND sum(valor) = 300 AND bool_and(NOT lancada) FROM hs_diarias WHERE reserva_uh_id = ru1), 'uma diária por noite, ainda não lançada');
  PERFORM ci.exige((SELECT periodo = daterange(date '2027-03-01', date '2027-03-04', '[)') AND origem = 'reserva' FROM hs_ocupacoes WHERE reserva_uh_id = ru1), 'a ocupação é [entrada, saída)');
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u101, '2027-03-01', '2027-03-04')), k1);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'reserva_id')::uuid = r1 AND (r ->> 'repetido')::boolean AND (r ->> 'total')::numeric = 300, 'repetir a chamada com a mesma chave devolve a mesma reserva');
  PERFORM ci.exige((SELECT count(*) FROM hs_reservas WHERE chave_idempotencia = k1) = 1, 'a repetição não cria outra reserva');

  -- calendário: cruzar é recusado, encostar é aceito; a restrição vale até para o dono do banco
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u101, '2027-03-03', '2027-03-05'))::text), 'reservar a mesma acomodação em período que cruza');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u101, '2027-02-28', '2027-03-02'))::text), 'cruzar pela frente');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u101, '2027-03-02', '2027-03-03'))::text), 'cruzar por dentro');
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(f1, h2, ci.quarto(u101, '2027-03-04', '2027-03-06')));
  PERFORM ci.sair();
  r2 := (r ->> 'reserva_id')::uuid;
  SELECT id INTO ru2 FROM hs_reserva_uhs WHERE reserva_id = r2;
  PERFORM ci.exige(r2 IS NOT NULL, 'a saída de uma reserva é a entrada da próxima: encostar é aceito');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_ocupacoes (tenant_id, filial_id, uh_id, periodo, origem, motivo) VALUES (%L, %L, %L, daterange(date '2027-03-02', date '2027-03-03', '[)'), 'bloqueio', 'x')$c$, demo, f1, u101), 'o dono do banco cruza duas ocupações da mesma acomodação');
  PERFORM ci.entrar(vend);
  r := hs_disponibilidade(f1, date '2027-03-02', date '2027-03-03');
  PERFORM ci.sair();
  SELECT e INTO el FROM jsonb_array_elements(r) e WHERE e ->> 'tipo_id' = t1::text;
  PERFORM ci.exige((el ->> 'ocupadas')::integer = 1 AND (el ->> 'disponiveis')::integer = 2, 'disponibilidade com uma acomodação ocupada na noite');
  PERFORM ci.entrar(vend);
  SELECT e INTO el FROM jsonb_array_elements(hs_disponibilidade(f1, date '2027-03-03', date '2027-03-05')) e WHERE e ->> 'tipo_id' = t1::text;
  PERFORM ci.sair();
  PERFORM ci.exige((el ->> 'ocupadas')::integer = 1 AND (el ->> 'disponiveis')::integer = 2, 'a acomodação com duas reservas no período conta uma vez, e quem ocupa só parte dele também sai da lista');

  -- atômica: se um quarto falha, nada fica gravado
  n0 := ci.n_calendario();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, '2027-03-10', '2027-03-12'), ci.quarto(u101, '2027-03-05', '2027-03-07'))::text), 'reserva de dois quartos em que o segundo cruza');
  PERFORM ci.exige(ci.n_calendario() = n0, 'a reserva que falhou não deixou reserva, quarto, diária nem ocupação');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u103, '2027-06-01', '2027-06-03'))::text), 'reservar noite sem tarifa');
  PERFORM ci.exige(ci.n_calendario() = n0, 'sem tarifa não grava nada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, '2027-03-10', '2027-03-12'), ci.quarto(u102, '2027-03-11', '2027-03-13'))::text), 'o mesmo quarto duas vezes na mesma reserva, cruzando');
  PERFORM ci.exige(ci.n_calendario() = n0, 'a mesma acomodação duas vezes não deixa nada pela metade');

  -- regras da reserva
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u104, '2027-03-10', '2027-03-12'))::text), 'reservar acomodação interditada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u301, '2027-03-10', '2027-03-12'))::text), 'reservar acomodação de outro hotel');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, '2027-03-10', '2027-03-12', 4))::text), 'reservar acima da capacidade');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, '2027-03-12', '2027-03-10'))::text), 'reservar com a saída antes da entrada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, jsonb_build_object('filial_id', f1, 'titular_id', h1, 'quartos', '[]'::jsonb)::text), 'reservar sem nenhum quarto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, jsonb_build_object('filial_id', f1, 'quartos', jsonb_build_array(ci.quarto(u102, '2027-03-10', '2027-03-12')))::text), 'reservar sem titular');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, (hoje - 1)::text, (hoje + 1)::text))::text), 'recepção reserva com entrada no passado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, '2027-03-10', '2027-03-13', 2, 0, 250))::text), 'recepção dá valor acordado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, jsonb_build_object('filial_id', f1, 'titular_id', h1, 'origem', 'pombo', 'quartos', jsonb_build_array(ci.quarto(u102, '2027-03-10', '2027-03-12')))::text), 'origem fora da lista');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, jsonb_build_object('filial_id', f1, 'titular_id', h1, 'situacao', 'hospedada', 'quartos', jsonb_build_array(ci.quarto(u102, '2027-03-10', '2027-03-12')))::text), 'criar a reserva já hospedada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, jsonb_build_object('filial_id', f1, 'titular_id', h1, 'quartos', jsonb_build_array(jsonb_build_object('uh_id', u102, 'tipo_id', t2, 'entrada', '2027-03-10', 'saida', '2027-03-12')))::text), 'tipo informado diferente do tipo da acomodação');

  -- gestão: valor acordado rateado (a sobra vai para a última noite) e data passada
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u102, '2027-03-10', '2027-03-13', 2, 0, 250)));
  racordo := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(f1, h2, ci.quarto(u103, (hoje - 2)::text, (hoje - 1)::text, 2, 0, 100)));
  PERFORM ci.sair();
  ruac := (SELECT id FROM hs_reserva_uhs WHERE reserva_id = racordo);
  PERFORM ci.exige((SELECT array_agg(valor ORDER BY data) = ARRAY[83.33, 83.33, 83.34]::numeric[] AND sum(valor) = 250 AND bool_and(tarifa_id IS NULL) FROM hs_diarias WHERE reserva_uh_id = ruac), 'valor acordado rateado em centavos, sem tarifa');
  rns := (r ->> 'reserva_id')::uuid;
  rune := (SELECT id FROM hs_reserva_uhs WHERE reserva_id = rns);
  PERFORM ci.exige((SELECT entrada = hoje - 2 FROM hs_reserva_uhs WHERE id = rune), 'a gestão registra reserva com data passada');

  -- mais reservas para as próximas etapas
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u103, '2027-03-20', '2027-03-22')));
  r3 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(jsonb_build_object('filial_id', f1, 'titular_id', h2, 'situacao', 'pendente', 'origem', 'telefone',
                                           'quartos', jsonb_build_array(ci.quarto(u201, '2027-03-05', '2027-03-07'))));
  r4 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru3 FROM hs_reserva_uhs WHERE reserva_id = r3;
  SELECT id INTO ru4 FROM hs_reserva_uhs WHERE reserva_id = r4;
  PERFORM ci.exige((SELECT situacao = 'pendente' AND origem = 'telefone' FROM hs_reservas WHERE id = r4), 'reserva pendente de origem telefone');
  PERFORM ci.entrar(vend); PERFORM hs_reserva_confirmar(r4); PERFORM hs_reserva_confirmar(r4); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'confirmada' FROM hs_reservas WHERE id = r4), 'confirmar a reserva pendente (e confirmar de novo não muda nada)');

  -- alterar o quarto: cruzar recusado; preço das noites que continuam é preservado
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, '{"saida":"2027-03-05"}'::jsonb)$c$, ru1), 'esticar a saída para cima de outra reserva');
  PERFORM ci.exige((SELECT periodo = daterange(date '2027-03-01', date '2027-03-04', '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru1), 'a tentativa recusada não mexeu no calendário');
  PERFORM ci.entrar(gest);
  PERFORM hs_tarifa_salvar(jsonb_build_object('id', ta1, 'tipo_id', t1, 'nome', 'Março', 'vigencia_de', '2027-03-01', 'vigencia_ate', '2027-03-31', 'valor_diaria', 120,
                                              'valor_adulto_extra', 40, 'valor_crianca', 20, 'pessoas_incluidas', 2));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT sum(valor) = 200 FROM hs_diarias WHERE reserva_uh_id = ru3), 'mudar a tarifa depois não muda a reserva já feita');
  PERFORM ci.entrar(vend);
  r := hs_reserva_uh_alterar(ru3, '{"saida":"2027-03-23"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 320, 'esticar a saída cota só a noite nova pela tarifa de hoje: 100 + 100 + 120');
  PERFORM ci.exige((SELECT array_agg(valor ORDER BY data) = ARRAY[100, 100, 120]::numeric[] FROM hs_diarias WHERE reserva_uh_id = ru3), 'as noites que continuam mantêm o preço');
  PERFORM ci.exige((SELECT periodo = daterange(date '2027-03-20', date '2027-03-23', '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru3), 'o calendário acompanha a nova saída');
  PERFORM ci.entrar(vend);
  r := hs_reserva_uh_alterar(ru3, '{"entrada":"2027-03-21"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT array_agg(valor ORDER BY data) = ARRAY[100, 120]::numeric[] FROM hs_diarias WHERE reserva_uh_id = ru3) AND (SELECT count(*) = 2 FROM hs_diarias WHERE reserva_uh_id = ru3), 'encurtar pela frente tira a diária que sobrou');
  PERFORM ci.entrar(vend);
  r := hs_reserva_uh_alterar(ru3, '{"entrada":"2027-03-20","adultos":3}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 3 * (120 + 40), 'mudar as pessoas recota todas as noites pela tarifa de hoje');
  PERFORM ci.entrar(gest);
  PERFORM hs_tarifa_salvar(jsonb_build_object('id', ta1, 'tipo_id', t1, 'nome', 'Março', 'vigencia_de', '2027-03-01', 'vigencia_ate', '2027-03-31', 'valor_diaria', 100,
                                              'valor_adulto_extra', 40, 'valor_crianca', 20, 'pessoas_incluidas', 2));
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  r := hs_reserva_uh_alterar(ru3, '{"adultos":2}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 300, 'voltando a 2 adultos com a tarifa de 100: 3 × 100');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, '{"adultos":4}'::jsonb)$c$, ru3), 'alterar acima da capacidade');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, jsonb_build_object('entrada', %L))$c$, ru3, (hoje - 1)::text), 'recepção move a entrada para o passado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, '{"valor_acordado_total":100}'::jsonb)$c$, ru3), 'recepção dá valor acordado ao alterar');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, '{"saida":"2027-03-20"}'::jsonb)$c$, ru3), 'saída igual à entrada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, '{"saida":"2027-06-01"}'::jsonb)$c$, ru3), 'esticar para noites sem tarifa');
  PERFORM ci.exige((SELECT count(*) = 3 AND sum(valor) = 300 FROM hs_diarias WHERE reserva_uh_id = ru3), 'a alteração recusada não deixa a reserva pela metade');
  PERFORM ci.entrar(gest);
  r := hs_reserva_uh_alterar(ru3, '{"valor_acordado_total":250}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 250, 'a gestão passa o quarto para valor acordado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_uh_alterar(%L, '{"saida":"2027-03-24"}'::jsonb)$c$, ru3), 'mudar o número de noites mantendo o acordado sem informar o novo valor');
  PERFORM ci.entrar(gest);
  r := hs_reserva_uh_alterar(ru3, '{"valor_acordado_total":null}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'total')::numeric = 300 AND (SELECT valor_acordado_total IS NULL FROM hs_reserva_uhs WHERE id = ru3), 'voltar para a tarifa recota as noites');

  -- dados da reserva
  PERFORM ci.entrar(vend);
  PERFORM hs_reserva_alterar(r3, jsonb_build_object('titular_id', h2, 'observacoes', ' Chegada tarde ', 'origem', 'whatsapp'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT titular_id = h2 AND observacoes = 'Chegada tarde' AND origem = 'whatsapp' FROM hs_reservas WHERE id = r3), 'alterar titular, origem e observações');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_alterar(%L, jsonb_build_object('titular_id', %L))$c$, r3, gen_random_uuid()), 'titular que não existe');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_alterar(%L, '{"origem":"pombo"}'::jsonb)$c$, r3), 'origem inválida ao alterar');

  -- trocar de acomodação
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_atribuir(%L, %L)$c$, ru2, u201), 'trocar para acomodação ocupada no período');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_atribuir(%L, %L)$c$, ru3, u104), 'trocar para acomodação interditada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_atribuir(%L, %L)$c$, ru3, u301), 'trocar para acomodação de outro hotel');
  PERFORM ci.entrar(vend);
  r := hs_reserva_uh_atribuir(ru3, u102);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT uh_id = u102 FROM hs_reserva_uhs WHERE id = ru3) AND (SELECT uh_id = u102 FROM hs_ocupacoes WHERE reserva_uh_id = ru3) AND (r ->> 'total')::numeric = 300, 'trocar dentro do mesmo tipo mantém o preço');
  PERFORM ci.entrar(vend);
  r := hs_reserva_uh_atribuir(ru3, u102);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean, 'trocar para a mesma acomodação não faz nada');
  PERFORM ci.entrar(vend);
  r := hs_reserva_uh_atribuir(ru3, u201);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tipo_id = t2 FROM hs_reserva_uhs WHERE id = ru3) AND (r ->> 'total')::numeric = 600, 'trocar de tipo recota as noites pelo tipo novo (3 × 200)');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_atribuir(%L, %L, true)$c$, ru3, u102), 'recepção manda manter o preço na troca de tipo');
  PERFORM ci.entrar(gest);
  r := hs_reserva_uh_atribuir(ru3, u102, true);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tipo_id = t1 FROM hs_reserva_uhs WHERE id = ru3) AND (r ->> 'total')::numeric = 600, 'a gestão mantém o preço combinado na troca de tipo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_atribuir(%L, %L)$c$, ru4, u101), 'trocar para a acomodação que a reserva 2 ocupa nas mesmas noites');

  -- cancelar: libera a acomodação, exige motivo e repetir não faz mal
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_cancelar(%L, '')$c$, r2), 'cancelar sem motivo');
  PERFORM ci.entrar(vend);
  r := hs_reserva_cancelar(r2, 'Hóspede desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND motivo_cancelamento = 'Hóspede desistiu' AND cancelada_em IS NOT NULL FROM hs_reservas WHERE id = r2), 'reserva cancelada com motivo e data');
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM hs_reserva_uhs WHERE id = ru2) AND NOT EXISTS (SELECT 1 FROM hs_ocupacoes WHERE reserva_uh_id = ru2), 'cancelar libera a acomodação no calendário');
  PERFORM ci.entrar(vend);
  PERFORM ci.exige(EXISTS (SELECT 1 FROM jsonb_array_elements(hs_uhs_livres(f1, date '2027-03-04', date '2027-03-06')) e WHERE e ->> 'id' = u101::text), 'a acomodação cancelada volta na lista de livres');
  r := hs_reserva_cancelar(r2, 'Outra vez');
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT motivo_cancelamento = 'Hóspede desistiu' FROM hs_reservas WHERE id = r2), 'cancelar de novo não reescreve o motivo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, '{"adultos":1}'::jsonb)$c$, ru2), 'alterar quarto de reserva cancelada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_alterar(%L, '{"observacoes":"x"}'::jsonb)$c$, r2), 'alterar dados de reserva cancelada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_confirmar(%L)$c$, r2), 'confirmar reserva cancelada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_atribuir(%L, %L)$c$, ru2, u102), 'trocar a acomodação de quarto cancelado');
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u101, '2027-03-04', '2027-03-06')));
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'reserva_id')::uuid IS NOT NULL, 'o período liberado pelo cancelamento pode ser vendido de novo');

  -- reserva de dois quartos: cancelar um quarto de cada vez
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u101, '2027-03-25', '2027-03-27'), ci.quarto(u102, '2027-03-25', '2027-03-27')));
  PERFORM ci.sair();
  r5 := (r ->> 'reserva_id')::uuid;
  SELECT min(id::text)::uuid, max(id::text)::uuid INTO ru5a, ru5b FROM hs_reserva_uhs WHERE reserva_id = r5;
  PERFORM ci.exige((r ->> 'quartos')::integer = 2 AND (r ->> 'total')::numeric = 400, 'reserva de dois quartos');
  PERFORM ci.entrar(vend); PERFORM hs_reserva_uh_cancelar(ru5a, 'Um quarto a menos'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'confirmada' FROM hs_reservas WHERE id = r5) AND (SELECT count(*) = 1 FROM hs_ocupacoes WHERE reserva_uh_id IN (ru5a, ru5b)), 'cancelar um dos quartos mantém a reserva');
  PERFORM ci.entrar(vend); PERFORM hs_reserva_uh_cancelar(ru5b, 'O outro também'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' AND motivo_cancelamento = 'O outro também' FROM hs_reservas WHERE id = r5), 'cancelar o último quarto cancela a reserva');

  -- quarto já ocupado (simulado pelo dono do banco; o check-in vem na migration seguinte): nada disso mexe nele
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u103, '2027-03-28', '2027-03-30')));
  PERFORM ci.sair();
  r6 := (r ->> 'reserva_id')::uuid;
  SELECT id INTO ru6 FROM hs_reserva_uhs WHERE reserva_id = r6;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_cancelar(%L, 'x')$c$, ru6), 'motivo de cancelamento curto demais');
  PERFORM ci.exige((SELECT situacao = 'reservada' FROM hs_reserva_uhs WHERE id = ru6), 'o cancelamento recusado não mexeu no quarto');
  UPDATE hs_reserva_uhs SET situacao = 'hospedada' WHERE id = ru6;
  PERFORM _hs_reserva_recalcular(r6);
  PERFORM ci.exige((SELECT situacao = 'hospedada' FROM hs_reservas WHERE id = r6), 'a situação da reserva acompanha o quarto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_cancelar(%L, 'Cancelar hospedado')$c$, r6), 'cancelar reserva com quarto hospedado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_cancelar(%L, 'Cancelar hospedado')$c$, ru6), 'cancelar o quarto hospedado');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_no_show(%L)$c$, ru6), 'não comparecimento de quarto hospedado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_alterar(%L, '{"adultos":1}'::jsonb)$c$, ru6), 'alterar quarto hospedado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_atribuir(%L, %L)$c$, ru6, u102), 'trocar a acomodação de quarto hospedado pela reserva');
  UPDATE hs_reserva_uhs SET situacao = 'reservada' WHERE id = ru6;
  PERFORM _hs_reserva_recalcular(r6);

  -- não comparecimento
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_no_show(%L)$c$, ru1), 'não comparecimento antes do dia da entrada');
  PERFORM ci.entrar(vend);
  r := hs_reserva_no_show(rune);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'no_show' FROM hs_reserva_uhs WHERE id = rune) AND (SELECT situacao = 'no_show' FROM hs_reservas WHERE id = rns) AND NOT EXISTS (SELECT 1 FROM hs_ocupacoes WHERE reserva_uh_id = rune), 'a recepção marca não comparecimento depois do dia da entrada e a acomodação sai do calendário');
  PERFORM ci.entrar(vend); r := hs_reserva_no_show(rune); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean, 'marcar de novo não faz nada');
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(f1, h1, ci.quarto(u103, hoje::text, (hoje + 1)::text, 2, 0, 100)));
  PERFORM ci.sair();
  rhoje := (r ->> 'reserva_id')::uuid;
  SELECT id INTO ruhoje FROM hs_reserva_uhs WHERE reserva_id = rhoje;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_no_show(%L)$c$, ruhoje), 'a recepção marca não comparecimento no próprio dia da entrada');
  PERFORM ci.entrar(gest); PERFORM hs_reserva_no_show(ruhoje); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'no_show' FROM hs_reserva_uhs WHERE id = ruhoje), 'a gestão marca no próprio dia da entrada');

  -- interdição por período
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_uh_interditar(%L, date '2027-05-01', date '2027-05-04', 'Pintura')$c$, u103), 'recepção interdita acomodação');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_interditar(%L, date '2027-05-01', date '2027-05-04', '')$c$, u103), 'interdição sem motivo');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_interditar(%L, date '2027-05-04', date '2027-05-04', 'Pintura')$c$, u103), 'interdição sem noite');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_interditar(%L, date '2020-01-01', date '2020-01-05', 'Pintura')$c$, u103), 'interdição que já acabou');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_interditar(%L, date '2027-03-01', date '2027-03-10', 'Pintura')$c$, u101), 'interditar por cima de reserva');
  PERFORM ci.entrar(gest);
  blq := hs_uh_interditar(u103, date '2027-05-01', date '2027-05-04', 'Pintura');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT origem = 'bloqueio' AND motivo = 'Pintura' AND periodo = daterange(date '2027-05-01', date '2027-05-04', '[)') FROM hs_ocupacoes WHERE id = blq), 'bloqueio no calendário até a data de volta');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_interditar(%L, date '2027-05-03', date '2027-05-06', 'Outra')$c$, u103), 'bloqueio por cima de bloqueio');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u103, '2027-05-02', '2027-05-03', 2, 0, 100))::text), 'reservar acomodação bloqueada');
  PERFORM ci.entrar(vend);
  r := hs_disponibilidade(f1, date '2027-05-01', date '2027-05-02');
  PERFORM ci.sair();
  SELECT e INTO el FROM jsonb_array_elements(r) e WHERE e ->> 'tipo_id' = t1::text;
  PERFORM ci.exige((el ->> 'bloqueadas')::integer = 1 AND (el ->> 'disponiveis')::integer = 2 AND el ->> 'motivo_sem_preco' IS NOT NULL, 'disponibilidade conta o bloqueio e avisa que não há tarifa em maio');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_bloqueio_remover(%L)$c$, blq), 'recepção remove bloqueio');
  PERFORM ci.entrar(gest); PERFORM hs_bloqueio_remover(blq); PERFORM ci.sair();
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM hs_ocupacoes WHERE id = blq), 'a gestão remove o bloqueio');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_bloqueio_remover(%L)$c$, blq), 'remover bloqueio que não existe');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_bloqueio_remover(%L)$c$, (SELECT id FROM hs_ocupacoes WHERE reserva_uh_id = ru1)), 'remover como bloqueio uma ocupação de reserva');

  -- acomodação com reserva a partir de hoje: não troca de tipo, não inativa, não interdita
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('id', %L, 'tipo_id', %L, 'numero', '101'))$c$, u101, t2), 'mudar o tipo da acomodação com reserva futura');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('id', %L, 'tipo_id', %L, 'numero', '101', 'ativo', false))$c$, u101, t1), 'inativar acomodação com reserva futura');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_salvar(jsonb_build_object('id', %L, 'tipo_id', %L, 'numero', '101', 'interditada', true, 'motivo_interdicao', 'Reforma'))$c$, u101, t1), 'interditar acomodação com reserva futura');
  PERFORM ci.entrar(gest);
  PERFORM hs_uh_salvar(jsonb_build_object('id', u104, 'tipo_id', t2, 'numero', '104', 'interditada', true, 'motivo_interdicao', 'Reforma'));
  PERFORM hs_uh_salvar(jsonb_build_object('id', u104, 'tipo_id', t1, 'numero', '104', 'ativo', false));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT NOT ativo FROM hs_uhs WHERE id = u104), 'acomodação sem reserva futura muda de tipo e inativa');

  -- permissões: salão e anônimo
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2027-03-03')$c$, f1, t1), 'garçom cota');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_disponibilidade(%L, date '2027-03-01', date '2027-03-03')$c$, f1), 'garçom consulta disponibilidade');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, '2027-03-10', '2027-03-11', 2, 0, 50))::text), 'garçom reserva');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_reserva_cancelar(%L, 'garçom')$c$, r1), 'garçom cancela');
  PERFORM ci.exige(ci.contar(hgar, 'SELECT count(*) FROM hs_reservas') = 0 AND ci.contar(hgar, 'SELECT count(*) FROM hs_ocupacoes') = 0
                   AND ci.contar(hgar, 'SELECT count(*) FROM hs_diarias') = 0 AND ci.contar(hgar, 'SELECT count(*) FROM hs_reserva_uhs') = 0, 'garçom não lê reservas, ocupações nem diárias');
  PERFORM ci.deve_falhar(NULL, 'SELECT count(*) FROM hs_reservas', 'anônimo lê reservas');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2027-03-03')$c$, f1, t1), 'anônimo cota');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_reserva_cancelar(%L, 'anônimo')$c$, r1), 'anônimo cancela');
  PERFORM ci.deve_falhar(vend, format($c$SELECT _hs_gravar_diarias(%L, false)$c$, ru1), 'usuário chama a rotina interna de diárias');
  PERFORM ci.deve_falhar(vend, format($c$SELECT _hs_precificar(%L, date '2027-03-01', date '2027-03-03', 2, 0)$c$, t1), 'usuário chama a rotina interna de preço');

  -- sem escrita direta nas tabelas, nem pelo administrador
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO hs_reservas (tenant_id, filial_id, numero, titular_id) VALUES (%L, %L, 9999, %L)$c$, demo, f1, h1), 'administrador insere reserva direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_reservas SET situacao = 'cancelada' WHERE id = %L$c$, r1), 'administrador cancela reserva direto');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM hs_reservas WHERE id = %L$c$, r1), 'administrador apaga reserva direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_reserva_uhs SET saida = saida + 1 WHERE id = %L$c$, ru1), 'administrador muda o quarto direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_diarias SET valor = 1 WHERE reserva_uh_id = %L$c$, ru1), 'administrador muda o preço da noite direto');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM hs_ocupacoes WHERE reserva_uh_id = %L$c$, ru1), 'administrador libera o calendário direto');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO hs_ocupacoes (tenant_id, filial_id, uh_id, periodo, origem, motivo) VALUES (%L, %L, %L, daterange(date '2030-01-01', date '2030-01-03', '[)'), 'bloqueio', 'x')$c$, demo, f1, u102), 'administrador bloqueia direto');

  -- restrições do banco, vistas pelo dono
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_reserva_uhs (tenant_id, filial_id, reserva_id, tipo_id, uh_id, entrada, saida) VALUES (%L, %L, %L, %L, %L, '2030-01-01', '2030-01-03')$c$, demo, f1, r1, t1, u301), 'quarto de um hotel com acomodação de outro');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_reserva_uhs (tenant_id, filial_id, reserva_id, tipo_id, uh_id, entrada, saida) VALUES (%L, %L, %L, %L, %L, '2030-01-01', '2030-01-03')$c$, demo, f1, r1, t3, u102), 'quarto de um hotel com tipo de outro');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_reserva_uhs (tenant_id, filial_id, reserva_id, tipo_id, uh_id, entrada, saida) VALUES (%L, %L, %L, %L, %L, '2030-01-03', '2030-01-03')$c$, demo, f1, r1, t1, u102), 'quarto com saída igual à entrada');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_ocupacoes (tenant_id, filial_id, uh_id, periodo, origem, motivo) VALUES (%L, %L, %L, daterange(date '2030-01-03', date '2030-01-03', '[)'), 'bloqueio', 'x')$c$, demo, f1, u102), 'ocupação de período vazio');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_ocupacoes (tenant_id, filial_id, uh_id, periodo, origem) VALUES (%L, %L, %L, daterange(date '2030-01-01', date '2030-01-03', '[)'), 'reserva')$c$, demo, f1, u102), 'ocupação de reserva sem quarto');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_ocupacoes (tenant_id, filial_id, uh_id, periodo, origem) VALUES (%L, %L, %L, daterange(date '2030-01-01', date '2030-01-03', '[)'), 'bloqueio')$c$, demo, f1, u102), 'bloqueio sem motivo');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_ocupacoes (tenant_id, filial_id, uh_id, periodo, origem, motivo) VALUES (%L, %L, %L, daterange(date '2030-01-01', NULL, '[)'), 'bloqueio', 'x')$c$, demo, f1, u102), 'ocupação sem fim');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_diarias (tenant_id, reserva_uh_id, data, valor) VALUES (%L, %L, '2027-03-01', 5)$c$, demo, ru1), 'a mesma noite duas vezes no quarto');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_reservas (tenant_id, filial_id, numero, titular_id) VALUES (%L, %L, (SELECT numero FROM hs_reservas WHERE id = %L), %L)$c$, demo, f1, r1, h1), 'número de reserva repetido na empresa');

  -- quem só acessa um hotel só enxerga as reservas dele
  UPDATE profiles SET filial_id = f2 WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_reservas') = 0 AND ci.contar(vend, 'SELECT count(*) FROM hs_reserva_uhs') = 0
                   AND ci.contar(vend, 'SELECT count(*) FROM hs_diarias') = 0 AND ci.contar(vend, 'SELECT count(*) FROM hs_ocupacoes') = 0, 'recepção do hotel 2 não lê reservas, quartos, diárias nem ocupações do hotel 1');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2027-03-03')$c$, f1, t1), 'recepção do hotel 2 cota no hotel 1');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_cancelar(%L, 'Outro hotel')$c$, r1), 'recepção do hotel 2 cancela reserva do hotel 1');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(u102, '2027-03-10', '2027-03-11'))::text), 'recepção do hotel 2 reserva no hotel 1');
  UPDATE profiles SET filial_id = f1 WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_reservas') > 0 AND ci.contar(vend, 'SELECT count(*) FROM hs_diarias') > 0, 'recepção do hotel 1 lê as reservas do hotel 1');
  UPDATE profiles SET filial_id = NULL WHERE id = vend;

  -- outra empresa: não vê, não usa e não altera
  INSERT INTO tenants (nome) VALUES ('Hotel Reservas B') RETURNING id INTO tb;
  INSERT INTO empresas (tenant_id, razao_social, ramo_atividade) VALUES (tb, 'Hotel Reservas B Ltda', 'hotelaria') RETURNING id INTO eb;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (tb, eb, 'Hotel B Reservas') RETURNING id INTO fb;
  UPDATE profiles SET tenant_id = tb WHERE id = bges;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (bges, tb, 'gestor');
  PERFORM ci.entrar(bges);
  tbx := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fb, 'nome', 'Standard'));
  ubx := hs_uh_salvar(jsonb_build_object('tipo_id', tbx, 'numero', '1'));
  tabx := hs_tarifa_salvar(jsonb_build_object('tipo_id', tbx, 'nome', 'B', 'vigencia_de', '2027-03-01', 'vigencia_ate', '2027-03-31', 'valor_diaria', 70));
  hbx := hs_hospede_salvar('{"nome":"Hóspede Reserva B"}'::jsonb);
  r := hs_reserva_criar(ci.reserva(fb, hbx, ci.quarto(ubx, '2027-03-01', '2027-03-03')));
  PERFORM ci.sair();
  rbx := (r ->> 'reserva_id')::uuid;
  SELECT id INTO rubx FROM hs_reserva_uhs WHERE reserva_id = rbx;
  PERFORM ci.exige((r ->> 'numero')::bigint = 1, 'a numeração de reservas é por empresa');
  PERFORM ci.exige(ci.contar(bges, 'SELECT count(*) FROM hs_reservas') = 1 AND ci.contar(bges, 'SELECT count(*) FROM hs_ocupacoes') = 1, 'o gestor B só lê o que é do hotel B');
  PERFORM ci.exige(ci.contar(gest, format('SELECT count(*) FROM hs_reservas WHERE tenant_id = %L', tb)) = 0 AND ci.contar(gest, format('SELECT count(*) FROM hs_ocupacoes WHERE tenant_id = %L', tb)) = 0
                   AND ci.contar(gest, format('SELECT count(*) FROM hs_diarias WHERE tenant_id = %L', tb)) = 0, 'o gestor A não lê reservas, ocupações nem diárias do hotel B');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_cancelar(%L, 'Invasor')$c$, rbx), 'cancelar reserva de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_uh_cancelar(%L, 'Invasor')$c$, rubx), 'cancelar quarto de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_uh_alterar(%L, '{"adultos":1}'::jsonb)$c$, rubx), 'alterar quarto de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_uh_atribuir(%L, %L)$c$, rubx, u102), 'trocar a acomodação de quarto de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_no_show(%L)$c$, rubx), 'não comparecimento de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_alterar(%L, '{"observacoes":"x"}'::jsonb)$c$, rbx), 'alterar reserva de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_confirmar(%L)$c$, rbx), 'confirmar reserva de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_cotar(%L, %L, date '2027-03-01', date '2027-03-03')$c$, fb, tbx), 'cotar no hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_disponibilidade(%L, date '2027-03-01', date '2027-03-03')$c$, fb), 'disponibilidade do hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uhs_livres(%L, date '2027-03-01', date '2027-03-03')$c$, fb), 'acomodações livres do hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_interditar(%L, date '2027-08-01', date '2027-08-03', 'Invasor')$c$, ubx), 'interditar acomodação de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(fb, h1, ci.quarto(ubx, '2027-03-10', '2027-03-12'))::text), 'reservar no hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, hbx, ci.quarto(u102, '2027-03-10', '2027-03-12'))::text), 'reservar com titular de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_criar(%L::jsonb)$c$, ci.reserva(f1, h1, ci.quarto(ubx, '2027-03-10', '2027-03-12'))::text), 'reservar com acomodação de outra empresa');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_reserva_uhs (tenant_id, filial_id, reserva_id, tipo_id, uh_id, entrada, saida) VALUES (%L, %L, %L, %L, %L, '2030-01-01', '2030-01-03')$c$, demo, f1, rbx, t1, u102), 'quarto de uma empresa na reserva de outra');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_reservas (tenant_id, filial_id, numero, titular_id) VALUES (%L, %L, 9997, %L)$c$, demo, f1, hbx), 'reserva da empresa A com hóspede da empresa B');

  -- limpeza
  DELETE FROM hs_ocupacoes WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_diarias WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_reserva_hospedes WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_reserva_uhs WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_reservas WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_tarifas WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_uhs WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_tipos_uh WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_hospedes WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_config WHERE tenant_id IN (demo, tb);
  DELETE FROM user_roles WHERE user_id IN (hgar, bges);
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant, modulos_sem_cnpj = sem_ant WHERE id = emp;
END $$;

-- 98. Hotelaria (estadia): conta do hóspede com razão que só cresce (estorno), pagamentos pelo caixa do mesmo hotel e sinal, check-in com ficha,
-- fechar o dia sem duplicar, estender, encurtar, trocar de quarto, cancelar e não comparecimento tratando o sinal, permissões e isolamento
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  hgar constant uuid := 'a0000000-0000-0000-0000-0000000002a4';
  bges constant uuid := 'a0000000-0000-0000-0000-0000000002a5';
  hoje date := current_date;
  ramo_ant text; cnae_ant text; cnae2_ant text; sem_ant text[];
  fa uuid; fb2 uuid; tb uuid; eb uuid; fbb uuid;
  tpA uuid; tpB uuid; tpC uuid; tbx uuid;
  a101 uuid; a102 uuid; a103 uuid; a104 uuid; a105 uuid; a106 uuid; a107 uuid; a201 uuid; a301 uuid; c1 uuid; ubx uuid;
  hA uuid; hNo uuid; hC uuid; hD uuid; hbx uuid;
  cxA uuid; cxB uuid; cxbx uuid;
  r jsonb; r1 uuid; r2 uuid; r3 uuid; r5 uuid; r6 uuid; r7 uuid; r8 uuid; r9 uuid; r10 uuid; r11 uuid; r12 uuid; r13 uuid; rf uuid; rp uuid; rs uuid; rbx uuid;
  ru1 uuid; ru2 uuid; ru3 uuid; ru5 uuid; ru6 uuid; ru10a uuid; ru10b uuid; ru11 uuid; ru12 uuid; ru13 uuid; rurf uuid; rurp uuid; rurs uuid; rubx uuid;
  fo1 uuid; fo2 uuid; fx uuid; fo7 uuid; fo8 uuid; fo9 uuid; fo10 uuid; fo11 uuid; fo12 uuid; fo13 uuid; fobx uuid;
  kp1 uuid := 'c0000000-0000-0000-0000-0000000000a1';
  kp2 uuid := 'c0000000-0000-0000-0000-0000000000a2';
  lc uuid; ld uuid; lt uuid; lest uuid; lbx uuid; n bigint; el jsonb; pg uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios, modulos_sem_cnpj INTO ramo_ant, cnae_ant, cnae2_ant, sem_ant FROM empresas WHERE id = emp;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = NULL, cnae_secundarios = NULL, modulos_sem_cnpj = '{}' WHERE id = emp;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'hotelaria');
  INSERT INTO auth.users (id, email) VALUES (hgar, 'garcom-estadia@ci'), (bges, 'gestor-estadia-b@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = hgar;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (hgar, demo, 'garcom');
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Estadia A') RETURNING id INTO fa;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Estadia B') RETURNING id INTO fb2;

  -- cadastro base
  PERFORM ci.entrar(gest);
  tpA := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fa, 'nome', 'Duplo', 'capacidade_adultos', 3, 'capacidade_criancas', 1));
  tpB := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fa, 'nome', 'Suíte', 'capacidade_adultos', 2, 'capacidade_criancas', 0));
  tpC := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fb2, 'nome', 'Duplo', 'capacidade_adultos', 2));
  a101 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '101'));
  a102 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '102'));
  a103 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '103'));
  a104 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '104'));
  a105 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '105'));
  a106 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '106'));
  a107 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '107'));
  a301 := hs_uh_salvar(jsonb_build_object('tipo_id', tpA, 'numero', '301'));
  a201 := hs_uh_salvar(jsonb_build_object('tipo_id', tpB, 'numero', '201'));
  c1 := hs_uh_salvar(jsonb_build_object('tipo_id', tpC, 'numero', 'C1'));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpA, 'nome', 'Base', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 120)::text, 'valor_diaria', 100,
                                              'valor_adulto_extra', 40, 'valor_crianca', 20, 'pessoas_incluidas', 2));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpB, 'nome', 'Base suíte', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 120)::text, 'valor_diaria', 200));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpC, 'nome', 'Base hotel B', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 120)::text, 'valor_diaria', 80));
  PERFORM hs_config_salvar(fa, '{"taxa_turismo_por_hospede_noite":"5"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  hA := hs_hospede_salvar('{"nome":"Hóspede Estadia A","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb);
  hNo := hs_hospede_salvar('{"nome":"Hóspede Sem Documento"}'::jsonb);
  hC := hs_hospede_salvar('{"nome":"Acompanhante C"}'::jsonb);
  hD := hs_hospede_salvar('{"nome":"Acompanhante D"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(adm);
  cxA := abrir_caixa(fa, 0);
  cxB := abrir_caixa(fb2, 0);
  PERFORM ci.sair();

  -- ===== reservas usadas nos testes =====
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a101, hoje::text, (hoje + 3)::text)));       r1 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fa, hNo, ci.quarto(a102, hoje::text, (hoje + 2)::text)));      r2 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a101, (hoje + 5)::text, (hoje + 7)::text))); r6 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a105, (hoje + 1)::text, (hoje + 3)::text))); rf := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(jsonb_build_object('filial_id', fa, 'titular_id', hA, 'situacao', 'pendente', 'quartos', jsonb_build_array(ci.quarto(a106, hoje::text, (hoje + 1)::text))));
  rp := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a301, hoje::text, (hoje + 1)::text)));       rs := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a103, (hoje - 1)::text, (hoje + 2)::text, 1))); r3 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru1 FROM hs_reserva_uhs WHERE reserva_id = r1;   SELECT id INTO ru2 FROM hs_reserva_uhs WHERE reserva_id = r2;
  SELECT id INTO ru3 FROM hs_reserva_uhs WHERE reserva_id = r3;   SELECT id INTO ru6 FROM hs_reserva_uhs WHERE reserva_id = r6;
  SELECT id INTO rurf FROM hs_reserva_uhs WHERE reserva_id = rf;  SELECT id INTO rurp FROM hs_reserva_uhs WHERE reserva_id = rp;
  SELECT id INTO rurs FROM hs_reserva_uhs WHERE reserva_id = rs;

  -- ===== conta e sinal antes do check-in =====
  PERFORM ci.entrar(vend);
  fo1 := hs_folio_principal(r1);
  PERFORM ci.sair();
  PERFORM ci.exige(fo1 = (SELECT id FROM hs_folios WHERE reserva_id = r1 AND principal) AND (SELECT count(*) FROM hs_folios WHERE reserva_id = r1) = 1, 'a conta principal é criada uma vez por reserva');
  PERFORM ci.entrar(vend); PERFORM ci.exige(hs_folio_principal(r1) = fo1, 'pedir a conta principal de novo devolve a mesma'); PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  r := hs_pagamento_registrar(fo1, 'pix', 100, cxA, 'sinal', kp1);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'saldo')::numeric = -100 AND NOT (r ->> 'repetido')::boolean, 'sinal de 100 deixa a conta com crédito de 100');
  pg := (r ->> 'pagamento_id')::uuid;
  PERFORM ci.entrar(vend); r := hs_pagamento_registrar(fo1, 'pix', 100, cxA, 'sinal', kp1); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (r ->> 'pagamento_id')::uuid = pg AND (SELECT count(*) FROM hs_pagamentos WHERE folio_id = fo1) = 1, 'repetir o sinal com a mesma chave não recebe duas vezes');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(valor) = 100 FROM caixa_movimentos WHERE caixa_id = cxA AND tipo = 'venda' AND forma_pagamento = 'pix'), 'o sinal entrou uma vez no caixa do hotel');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'crediario', 10, %L, 'sinal')$c$, fo1, cxA), 'sinal em crediário');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 0, %L, 'sinal')$c$, fo1, cxA), 'sinal de valor zero');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 10, %L, 'sinal')$c$, fo1, cxB), 'sinal no caixa de outro hotel');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 10, %L, 'xyz')$c$, fo1, cxA), 'tipo de pagamento inventado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 10, %L, 'pagamento')$c$, fo1, cxA), 'pagamento em conta que ainda não deve nada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 10, %L, 'devolucao')$c$, fo1, cxA), 'recepção faz devolução');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 10, gen_random_uuid(), 'sinal')$c$, fo1), 'caixa que não existe');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 10, %L, 'sinal')$c$, fo1, cxA), 'garçom recebe sinal');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 10, %L, 'sinal')$c$, fo1, cxA), 'anônimo recebe sinal');

  -- ===== check-in =====
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L)$c$, ru2), 'check-in de titular sem documento');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L)$c$, rurf), 'check-in antes do dia da entrada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L)$c$, rurp), 'check-in de reserva pendente');
  UPDATE hs_uhs SET situacao_limpeza = 'sujo' WHERE id = a301;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L)$c$, rurs), 'check-in em acomodação suja');
  UPDATE hs_uhs SET situacao_limpeza = 'limpo' WHERE id = a301;
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_checkin(%L)$c$, ru1), 'garçom faz check-in');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L, ARRAY[%L, %L]::uuid[])$c$, ru1, hC, hD), 'check-in com mais pessoas que a reserva');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L, ARRAY[gen_random_uuid()]::uuid[])$c$, ru1), 'acompanhante que não existe');
  PERFORM ci.exige((SELECT situacao = 'reservada' FROM hs_reserva_uhs WHERE id = ru1) AND NOT EXISTS (SELECT 1 FROM hs_reserva_hospedes WHERE reserva_uh_id = ru1), 'o check-in recusado não deixou nada gravado');
  PERFORM ci.entrar(vend);
  r := hs_checkin(ru1, ARRAY[hC]);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'repetido')::boolean AND (r ->> 'folio_id')::uuid = fo1 AND (r ->> 'uh') = '101' AND jsonb_array_length(r -> 'hospedes') = 2, 'check-in devolve a ficha com os dois hóspedes e a conta principal');
  PERFORM ci.exige((r -> 'hospedes' -> 0 ->> 'principal')::boolean AND (r -> 'hospedes' -> 0 ->> 'documento_numero') = '52998224725', 'o titular vem primeiro na ficha, com o documento');
  PERFORM ci.exige((SELECT situacao = 'hospedada' AND checkin_em IS NOT NULL FROM hs_reserva_uhs WHERE id = ru1) AND (SELECT situacao = 'hospedada' FROM hs_reservas WHERE id = r1), 'quarto e reserva ficam hospedados');
  PERFORM ci.entrar(vend); r := hs_checkin(ru1, ARRAY[hC]); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) = 2 FROM hs_reserva_hospedes WHERE reserva_uh_id = ru1), 'repetir o check-in devolve a mesma ficha');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_hospede_adicionar(%L, %L)$c$, ru1, hD), 'acompanhante além das pessoas da reserva');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_hospede_remover(%L, %L)$c$, ru1, hA), 'tirar o hóspede principal do quarto');
  PERFORM ci.entrar(vend); PERFORM hs_reserva_hospede_remover(ru1, hC); PERFORM hs_reserva_hospede_adicionar(ru1, hD); PERFORM hs_reserva_hospede_adicionar(ru1, hD); PERFORM ci.sair();
  PERFORM ci.exige((SELECT array_agg(hospede_id ORDER BY principal DESC) = ARRAY[hA, hD] FROM hs_reserva_hospedes WHERE reserva_uh_id = ru1), 'trocar o acompanhante do quarto (adicionar de novo não duplica)');
  PERFORM ci.entrar(vend);
  PERFORM hs_hospede_salvar(jsonb_build_object('id', hNo, 'nome', 'Hóspede Sem Documento', 'documento_tipo', 'passaporte', 'documento_numero', 'XX123456'));
  r := hs_checkin(ru2);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'hospedada' FROM hs_reserva_uhs WHERE id = ru2), 'com o documento informado o check-in passa');
  PERFORM ci.entrar(vend); r := hs_checkin(ru3); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'hospedada' FROM hs_reserva_uhs WHERE id = ru3), 'chegada atrasada (entrada ontem) faz check-in hoje');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L)$c$, ru6), 'check-in de reserva que só chega daqui a cinco dias');

  -- ===== fechar o dia =====
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_auditoria_noturna(%L)$c$, fa), 'garçom fecha o dia');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_auditoria_noturna(%L, %L)$c$, fa, hoje + 1), 'fechar um dia que ainda não chegou');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_auditoria_noturna(%L, %L)$c$, fa, hoje - 40), 'fechar um dia de mais de 31 dias atrás');
  PERFORM ci.entrar(vend);
  r := hs_auditoria_noturna(fa);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'quartos')::integer = 3 AND (r ->> 'total_lancado')::numeric = 320, 'fechar o dia lança 3 quartos: diária + taxa de turismo por hóspede (110 + 105 + 105)');
  PERFORM ci.exige((SELECT count(*) = 6 FROM hs_lancamentos WHERE tenant_id = demo AND filial_id = fa), 'seis lançamentos: uma diária e uma taxa por quarto');
  PERFORM ci.exige((SELECT sum(total) = 110 FROM hs_lancamentos WHERE folio_id = fo1), 'a conta do quarto 101 tem diária de 100 e taxa de 2 hóspedes (10)');
  PERFORM ci.exige((SELECT bool_and(lancada) FROM hs_diarias WHERE reserva_uh_id = ru1 AND data = hoje) AND (SELECT NOT lancada FROM hs_diarias WHERE reserva_uh_id = ru3 AND data = hoje - 1), 'a noite lançada fica marcada; a anterior ao check-in atrasado não é lançada');
  PERFORM ci.entrar(vend); r := hs_auditoria_noturna(fa); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'quartos')::integer = 0 AND (r ->> 'total_lancado')::numeric = 0 AND (SELECT count(*) = 6 FROM hs_lancamentos WHERE tenant_id = demo AND filial_id = fa), 'fechar o dia de novo não duplica nada');
  PERFORM ci.exige(jsonb_array_length(r -> 'chegadas_pendentes') >= 2 AND EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'chegadas_pendentes') e WHERE (e ->> 'reserva_uh_id')::uuid = rurp), 'chegadas que não vieram aparecem para decisão');
  PERFORM ci.exige(jsonb_array_length(r -> 'saidas_atrasadas') = 0, 'sem saídas atrasadas');
  -- saída atrasada (simulada pelo dono do banco): aparece e não é cobrada
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a107, (hoje - 3)::text, (hoje - 1)::text)));
  PERFORM ci.sair();
  r5 := (r ->> 'reserva_id')::uuid; SELECT id INTO ru5 FROM hs_reserva_uhs WHERE reserva_id = r5;
  UPDATE hs_reserva_uhs SET situacao = 'hospedada', checkin_em = now() - interval '3 days' WHERE id = ru5;
  PERFORM _hs_reserva_recalcular(r5);
  PERFORM ci.entrar(vend); r := hs_auditoria_noturna(fa); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'quartos')::integer = 0 AND EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'saidas_atrasadas') e WHERE (e ->> 'reserva_uh_id')::uuid = ru5), 'saída atrasada aparece e não gera diária');
  UPDATE hs_reserva_uhs SET situacao = 'finalizada' WHERE id = ru5;
  PERFORM _hs_reserva_recalcular(r5);

  -- ===== lançamentos e estornos =====
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = 10)::int', fo1)) = 1, 'saldo da conta: 110 lançados − 100 de sinal = 10');
  PERFORM ci.entrar(vend);
  lc := hs_lancar(fo1, '{"tipo":"consumo","descricao":" Frigobar ","quantidade":2,"valor_unitario":7.5}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT total = 15 AND descricao = 'Frigobar' AND tipo = 'consumo' AND criado_por = vend FROM hs_lancamentos WHERE id = lc), 'consumo de 2 × 7,50 vira um lançamento de 15');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"ajuste","descricao":"x","valor_unitario":-5}'::jsonb)$c$, fo1), 'recepção dá ajuste');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"x","valor_unitario":-5}'::jsonb)$c$, fo1), 'consumo com valor negativo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":" ","valor_unitario":5}'::jsonb)$c$, fo1), 'lançamento sem descrição');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"diaria","descricao":"x","valor_unitario":5}'::jsonb)$c$, fo1), 'diária lançada à mão');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"x","valor_unitario":5,"quantidade":0}'::jsonb)$c$, fo1), 'quantidade zero');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"x"}'::jsonb)$c$, fo1), 'lançamento sem valor');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, jsonb_build_object('tipo','consumo','descricao','x','valor_unitario',5,'reserva_uh_id',%L))$c$, fo1, ru2), 'lançar para o quarto de outra reserva');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, jsonb_build_object('tipo','consumo','descricao','x','valor_unitario',5,'produto_id',gen_random_uuid()))$c$, fo1), 'produto que não existe');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"x","valor_unitario":5}'::jsonb)$c$, fo1), 'garçom lança na conta');
  PERFORM ci.entrar(gest);
  PERFORM hs_lancar(fo1, '{"tipo":"ajuste","descricao":"Cortesia da gerência","valor_unitario":-10}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = 15)::int', fo1)) = 1, 'com consumo (+15) e desconto da gestão (−10) o saldo é 15');
  PERFORM ci.exige((SELECT count(*) = 1 FROM auditoria WHERE entidade = 'hs_lancamentos' AND operacao = 'ajuste' AND tenant_id = demo), 'o ajuste da gestão fica na auditoria');
  SELECT id INTO ld FROM hs_lancamentos WHERE folio_id = fo1 AND tipo = 'diaria';
  SELECT id INTO lt FROM hs_lancamentos WHERE folio_id = fo1 AND tipo = 'taxa_turismo';
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_estornar(%L, 'Lançado errado')$c$, ld), 'recepção estorna diária');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_estornar(%L, 'Lançado errado')$c$, lt), 'recepção estorna taxa de turismo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_estornar(%L, 'ab')$c$, lc), 'estorno com motivo curto');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_lancamento_estornar(%L, 'Lançado errado')$c$, lc), 'garçom estorna');
  PERFORM ci.entrar(vend); r := hs_lancamento_estornar(lc, 'Lançado errado'); PERFORM ci.sair();
  lest := (r ->> 'estorno_id')::uuid;
  PERFORM ci.exige((SELECT total = -15 AND valor_unitario = -7.5 AND estorna_id = lc AND tipo = 'consumo' FROM hs_lancamentos WHERE id = lest) AND (SELECT total = 15 FROM hs_lancamentos WHERE id = lc), 'o estorno é uma linha de sinal oposto e o original não muda');
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = 0)::int', fo1)) = 1, 'com o consumo estornado o saldo volta a 0');
  PERFORM ci.entrar(vend); r := hs_lancamento_estornar(lc, 'Outra vez'); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) = 1 FROM hs_lancamentos WHERE estorna_id = lc), 'estornar de novo não cria outra linha');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_estornar(%L, 'Estorno do estorno')$c$, lest), 'estornar um estorno');
  PERFORM ci.entrar(gest); PERFORM hs_lancamento_estornar(lt, 'Hóspede isento da taxa'); PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = -10)::int', fo1)) = 1, 'a gestão estorna a taxa de turismo: saldo −10');
  PERFORM ci.exige((SELECT count(*) = 1 FROM auditoria WHERE entidade = 'hs_lancamentos' AND operacao = 'estorno' AND entidade_id = lt), 'o estorno da gestão fica na auditoria');
  PERFORM ci.entrar(vend); r := hs_auditoria_noturna(fa); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'quartos')::integer = 0 AND (SELECT count(*) = 10 FROM hs_lancamentos WHERE tenant_id = demo AND filial_id = fa), 'fechar o dia depois do estorno não lança a taxa estornada de novo');

  -- ===== pagamento e devolução =====
  PERFORM ci.entrar(vend); PERFORM hs_lancar(fo1, '{"tipo":"servico","descricao":"Lavanderia","valor_unitario":60}'::jsonb); PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'dinheiro', 80, %L)$c$, fo1, cxA), 'pagamento maior que o saldo');
  PERFORM ci.entrar(vend); r := hs_pagamento_registrar(fo1, 'dinheiro', 50, cxA); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'saldo')::numeric = 0, 'pagar o saldo (50) zera a conta');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'dinheiro', 20, %L, 'devolucao')$c$, fo1, cxA), 'recepção devolve dinheiro');
  PERFORM ci.entrar(gest); r := hs_pagamento_registrar(fo1, 'dinheiro', 20, cxA, 'devolucao'); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'saldo')::numeric = 20, 'a gestão devolve 20: a conta volta a dever 20');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(valor) = 20 FROM caixa_movimentos WHERE caixa_id = cxA AND tipo = 'saida'), 'a devolução saiu do caixa');
  PERFORM ci.exige((SELECT count(*) = 1 FROM auditoria WHERE entidade = 'hs_folios' AND operacao = 'devolucao' AND entidade_id = fo1), 'a devolução fica na auditoria');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_pagamento_registrar(%L, 'dinheiro', 500, %L, 'devolucao')$c$, fo1, cxA), 'devolver mais do que foi recebido');

  -- ===== separar contas =====
  PERFORM ci.entrar(vend); fo2 := hs_folio_principal(r2); fx := hs_folio_abrir(r1, 'Empresa'); PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_folio_abrir(%L, ' empresa ')$c$, r1), 'conta extra com nome repetido');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_folio_abrir(%L, ' ')$c$, r1), 'conta extra sem nome');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_transferir(ARRAY[%L]::uuid[], %L)$c$, lest, fx), 'transferir só o estorno');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_transferir(ARRAY[%L]::uuid[], %L)$c$, ld, fo2), 'transferir para a conta de outra reserva');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_transferir('{}'::uuid[], %L)$c$, fx), 'transferir nada');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_lancamento_transferir(ARRAY[%L]::uuid[], %L)$c$, ld, fx), 'garçom transfere');
  PERFORM ci.entrar(vend); n := hs_lancamento_transferir(ARRAY[ld, lt], fx); PERFORM ci.sair();
  PERFORM ci.exige(n = 2, 'transferiu a diária e a taxa');
  PERFORM ci.exige((SELECT folio_id = fx FROM hs_lancamentos WHERE estorna_id = lt), 'o estorno da taxa foi junto com ela');
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = 100)::int', fx)) = 1, 'a conta da empresa: diária 100 + taxa 10 − estorno 10');
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = -80)::int', fo1)) = 1, 'a conta principal ficou com crédito de 80');
  PERFORM ci.exige((SELECT count(*) = 1 FROM auditoria WHERE entidade = 'hs_lancamentos' AND operacao = 'transferencia' AND entidade_id = ld), 'a transferência fica na auditoria');
  PERFORM ci.entrar(vend); n := hs_lancamento_transferir(ARRAY[ld], fx); PERFORM ci.sair();
  PERFORM ci.exige(n = 0, 'transferir para a conta onde já está não faz nada');

  -- ===== estender e encurtar =====
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_estender(%L, %L)$c$, ru1, hoje + 3), 'estender para a mesma saída');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_estender(%L, %L)$c$, ru6, hoje + 9), 'estender quarto que ainda não fez check-in');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_estender(%L, %L)$c$, ru1, hoje + 6), 'estender por cima da reserva seguinte');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_estender(%L, %L, 150)$c$, ru1, hoje + 5), 'recepção combina o valor das noites novas');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_estadia_estender(%L, %L)$c$, ru1, hoje + 5), 'garçom estende');
  PERFORM ci.exige((SELECT periodo = daterange(hoje, hoje + 3, '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru1) AND (SELECT count(*) = 3 FROM hs_diarias WHERE reserva_uh_id = ru1), 'a tentativa recusada não mexeu no calendário nem nas diárias');
  PERFORM ci.entrar(vend); r := hs_estadia_estender(ru1, hoje + 5); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'noites_novas')::integer = 2 AND (r ->> 'valor_novas_noites')::numeric = 200 AND (SELECT saida = hoje + 5 FROM hs_reserva_uhs WHERE id = ru1), 'estender encosta na reserva seguinte: 2 noites novas de 100');
  PERFORM ci.exige((SELECT periodo = daterange(hoje, hoje + 5, '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru1) AND (SELECT count(*) = 5 AND count(*) FILTER (WHERE lancada) = 1 FROM hs_diarias WHERE reserva_uh_id = ru1), 'o calendário acompanha e a noite lançada continua lançada');
  PERFORM ci.entrar(gest); r := hs_estadia_estender(ru3, hoje + 4, 150); PERFORM ci.sair();
  PERFORM ci.exige((SELECT array_agg(valor ORDER BY data) FILTER (WHERE data >= hoje + 2) = ARRAY[75, 75]::numeric[] FROM hs_diarias WHERE reserva_uh_id = ru3), 'a gestão combina 150 para as 2 noites novas: 75 + 75');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_encurtar(%L, %L)$c$, ru1, hoje + 5), 'encurtar para a mesma saída');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_encurtar(%L, %L)$c$, ru1, hoje), 'encurtar até a data da entrada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_encurtar(%L, %L)$c$, ru3, hoje), 'encurtar cortando uma noite já lançada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_encurtar(%L, %L)$c$, ru6, hoje + 6), 'encurtar quarto que ainda não fez check-in');
  PERFORM ci.entrar(vend); r := hs_estadia_encurtar(ru1, hoje + 4); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'noites_removidas')::integer = 1 AND (SELECT periodo = daterange(hoje, hoje + 4, '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru1) AND (SELECT count(*) = 4 FROM hs_diarias WHERE reserva_uh_id = ru1), 'encurtar tira a última noite e libera o dia no calendário');
  PERFORM ci.entrar(gest); r := hs_estadia_encurtar(ru3, hoje + 3); PERFORM ci.sair();
  PERFORM ci.exige((SELECT saida = hoje + 3 FROM hs_reserva_uhs WHERE id = ru3) AND (SELECT count(*) = 4 FROM hs_diarias WHERE reserva_uh_id = ru3), 'encurtar a estadia da chegada atrasada');

  -- ===== trocar de quarto no meio da estadia =====
  UPDATE hs_uhs SET situacao_limpeza = 'sujo' WHERE id = a301;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_trocar_uh(%L, %L, 'Barulho no quarto')$c$, ru2, a301), 'trocar para acomodação suja');
  UPDATE hs_uhs SET situacao_limpeza = 'limpo' WHERE id = a301;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_trocar_uh(%L, %L, 'Barulho no quarto')$c$, ru2, a101), 'trocar para acomodação ocupada por outro hóspede');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_trocar_uh(%L, %L, 'x')$c$, ru2, a201), 'trocar de quarto sem motivo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_trocar_uh(%L, %L, 'Barulho no quarto', true)$c$, ru2, a201), 'recepção manda manter o preço');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_trocar_uh(%L, %L, 'Barulho no quarto')$c$, ru6, a201), 'trocar quarto que ainda não fez check-in');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_estadia_trocar_uh(%L, %L, 'Barulho no quarto')$c$, ru2, a201), 'garçom troca o quarto');
  PERFORM ci.entrar(vend); r := hs_estadia_trocar_uh(ru2, a201, 'Barulho no quarto'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT uh_id = a201 AND tipo_id = tpB FROM hs_reserva_uhs WHERE id = ru2) AND (SELECT situacao_limpeza = 'sujo' FROM hs_uhs WHERE id = a102), 'trocou para a suíte e a acomodação antiga ficou suja');
  PERFORM ci.exige((SELECT count(*) = 1 AND bool_and(uh_id = a201) FROM hs_ocupacoes WHERE reserva_uh_id = ru2), 'trocar no dia do check-in só muda a acomodação no calendário');
  PERFORM ci.exige((SELECT array_agg(valor ORDER BY data) = ARRAY[100, 200]::numeric[] FROM hs_diarias WHERE reserva_uh_id = ru2), 'a noite lançada fica com o preço antigo e a seguinte passa a valer pela suíte');
  PERFORM ci.entrar(vend); r := hs_estadia_trocar_uh(ru2, a201, 'Barulho no quarto'); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean, 'trocar para a mesma acomodação não faz nada');
  PERFORM ci.entrar(vend); r := hs_estadia_trocar_uh(ru3, a104, 'Ar-condicionado quebrado'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT count(*) = 2 FROM hs_ocupacoes WHERE reserva_uh_id = ru3)
                   AND EXISTS (SELECT 1 FROM hs_ocupacoes WHERE reserva_uh_id = ru3 AND uh_id = a103 AND periodo = daterange(hoje - 1, hoje, '[)'))
                   AND EXISTS (SELECT 1 FROM hs_ocupacoes WHERE reserva_uh_id = ru3 AND uh_id = a104 AND periodo = daterange(hoje, hoje + 3, '[)')), 'trocar no meio da estadia divide o calendário: a antiga até hoje e a nova até a saída');
  PERFORM ci.exige((SELECT situacao_limpeza = 'sujo' FROM hs_uhs WHERE id = a103) AND (SELECT count(*) = 4 AND sum(valor) = 375 FROM hs_diarias WHERE reserva_uh_id = ru3), 'a troca dentro do mesmo tipo não mexe nos preços');
  PERFORM ci.exige((SELECT count(*) = 2 FROM auditoria WHERE entidade = 'hs_reserva_uhs' AND operacao = 'troca_de_quarto'), 'as duas trocas ficam na auditoria');
  UPDATE hs_uhs SET situacao_limpeza = 'limpo' WHERE id = a102;
  PERFORM ci.entrar(gest);
  r := hs_estadia_trocar_uh(ru2, a102, 'Voltou ao quarto de origem', true);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT tipo_id = tpA AND uh_id = a102 FROM hs_reserva_uhs WHERE id = ru2) AND (SELECT array_agg(valor ORDER BY data) = ARRAY[100, 200]::numeric[] FROM hs_diarias WHERE reserva_uh_id = ru2), 'a gestão troca de tipo mantendo o preço combinado');

  -- ===== cancelar com sinal =====
  -- R7: sinal devolvido
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a105, (hoje + 10)::text, (hoje + 12)::text))); r7 := (r ->> 'reserva_id')::uuid;
  fo7 := hs_folio_principal(r7);
  PERFORM hs_pagamento_registrar(fo7, 'pix', 80, cxA, 'sinal');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_cancelar(%L, 'Desistência')$c$, r7), 'cancelar com sinal sem informar o caixa para devolver');
  PERFORM ci.exige((SELECT situacao = 'confirmada' FROM hs_reservas WHERE id = r7) AND EXISTS (SELECT 1 FROM hs_ocupacoes o JOIN hs_reserva_uhs u ON u.id = o.reserva_uh_id WHERE u.reserva_id = r7), 'o cancelamento recusado não mexeu na reserva');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_cancelar(%L, 'Desistência', true, %L, 'pix')$c$, r7, cxB), 'devolver o sinal pelo caixa de outro hotel');
  PERFORM ci.entrar(vend); PERFORM hs_reserva_cancelar(r7, 'Desistência', true, cxA, 'pix'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM hs_reservas WHERE id = r7) AND (SELECT situacao = 'fechado' AND fechado_em IS NOT NULL FROM hs_folios WHERE id = fo7), 'cancelar com devolução fecha a conta');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(valor) = 80 FROM hs_pagamentos WHERE folio_id = fo7 AND tipo = 'devolucao') AND (SELECT count(*) = 1 AND sum(valor) = 80 FROM caixa_movimentos WHERE caixa_id = cxA AND tipo = 'saida' AND valor = 80), 'a devolução do sinal saiu do caixa uma vez');
  PERFORM ci.entrar(vend); r := hs_reserva_cancelar(r7, 'Outra vez', true, cxA, 'pix'); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND (SELECT count(*) = 1 FROM hs_pagamentos WHERE folio_id = fo7 AND tipo = 'devolucao'), 'cancelar de novo não devolve outra vez');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"x","valor_unitario":5}'::jsonb)$c$, fo7), 'lançar em conta fechada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 5, %L, 'sinal')$c$, fo7, cxA), 'receber em conta fechada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_folio_abrir(%L, 'Outra')$c$, r7), 'abrir conta em reserva cancelada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_folio_principal(%L)$c$, (SELECT id FROM hs_reservas WHERE id = r7 AND false)), 'conta principal sem reserva');
  -- R8: sinal retido (só a gestão)
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a105, (hoje + 20)::text, (hoje + 22)::text))); r8 := (r ->> 'reserva_id')::uuid;
  fo8 := hs_folio_principal(r8);
  PERFORM hs_pagamento_registrar(fo8, 'dinheiro', 60, cxA, 'sinal');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_cancelar(%L, 'Cancelou em cima da hora', false)$c$, r8), 'recepção retém o sinal');
  PERFORM ci.entrar(gest); PERFORM hs_reserva_cancelar(r8, 'Cancelou em cima da hora', false); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'fechado' FROM hs_folios WHERE id = fo8) AND (SELECT count(*) = 1 AND sum(total) = 60 FROM hs_lancamentos WHERE folio_id = fo8 AND tipo = 'servico' AND descricao LIKE 'Sinal retido%')
                   AND NOT EXISTS (SELECT 1 FROM hs_pagamentos WHERE folio_id = fo8 AND tipo = 'devolucao'), 'a gestão retém o sinal: vira receita na própria conta e a conta fecha');
  PERFORM ci.exige((SELECT count(*) = 1 FROM auditoria WHERE entidade = 'hs_folios' AND operacao = 'retencao_sinal' AND entidade_id = fo8), 'reter o sinal fica na auditoria');
  -- R9: cancelamento que falha no meio não deixa nada pela metade
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a105, (hoje + 30)::text, (hoje + 32)::text))); r9 := (r ->> 'reserva_id')::uuid;
  fo9 := hs_folio_principal(r9);
  PERFORM hs_pagamento_registrar(fo9, 'pix', 50, cxA, 'sinal');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_cancelar(%L, 'Teste de falha', true, %L, 'pix')$c$, r9, cxB), 'cancelar devolvendo por caixa de outro hotel');
  PERFORM ci.exige((SELECT situacao = 'confirmada' FROM hs_reservas WHERE id = r9) AND (SELECT situacao = 'aberto' FROM hs_folios WHERE id = fo9)
                   AND EXISTS (SELECT 1 FROM hs_ocupacoes o JOIN hs_reserva_uhs u ON u.id = o.reserva_uh_id WHERE u.reserva_id = r9), 'a falha na devolução desfaz o cancelamento inteiro');
  -- R10: dois quartos, o sinal só é tratado quando a reserva inteira acaba
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a105, (hoje + 40)::text, (hoje + 42)::text), ci.quarto(a106, (hoje + 40)::text, (hoje + 42)::text))); r10 := (r ->> 'reserva_id')::uuid;
  fo10 := hs_folio_principal(r10);
  PERFORM hs_pagamento_registrar(fo10, 'pix', 100, cxA, 'sinal');
  PERFORM ci.sair();
  SELECT min(id::text)::uuid, max(id::text)::uuid INTO ru10a, ru10b FROM hs_reserva_uhs WHERE reserva_id = r10;
  PERFORM ci.entrar(vend); PERFORM hs_reserva_uh_cancelar(ru10a, 'Um quarto a menos'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'confirmada' FROM hs_reservas WHERE id = r10) AND (SELECT situacao = 'aberto' FROM hs_folios WHERE id = fo10) AND NOT EXISTS (SELECT 1 FROM hs_pagamentos WHERE folio_id = fo10 AND tipo = 'devolucao'), 'cancelar um dos dois quartos não mexe no sinal');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_uh_cancelar(%L, 'O outro também')$c$, ru10b), 'cancelar o último quarto sem informar o caixa para devolver o sinal');
  PERFORM ci.entrar(vend); PERFORM hs_reserva_uh_cancelar(ru10b, 'O outro também', true, cxA, 'pix'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelada' FROM hs_reservas WHERE id = r10) AND (SELECT situacao = 'fechado' FROM hs_folios WHERE id = fo10) AND (SELECT sum(valor) = 100 FROM hs_pagamentos WHERE folio_id = fo10 AND tipo = 'devolucao'), 'cancelar o último quarto devolve o sinal e fecha a conta');

  -- ===== não comparecimento com sinal =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a106, (hoje - 1)::text, hoje::text)));       r11 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a106, (hoje - 3)::text, (hoje - 2)::text))); r12 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fa, hA, ci.quarto(a106, (hoje - 5)::text, (hoje - 4)::text))); r13 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru11 FROM hs_reserva_uhs WHERE reserva_id = r11; SELECT id INTO ru12 FROM hs_reserva_uhs WHERE reserva_id = r12; SELECT id INTO ru13 FROM hs_reserva_uhs WHERE reserva_id = r13;
  PERFORM ci.entrar(vend);
  fo11 := hs_folio_principal(r11); fo12 := hs_folio_principal(r12); fo13 := hs_folio_principal(r13);
  PERFORM hs_pagamento_registrar(fo11, 'pix', 70, cxA, 'sinal'); PERFORM hs_pagamento_registrar(fo12, 'dinheiro', 40, cxA, 'sinal'); PERFORM hs_pagamento_registrar(fo13, 'pix', 30, cxA, 'sinal');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_no_show(%L)$c$, ru11), 'recepção marca não comparecimento retendo o sinal');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_no_show(%L, true, true, %L, 'dinheiro')$c$, ru12, cxA), 'recepção cobra a diária do não comparecimento');
  PERFORM ci.exige((SELECT situacao = 'reservada' FROM hs_reserva_uhs WHERE id = ru11) AND (SELECT situacao = 'reservada' FROM hs_reserva_uhs WHERE id = ru12), 'os não comparecimentos recusados não mexeram nos quartos');
  PERFORM ci.entrar(vend); PERFORM hs_reserva_no_show(ru12, false, true, cxA, 'dinheiro'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'no_show' FROM hs_reservas WHERE id = r12) AND (SELECT situacao = 'fechado' FROM hs_folios WHERE id = fo12) AND (SELECT sum(valor) = 40 FROM hs_pagamentos WHERE folio_id = fo12 AND tipo = 'devolucao'), 'a recepção marca o não comparecimento devolvendo o sinal');
  PERFORM ci.entrar(gest); PERFORM hs_reserva_no_show(ru13); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'fechado' FROM hs_folios WHERE id = fo13) AND (SELECT sum(total) = 30 FROM hs_lancamentos WHERE folio_id = fo13 AND descricao LIKE 'Sinal retido%'), 'a gestão marca o não comparecimento e o sinal vira receita');
  PERFORM ci.entrar(gest); PERFORM hs_reserva_no_show(ru11, true); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'no_show' FROM hs_reservas WHERE id = r11) AND (SELECT situacao = 'aberto' FROM hs_folios WHERE id = fo11)
                   AND (SELECT count(*) = 1 AND sum(total) = 100 FROM hs_lancamentos WHERE folio_id = fo11 AND tipo = 'diaria') AND NOT EXISTS (SELECT 1 FROM hs_lancamentos WHERE folio_id = fo11 AND tipo = 'taxa_turismo'),
                   'cobrar a primeira diária do não comparecimento: 100 sem taxa de turismo, sobra 30 a receber e a conta continua aberta');
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = 30)::int', fo11)) = 1, 'saldo a receber de 30 (diária 100 − sinal 70)');

  -- ===== salão, anônimo e escrita direta =====
  PERFORM ci.exige(ci.contar(hgar, 'SELECT count(*) FROM hs_folios') = 0 AND ci.contar(hgar, 'SELECT count(*) FROM hs_lancamentos') = 0
                   AND ci.contar(hgar, 'SELECT count(*) FROM hs_pagamentos') = 0, 'garçom não lê contas, lançamentos nem pagamentos');
  PERFORM ci.deve_falhar(NULL, 'SELECT count(*) FROM hs_lancamentos', 'anônimo lê lançamentos');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_checkin(%L)$c$, ru6), 'anônimo faz check-in');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_auditoria_noturna(%L)$c$, fa), 'anônimo fecha o dia');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 1, 5, 5)$c$, demo, fa, fo1), 'administrador lança direto');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_lancamentos SET valor_unitario = 1, total = 1 WHERE id = %L$c$, ld), 'administrador muda o valor de um lançamento');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM hs_lancamentos WHERE id = %L$c$, ld), 'administrador apaga um lançamento');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO hs_pagamentos (tenant_id, filial_id, folio_id, tipo, forma, valor, caixa_id) VALUES (%L, %L, %L, 'pagamento', 'pix', 5, %L)$c$, demo, fa, fo1, cxA), 'administrador recebe direto');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM hs_pagamentos WHERE folio_id = %L$c$, fo1), 'administrador apaga pagamentos');
  PERFORM ci.deve_falhar(adm, format($c$UPDATE hs_folios SET situacao = 'fechado' WHERE id = %L$c$, fo1), 'administrador fecha a conta direto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT _hs_lancar_diaria(%L, current_date)$c$, ru1), 'usuário chama a rotina interna de diária');
  PERFORM ci.deve_falhar(vend, format($c$SELECT _hs_registrar_pagamento(%L, 'pix', 10, %L, 'pagamento', NULL)$c$, fo1, cxA), 'usuário chama a rotina interna de pagamento');
  PERFORM ci.deve_falhar(vend, format($c$SELECT _hs_encerrar_sem_estadia(%L, true, NULL, NULL, 'x')$c$, r1), 'usuário chama a rotina interna de encerramento');
  PERFORM ci.deve_falhar(vend, format($c$SELECT _hs_folio_saldo(%L)$c$, fo1), 'usuário chama a rotina interna de saldo');

  -- ===== restrições do banco, vistas pelo dono =====
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 2, 5, 11)$c$, demo, fa, fo1), 'lançamento com total diferente de quantidade × valor');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 1, -5, -5)$c$, demo, fa, fo1), 'consumo com valor negativo direto no banco');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, current_date, 'consumo', ' ', 1, 5, 5)$c$, demo, fa, fo1), 'lançamento sem descrição');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 0, 5, 0)$c$, demo, fa, fo1), 'lançamento de quantidade zero');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, reserva_uh_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, %L, %L, 'diaria', 'Repetida', 1, 100, 100)$c$, demo, fa, fo1, ru1, hoje), 'a mesma diária duas vezes para o mesmo quarto e noite');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total, estorna_id) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 1, -15, -15, %L)$c$, demo, fa, fo1, lc), 'estorno sem motivo');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total, estorna_id, motivo) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 1, -15, -15, %L, 'Segundo estorno')$c$, demo, fa, fo1, lc), 'dois estornos do mesmo lançamento');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 1, 5, 5)$c$, demo, fb2, fo1), 'lançamento de um hotel na conta de outro');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_pagamentos (tenant_id, filial_id, folio_id, tipo, forma, valor, caixa_id) VALUES (%L, %L, %L, 'pagamento', 'crediario', 5, %L)$c$, demo, fa, fo1, cxA), 'pagamento em crediário direto no banco');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_pagamentos (tenant_id, filial_id, folio_id, tipo, forma, valor, caixa_id) VALUES (%L, %L, %L, 'pagamento', 'pix', 0, %L)$c$, demo, fa, fo1, cxA), 'pagamento de valor zero direto no banco');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_pagamentos (tenant_id, filial_id, folio_id, tipo, forma, valor, caixa_id) VALUES (%L, %L, %L, 'pagamento', 'pix', 5, %L)$c$, demo, fb2, fo1, cxB), 'pagamento de um hotel na conta de outro');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_pagamentos (tenant_id, filial_id, folio_id, tipo, forma, valor, caixa_id, chave_idempotencia) VALUES (%L, %L, %L, 'pagamento', 'pix', 5, %L, %L)$c$, demo, fa, fo1, cxA, kp1), 'chave de pagamento repetida na empresa');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_folios (tenant_id, filial_id, reserva_id, principal) VALUES (%L, %L, %L, true)$c$, demo, fa, r1), 'segunda conta principal na mesma reserva');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_folios (tenant_id, filial_id, reserva_id, titulo) VALUES (%L, %L, %L, 'Cruzada')$c$, demo, fb2, r1), 'conta de um hotel numa reserva de outro');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_reserva_hospedes (tenant_id, reserva_uh_id, hospede_id, principal) VALUES (%L, %L, %L, true)$c$, demo, ru1, hC), 'dois hóspedes principais no mesmo quarto');

  -- ===== quem só acessa um hotel =====
  UPDATE profiles SET filial_id = fb2 WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_folios') = 0 AND ci.contar(vend, 'SELECT count(*) FROM hs_lancamentos') = 0 AND ci.contar(vend, 'SELECT count(*) FROM hs_pagamentos') = 0,
                   'recepção do hotel B não lê contas, lançamentos nem pagamentos do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"x","valor_unitario":5}'::jsonb)$c$, fo1), 'recepção do hotel B lança na conta do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 5, %L, 'sinal')$c$, fo1, cxB), 'recepção do hotel B recebe na conta do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_folio_saldo(%L)$c$, fo1), 'recepção do hotel B consulta o saldo do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L)$c$, ru6), 'recepção do hotel B faz check-in no hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_auditoria_noturna(%L)$c$, fa), 'recepção do hotel B fecha o dia do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_estadia_estender(%L, %L)$c$, ru1, hoje + 4), 'recepção do hotel B estende estadia do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancamento_estornar(%L, 'Outro hotel')$c$, lc), 'recepção do hotel B estorna lançamento do hotel A');
  UPDATE profiles SET filial_id = fa WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_folios') > 0 AND ci.contar(vend, 'SELECT count(*) FROM hs_lancamentos') > 0 AND ci.contar(vend, 'SELECT count(*) FROM hs_pagamentos') > 0, 'recepção do hotel A lê as contas do hotel A');
  UPDATE profiles SET filial_id = NULL WHERE id = vend;

  -- ===== outra empresa =====
  INSERT INTO tenants (nome) VALUES ('Hotel Estadia B') RETURNING id INTO tb;
  INSERT INTO empresas (tenant_id, razao_social, ramo_atividade) VALUES (tb, 'Hotel Estadia B Ltda', 'hotelaria') RETURNING id INTO eb;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (tb, eb, 'Hotel B Estadia') RETURNING id INTO fbb;
  UPDATE profiles SET tenant_id = tb WHERE id = bges;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (bges, tb, 'gestor');
  INSERT INTO caixas (tenant_id, filial_id) VALUES (tb, fbb) RETURNING id INTO cxbx;
  PERFORM ci.entrar(bges);
  tbx := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fbb, 'nome', 'Standard'));
  ubx := hs_uh_salvar(jsonb_build_object('tipo_id', tbx, 'numero', '1'));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tbx, 'nome', 'B', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 120)::text, 'valor_diaria', 70));
  hbx := hs_hospede_salvar('{"nome":"Hóspede Estadia B","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb);
  r := hs_reserva_criar(ci.reserva(fbb, hbx, ci.quarto(ubx, hoje::text, (hoje + 2)::text))); rbx := (r ->> 'reserva_id')::uuid;
  fobx := hs_folio_principal(rbx);
  PERFORM hs_pagamento_registrar(fobx, 'pix', 50, cxbx, 'sinal');
  SELECT id INTO rubx FROM hs_reserva_uhs WHERE reserva_id = rbx;
  PERFORM hs_checkin(rubx);
  PERFORM hs_auditoria_noturna(fbb);
  PERFORM ci.sair();
  SELECT id INTO lbx FROM hs_lancamentos WHERE folio_id = fobx AND tipo = 'diaria';
  PERFORM ci.exige(lbx IS NOT NULL AND ci.contar(bges, 'SELECT count(*) FROM hs_folios') = 1 AND ci.contar(bges, 'SELECT count(*) FROM hs_pagamentos') = 1, 'o gestor B opera o próprio hotel (sinal, check-in e fechar o dia)');
  PERFORM ci.exige(ci.contar(gest, format('SELECT count(*) FROM hs_folios WHERE tenant_id = %L', tb)) = 0 AND ci.contar(gest, format('SELECT count(*) FROM hs_lancamentos WHERE tenant_id = %L', tb)) = 0
                   AND ci.contar(gest, format('SELECT count(*) FROM hs_pagamentos WHERE tenant_id = %L', tb)) = 0, 'o gestor A não lê contas, lançamentos nem pagamentos do hotel B');
  PERFORM ci.exige(ci.contar(bges, format('SELECT count(*) FROM hs_lancamentos WHERE folio_id = %L', fo1)) = 0, 'o gestor B não lê a conta do hotel A');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"Invasor","valor_unitario":5}'::jsonb)$c$, fobx), 'lançar na conta de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 5, %L, 'sinal')$c$, fobx, cxA), 'receber na conta de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_pagamento_registrar(%L, 'pix', 5, %L, 'devolucao')$c$, fobx, cxbx), 'devolver dinheiro da conta de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_lancamento_estornar(%L, 'Invasor')$c$, lbx), 'estornar lançamento de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_lancamento_transferir(ARRAY[%L]::uuid[], %L)$c$, lbx, fx), 'transferir lançamento de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_lancamento_transferir(ARRAY[%L]::uuid[], %L)$c$, ld, fobx), 'transferir para a conta de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_folio_saldo(%L)$c$, fobx), 'ver o saldo da conta de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_folio_principal(%L)$c$, rbx), 'abrir a conta de reserva de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_folio_abrir(%L, 'Invasora')$c$, rbx), 'abrir conta extra em reserva de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_checkin(%L)$c$, rubx), 'check-in em quarto de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_auditoria_noturna(%L)$c$, fbb), 'fechar o dia de hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_estadia_estender(%L, %L)$c$, rubx, hoje + 4), 'estender estadia de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_estadia_encurtar(%L, %L)$c$, rubx, hoje + 1), 'encurtar estadia de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_estadia_trocar_uh(%L, %L, 'Invasor aqui')$c$, rubx, a104), 'trocar quarto de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_hospede_adicionar(%L, %L)$c$, rubx, hD), 'adicionar hóspede em quarto de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_cancelar(%L, 'Invasor aqui', false)$c$, rbx), 'cancelar reserva de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_no_show(%L, true)$c$, rubx), 'não comparecimento de outra empresa');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_lancamentos (tenant_id, filial_id, folio_id, data_competencia, tipo, descricao, quantidade, valor_unitario, total) VALUES (%L, %L, %L, current_date, 'consumo', 'x', 1, 5, 5)$c$, demo, fa, fobx), 'lançamento da empresa A na conta da empresa B');

  -- limpeza
  DELETE FROM hs_pagamentos WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_lancamentos WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_folios WHERE tenant_id IN (demo, tb);
  -- os movimentos de caixa são imutáveis: os caixas do teste ficam como estão
  DELETE FROM hs_ocupacoes WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_diarias WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_reserva_hospedes WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_reserva_uhs WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_reservas WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_tarifas WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_uhs WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_tipos_uh WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_hospedes WHERE tenant_id IN (demo, tb);
  DELETE FROM hs_config WHERE tenant_id IN (demo, tb);
  DELETE FROM user_roles WHERE user_id IN (hgar, bges);
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant, modulos_sem_cnpj = sem_ant WHERE id = emp;
END $$;

-- 99. Hotelaria (check-out): noites cobradas (mínimo de uma, saída antecipada, chegada atrasada), conta zerada para sair, pagamentos e devolução,
-- reserva de vários quartos e contas extras, NFS-e de hospedagem em rascunho (sem taxa de turismo nem consumo, com desconto rateado e ISS sobre o líquido),
-- acomodação suja até a recepção liberar, permissões e isolamento
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  hgar constant uuid := 'a0000000-0000-0000-0000-0000000002a6';
  bges constant uuid := 'a0000000-0000-0000-0000-0000000002a7';
  hoje date := current_date;
  ramo_ant text; cnae_ant text; cnae2_ant text; sem_ant text[]; iss_ant numeric;
  fb uuid; fb2 uuid; tnb uuid; ebb uuid; fbb uuid;
  tpo uuid; tpx uuid;
  b101 uuid; b102 uuid; b103 uuid; b104 uuid; b105 uuid; b106 uuid; b107 uuid; b108 uuid; ubx uuid;
  hT uuid; hU uuid; hbx uuid; cli uuid;
  cx uuid; cx2 uuid; cxbx uuid;
  r jsonb; r1 uuid; r2 uuid; r3 uuid; r4 uuid; r5 uuid; r6 uuid; r7 uuid; r8 uuid; rbx uuid;
  ru1 uuid; ru2 uuid; ru3 uuid; ru4a uuid; ru4b uuid; ru5 uuid; ru6 uuid; ru7 uuid; ru8 uuid; rubx uuid;
  fo1 uuid; fo2 uuid; fo4 uuid; fo5 uuid; fx uuid; fobx uuid;
  nf uuid; ld uuid; n bigint; pg0 bigint;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios, modulos_sem_cnpj INTO ramo_ant, cnae_ant, cnae2_ant, sem_ant FROM empresas WHERE id = emp;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = NULL, cnae_secundarios = NULL, modulos_sem_cnpj = '{}' WHERE id = emp;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'hotelaria');
  IF NOT EXISTS (SELECT 1 FROM fiscal_config WHERE tenant_id = demo AND filial_id IS NULL) THEN
    INSERT INTO fiscal_config (tenant_id, empresa_id) SELECT demo, id FROM empresas WHERE tenant_id = demo ORDER BY created_at, id LIMIT 1;
  END IF;
  SELECT aliquota_iss INTO iss_ant FROM fiscal_config WHERE tenant_id = demo AND filial_id IS NULL ORDER BY (empresa_id IS NULL), created_at LIMIT 1;
  UPDATE fiscal_config SET aliquota_iss = 5 WHERE tenant_id = demo;
  INSERT INTO auth.users (id, email) VALUES (hgar, 'garcom-checkout@ci'), (bges, 'gestor-checkout-b@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = hgar;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (hgar, demo, 'garcom');
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Checkout A') RETURNING id INTO fb;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Checkout B') RETURNING id INTO fb2;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Hotel CI', '52998224725') RETURNING id INTO cli;

  PERFORM ci.entrar(gest);
  tpo := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fb, 'nome', 'Duplo', 'capacidade_adultos', 3, 'capacidade_criancas', 1));
  b101 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '101'));  b102 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '102'));
  b103 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '103'));  b104 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '104'));
  b105 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '105'));  b106 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '106'));
  b107 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '107'));  b108 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '108'));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpo, 'nome', 'Base', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 60)::text, 'valor_diaria', 100));
  PERFORM hs_config_salvar(fb, '{"taxa_turismo_por_hospede_noite":"5"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  hT := hs_hospede_salvar('{"nome":"Hóspede Checkout T","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb);
  hU := hs_hospede_salvar('{"nome":"Hóspede Checkout U","documento_tipo":"cpf","documento_numero":"11144477735"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(adm); cx := abrir_caixa(fb, 0); cx2 := abrir_caixa(fb2, 0); PERFORM ci.sair();

  -- ===== S1: saída antecipada (a reserva ia até amanhã), conta com consumo e serviço =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(jsonb_build_object('filial_id', fb, 'titular_id', hT, 'pagador_cliente_id', cli, 'quartos', jsonb_build_array(ci.quarto(b101, (hoje - 2)::text, (hoje + 1)::text))));
  r1 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru1 FROM hs_reserva_uhs WHERE reserva_id = r1;
  PERFORM ci.entrar(vend); PERFORM hs_checkin(ru1); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '2 days' WHERE id = ru1;
  PERFORM ci.entrar(vend);
  PERFORM hs_auditoria_noturna(fb, hoje - 2); PERFORM hs_auditoria_noturna(fb, hoje - 1);
  fo1 := hs_folio_principal(r1);
  PERFORM hs_lancar(fo1, '{"tipo":"consumo","descricao":"Frigobar","valor_unitario":20}'::jsonb);
  PERFORM hs_lancar(fo1, '{"tipo":"servico","descricao":"Lavanderia","valor_unitario":30}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = 260)::int', fo1)) = 1, 'conta antes do check-out: 2 diárias com taxa (210) + frigobar 20 + lavanderia 30');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L)$c$, ru1), 'check-out com a conta em aberto');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":100}]'::jsonb, %L)$c$, ru1, cx), 'check-out pagando menos que o saldo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":300}]'::jsonb, %L)$c$, ru1, cx), 'check-out pagando mais que o saldo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":260}]'::jsonb)$c$, ru1), 'check-out com pagamento e sem caixa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":260}]'::jsonb, %L)$c$, ru1, cx2), 'check-out recebendo no caixa de outro hotel');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"crediario","valor":260}]'::jsonb, %L)$c$, ru1, cx), 'check-out em crediário');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"xx","valor":260}]'::jsonb, %L)$c$, ru1, cx), 'check-out com forma de pagamento inventada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":0}]'::jsonb, %L)$c$, ru1, cx), 'check-out com pagamento de valor zero');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":5,"tipo":"xyz"}]'::jsonb, %L)$c$, ru1, cx), 'check-out com tipo de pagamento inventado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":5,"tipo":"devolucao"}]'::jsonb, %L)$c$, ru1, cx), 'devolução numa conta que ainda deve');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, jsonb_build_array(jsonb_build_object('forma','pix','valor',5,'folio_id',gen_random_uuid())), %L)$c$, ru1, cx), 'pagamento numa conta que não é da reserva');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '{"forma":"pix"}'::jsonb, %L)$c$, ru1, cx), 'pagamentos que não são uma lista');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":260}]'::jsonb, %L)$c$, ru1, cx), 'garçom faz check-out');
  PERFORM ci.exige((SELECT situacao = 'hospedada' AND saida = hoje + 1 AND checkout_em IS NULL FROM hs_reserva_uhs WHERE id = ru1)
                   AND (SELECT periodo = daterange(hoje - 2, hoje + 1, '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru1)
                   AND (SELECT count(*) = 3 AND count(*) FILTER (WHERE lancada) = 2 FROM hs_diarias WHERE reserva_uh_id = ru1)
                   AND (SELECT count(*) = 0 FROM hs_pagamentos WHERE folio_id = fo1) AND (SELECT situacao = 'aberto' FROM hs_folios WHERE id = fo1)
                   AND (SELECT situacao_limpeza <> 'sujo' FROM hs_uhs WHERE id = b101), 'os check-outs recusados não deixaram nada pela metade');
  PERFORM ci.entrar(vend);
  r := hs_checkout(ru1, '[{"forma":"pix","valor":100},{"forma":"dinheiro","valor":160}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige(NOT (r ->> 'parcial')::boolean AND NOT (r ->> 'repetido')::boolean AND (r ->> 'noites_cobradas')::integer = 2 AND (r ->> 'recebido')::numeric = 260 AND jsonb_array_length(r -> 'nfe_ids') = 1, 'check-out com saída antecipada: 2 noites cobradas, 260 recebidos, 1 nota');
  nf := ((r -> 'nfe_ids') ->> 0)::uuid;
  PERFORM ci.exige((SELECT situacao = 'finalizada' AND saida = hoje AND checkout_em IS NOT NULL FROM hs_reserva_uhs WHERE id = ru1) AND (SELECT situacao = 'finalizada' FROM hs_reservas WHERE id = r1), 'quarto e reserva finalizados e a saída passa a ser hoje');
  PERFORM ci.exige((SELECT periodo = daterange(hoje - 2, hoje, '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru1) AND (SELECT count(*) = 2 FROM hs_diarias WHERE reserva_uh_id = ru1), 'a noite que sobrou saiu da estadia e o calendário termina hoje');
  PERFORM ci.exige((SELECT situacao_limpeza = 'sujo' FROM hs_uhs WHERE id = b101), 'a acomodação fica suja');
  PERFORM ci.exige((SELECT situacao = 'fechado' AND fechado_em IS NOT NULL AND caixa_id = cx FROM hs_folios WHERE id = fo1) AND ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = 0)::int', fo1)) = 1, 'conta fechada e zerada, com o caixa do recebimento');
  PERFORM ci.exige((SELECT count(*) = 2 AND sum(valor) = 260 FROM hs_pagamentos WHERE folio_id = fo1 AND tipo = 'pagamento') AND (SELECT sum(valor) = 260 FROM caixa_movimentos WHERE caixa_id = cx AND tipo = 'venda'), 'os dois pagamentos entraram no caixa do hotel');
  PERFORM ci.exige((SELECT modelo = 'nfse' AND situacao IN ('rascunho', 'pronta') AND valor_produtos = 230 AND valor_total = 230 AND valor_desconto = 0 AND cliente_id = cli AND pedido_id IS NULL
                      AND (destinatario ->> 'nome') = 'Cliente Hotel CI' AND natureza_operacao = 'Prestação de serviço — hospedagem' FROM nfe WHERE id = nf), 'NFS-e de hospedagem: 200 de diárias + 30 de lavanderia, para o cliente pagador');
  PERFORM ci.exige((SELECT count(*) = 2 AND sum(total) = 230 FROM nfe_itens WHERE nfe_id = nf) AND NOT EXISTS (SELECT 1 FROM nfe_itens WHERE nfe_id = nf AND (descricao ILIKE '%taxa%' OR descricao ILIKE '%frigobar%')), 'a nota não leva a taxa de turismo nem o frigobar');
  PERFORM ci.exige((SELECT descricao LIKE 'Hospedagem — UH 101 — 2 diária(s) de %' FROM nfe_itens WHERE nfe_id = nf ORDER BY total DESC LIMIT 1), 'o item da hospedagem descreve o quarto e as diárias');
  PERFORM ci.exige((SELECT count(*) = 1 FROM hs_folio_notas WHERE folio_id = fo1 AND nfe_id = nf AND reserva_id = r1), 'a nota fica ligada à conta');
  pg0 := (SELECT count(*) FROM hs_pagamentos WHERE folio_id = fo1);
  PERFORM ci.entrar(vend); r := hs_checkout(ru1, '[{"forma":"pix","valor":999}]'::jsonb, cx); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'repetido')::boolean AND ((r -> 'nfe_ids') ->> 0)::uuid = nf AND (SELECT count(*) = pg0 FROM hs_pagamentos WHERE folio_id = fo1) AND (SELECT count(*) = 1 FROM hs_folio_notas WHERE reserva_id = r1), 'repetir o check-out devolve o mesmo resultado, sem receber de novo nem criar outra nota');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_lancar(%L, '{"tipo":"consumo","descricao":"x","valor_unitario":5}'::jsonb)$c$, fo1), 'lançar numa conta depois do check-out');

  -- ===== S2: estadia inteira, sinal maior que a conta (devolver o crédito), desconto da gestão e ISS sobre o líquido =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fb, hT, ci.quarto(b102, (hoje - 2)::text, (hoje + 1)::text))); r2 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru2 FROM hs_reserva_uhs WHERE reserva_id = r2;
  PERFORM ci.entrar(vend); fo2 := hs_folio_principal(r2); PERFORM hs_pagamento_registrar(fo2, 'pix', 300, cx, 'sinal'); PERFORM hs_checkin(ru2); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '2 days' WHERE id = ru2;
  PERFORM ci.entrar(vend); PERFORM hs_auditoria_noturna(fb, hoje - 2); PERFORM hs_auditoria_noturna(fb, hoje - 1); PERFORM ci.sair();
  PERFORM ci.entrar(gest); PERFORM hs_lancar(fo2, '{"tipo":"ajuste","descricao":"Desconto da gerência","valor_unitario":-20}'::jsonb); PERFORM ci.sair();
  PERFORM ci.exige(ci.contar(vend, format('SELECT (hs_folio_saldo(%L) = -110)::int', fo2)) = 1, 'conta com crédito de 110: diárias 210 − desconto 20 − sinal 300');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L)$c$, ru2), 'check-out com crédito do hóspede sem devolver');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":200,"tipo":"devolucao"}]'::jsonb, %L)$c$, ru2, cx), 'devolver mais que o crédito');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":10}]'::jsonb, %L)$c$, ru2, cx), 'receber de quem tem crédito');
  PERFORM ci.entrar(vend); r := hs_checkout(ru2, '[{"forma":"pix","valor":110,"tipo":"devolucao"}]'::jsonb, cx); PERFORM ci.sair();
  nf := ((r -> 'nfe_ids') ->> 0)::uuid;
  PERFORM ci.exige(NOT (r ->> 'parcial')::boolean AND (r ->> 'noites_cobradas')::integer = 2 AND (r ->> 'recebido')::numeric = -110, 'check-out da estadia inteira devolvendo 110 de crédito');
  PERFORM ci.exige((SELECT sum(valor) = 110 FROM hs_pagamentos WHERE folio_id = fo2 AND tipo = 'devolucao') AND (SELECT sum(valor) = 110 FROM caixa_movimentos WHERE caixa_id = cx AND tipo = 'saida'), 'a devolução do crédito saiu do caixa');
  PERFORM ci.exige((SELECT count(*) = 1 FROM auditoria WHERE entidade = 'hs_folios' AND operacao = 'devolucao' AND entidade_id = fo2), 'a devolução no check-out fica na auditoria');
  PERFORM ci.exige((SELECT valor_produtos = 200 AND valor_desconto = 20 AND valor_total = 180 AND valor_iss = 9.00 AND cliente_id IS NULL AND (destinatario ->> 'nome') = 'Hóspede Checkout T' AND (destinatario ->> 'cpf') = '52998224725' FROM nfe WHERE id = nf),
                   'NFS-e sem cliente cadastrado usa o titular; desconto de 20 e ISS de 5% sobre o líquido (9,00)');
  PERFORM ci.exige((SELECT count(*) = 1 AND sum(desconto) = 20 AND sum(total) = 180 AND sum(valor_iss) = 9.00 FROM nfe_itens WHERE nfe_id = nf), 'o item da nota guarda o desconto e o total líquido');
  PERFORM ci.exige((SELECT situacao = 'finalizada' AND saida = hoje FROM hs_reserva_uhs WHERE id = ru2) AND (SELECT periodo = daterange(hoje - 2, hoje, '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru2), 'a saída passa a ser hoje também na estadia que ia até amanhã');

  -- ===== S3: entrou e saiu no mesmo dia: cobra ao menos uma noite =====
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fb, hT, ci.quarto(b103, hoje::text, (hoje + 2)::text))); r3 := (r ->> 'reserva_id')::uuid;
  SELECT id INTO ru3 FROM hs_reserva_uhs WHERE reserva_id = r3;
  PERFORM hs_checkin(ru3);
  r := hs_checkout(ru3, '[{"forma":"pix","valor":105}]'::jsonb, cx);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'noites_cobradas')::integer = 1 AND (SELECT saida = hoje + 1 FROM hs_reserva_uhs WHERE id = ru3) AND (SELECT periodo = daterange(hoje, hoje + 1, '[)') FROM hs_ocupacoes WHERE reserva_uh_id = ru3)
                   AND (SELECT count(*) = 1 FROM hs_diarias WHERE reserva_uh_id = ru3), 'check-out no dia da chegada cobra uma noite e libera as seguintes');
  PERFORM ci.exige((SELECT valor_total = 100 FROM nfe WHERE id = ((r -> 'nfe_ids') ->> 0)::uuid), 'a nota da noite única é de 100 (a taxa de 5 fica de fora)');

  -- ===== S4: dois quartos, conta compartilhada =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fb, hT, ci.quarto(b104, (hoje - 1)::text, (hoje + 1)::text), ci.quarto(b105, (hoje - 1)::text, (hoje + 1)::text))); r4 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT min(id::text)::uuid, max(id::text)::uuid INTO ru4a, ru4b FROM hs_reserva_uhs WHERE reserva_id = r4;
  PERFORM ci.entrar(vend); PERFORM hs_checkin(ru4a); PERFORM hs_checkin(ru4b); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '1 day' WHERE reserva_id = r4;
  PERFORM ci.entrar(vend); PERFORM hs_auditoria_noturna(fb, hoje - 1); fo4 := hs_folio_principal(r4); PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":105}]'::jsonb, %L)$c$, ru4a, cx), 'pagar no check-out do primeiro de dois quartos');
  PERFORM ci.exige((SELECT situacao = 'hospedada' FROM hs_reserva_uhs WHERE id = ru4a), 'o check-out recusado do primeiro quarto não mexeu nele');
  PERFORM ci.entrar(vend); r := hs_checkout(ru4a); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'parcial')::boolean AND jsonb_array_length(r -> 'nfe_ids') = 0 AND (SELECT situacao = 'finalizada' FROM hs_reserva_uhs WHERE id = ru4a) AND (SELECT situacao = 'hospedada' FROM hs_reservas WHERE id = r4)
                   AND (SELECT situacao = 'aberto' FROM hs_folios WHERE id = fo4) AND (SELECT situacao_limpeza = 'sujo' FROM hs_uhs WHERE id = CASE WHEN (SELECT uh_id FROM hs_reserva_uhs WHERE id = ru4a) = b104 THEN b104 ELSE b105 END),
                   'o primeiro quarto sai sem cobrar: a reserva segue hospedada e a conta aberta');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":100}]'::jsonb, %L)$c$, ru4b, cx), 'último quarto sem pagar a conta toda');
  PERFORM ci.entrar(vend); r := hs_checkout(ru4b, '[{"forma":"pix","valor":210}]'::jsonb, cx); PERFORM ci.sair();
  nf := ((r -> 'nfe_ids') ->> 0)::uuid;
  PERFORM ci.exige(NOT (r ->> 'parcial')::boolean AND jsonb_array_length(r -> 'nfe_ids') = 1 AND (SELECT situacao = 'finalizada' FROM hs_reservas WHERE id = r4) AND (SELECT situacao = 'fechado' FROM hs_folios WHERE id = fo4), 'o último quarto cobra a conta toda e fecha a reserva');
  PERFORM ci.exige((SELECT count(*) = 2 AND sum(total) = 200 FROM nfe_itens WHERE nfe_id = nf), 'uma nota com um item de hospedagem por quarto');

  -- ===== S5: conta extra (a empresa paga as diárias) =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fb, hT, ci.quarto(b106, (hoje - 1)::text, (hoje + 1)::text))); r5 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru5 FROM hs_reserva_uhs WHERE reserva_id = r5;
  PERFORM ci.entrar(vend); PERFORM hs_checkin(ru5); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '1 day' WHERE id = ru5;
  PERFORM ci.entrar(vend);
  PERFORM hs_auditoria_noturna(fb, hoje - 1);
  fo5 := hs_folio_principal(r5); fx := hs_folio_abrir(r5, 'Empresa');
  SELECT id INTO ld FROM hs_lancamentos WHERE folio_id = fo5 AND tipo = 'diaria';
  PERFORM hs_lancamento_transferir(ARRAY[ld], fx);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":5}]'::jsonb, %L)$c$, ru5, cx), 'check-out sem pagar a conta extra');
  PERFORM ci.entrar(vend);
  r := hs_checkout(ru5, jsonb_build_array(jsonb_build_object('forma', 'pix', 'valor', 5), jsonb_build_object('forma', 'dinheiro', 'valor', 100, 'folio_id', fx)), cx);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'nfe_ids') = 1 AND (SELECT situacao = 'fechado' FROM hs_folios WHERE id = fo5) AND (SELECT situacao = 'fechado' FROM hs_folios WHERE id = fx), 'as duas contas fecham');
  PERFORM ci.exige((SELECT count(*) = 1 FROM hs_folio_notas WHERE reserva_id = r5 AND folio_id = fx) AND NOT EXISTS (SELECT 1 FROM hs_folio_notas WHERE folio_id = fo5), 'só a conta com hospedagem gera nota; a que tem só a taxa de turismo não');
  PERFORM ci.exige((SELECT sum(valor) = 100 FROM hs_pagamentos WHERE folio_id = fx) AND (SELECT sum(valor) = 5 FROM hs_pagamentos WHERE folio_id = fo5), 'cada pagamento foi para a conta informada');

  -- ===== S6: chegada atrasada: a noite anterior ao check-in não é cobrada =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fb, hT, ci.quarto(b107, (hoje - 1)::text, (hoje + 1)::text))); r6 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru6 FROM hs_reserva_uhs WHERE reserva_id = r6;
  PERFORM ci.entrar(vend); PERFORM hs_checkin(ru6); PERFORM hs_auditoria_noturna(fb); r := hs_checkout(ru6, '[{"forma":"pix","valor":105}]'::jsonb, cx); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'noites_cobradas')::integer = 1 AND (SELECT NOT lancada FROM hs_diarias WHERE reserva_uh_id = ru6 AND data = hoje - 1) AND (SELECT lancada FROM hs_diarias WHERE reserva_uh_id = ru6 AND data = hoje), 'a noite anterior ao check-in atrasado não é lançada nem cobrada');
  PERFORM ci.exige((SELECT valor_total = 100 FROM nfe WHERE id = ((r -> 'nfe_ids') ->> 0)::uuid), 'a nota da chegada atrasada é de 100');
  PERFORM ci.exige((SELECT numero IS NULL OR situacao = 'pronta' FROM nfe WHERE id = ((r -> 'nfe_ids') ->> 0)::uuid), 'nota em rascunho não gasta número da prefeitura');

  -- ===== limpeza da acomodação =====
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fb, hT, ci.quarto(b101, hoje::text, (hoje + 1)::text))); r8 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru8 FROM hs_reserva_uhs WHERE reserva_id = r8;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkin(%L)$c$, ru8), 'check-in na acomodação que ficou suja no check-out');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_uh_situacao(%L, 'brilhando')$c$, b101), 'situação de limpeza inventada');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_uh_situacao(%L, 'limpo')$c$, b101), 'garçom libera a limpeza');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_uh_situacao(%L, 'limpo')$c$, b101), 'anônimo libera a limpeza');
  PERFORM ci.entrar(vend); PERFORM hs_uh_situacao(b101, 'inspecionado'); PERFORM hs_checkin(ru8); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'hospedada' FROM hs_reserva_uhs WHERE id = ru8) AND (SELECT situacao_limpeza = 'inspecionado' FROM hs_uhs WHERE id = b101), 'depois de liberada a acomodação aceita o check-in');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_uh_situacao(%L, 'limpo')$c$, b101), 'marcar como limpa a acomodação com hóspede');
  PERFORM ci.entrar(vend); PERFORM hs_uh_situacao(b101, 'sujo'); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao_limpeza = 'sujo' FROM hs_uhs WHERE id = b101), 'acomodação com hóspede pode ser marcada como suja');

  -- ===== outros quartos e hotéis =====
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fb, hT, ci.quarto(b108, (hoje + 5)::text, (hoje + 6)::text))); r7 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru7 FROM hs_reserva_uhs WHERE reserva_id = r7;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L)$c$, ru7), 'check-out de quarto que ainda não fez check-in');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_checkout(%L)$c$, ru8), 'anônimo faz check-out');
  UPDATE profiles SET filial_id = fb2 WHERE id = vend;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":5}]'::jsonb, %L)$c$, ru8, cx2), 'recepção do hotel B faz check-out no hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_uh_situacao(%L, 'limpo')$c$, b102), 'recepção do hotel B libera a limpeza no hotel A');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_folio_notas') = 0, 'recepção do hotel B não lê as notas do hotel A');
  UPDATE profiles SET filial_id = NULL WHERE id = vend;
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM hs_folio_notas') >= 5, 'recepção sem filial fixa lê as notas dos hotéis da empresa');
  PERFORM ci.exige(ci.contar(hgar, 'SELECT count(*) FROM hs_folio_notas') = 0, 'garçom não lê as notas dos hotéis');
  PERFORM ci.deve_falhar(NULL, 'SELECT count(*) FROM hs_folio_notas', 'anônimo lê as notas dos hotéis');
  PERFORM ci.deve_falhar(vend, format($c$SELECT _hs_nfse_rascunho(%L)$c$, fo1), 'usuário chama a rotina interna da nota');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO hs_folio_notas (tenant_id, filial_id, folio_id, reserva_id, nfe_id) VALUES (%L, %L, %L, %L, %L)$c$, demo, fb, fo1, r1, nf), 'administrador liga uma nota direto');
  PERFORM ci.deve_falhar(adm, format($c$DELETE FROM hs_folio_notas WHERE folio_id = %L$c$, fo1), 'administrador apaga o vínculo da nota');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_folio_notas (tenant_id, filial_id, folio_id, reserva_id, nfe_id) VALUES (%L, %L, %L, %L, (SELECT id FROM nfe WHERE modelo = 'nfse' AND id NOT IN (SELECT nfe_id FROM hs_folio_notas) LIMIT 1))$c$, demo, fb, fo1, r1), 'duas notas para a mesma conta');

  -- ===== outra empresa =====
  INSERT INTO tenants (nome) VALUES ('Hotel Checkout B') RETURNING id INTO tnb;
  INSERT INTO empresas (tenant_id, razao_social, ramo_atividade) VALUES (tnb, 'Hotel Checkout B Ltda', 'hotelaria') RETURNING id INTO ebb;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (tnb, ebb, 'Hotel B Checkout') RETURNING id INTO fbb;
  UPDATE profiles SET tenant_id = tnb WHERE id = bges;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (bges, tnb, 'gestor');
  INSERT INTO caixas (tenant_id, filial_id) VALUES (tnb, fbb) RETURNING id INTO cxbx;
  PERFORM ci.entrar(bges);
  tpx := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fbb, 'nome', 'Standard'));
  ubx := hs_uh_salvar(jsonb_build_object('tipo_id', tpx, 'numero', '1'));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpx, 'nome', 'B', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 60)::text, 'valor_diaria', 70));
  hbx := hs_hospede_salvar('{"nome":"Hóspede Checkout B","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb);
  r := hs_reserva_criar(ci.reserva(fbb, hbx, ci.quarto(ubx, (hoje - 1)::text, (hoje + 1)::text))); rbx := (r ->> 'reserva_id')::uuid;
  SELECT id INTO rubx FROM hs_reserva_uhs WHERE reserva_id = rbx;
  PERFORM hs_checkin(rubx);
  PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '1 day' WHERE id = rubx;
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_checkout(%L, '[{"forma":"pix","valor":70}]'::jsonb, %L)$c$, rubx, cxbx), 'check-out de quarto de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_uh_situacao(%L, 'limpo')$c$, ubx), 'liberar a limpeza de acomodação de outra empresa');
  PERFORM ci.entrar(bges); PERFORM hs_auditoria_noturna(fbb, hoje - 1); r := hs_checkout(rubx, '[{"forma":"pix","valor":70}]'::jsonb, cxbx); PERFORM ci.sair();
  PERFORM ci.exige((SELECT valor_total = 70 AND tenant_id = tnb FROM nfe WHERE id = ((r -> 'nfe_ids') ->> 0)::uuid), 'o gestor B faz o check-out e a nota é da empresa B');
  PERFORM ci.exige(ci.contar(bges, 'SELECT count(*) FROM hs_folio_notas') = 1 AND ci.contar(gest, format('SELECT count(*) FROM hs_folio_notas WHERE tenant_id = %L', tnb)) = 0, 'cada empresa só lê as próprias notas');
  PERFORM ci.exige(ci.contar(gest, format('SELECT count(*) FROM nfe WHERE tenant_id = %L', tnb)) = 0, 'a nota da empresa B não aparece para a empresa A');
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO hs_folio_notas (tenant_id, filial_id, folio_id, reserva_id, nfe_id) VALUES (%L, %L, %L, %L, %L)$c$, tnb, fbb, fo1, rbx, nf), 'nota da empresa B ligada à conta da empresa A');

  -- limpeza
  DELETE FROM hs_folio_notas WHERE tenant_id IN (demo, tnb);
  DELETE FROM nfe_itens WHERE nfe_id IN (SELECT id FROM nfe WHERE natureza_operacao = 'Prestação de serviço — hospedagem');
  DELETE FROM nfe WHERE natureza_operacao = 'Prestação de serviço — hospedagem';
  DELETE FROM hs_pagamentos WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_lancamentos WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_folios WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_ocupacoes WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_diarias WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_reserva_hospedes WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_reserva_uhs WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_reservas WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_tarifas WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_uhs WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_tipos_uh WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_hospedes WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_config WHERE tenant_id IN (demo, tnb);
  DELETE FROM user_roles WHERE user_id IN (hgar, bges);
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  UPDATE fiscal_config SET aliquota_iss = coalesce(iss_ant, 0) WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant, modulos_sem_cnpj = sem_ant WHERE id = emp;
END $$;

-- 100. Hotelaria (leitura): mapa de ocupação (acomodação × dia, totais por noite, bloqueios, quartos sem acomodação), painel do dia (chegadas, saídas, atrasos,
-- hospedados, ocupação, sujas, contas em aberto, dia passado e futuro), resumo da conta e da reserva; só quem pode e só do próprio hotel e da própria empresa
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  hgar constant uuid := 'a0000000-0000-0000-0000-0000000002a8';
  bges constant uuid := 'a0000000-0000-0000-0000-0000000002a9';
  hoje date := current_date;
  ramo_ant text; cnae_ant text; cnae2_ant text; sem_ant text[]; iss_ant numeric;
  fm uuid; fm2 uuid; tnb uuid; ebb uuid; fbb uuid;
  tpo uuid; tpo2 uuid; tpx uuid;
  m101 uuid; m102 uuid; m103 uuid; m104 uuid; m105 uuid; m106 uuid; m107 uuid; m108 uuid; m109 uuid; m110 uuid; x1 uuid; ubx uuid;
  hT uuid; hU uuid; hbx uuid; cx uuid; cx2 uuid;
  r jsonb; el jsonb; r1 uuid; r2 uuid; r3 uuid; r4 uuid; r5 uuid; r6 uuid; r7 uuid; r8 uuid; rsem uuid; rbx uuid;
  ru1 uuid; ru4 uuid; ru5 uuid; ru7 uuid; rubx uuid; fo1 uuid; fo7 uuid; fobx uuid; blq uuid; lcons uuid; lserv uuid; num1 bigint; nf uuid;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios, modulos_sem_cnpj INTO ramo_ant, cnae_ant, cnae2_ant, sem_ant FROM empresas WHERE id = emp;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = NULL, cnae_secundarios = NULL, modulos_sem_cnpj = '{}' WHERE id = emp;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'hotelaria');
  SELECT aliquota_iss INTO iss_ant FROM fiscal_config WHERE tenant_id = demo AND filial_id IS NULL ORDER BY (empresa_id IS NULL), created_at LIMIT 1;
  INSERT INTO auth.users (id, email) VALUES (hgar, 'garcom-leitura@ci'), (bges, 'gestor-leitura-b@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = hgar;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (hgar, demo, 'garcom');
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Mapa A') RETURNING id INTO fm;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Mapa B') RETURNING id INTO fm2;

  PERFORM ci.entrar(gest);
  tpo := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fm, 'nome', 'Duplo', 'capacidade_adultos', 3, 'capacidade_criancas', 1));
  tpo2 := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fm2, 'nome', 'Duplo', 'capacidade_adultos', 2));
  m101 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '101'));  m102 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '102'));
  m103 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '103'));  m104 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '104'));
  m105 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '105'));  m106 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '106'));
  m107 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '107', 'ativo', false));
  m108 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '108', 'interditada', true, 'motivo_interdicao', 'Reforma'));
  m109 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '109'));  m110 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '110'));
  x1 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo2, 'numero', 'X1'));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpo, 'nome', 'Base', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 60)::text, 'valor_diaria', 100));
  PERFORM hs_config_salvar(fm, '{"taxa_turismo_por_hospede_noite":"5"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  hT := hs_hospede_salvar('{"nome":"Hóspede Mapa T","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb);
  hU := hs_hospede_salvar('{"nome":"Hóspede Mapa U","documento_tipo":"cpf","documento_numero":"11144477735"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(adm); cx := abrir_caixa(fm, 0); cx2 := abrir_caixa(fm2, 0); PERFORM ci.sair();

  -- ===== dados do dia =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fm, hT, ci.quarto(m101, (hoje - 1)::text, (hoje + 2)::text))); r1 := (r ->> 'reserva_id')::uuid; num1 := (r ->> 'numero')::bigint;
  r := hs_reserva_criar(ci.reserva(fm, hU, ci.quarto(m104, (hoje - 2)::text, hoje::text)));       r4 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fm, hU, ci.quarto(m105, (hoje - 3)::text, (hoje - 1)::text))); r5 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(ci.reserva(fm, hU, ci.quarto(m106, (hoje - 1)::text, (hoje + 1)::text))); r6 := (r ->> 'reserva_id')::uuid;
  blq := hs_uh_interditar(m109, hoje - 1, hoje + 3, 'Pintura');
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fm, hU, ci.quarto(m102, hoje::text, (hoje + 1)::text))); r2 := (r ->> 'reserva_id')::uuid;
  r := hs_reserva_criar(jsonb_build_object('filial_id', fm, 'titular_id', hU, 'situacao', 'pendente', 'quartos', jsonb_build_array(ci.quarto(m103, hoje::text, (hoje + 3)::text))));
  r3 := (r ->> 'reserva_id')::uuid;
  fo1 := hs_folio_principal(r1);
  PERFORM hs_pagamento_registrar(fo1, 'pix', 50, cx, 'sinal');
  SELECT id INTO ru1 FROM hs_reserva_uhs WHERE reserva_id = r1;
  PERFORM hs_checkin(ru1);
  PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '1 day' WHERE id = ru1;
  PERFORM ci.entrar(vend);
  PERFORM hs_auditoria_noturna(fm, hoje - 1);
  lcons := hs_lancar(fo1, '{"tipo":"consumo","descricao":"Frigobar","valor_unitario":20}'::jsonb);
  lserv := hs_lancar(fo1, '{"tipo":"servico","descricao":"Lavanderia","valor_unitario":30}'::jsonb);
  PERFORM hs_lancamento_estornar(lserv, 'Cobrado por engano');
  PERFORM ci.sair();
  -- hóspedes simulados pelo dono do banco depois do fechamento do dia (para não gerar lançamentos)
  SELECT id INTO ru4 FROM hs_reserva_uhs WHERE reserva_id = r4;  SELECT id INTO ru5 FROM hs_reserva_uhs WHERE reserva_id = r5;
  UPDATE hs_reserva_uhs SET situacao = 'hospedada', checkin_em = now() - interval '2 days' WHERE id = ru4;
  UPDATE hs_reserva_uhs SET situacao = 'hospedada', checkin_em = now() - interval '3 days' WHERE id = ru5;
  PERFORM _hs_reserva_recalcular(r4); PERFORM _hs_reserva_recalcular(r5);
  UPDATE hs_uhs SET situacao_limpeza = 'sujo' WHERE id IN (m104, m105);
  INSERT INTO hs_reservas (tenant_id, filial_id, numero, titular_id) VALUES (demo, fm, 9001, hT) RETURNING id INTO rsem;
  INSERT INTO hs_reserva_uhs (tenant_id, filial_id, reserva_id, tipo_id, uh_id, entrada, saida) VALUES (demo, fm, rsem, tpo, NULL, hoje + 1, hoje + 3);

  -- ===== mapa =====
  PERFORM ci.entrar(vend); r := hs_mapa(fm, hoje - 2, hoje + 3); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'dias') = 5 AND (r -> 'dias' ->> 0)::date = hoje - 2 AND (r -> 'dias' ->> 4)::date = hoje + 2, 'o mapa traz os 5 dias da janela');
  PERFORM ci.exige(jsonb_array_length(r -> 'uhs') = 9 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'uhs') e WHERE e ->> 'numero' = '107'), 'o mapa traz as 9 acomodações ativas e deixa de fora a inativa');
  PERFORM ci.exige((SELECT array_agg(e ->> 'numero' ORDER BY ord) = ARRAY['101','102','103','104','105','106','108','109','110'] FROM jsonb_array_elements(r -> 'uhs') WITH ORDINALITY x(e, ord)), 'ordem por tipo e número');
  SELECT e INTO el FROM jsonb_array_elements(r -> 'uhs') e WHERE e ->> 'numero' = '101';
  PERFORM ci.exige(jsonb_array_length(el -> 'ocupacoes') = 1 AND (el -> 'ocupacoes' -> 0 ->> 'origem') = 'reserva' AND (el -> 'ocupacoes' -> 0 ->> 'situacao') = 'hospedada'
                   AND (el -> 'ocupacoes' -> 0 ->> 'de')::date = hoje - 1 AND (el -> 'ocupacoes' -> 0 ->> 'ate')::date = hoje + 2 AND (el -> 'ocupacoes' -> 0 ->> 'reserva_numero')::bigint = num1
                   AND (el -> 'ocupacoes' -> 0 ->> 'titular') = 'Hóspede Mapa T', 'a acomodação 101 mostra a reserva hospedada com as datas reais e o titular');
  SELECT e INTO el FROM jsonb_array_elements(r -> 'uhs') e WHERE e ->> 'numero' = '109';
  PERFORM ci.exige((el -> 'ocupacoes' -> 0 ->> 'origem') = 'bloqueio' AND (el -> 'ocupacoes' -> 0 ->> 'motivo') = 'Pintura' AND (el -> 'ocupacoes' -> 0 -> 'reserva_id') = 'null'::jsonb, 'a acomodação 109 mostra o bloqueio com o motivo');
  SELECT e INTO el FROM jsonb_array_elements(r -> 'uhs') e WHERE e ->> 'numero' = '108';
  PERFORM ci.exige((el ->> 'interditada')::boolean AND el ->> 'motivo_interdicao' = 'Reforma' AND jsonb_array_length(el -> 'ocupacoes') = 0, 'a acomodação interditada vem marcada');
  SELECT e INTO el FROM jsonb_array_elements(r -> 'uhs') e WHERE e ->> 'numero' = '104';
  PERFORM ci.exige((el ->> 'situacao_limpeza') = 'sujo', 'a limpeza aparece no mapa');
  PERFORM ci.exige((SELECT array_agg(((e ->> 'ocupadas')::int, (e ->> 'bloqueadas')::int, (e ->> 'livres')::int, (e ->> 'total')::int)::text ORDER BY ord)
                      = ARRAY['(2,0,6,8)', '(3,1,4,8)', '(4,1,3,8)', '(2,1,5,8)', '(1,1,6,8)'] FROM jsonb_array_elements(r -> 'totais_por_dia') WITH ORDINALITY x(e, ord)),
                   'totais por noite: ocupadas, bloqueadas, livres e vendáveis (a interditada e a inativa ficam fora)');
  PERFORM ci.exige(jsonb_array_length(r -> 'sem_acomodacao') = 1 AND (r -> 'sem_acomodacao' -> 0 ->> 'reserva_numero')::bigint = 9001 AND (r -> 'sem_acomodacao' -> 0 ->> 'entrada')::date = hoje + 1, 'o quarto reservado sem acomodação aparece à parte');
  PERFORM ci.entrar(vend); r := hs_mapa(fm, hoje + 10, hoje + 11); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'sem_acomodacao') = 0 AND (r -> 'totais_por_dia' -> 0 ->> 'ocupadas')::int = 0 AND (r -> 'totais_por_dia' -> 0 ->> 'livres')::int = 8, 'janela sem nada: tudo livre');
  PERFORM ci.entrar(vend); r := hs_mapa(fm, hoje, hoje + 62); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'dias') = 62, 'a janela de 62 dias é aceita');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fm, hoje, hoje + 63), 'janela de 63 dias');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fm, hoje, hoje), 'janela vazia');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fm, hoje + 1, hoje), 'janela invertida');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_mapa(%L, NULL, %L)$c$, fm, hoje), 'janela sem início');

  -- ===== painel do dia =====
  PERFORM ci.entrar(vend); r := hs_painel_dia(fm); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'data')::date = hoje AND (r ->> 'hoje')::date = hoje, 'o painel abre no dia de hoje');
  PERFORM ci.exige((SELECT array_agg(e ->> 'uh' ORDER BY ord) = ARRAY['102', '103'] FROM jsonb_array_elements(r -> 'chegadas') WITH ORDINALITY x(e, ord)) AND (r -> 'chegadas' -> 1 ->> 'pendente')::boolean AND NOT (r -> 'chegadas' -> 0 ->> 'pendente')::boolean,
                   'chegadas do dia: 102 confirmada e 103 pendente');
  PERFORM ci.exige(jsonb_array_length(r -> 'chegadas_atrasadas') = 1 AND (r -> 'chegadas_atrasadas' -> 0 ->> 'uh') = '106', 'chegada atrasada: a reserva de ontem que não veio');
  PERFORM ci.exige(jsonb_array_length(r -> 'saidas') = 1 AND (r -> 'saidas' -> 0 ->> 'uh') = '104' AND (r -> 'saidas' -> 0 ->> 'situacao') = 'hospedada', 'saída do dia: a 104 ainda hospedada');
  PERFORM ci.exige(jsonb_array_length(r -> 'saidas_atrasadas') = 1 AND (r -> 'saidas_atrasadas' -> 0 ->> 'uh') = '105', 'saída atrasada: a 105 devia ter saído ontem');
  PERFORM ci.exige(jsonb_array_length(r -> 'hospedados') = 1 AND (r -> 'hospedados' -> 0 ->> 'uh') = '101' AND (r -> 'hospedados' -> 0 ->> 'titular') = 'Hóspede Mapa T' AND (r -> 'hospedados' -> 0 ->> 'saldo')::numeric = 75
                   AND (r -> 'hospedados' -> 0 ->> 'hospedes')::int = 1, 'hospedados: só a 101, com o saldo da conta (75) e o número de hóspedes');
  PERFORM ci.exige((r -> 'ocupacao' ->> 'acomodacoes')::int = 8 AND (r -> 'ocupacao' ->> 'bloqueadas')::int = 1 AND (r -> 'ocupacao' ->> 'vendaveis')::int = 7 AND (r -> 'ocupacao' ->> 'ocupadas')::int = 4
                   AND (r -> 'ocupacao' ->> 'livres')::int = 3 AND (r -> 'ocupacao' ->> 'percentual')::numeric = 57.1, 'ocupação de hoje: 4 de 7 vendáveis (57,1%)');
  PERFORM ci.exige(jsonb_array_length(r -> 'sujas') = 2 AND (r -> 'sujas' -> 0 ->> 'numero') = '104' AND (r -> 'sujas' -> 0 ->> 'ocupada')::boolean, 'acomodações sujas, com a marca de ocupada');
  PERFORM ci.exige((r -> 'contas_em_aberto' ->> 'quantidade')::int = 1 AND (r -> 'contas_em_aberto' ->> 'total')::numeric = 75, 'contas em aberto: uma, de 75');
  PERFORM ci.exige((r -> 'totais' ->> 'chegadas')::int = 2 AND (r -> 'totais' ->> 'saidas')::int = 1 AND (r -> 'totais' ->> 'hospedados')::int = 1 AND (r -> 'totais' ->> 'sujas')::int = 2, 'totais do painel');
  PERFORM ci.entrar(vend); r := hs_painel_dia(fm, hoje - 1); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'chegadas') = 2 AND jsonb_array_length(r -> 'saidas') = 1 AND (r -> 'saidas' -> 0 ->> 'uh') = '105'
                   AND jsonb_array_length(r -> 'chegadas_atrasadas') = 0 AND jsonb_array_length(r -> 'saidas_atrasadas') = 0, 'ontem: 2 chegadas, a saída da 105 e nenhum atraso (atraso só vale de hoje em diante)');
  PERFORM ci.exige((SELECT array_agg(e ->> 'uh' ORDER BY e ->> 'uh') = ARRAY['101', '104'] FROM jsonb_array_elements(r -> 'hospedados') e), 'ontem dormiram a 101 e a 104');
  PERFORM ci.exige((r -> 'ocupacao' ->> 'ocupadas')::int = 3 AND (r -> 'ocupacao' ->> 'bloqueadas')::int = 1 AND (r -> 'ocupacao' ->> 'percentual')::numeric = 42.9, 'ocupação de ontem: 3 de 7 (42,9%)');
  PERFORM ci.entrar(vend); r := hs_painel_dia(fm, hoje + 1); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'chegadas') = 1 AND (r -> 'chegadas' -> 0 ->> 'uh') IS NULL AND jsonb_array_length(r -> 'hospedados') = 1 AND (r -> 'hospedados' -> 0 ->> 'uh') = '101'
                   AND jsonb_array_length(r -> 'chegadas_atrasadas') = 1 AND (r -> 'chegadas_atrasadas' -> 0 ->> 'uh') = '103', 'amanhã: chega o quarto sem acomodação, segue a 101 e a 103 ainda não chegou');
  PERFORM ci.exige((r -> 'ocupacao' ->> 'ocupadas')::int = 2 AND (r -> 'ocupacao' ->> 'livres')::int = 5 AND (r -> 'ocupacao' ->> 'percentual')::numeric = 28.6, 'ocupação de amanhã: 2 de 7 (28,6%)');

  -- ===== resumo da conta e da reserva =====
  PERFORM ci.entrar(vend); r := hs_folio_resumo(fo1); PERFORM ci.sair();
  PERFORM ci.exige((r -> 'folio' ->> 'principal')::boolean AND (r -> 'folio' ->> 'situacao') = 'aberto' AND (r -> 'reserva' ->> 'numero')::bigint = num1 AND (r -> 'reserva' ->> 'titular') = 'Hóspede Mapa T' AND r -> 'nota' = 'null'::jsonb, 'resumo da conta: reserva, titular e sem nota');
  PERFORM ci.exige(jsonb_array_length(r -> 'lancamentos') = 5 AND (r -> 'totais' ->> 'lancado')::numeric = 125 AND (r -> 'totais' ->> 'recebido')::numeric = 50 AND (r -> 'totais' ->> 'devolvido')::numeric = 0 AND (r -> 'totais' ->> 'saldo')::numeric = 75,
                   'totais da conta: lançado 125, recebido 50, saldo 75');
  PERFORM ci.exige((SELECT (e ->> 'estornado')::boolean FROM jsonb_array_elements(r -> 'lancamentos') e WHERE e ->> 'id' = lserv::text) AND (SELECT NOT (e ->> 'estornado')::boolean FROM jsonb_array_elements(r -> 'lancamentos') e WHERE e ->> 'id' = lcons::text)
                   AND (SELECT count(*) = 1 FROM jsonb_array_elements(r -> 'lancamentos') e WHERE e ->> 'estorna_id' = lserv::text), 'o lançamento estornado vem marcado e o estorno aponta para ele');
  PERFORM ci.exige((SELECT (e ->> 'uh') = '101' FROM jsonb_array_elements(r -> 'lancamentos') e WHERE e ->> 'tipo' = 'diaria') AND jsonb_array_length(r -> 'pagamentos') = 1 AND (r -> 'pagamentos' -> 0 ->> 'tipo') = 'sinal', 'a diária mostra a acomodação e o sinal aparece nos pagamentos');
  PERFORM ci.entrar(vend); r := hs_reserva_resumo(r1); PERFORM ci.sair();
  PERFORM ci.exige((r -> 'reserva' ->> 'situacao') = 'hospedada' AND (r -> 'titular' ->> 'nome') = 'Hóspede Mapa T' AND jsonb_array_length(r -> 'quartos') = 1 AND (r -> 'quartos' -> 0 ->> 'uh') = '101'
                   AND (r -> 'quartos' -> 0 ->> 'noites')::int = 3 AND (r -> 'quartos' -> 0 -> 'diarias' ->> 'total')::numeric = 300 AND (r -> 'quartos' -> 0 -> 'diarias' ->> 'lancadas')::int = 1
                   AND jsonb_array_length(r -> 'quartos' -> 0 -> 'hospedes') = 1 AND (r -> 'quartos' -> 0 -> 'hospedes' -> 0 ->> 'principal')::boolean, 'resumo da reserva: quarto, noites, diárias e hóspedes');
  PERFORM ci.exige(jsonb_array_length(r -> 'contas') = 1 AND (r -> 'contas' -> 0 ->> 'saldo')::numeric = 75 AND (r -> 'totais' ->> 'saldo')::numeric = 75 AND (r -> 'totais' ->> 'sinal_liquido')::numeric = 50 AND (r -> 'totais' ->> 'diarias')::numeric = 300, 'resumo da reserva: conta com saldo 75, sinal 50 e diárias 300');
  PERFORM ci.entrar(vend);
  r := hs_reserva_criar(ci.reserva(fm, hT, ci.quarto(m102, (hoje + 5)::text, (hoje + 7)::text))); r8 := (r ->> 'reserva_id')::uuid;
  PERFORM hs_reserva_cancelar(r8, 'Desistência');
  r := hs_reserva_resumo(r8);
  PERFORM ci.sair();
  PERFORM ci.exige((r -> 'reserva' ->> 'situacao') = 'cancelada' AND (r -> 'reserva' ->> 'motivo_cancelamento') = 'Desistência' AND (r -> 'quartos' -> 0 ->> 'situacao') = 'cancelada' AND (r -> 'totais' ->> 'diarias')::numeric = 0, 'reserva cancelada: quarto cancelado e sem diárias no total');

  -- ===== check-out e a nota na conta =====
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fm, hT, ci.quarto(m110, (hoje - 1)::text, (hoje + 1)::text))); r7 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT id INTO ru7 FROM hs_reserva_uhs WHERE reserva_id = r7;
  PERFORM ci.entrar(vend); PERFORM hs_checkin(ru7); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '1 day' WHERE id = ru7;
  PERFORM ci.entrar(vend); PERFORM hs_auditoria_noturna(fm, hoje - 1); fo7 := hs_folio_principal(r7); r := hs_checkout(ru7, '[{"forma":"pix","valor":105}]'::jsonb, cx); PERFORM ci.sair();
  nf := ((r -> 'nfe_ids') ->> 0)::uuid;
  PERFORM ci.entrar(vend); r := hs_folio_resumo(fo7); PERFORM ci.sair();
  PERFORM ci.exige((r -> 'folio' ->> 'situacao') = 'fechado' AND (r -> 'nota' ->> 'nfe_id')::uuid = nf AND (r -> 'nota' ->> 'modelo') = 'nfse' AND (r -> 'nota' ->> 'valor_total')::numeric = 100 AND (r -> 'nota' ->> 'situacao') IN ('rascunho', 'pronta')
                   AND (r -> 'totais' ->> 'lancado')::numeric = 105 AND (r -> 'totais' ->> 'recebido')::numeric = 105 AND (r -> 'totais' ->> 'saldo')::numeric = 0, 'conta fechada mostra a nota (100) e o saldo zerado');
  PERFORM ci.entrar(vend); r := hs_reserva_resumo(r7); PERFORM ci.sair();
  PERFORM ci.exige((r -> 'reserva' ->> 'situacao') = 'finalizada' AND (r -> 'quartos' -> 0 ->> 'situacao') = 'finalizada' AND (r -> 'quartos' -> 0 ->> 'checkout_em') IS NOT NULL AND (r -> 'contas' -> 0 ->> 'nfe_id')::uuid = nf, 'resumo da reserva finalizada: quarto finalizado e nota da conta');

  -- ===== permissões e isolamento =====
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fm, hoje, hoje + 5), 'garçom abre o mapa');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_painel_dia(%L)$c$, fm), 'garçom abre o painel do dia');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_folio_resumo(%L)$c$, fo1), 'garçom abre a conta');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_reserva_resumo(%L)$c$, r1), 'garçom abre a reserva');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fm, hoje, hoje + 5), 'anônimo abre o mapa');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_painel_dia(%L)$c$, fm), 'anônimo abre o painel do dia');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_folio_resumo(%L)$c$, fo1), 'anônimo abre a conta');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_reserva_resumo(%L)$c$, r1), 'anônimo abre a reserva');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_folio_resumo(%L)$c$, gen_random_uuid()), 'conta que não existe');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_resumo(%L)$c$, gen_random_uuid()), 'reserva que não existe');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_painel_dia(%L)$c$, gen_random_uuid()), 'painel de hotel que não existe');
  UPDATE profiles SET filial_id = fm2 WHERE id = vend;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fm, hoje, hoje + 5), 'recepção do hotel B abre o mapa do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_painel_dia(%L)$c$, fm), 'recepção do hotel B abre o painel do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_folio_resumo(%L)$c$, fo1), 'recepção do hotel B abre a conta do hotel A');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_reserva_resumo(%L)$c$, r1), 'recepção do hotel B abre a reserva do hotel A');
  PERFORM ci.entrar(vend); r := hs_mapa(fm2, hoje, hoje + 3); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'uhs') = 1 AND (r -> 'uhs' -> 0 ->> 'numero') = 'X1' AND jsonb_array_length(r -> 'sem_acomodacao') = 0, 'a recepção do hotel B vê só o mapa do hotel B');
  PERFORM ci.entrar(vend); r := hs_painel_dia(fm2); PERFORM ci.sair();
  PERFORM ci.exige((r -> 'ocupacao' ->> 'acomodacoes')::int = 1 AND jsonb_array_length(r -> 'hospedados') = 0 AND (r -> 'contas_em_aberto' ->> 'quantidade')::int = 0, 'o painel do hotel B não traz nada do hotel A');
  UPDATE profiles SET filial_id = NULL WHERE id = vend;

  INSERT INTO tenants (nome) VALUES ('Hotel Leitura B') RETURNING id INTO tnb;
  INSERT INTO empresas (tenant_id, razao_social, ramo_atividade) VALUES (tnb, 'Hotel Leitura B Ltda', 'hotelaria') RETURNING id INTO ebb;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (tnb, ebb, 'Hotel B Leitura') RETURNING id INTO fbb;
  UPDATE profiles SET tenant_id = tnb WHERE id = bges;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (bges, tnb, 'gestor');
  PERFORM ci.entrar(bges);
  tpx := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fbb, 'nome', 'Standard'));
  ubx := hs_uh_salvar(jsonb_build_object('tipo_id', tpx, 'numero', '1'));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpx, 'nome', 'B', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 60)::text, 'valor_diaria', 70));
  hbx := hs_hospede_salvar('{"nome":"Hóspede Leitura B","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb);
  r := hs_reserva_criar(ci.reserva(fbb, hbx, ci.quarto(ubx, hoje::text, (hoje + 2)::text))); rbx := (r ->> 'reserva_id')::uuid;
  fobx := hs_folio_principal(rbx);
  r := hs_mapa(fbb, hoje, hoje + 3);
  PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'uhs') = 1 AND (r -> 'uhs' -> 0 ->> 'numero') = '1' AND (r -> 'uhs' -> 0 -> 'ocupacoes' -> 0 ->> 'titular') = 'Hóspede Leitura B', 'o gestor B vê só o próprio mapa');
  PERFORM ci.entrar(bges); r := hs_painel_dia(fbb); PERFORM ci.sair();
  PERFORM ci.exige(jsonb_array_length(r -> 'chegadas') = 1 AND (r -> 'ocupacao' ->> 'acomodacoes')::int = 1, 'o painel do gestor B traz só a chegada dele');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fbb, hoje, hoje + 5), 'mapa do hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_painel_dia(%L)$c$, fbb), 'painel do hotel de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_folio_resumo(%L)$c$, fobx), 'conta de outra empresa');
  PERFORM ci.deve_falhar(gest, format($c$SELECT hs_reserva_resumo(%L)$c$, rbx), 'reserva de outra empresa');
  PERFORM ci.deve_falhar(bges, format($c$SELECT hs_mapa(%L, %L, %L)$c$, fm, hoje, hoje + 5), 'o gestor B abre o mapa do hotel A');
  PERFORM ci.deve_falhar(bges, format($c$SELECT hs_folio_resumo(%L)$c$, fo1), 'o gestor B abre a conta do hotel A');
  PERFORM ci.deve_falhar(bges, format($c$SELECT hs_reserva_resumo(%L)$c$, r1), 'o gestor B abre a reserva do hotel A');

  -- limpeza
  DELETE FROM hs_folio_notas WHERE tenant_id IN (demo, tnb);
  DELETE FROM nfe_itens WHERE nfe_id IN (SELECT id FROM nfe WHERE natureza_operacao = 'Prestação de serviço — hospedagem');
  DELETE FROM nfe WHERE natureza_operacao = 'Prestação de serviço — hospedagem';
  DELETE FROM hs_pagamentos WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_lancamentos WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_folios WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_ocupacoes WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_diarias WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_reserva_hospedes WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_reserva_uhs WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_reservas WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_tarifas WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_uhs WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_tipos_uh WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_hospedes WHERE tenant_id IN (demo, tnb);
  DELETE FROM hs_config WHERE tenant_id IN (demo, tnb);
  DELETE FROM user_roles WHERE user_id IN (hgar, bges);
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant, modulos_sem_cnpj = sem_ant WHERE id = emp;
END $$;

-- 101. Hotelaria (prévia do check-out): a prévia diz o mesmo que o check-out faz (noites, saída, valor a lançar e saldo de cada conta), sem gravar nada
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  emp  constant uuid := '22222222-2222-2222-2222-222222222222';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  hgar constant uuid := 'a0000000-0000-0000-0000-0000000002aa';
  hoje date := current_date;
  ramo_ant text; cnae_ant text; cnae2_ant text; sem_ant text[];
  fp uuid; fp2 uuid; tpo uuid; p101 uuid; p102 uuid; p103 uuid; p104 uuid; p105 uuid; hT uuid; cx uuid;
  r jsonb; pv jsonb; rs1 uuid; rs2 uuid; rs3 uuid; rs4 uuid; ru1 uuid; ru2 uuid; ru3a uuid; ru3b uuid; ru4 uuid; fo2 uuid; n0 bigint; saldo numeric;
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios, modulos_sem_cnpj INTO ramo_ant, cnae_ant, cnae2_ant, sem_ant FROM empresas WHERE id = emp;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = NULL, cnae_secundarios = NULL, modulos_sem_cnpj = '{}' WHERE id = emp;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  INSERT INTO empresa_modulos_liberados (empresa_id, modulo) VALUES (emp, 'hotelaria');
  INSERT INTO auth.users (id, email) VALUES (hgar, 'garcom-previa@ci');
  UPDATE profiles SET tenant_id = demo WHERE id = hgar;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (hgar, demo, 'garcom');
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Prévia A') RETURNING id INTO fp;
  INSERT INTO filiais (tenant_id, empresa_id, nome) VALUES (demo, emp, 'Hotel CI Prévia B') RETURNING id INTO fp2;

  PERFORM ci.entrar(gest);
  tpo := hs_tipo_uh_salvar(jsonb_build_object('filial_id', fp, 'nome', 'Duplo', 'capacidade_adultos', 3, 'capacidade_criancas', 1));
  p101 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '101')); p102 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '102'));
  p103 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '103')); p104 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '104'));
  p105 := hs_uh_salvar(jsonb_build_object('tipo_id', tpo, 'numero', '105'));
  PERFORM hs_tarifa_salvar(jsonb_build_object('tipo_id', tpo, 'nome', 'Base', 'vigencia_de', (hoje - 10)::text, 'vigencia_ate', (hoje + 60)::text, 'valor_diaria', 100));
  PERFORM hs_config_salvar(fp, '{"taxa_turismo_por_hospede_noite":"5"}'::jsonb);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend); hT := hs_hospede_salvar('{"nome":"Hóspede Prévia","documento_tipo":"cpf","documento_numero":"52998224725"}'::jsonb); PERFORM ci.sair();
  PERFORM ci.entrar(adm); cx := abrir_caixa(fp, 0); PERFORM ci.sair();

  -- P1: duas noites já lançadas, sai hoje: nada a lançar, saída encurtada
  PERFORM ci.entrar(gest); r := hs_reserva_criar(ci.reserva(fp, hT, ci.quarto(p101, (hoje - 2)::text, (hoje + 1)::text))); rs1 := (r ->> 'reserva_id')::uuid; PERFORM ci.sair();
  SELECT id INTO ru1 FROM hs_reserva_uhs WHERE reserva_id = rs1;
  PERFORM ci.entrar(vend); PERFORM hs_checkin(ru1); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '2 days' WHERE id = ru1;
  PERFORM ci.entrar(vend); PERFORM hs_auditoria_noturna(fp, hoje - 2); PERFORM hs_auditoria_noturna(fp, hoje - 1); pv := hs_checkout_previa(ru1); PERFORM ci.sair();
  PERFORM ci.exige((pv ->> 'saida')::date = hoje AND (pv ->> 'saida_prevista')::date = hoje + 1 AND (pv ->> 'noites_cobradas')::int = 2 AND (pv ->> 'a_lancar')::numeric = 0 AND (pv ->> 'ultimo_quarto')::boolean
                   AND (pv -> 'contas' -> 0 ->> 'saldo_atual')::numeric = 210 AND (pv -> 'contas' -> 0 ->> 'saldo_previsto')::numeric = 210, 'prévia com as noites já lançadas: saída hoje, nada a lançar, saldo 210');
  n0 := (SELECT count(*) FROM hs_lancamentos WHERE tenant_id = demo AND filial_id = fp);
  PERFORM ci.entrar(vend); PERFORM hs_checkout_previa(ru1); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'hospedada' AND saida = hoje + 1 FROM hs_reserva_uhs WHERE id = ru1) AND (SELECT count(*) = n0 FROM hs_lancamentos WHERE tenant_id = demo AND filial_id = fp), 'a prévia não grava nada');
  PERFORM ci.entrar(vend); r := hs_checkout(ru1, '[{"forma":"pix","valor":210}]'::jsonb, cx); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'noites_cobradas')::int = (pv ->> 'noites_cobradas')::int AND (r ->> 'saida')::date = (pv ->> 'saida')::date, 'o check-out fez o que a prévia disse (noites e saída) e o saldo previsto foi o que pagou');

  -- P2: noite de ontem ainda não lançada: a prévia soma a diária e a taxa e o check-out cobra exatamente isso
  PERFORM ci.entrar(gest); r := hs_reserva_criar(ci.reserva(fp, hT, ci.quarto(p102, (hoje - 1)::text, (hoje + 1)::text))); rs2 := (r ->> 'reserva_id')::uuid; PERFORM ci.sair();
  SELECT id INTO ru2 FROM hs_reserva_uhs WHERE reserva_id = rs2;
  PERFORM ci.entrar(vend); fo2 := hs_folio_principal(rs2); PERFORM hs_pagamento_registrar(fo2, 'pix', 300, cx, 'sinal'); PERFORM hs_checkin(ru2); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '1 day' WHERE id = ru2;
  PERFORM ci.entrar(vend); pv := hs_checkout_previa(ru2); PERFORM ci.sair();
  PERFORM ci.exige((pv ->> 'a_lancar')::numeric = 105 AND (pv ->> 'noites_cobradas')::int = 1 AND (pv ->> 'saida')::date = hoje AND (pv -> 'contas' -> 0 ->> 'saldo_atual')::numeric = -300 AND (pv -> 'contas' -> 0 ->> 'saldo_previsto')::numeric = -195,
                   'prévia com a noite de ontem por lançar: a lançar 105 e saldo previsto −195 (sinal de 300)');
  PERFORM ci.entrar(vend); r := hs_checkout(ru2, '[{"forma":"pix","valor":195,"tipo":"devolucao"}]'::jsonb, cx); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'recebido')::numeric = -195 AND (SELECT situacao = 'fechado' FROM hs_folios WHERE id = fo2), 'devolver o crédito previsto fecha a conta');

  -- P3: dois quartos: o primeiro não é o último; sem conta principal ainda a prévia traz a conta virtual
  PERFORM ci.entrar(gest);
  r := hs_reserva_criar(ci.reserva(fp, hT, ci.quarto(p103, (hoje - 1)::text, (hoje + 1)::text), ci.quarto(p104, (hoje - 1)::text, (hoje + 1)::text))); rs3 := (r ->> 'reserva_id')::uuid;
  PERFORM ci.sair();
  SELECT min(id::text)::uuid, max(id::text)::uuid INTO ru3a, ru3b FROM hs_reserva_uhs WHERE reserva_id = rs3;
  PERFORM ci.entrar(vend); PERFORM hs_checkin(ru3a); PERFORM hs_checkin(ru3b); PERFORM ci.sair();
  UPDATE hs_reserva_uhs SET checkin_em = now() - interval '1 day' WHERE reserva_id = rs3;
  DELETE FROM hs_folios WHERE reserva_id = rs3 AND NOT EXISTS (SELECT 1 FROM hs_lancamentos l WHERE l.folio_id = hs_folios.id) AND NOT EXISTS (SELECT 1 FROM hs_pagamentos p WHERE p.folio_id = hs_folios.id);
  PERFORM ci.entrar(vend); pv := hs_checkout_previa(ru3a); PERFORM ci.sair();
  PERFORM ci.exige(NOT (pv ->> 'ultimo_quarto')::boolean AND (pv ->> 'a_lancar')::numeric = 105 AND (pv -> 'contas' -> 0 ->> 'folio_id') IS NULL AND (pv -> 'contas' -> 0 ->> 'saldo_previsto')::numeric = 105,
                   'com dois quartos hospedados o primeiro não é o último; sem conta ainda a prévia traz a principal virtual');
  PERFORM ci.entrar(vend); PERFORM hs_checkout(ru3a); pv := hs_checkout_previa(ru3b); PERFORM ci.sair();
  PERFORM ci.exige((pv ->> 'ultimo_quarto')::boolean AND (pv -> 'contas' -> 0 ->> 'saldo_atual')::numeric = 105 AND (pv -> 'contas' -> 0 ->> 'saldo_previsto')::numeric = 210, 'depois que o primeiro saiu o segundo é o último e a conta prevista soma os dois');
  PERFORM ci.entrar(vend); saldo := (pv -> 'contas' -> 0 ->> 'saldo_previsto')::numeric; r := hs_checkout(ru3b, jsonb_build_array(jsonb_build_object('forma', 'pix', 'valor', saldo)), cx); PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'finalizada' FROM hs_reservas WHERE id = rs3) AND jsonb_array_length(r -> 'nfe_ids') = 1, 'pagar o saldo previsto fecha a reserva de dois quartos');

  -- guardas
  PERFORM ci.entrar(gest); r := hs_reserva_criar(ci.reserva(fp, hT, ci.quarto(p105, (hoje + 3)::text, (hoje + 4)::text))); rs4 := (r ->> 'reserva_id')::uuid; PERFORM ci.sair();
  SELECT id INTO ru4 FROM hs_reserva_uhs WHERE reserva_id = rs4;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout_previa(%L)$c$, ru4), 'prévia de quarto que não está hospedado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout_previa(%L)$c$, gen_random_uuid()), 'prévia de quarto que não existe');
  PERFORM ci.deve_falhar(hgar, format($c$SELECT hs_checkout_previa(%L)$c$, ru3b), 'garçom pede a prévia');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT hs_checkout_previa(%L)$c$, ru3b), 'anônimo pede a prévia');
  UPDATE profiles SET filial_id = fp2 WHERE id = vend;
  PERFORM ci.deve_falhar(vend, format($c$SELECT hs_checkout_previa(%L)$c$, ru4), 'recepção de outro hotel pede a prévia');
  UPDATE profiles SET filial_id = NULL WHERE id = vend;

  -- limpeza
  DELETE FROM hs_folio_notas WHERE tenant_id = demo;
  DELETE FROM nfe_itens WHERE nfe_id IN (SELECT id FROM nfe WHERE natureza_operacao = 'Prestação de serviço — hospedagem');
  DELETE FROM nfe WHERE natureza_operacao = 'Prestação de serviço — hospedagem';
  DELETE FROM hs_pagamentos WHERE tenant_id = demo; DELETE FROM hs_lancamentos WHERE tenant_id = demo; DELETE FROM hs_folios WHERE tenant_id = demo;
  DELETE FROM hs_ocupacoes WHERE tenant_id = demo; DELETE FROM hs_diarias WHERE tenant_id = demo; DELETE FROM hs_reserva_hospedes WHERE tenant_id = demo;
  DELETE FROM hs_reserva_uhs WHERE tenant_id = demo; DELETE FROM hs_reservas WHERE tenant_id = demo; DELETE FROM hs_tarifas WHERE tenant_id = demo;
  DELETE FROM hs_uhs WHERE tenant_id = demo; DELETE FROM hs_tipos_uh WHERE tenant_id = demo; DELETE FROM hs_hospedes WHERE tenant_id = demo; DELETE FROM hs_config WHERE tenant_id = demo;
  DELETE FROM user_roles WHERE user_id = hgar;
  DELETE FROM empresa_modulos_liberados WHERE empresa_id = emp AND modulo = 'hotelaria';
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant, modulos_sem_cnpj = sem_ant WHERE id = emp;
END $$;

-- 102. Lava rápido (agenda): RLS nas quatro tabelas, escrita só por função, papel e módulo, empresa de cada referência (cross-tenant),
-- conflito por lavador e por box (intervalo aberto), cancelar e faltar liberam, remarcar ignora o próprio, regra por empresa,
-- chegada idempotente que cria a ordem em aguardando sem cobrar, sem plano e sem baixa, e que respeita o checklist do pátio
DO $$
DECLARE
  demo constant uuid := '11111111-1111-1111-1111-111111111111';
  adm  constant uuid := 'a0000000-0000-0000-0000-000000000001';
  vend constant uuid := 'a0000000-0000-0000-0000-000000000002';
  gest constant uuid := 'a0000000-0000-0000-0000-000000000005';
  gar  constant uuid := 'a0000000-0000-0000-0000-000000000006';
  est  constant uuid := 'a0000000-0000-0000-0000-0000000000b1';
  u2   constant uuid := 'a0000000-0000-0000-0000-000000007802';
  u3   constant uuid := 'a0000000-0000-0000-0000-000000007803';
  ramo_ant text; cnae_ant text; cnae2_ant text;
  t2 uuid; t3 uuid;
  cli uuid; cli_b uuid; v1 uuid; v2 uuid; v3 uuid; v_b uuid; l1 uuid; l2 uuid; l_b uuid; s1 uuid; s2 uuid; s_sem uuid; s_b uuid; s_prod uuid;
  dep uuid; ped uuid;
  a1 uuid; a2 uuid; a3 uuid; a4 uuid; a5 uuid; a6 uuid; a_b uuid; o uuid; o2 uuid; r jsonb; n int; n0 int; i1 uuid;
  pl uuid; ass uuid; a7 uuid; a8 uuid; a9 uuid; o3 uuid; ped2 uuid; cli_p uuid; v_p uuid; v_q uuid; cli_f uuid; v_f uuid; v_g uuid;
  ini timestamptz := '2030-03-15 09:00:00-03';
BEGIN
  SELECT ramo_atividade, cnae, cnae_secundarios INTO ramo_ant, cnae_ant, cnae2_ant FROM empresas WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = 'outro', cnae = '4520-0/06', cnae_secundarios = NULL WHERE tenant_id = demo;

  -- outra empresa com o módulo e um administrador (prova de que a recusa é por empresa) e uma empresa sem o módulo
  INSERT INTO tenants (nome) VALUES ('Lava Agenda T2 CI') RETURNING id INTO t2;
  INSERT INTO tenants (nome) VALUES ('Lava Agenda T3 CI') RETURNING id INTO t3;
  INSERT INTO empresas (tenant_id, razao_social, cnae) VALUES (t2, 'Lava Agenda T2 Ltda', '4520-0/06');
  INSERT INTO empresas (tenant_id, razao_social) VALUES (t3, 'Lava Agenda T3 Ltda');
  INSERT INTO auth.users (id, email) VALUES (u2, 'agenda-t2@ci'), (u3, 'agenda-t3@ci');
  UPDATE profiles SET tenant_id = t2, nome = 'Admin T2' WHERE id = u2;
  UPDATE profiles SET tenant_id = t3, nome = 'Admin T3' WHERE id = u3;
  INSERT INTO user_roles (user_id, tenant_id, role) VALUES (u2, t2, 'administrador'), (u3, t3, 'administrador');

  INSERT INTO depositos (tenant_id, nome) VALUES (demo, 'Lava Agenda CI') RETURNING id INTO dep;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Agenda CI', '52998224725') RETURNING id INTO cli;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (t2, 'Cliente Agenda T2', '11144477735') RETURNING id INTO cli_b;
  PERFORM ci.entrar(vend);
  v1 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'AGD1A11', 'fabricante', 'Fiat', 'modelo', 'Argo'));
  v2 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'moto', 'identificacao', 'AGD2B22', 'fabricante', 'Honda', 'modelo', 'Biz'));
  v3 := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli, 'tipo', 'carro', 'identificacao', 'AGD3C33', 'fabricante', 'VW', 'modelo', 'Polo'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  s1 := lr_servico_salvar('{"nome":"Lavagem agenda","duracao_min":30,"preco_base":40}'::jsonb);
  s2 := lr_servico_salvar('{"nome":"Cera agenda","duracao_min":45,"preco_base":30}'::jsonb);
  s_sem := lr_servico_salvar('{"nome":"Serviço sem preço agenda","duracao_min":20,"preco_base":10}'::jsonb);
  l1 := lr_lavador_salvar('{"nome":"Lavador Agenda 1","comissao_percentual":10}'::jsonb);
  l2 := lr_lavador_salvar('{"nome":"Lavador Agenda 2","comissao_percentual":0}'::jsonb);
  PERFORM ci.sair();
  -- serviço sem nenhum preço cadastrado (nem por tipo, nem geral, nem no cadastro)
  UPDATE produtos SET preco_venda = 0 WHERE id = (SELECT produto_id FROM lr_servicos WHERE id = s_sem);
  DELETE FROM lr_servico_precos WHERE servico_id = s_sem;
  -- preço por tipo vence o geral no carro
  INSERT INTO lr_servico_precos (tenant_id, servico_id, tipo, preco) VALUES (demo, s1, 'carro', 55);
  SELECT produto_id INTO s_prod FROM lr_servicos WHERE id = s1;

  PERFORM ci.entrar(u2);
  v_b := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_b, 'tipo', 'carro', 'identificacao', 'AGB1A11', 'fabricante', 'Fiat', 'modelo', 'Uno'));
  s_b := lr_servico_salvar('{"nome":"Lavagem T2","duracao_min":30,"preco_base":40}'::jsonb);
  l_b := lr_lavador_salvar('{"nome":"Lavador T2","comissao_percentual":0}'::jsonb);
  PERFORM ci.sair();

  -- ===== escrita direta e leitura: só pelas funções, só da própria empresa =====
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO lr_agendamentos (tenant_id, veiculo_id, cliente_id, inicio, fim) VALUES (%L, %L, %L, now(), now() + interval '1 hour')$c$, demo, v1, cli), 'inserir agendamento direto');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO lr_agendamento_itens (tenant_id, agendamento_id, servico_id, duracao_min) VALUES (%L, gen_random_uuid(), %L, 30)$c$, demo, s1), 'inserir item de agendamento direto');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO lr_agenda_ocupacoes (tenant_id, agendamento_id, recurso, chave, periodo) VALUES (%L, gen_random_uuid(), 'box', 'x', tstzrange(now(), now() + interval '1 hour'))$c$, demo), 'inserir ocupação direto');
  PERFORM ci.deve_falhar(adm, format($c$INSERT INTO lr_agenda_config (tenant_id) VALUES (%L)$c$, demo), 'inserir configuração da agenda direto');
  PERFORM ci.deve_falhar(adm, $c$UPDATE lr_agendamentos SET situacao = 'faltou'$c$, 'alterar agendamento direto');
  PERFORM ci.deve_falhar(adm, $c$DELETE FROM lr_agendamentos$c$, 'apagar agendamento direto');
  PERFORM ci.deve_falhar(NULL, $c$SELECT count(*) FROM lr_agendamentos$c$, 'anon lê agendamentos');
  PERFORM ci.deve_falhar(NULL, $c$SELECT count(*) FROM lr_agendamento_itens$c$, 'anon lê itens');
  PERFORM ci.exige(ci.contar(gar, 'SELECT count(*) FROM lr_agendamentos') = 0, 'garçom não lê agendamentos');

  -- ===== papel e módulo nas cinco funções de escrita =====
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l1, ini, s1), 'garçom agenda');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l1, ini, s1), 'estoquista agenda');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l1, ini, s1), 'anon agenda');
  PERFORM ci.deve_falhar(u3, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l1, ini, s1), 'administrador de empresa sem o módulo agenda');
  PERFORM ci.deve_falhar(vend, $c$SELECT lr_agenda_config_salvar(true, true, true)$c$, 'vendedor muda a regra da agenda');
  PERFORM ci.deve_falhar(gar, $c$SELECT lr_agenda_config_salvar(true, true, true)$c$, 'garçom muda a regra da agenda');
  PERFORM ci.deve_falhar(NULL, $c$SELECT lr_agenda_config_salvar(true, true, true)$c$, 'anon muda a regra da agenda');
  PERFORM ci.deve_falhar(u3, $c$SELECT lr_agenda_config_salvar(true, true, true)$c$, 'empresa sem o módulo muda a regra da agenda');

  -- ===== agendar: validações, fim sugerido, preço e duração do cadastro =====
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, ini, s1), 'agendar sem lavador e sem box');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l1, s1), 'agendar sem início');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array()))$c$, v1, l1, ini), 'agendar sem serviço');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'fim', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l1, ini, ini, s1), 'fim igual ao início');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'fim', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l1, ini, ini + interval '25 hours', s1), 'agendamento de mais de 24 horas');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'cliente_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, cli_b, l1, ini, s1), 'cliente que não é dono do veículo');
  PERFORM ci.entrar(vend);
  a1 := lr_agendar(jsonb_build_object('veiculo_id', v1, 'cliente_id', cli, 'lavador_id', l1, 'box', ' Box 1 ', 'inicio', ini, 'servicos', jsonb_build_array(s1, s2), 'observacoes', 'Cliente pede cuidado com o banco'));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT fim = inicio + interval '75 minutes' AND situacao = 'agendado' AND box = 'Box 1' AND lavador_id = l1 AND cliente_id = cli FROM lr_agendamentos WHERE id = a1),
                   'o fim sugerido é a soma das durações cadastradas (30 + 45) e o box é gravado sem espaços');
  PERFORM ci.exige((SELECT preco_estimado = 55 AND duracao_min = 30 FROM lr_agendamento_itens WHERE agendamento_id = a1 AND servico_id = s1), 'o preço previsto é o do tipo do veículo e a duração é a do serviço');
  PERFORM ci.exige((SELECT preco_estimado = 30 AND duracao_min = 45 FROM lr_agendamento_itens WHERE agendamento_id = a1 AND servico_id = s2), 'sem preço por tipo, vale o preço do cadastro do serviço');
  PERFORM ci.entrar(vend);
  a2 := lr_agendar(jsonb_build_object('veiculo_id', v2, 'lavador_id', l2, 'inicio', ini + interval '3 hours', 'servicos', jsonb_build_array(s_sem)));
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT preco_estimado IS NULL FROM lr_agendamento_itens WHERE agendamento_id = a2), 'serviço sem preço cadastrado fica sem preço previsto (nada é inventado)');
  PERFORM ci.exige((SELECT count(*) = 2 FROM lr_agenda_ocupacoes WHERE agendamento_id = a1) AND (SELECT count(*) = 1 FROM lr_agenda_ocupacoes WHERE agendamento_id = a2), 'o calendário guarda lavador e box de cada agendamento');

  -- ===== cross-tenant: cada referência precisa ser da empresa de quem chama =====
  PERFORM ci.deve_falhar(u2, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v1, l_b, ini, s_b), 'agendar com veículo de outra empresa');
  PERFORM ci.deve_falhar(u2, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v_b, l1, ini, s_b), 'agendar com lavador de outra empresa');
  PERFORM ci.deve_falhar(u2, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v_b, l_b, ini, s1), 'agendar com serviço de outra empresa');
  PERFORM ci.deve_falhar(u2, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'cliente_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v_b, cli, l_b, ini, s_b), 'agendar com cliente de outra empresa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v_b, l1, ini + interval '5 hours', s1), 'a empresa de demonstração agenda veículo da T2');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v3, l_b, ini + interval '5 hours', s1), 'a empresa de demonstração agenda com lavador da T2');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v3, l1, ini + interval '5 hours', s_b), 'a empresa de demonstração agenda serviço da T2');
  PERFORM ci.entrar(u2);
  a_b := lr_agendar(jsonb_build_object('veiculo_id', v_b, 'cliente_id', cli_b, 'lavador_id', l_b, 'inicio', ini, 'servicos', jsonb_build_array(s_b)));
  PERFORM ci.sair();
  PERFORM ci.exige(a_b IS NOT NULL, 'a T2 agenda com os próprios cadastros (a recusa acima é por empresa, não por papel ou módulo)');
  PERFORM ci.deve_falhar(u2, format($c$SELECT lr_agenda_situacao(%L, 'confirmado')$c$, a1), 'confirmar agendamento de outra empresa');
  PERFORM ci.deve_falhar(u2, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, NULL)$c$, a1, ini + interval '1 day', l_b), 'remarcar agendamento de outra empresa');
  PERFORM ci.deve_falhar(u2, format($c$SELECT lr_agenda_chegada(%L)$c$, a1), 'registrar chegada de agendamento de outra empresa');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_chegada(%L)$c$, a_b), 'chegada de agendamento da T2 pela empresa de demonstração');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, NULL)$c$, a1, ini + interval '1 day', l_b), 'remarcar com lavador de outra empresa');
  PERFORM ci.exige(ci.contar(u2, 'SELECT count(*) FROM lr_agendamentos') = 1 AND ci.contar(u2, 'SELECT count(*) FROM lr_agendamento_itens') = 1, 'a T2 só lê o que é dela (cabeçalho e itens)');
  PERFORM ci.exige(ci.contar(u2, 'SELECT count(*) FROM lr_agenda_ocupacoes') = 1, 'a T2 só lê as ocupações dela');
  PERFORM ci.exige(ci.contar(vend, format($c$SELECT count(*) FROM lr_agendamentos WHERE id = %L$c$, a_b)) = 0, 'a empresa de demonstração não lê agendamento da T2');
  PERFORM ci.exige(ci.contar(vend, 'SELECT count(*) FROM lr_agendamentos') >= 2, 'a empresa de demonstração lê os seus');

  -- ===== conflito por lavador e por box (intervalo aberto no fim) =====
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'fim', %L, 'servicos', jsonb_build_array(%L)))$c$, v3, l1, ini + interval '30 minutes', ini + interval '90 minutes', s1), 'mesmo lavador em horário que cruza');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'inicio', %L, 'fim', %L, 'servicos', jsonb_build_array(%L)))$c$, v3, l1, ini - interval '30 minutes', ini + interval '1 minute', s1), 'mesmo lavador cruzando só o começo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'box', 'BOX 1', 'inicio', %L, 'fim', %L, 'servicos', jsonb_build_array(%L)))$c$, v3, l2, ini + interval '10 minutes', ini + interval '40 minutes', s1), 'mesmo box (maiúsculas e minúsculas não diferenciam) em horário que cruza');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'box', 'Box 1', 'inicio', %L, 'fim', %L, 'servicos', jsonb_build_array(%L)))$c$, v3, ini + interval '10 minutes', ini + interval '40 minutes', s1), 'só o box informado, que está ocupado');
  PERFORM ci.entrar(vend);
  a3 := lr_agendar(jsonb_build_object('veiculo_id', v3, 'lavador_id', l1, 'box', 'Box 1', 'inicio', ini + interval '75 minutes', 'servicos', jsonb_build_array(s1)));
  a4 := lr_agendar(jsonb_build_object('veiculo_id', v3, 'lavador_id', l2, 'box', 'Box 2', 'inicio', ini, 'servicos', jsonb_build_array(s1)));
  PERFORM ci.sair();
  PERFORM ci.exige(a3 IS NOT NULL, 'começar quando o outro termina é permitido (intervalo aberto no fim)');
  PERFORM ci.exige(a4 IS NOT NULL, 'outro lavador e outro box no mesmo horário é permitido');
  -- só o box, sem lavador
  PERFORM ci.entrar(vend);
  a5 := lr_agendar(jsonb_build_object('veiculo_id', v2, 'box', 'Box 3', 'inicio', ini + interval '6 hours', 'servicos', jsonb_build_array(s1)));
  PERFORM ci.sair();
  PERFORM ci.exige(a5 IS NOT NULL AND (SELECT count(*) = 1 FROM lr_agenda_ocupacoes WHERE agendamento_id = a5 AND recurso = 'box'), 'agendar só com o box vale e ocupa o box');

  -- ===== situação: confirmar, cancelar com motivo, faltar =====
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_agenda_situacao(%L, 'confirmado')$c$, a1), 'garçom confirma');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_agenda_situacao(%L, 'confirmado')$c$, a1), 'estoquista confirma');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_agenda_situacao(%L, 'confirmado')$c$, a1), 'anon confirma');
  PERFORM ci.deve_falhar(u3, format($c$SELECT lr_agenda_situacao(%L, 'confirmado')$c$, a1), 'empresa sem o módulo confirma');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'concluido')$c$, a1), 'concluir sem registrar a chegada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'cancelado')$c$, a1), 'cancelar sem motivo');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'cancelado', '   ')$c$, a1), 'cancelar com motivo em branco');
  PERFORM ci.entrar(vend);
  PERFORM lr_agenda_situacao(a1, 'confirmado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'confirmado' FROM lr_agendamentos WHERE id = a1), 'confirmar');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'agendado')$c$, a1), 'voltar de confirmado para agendado');
  -- cancelar libera o horário do lavador e do box
  PERFORM ci.entrar(vend);
  PERFORM lr_agenda_situacao(a3, 'cancelado', 'cliente desistiu');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'cancelado' AND motivo = 'cliente desistiu' FROM lr_agendamentos WHERE id = a3) AND NOT EXISTS (SELECT 1 FROM lr_agenda_ocupacoes WHERE agendamento_id = a3), 'cancelar guarda o motivo e libera o calendário');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'confirmado')$c$, a3), 'confirmar agendamento cancelado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'faltou')$c$, a3), 'marcar falta em agendamento cancelado');
  PERFORM ci.entrar(vend);
  a6 := lr_agendar(jsonb_build_object('veiculo_id', v3, 'lavador_id', l1, 'box', 'Box 1', 'inicio', ini + interval '75 minutes', 'servicos', jsonb_build_array(s1)));
  PERFORM ci.sair();
  PERFORM ci.exige(a6 IS NOT NULL, 'o horário liberado pelo cancelamento pode ser agendado de novo');
  PERFORM ci.entrar(vend);
  PERFORM lr_agenda_situacao(a6, 'faltou');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'faltou' FROM lr_agendamentos WHERE id = a6) AND NOT EXISTS (SELECT 1 FROM lr_agenda_ocupacoes WHERE agendamento_id = a6), 'falta libera o calendário');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'cancelado', 'x')$c$, a6), 'cancelar depois da falta');

  -- ===== remarcar =====
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, NULL)$c$, a1, ini + interval '1 day', l1), 'garçom remarca');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, NULL)$c$, a1, ini + interval '1 day', l1), 'anon remarca');
  PERFORM ci.deve_falhar(u3, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, NULL)$c$, a1, ini + interval '1 day', l1), 'empresa sem o módulo remarca');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, NULL, NULL)$c$, a1, ini + interval '1 day'), 'remarcar sem lavador e sem box');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, NULL)$c$, a3, ini + interval '1 day', l1), 'remarcar agendamento cancelado');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, 'Box 2')$c$, a1, ini, l2), 'remarcar para cima de outro lavador e outro box');
  PERFORM ci.entrar(vend);
  PERFORM lr_agenda_remarcar(a1, ini + interval '10 minutes', NULL, l1, 'Box 1');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT inicio = ini + interval '10 minutes' AND fim = ini + interval '85 minutes' AND situacao = 'agendado' FROM lr_agendamentos WHERE id = a1),
                   'remarcar para um horário que cruza só o próprio agendamento vale, mantém a duração e volta a "agendado"');
  PERFORM ci.exige((SELECT periodo = tstzrange(ini + interval '10 minutes', ini + interval '85 minutes', '[)') FROM lr_agenda_ocupacoes WHERE agendamento_id = a1 AND recurso = 'lavador'), 'o calendário acompanha a remarcação');

  -- ===== regra por empresa =====
  PERFORM ci.entrar(gest);
  PERFORM lr_agenda_config_salvar(false, true, true);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  a3 := lr_agendar(jsonb_build_object('veiculo_id', v3, 'lavador_id', l1, 'box', 'Box 9', 'inicio', ini + interval '20 minutes', 'servicos', jsonb_build_array(s1)));
  PERFORM ci.sair();
  PERFORM ci.exige(a3 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM lr_agenda_ocupacoes WHERE agendamento_id = a3 AND recurso = 'lavador'), 'com o conflito por lavador desligado, o lavador pode repetir (e o calendário não o trava)');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'lavador_id', %L, 'box', 'Box 1', 'inicio', %L, 'fim', %L, 'servicos', jsonb_build_array(%L)))$c$, v2, l2, ini + interval '20 minutes', ini + interval '50 minutes', s1), 'o conflito por box continua ligado');
  PERFORM ci.entrar(gest);
  PERFORM lr_agenda_config_salvar(true, false, false);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  a5 := lr_agendar(jsonb_build_object('veiculo_id', v2, 'inicio', ini + interval '8 hours', 'servicos', jsonb_build_array(s1)));
  PERFORM ci.sair();
  PERFORM ci.exige(a5 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM lr_agenda_ocupacoes WHERE agendamento_id = a5), 'sem exigir recurso, agendar sem lavador e sem box vale (e não ocupa nada)');
  PERFORM ci.entrar(gest);
  PERFORM lr_agenda_config_salvar(true, true, true);
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agendar(jsonb_build_object('veiculo_id', %L, 'inicio', %L, 'servicos', jsonb_build_array(%L)))$c$, v2, ini + interval '9 hours', s1), 'a regra padrão volta a exigir lavador ou box');
  -- o agendamento aceito com o conflito por lavador desligado (a3 cruza a1) ainda se confirma depois que a regra volta: confirmar não refaz o calendário
  SELECT count(*) INTO n FROM lr_agenda_ocupacoes WHERE agendamento_id IN (a1, a3);
  PERFORM ci.entrar(vend);
  PERFORM lr_agenda_situacao(a3, 'confirmado');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'confirmado' FROM lr_agendamentos WHERE id = a3) AND (SELECT count(*) = n FROM lr_agenda_ocupacoes WHERE agendamento_id IN (a1, a3))
                   AND NOT EXISTS (SELECT 1 FROM lr_agenda_ocupacoes WHERE agendamento_id = a3 AND recurso = 'lavador'),
                   'confirmar preserva o calendário: agendamento aceito antes da regra nova continua confirmável');
  -- no fundo, o banco recusa cruzamento mesmo fora das funções
  PERFORM ci.deve_falhar_dono(format($c$INSERT INTO lr_agenda_ocupacoes (tenant_id, agendamento_id, recurso, chave, periodo)
      VALUES (%L, %L, 'lavador', %L, tstzrange(%L::timestamptz, %L::timestamptz, '[)'))$c$, demo, a4, l2::text, ini + interval '10 minutes', ini + interval '20 minutes'), 'a restrição de exclusão do calendário recusa cruzamento');

  -- ===== chegada =====
  PERFORM ci.deve_falhar(gar, format($c$SELECT lr_agenda_chegada(%L)$c$, a1), 'garçom registra chegada');
  PERFORM ci.deve_falhar(est, format($c$SELECT lr_agenda_chegada(%L)$c$, a1), 'estoquista registra chegada');
  PERFORM ci.deve_falhar(NULL, format($c$SELECT lr_agenda_chegada(%L)$c$, a1), 'anon registra chegada');
  PERFORM ci.deve_falhar(u3, format($c$SELECT lr_agenda_chegada(%L)$c$, a1), 'empresa sem o módulo registra chegada');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_chegada(%L)$c$, gen_random_uuid()), 'chegada de agendamento que não existe');
  SELECT count(*) INTO n0 FROM lr_ordens WHERE tenant_id = demo;
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_chegada(%L)$c$, a6), 'agendamento marcado como falta não gera ordem');
  PERFORM ci.entrar(vend);
  PERFORM lr_agenda_situacao(a2, 'cancelado', 'teste');
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_chegada(%L)$c$, a2), 'agendamento cancelado não gera ordem');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_chegada(%L)$c$, a2), 'clique repetido em agendamento cancelado continua sem gerar ordem');
  PERFORM ci.exige((SELECT count(*) = n0 FROM lr_ordens WHERE tenant_id = demo) AND (SELECT ordem_id IS NULL FROM lr_agendamentos WHERE id = a2), 'cancelado e falta não criaram ordem');

  -- serviço sem preço: a chegada recusa e nada fica pela metade
  PERFORM ci.entrar(vend);
  a2 := lr_agendar(jsonb_build_object('veiculo_id', v2, 'lavador_id', l2, 'inicio', ini + interval '12 hours', 'servicos', jsonb_build_array(s_sem)));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_chegada(%L)$c$, a2), 'chegada com serviço sem preço cadastrado');
  PERFORM ci.exige((SELECT count(*) = n0 FROM lr_ordens WHERE tenant_id = demo) AND (SELECT situacao = 'agendado' AND ordem_id IS NULL FROM lr_agendamentos WHERE id = a2), 'a chegada recusada não deixou ordem nem mudou o agendamento');

  -- chegada de verdade (checklist obrigatório na empresa)
  PERFORM ci.entrar(gest);
  PERFORM lr_config_salvar(true);
  PERFORM ci.sair();
  PERFORM ci.entrar(vend);
  PERFORM lr_agenda_situacao(a1, 'confirmado');
  r := lr_agenda_chegada(a1);
  PERFORM ci.sair();
  o := (r ->> 'ordem_id')::uuid;
  PERFORM ci.exige(o IS NOT NULL AND NOT (r ->> 'repetido')::boolean, 'a chegada cria a ordem');
  PERFORM ci.exige((SELECT situacao = 'aguardando' AND veiculo_id = v1 AND cliente_id = cli AND lavador_id = l1 AND box = 'Box 1' AND observacoes = 'Cliente pede cuidado com o banco' AND checklist_em IS NULL
                      FROM lr_ordens WHERE id = o), 'a ordem nasce em aguardando, com cliente, veículo, lavador, box e observações, sem checklist');
  PERFORM ci.exige((SELECT situacao = 'concluido' AND ordem_id = o AND chegada_em IS NOT NULL FROM lr_agendamentos WHERE id = a1), 'o agendamento guarda o ordem_id e fica concluído');
  PERFORM ci.exige((SELECT count(*) = 2 FROM lr_ordem_itens WHERE ordem_id = o AND cobertura IS NULL AND assinatura_id IS NULL), 'sem plano nem brinde, os serviços previstos entram como itens comuns');
  PERFORM ci.exige((SELECT preco_aplicado = 55 FROM lr_ordem_itens WHERE ordem_id = o AND servico_id = s1) AND (SELECT preco_aplicado = 30 FROM lr_ordem_itens WHERE ordem_id = o AND servico_id = s2), 'preço da ordem: o do cadastro, por tipo de veículo');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM lr_assinatura_usos u JOIN lr_ordem_itens i ON i.id = u.item_id WHERE i.ordem_id = o), 'sem plano nem brinde no cadastro, a chegada não aplica cobertura');
  PERFORM ci.exige(NOT EXISTS (SELECT 1 FROM lr_insumo_baixas b WHERE b.ordem_id = o) AND NOT EXISTS (SELECT 1 FROM lr_comissoes WHERE ordem_id = o) AND (SELECT venda_id IS NULL FROM lr_ordens WHERE id = o), 'a chegada não cobra, não baixa insumo e não gera comissão');
  -- repetir a chegada devolve a mesma ordem
  PERFORM ci.entrar(vend);
  r := lr_agenda_chegada(a1);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ordem_id')::uuid = o AND (r ->> 'repetido')::boolean, 'clique repetido devolve a ordem existente');
  PERFORM ci.exige((SELECT count(*) = 1 FROM lr_ordens WHERE veiculo_id = v1 AND situacao <> 'cancelada') AND (SELECT count(*) = 2 FROM lr_ordem_itens WHERE ordem_id = o), 'e não cria outra ordem nem repete itens');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_situacao(%L, 'cancelado', 'x')$c$, a1), 'cancelar agendamento já concluído');
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_remarcar(%L, %L, NULL, %L, NULL)$c$, a1, ini + interval '2 days', l1), 'remarcar agendamento já concluído');
  -- veículo que já tem ordem aberta: a chegada seguinte recusa
  PERFORM ci.entrar(vend);
  a5 := lr_agendar(jsonb_build_object('veiculo_id', v1, 'lavador_id', l2, 'inicio', ini + interval '2 days', 'servicos', jsonb_build_array(s1)));
  PERFORM ci.sair();
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_agenda_chegada(%L)$c$, a5), 'chegada de veículo que já tem ordem aberta');
  PERFORM ci.exige((SELECT situacao = 'agendado' AND ordem_id IS NULL FROM lr_agendamentos WHERE id = a5), 'a recusa deixou o agendamento como estava');

  -- o pátio manda: checklist obrigatório vale para a ordem vinda da agenda
  PERFORM ci.deve_falhar(vend, format($c$SELECT lr_ordem_situacao(%L, 'lavando')$c$, o), 'lavar sem o checklist (a agenda não contorna)');
  PERFORM ci.entrar(vend);
  PERFORM lr_checklist_concluir(o, true);
  PERFORM lr_ordem_situacao(o, 'lavando');
  PERFORM lr_ordem_situacao(o, 'pronto');
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'pronto' FROM lr_ordens WHERE id = o), 'com o checklist concluído a ordem segue o pátio normalmente');
  -- entregar e cobrar: pelo fluxo de sempre
  PERFORM ci.entrar(vend);
  ped := pdv_venda(dep, jsonb_build_array(
           jsonb_build_object('produto_id', (SELECT produto_id FROM lr_servicos WHERE id = s1), 'quantidade', 1, 'preco_unitario', 55),
           jsonb_build_object('produto_id', (SELECT produto_id FROM lr_servicos WHERE id = s2), 'quantidade', 1, 'preco_unitario', 30)), 'crediario', cli, 0, 1, current_date + 30);
  r := lr_ordem_retirar(o, ped);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT situacao = 'entregue' AND venda_id = ped FROM lr_ordens WHERE id = o), 'Entregar e cobrar cobra a ordem da agenda pelo fluxo existente');
  PERFORM ci.exige((SELECT valor = 8.5 FROM lr_comissoes WHERE ordem_id = o), 'a comissão sai só na entrega (10% de 85)');
  PERFORM ci.entrar(vend);
  r := lr_agenda_chegada(a1);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ordem_id')::uuid = o AND (r ->> 'repetido')::boolean, 'depois de entregue, a chegada repetida ainda devolve a mesma ordem');

  -- ===== plano e fidelidade: a chegada aplica a mesma cobertura da ordem aberta no pátio =====
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Plano Agenda CI', '11144477735') RETURNING id INTO cli_p;
  INSERT INTO clientes (tenant_id, nome, cpf) VALUES (demo, 'Cliente Fiel Agenda CI', '39053344705') RETURNING id INTO cli_f;
  PERFORM ci.entrar(vend);
  v_p := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_p, 'tipo', 'carro', 'identificacao', 'AGP1A11', 'fabricante', 'Fiat', 'modelo', 'Mobi'));
  v_q := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_p, 'tipo', 'carro', 'identificacao', 'AGP2B22', 'fabricante', 'Fiat', 'modelo', 'Palio'));
  v_f := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_f, 'tipo', 'carro', 'identificacao', 'AGF1C33', 'fabricante', 'VW', 'modelo', 'Fox'));
  v_g := lr_veiculo_salvar(jsonb_build_object('cliente_id', cli_f, 'tipo', 'carro', 'identificacao', 'AGF2D44', 'fabricante', 'VW', 'modelo', 'Up'));
  PERFORM ci.sair();
  PERFORM ci.entrar(gest);
  pl := lr_plano_salvar(jsonb_build_object('nome', 'Plano agenda CI', 'servico_id', s1, 'lavagens', 2, 'preco', 60, 'validade_dias', 30, 'tipo', 'carro'));
  PERFORM ci.sair();
  -- assinatura ativa do veículo v_p para o serviço s1 (a venda do plano é testada na seção do pátio)
  INSERT INTO lr_assinaturas (tenant_id, plano_id, veiculo_id, cliente_id, servico_id, lavagens, valor, comprado_em, vence_em)
  VALUES (demo, pl, v_p, cli_p, s1, 2, 60, current_date, current_date + 30) RETURNING id INTO ass;
  PERFORM ci.entrar(vend);
  a7 := lr_agendar(jsonb_build_object('veiculo_id', v_p, 'lavador_id', l2, 'inicio', ini + interval '3 days', 'servicos', jsonb_build_array(s1, s2)));
  r := lr_agenda_chegada(a7);
  PERFORM ci.sair();
  o3 := (r ->> 'ordem_id')::uuid;
  PERFORM ci.exige((SELECT cobertura = 'assinatura' AND assinatura_id = ass FROM lr_ordem_itens WHERE ordem_id = o3 AND servico_id = s1), 'o serviço do plano ativo do veículo sai coberto pela assinatura');
  PERFORM ci.exige((SELECT cobertura IS NULL AND assinatura_id IS NULL AND preco_aplicado = 30 FROM lr_ordem_itens WHERE ordem_id = o3 AND servico_id = s2), 'o serviço fora do plano segue cobrado, com o preço do cadastro');
  PERFORM ci.exige((SELECT count(*) = 1 FROM lr_assinatura_usos u JOIN lr_ordem_itens i ON i.id = u.item_id WHERE i.ordem_id = o3 AND u.assinatura_id = ass AND NOT u.desfeito)
                   AND _lr_assinatura_restam(ass) = 1, 'a lavagem do plano é gasta uma vez');
  PERFORM ci.exige((SELECT situacao = 'aguardando' AND venda_id IS NULL FROM lr_ordens WHERE id = o3), 'a ordem com plano nasce em aguardando, sem venda');
  -- repetir a chegada não gasta outra lavagem
  PERFORM ci.entrar(vend);
  r := lr_agenda_chegada(a7);
  PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'ordem_id')::uuid = o3 AND (r ->> 'repetido')::boolean AND _lr_assinatura_restam(ass) = 1, 'clique repetido não gasta outra lavagem do plano');
  -- cancelar a ordem devolve a lavagem (regra do pátio)
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o3, 'cancelada', 'teste');
  PERFORM ci.sair();
  PERFORM ci.exige(_lr_assinatura_restam(ass) = 2, 'cancelar a ordem da agenda devolve a lavagem do plano');
  -- plano de outro veículo do mesmo cliente não vale
  PERFORM ci.entrar(vend);
  a8 := lr_agendar(jsonb_build_object('veiculo_id', v_q, 'lavador_id', l2, 'inicio', ini + interval '3 days 2 hours', 'servicos', jsonb_build_array(s1)));
  r := lr_agenda_chegada(a8);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura IS NULL AND preco_aplicado = 55 FROM lr_ordem_itens WHERE ordem_id = (r ->> 'ordem_id')::uuid), 'a assinatura de um veículo não cobre outro veículo');
  -- plano vencido não cobre
  UPDATE lr_assinaturas SET vence_em = current_date - 1 WHERE id = ass;
  PERFORM ci.entrar(vend);
  a9 := lr_agendar(jsonb_build_object('veiculo_id', v_p, 'lavador_id', l1, 'inicio', ini + interval '4 days', 'servicos', jsonb_build_array(s1)));
  r := lr_agenda_chegada(a9);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura IS NULL FROM lr_ordem_itens WHERE ordem_id = (r ->> 'ordem_id')::uuid) AND _lr_assinatura_restam(ass) = 2, 'plano vencido não cobre a ordem da agenda');
  -- outra empresa não enxerga nem usa essa assinatura
  PERFORM ci.exige(ci.contar(u2, 'SELECT count(*) FROM lr_assinaturas') = 0, 'a assinatura não aparece para outra empresa');

  -- fidelidade: a cada 2 lavagens entregues, a próxima do serviço-brinde (s2) é grátis
  PERFORM ci.entrar(gest);
  PERFORM lr_fidelidade_salvar(true, 2, s2);
  PERFORM ci.sair();
  FOR n IN 1..2 LOOP
    PERFORM ci.entrar(vend);
    o3 := lr_ordem_criar(jsonb_build_object('veiculo_id', v_f, 'lavador_id', l2, 'servicos', jsonb_build_array(s1)));
    PERFORM lr_checklist_concluir(o3, true);
    PERFORM lr_ordem_situacao(o3, 'lavando'); PERFORM lr_ordem_situacao(o3, 'pronto');
    ped2 := pdv_venda(dep, jsonb_build_array(jsonb_build_object('produto_id', s_prod, 'quantidade', 1, 'preco_unitario', 55)), 'crediario', cli_f, 0, 1, current_date + 30);
    PERFORM lr_ordem_retirar(o3, ped2);
    PERFORM ci.sair();
  END LOOP;
  PERFORM ci.entrar(vend); r := lr_fidelidade_cliente(cli_f); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'disponiveis')::int = 1, 'duas lavagens entregues dão um brinde');
  PERFORM ci.entrar(vend);
  a7 := lr_agendar(jsonb_build_object('veiculo_id', v_f, 'lavador_id', l2, 'inicio', ini + interval '5 days', 'servicos', jsonb_build_array(s1, s2)));
  a8 := lr_agendar(jsonb_build_object('veiculo_id', v_g, 'lavador_id', l1, 'inicio', ini + interval '5 days', 'servicos', jsonb_build_array(s2)));
  r := lr_agenda_chegada(a7);
  o3 := (r ->> 'ordem_id')::uuid;
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura = 'fidelidade' AND assinatura_id IS NULL FROM lr_ordem_itens WHERE ordem_id = o3 AND servico_id = s2), 'o serviço-brinde sai de graça na chegada');
  PERFORM ci.exige((SELECT cobertura IS NULL AND preco_aplicado = 55 FROM lr_ordem_itens WHERE ordem_id = o3 AND servico_id = s1), 'os outros serviços seguem cobrados');
  -- o brinde é do cliente: a chegada do outro veículo dele, com o brinde já usado, cobra normalmente
  PERFORM ci.entrar(vend);
  r := lr_agenda_chegada(a8);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura IS NULL AND preco_aplicado = 30 FROM lr_ordem_itens WHERE ordem_id = (r ->> 'ordem_id')::uuid), 'brinde já usado: a segunda ordem do cliente é cobrada');
  PERFORM ci.entrar(vend); r := lr_fidelidade_cliente(cli_f); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'disponiveis')::int = 0, 'o brinde usado na agenda não fica disponível de novo');
  -- cancelar a ordem devolve o brinde
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao(o3, 'cancelada', 'teste');
  PERFORM ci.sair();
  PERFORM ci.entrar(vend); r := lr_fidelidade_cliente(cli_f); PERFORM ci.sair();
  PERFORM ci.exige((r ->> 'disponiveis')::int = 1, 'cancelar a ordem da agenda devolve o brinde');
  -- serviço coberto não exige preço cadastrado (o cobrado exige, como testado acima)
  PERFORM ci.entrar(vend);
  PERFORM lr_ordem_situacao((SELECT ordem_id FROM lr_agendamentos WHERE id = a8), 'cancelada', 'teste');
  PERFORM ci.sair();
  INSERT INTO lr_assinaturas (tenant_id, plano_id, veiculo_id, cliente_id, servico_id, lavagens, valor, comprado_em, vence_em)
  VALUES (demo, pl, v_g, cli_f, s_sem, 2, 20, current_date, current_date + 30) RETURNING id INTO ass;
  PERFORM ci.entrar(vend);
  a9 := lr_agendar(jsonb_build_object('veiculo_id', v_g, 'lavador_id', l1, 'inicio', ini + interval '6 days', 'servicos', jsonb_build_array(s_sem)));
  r := lr_agenda_chegada(a9);
  PERFORM ci.sair();
  PERFORM ci.exige((SELECT cobertura = 'assinatura' AND preco_aplicado = 0 FROM lr_ordem_itens WHERE ordem_id = (r ->> 'ordem_id')::uuid), 'serviço coberto pelo plano entra sem exigir preço cadastrado');
  -- fidelidade desligada
  PERFORM ci.entrar(gest);
  PERFORM lr_fidelidade_salvar(false, 2, s2);
  PERFORM ci.sair();

  -- limpeza
  DELETE FROM lr_agenda_config WHERE tenant_id = demo;
  DELETE FROM lr_config WHERE tenant_id = demo;
  UPDATE empresas SET ramo_atividade = ramo_ant, cnae = cnae_ant, cnae_secundarios = cnae2_ant WHERE tenant_id = demo;
END $$;
